import type { BankQuestion } from "@/lib/bank";

/** Environment and Ecology (Environment): 1000 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"env-ecology-1","question":"The Ramsar Convention is concerned with the conservation of:","options":["Wetlands","Coral reefs only","Mountain glaciers","Deserts"],"answer":0,"explanation":"The Ramsar Convention (1971) is an intergovernmental treaty for the conservation and wise use of wetlands.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"रामसर कन्वेंशन किसके संरक्षण से संबंधित है?","optionsHi":["आर्द्रभूमि","केवल प्रवाल भित्तियाँ","पर्वतीय हिमनद","मरुस्थल"],"explanationHi":"रामसर कन्वेंशन (1971) आर्द्रभूमियों के संरक्षण और विवेकपूर्ण उपयोग के लिए एक अंतर-सरकारी संधि है।"},
  {"id":"env-ecology-2","question":"India's first national park, set up in 1936 as Hailey National Park, is now known as:","options":["Jim Corbett National Park","Rajaji National Park","Valley of Flowers National Park","Kaziranga National Park"],"answer":0,"explanation":"Hailey National Park in Uttarakhand was renamed Ramganga and then Jim Corbett National Park, after the hunter-turned-conservationist Jim Corbett.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भारत का पहला राष्ट्रीय उद्यान, जिसे 1936 में हेली राष्ट्रीय उद्यान के रूप में स्थापित किया गया था, अब किस नाम से जाना जाता है?","optionsHi":["जिम कॉर्बेट राष्ट्रीय उद्यान","राजाजी राष्ट्रीय उद्यान","फूलों की घाटी राष्ट्रीय उद्यान","काजीरंगा राष्ट्रीय उद्यान"],"explanationHi":"उत्तराखंड के हेली राष्ट्रीय उद्यान का नाम बदलकर पहले रामगंगा और फिर शिकारी से संरक्षणवादी बने जिम कॉर्बेट के नाम पर जिम कॉर्बेट राष्ट्रीय उद्यान रखा गया।"},
  {"id":"env-ecology-3","question":"Project Tiger was launched in India in:","options":["1973","1972","1986","1980"],"answer":0,"explanation":"Project Tiger began on 1 April 1973; the Wildlife (Protection) Act came a year earlier, in 1972.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"भारत में प्रोजेक्ट टाइगर कब शुरू किया गया था?","optionsHi":["1973","1972","1986","1980"],"explanationHi":"प्रोजेक्ट टाइगर 1 अप्रैल 1973 को शुरू हुआ; वन्यजीव (संरक्षण) अधिनियम इससे एक वर्ष पहले, 1972 में आया था।"},
  {"id":"env-ecology-4","question":"Kaziranga National Park is best known for the:","options":["Asiatic wild ass","Lion-tailed macaque","Hangul (Kashmir stag)","One-horned rhinoceros"],"answer":3,"explanation":"Kaziranga in Assam holds the largest population of the greater one-horned rhinoceros; it is a World Heritage Site and a tiger reserve.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"काजीरंगा राष्ट्रीय उद्यान किसके लिए सबसे अधिक प्रसिद्ध है?","optionsHi":["एशियाई जंगली गधा","शेर-पूँछ वाला मकाक","हंगुल (कश्मीर हिरण)","एक सींग वाला गैंडा"],"explanationHi":"असम का काजीरंगा बड़े एक सींग वाले गैंडे की सबसे बड़ी आबादी का घर है; यह विश्व धरोहर स्थल और बाघ अभयारण्य (टाइगर रिज़र्व) भी है।"},
  {"id":"env-ecology-5","question":"The Kyoto Protocol, adopted in 1997, deals with:","options":["Wetlands of international importance","Phasing out ozone-depleting substances","Trade in endangered wild species","Reducing greenhouse gas emissions"],"answer":3,"explanation":"Kyoto set binding emission-reduction targets for developed countries under the UNFCCC; the ozone layer is covered by the Montreal Protocol.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"1997 में अपनाया गया क्योटो प्रोटोकॉल किससे संबंधित है?","optionsHi":["अंतरराष्ट्रीय महत्व की आर्द्रभूमियाँ","ओज़ोन परत को नष्ट करने वाले पदार्थों को चरणबद्ध ढंग से समाप्त करना","लुप्तप्राय वन्य प्रजातियों का व्यापार","हरितगृह गैसों के उत्सर्जन में कमी करना"],"explanationHi":"क्योटो प्रोटोकॉल ने UNFCCC के अंतर्गत विकसित देशों के लिए उत्सर्जन में कमी के बाध्यकारी लक्ष्य तय किए; ओज़ोन परत का विषय मॉन्ट्रियल प्रोटोकॉल में आता है।"},
  {"id":"env-ecology-6","question":"The central goal of the Paris Agreement (2015) is to hold the rise in global average temperature to:","options":["Below 2.5 °C above pre-industrial levels by 2100","Below 2 °C above present levels by the year 2050 at the latest","Well below 2 °C above pre-industrial, aiming for 1.5 °C","Below 1.5 °C above 1990 levels, as a binding cap"],"answer":2,"explanation":"The Paris Agreement aims to keep warming well below 2 °C above pre-industrial levels and to pursue efforts to limit it to 1.5 °C.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"पेरिस समझौते (2015) का केंद्रीय लक्ष्य वैश्विक औसत तापमान वृद्धि को किस सीमा तक रोकना है?","optionsHi":["पूर्व-औद्योगिक स्तर से 2.5 °C से कम, 2100 तक","वर्तमान स्तर से 2 °C से कम, अधिकतम 2050 तक","पूर्व-औद्योगिक स्तर से 2 °C से काफ़ी कम, 1.5 °C का लक्ष्य रखते हुए","1.5 °C से कम, 1990 के स्तर से ऊपर, बाध्यकारी सीमा के रूप में"],"explanationHi":"पेरिस समझौते का उद्देश्य तापमान वृद्धि को पूर्व-औद्योगिक स्तर से 2 °C से काफ़ी कम रखना और इसे 1.5 °C तक सीमित करने के प्रयास करना है।"},
  {"id":"env-ecology-7","question":"Gir National Park, the only wild home of the Asiatic lion, is in:","options":["Maharashtra","Madhya Pradesh","Rajasthan","Gujarat"],"answer":3,"explanation":"The Asiatic lion survives in the wild only in the Gir forest and surrounding areas of Saurashtra, Gujarat.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"गिर राष्ट्रीय उद्यान, जो एशियाई सिंह का एकमात्र प्राकृतिक आवास है, किस राज्य में स्थित है?","optionsHi":["महाराष्ट्र","मध्य प्रदेश","राजस्थान","गुजरात"],"explanationHi":"एशियाई सिंह जंगल में केवल गुजरात के सौराष्ट्र क्षेत्र के गिर वन और उसके आसपास के क्षेत्रों में पाया जाता है।"},
  {"id":"env-ecology-8","question":"Among the following IUCN Red List categories, which indicates the highest risk of extinction in the wild?","options":["Near Threatened","Vulnerable","Critically Endangered","Endangered"],"answer":2,"explanation":"The threatened categories in rising order of risk are Vulnerable, Endangered and Critically Endangered; Near Threatened is below Vulnerable.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित IUCN रेड लिस्ट श्रेणियों में से कौन-सी जंगल में विलुप्त होने का सर्वाधिक खतरा दर्शाती है?","optionsHi":["संकट के निकट (Near Threatened)","सुभेद्य (Vulnerable)","घोर संकटग्रस्त (Critically Endangered)","संकटग्रस्त (Endangered)"],"explanationHi":"संकटग्रस्त श्रेणियाँ खतरे के बढ़ते क्रम में सुभेद्य, संकटग्रस्त और घोर संकटग्रस्त हैं; संकट के निकट श्रेणी सुभेद्य से नीचे है।"},
  {"id":"env-ecology-9","question":"CITES regulates:","options":["International trade in endangered wild fauna and flora","Emissions of greenhouse gases from industrialised nations","Cross-border movement of hazardous wastes and disposal","Use and trade of mercury and mercury-added products"],"answer":0,"explanation":"CITES (Convention on International Trade in Endangered Species of Wild Fauna and Flora) controls cross-border trade in listed species through its appendices.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"CITES किसका विनियमन करता है?","optionsHi":["लुप्तप्राय वन्य जीव-जंतुओं और वनस्पतियों का अंतरराष्ट्रीय व्यापार","औद्योगिक देशों से हरितगृह गैसों का उत्सर्जन","खतरनाक अपशिष्टों की सीमा-पार आवाजाही और निपटान","पारे और पारायुक्त उत्पादों का उपयोग तथा व्यापार"],"explanationHi":"CITES (लुप्तप्राय वन्य जीव-जंतुओं और वनस्पतियों की प्रजातियों के अंतरराष्ट्रीय व्यापार पर कन्वेंशन) अपने परिशिष्टों के माध्यम से सूचीबद्ध प्रजातियों के सीमा-पार व्यापार को नियंत्रित करता है।"},
  {"id":"env-ecology-10","question":"Silent Valley National Park, saved from a hydroelectric project after a public campaign, is in:","options":["Goa","Tamil Nadu","Karnataka","Kerala"],"answer":3,"explanation":"Silent Valley in Palakkad district, Kerala, is a tropical evergreen forest and part of the Nilgiri Biosphere Reserve.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"साइलेंट वैली राष्ट्रीय उद्यान, जिसे जन-अभियान के बाद एक पनबिजली परियोजना से बचाया गया, कहाँ स्थित है?","optionsHi":["गोवा","तमिलनाडु","कर्नाटक","केरल"],"explanationHi":"केरल के पलक्कड़ ज़िले में स्थित साइलेंट वैली एक उष्णकटिबंधीय सदाबहार वन है और नीलगिरि जैवमंडल आरक्षित क्षेत्र का हिस्सा है।"},
  {"id":"env-ecology-11","question":"Acid rain is caused mainly by:","options":["Carbon monoxide from vehicle exhaust","Sulphur dioxide and nitrogen oxides","Carbon dioxide and methane from landfills","Chlorofluorocarbons from refrigerants"],"answer":1,"explanation":"SO₂ and NOₓ from burning fossil fuels form sulphuric and nitric acids in the atmosphere, which fall as acid rain.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"अम्ल वर्षा मुख्य रूप से किसके कारण होती है?","optionsHi":["वाहनों के धुएँ से निकली कार्बन मोनोऑक्साइड","सल्फर डाइऑक्साइड और नाइट्रोजन ऑक्साइड","भूमि भराव (लैंडफिल) से निकली कार्बन डाइऑक्साइड और मीथेन","रेफ्रिजरेटरों से निकले क्लोरोफ्लोरोकार्बन"],"explanationHi":"जीवाश्म ईंधन जलने से निकली SO₂ और NOₓ वायुमंडल में सल्फ्यूरिक और नाइट्रिक अम्ल बनाती हैं, जो अम्ल वर्षा के रूप में गिरते हैं।"},
  {"id":"env-ecology-12","question":"Keoladeo National Park at Bharatpur, Rajasthan, is famous for:","options":["Indian wild ass of the salt flats","One-horned rhinos of the floodplain","Resident and migratory waterbirds","Great Indian Bustard breeding grounds"],"answer":2,"explanation":"Keoladeo, a World Heritage Site and Ramsar site, is a wetland famous for resident and migratory birds; it was once a wintering site of the Siberian crane.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"राजस्थान के भरतपुर में स्थित केवलादेव राष्ट्रीय उद्यान किसके लिए प्रसिद्ध है?","optionsHi":["नमक के मैदानों का भारतीय जंगली गधा","बाढ़ के मैदान के एक सींग वाले गैंडे","स्थानीय और प्रवासी जलपक्षी","ग्रेट इंडियन बस्टर्ड के प्रजनन स्थल"],"explanationHi":"केवलादेव विश्व धरोहर स्थल और रामसर स्थल है; यह आर्द्रभूमि स्थानीय और प्रवासी पक्षियों के लिए प्रसिद्ध है तथा कभी साइबेरियाई सारस का शीतकालीन प्रवास स्थल था।"},
  {"id":"env-ecology-13","question":"The Nicobar Islands fall within which biodiversity hotspot?","options":["Sundaland","Indo-Burma","Western Ghats and Sri Lanka","Himalaya"],"answer":0,"explanation":"India has parts of four hotspots: the Himalaya, Indo-Burma, the Western Ghats and Sri Lanka, and Sundaland, which covers the Nicobar Islands.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निकोबार द्वीप समूह किस जैव विविधता हॉटस्पॉट के अंतर्गत आते हैं?","optionsHi":["सुंडालैंड","इंडो-बर्मा","पश्चिमी घाट और श्रीलंका","हिमालय"],"explanationHi":"भारत में चार हॉटस्पॉट के भाग हैं: हिमालय, इंडो-बर्मा, पश्चिमी घाट और श्रीलंका, तथा सुंडालैंड, जिसमें निकोबार द्वीप समूह आते हैं।"},
  {"id":"env-ecology-14","question":"The Environment (Protection) Act, an umbrella law passed after the Bhopal gas tragedy, was enacted in:","options":["1986","1980","1972","1974"],"answer":0,"explanation":"The Environment (Protection) Act came in 1986; the Wildlife (Protection) Act dates from 1972, the Water Act from 1974 and the Forest (Conservation) Act from 1980.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भोपाल गैस त्रासदी के बाद पारित छत्र (अम्ब्रेला) कानून, पर्यावरण (संरक्षण) अधिनियम, किस वर्ष लागू किया गया?","optionsHi":["1986","1980","1972","1974"],"explanationHi":"पर्यावरण (संरक्षण) अधिनियम 1986 में आया; वन्यजीव (संरक्षण) अधिनियम 1972 का, जल अधिनियम 1974 का और वन (संरक्षण) अधिनियम 1980 का है।"},
  {"id":"env-ecology-15","question":"The concept of biosphere reserves comes from UNESCO's:","options":["World Heritage Convention of 1972","Ramsar Convention on Wetlands","Convention on Biological Diversity","Man and the Biosphere Programme"],"answer":3,"explanation":"Biosphere reserves were launched under UNESCO's Man and the Biosphere Programme, begun in 1971.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"जैवमंडल आरक्षित क्षेत्रों की अवधारणा यूनेस्को के किस कार्यक्रम/सम्मेलन से आई है?","optionsHi":["1972 का विश्व धरोहर कन्वेंशन","आर्द्रभूमि पर रामसर कन्वेंशन","जैव विविधता पर कन्वेंशन","मानव और जैवमंडल कार्यक्रम (Man and the Biosphere Programme)"],"explanationHi":"जैवमंडल आरक्षित क्षेत्र यूनेस्को के मानव और जैवमंडल कार्यक्रम के अंतर्गत शुरू किए गए, जिसका आरंभ 1971 में हुआ था।"},
  {"id":"env-ecology-16","question":"In a biosphere reserve, the zone where research, education and limited human activity are allowed but settlements are not is the:","options":["Corridor zone","Buffer zone","Core zone","Transition zone"],"answer":1,"explanation":"The core zone is strictly protected; the surrounding buffer zone allows research, education and limited activity; the outer transition zone has settlements and farming.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"जैवमंडल आरक्षित क्षेत्र में वह क्षेत्र कौन-सा है जहाँ अनुसंधान, शिक्षा और सीमित मानव गतिविधि की अनुमति होती है, परंतु बस्तियाँ नहीं होतीं?","optionsHi":["गलियारा क्षेत्र","बफर क्षेत्र","कोर क्षेत्र","संक्रमण क्षेत्र"],"explanationHi":"कोर क्षेत्र पूर्णतः संरक्षित होता है; उसके चारों ओर का बफर क्षेत्र अनुसंधान, शिक्षा और सीमित गतिविधि की अनुमति देता है; बाहरी संक्रमण क्षेत्र में बस्तियाँ और खेती होती है।"},
  {"id":"env-ecology-17","question":"Dachigam National Park in Jammu and Kashmir is known for the:","options":["Hangul (Kashmir stag)","Sangai (brow-antlered deer)","Markhor (screw-horned goat)","Nilgiri tahr"],"answer":0,"explanation":"Dachigam, near Srinagar, is the last stronghold of the hangul, the Kashmir red deer; the sangai lives in Manipur's Keibul Lamjao.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जम्मू और कश्मीर का दाचीगाम राष्ट्रीय उद्यान किसके लिए जाना जाता है?","optionsHi":["हंगुल (कश्मीर हिरण)","संगाई (भौंह-सींग वाला हिरण)","मारखोर (पेचदार सींग वाली बकरी)","नीलगिरि तहर"],"explanationHi":"श्रीनगर के पास स्थित दाचीगाम कश्मीर लाल हिरण, यानी हंगुल, का अंतिम गढ़ है; संगाई मणिपुर के केइबुल लामजाओ में रहता है।"},
  {"id":"env-ecology-18","question":"Which of these tiger reserves is in Kerala?","options":["Nagarhole","Bandipur","Mudumalai","Periyar"],"answer":3,"explanation":"Periyar is in Kerala; Mudumalai is in Tamil Nadu, and Bandipur and Nagarhole are in Karnataka. All four lie in the Nilgiri–Western Ghats landscape.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कौन-सा बाघ अभयारण्य केरल में है?","optionsHi":["नागरहोले","बांदीपुर","मुदुमलाई","पेरियार"],"explanationHi":"पेरियार केरल में है; मुदुमलाई तमिलनाडु में है, और बांदीपुर तथा नागरहोले कर्नाटक में हैं। चारों नीलगिरि–पश्चिमी घाट भू-दृश्य में स्थित हैं।"},
  {"id":"env-ecology-19","question":"The Kigali Amendment (2016) to the Montreal Protocol aims to phase down:","options":["Mercury","Chlorofluorocarbons (CFCs)","Carbon dioxide","Hydrofluorocarbons (HFCs)"],"answer":3,"explanation":"HFCs do not harm the ozone layer but are powerful greenhouse gases; the Kigali Amendment set a schedule to cut them. CFCs were already being phased out under the original protocol.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मॉन्ट्रियल प्रोटोकॉल का किगाली संशोधन (2016) किसे चरणबद्ध ढंग से घटाने का लक्ष्य रखता है?","optionsHi":["पारा","क्लोरोफ्लोरोकार्बन (CFCs)","कार्बन डाइऑक्साइड","हाइड्रोफ्लोरोकार्बन (HFCs)"],"explanationHi":"HFCs ओज़ोन परत को हानि नहीं पहुँचाते, पर शक्तिशाली हरितगृह गैसें हैं; किगाली संशोधन ने इन्हें घटाने की समय-सारणी तय की। CFCs को मूल प्रोटोकॉल के अंतर्गत पहले ही चरणबद्ध ढंग से हटाया जा रहा था।"},
  {"id":"env-ecology-20","question":"The Nagoya Protocol under the Convention on Biological Diversity deals with:","options":["Conservation of migratory species and their habitats","Safe transboundary movement of living modified organisms","Prior informed consent for trade in hazardous chemicals","Access to genetic resources and benefit-sharing"],"answer":3,"explanation":"The Nagoya Protocol (2010) covers access and benefit-sharing; biosafety of living modified organisms is the subject of the Cartagena Protocol.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जैव विविधता पर कन्वेंशन के अंतर्गत नागोया प्रोटोकॉल किससे संबंधित है?","optionsHi":["प्रवासी प्रजातियों और उनके आवासों का संरक्षण","जीवित रूपांतरित जीवों की सुरक्षित सीमा-पार आवाजाही","खतरनाक रसायनों के व्यापार के लिए पूर्व सूचित सहमति","आनुवंशिक संसाधनों तक पहुँच और लाभों का बँटवारा"],"explanationHi":"नागोया प्रोटोकॉल (2010) पहुँच और लाभ-बँटवारे से संबंधित है; जीवित रूपांतरित जीवों की जैव सुरक्षा कार्टाजेना प्रोटोकॉल का विषय है।"},
  {"id":"env-ecology-21","question":"Persistent organic pollutants (POPs) are the subject of the:","options":["Stockholm Convention","Ramsar Convention","Rotterdam Convention","Minamata Convention"],"answer":0,"explanation":"The Stockholm Convention (2001) aims to eliminate or restrict POPs such as DDT and PCBs; Rotterdam covers prior informed consent for hazardous chemicals in trade and Minamata covers mercury.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"सतत कार्बनिक प्रदूषक (POPs) किसका विषय हैं?","optionsHi":["स्टॉकहोम कन्वेंशन","रामसर कन्वेंशन","रॉटरडैम कन्वेंशन","मिनामाता कन्वेंशन"],"explanationHi":"स्टॉकहोम कन्वेंशन (2001) का उद्देश्य DDT और PCBs जैसे POPs को समाप्त या सीमित करना है; रॉटरडैम व्यापार में खतरनाक रसायनों के लिए पूर्व सूचित सहमति से और मिनामाता पारे से संबंधित है।"},
  {"id":"env-ecology-22","question":"The Bonn Convention (CMS) aims to conserve:","options":["World cultural heritage","Migratory species of wild animals","The ozone layer","Wetlands of international importance"],"answer":1,"explanation":"The Convention on the Conservation of Migratory Species of Wild Animals was signed at Bonn in 1979.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बॉन कन्वेंशन (CMS) का उद्देश्य किसका संरक्षण करना है?","optionsHi":["विश्व सांस्कृतिक धरोहर","वन्य जीवों की प्रवासी प्रजातियाँ","ओज़ोन परत","अंतरराष्ट्रीय महत्व की आर्द्रभूमियाँ"],"explanationHi":"वन्य जीवों की प्रवासी प्रजातियों के संरक्षण पर कन्वेंशन पर 1979 में बॉन में हस्ताक्षर किए गए थे।"},
  {"id":"env-ecology-23","question":"When a lake receives large amounts of nitrates and phosphates from fertiliser run-off, the usual chain of events is:","options":["Fall in algae as nitrates poison them, so oxygen rises","Algal bloom, then oxygen depletion and fish kills","Rise in water clarity and a boom in fish numbers","Fall in BOD as plants absorb the extra nutrients"],"answer":1,"explanation":"This is eutrophication: nutrients feed an algal bloom, and decomposition of the dead algae uses up dissolved oxygen, killing fish.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"जब किसी झील में उर्वरक के बहाव से बड़ी मात्रा में नाइट्रेट और फॉस्फेट पहुँचते हैं, तो सामान्यतः घटनाओं का क्रम क्या होता है?","optionsHi":["शैवाल घटते हैं क्योंकि नाइट्रेट उन्हें विषाक्त कर देते हैं, इसलिए ऑक्सीजन बढ़ती है","शैवाल प्रस्फुटन, फिर ऑक्सीजन की कमी और मछलियों की मृत्यु","जल की स्वच्छता बढ़ती है और मछलियों की संख्या में वृद्धि होती है","BOD घटता है क्योंकि पौधे अतिरिक्त पोषक तत्व अवशोषित कर लेते हैं"],"explanationHi":"यह सुपोषण (यूट्रोफिकेशन) है: पोषक तत्व शैवाल प्रस्फुटन को बढ़ावा देते हैं, और मृत शैवालों के अपघटन में घुली ऑक्सीजन समाप्त हो जाती है, जिससे मछलियाँ मर जाती हैं।"},
  {"id":"env-ecology-24","question":"The IUCN Red List status of the Great Indian Bustard, the state bird of Rajasthan, is:","options":["Critically Endangered","Vulnerable","Endangered","Near Threatened"],"answer":0,"explanation":"The Great Indian Bustard has been listed as Critically Endangered since 2011; collisions with power lines in the Thar are a major threat.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"राजस्थान के राज्य पक्षी ग्रेट इंडियन बस्टर्ड की IUCN रेड लिस्ट स्थिति क्या है?","optionsHi":["घोर संकटग्रस्त","सुभेद्य","संकटग्रस्त","संकट के निकट"],"explanationHi":"ग्रेट इंडियन बस्टर्ड 2011 से घोर संकटग्रस्त श्रेणी में सूचीबद्ध है; थार में बिजली की तारों से टकराव इसके लिए एक बड़ा खतरा है।"},
  {"id":"env-ecology-25","question":"Match the international agreement with its subject. A. Basel Convention  B. Rotterdam Convention  C. Minamata Convention  D. Cartagena Protocol; 1. Prior informed consent for trade in hazardous chemicals  2. Transboundary movement of hazardous wastes  3. Biosafety of living modified organisms  4. Mercury","options":["A-4, B-1, C-2, D-3","A-3, B-1, C-4, D-2","A-2, B-1, C-4, D-3","A-2, B-3, C-4, D-1"],"answer":2,"explanation":"Basel controls movement of hazardous wastes, Rotterdam sets prior informed consent for hazardous chemicals and pesticides, Minamata limits mercury, and the Cartagena Protocol under the CBD covers biosafety of LMOs.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अंतरराष्ट्रीय समझौते का उसके विषय से मिलान कीजिए। A. बेसल कन्वेंशन  B. रॉटरडैम कन्वेंशन  C. मिनामाता कन्वेंशन  D. कार्टाजेना प्रोटोकॉल; 1. खतरनाक रसायनों के व्यापार के लिए पूर्व सूचित सहमति  2. खतरनाक अपशिष्टों की सीमा-पार आवाजाही  3. जीवित रूपांतरित जीवों की जैव सुरक्षा  4. पारा","optionsHi":["A-4, B-1, C-2, D-3","A-3, B-1, C-4, D-2","A-2, B-1, C-4, D-3","A-2, B-3, C-4, D-1"],"explanationHi":"बेसल खतरनाक अपशिष्टों की आवाजाही को नियंत्रित करता है, रॉटरडैम खतरनाक रसायनों और कीटनाशकों के लिए पूर्व सूचित सहमति तय करता है, मिनामाता पारे को सीमित करता है, और CBD के अंतर्गत कार्टाजेना प्रोटोकॉल जीवित रूपांतरित जीवों की जैव सुरक्षा से संबंधित है।"},
  {"id":"env-ecology-26","question":"How many of the following statements about the Ramsar Convention are correct? I. It was signed in 1971 at Ramsar in Iran. II. Chilika Lake and Keoladeo were India's first Ramsar sites, in 1981. III. The Montreux Record lists Ramsar sites where ecological change is occurring or likely. IV. Loktak Lake in Manipur is on the Montreux Record.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Keoladeo and Loktak are India's sites on the Montreux Record; Chilika was placed on it in 1993 and removed in 2002 after restoration.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"रामसर कन्वेंशन के बारे में निम्नलिखित में से कितने कथन सही हैं? I. इस पर 1971 में ईरान के रामसर में हस्ताक्षर हुए थे। II. चिल्का झील और केवलादेव 1981 में भारत के पहले रामसर स्थल थे। III. मॉन्ट्रो रिकॉर्ड में उन रामसर स्थलों को सूचीबद्ध किया जाता है जहाँ पारिस्थितिक परिवर्तन हो रहा है या होने की संभावना है। IV. मणिपुर की लोकटक झील मॉन्ट्रो रिकॉर्ड में है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चारों सही हैं। केवलादेव और लोकटक मॉन्ट्रो रिकॉर्ड में भारत के स्थल हैं; चिल्का को 1993 में इसमें रखा गया था और पुनर्स्थापन के बाद 2002 में हटा दिया गया।"},
  {"id":"env-ecology-27","question":"Which of these is NOT a tiger reserve in Madhya Pradesh?","options":["Sanjay-Dubri","Bandhavgarh","Veerangana Durgavati","Tadoba-Andhari"],"answer":3,"explanation":"Sanjay-Dubri, Bandhavgarh and Veerangana Durgavati (notified 2023) are tiger reserves in Madhya Pradesh; Tadoba-Andhari is in Chandrapur district of Maharashtra.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सा मध्य प्रदेश में बाघ अभयारण्य नहीं है?","optionsHi":["संजय-दुबरी","बांधवगढ़","वीरांगना दुर्गावती","ताडोबा-अंधारी"],"explanationHi":"संजय-दुबरी, बांधवगढ़ और वीरांगना दुर्गावती (2023 में अधिसूचित) मध्य प्रदेश के बाघ अभयारण्य हैं; ताडोबा-अंधारी महाराष्ट्र के चंद्रपुर ज़िले में है।"},
  {"id":"env-ecology-28","question":"Match the national park with its state. A. Namdapha  B. Valley of Flowers  C. Bandipur  D. Simlipal; 1. Odisha  2. Karnataka  3. Arunachal Pradesh  4. Uttarakhand","options":["A-2, B-4, C-3, D-1","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"Namdapha is in Arunachal Pradesh, the Valley of Flowers in Uttarakhand, Bandipur in Karnataka and Simlipal in Odisha.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"राष्ट्रीय उद्यान का उसके राज्य से मिलान कीजिए। A. नामदफा  B. फूलों की घाटी  C. बांदीपुर  D. सिमलीपाल; 1. ओडिशा  2. कर्नाटक  3. अरुणाचल प्रदेश  4. उत्तराखंड","optionsHi":["A-2, B-4, C-3, D-1","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"explanationHi":"नामदफा अरुणाचल प्रदेश में, फूलों की घाटी उत्तराखंड में, बांदीपुर कर्नाटक में और सिमलीपाल ओडिशा में है।"},
  {"id":"env-ecology-29","question":"How many of the following statements are correct? I. National parks and wildlife sanctuaries are declared under the Wildlife (Protection) Act, 1972. II. Biosphere reserves are notified under the Wildlife (Protection) Act, 1972. III. Grazing of livestock may be regulated and permitted in a national park but is not allowed in a sanctuary. IV. Conservation reserves and community reserves were added by an amendment to the Wildlife (Protection) Act in 2006.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Biosphere reserves have no status under the 1972 Act (II); grazing may be permitted in a sanctuary but not in a national park (III reversed); and conservation and community reserves came with the 2002 amendment, not 2006 (IV).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. राष्ट्रीय उद्यान और वन्यजीव अभयारण्य वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत घोषित किए जाते हैं। II. जैवमंडल आरक्षित क्षेत्र वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत अधिसूचित किए जाते हैं। III. राष्ट्रीय उद्यान में पशुओं की चराई को नियंत्रित और अनुमत किया जा सकता है, परंतु अभयारण्य में नहीं। IV. संरक्षण रिज़र्व और सामुदायिक रिज़र्व वन्यजीव (संरक्षण) अधिनियम में 2006 के संशोधन द्वारा जोड़े गए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। जैवमंडल आरक्षित क्षेत्रों की 1972 के अधिनियम में कोई वैधानिक स्थिति नहीं है (II); चराई अभयारण्य में अनुमत हो सकती है, राष्ट्रीय उद्यान में नहीं (III उलटा है); और संरक्षण तथा सामुदायिक रिज़र्व 2002 के संशोधन से आए, 2006 से नहीं (IV)।"},
  {"id":"env-ecology-30","question":"How many of the following statements are correct? I. The UNFCCC was opened for signature at the Rio Earth Summit in 1992. II. The Kyoto Protocol set binding emission targets for developing countries such as India. III. Under the Paris Agreement every party must prepare and communicate Nationally Determined Contributions. IV. The Paris Agreement was adopted at COP-21 in Copenhagen.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. Kyoto's binding targets applied only to developed (Annex I) countries (II wrong), and COP-21 was held in Paris; Copenhagen hosted COP-15 in 2009 (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. UNFCCC को 1992 के रियो पृथ्वी शिखर सम्मेलन में हस्ताक्षर के लिए खोला गया था। II. क्योटो प्रोटोकॉल ने भारत जैसे विकासशील देशों के लिए बाध्यकारी उत्सर्जन लक्ष्य तय किए। III. पेरिस समझौते के अंतर्गत प्रत्येक पक्षकार को राष्ट्रीय स्तर पर निर्धारित योगदान (NDC) तैयार कर प्रस्तुत करना होता है। IV. पेरिस समझौता कोपेनहेगन में COP-21 में अपनाया गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। क्योटो के बाध्यकारी लक्ष्य केवल विकसित (अनुलग्नक I) देशों पर लागू थे (II गलत), और COP-21 पेरिस में हुआ था; कोपेनहेगन ने 2009 में COP-15 की मेज़बानी की थी (IV गलत)।"},
  {"id":"env-ecology-31","question":"Arrange in chronological order: 1. Montreal Protocol  2. Kyoto Protocol  3. Stockholm Conference on the Human Environment  4. Rio Earth Summit","options":["4-1-3-2","2-4-3-1","3-1-4-2","4-3-2-1"],"answer":2,"explanation":"Stockholm Conference 1972, Montreal Protocol 1987, Rio Earth Summit 1992, Kyoto Protocol 1997.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. मॉन्ट्रियल प्रोटोकॉल  2. क्योटो प्रोटोकॉल  3. मानव पर्यावरण पर स्टॉकहोम सम्मेलन  4. रियो पृथ्वी शिखर सम्मेलन","optionsHi":["4-1-3-2","2-4-3-1","3-1-4-2","4-3-2-1"],"explanationHi":"स्टॉकहोम सम्मेलन 1972, मॉन्ट्रियल प्रोटोकॉल 1987, रियो पृथ्वी शिखर सम्मेलन 1992, क्योटो प्रोटोकॉल 1997।"},
  {"id":"env-ecology-32","question":"Assertion (A): The ozone hole is most pronounced over Antarctica in the southern spring (September–October). Reason (R): Polar stratospheric clouds formed in the extreme winter cold provide surfaces on which reactions release active chlorine.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In the dark polar winter, polar stratospheric clouds convert stable chlorine compounds into reactive forms; when sunlight returns in spring, that chlorine rapidly destroys ozone.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): ओज़ोन छिद्र अंटार्कटिका के ऊपर दक्षिणी वसंत (सितंबर–अक्टूबर) में सबसे अधिक स्पष्ट होता है। कारण (R): अत्यधिक शीतकालीन ठंड में बने ध्रुवीय समतापमंडलीय बादल ऐसी सतहें प्रदान करते हैं जिन पर अभिक्रियाओं से सक्रिय क्लोरीन मुक्त होती है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"अंधकारमय ध्रुवीय शीत ऋतु में ध्रुवीय समतापमंडलीय बादल स्थिर क्लोरीन यौगिकों को सक्रिय रूपों में बदल देते हैं; वसंत में सूर्य का प्रकाश लौटने पर वह क्लोरीन तेज़ी से ओज़ोन को नष्ट करती है।"},
  {"id":"env-ecology-33","question":"Match the disease with the pollutant that causes it. A. Minamata disease  B. Itai-itai disease  C. Blue baby syndrome  D. Blackfoot disease; 1. Arsenic  2. Nitrate  3. Mercury  4. Cadmium","options":["A-4, B-3, C-2, D-1","A-1, B-4, C-2, D-3","A-3, B-1, C-2, D-4","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"Minamata disease comes from mercury, itai-itai from cadmium, blue baby syndrome (methaemoglobinaemia) from nitrate in drinking water, and blackfoot disease from arsenic.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"रोग का उसके कारक प्रदूषक से मिलान कीजिए। A. मिनामाता रोग  B. इटाई-इटाई रोग  C. ब्लू बेबी सिंड्रोम  D. ब्लैकफुट रोग; 1. आर्सेनिक  2. नाइट्रेट  3. पारा  4. कैडमियम","optionsHi":["A-4, B-3, C-2, D-1","A-1, B-4, C-2, D-3","A-3, B-1, C-2, D-4","A-3, B-4, C-2, D-1"],"explanationHi":"मिनामाता रोग पारे से, इटाई-इटाई कैडमियम से, ब्लू बेबी सिंड्रोम (मेथेमोग्लोबिनेमिया) पेयजल में नाइट्रेट से और ब्लैकफुट रोग आर्सेनिक से होता है।"},
  {"id":"env-ecology-34","question":"Arrange these IUCN categories in increasing order of extinction risk: 1. Vulnerable  2. Near Threatened  3. Critically Endangered  4. Endangered","options":["3-2-1-4","2-1-4-3","3-1-2-4","4-1-2-3"],"answer":1,"explanation":"Near Threatened is below the threatened categories; then come Vulnerable, Endangered and Critically Endangered, followed only by Extinct in the Wild and Extinct.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"IUCN की इन श्रेणियों को विलुप्त होने के बढ़ते खतरे के क्रम में व्यवस्थित कीजिए: 1. सुभेद्य (Vulnerable)  2. संकट के निकट (Near Threatened)  3. घोर संकटग्रस्त (Critically Endangered)  4. संकटग्रस्त (Endangered)","optionsHi":["3-2-1-4","2-1-4-3","3-1-2-4","4-1-2-3"],"explanationHi":"संकट के निकट श्रेणी संकटग्रस्त श्रेणियों से नीचे है; उसके बाद सुभेद्य, संकटग्रस्त और घोर संकटग्रस्त आते हैं, और उनके बाद केवल जंगल में विलुप्त तथा विलुप्त श्रेणियाँ आती हैं।"},
  {"id":"env-ecology-35","question":"How many of the following statements about biodiversity hotspots are correct? I. The concept was proposed by E. O. Wilson. II. A hotspot must have at least 1,500 endemic species of vascular plants. III. A hotspot must have lost at least 70% of its original habitat. IV. The Eastern Ghats are recognised as a separate hotspot.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are the two criteria and are correct. The concept was proposed by Norman Myers in 1988 (I wrong), and the Eastern Ghats are not a hotspot (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैव विविधता हॉटस्पॉट के बारे में निम्नलिखित में से कितने कथन सही हैं? I. यह अवधारणा ई. ओ. विल्सन ने प्रस्तावित की थी। II. हॉटस्पॉट में संवहनी पादपों की कम से कम 1,500 स्थानिक प्रजातियाँ होनी चाहिए। III. हॉटस्पॉट अपने मूल आवास का कम से कम 70% खो चुका होना चाहिए। IV. पूर्वी घाट एक पृथक हॉटस्पॉट के रूप में मान्यता प्राप्त हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III दो मानदंड हैं और सही हैं। यह अवधारणा 1988 में नॉर्मन मायर्स ने प्रस्तावित की थी (I गलत), और पूर्वी घाट हॉटस्पॉट नहीं हैं (IV गलत)।"},
  {"id":"env-ecology-36","question":"Which pair of animal and protected area is NOT correctly matched?","options":["Indian wild ass — Little Rann of Kutch, Gujarat","Lion-tailed macaque — Desert National Park","Sangai — Keibul Lamjao, Manipur","Nilgiri tahr — Eravikulam, Kerala"],"answer":1,"explanation":"The lion-tailed macaque lives in the rainforests of the Western Ghats (e.g., Silent Valley); Desert National Park in Rajasthan is known for the Great Indian Bustard.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पशु और संरक्षित क्षेत्र की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["भारतीय जंगली गधा — कच्छ का छोटा रण, गुजरात","शेर-पूँछ वाला मकाक — डेज़र्ट नेशनल पार्क","संगाई — केइबुल लामजाओ, मणिपुर","नीलगिरि तहर — इराविकुलम, केरल"],"explanationHi":"शेर-पूँछ वाला मकाक पश्चिमी घाट के वर्षावनों (जैसे साइलेंट वैली) में रहता है; राजस्थान का डेज़र्ट नेशनल पार्क ग्रेट इंडियन बस्टर्ड के लिए जाना जाता है।"},
  {"id":"env-ecology-37","question":"Which of these Ramsar sites is NOT in Odisha?","options":["Hirakud reservoir","Bhitarkanika mangroves","Sambhar Lake","Chilika Lake"],"answer":2,"explanation":"Chilika, Bhitarkanika and Hirakud are Ramsar sites in Odisha; Sambhar, India's largest inland salt lake, is in Rajasthan.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सा रामसर स्थल ओडिशा में नहीं है?","optionsHi":["हीराकुड जलाशय","भितरकनिका मैंग्रोव","सांभर झील","चिल्का झील"],"explanationHi":"चिल्का, भितरकनिका और हीराकुड ओडिशा के रामसर स्थल हैं; भारत की सबसे बड़ी अंतर्देशीय खारे पानी की झील सांभर राजस्थान में है।"},
  {"id":"env-ecology-38","question":"How many of the following statements about air pollution are correct? I. PM2.5 particles can penetrate deep into the lungs. II. Carbon dioxide is the main cause of stratospheric ozone depletion. III. Ground-level ozone is a primary pollutant emitted directly by vehicles. IV. Fly ash comes mainly from hydroelectric power stations.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Ozone depletion is caused chiefly by CFCs and other halogen compounds (II wrong); ground-level ozone is a secondary pollutant formed from NOₓ and hydrocarbons in sunlight (III wrong); fly ash comes from coal-fired thermal plants (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वायु प्रदूषण के बारे में निम्नलिखित में से कितने कथन सही हैं? I. PM2.5 कण फेफड़ों में गहराई तक पहुँच सकते हैं। II. कार्बन डाइऑक्साइड समतापमंडलीय ओज़ोन क्षरण का मुख्य कारण है। III. भू-स्तरीय ओज़ोन एक प्राथमिक प्रदूषक है जो वाहनों से सीधे उत्सर्जित होती है। IV. फ्लाई ऐश मुख्यतः पनबिजली केंद्रों से आती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। ओज़ोन क्षरण मुख्यतः CFCs और अन्य हैलोजन यौगिकों के कारण होता है (II गलत); भू-स्तरीय ओज़ोन एक द्वितीयक प्रदूषक है जो सूर्य के प्रकाश में NOₓ और हाइड्रोकार्बन से बनती है (III गलत); फ्लाई ऐश कोयला-चालित ताप विद्युत संयंत्रों से आती है (IV गलत)।"},
  {"id":"env-ecology-39","question":"Match the tiger reserve with its state. A. Dudhwa  B. Valmiki  C. Manas  D. Achanakmar; 1. Bihar  2. Uttar Pradesh  3. Chhattisgarh  4. Assam","options":["A-3, B-1, C-4, D-2","A-2, B-3, C-4, D-1","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"answer":2,"explanation":"Dudhwa is in Uttar Pradesh, Valmiki in Bihar, Manas in Assam and Achanakmar in Chhattisgarh.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"बाघ अभयारण्य का उसके राज्य से मिलान कीजिए। A. दुधवा  B. वाल्मीकि  C. मानस  D. अचानकमार; 1. बिहार  2. उत्तर प्रदेश  3. छत्तीसगढ़  4. असम","optionsHi":["A-3, B-1, C-4, D-2","A-2, B-3, C-4, D-1","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"explanationHi":"दुधवा उत्तर प्रदेश में, वाल्मीकि बिहार में, मानस असम में और अचानकमार छत्तीसगढ़ में है।"},
  {"id":"env-ecology-40","question":"Which of the following is at the same time a UNESCO World Heritage Site, a tiger reserve and a biosphere reserve?","options":["Sundarbans","Keoladeo","Jim Corbett","Nanda Devi"],"answer":0,"explanation":"The Sundarbans is all three. Nanda Devi is a World Heritage Site and biosphere reserve but not a tiger reserve; Keoladeo is a World Heritage Site only; Corbett is a tiger reserve but not a World Heritage Site.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन एक साथ यूनेस्को विश्व धरोहर स्थल, बाघ अभयारण्य और जैवमंडल आरक्षित क्षेत्र है?","optionsHi":["सुंदरबन","केवलादेव","जिम कॉर्बेट","नंदा देवी"],"explanationHi":"सुंदरबन तीनों है। नंदा देवी विश्व धरोहर स्थल और जैवमंडल आरक्षित क्षेत्र है, पर बाघ अभयारण्य नहीं; केवलादेव केवल विश्व धरोहर स्थल है; कॉर्बेट बाघ अभयारण्य है, पर विश्व धरोहर स्थल नहीं।"},
  {"id":"env-ecology-41","question":"Project Elephant was launched by the Government of India in:","options":["1973","1992","2006","1985"],"answer":1,"explanation":"Project Elephant began in 1992 to protect elephants, their habitats and corridors. Project Tiger dates from 1973.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भारत सरकार द्वारा प्रोजेक्ट एलिफेंट कब शुरू किया गया था?","optionsHi":["1973","1992","2006","1985"],"explanationHi":"प्रोजेक्ट एलिफेंट 1992 में हाथियों, उनके आवासों और गलियारों की रक्षा के लिए शुरू हुआ। प्रोजेक्ट टाइगर 1973 का है।"},
  {"id":"env-ecology-42","question":"World Environment Day is observed every year on:","options":["22 April","22 March","5 June","16 September"],"answer":2,"explanation":"World Environment Day, led by UNEP, falls on 5 June. 22 April is Earth Day, 22 March World Water Day and 16 September World Ozone Day.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"विश्व पर्यावरण दिवस प्रतिवर्ष किस दिन मनाया जाता है?","optionsHi":["22 अप्रैल","22 मार्च","5 जून","16 सितंबर"],"explanationHi":"UNEP के नेतृत्व में मनाया जाने वाला विश्व पर्यावरण दिवस 5 जून को पड़ता है। 22 अप्रैल पृथ्वी दिवस, 22 मार्च विश्व जल दिवस और 16 सितंबर विश्व ओज़ोन दिवस है।"},
  {"id":"env-ecology-43","question":"Which greenhouse gas released by human activities contributes the most to global warming?","options":["Carbon dioxide","Methane","Nitrous oxide","Water vapour from aircraft"],"answer":0,"explanation":"Carbon dioxide from burning fossil fuels and clearing forests is the largest human contribution to warming. Methane is more potent per molecule but is emitted in much smaller amounts.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"मानवीय गतिविधियों से उत्सर्जित कौन-सी हरितगृह गैस वैश्विक तापन में सबसे अधिक योगदान देती है?","optionsHi":["कार्बन डाइऑक्साइड","मीथेन","नाइट्रस ऑक्साइड","विमानों से निकली जलवाष्प"],"explanationHi":"जीवाश्म ईंधन जलाने और वनों की कटाई से निकली कार्बन डाइऑक्साइड तापन में मानवीय योगदान का सबसे बड़ा हिस्सा है। मीथेन प्रति अणु अधिक प्रभावशाली है, परंतु इसका उत्सर्जन बहुत कम मात्रा में होता है।"},
  {"id":"env-ecology-44","question":"Which of these biodiversity hotspots covers part of India?","options":["Madagascar and the Indian Ocean Islands","Caribbean Islands","Atlantic Forest","Western Ghats and Sri Lanka"],"answer":3,"explanation":"India has parts of four hotspots: the Himalaya, Indo-Burma, the Western Ghats and Sri Lanka, and Sundaland (Nicobar Islands). The others are outside Asia.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से कौन-सा जैव विविधता हॉटस्पॉट भारत के एक भाग को समाहित करता है?","optionsHi":["मेडागास्कर और हिंद महासागर के द्वीप","कैरेबियाई द्वीप","अटलांटिक वन","पश्चिमी घाट और श्रीलंका"],"explanationHi":"भारत में चार हॉटस्पॉट के भाग हैं: हिमालय, इंडो-बर्मा, पश्चिमी घाट और श्रीलंका, तथा सुंडालैंड (निकोबार द्वीप समूह)। शेष हॉटस्पॉट एशिया के बाहर हैं।"},
  {"id":"env-ecology-45","question":"The ozone layer that shields the Earth from ultraviolet radiation lies in the:","options":["Troposphere","Stratosphere","Mesosphere","Thermosphere"],"answer":1,"explanation":"Most atmospheric ozone sits in the stratosphere at about 15–35 km, where it absorbs harmful UV-B radiation. Ozone near the ground is a pollutant.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"पृथ्वी को पराबैंगनी विकिरण से बचाने वाली ओज़ोन परत किसमें स्थित है?","optionsHi":["क्षोभमंडल","समतापमंडल","मध्यमंडल","तापमंडल"],"explanationHi":"वायुमंडलीय ओज़ोन का अधिकांश भाग समतापमंडल में लगभग 15–35 km की ऊँचाई पर स्थित है, जहाँ वह हानिकारक UV-B विकिरण को अवशोषित करती है। धरातल के निकट की ओज़ोन एक प्रदूषक है।"},
  {"id":"env-ecology-46","question":"The Red Data Book, which lists threatened species, is maintained by:","options":["UNEP","WWF","IUCN","UNESCO"],"answer":2,"explanation":"The International Union for Conservation of Nature (IUCN) compiles the Red List / Red Data Book of species at risk of extinction.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"संकटग्रस्त प्रजातियों की सूची वाली रेड डेटा बुक का रखरखाव कौन करता है?","optionsHi":["UNEP","WWF","IUCN","UNESCO"],"explanationHi":"अंतरराष्ट्रीय प्रकृति संरक्षण संघ (IUCN) विलुप्ति के खतरे वाली प्रजातियों की रेड लिस्ट / रेड डेटा बुक तैयार करता है।"},
  {"id":"env-ecology-47","question":"A species found naturally only in one particular region and nowhere else is called:","options":["Endemic","Exotic","Keystone","Invasive"],"answer":0,"explanation":"Endemic species are restricted to one area, like the lion-tailed macaque of the Western Ghats. Exotic species are introduced from elsewhere.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"वह प्रजाति जो प्राकृतिक रूप से केवल किसी एक विशेष क्षेत्र में पाई जाती है और कहीं और नहीं, क्या कहलाती है?","optionsHi":["स्थानिक (एंडेमिक)","विदेशी (एक्सोटिक)","कीस्टोन","आक्रामक"],"explanationHi":"स्थानिक प्रजातियाँ किसी एक क्षेत्र तक सीमित होती हैं, जैसे पश्चिमी घाट का शेर-पूँछ वाला मकाक। विदेशी प्रजातियाँ कहीं और से लाई गई होती हैं।"},
  {"id":"env-ecology-48","question":"The transition zone between two ecosystems, such as a forest and a grassland, which often has more species than either, is called an:","options":["Ecological niche","Ecotone","Ecological pyramid","Ecological footprint"],"answer":1,"explanation":"An ecotone is the boundary zone where two communities meet; the higher variety of species there is called the edge effect. A niche is the role of a species.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"दो पारिस्थितिकी तंत्रों, जैसे वन और घास के मैदान, के बीच का संक्रमण क्षेत्र, जिसमें प्रायः दोनों से अधिक प्रजातियाँ होती हैं, क्या कहलाता है?","optionsHi":["पारिस्थितिक निकेत","पारिस्थितिक संक्रमण क्षेत्र (इकोटोन)","पारिस्थितिक पिरामिड","पारिस्थितिक पदचिह्न"],"explanationHi":"इकोटोन वह सीमा क्षेत्र है जहाँ दो समुदाय मिलते हैं; वहाँ प्रजातियों की अधिक विविधता को कोर/किनारा प्रभाव (एज इफेक्ट) कहते हैं। निकेत किसी प्रजाति की भूमिका है।"},
  {"id":"env-ecology-49","question":"A species whose effect on its ecosystem is much larger than its numbers would suggest, so that its loss changes the whole community, is a:","options":["Pioneer species","Flagship species","Endemic species","Keystone species"],"answer":3,"explanation":"A keystone species, such as a top predator or the fig tree in tropical forests, holds the community together. A flagship species is chosen mainly to draw public support.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"वह प्रजाति जिसका पारिस्थितिकी तंत्र पर प्रभाव उसकी संख्या से कहीं अधिक होता है, जिससे उसके लुप्त होने पर पूरा समुदाय बदल जाता है, क्या कहलाती है?","optionsHi":["अग्रगामी (पायनियर) प्रजाति","प्रमुख (फ्लैगशिप) प्रजाति","स्थानिक प्रजाति","प्रमुख आधार (कीस्टोन) प्रजाति"],"explanationHi":"कीस्टोन प्रजाति, जैसे शीर्ष परभक्षी या उष्णकटिबंधीय वनों में अंजीर का वृक्ष, समुदाय को एक साथ बाँधे रखती है। फ्लैगशिप प्रजाति मुख्यतः जन-समर्थन जुटाने के लिए चुनी जाती है।"},
  {"id":"env-ecology-50","question":"The National Green Tribunal was set up in 2010 under:","options":["The Environment (Protection) Act, 1986","The Wildlife (Protection) Act, 1972","The National Green Tribunal Act, 2010","An executive order of the Ministry of Environment"],"answer":2,"explanation":"The NGT is a statutory body created by the National Green Tribunal Act, 2010, to dispose of environmental cases quickly.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"राष्ट्रीय हरित अधिकरण की स्थापना 2010 में किसके अंतर्गत की गई थी?","optionsHi":["पर्यावरण (संरक्षण) अधिनियम, 1986","वन्यजीव (संरक्षण) अधिनियम, 1972","राष्ट्रीय हरित अधिकरण अधिनियम, 2010","पर्यावरण मंत्रालय का एक कार्यकारी आदेश"],"explanationHi":"NGT राष्ट्रीय हरित अधिकरण अधिनियम, 2010 द्वारा गठित एक वैधानिक निकाय है, जिसका उद्देश्य पर्यावरण संबंधी मामलों का शीघ्र निपटारा करना है।"},
  {"id":"env-ecology-51","question":"Mass nesting ('arribada') of Olive Ridley turtles takes place mainly on the coast of:","options":["Odisha, at Gahirmatha and Rushikulya","Kerala, at Kovalam and Varkala","Tamil Nadu, at Rameswaram and Dhanushkodi","Maharashtra, at Velas and Ratnagiri"],"answer":0,"explanation":"Hundreds of thousands of Olive Ridleys nest together on the Odisha beaches of Gahirmatha, Rushikulya and the Devi river mouth. Velas in Maharashtra sees only scattered nesting, not an arribada.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"ऑलिव रिडले कछुओं का सामूहिक नीड़न ('अर्रिबादा') मुख्यतः किस तट पर होता है?","optionsHi":["ओडिशा, गहिरमाथा और ऋषिकुल्या में","केरल, कोवलम और वर्कला में","तमिलनाडु, रामेश्वरम और धनुषकोडी में","महाराष्ट्र, वेलास और रत्नागिरी में"],"explanationHi":"लाखों ऑलिव रिडले कछुए ओडिशा के गहिरमाथा, ऋषिकुल्या और देवी नदी मुहाने के समुद्र तटों पर एक साथ अंडे देते हैं। महाराष्ट्र के वेलास में केवल छिटपुट नीड़न होता है, अर्रिबादा नहीं।"},
  {"id":"env-ecology-52","question":"In 1730, Amrita Devi and more than 350 members of the Bishnoi community gave their lives to save khejri trees at:","options":["Reni, Uttarakhand","Silent Valley, Kerala","Khejarli, Rajasthan","Sirsi, Karnataka"],"answer":2,"explanation":"The Khejarli sacrifice near Jodhpur is an early example of tree-protection; the Chipko movement at Reni came more than two centuries later.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"1730 में अमृता देवी और बिश्नोई समुदाय के 350 से अधिक सदस्यों ने खेजड़ी के वृक्षों को बचाने के लिए कहाँ अपने प्राणों की आहुति दी?","optionsHi":["रैणी, उत्तराखंड","साइलेंट वैली, केरल","खेजड़ली, राजस्थान","सिरसी, कर्नाटक"],"explanationHi":"जोधपुर के निकट खेजड़ली का बलिदान वृक्ष-संरक्षण का एक प्रारंभिक उदाहरण है; रैणी में चिपको आंदोलन इसके दो शताब्दियों से भी अधिक बाद हुआ।"},
  {"id":"env-ecology-53","question":"Flooded paddy fields and the digestion of cattle are major sources of which greenhouse gas?","options":["Carbon monoxide","Methane","Sulphur dioxide","Ozone"],"answer":1,"explanation":"Anaerobic bacteria in waterlogged paddy soil and in the stomachs of ruminants produce methane.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"जलमग्न धान के खेत और पशुओं का पाचन किस हरितगृह गैस के प्रमुख स्रोत हैं?","optionsHi":["कार्बन मोनोऑक्साइड","मीथेन","सल्फर डाइऑक्साइड","ओज़ोन"],"explanationHi":"जलभराव वाली धान की मिट्टी में और जुगाली करने वाले पशुओं के पेट में अवायवीय जीवाणु मीथेन उत्पन्न करते हैं।"},
  {"id":"env-ecology-54","question":"Using micro-organisms to break down pollutants, such as oil spills, into harmless substances is called:","options":["Bioremediation","Biomagnification","Eutrophication","Biofortification"],"answer":0,"explanation":"Bioremediation uses microbes (and sometimes plants) to clean up pollution. Biomagnification is the build-up of toxins up the food chain.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"सूक्ष्मजीवों द्वारा प्रदूषकों, जैसे तेल रिसाव, को हानिरहित पदार्थों में विघटित करना क्या कहलाता है?","optionsHi":["जैव उपचार (बायोरेमेडिएशन)","जैव आवर्धन (बायोमैग्निफिकेशन)","सुपोषण (यूट्रोफिकेशन)","जैव सुदृढ़ीकरण (बायोफोर्टिफिकेशन)"],"explanationHi":"बायोरेमेडिएशन में सूक्ष्मजीवों (और कभी-कभी पौधों) द्वारा प्रदूषण की सफाई की जाती है। जैव आवर्धन खाद्य श्रृंखला में ऊपर की ओर विषैले पदार्थों का संचय है।"},
  {"id":"env-ecology-55","question":"In carbon trading, one carbon credit generally represents:","options":["One kilogram of CO₂ avoided by an offset project","One tonne of pure carbon stored in biomass","One tonne of CO₂-equivalent reduced or removed","One hectare of forest planted or protected"],"answer":2,"explanation":"A carbon credit stands for a reduction or removal of one tonne of CO₂-equivalent; other gases are converted using their global warming potential.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"कार्बन व्यापार में एक कार्बन क्रेडिट सामान्यतः किसका प्रतिनिधित्व करता है?","optionsHi":["ऑफसेट परियोजना द्वारा बचाया गया एक किलोग्राम CO₂","जैवभार में संचित एक टन शुद्ध कार्बन","घटाया या हटाया गया एक टन CO₂-समतुल्य","रोपित या संरक्षित एक हेक्टेयर वन"],"explanationHi":"एक कार्बन क्रेडिट एक टन CO₂-समतुल्य की कमी या निष्कासन को दर्शाता है; अन्य गैसों को उनकी वैश्विक तापन क्षमता के आधार पर परिवर्तित किया जाता है।"},
  {"id":"env-ecology-56","question":"'Blue carbon' refers to carbon:","options":["Released when natural gas, the 'blue' fuel, is burnt","Stored by mangroves, seagrasses and salt marshes","Locked in glaciers, polar ice sheets and permafrost","Emitted by ships and ports along international sea lanes"],"answer":1,"explanation":"Blue carbon is carbon stored by ocean and coastal ecosystems, which can lock it in their sediments for very long periods.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"'ब्लू कार्बन' किस कार्बन को कहते हैं?","optionsHi":["प्राकृतिक गैस, यानी 'नीले' ईंधन, के जलने पर निकलने वाला","मैंग्रोव, समुद्री घासों और लवणीय दलदलों द्वारा संचित","हिमनदों, ध्रुवीय हिम चादरों और पर्माफ्रॉस्ट में जमा हुआ","अंतरराष्ट्रीय समुद्री मार्गों पर जहाज़ों और बंदरगाहों से उत्सर्जित"],"explanationHi":"ब्लू कार्बन वह कार्बन है जो समुद्री और तटीय पारिस्थितिकी तंत्रों द्वारा संचित किया जाता है; ये उसे अपने तलछट में बहुत लंबे समय तक बाँधे रख सकते हैं।"},
  {"id":"env-ecology-57","question":"The St Petersburg Declaration (2010) of the tiger range countries set the goal of:","options":["Banning all trade in tiger parts by 2015","Creating a single tiger reserve across Asia","Doubling the number of wild tigers by 2022","Moving all tigers to protected zoos"],"answer":2,"explanation":"The 13 tiger range countries pledged to double wild tiger numbers by 2022 (the TX2 goal), the next Chinese Year of the Tiger.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"बाघ-क्षेत्र वाले देशों की सेंट पीटर्सबर्ग घोषणा (2010) ने किस लक्ष्य को निर्धारित किया?","optionsHi":["2015 तक बाघ के अंगों के सभी व्यापार पर प्रतिबंध","पूरे एशिया में एक ही बाघ अभयारण्य बनाना","2022 तक जंगली बाघों की संख्या दोगुनी करना","सभी बाघों को संरक्षित चिड़ियाघरों में स्थानांतरित करना"],"explanationHi":"13 बाघ-क्षेत्र वाले देशों ने 2022 तक जंगली बाघों की संख्या दोगुनी करने (TX2 लक्ष्य) का संकल्प लिया, जो अगला चीनी बाघ वर्ष था।"},
  {"id":"env-ecology-58","question":"Project Snow Leopard, covering the high Himalayan states, was launched in:","options":["1973","1992","2016","2009"],"answer":3,"explanation":"Project Snow Leopard began in 2009 to conserve the snow leopard and its high-altitude habitat through a participatory approach.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"ऊँचे हिमालयी राज्यों को शामिल करने वाला प्रोजेक्ट स्नो लेपर्ड कब शुरू किया गया था?","optionsHi":["1973","1992","2016","2009"],"explanationHi":"प्रोजेक्ट स्नो लेपर्ड 2009 में हिम तेंदुए और उसके उच्च-पर्वतीय आवास के संरक्षण के लिए भागीदारी-आधारित दृष्टिकोण से शुरू हुआ।"},
  {"id":"env-ecology-59","question":"India's first Dugong Conservation Reserve was notified in 2022 in:","options":["Palk Bay, Tamil Nadu","Gulf of Kutch, Gujarat","Chilika Lake, Odisha","Lakshadweep"],"answer":0,"explanation":"The dugong reserve in the northern Palk Bay off Tamil Nadu protects seagrass beds that dugongs, or sea cows, graze on.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत का पहला डुगोंग संरक्षण रिज़र्व 2022 में कहाँ अधिसूचित किया गया?","optionsHi":["पाक खाड़ी, तमिलनाडु","कच्छ की खाड़ी, गुजरात","चिल्का झील, ओडिशा","लक्षद्वीप"],"explanationHi":"तमिलनाडु के तट पर उत्तरी पाक खाड़ी में स्थित डुगोंग रिज़र्व समुद्री घास के उन मैदानों की रक्षा करता है जिन्हें डुगोंग, यानी समुद्री गाय, चरते हैं।"},
  {"id":"env-ecology-60","question":"Black carbon, which darkens Himalayan snow and speeds its melting, is mainly:","options":["A long-lived greenhouse gas that persists like CO₂","Fine soot from incomplete burning of fuels and biomass","Dissolved inorganic carbon carried down by glacier melt","Coal dust blown from open-cast mines in the Himalaya"],"answer":1,"explanation":"Black carbon is soot. It stays in the air only days to weeks, which makes it a short-lived climate pollutant, but it absorbs sunlight strongly and lowers the reflectivity of snow.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"ब्लैक कार्बन, जो हिमालय की बर्फ़ को काला कर उसके पिघलने की गति बढ़ाता है, मुख्यतः क्या है?","optionsHi":["CO₂ की तरह लंबे समय तक बनी रहने वाली हरितगृह गैस","ईंधनों और जैवभार के अपूर्ण दहन से निकली सूक्ष्म कालिख","हिमनद के पिघलने से बहकर आया घुला हुआ अकार्बनिक कार्बन","हिमालय की खुली खदानों से उड़ी कोयले की धूल"],"explanationHi":"ब्लैक कार्बन कालिख है। यह वायु में केवल कुछ दिनों से कुछ सप्ताह तक रहती है, इसलिए यह अल्पजीवी जलवायु प्रदूषक है, परंतु यह सूर्य के प्रकाश को तेज़ी से अवशोषित करती है और बर्फ़ की परावर्तकता को घटाती है।"},
  {"id":"env-ecology-61","question":"In which year were the Western Ghats inscribed as a UNESCO World Heritage Site?","options":["2002","2012","1985","2016"],"answer":1,"explanation":"The Western Ghats, a cluster of 39 sites across four states, were inscribed in 2012 for their outstanding biodiversity and endemism.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिमी घाट को किस वर्ष यूनेस्को विश्व धरोहर स्थल के रूप में अंकित किया गया?","optionsHi":["2002","2012","1985","2016"],"explanationHi":"चार राज्यों में फैले 39 स्थलों के समूह, पश्चिमी घाट, को उनकी उत्कृष्ट जैव विविधता और स्थानिकता के लिए 2012 में अंकित किया गया।"},
  {"id":"env-ecology-62","question":"After the Sundarbans, the second largest mangrove ecosystem in India is:","options":["Pichavaram","Chorao Island","Bhitarkanika","Vembanad"],"answer":2,"explanation":"Bhitarkanika in Odisha, in the Brahmani–Baitarani delta, is India's second largest mangrove ecosystem and is famous for saltwater crocodiles.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"सुंदरबन के बाद भारत का दूसरा सबसे बड़ा मैंग्रोव पारिस्थितिकी तंत्र कौन-सा है?","optionsHi":["पिचावरम","चोराओ द्वीप","भितरकनिका","वेम्बनाड"],"explanationHi":"ओडिशा में ब्राह्मणी–बैतरणी डेल्टा में स्थित भितरकनिका भारत का दूसरा सबसे बड़ा मैंग्रोव पारिस्थितिकी तंत्र है और खारे पानी के मगरमच्छों के लिए प्रसिद्ध है।"},
  {"id":"env-ecology-63","question":"The gas that leaked from the Union Carbide plant in the Bhopal disaster of 1984 was:","options":["Methyl isocyanate","Phosgene","Hydrogen sulphide","Chlorine"],"answer":0,"explanation":"Methyl isocyanate (MIC) leaked on the night of 2–3 December 1984, killing thousands. The disaster led to the Environment (Protection) Act, 1986.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"1984 की भोपाल त्रासदी में यूनियन कार्बाइड संयंत्र से कौन-सी गैस रिसी थी?","optionsHi":["मिथाइल आइसोसाइनेट","फॉस्जीन","हाइड्रोजन सल्फाइड","क्लोरीन"],"explanationHi":"मिथाइल आइसोसाइनेट (MIC) 2–3 दिसंबर 1984 की रात रिसी, जिससे हज़ारों लोगों की मृत्यु हुई। इस त्रासदी के कारण पर्यावरण (संरक्षण) अधिनियम, 1986 बना।"},
  {"id":"env-ecology-64","question":"The National Tiger Conservation Authority (NTCA) was constituted in 2006 under:","options":["A notification under the Environment (Protection) Act","A section of the Forest (Conservation) Act, 1980","The Biological Diversity Act, 2002","A 2006 amendment to the Wildlife (Protection) Act"],"answer":3,"explanation":"The 2006 amendment to the Wildlife (Protection) Act created the NTCA as a statutory body, replacing the earlier Project Tiger directorate.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"राष्ट्रीय बाघ संरक्षण प्राधिकरण (NTCA) का गठन 2006 में किसके अंतर्गत किया गया था?","optionsHi":["पर्यावरण (संरक्षण) अधिनियम के अंतर्गत एक अधिसूचना","वन (संरक्षण) अधिनियम, 1980 की एक धारा","जैविक विविधता अधिनियम, 2002","वन्यजीव (संरक्षण) अधिनियम में 2006 का संशोधन"],"explanationHi":"वन्यजीव (संरक्षण) अधिनियम में 2006 के संशोधन ने NTCA को एक वैधानिक निकाय के रूप में बनाया, जिसने पूर्ववर्ती प्रोजेक्ट टाइगर निदेशालय का स्थान लिया।"},
  {"id":"env-ecology-65","question":"The ozone-depleting potential (ODP) of a substance is measured relative to:","options":["Carbon dioxide","CFC-11","Methane","Halon-1301"],"answer":1,"explanation":"ODP compares a chemical's ozone-destroying power with that of CFC-11 (ODP = 1). Global warming potential, by contrast, uses CO₂ as the reference.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किसी पदार्थ की ओज़ोन क्षरण क्षमता (ODP) किसके सापेक्ष मापी जाती है?","optionsHi":["कार्बन डाइऑक्साइड","CFC-11","मीथेन","हैलोन-1301"],"explanationHi":"ODP किसी रसायन की ओज़ोन-नाशक क्षमता की तुलना CFC-11 से करती है (ODP = 1)। इसके विपरीत, वैश्विक तापन क्षमता में संदर्भ के रूप में CO₂ का उपयोग होता है।"},
  {"id":"env-ecology-66","question":"Which of these is NOT a major coral reef area of India?","options":["Gulf of Mannar","Gulf of Kutch","Andaman and Nicobar Islands","Gulf of Khambhat"],"answer":3,"explanation":"India's main reefs are in the Gulf of Mannar, the Gulf of Kutch, the Andaman and Nicobar Islands and Lakshadweep. The Gulf of Khambhat's muddy, turbid water does not suit corals.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सा भारत का प्रमुख प्रवाल भित्ति क्षेत्र नहीं है?","optionsHi":["मन्नार की खाड़ी","कच्छ की खाड़ी","अंडमान और निकोबार द्वीप समूह","खंभात की खाड़ी"],"explanationHi":"भारत की प्रमुख भित्तियाँ मन्नार की खाड़ी, कच्छ की खाड़ी, अंडमान और निकोबार द्वीप समूह तथा लक्षद्वीप में हैं। खंभात की खाड़ी का कीचड़युक्त, गँदला जल प्रवालों के अनुकूल नहीं है।"},
  {"id":"env-ecology-67","question":"India hosted the 14th Conference of Parties (COP-14) in 2019 of the:","options":["UN Convention to Combat Desertification","Ramsar Convention on Wetlands","Convention on Biological Diversity","UN Framework Convention on Climate Change"],"answer":0,"explanation":"COP-14 of the UNCCD was held at Greater Noida (Delhi NCR) in 2019; India set a target to restore 26 million hectares of degraded land by 2030. India had hosted CBD COP-11 at Hyderabad in 2012.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"2019 में भारत ने किसके 14वें पक्षकार सम्मेलन (COP-14) की मेज़बानी की?","optionsHi":["संयुक्त राष्ट्र मरुस्थलीकरण रोकथाम कन्वेंशन","आर्द्रभूमि पर रामसर कन्वेंशन","जैव विविधता पर कन्वेंशन","संयुक्त राष्ट्र जलवायु परिवर्तन फ्रेमवर्क कन्वेंशन"],"explanationHi":"UNCCD का COP-14 2019 में ग्रेटर नोएडा (दिल्ली NCR) में हुआ; भारत ने 2030 तक 26 मिलियन हेक्टेयर निम्नीकृत भूमि को पुनर्स्थापित करने का लक्ष्य रखा। भारत ने 2012 में हैदराबाद में CBD के COP-11 की मेज़बानी की थी।"},
  {"id":"env-ecology-68","question":"Arrange these laws in chronological order: 1. Air (Prevention and Control of Pollution) Act  2. Water (Prevention and Control of Pollution) Act  3. Forest (Conservation) Act  4. Wildlife (Protection) Act","options":["4-3-2-1","2-4-3-1","4-2-1-3","4-2-3-1"],"answer":3,"explanation":"Wildlife (Protection) Act 1972, Water Act 1974, Forest (Conservation) Act 1980 and Air Act 1981. So 4-2-3-1.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन कानूनों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम  2. जल (प्रदूषण निवारण और नियंत्रण) अधिनियम  3. वन (संरक्षण) अधिनियम  4. वन्यजीव (संरक्षण) अधिनियम","optionsHi":["4-3-2-1","2-4-3-1","4-2-1-3","4-2-3-1"],"explanationHi":"वन्यजीव (संरक्षण) अधिनियम 1972, जल अधिनियम 1974, वन (संरक्षण) अधिनियम 1980 और वायु अधिनियम 1981। अतः 4-2-3-1।"},
  {"id":"env-ecology-69","question":"Match the environmental movement with its region. A. Chipko  B. Appiko  C. Jungle Bachao Andolan  D. Narmada Bachao Andolan; 1. Singhbhum, then in Bihar and now in Jharkhand  2. Garhwal Himalaya, now in Uttarakhand  3. Narmada valley  4. Uttara Kannada, Karnataka","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"answer":0,"explanation":"Chipko began in Garhwal, Appiko in the Western Ghats of Karnataka, Jungle Bachao in Singhbhum against replacing sal forests with teak, and Narmada Bachao against the large dams on the Narmada.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पर्यावरण आंदोलन का उसके क्षेत्र से मिलान कीजिए। A. चिपको  B. अप्पिको  C. जंगल बचाओ आंदोलन  D. नर्मदा बचाओ आंदोलन; 1. सिंहभूम, तब बिहार में और अब झारखंड में  2. गढ़वाल हिमालय, अब उत्तराखंड में  3. नर्मदा घाटी  4. उत्तर कन्नड़, कर्नाटक","optionsHi":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"explanationHi":"चिपको गढ़वाल में, अप्पिको कर्नाटक के पश्चिमी घाट में शुरू हुआ; जंगल बचाओ आंदोलन सिंहभूम में साल के वनों को सागौन से बदलने के विरुद्ध था, और नर्मदा बचाओ आंदोलन नर्मदा पर बड़े बाँधों के विरुद्ध था।"},
  {"id":"env-ecology-70","question":"How many of the following statements about India's climate commitments are correct? I. India announced a net-zero emissions target for 2050 at COP-26 in Glasgow. II. The International Solar Alliance was launched by India and the USA at COP-21 in Paris. III. India's updated NDC aims for about half of its installed electric power capacity to come from non-fossil sources by 2030. IV. India accepted binding emission reduction targets under the Kyoto Protocol.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. India's net-zero target at Glasgow is 2070 (I wrong); the ISA was launched by India and France at Paris (II wrong); and Kyoto's binding targets applied only to Annex I countries (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"भारत की जलवायु प्रतिबद्धताओं के बारे में निम्नलिखित में से कितने कथन सही हैं? I. भारत ने ग्लासगो में COP-26 में 2050 के लिए शुद्ध-शून्य उत्सर्जन लक्ष्य की घोषणा की। II. अंतरराष्ट्रीय सौर गठबंधन भारत और अमेरिका द्वारा पेरिस में COP-21 में शुरू किया गया था। III. भारत के अद्यतन NDC का लक्ष्य 2030 तक अपनी स्थापित विद्युत क्षमता का लगभग आधा हिस्सा गैर-जीवाश्म स्रोतों से प्राप्त करना है। IV. भारत ने क्योटो प्रोटोकॉल के अंतर्गत बाध्यकारी उत्सर्जन कटौती लक्ष्य स्वीकार किए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल III सही है। ग्लासगो में भारत का शुद्ध-शून्य लक्ष्य 2070 है (I गलत); ISA को पेरिस में भारत और फ्रांस ने शुरू किया था (II गलत); और क्योटो के बाध्यकारी लक्ष्य केवल अनुलग्नक I देशों पर लागू थे (IV गलत)।"},
  {"id":"env-ecology-71","question":"Match the natural World Heritage Site with its state. A. Manas  B. Nanda Devi and Valley of Flowers  C. Great Himalayan National Park  D. Khangchendzonga National Park; 1. Himachal Pradesh  2. Sikkim  3. Assam  4. Uttarakhand","options":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2"],"answer":1,"explanation":"Manas is in Assam, Nanda Devi and Valley of Flowers in Uttarakhand, the Great Himalayan National Park in Himachal Pradesh and Khangchendzonga in Sikkim.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"प्राकृतिक विश्व धरोहर स्थल का उसके राज्य से मिलान कीजिए। A. मानस  B. नंदा देवी और फूलों की घाटी  C. ग्रेट हिमालयन राष्ट्रीय उद्यान  D. खंगचेंदज़ोंगा राष्ट्रीय उद्यान; 1. हिमाचल प्रदेश  2. सिक्किम  3. असम  4. उत्तराखंड","optionsHi":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2"],"explanationHi":"मानस असम में, नंदा देवी और फूलों की घाटी उत्तराखंड में, ग्रेट हिमालयन राष्ट्रीय उद्यान हिमाचल प्रदेश में और खंगचेंदज़ोंगा सिक्किम में है।"},
  {"id":"env-ecology-72","question":"Match the animal with the protected area known for it. A. Hoolock gibbon  B. Blackbuck  C. Hard-ground barasingha  D. Red panda; 1. Kanha, Madhya Pradesh  2. Singalila, West Bengal  3. Hollongapar Gibbon Sanctuary, Assam  4. Velavadar, Gujarat","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"India's only ape, the hoolock gibbon, lives in Hollongapar; Velavadar is a blackbuck national park; Kanha saved the hard-ground barasingha from near-extinction; Singalila is known for red pandas.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पशु का उसके लिए प्रसिद्ध संरक्षित क्षेत्र से मिलान कीजिए। A. हूलॉक गिब्बन  B. काला हिरण  C. कठोर-भूमि बारहसिंगा  D. लाल पांडा; 1. कान्हा, मध्य प्रदेश  2. सिंगालिला, पश्चिम बंगाल  3. होलोंगापार गिब्बन अभयारण्य, असम  4. वेलावदर, गुजरात","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"भारत का एकमात्र वानर, हूलॉक गिब्बन, होलोंगापार में रहता है; वेलावदर एक काला हिरण राष्ट्रीय उद्यान है; कान्हा ने कठोर-भूमि बारहसिंगा को विलुप्ति के कगार से बचाया; सिंगालिला लाल पांडा के लिए जाना जाता है।"},
  {"id":"env-ecology-73","question":"Assertion (A): Coral reefs turn white (bleach) when sea temperatures stay unusually high. Reason (R): Under heat stress, corals expel the symbiotic zooxanthellae algae that give them colour and food.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Corals depend on zooxanthellae for colour and most of their food. Warm water makes them expel the algae, leaving the white skeleton visible. R explains A.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): जब समुद्र का तापमान असामान्य रूप से अधिक बना रहता है, तो प्रवाल भित्तियाँ सफ़ेद पड़ जाती हैं (विरंजन)। कारण (R): ऊष्मीय दबाव में प्रवाल उन सहजीवी ज़ूज़ैन्थेली शैवालों को बाहर निकाल देते हैं जो उन्हें रंग और भोजन देते हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"प्रवाल रंग और अपने अधिकांश भोजन के लिए ज़ूज़ैन्थेली पर निर्भर होते हैं। गर्म जल उन्हें शैवाल बाहर निकालने पर विवश करता है, जिससे सफ़ेद कंकाल दिखाई देने लगता है। R, A की व्याख्या करता है।"},
  {"id":"env-ecology-74","question":"Assertion (A): Mangrove forests reduce the damage caused by storm surges and tsunamis on coasts. Reason (R): Mangroves grow best in fresh water, far from the sea.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"A is true: dense roots break waves and trap sediment. R is false: mangroves are salt-tolerant plants of the tidal zone in estuaries and deltas.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): मैंग्रोव वन तटों पर तूफ़ानी लहरों और सुनामी से होने वाली क्षति को कम करते हैं। कारण (R): मैंग्रोव समुद्र से दूर, मीठे पानी में सबसे अच्छे उगते हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A सही है, परंतु R गलत है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A गलत है, परंतु R सही है"],"explanationHi":"A सही है: घनी जड़ें लहरों को रोकती हैं और तलछट को रोक लेती हैं। R गलत है: मैंग्रोव लवण-सहिष्णु पौधे हैं जो मुहानों और डेल्टाओं के ज्वारीय क्षेत्र में उगते हैं।"},
  {"id":"env-ecology-75","question":"Arrange these gases in increasing order of their 100-year global warming potential: 1. Nitrous oxide  2. Carbon dioxide  3. Sulphur hexafluoride  4. Methane","options":["2-1-4-3","2-4-1-3","4-2-1-3","2-4-3-1"],"answer":1,"explanation":"Taking CO₂ as 1, methane is about 28, nitrous oxide about 265 and SF₆ about 23,500. So 2-4-1-3.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन गैसों को उनकी 100-वर्षीय वैश्विक तापन क्षमता के बढ़ते क्रम में व्यवस्थित कीजिए: 1. नाइट्रस ऑक्साइड  2. कार्बन डाइऑक्साइड  3. सल्फर हेक्साफ्लोराइड  4. मीथेन","optionsHi":["2-1-4-3","2-4-1-3","4-2-1-3","2-4-3-1"],"explanationHi":"CO₂ को 1 मानने पर मीथेन लगभग 28, नाइट्रस ऑक्साइड लगभग 265 और SF₆ लगभग 23,500 है। अतः 2-4-1-3।"},
  {"id":"env-ecology-76","question":"How many of the following are notified under the Environment (Protection) Act, 1986? I. Eco-sensitive zones around protected areas  II. The Coastal Regulation Zone notification  III. The Environmental Impact Assessment notification","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are issued under the EP Act. National parks and sanctuaries, by contrast, are declared under the Wildlife (Protection) Act, 1972.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितने पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत अधिसूचित किए जाते हैं? I. संरक्षित क्षेत्रों के आसपास पारिस्थितिक रूप से संवेदनशील क्षेत्र  II. तटीय विनियमन क्षेत्र (CRZ) अधिसूचना  III. पर्यावरण प्रभाव आकलन (EIA) अधिसूचना","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"तीनों EP अधिनियम के अंतर्गत जारी किए जाते हैं। इसके विपरीत, राष्ट्रीय उद्यान और अभयारण्य वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत घोषित किए जाते हैं।"},
  {"id":"env-ecology-77","question":"Which of the following is NOT a statutory body (created by an Act of Parliament)?","options":["Central Pollution Control Board","National Biodiversity Authority","Animal Welfare Board of India","Wildlife Institute of India"],"answer":3,"explanation":"The Wildlife Institute of India (Dehradun) is an autonomous institute of the Environment Ministry. The CPCB comes from the Water Act 1974, the NBA from the Biological Diversity Act 2002 and the AWBI from the Prevention of Cruelty to Animals Act 1960.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन-सा वैधानिक निकाय (संसद के अधिनियम द्वारा गठित) नहीं है?","optionsHi":["केंद्रीय प्रदूषण नियंत्रण बोर्ड","राष्ट्रीय जैव विविधता प्राधिकरण","भारतीय पशु कल्याण बोर्ड","भारतीय वन्यजीव संस्थान"],"explanationHi":"भारतीय वन्यजीव संस्थान (देहरादून) पर्यावरण मंत्रालय का एक स्वायत्त संस्थान है। CPCB जल अधिनियम 1974 से, NBA जैविक विविधता अधिनियम 2002 से और AWBI पशुओं के प्रति क्रूरता निवारण अधिनियम 1960 से बना है।"},
  {"id":"env-ecology-78","question":"Match the invasive plant with its description. A. Lantana camara  B. Prosopis juliflora  C. Eichhornia crassipes  D. Parthenium hysterophorus; 1. Floating water weed that chokes ponds, called the 'terror of Bengal'  2. 'Congress grass', a weed that causes allergies  3. Thorny Mexican shrub ('vilayati babul') spreading in dry areas  4. Flowering shrub that has invaded forests and tiger habitats","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"Lantana smothers forest undergrowth, Prosopis juliflora (vilayati babul) spreads in drylands, water hyacinth (Eichhornia) chokes water bodies and Parthenium is congress grass.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"आक्रामक पादप का उसके वर्णन से मिलान कीजिए। A. लैंटाना कैमारा  B. प्रोसोपिस जूलीफ्लोरा  C. आइकोर्निया क्रैसिपीज़  D. पार्थेनियम हिस्टेरोफोरस; 1. तैरने वाला जलीय खरपतवार जो तालाबों को अवरुद्ध कर देता है, जिसे 'बंगाल का आतंक' कहते हैं  2. 'गाजर घास (कांग्रेस घास)', एलर्जी उत्पन्न करने वाला खरपतवार  3. शुष्क क्षेत्रों में फैलने वाली काँटेदार मैक्सिकन झाड़ी ('विलायती बबूल')  4. फूलदार झाड़ी जिसने वनों और बाघ आवासों पर आक्रमण कर लिया है","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2"],"explanationHi":"लैंटाना वन के निचले स्तर की वनस्पति को दबा देता है, प्रोसोपिस जूलीफ्लोरा (विलायती बबूल) शुष्क क्षेत्रों में फैलता है, जलकुंभी (आइकोर्निया) जलाशयों को अवरुद्ध करती है और पार्थेनियम गाजर घास है।"},
  {"id":"env-ecology-79","question":"How many of the following statements about biosphere reserves in India are correct? I. The Sundarbans Biosphere Reserve, set up in 1986, was India's first. II. The Gulf of Mannar Biosphere Reserve includes a marine national park. III. The Nilgiri Biosphere Reserve is the largest biosphere reserve in India by area. IV. All of India's biosphere reserves are included in UNESCO's World Network of Biosphere Reserves.","options":["Only one","Only three","Only two","All four"],"answer":0,"explanation":"Only II is correct. India's first biosphere reserve was the Nilgiri (1986), and the largest is the Great Rann of Kutch, so I and III are wrong. IV is wrong: only some Indian reserves are on UNESCO's World Network.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"भारत के जैवमंडल आरक्षित क्षेत्रों के बारे में निम्नलिखित में से कितने कथन सही हैं? I. 1986 में स्थापित सुंदरबन जैवमंडल आरक्षित क्षेत्र भारत का पहला था। II. मन्नार की खाड़ी जैवमंडल आरक्षित क्षेत्र में एक समुद्री राष्ट्रीय उद्यान शामिल है। III. नीलगिरि जैवमंडल आरक्षित क्षेत्र क्षेत्रफल की दृष्टि से भारत का सबसे बड़ा जैवमंडल आरक्षित क्षेत्र है। IV. भारत के सभी जैवमंडल आरक्षित क्षेत्र यूनेस्को के विश्व जैवमंडल आरक्षित क्षेत्र नेटवर्क में शामिल हैं।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"केवल II सही है। भारत का पहला जैवमंडल आरक्षित क्षेत्र नीलगिरि (1986) था, और सबसे बड़ा कच्छ का महान रण है, इसलिए I और III गलत हैं। IV गलत है: भारत के केवल कुछ आरक्षित क्षेत्र ही यूनेस्को के विश्व नेटवर्क में हैं।"},
  {"id":"env-ecology-80","question":"Match the UNFCCC Conference of Parties with its host city. A. COP-21  B. COP-26  C. COP-27  D. COP-28; 1. Dubai  2. Sharm el-Sheikh  3. Paris  4. Glasgow","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"answer":2,"explanation":"COP-21 (2015) in Paris adopted the Paris Agreement, COP-26 (2021) was in Glasgow, COP-27 (2022) in Sharm el-Sheikh agreed to set up a loss and damage fund, and COP-28 (2023) was in Dubai.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"UNFCCC के पक्षकार सम्मेलन का उसके मेज़बान शहर से मिलान कीजिए। A. COP-21  B. COP-26  C. COP-27  D. COP-28; 1. दुबई  2. शर्म अल-शेख  3. पेरिस  4. ग्लासगो","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"explanationHi":"पेरिस में COP-21 (2015) में पेरिस समझौता अपनाया गया, COP-26 (2021) ग्लासगो में हुआ, शर्म अल-शेख में COP-27 (2022) में हानि और क्षति कोष स्थापित करने पर सहमति बनी, और COP-28 (2023) दुबई में हुआ।"},
  {"id":"env-ecology-81","question":"How many of the following statements about the Ganges river dolphin are correct? I. It is India's National Aquatic Animal. II. It is nearly blind and finds its way and food by echolocation. III. The Vikramshila Gangetic Dolphin Sanctuary is in Bihar. IV. It is listed as Endangered on the IUCN Red List.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The dolphin was declared the National Aquatic Animal in 2009, and the Vikramshila sanctuary near Bhagalpur protects a stretch of the Ganga.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"गंगा नदी की डॉल्फिन के बारे में निम्नलिखित में से कितने कथन सही हैं? I. यह भारत का राष्ट्रीय जलीय जीव है। II. यह लगभग अंधी होती है और प्रतिध्वनि-स्थान निर्धारण (इकोलोकेशन) से अपना मार्ग और भोजन खोजती है। III. विक्रमशिला गंगा डॉल्फिन अभयारण्य बिहार में है। IV. यह IUCN रेड लिस्ट में संकटग्रस्त के रूप में सूचीबद्ध है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चारों सही हैं। डॉल्फिन को 2009 में राष्ट्रीय जलीय जीव घोषित किया गया था, और भागलपुर के निकट विक्रमशिला अभयारण्य गंगा के एक खंड की रक्षा करता है।"},
  {"id":"env-ecology-82","question":"Match the report with the organisation that publishes it. A. India State of Forest Report  B. Living Planet Report  C. Emissions Gap Report  D. Global Risks Report; 1. World Economic Forum  2. UNEP  3. Forest Survey of India  4. WWF","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2"],"answer":0,"explanation":"The Forest Survey of India (Dehradun) publishes the ISFR every two years, WWF the Living Planet Report, UNEP the Emissions Gap Report and the World Economic Forum the Global Risks Report.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"रिपोर्ट का उसे प्रकाशित करने वाले संगठन से मिलान कीजिए। A. भारत वन स्थिति रिपोर्ट  B. लिविंग प्लैनेट रिपोर्ट  C. एमिशंस गैप रिपोर्ट  D. ग्लोबल रिस्क्स रिपोर्ट; 1. विश्व आर्थिक मंच  2. UNEP  3. भारतीय वन सर्वेक्षण  4. WWF","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2"],"explanationHi":"भारतीय वन सर्वेक्षण (देहरादून) हर दो वर्ष में ISFR प्रकाशित करता है, WWF लिविंग प्लैनेट रिपोर्ट, UNEP एमिशंस गैप रिपोर्ट और विश्व आर्थिक मंच ग्लोबल रिस्क्स रिपोर्ट प्रकाशित करता है।"},
  {"id":"env-ecology-83","question":"How many of the following statements are correct? I. The Forest Rights Act, 2006 recognises the forest rights of Scheduled Tribes and other traditional forest dwellers. II. Under that Act, the Gram Sabha starts the process of deciding individual and community rights. III. The Compensatory Afforestation Fund Act, 2016 governs funds collected for afforestation when forest land is diverted. IV. The National Biodiversity Authority, set up under the Biological Diversity Act, 2002, is headquartered in Chennai.","options":["Only two","Only three","Only one","All four"],"answer":3,"explanation":"All four are correct: the FRA makes the Gram Sabha the body that initiates rights claims, CAMPA funds are governed by the 2016 Act, and the NBA is based in Chennai.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. वन अधिकार अधिनियम, 2006 अनुसूचित जनजातियों और अन्य पारंपरिक वनवासियों के वन अधिकारों को मान्यता देता है। II. उस अधिनियम के अंतर्गत व्यक्तिगत और सामुदायिक अधिकारों के निर्धारण की प्रक्रिया ग्राम सभा शुरू करती है। III. प्रतिकारात्मक वनरोपण निधि अधिनियम, 2016 वन भूमि के अन्यत्र उपयोग पर वनरोपण के लिए एकत्र की गई निधियों को नियंत्रित करता है। IV. जैविक विविधता अधिनियम, 2002 के अंतर्गत गठित राष्ट्रीय जैव विविधता प्राधिकरण का मुख्यालय चेन्नई में है।","optionsHi":["केवल दो","केवल तीन","केवल एक","सभी चार"],"explanationHi":"सभी चारों सही हैं: FRA ग्राम सभा को अधिकार-दावे शुरू करने वाली संस्था बनाता है, CAMPA निधियाँ 2016 के अधिनियम से नियंत्रित होती हैं, और NBA का मुख्यालय चेन्नई में है।"},
  {"id":"env-ecology-84","question":"How many of the following statements about the reintroduction of cheetahs in India are correct? I. India officially declared the cheetah extinct in 1972, the year the Wildlife (Protection) Act was passed. II. Cheetahs were brought from Namibia and South Africa. III. They were first released in Kuno National Park in Rajasthan. IV. The African cheetahs belong to the same subspecies as the extinct Asiatic cheetah.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. The cheetah was declared extinct in India in 1952 (the last ones were shot in 1947), Kuno National Park is in Madhya Pradesh, and the African animals are a different subspecies from the Asiatic cheetah.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"भारत में चीतों के पुनःप्रवेश के बारे में निम्नलिखित में से कितने कथन सही हैं? I. भारत ने 1972 में, जिस वर्ष वन्यजीव (संरक्षण) अधिनियम पारित हुआ, चीते को आधिकारिक रूप से विलुप्त घोषित किया। II. चीते नामीबिया और दक्षिण अफ्रीका से लाए गए थे। III. उन्हें पहले राजस्थान के कूनो राष्ट्रीय उद्यान में छोड़ा गया था। IV. अफ्रीकी चीते उसी उप-प्रजाति के हैं जिसके विलुप्त एशियाई चीते थे।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है। चीते को भारत में 1952 में विलुप्त घोषित किया गया था (अंतिम चीते 1947 में मारे गए थे), कूनो राष्ट्रीय उद्यान मध्य प्रदेश में है, और अफ्रीकी चीते एशियाई चीते से भिन्न उप-प्रजाति के हैं।"},
  {"id":"env-ecology-85","question":"Which of the following is NOT one of the eight national missions under India's National Action Plan on Climate Change (2008)?","options":["National Solar Mission","National Mission for a Green India","National Mission on Clean Coal","National Mission for Sustaining the Himalayan Ecosystem"],"answer":2,"explanation":"The eight NAPCC missions are Solar, Enhanced Energy Efficiency, Sustainable Habitat, Water, Sustaining the Himalayan Ecosystem, Green India, Sustainable Agriculture and Strategic Knowledge for Climate Change. There is no clean-coal mission.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन-सा जलवायु परिवर्तन पर भारत की राष्ट्रीय कार्य योजना (2008) के अंतर्गत आठ राष्ट्रीय मिशनों में से एक नहीं है?","optionsHi":["राष्ट्रीय सौर मिशन","राष्ट्रीय हरित भारत मिशन","राष्ट्रीय स्वच्छ कोयला मिशन","हिमालयी पारिस्थितिकी तंत्र को बनाए रखने के लिए राष्ट्रीय मिशन"],"explanationHi":"NAPCC के आठ मिशन हैं: सौर, उन्नत ऊर्जा दक्षता, संधारणीय आवास, जल, हिमालयी पारिस्थितिकी तंत्र को बनाए रखना, हरित भारत, संधारणीय कृषि और जलवायु परिवर्तन के लिए सामरिक ज्ञान। स्वच्छ कोयले का कोई मिशन नहीं है।"},
  {"id":"env-ecology-86","question":"In an ecosystem, the organisms that make their own food from sunlight are called:","options":["Producers","Herbivores","Decomposers","Carnivores"],"answer":0,"explanation":"Green plants, algae and some bacteria are producers (autotrophs); every food chain starts with them. Consumers and decomposers depend on the energy they fix.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"किसी पारिस्थितिकी तंत्र में सूर्य के प्रकाश से अपना भोजन स्वयं बनाने वाले जीव क्या कहलाते हैं?","optionsHi":["उत्पादक","शाकाहारी","अपघटक","मांसाहारी"],"explanationHi":"हरे पौधे, शैवाल और कुछ जीवाणु उत्पादक (स्वपोषी) हैं; प्रत्येक खाद्य श्रृंखला उन्हीं से शुरू होती है। उपभोक्ता और अपघटक उनके द्वारा स्थिर की गई ऊर्जा पर निर्भर रहते हैं।"},
  {"id":"env-ecology-87","question":"Which of these wastes is non-biodegradable?","options":["Vegetable peels","Polythene bags","Paper","Cotton cloth"],"answer":1,"explanation":"Microbes cannot readily break down most plastics such as polythene, so they persist for centuries. Peels, paper and cotton are decomposed naturally.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"इनमें से कौन-सा अपशिष्ट अजैवनिम्नीकरणीय है?","optionsHi":["सब्ज़ियों के छिलके","पॉलिथीन की थैलियाँ","कागज़","सूती कपड़ा"],"explanationHi":"सूक्ष्मजीव पॉलिथीन जैसे अधिकांश प्लास्टिक को आसानी से विघटित नहीं कर पाते, इसलिए वे सदियों तक बने रहते हैं। छिलके, कागज़ और सूती कपड़ा प्राकृतिक रूप से अपघटित हो जाते हैं।"},
  {"id":"env-ecology-88","question":"Bacteria and fungi that break down dead plants and animals and return nutrients to the soil are called:","options":["Producers","Primary consumers","Decomposers","Predators"],"answer":2,"explanation":"Decomposers recycle nutrients locked in dead matter; without them, elements such as nitrogen and phosphorus would not return to the soil.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"मृत पौधों और जंतुओं को विघटित कर पोषक तत्वों को मिट्टी में लौटाने वाले जीवाणु और कवक क्या कहलाते हैं?","optionsHi":["उत्पादक","प्राथमिक उपभोक्ता","अपघटक","परभक्षी"],"explanationHi":"अपघटक मृत पदार्थ में बँधे पोषक तत्वों का पुनर्चक्रण करते हैं; उनके बिना नाइट्रोजन और फॉस्फोरस जैसे तत्व मिट्टी में वापस नहीं लौट पाते।"},
  {"id":"env-ecology-89","question":"The “3 Rs” of waste management stand for:","options":["Remove, Replace, Repair","Recover, Refine, Resell","Read, Recall, Revise","Reduce, Reuse, Recycle"],"answer":3,"explanation":"Reducing waste comes first, then reusing items, and finally recycling materials into new products.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"अपशिष्ट प्रबंधन के “3 R” का क्या अर्थ है?","optionsHi":["हटाना, बदलना, मरम्मत करना (Remove, Replace, Repair)","पुनःप्राप्त करना, परिष्कृत करना, पुनः बेचना (Recover, Refine, Resell)","पढ़ना, याद करना, दोहराना (Read, Recall, Revise)","कम करना, पुनः उपयोग करना, पुनर्चक्रण करना (Reduce, Reuse, Recycle)"],"explanationHi":"सबसे पहले अपशिष्ट को कम किया जाता है, फिर वस्तुओं का पुनः उपयोग, और अंत में पदार्थों का पुनर्चक्रण करके नए उत्पाद बनाए जाते हैं।"},
  {"id":"env-ecology-90","question":"Which of these is the most effective way to check soil erosion on a slope?","options":["Maintaining a cover of trees and grass","Removing vegetation so rain drains off faster","Allowing controlled grazing to trample soil firm","Ploughing straight down the slope"],"answer":0,"explanation":"Plant roots bind soil and leaves break the force of rain. Clearing vegetation, overgrazing and ploughing up and down the slope all speed up erosion.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"ढलान पर मृदा अपरदन को रोकने का सबसे प्रभावी तरीका इनमें से कौन-सा है?","optionsHi":["वृक्षों और घास का आवरण बनाए रखना","वनस्पति हटाना ताकि वर्षा का पानी तेज़ी से बह जाए","नियंत्रित चराई की अनुमति देना ताकि पशुओं के रौंदने से मिट्टी कठोर हो जाए","ढलान के सीध में नीचे की ओर जुताई करना"],"explanationHi":"पौधों की जड़ें मिट्टी को बाँधती हैं और पत्तियाँ वर्षा के वेग को कम करती हैं। वनस्पति हटाना, अतिचारण और ढलान के ऊपर-नीचे जुताई करना, तीनों अपरदन को तेज़ करते हैं।"},
  {"id":"env-ecology-91","question":"Which biome has the highest biodiversity on land?","options":["Tundra","Tropical rainforest","Temperate grassland","Hot desert"],"answer":1,"explanation":"Warm temperatures, abundant rain all year and a long, stable history make tropical rainforests the richest terrestrial biome, though they cover a small share of the land.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"स्थल पर किस बायोम में सर्वाधिक जैव विविधता पाई जाती है?","optionsHi":["टुंड्रा","उष्णकटिबंधीय वर्षावन","शीतोष्ण घास का मैदान","उष्ण मरुस्थल"],"explanationHi":"गर्म तापमान, वर्ष भर प्रचुर वर्षा और लंबा, स्थिर इतिहास उष्णकटिबंधीय वर्षावनों को स्थलीय बायोम में सबसे समृद्ध बनाते हैं, हालाँकि वे भूमि के एक छोटे भाग में ही फैले हैं।"},
  {"id":"env-ecology-92","question":"Which of these is an abiotic component of an ecosystem?","options":["Grass","Earthworms","Sunlight","Fungi"],"answer":2,"explanation":"Abiotic components are non-living factors such as sunlight, temperature, water and soil minerals. Grass, earthworms and fungi are biotic.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"इनमें से कौन-सा पारिस्थितिकी तंत्र का अजैविक घटक है?","optionsHi":["घास","केंचुए","सूर्य का प्रकाश","कवक"],"explanationHi":"अजैविक घटक सूर्य का प्रकाश, तापमान, जल और मृदा खनिज जैसे निर्जीव कारक हैं। घास, केंचुए और कवक जैविक हैं।"},
  {"id":"env-ecology-93","question":"In a food chain, herbivores such as deer and grasshoppers are:","options":["Producers","Secondary consumers","Decomposers","Primary consumers"],"answer":3,"explanation":"Herbivores eat producers directly and occupy the second trophic level as primary consumers; carnivores that eat them are secondary consumers.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"किसी खाद्य श्रृंखला में हिरण और टिड्डे जैसे शाकाहारी जीव क्या होते हैं?","optionsHi":["उत्पादक","द्वितीयक उपभोक्ता","अपघटक","प्राथमिक उपभोक्ता"],"explanationHi":"शाकाहारी जीव उत्पादकों को सीधे खाते हैं और प्राथमिक उपभोक्ता के रूप में दूसरे पोषण स्तर पर होते हैं; उन्हें खाने वाले मांसाहारी द्वितीयक उपभोक्ता होते हैं।"},
  {"id":"env-ecology-94","question":"Ecological succession on abandoned farmland or after a forest fire, where soil is already present, is called:","options":["Secondary succession","Primary succession","Retrogressive succession","Xerarch succession on bare rock"],"answer":0,"explanation":"Secondary succession starts where a community was removed but soil remains, so it is faster. Primary succession begins on lifeless surfaces such as bare rock or new lava.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"परित्यक्त कृषि भूमि पर या वनाग्नि के बाद, जहाँ मिट्टी पहले से मौजूद होती है, होने वाला पारिस्थितिक अनुक्रमण क्या कहलाता है?","optionsHi":["द्वितीयक अनुक्रमण","प्राथमिक अनुक्रमण","प्रतिगामी अनुक्रमण","नंगी चट्टान पर शुष्कारंभी (ज़ेरार्क) अनुक्रमण"],"explanationHi":"द्वितीयक अनुक्रमण वहाँ शुरू होता है जहाँ समुदाय हट गया हो पर मिट्टी बची हो, इसलिए यह तेज़ होता है। प्राथमिक अनुक्रमण नंगी चट्टान या नए लावा जैसी निर्जीव सतहों पर शुरू होता है।"},
  {"id":"env-ecology-95","question":"Which of these is an example of in situ conservation?","options":["A zoo","A national park","A seed bank","A botanical garden"],"answer":1,"explanation":"In situ conservation protects species in their natural habitat, as in national parks and sanctuaries. Zoos, seed banks and botanical gardens conserve species outside it (ex situ).","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"इनमें से कौन-सा स्वस्थाने (इन सीटू) संरक्षण का उदाहरण है?","optionsHi":["चिड़ियाघर","राष्ट्रीय उद्यान","बीज बैंक","वनस्पति उद्यान"],"explanationHi":"स्वस्थाने संरक्षण में प्रजातियों की रक्षा उनके प्राकृतिक आवास में की जाती है, जैसे राष्ट्रीय उद्यानों और अभयारण्यों में। चिड़ियाघर, बीज बैंक और वनस्पति उद्यान प्रजातियों का संरक्षण उसके बाहर (बहिःस्थाने) करते हैं।"},
  {"id":"env-ecology-96","question":"A very high Biochemical Oxygen Demand (BOD) in a river indicates that the water:","options":["Is very clean, with few microbes present","Is rich in dissolved oxygen for aquatic life","Is heavily polluted with organic matter","Is very cold"],"answer":2,"explanation":"Microbes decomposing organic waste such as sewage use up dissolved oxygen, so a high BOD signals heavy organic pollution and low oxygen left for fish.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"किसी नदी में जैव रासायनिक ऑक्सीजन माँग (BOD) का बहुत अधिक होना दर्शाता है कि जल:","optionsHi":["बहुत स्वच्छ है, जिसमें सूक्ष्मजीव कम हैं","जलीय जीवन के लिए घुली ऑक्सीजन से समृद्ध है","कार्बनिक पदार्थ से अत्यधिक प्रदूषित है","बहुत ठंडा है"],"explanationHi":"सीवेज जैसे कार्बनिक अपशिष्ट को विघटित करने वाले सूक्ष्मजीव घुली ऑक्सीजन का उपयोग कर लेते हैं, इसलिए उच्च BOD भारी कार्बनिक प्रदूषण और मछलियों के लिए कम बची ऑक्सीजन का संकेत देता है।"},
  {"id":"env-ecology-97","question":"Photochemical smog, typical of cities with heavy traffic and strong sunshine, contains mainly:","options":["Smoke, soot and sulphur dioxide mixed with fog","Methane and carbon dioxide","Chlorofluorocarbons from aerosols","Ozone, nitrogen oxides and PAN"],"answer":3,"explanation":"Sunlight drives reactions between nitrogen oxides and hydrocarbons from vehicle exhaust, producing ozone and PAN. Classical (London) smog was smoke and sulphur dioxide with fog.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"भारी यातायात और तेज़ धूप वाले शहरों में बनने वाले प्रकाश-रासायनिक धूम-कोहरे (फोटोकेमिकल स्मॉग) में मुख्यतः क्या होता है?","optionsHi":["कोहरे में मिला धुआँ, कालिख और सल्फर डाइऑक्साइड","मीथेन और कार्बन डाइऑक्साइड","एरोसोल से निकले क्लोरोफ्लोरोकार्बन","ओज़ोन, नाइट्रोजन ऑक्साइड और PAN"],"explanationHi":"सूर्य का प्रकाश वाहनों के धुएँ से निकले नाइट्रोजन ऑक्साइड और हाइड्रोकार्बन के बीच अभिक्रियाएँ कराता है, जिनसे ओज़ोन और PAN बनते हैं। परंपरागत (लंदन) स्मॉग कोहरे में मिला धुआँ और सल्फर डाइऑक्साइड था।"},
  {"id":"env-ecology-98","question":"The “ten per cent law” of energy transfer between trophic levels was proposed by:","options":["Raymond Lindeman","Charles Elton","Eugene Odum","Arthur G. Tansley"],"answer":0,"explanation":"Lindeman (1942) observed that only about 10% of energy passes to the next trophic level. Elton described the pyramid of numbers and Tansley coined the term “ecosystem”.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"पोषण स्तरों के बीच ऊर्जा स्थानांतरण के “दस प्रतिशत नियम” का प्रस्ताव किसने किया?","optionsHi":["रेमंड लिंडमैन","चार्ल्स एल्टन","यूजीन ओडम","आर्थर जी. टैन्सले"],"explanationHi":"लिंडमैन (1942) ने देखा कि केवल लगभग 10% ऊर्जा अगले पोषण स्तर तक पहुँचती है। एल्टन ने संख्या के पिरामिड का वर्णन किया और टैन्सले ने “पारिस्थितिकी तंत्र” शब्द गढ़ा।"},
  {"id":"env-ecology-99","question":"Fly ash, which is used to make bricks and cement, is a by-product of:","options":["Blast furnaces in integrated steel plants","Coal-based thermal power plants","Nuclear power plants","Cement kilns burning petcoke"],"answer":1,"explanation":"Burning pulverised coal leaves fine ash that is carried in flue gas; its safe use in bricks and cement reduces the need to dump it in ash ponds.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"फ्लाई ऐश, जिसका उपयोग ईंट और सीमेंट बनाने में होता है, किसका उप-उत्पाद है?","optionsHi":["एकीकृत इस्पात संयंत्रों की धमन भट्टियाँ","कोयला-आधारित ताप विद्युत संयंत्र","नाभिकीय विद्युत संयंत्र","पेटकोक जलाने वाली सीमेंट भट्टियाँ"],"explanationHi":"चूर्णित कोयले के जलने से महीन राख बचती है जो ग्रिप गैस के साथ बहती है; ईंट और सीमेंट में इसका सुरक्षित उपयोग इसे राख-तालाबों में फेंकने की आवश्यकता घटाता है।"},
  {"id":"env-ecology-100","question":"An orchid growing on the branch of a mango tree gets support and light without harming the tree. This relationship is:","options":["Parasitism","Mutualism","Commensalism","Protocooperation"],"answer":2,"explanation":"In commensalism one partner benefits while the other is unaffected. The orchid is an epiphyte, making its own food, not a parasite.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"आम के पेड़ की शाखा पर उगने वाला ऑर्किड पेड़ को हानि पहुँचाए बिना सहारा और प्रकाश पाता है। यह संबंध है:","optionsHi":["परजीविता","सहोपकारिता","सहभोजिता","प्रोटोकोऑपरेशन (आदि-सहयोग)"],"explanationHi":"सहभोजिता में एक साथी को लाभ होता है जबकि दूसरा अप्रभावित रहता है। ऑर्किड एक अधिपादप (एपिफाइट) है जो अपना भोजन स्वयं बनाता है, परजीवी नहीं है।"},
  {"id":"env-ecology-101","question":"In a tree-based ecosystem, where one large tree supports thousands of insects that are eaten by a few birds, the pyramid of numbers is:","options":["Upright, as in most grasslands","Rectangular, as each level matches","Absent","Inverted or spindle-shaped"],"answer":3,"explanation":"Because a single tree supports many herbivores, the base is narrow and the next level wide, giving an inverted (spindle-shaped) pyramid of numbers. The pyramid of energy is never inverted.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किसी वृक्ष-आधारित पारिस्थितिकी तंत्र में, जहाँ एक बड़ा वृक्ष हज़ारों कीटों को सहारा देता है जिन्हें कुछ पक्षी खाते हैं, संख्या का पिरामिड होता है:","optionsHi":["सीधा, जैसा अधिकांश घास के मैदानों में होता है","आयताकार, क्योंकि प्रत्येक स्तर समान होता है","अनुपस्थित","उलटा या तर्कु (स्पिंडल) के आकार का"],"explanationHi":"क्योंकि एक अकेला वृक्ष अनेक शाकाहारियों को सहारा देता है, आधार संकरा और अगला स्तर चौड़ा होता है, जिससे संख्या का उलटा (तर्कु-आकार का) पिरामिड बनता है। ऊर्जा का पिरामिड कभी उलटा नहीं होता।"},
  {"id":"env-ecology-102","question":"Chemical Oxygen Demand (COD) of a water sample is generally equal to or higher than its BOD because COD:","options":["Oxidises biodegradable and non-biodegradable matter","Is measured over a longer incubation period of 20 days","Measures only oxygen consumed by aerobic bacteria","Ignores organic matter altogether"],"answer":0,"explanation":"COD uses a strong chemical oxidant that oxidises almost all organic matter, while BOD counts only what microbes can break down, typically over 5 days; so COD ≥ BOD.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किसी जल नमूने की रासायनिक ऑक्सीजन माँग (COD) सामान्यतः उसकी BOD के बराबर या उससे अधिक होती है, क्योंकि COD:","optionsHi":["जैव-निम्नीकरणीय और अजैव-निम्नीकरणीय दोनों पदार्थों का ऑक्सीकरण करती है","20 दिनों की लंबी अंतःस्फुटन अवधि में मापी जाती है","केवल वायवीय जीवाणुओं द्वारा उपयोग की गई ऑक्सीजन मापती है","कार्बनिक पदार्थ को पूरी तरह अनदेखा करती है"],"explanationHi":"COD में एक प्रबल रासायनिक ऑक्सीकारक का उपयोग होता है जो लगभग सभी कार्बनिक पदार्थों का ऑक्सीकरण कर देता है, जबकि BOD केवल वही गिनती है जिसे सूक्ष्मजीव विघटित कर सकें, सामान्यतः 5 दिनों में; इसलिए COD ≥ BOD।"},
  {"id":"env-ecology-103","question":"A lichen is a classic example of which kind of interaction?","options":["Parasitism of a moss on tree bark","Mutualism between an alga and a fungus","Commensalism of a fungus on rock","Competition between mosses and algae for light"],"answer":1,"explanation":"The photosynthetic partner supplies food while the fungus gives shelter and absorbs water and minerals; both benefit, which is mutualism.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"लाइकेन किस प्रकार की अंतःक्रिया का उत्कृष्ट उदाहरण है?","optionsHi":["पेड़ की छाल पर काई की परजीविता","शैवाल और कवक के बीच सहोपकारिता","चट्टान पर कवक की सहभोजिता","प्रकाश के लिए काई और शैवाल के बीच प्रतिस्पर्धा"],"explanationHi":"प्रकाश-संश्लेषी साथी भोजन देता है जबकि कवक आश्रय देता है तथा जल और खनिज अवशोषित करता है; दोनों को लाभ होता है, यही सहोपकारिता है।"},
  {"id":"env-ecology-104","question":"The mould Penicillium releases a substance that kills nearby bacteria while the mould itself is not affected. This interaction is called:","options":["Mutualism","Commensalism","Amensalism","Parasitism"],"answer":2,"explanation":"In amensalism one species is harmed and the other is unaffected. In parasitism the harming partner also benefits by feeding on the host.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पेनिसिलियम फफूँद एक ऐसा पदार्थ छोड़ती है जो आस-पास के जीवाणुओं को मार देता है, जबकि फफूँद स्वयं अप्रभावित रहती है। इस अंतःक्रिया को कहते हैं:","optionsHi":["सहोपकारिता","सहभोजिता","अमेन्सलिज़्म (असहभोजिता)","परजीविता"],"explanationHi":"अमेन्सलिज़्म में एक प्रजाति को हानि होती है और दूसरी अप्रभावित रहती है। परजीविता में हानि पहुँचाने वाला साथी पोषक को खाकर स्वयं भी लाभ पाता है।"},
  {"id":"env-ecology-105","question":"Net primary productivity (NPP) of an ecosystem is:","options":["The total energy fixed by plants, including what they use in respiration","The energy stored in carnivores","Energy lost as heat at each level","Gross primary productivity minus the energy plants use in respiration"],"answer":3,"explanation":"NPP = GPP − R. It is the organic matter actually available to herbivores and decomposers.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किसी पारिस्थितिकी तंत्र की शुद्ध प्राथमिक उत्पादकता (NPP) है:","optionsHi":["पौधों द्वारा स्थिर की गई कुल ऊर्जा, जिसमें श्वसन में उपयोग की गई ऊर्जा भी शामिल है","मांसाहारियों में संचित ऊर्जा","प्रत्येक स्तर पर ऊष्मा के रूप में खोई ऊर्जा","सकल प्राथमिक उत्पादकता में से पौधों द्वारा श्वसन में उपयोग की गई ऊर्जा घटाने पर प्राप्त"],"explanationHi":"NPP = GPP − R। यह वह कार्बनिक पदार्थ है जो वास्तव में शाकाहारियों और अपघटकों को उपलब्ध होता है।"},
  {"id":"env-ecology-106","question":"A charismatic species such as the tiger or the giant panda, used to draw public support for conserving a whole habitat, is called a:","options":["Flagship species","Keystone species","Indicator species","Invasive species"],"answer":0,"explanation":"Flagship species are chosen for their public appeal; protecting them protects many other species sharing the habitat. A keystone species is defined by its outsized ecological role instead.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"बाघ या विशाल पांडा जैसी आकर्षक प्रजाति, जिसका उपयोग पूरे आवास के संरक्षण के लिए जन-समर्थन जुटाने में होता है, क्या कहलाती है?","optionsHi":["प्रमुख (फ्लैगशिप) प्रजाति","कीस्टोन प्रजाति","सूचक प्रजाति","आक्रामक प्रजाति"],"explanationHi":"फ्लैगशिप प्रजातियाँ अपनी जन-अपील के कारण चुनी जाती हैं; उनकी रक्षा से उसी आवास में रहने वाली अनेक अन्य प्रजातियों की भी रक्षा होती है। इसके विपरीत, कीस्टोन प्रजाति अपनी असाधारण पारिस्थितिक भूमिका से परिभाषित होती है।"},
  {"id":"env-ecology-107","question":"Which of these biogeochemical cycles has no significant gaseous phase in the atmosphere?","options":["Carbon cycle","Phosphorus cycle","Nitrogen cycle","Hydrological cycle"],"answer":1,"explanation":"Phosphorus moves mainly through rocks, soil, water and living things (a sedimentary cycle), so it is slow and often limits plant growth. Carbon, nitrogen and water all have a major atmospheric phase.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से किस जैव-भू-रासायनिक चक्र में वायुमंडल में कोई महत्वपूर्ण गैसीय प्रावस्था नहीं होती?","optionsHi":["कार्बन चक्र","फॉस्फोरस चक्र","नाइट्रोजन चक्र","जलीय (जल) चक्र"],"explanationHi":"फॉस्फोरस मुख्यतः चट्टानों, मिट्टी, जल और जीवित प्राणियों से होकर गुज़रता है (अवसादी चक्र), इसलिए यह धीमा होता है और प्रायः पौधों की वृद्धि को सीमित करता है। कार्बन, नाइट्रोजन और जल, तीनों की वायुमंडल में प्रमुख प्रावस्था होती है।"},
  {"id":"env-ecology-108","question":"The carrying capacity of an environment refers to:","options":["The number of species it can hold at equilibrium","The intrinsic rate at which a population grows when small","The largest population its resources can sustain","The total biomass its producers make in a year"],"answer":2,"explanation":"Population growth slows as it nears the carrying capacity (K) because food, space and other resources run short, giving the S-shaped logistic curve.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किसी पर्यावरण की धारण क्षमता (कैरिंग कैपेसिटी) से तात्पर्य है:","optionsHi":["संतुलन की स्थिति में उसमें रह सकने वाली प्रजातियों की संख्या","छोटी होने पर किसी आबादी के बढ़ने की आंतरिक दर","उसके संसाधनों द्वारा पोषित की जा सकने वाली सबसे बड़ी आबादी","उसके उत्पादकों द्वारा एक वर्ष में बनाया गया कुल जैवभार"],"explanationHi":"धारण क्षमता (K) के निकट पहुँचने पर आबादी की वृद्धि धीमी हो जाती है क्योंकि भोजन, स्थान और अन्य संसाधन कम पड़ने लगते हैं, जिससे S-आकार का लॉजिस्टिक वक्र बनता है।"},
  {"id":"env-ecology-109","question":"Species that produce very many offspring, give little parental care and thrive in unstable environments, such as many insects, are called:","options":["K-selected species","Keystone species","Endemic species","r-selected species"],"answer":3,"explanation":"r-selected species maximise reproductive rate (r). K-selected species, such as elephants and whales, have few young, long lives and heavy parental care.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"वे प्रजातियाँ जो बहुत अधिक संतानें उत्पन्न करती हैं, माता-पिता की देखभाल कम करती हैं और अस्थिर परिवेश में फलती-फूलती हैं, जैसे अनेक कीट, क्या कहलाती हैं?","optionsHi":["K-चयनित प्रजातियाँ","कीस्टोन प्रजातियाँ","स्थानिक प्रजातियाँ","r-चयनित प्रजातियाँ"],"explanationHi":"r-चयनित प्रजातियाँ प्रजनन दर (r) को अधिकतम करती हैं। हाथी और व्हेल जैसी K-चयनित प्रजातियों में कम संतानें, लंबा जीवन और माता-पिता की अधिक देखभाल होती है।"},
  {"id":"env-ecology-110","question":"The “ecological footprint” of a population measures:","options":["Land and water area needed for its consumption and wastes","Total carbon dioxide it emits in a year, in tonnes","The area of forests and parks it legally protects","The land it physically occupies with buildings, farms and roads"],"answer":0,"explanation":"The footprint is the bioproductive land and water needed to supply what a population consumes and absorb its wastes, in global hectares; the carbon footprint (tonnes of CO₂) is only one part of it.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किसी आबादी का “पारिस्थितिक पदचिह्न” किसे मापता है?","optionsHi":["उसकी खपत और अपशिष्टों के लिए आवश्यक भूमि और जल का क्षेत्रफल","एक वर्ष में उसके द्वारा उत्सर्जित कुल कार्बन डाइऑक्साइड, टन में","उसके द्वारा कानूनी रूप से संरक्षित वनों और उद्यानों का क्षेत्रफल","भवनों, खेतों और सड़कों से वह जितनी भूमि भौतिक रूप से घेरती है"],"explanationHi":"पदचिह्न वह जैव-उत्पादक भूमि और जल है जो किसी आबादी की खपत की आपूर्ति करने और उसके अपशिष्टों को सोखने के लिए आवश्यक है, जिसे वैश्विक हेक्टेयर में मापा जाता है; कार्बन पदचिह्न (CO₂ के टन) उसका केवल एक भाग है।"},
  {"id":"env-ecology-111","question":"In cryopreservation, seeds, gametes or tissues are stored for long periods at about:","options":["0 °C in a refrigerator","−196 °C in liquid nitrogen","−18 °C, the standard seed-bank cold store","4 °C in cold rooms"],"answer":1,"explanation":"At −196 °C, the temperature of liquid nitrogen, biological activity virtually stops, so genetic material can be preserved ex situ for decades. Conventional seed banks store dried seeds at about −18 °C, which is not cryopreservation.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"क्रायोप्रिज़र्वेशन में बीज, युग्मक या ऊतक लंबे समय तक लगभग किस तापमान पर संग्रहीत किए जाते हैं?","optionsHi":["रेफ्रिजरेटर में 0 °C","तरल नाइट्रोजन में −196 °C","−18 °C, मानक बीज-बैंक शीत भंडार","शीत कक्षों में 4 °C"],"explanationHi":"तरल नाइट्रोजन के तापमान −196 °C पर जैविक गतिविधि लगभग रुक जाती है, इसलिए आनुवंशिक पदार्थ को दशकों तक बहिःस्थाने संरक्षित किया जा सकता है। पारंपरिक बीज बैंक सूखे बीजों को लगभग −18 °C पर रखते हैं, जो क्रायोप्रिज़र्वेशन नहीं है।"},
  {"id":"env-ecology-112","question":"“Devrai” in Maharashtra, “Kavu” in Kerala, “Orans” in Rajasthan and “Law Kyntang” in Meghalaya are all names for:","options":["Traditional rainwater harvesting tanks","Plots cleared for shifting cultivation","Sacred groves protected by communities","Village community seed banks"],"answer":2,"explanation":"Sacred groves are patches of forest left untouched for religious reasons; they are a form of community-based in situ conservation and often shelter rare species.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"महाराष्ट्र में “देवराई”, केरल में “कावु”, राजस्थान में “ओरण” और मेघालय में “लॉ क्यंतांग” सभी किसके नाम हैं?","optionsHi":["वर्षा जल संचयन के पारंपरिक टैंक","स्थानांतरी कृषि के लिए साफ़ किए गए भूखंड","समुदायों द्वारा संरक्षित पवित्र उपवन","गाँवों के सामुदायिक बीज बैंक"],"explanationHi":"पवित्र उपवन धार्मिक कारणों से अछूते छोड़े गए वन-खंड हैं; ये समुदाय-आधारित स्वस्थाने संरक्षण का एक रूप हैं और प्रायः दुर्लभ प्रजातियों को आश्रय देते हैं।"},
  {"id":"env-ecology-113","question":"The most abundant greenhouse gas in the Earth's atmosphere is:","options":["Carbon dioxide","Methane","Nitrous oxide","Water vapour"],"answer":3,"explanation":"Water vapour contributes the most to the natural greenhouse effect, but its amount depends on temperature; carbon dioxide is the main gas whose rise from human activity drives warming.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पृथ्वी के वायुमंडल की सबसे प्रचुर हरितगृह गैस कौन-सी है?","optionsHi":["कार्बन डाइऑक्साइड","मीथेन","नाइट्रस ऑक्साइड","जलवाष्प"],"explanationHi":"प्राकृतिक हरितगृह प्रभाव में जलवाष्प का योगदान सबसे अधिक है, परंतु उसकी मात्रा तापमान पर निर्भर करती है; कार्बन डाइऑक्साइड वह मुख्य गैस है जिसकी मानवीय गतिविधियों से बढ़ती मात्रा तापन को बढ़ा रही है।"},
  {"id":"env-ecology-114","question":"In ecology, alpha diversity refers to:","options":["Species diversity within one habitat or community","Change in species composition between habitats","Total species diversity of a whole region","Genetic diversity within the members of one species"],"answer":0,"explanation":"Alpha diversity is within-habitat richness; beta diversity measures turnover between habitats; gamma diversity covers a whole landscape or region.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पारिस्थितिकी में अल्फा विविधता किसे कहते हैं?","optionsHi":["किसी एक आवास या समुदाय के भीतर प्रजाति विविधता","आवासों के बीच प्रजाति संघटन में परिवर्तन","किसी पूरे क्षेत्र की कुल प्रजाति विविधता","किसी एक प्रजाति के सदस्यों के भीतर आनुवंशिक विविधता"],"explanationHi":"अल्फा विविधता एक आवास के भीतर की समृद्धि है; बीटा विविधता आवासों के बीच परिवर्तन मापती है; गामा विविधता पूरे भू-दृश्य या क्षेत्र को समाहित करती है।"},
  {"id":"env-ecology-115","question":"Using plants such as sunflower or Indian mustard to absorb heavy metals from contaminated soil is called:","options":["Biomagnification","Phytoremediation","Eutrophication","Vermicomposting"],"answer":1,"explanation":"In phytoremediation plants take up, stabilise or break down pollutants. Biomagnification is the build-up of toxins along a food chain.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"सूरजमुखी या भारतीय सरसों जैसे पौधों द्वारा दूषित मिट्टी से भारी धातुओं को अवशोषित करना क्या कहलाता है?","optionsHi":["जैव आवर्धन","पादप-उपचार (फाइटोरेमेडिएशन)","सुपोषण (यूट्रोफिकेशन)","केंचुआ खाद निर्माण (वर्मीकम्पोस्टिंग)"],"explanationHi":"फाइटोरेमेडिएशन में पौधे प्रदूषकों को अवशोषित करते हैं, स्थिर करते हैं या विघटित करते हैं। जैव आवर्धन खाद्य श्रृंखला में विषैले पदार्थों का संचय है।"},
  {"id":"env-ecology-116","question":"Bioaccumulation, as distinct from biomagnification, refers to:","options":["Build-up of a toxin within one organism faster than it is excreted","Rise in a toxin's concentration from one trophic level to the next","Breakdown of toxins by soil bacteria into harmless forms","Spread of a toxin through groundwater to nearby wells"],"answer":0,"explanation":"Bioaccumulation happens within one organism, for example mercury building up in a fish as it ages; biomagnification is the increase in concentration along the food chain, as with DDT in fish-eating birds.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"जैव आवर्धन से भिन्न, जैव संचयन (बायोएक्युमुलेशन) से तात्पर्य है:","optionsHi":["किसी एक जीव के भीतर विषैले पदार्थ का उसके उत्सर्जन से अधिक तेज़ी से जमा होना","एक पोषण स्तर से अगले पोषण स्तर तक विषैले पदार्थ की सांद्रता का बढ़ना","मृदा जीवाणुओं द्वारा विषैले पदार्थों का हानिरहित रूपों में विघटन","भूजल के माध्यम से विषैले पदार्थ का आस-पास के कुओं तक फैलना"],"explanationHi":"जैव संचयन एक ही जीव के भीतर होता है, जैसे आयु बढ़ने के साथ मछली में पारे का जमा होना; जैव आवर्धन खाद्य श्रृंखला में सांद्रता का बढ़ना है, जैसे मछली खाने वाले पक्षियों में DDT।"},
  {"id":"env-ecology-117","question":"Under the principle of Extended Producer Responsibility (EPR) applied to plastic packaging and e-waste in India, producers are responsible for:","options":["Only the quality and safety of their products at the time of sale","Take-back and recycling or safe disposal of used products","Paying municipalities a flat tax in place of any collection duty","Manufacturing only biodegradable products from 2022 onwards"],"answer":1,"explanation":"EPR shifts part of the burden of end-of-life waste from municipalities to producers, importers and brand owners, who must meet collection and recycling targets.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत में प्लास्टिक पैकेजिंग और ई-अपशिष्ट पर लागू विस्तारित उत्पादक उत्तरदायित्व (EPR) के सिद्धांत के अंतर्गत उत्पादक किसके लिए उत्तरदायी होते हैं?","optionsHi":["केवल बिक्री के समय अपने उत्पादों की गुणवत्ता और सुरक्षा के लिए","प्रयुक्त उत्पादों को वापस लेने तथा उनके पुनर्चक्रण या सुरक्षित निपटान के लिए","संग्रहण के दायित्व के स्थान पर नगरपालिकाओं को एकमुश्त कर चुकाने के लिए","2022 से केवल जैव-निम्नीकरणीय उत्पाद बनाने के लिए"],"explanationHi":"EPR जीवन-अंत अपशिष्ट का कुछ भार नगरपालिकाओं से हटाकर उत्पादकों, आयातकों और ब्रांड स्वामियों पर डालता है, जिन्हें संग्रहण और पुनर्चक्रण के लक्ष्य पूरे करने होते हैं।"},
  {"id":"env-ecology-118","question":"How many of these statements about ecological pyramids are correct? I. The pyramid of energy is always upright. II. The pyramid of biomass can be inverted in some aquatic ecosystems. III. The pyramid of numbers can be inverted in a tree-based ecosystem. IV. In a pond, the pyramid of energy is usually inverted.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct; in the sea a small standing crop of fast-growing phytoplankton supports a larger biomass of zooplankton. Energy is lost at every transfer, so the energy pyramid can never be inverted; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पारिस्थितिक पिरामिडों के बारे में इनमें से कितने कथन सही हैं? I. ऊर्जा का पिरामिड सदैव सीधा होता है। II. जैवभार का पिरामिड कुछ जलीय पारिस्थितिकी तंत्रों में उलटा हो सकता है। III. वृक्ष-आधारित पारिस्थितिकी तंत्र में संख्या का पिरामिड उलटा हो सकता है। IV. तालाब में ऊर्जा का पिरामिड प्रायः उलटा होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं; समुद्र में तेज़ी से बढ़ने वाले पादपप्लवकों की छोटी खड़ी फसल जंतुप्लवकों के बड़े जैवभार को पोषित करती है। प्रत्येक स्थानांतरण पर ऊर्जा की हानि होती है, इसलिए ऊर्जा का पिरामिड कभी उलटा नहीं हो सकता; IV गलत है।"},
  {"id":"env-ecology-119","question":"Match the interaction with its effect on the two species (+ benefit, − harm, 0 no effect). A. Mutualism  B. Commensalism  C. Parasitism  D. Competition; 1. + / 0  2. + / −  3. + / +  4. − / −","options":["A-3, B-2, C-1, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"Mutualism helps both partners, commensalism helps one and leaves the other unaffected, parasitism helps the parasite at the host's cost, and competition harms both.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अंतःक्रिया का दोनों प्रजातियों पर उसके प्रभाव से मिलान कीजिए (+ लाभ, − हानि, 0 कोई प्रभाव नहीं)। A. सहोपकारिता  B. सहभोजिता  C. परजीविता  D. प्रतिस्पर्धा; 1. + / 0  2. + / −  3. + / +  4. − / −","optionsHi":["A-3, B-2, C-1, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"explanationHi":"सहोपकारिता में दोनों साथियों को लाभ होता है, सहभोजिता में एक को लाभ और दूसरा अप्रभावित रहता है, परजीविता में परजीवी को पोषक की कीमत पर लाभ होता है, और प्रतिस्पर्धा में दोनों को हानि होती है।"},
  {"id":"env-ecology-120","question":"Assertion (A): Fish-eating birds can carry much higher concentrations of DDT than the fish they eat. Reason (R): DDT is fat-soluble and is not easily broken down or excreted, so it accumulates and is passed up the food chain.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Each predator eats many contaminated prey and retains the DDT in its fat, so concentrations multiply at each level; this thinned eggshells and crashed populations of birds of prey.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): मछली खाने वाले पक्षियों में DDT की सांद्रता उनके द्वारा खाई जाने वाली मछलियों से कहीं अधिक हो सकती है। कारण (R): DDT वसा में घुलनशील है और आसानी से विघटित या उत्सर्जित नहीं होता, इसलिए यह संचित होकर खाद्य श्रृंखला में ऊपर की ओर पहुँचता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"प्रत्येक परभक्षी अनेक दूषित शिकार खाता है और DDT को अपनी वसा में रख लेता है, इसलिए प्रत्येक स्तर पर सांद्रता कई गुना हो जाती है; इससे अंडों के छिलके पतले हो गए और शिकारी पक्षियों की आबादी घट गई।"},
  {"id":"env-ecology-121","question":"How many of these statements about the nitrogen cycle are correct? I. Rhizobium in the root nodules of legumes fixes atmospheric nitrogen. II. Nitrosomonas converts ammonia into nitrite. III. Nitrobacter converts nitrite into nitrate. IV. Denitrifying bacteria convert nitrate into ammonia.","options":["Only one","Only two","All four","Only three"],"answer":3,"explanation":"I, II and III are correct. Denitrifying bacteria such as Pseudomonas reduce nitrate to nitrogen gas, returning it to the atmosphere, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"नाइट्रोजन चक्र के बारे में इनमें से कितने कथन सही हैं? I. फलीदार पौधों की जड़ ग्रंथिकाओं में राइज़ोबियम वायुमंडलीय नाइट्रोजन का स्थिरीकरण करता है। II. नाइट्रोसोमोनास अमोनिया को नाइट्राइट में बदलता है। III. नाइट्रोबैक्टर नाइट्राइट को नाइट्रेट में बदलता है। IV. विनाइट्रीकारी जीवाणु नाइट्रेट को अमोनिया में बदलते हैं।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"I, II और III सही हैं। सूडोमोनास जैसे विनाइट्रीकारी जीवाणु नाइट्रेट को नाइट्रोजन गैस में अपचयित करते हैं और उसे वायुमंडल में लौटा देते हैं, इसलिए IV गलत है।"},
  {"id":"env-ecology-122","question":"Arrange these stages of primary succession on bare rock in the order they appear: 1. Shrubs  2. Lichens  3. Grasses and herbs  4. Mosses","options":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"answer":0,"explanation":"Crustose lichens are the pioneers that start weathering rock; mosses follow on the thin soil, then grasses and herbs, then shrubs, and finally a climax forest.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"नंगी चट्टान पर प्राथमिक अनुक्रमण की इन अवस्थाओं को उनके प्रकट होने के क्रम में व्यवस्थित कीजिए: 1. झाड़ियाँ  2. लाइकेन  3. घास और शाक  4. काई","optionsHi":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"explanationHi":"क्रस्टोज़ लाइकेन अग्रगामी हैं जो चट्टान का अपक्षय शुरू करते हैं; पतली मिट्टी पर काई आती है, फिर घास और शाक, फिर झाड़ियाँ, और अंत में चरम (क्लाइमैक्स) वन।"},
  {"id":"env-ecology-123","question":"How many of the following are ex situ methods of conservation? I. Seed bank  II. Sacred grove  III. Biosphere reserve  IV. National park","options":["Only one","Only three","Only two","All four"],"answer":0,"explanation":"Only the seed bank keeps species outside their natural habitat, so it is ex situ. Sacred groves, biosphere reserves and national parks protect species where they naturally occur, so they are in situ.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितने संरक्षण की बहिःस्थाने (एक्स सीटू) विधियाँ हैं? I. बीज बैंक  II. पवित्र उपवन  III. जैवमंडल आरक्षित क्षेत्र  IV. राष्ट्रीय उद्यान","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"केवल बीज बैंक प्रजातियों को उनके प्राकृतिक आवास से बाहर रखता है, इसलिए वह बहिःस्थाने है। पवित्र उपवन, जैवमंडल आरक्षित क्षेत्र और राष्ट्रीय उद्यान प्रजातियों की रक्षा वहीं करते हैं जहाँ वे प्राकृतिक रूप से पाई जाती हैं, इसलिए वे स्वस्थाने हैं।"},
  {"id":"env-ecology-124","question":"Assertion (A): Lichens are useful indicators of air pollution. Reason (R): Many lichens are very sensitive to sulphur dioxide and disappear from heavily polluted areas.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Lichens absorb water and minerals directly from the air and cannot shed toxins, so their absence or decline around industrial towns signals SO₂ pollution.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): लाइकेन वायु प्रदूषण के उपयोगी सूचक हैं। कारण (R): अनेक लाइकेन सल्फर डाइऑक्साइड के प्रति अत्यंत संवेदनशील होते हैं और भारी प्रदूषित क्षेत्रों से लुप्त हो जाते हैं।","optionsHi":["A सही है, परंतु R गलत है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं और R, A की सही व्याख्या है","A गलत है, परंतु R सही है"],"explanationHi":"लाइकेन जल और खनिज सीधे वायु से अवशोषित करते हैं और विषैले पदार्थों को बाहर नहीं निकाल सकते, इसलिए औद्योगिक नगरों के आसपास उनकी अनुपस्थिति या कमी SO₂ प्रदूषण का संकेत देती है।"},
  {"id":"env-ecology-125","question":"How many of these statements about ozone are correct? I. Stratospheric ozone absorbs much of the Sun's harmful ultraviolet radiation. II. Ozone near the ground is a pollutant that harms lungs and crops. III. Ground-level ozone is a secondary pollutant formed from nitrogen oxides and volatile organic compounds in sunlight. IV. The largest seasonal ozone hole forms over the Arctic every year.","options":["Only three","Only one","Only two","All four"],"answer":0,"explanation":"I, II and III are correct. The large recurring ozone hole forms over Antarctica in the southern spring, helped by its very cold polar stratospheric clouds, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ओज़ोन के बारे में इनमें से कितने कथन सही हैं? I. समतापमंडलीय ओज़ोन सूर्य की हानिकारक पराबैंगनी विकिरण के बड़े भाग को अवशोषित करती है। II. धरातल के निकट की ओज़ोन एक प्रदूषक है जो फेफड़ों और फसलों को हानि पहुँचाती है। III. भू-स्तरीय ओज़ोन एक द्वितीयक प्रदूषक है जो सूर्य के प्रकाश में नाइट्रोजन ऑक्साइड और वाष्पशील कार्बनिक यौगिकों से बनती है। IV. सबसे बड़ा मौसमी ओज़ोन छिद्र प्रत्येक वर्ष आर्कटिक के ऊपर बनता है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। बड़ा आवर्ती ओज़ोन छिद्र दक्षिणी वसंत में अंटार्कटिका के ऊपर बनता है, जिसमें वहाँ के अत्यंत ठंडे ध्रुवीय समतापमंडलीय बादलों की भूमिका होती है, इसलिए IV गलत है।"},
  {"id":"env-ecology-126","question":"Match the pollutant with its source or effect. A. Carbon monoxide  B. Sulphur dioxide  C. Lead  D. Nitrogen oxides; 1. Binds to haemoglobin, reducing oxygen supply to tissues  2. Released mainly by burning coal, a major cause of acid rain  3. A neurotoxin once emitted widely from leaded petrol  4. Formed in high-temperature combustion in engines; a precursor of photochemical smog","options":["A-1, B-3, C-2, D-4","A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-1, B-2, C-4, D-3"],"answer":2,"explanation":"CO forms carboxyhaemoglobin; SO₂ from coal forms sulphuric acid in rain; lead harms the nervous system, especially in children, which is why leaded petrol was phased out; NOₓ from vehicles drives smog and ozone formation.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"प्रदूषक का उसके स्रोत या प्रभाव से मिलान कीजिए। A. कार्बन मोनोऑक्साइड  B. सल्फर डाइऑक्साइड  C. सीसा  D. नाइट्रोजन ऑक्साइड; 1. हीमोग्लोबिन से जुड़कर ऊतकों को ऑक्सीजन की आपूर्ति घटाती है  2. मुख्यतः कोयला जलाने से निकलती है, अम्ल वर्षा का प्रमुख कारण  3. एक तंत्रिका-विष जो कभी सीसायुक्त पेट्रोल से व्यापक रूप से उत्सर्जित होता था  4. इंजनों में उच्च तापमान पर दहन से बनती है; प्रकाश-रासायनिक धूम-कोहरे की पूर्वगामी","optionsHi":["A-1, B-3, C-2, D-4","A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-1, B-2, C-4, D-3"],"explanationHi":"CO कार्बोक्सीहीमोग्लोबिन बनाती है; कोयले से निकली SO₂ वर्षा में सल्फ्यूरिक अम्ल बनाती है; सीसा तंत्रिका तंत्र को, विशेषकर बच्चों में, हानि पहुँचाता है, इसीलिए सीसायुक्त पेट्रोल को चरणबद्ध ढंग से हटाया गया; वाहनों से निकली NOₓ धूम-कोहरे और ओज़ोन के निर्माण को बढ़ावा देती है।"},
  {"id":"env-ecology-127","question":"Arrange these biomes in decreasing order of average net primary productivity per unit area: 1. Desert  2. Tropical rainforest  3. Temperate grassland  4. Temperate deciduous forest","options":["2-3-4-1","4-2-3-1","2-4-1-3","2-4-3-1"],"answer":3,"explanation":"Warmth and moisture all year make tropical rainforests most productive, followed by temperate forests, then temperate grasslands; deserts, short of water, are the least productive.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन बायोमों को प्रति इकाई क्षेत्र औसत शुद्ध प्राथमिक उत्पादकता के घटते क्रम में व्यवस्थित कीजिए: 1. मरुस्थल  2. उष्णकटिबंधीय वर्षावन  3. शीतोष्ण घास का मैदान  4. शीतोष्ण पर्णपाती वन","optionsHi":["2-3-4-1","4-2-3-1","2-4-1-3","2-4-3-1"],"explanationHi":"पूरे वर्ष की गर्मी और नमी उष्णकटिबंधीय वर्षावनों को सबसे अधिक उत्पादक बनाती है, उसके बाद शीतोष्ण वन, फिर शीतोष्ण घास के मैदान आते हैं; जल की कमी के कारण मरुस्थल सबसे कम उत्पादक हैं।"},
  {"id":"env-ecology-128","question":"How many of these statements about mangroves are correct? I. Many mangroves have breathing roots (pneumatophores) that grow up out of the mud. II. Some mangrove species show vivipary, with seeds germinating while still on the parent tree. III. Mangroves tolerate saline, tidal water. IV. Mangroves are found mainly along tropical and subtropical coasts.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: mangroves have pneumatophores, some show vivipary, they tolerate saline tidal water, and they grow along tropical and subtropical coasts such as the Sundarbans and Bhitarkanika.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मैंग्रोव के बारे में इनमें से कितने कथन सही हैं? I. अनेक मैंग्रोव में श्वसन मूल (न्यूमेटोफोर) होती हैं जो कीचड़ से ऊपर निकलकर उगती हैं। II. कुछ मैंग्रोव प्रजातियों में जरायुजता (विविपैरी) दिखती है, जिसमें बीज मातृ वृक्ष पर ही अंकुरित हो जाते हैं। III. मैंग्रोव लवणीय, ज्वारीय जल को सहन करते हैं। IV. मैंग्रोव मुख्यतः उष्णकटिबंधीय और उपोष्णकटिबंधीय तटों पर पाए जाते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चारों सही हैं: मैंग्रोव में श्वसन मूल होती हैं, कुछ में जरायुजता दिखती है, वे लवणीय ज्वारीय जल को सहन करते हैं, और सुंदरबन तथा भितरकनिका जैसे उष्णकटिबंधीय और उपोष्णकटिबंधीय तटों पर उगते हैं।"},
  {"id":"env-ecology-129","question":"Assertion (A): Air quality in Delhi often worsens sharply on calm winter nights. Reason (R): A temperature inversion places warmer air above cooler surface air, preventing vertical mixing and trapping pollutants near the ground.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"With low wind and an inversion lid, emissions from vehicles, industry and crop-residue burning accumulate close to the ground; daytime heating breaks the inversion and lets them disperse.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): दिल्ली में शांत शीत रातों में वायु गुणवत्ता प्रायः तेज़ी से बिगड़ जाती है। कारण (R): तापमान व्युत्क्रमण (टेम्परेचर इनवर्शन) ठंडी सतही वायु के ऊपर गर्म वायु रख देता है, जो ऊर्ध्वाधर मिश्रण को रोकता है और प्रदूषकों को धरातल के निकट फँसा देता है।","optionsHi":["A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं और R, A की सही व्याख्या है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"कम हवा और व्युत्क्रमण के ढक्कन के कारण वाहनों, उद्योगों और फसल-अवशेष जलाने से निकला उत्सर्जन धरातल के निकट जमा हो जाता है; दिन में गर्मी व्युत्क्रमण को तोड़ देती है और प्रदूषक बिखर जाते हैं।"},
  {"id":"env-ecology-130","question":"Match the term with its meaning. A. Ecotone  B. Niche  C. Habitat  D. Edge effect; 1. The physical place where an organism lives  2. The functional role of a species, including the resources it uses  3. A transition zone between two communities  4. The tendency for a transition zone to have greater variety and density of species","options":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1"],"answer":0,"explanation":"A habitat is an address, a niche a profession. Ecotones such as forest edges or estuaries often hold species from both sides plus their own, which is the edge effect.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"शब्द का उसके अर्थ से मिलान कीजिए। A. इकोटोन (संक्रमण क्षेत्र)  B. निकेत  C. आवास  D. कोर/किनारा प्रभाव (एज इफेक्ट); 1. वह भौतिक स्थान जहाँ कोई जीव रहता है  2. किसी प्रजाति की कार्यात्मक भूमिका, जिसमें उसके द्वारा उपयोग किए जाने वाले संसाधन भी शामिल हैं  3. दो समुदायों के बीच का संक्रमण क्षेत्र  4. संक्रमण क्षेत्र में प्रजातियों की अधिक विविधता और घनत्व होने की प्रवृत्ति","optionsHi":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1"],"explanationHi":"आवास पता है, निकेत व्यवसाय। वन के किनारे या मुहाने जैसे इकोटोन में प्रायः दोनों ओर की प्रजातियाँ और उनकी अपनी प्रजातियाँ भी होती हैं, यही किनारा प्रभाव (एज इफेक्ट) है।"},
  {"id":"env-ecology-131","question":"How many of these statements about greenhouse gases are correct? I. Per kilogram, methane traps far more heat than carbon dioxide over a 100-year period. II. Nitrous oxide is released from fertilised agricultural soils. III. HFCs do not deplete the ozone layer but are powerful greenhouse gases. IV. CFCs deplete ozone and are also potent greenhouse gases.","options":["Only one","Only three","Only two","All four"],"answer":3,"explanation":"All four are correct: methane traps far more heat per kilogram than CO₂; fertilised soils release N₂O; HFCs spare ozone but are strong greenhouse gases (phased down under Kigali); and CFCs both deplete ozone and warm the climate.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"हरितगृह गैसों के बारे में इनमें से कितने कथन सही हैं? I. प्रति किलोग्राम, मीथेन 100 वर्ष की अवधि में कार्बन डाइऑक्साइड की तुलना में कहीं अधिक ऊष्मा रोकती है। II. नाइट्रस ऑक्साइड उर्वरित कृषि मिट्टी से निकलती है। III. HFCs ओज़ोन परत को क्षीण नहीं करते, परंतु शक्तिशाली हरितगृह गैसें हैं। IV. CFCs ओज़ोन को क्षीण करते हैं और प्रबल हरितगृह गैसें भी हैं।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"सभी चारों सही हैं: मीथेन प्रति किलोग्राम CO₂ से कहीं अधिक ऊष्मा रोकती है; उर्वरित मिट्टी N₂O छोड़ती है; HFCs ओज़ोन को बख़्श देते हैं पर प्रबल हरितगृह गैसें हैं (किगाली के अंतर्गत इन्हें घटाया जा रहा है); और CFCs ओज़ोन को क्षीण भी करते हैं और जलवायु को गर्म भी करते हैं।"},
  {"id":"env-ecology-132","question":"Arrange these international environmental conferences in chronological order: 1. Rio Earth Summit (UN Conference on Environment and Development)  2. Stockholm Conference on the Human Environment  3. World Summit on Sustainable Development, Johannesburg  4. Rio+20 Conference on Sustainable Development","options":["1-2-3-4","2-3-1-4","2-1-3-4","2-1-4-3"],"answer":2,"explanation":"Stockholm was held in 1972 (and led to UNEP), the Rio Earth Summit in 1992, Johannesburg in 2002 and Rio+20 in 2012.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन अंतरराष्ट्रीय पर्यावरण सम्मेलनों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. रियो पृथ्वी शिखर सम्मेलन (पर्यावरण और विकास पर संयुक्त राष्ट्र सम्मेलन)  2. मानव पर्यावरण पर स्टॉकहोम सम्मेलन  3. सतत विकास पर विश्व शिखर सम्मेलन, जोहानिसबर्ग  4. सतत विकास पर रियो+20 सम्मेलन","optionsHi":["1-2-3-4","2-3-1-4","2-1-3-4","2-1-4-3"],"explanationHi":"स्टॉकहोम 1972 में हुआ (जिससे UNEP बना), रियो पृथ्वी शिखर सम्मेलन 1992 में, जोहानिसबर्ग 2002 में और रियो+20 2012 में।"},
  {"id":"env-ecology-133","question":"Assertion (A): Invasive plants such as water hyacinth can choke lakes and rivers in India. Reason (R): In a new region they often lack natural enemies and spread rapidly, crowding out native species.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Water hyacinth, a South American plant, forms dense mats that block light and deplete oxygen; freed from its native herbivores, it multiplies unchecked.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): जलकुंभी जैसे आक्रामक पौधे भारत में झीलों और नदियों को अवरुद्ध कर सकते हैं। कारण (R): नए क्षेत्र में उनके प्रायः प्राकृतिक शत्रु नहीं होते और वे तेज़ी से फैलकर स्थानीय प्रजातियों को दबा देते हैं।","optionsHi":["A सही है, परंतु R गलत है","A गलत है, परंतु R सही है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं और R, A की सही व्याख्या है"],"explanationHi":"जलकुंभी, एक दक्षिण अमेरिकी पौधा, घनी परतें बनाती है जो प्रकाश को रोकती हैं और ऑक्सीजन घटाती हैं; अपने मूल शाकाहारियों से मुक्त होकर यह अनियंत्रित रूप से बढ़ती है।"},
  {"id":"env-ecology-134","question":"How many of these statements about plastic pollution are correct? I. India banned a list of identified single-use plastic items from 1 July 2022. II. Extended Producer Responsibility makes brand owners responsible for collecting their plastic packaging. III. Microplastics are plastic particles smaller than 5 mm. IV. Many plastics labelled biodegradable break down fully only under industrial composting conditions.","options":["Only three","Only one","Only two","All four"],"answer":3,"explanation":"All four are correct: identified single-use items were banned from 1 July 2022, EPR makes brand owners collect packaging, microplastics are under 5 mm, and many 'biodegradable' plastics need industrial composting to break down.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"प्लास्टिक प्रदूषण के बारे में इनमें से कितने कथन सही हैं? I. भारत ने 1 जुलाई 2022 से चिह्नित एकल-उपयोग प्लास्टिक वस्तुओं की एक सूची पर प्रतिबंध लगाया। II. विस्तारित उत्पादक उत्तरदायित्व ब्रांड स्वामियों को अपनी प्लास्टिक पैकेजिंग के संग्रहण के लिए उत्तरदायी बनाता है। III. माइक्रोप्लास्टिक 5 mm से छोटे प्लास्टिक कण होते हैं। IV. जैव-निम्नीकरणीय के रूप में लेबल किए गए अनेक प्लास्टिक केवल औद्योगिक खाद-निर्माण (कम्पोस्टिंग) की परिस्थितियों में ही पूरी तरह विघटित होते हैं।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"सभी चारों सही हैं: चिह्नित एकल-उपयोग वस्तुओं पर 1 जुलाई 2022 से प्रतिबंध लगा, EPR ब्रांड स्वामियों से पैकेजिंग एकत्र कराता है, माइक्रोप्लास्टिक 5 mm से कम के होते हैं, और अनेक 'जैव-निम्नीकरणीय' प्लास्टिक को विघटित होने के लिए औद्योगिक कम्पोस्टिंग चाहिए।"},
  {"id":"env-ecology-135","question":"Match the body with the law under which it was set up. A. Central Pollution Control Board  B. National Tiger Conservation Authority  C. National Green Tribunal  D. National Biodiversity Authority; 1. Biological Diversity Act, 2002  2. National Green Tribunal Act, 2010  3. Wildlife (Protection) Act, 1972, as amended in 2006  4. Water (Prevention and Control of Pollution) Act, 1974","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"The CPCB was constituted under the Water Act of 1974 and later given Air Act functions; the NTCA came through the 2006 amendment of the Wildlife Act; the NGT has its own Act of 2010; the NBA, in Chennai, was set up under the Biological Diversity Act.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निकाय का उस कानून से मिलान कीजिए जिसके अंतर्गत वह गठित हुआ। A. केंद्रीय प्रदूषण नियंत्रण बोर्ड  B. राष्ट्रीय बाघ संरक्षण प्राधिकरण  C. राष्ट्रीय हरित अधिकरण  D. राष्ट्रीय जैव विविधता प्राधिकरण; 1. जैविक विविधता अधिनियम, 2002  2. राष्ट्रीय हरित अधिकरण अधिनियम, 2010  3. वन्यजीव (संरक्षण) अधिनियम, 1972, 2006 में यथासंशोधित  4. जल (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1974","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"CPCB का गठन 1974 के जल अधिनियम के अंतर्गत हुआ और बाद में उसे वायु अधिनियम के कार्य भी दिए गए; NTCA वन्यजीव अधिनियम के 2006 के संशोधन से आया; NGT का अपना 2010 का अधिनियम है; चेन्नई स्थित NBA की स्थापना जैविक विविधता अधिनियम के अंतर्गत हुई।"},
  {"id":"env-ecology-136","question":"Consider the following statements about productivity in an ecosystem: 1. Net primary productivity equals gross primary productivity minus the energy used by producers in respiration. 2. Secondary productivity is the rate at which consumers form new organic matter. 3. In a mature climax forest, the net productivity of the whole community tends towards zero. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three hold: NPP = GPP − R of producers; secondary productivity is consumer production; at climax total community respiration nearly balances GPP, so net ecosystem productivity approaches zero even though NPP itself is still positive.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पारिस्थितिकी तंत्र में उत्पादकता के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. शुद्ध प्राथमिक उत्पादकता, सकल प्राथमिक उत्पादकता में से उत्पादकों द्वारा श्वसन में उपयोग की गई ऊर्जा घटाने के बराबर होती है। 2. द्वितीयक उत्पादकता वह दर है जिस पर उपभोक्ता नया कार्बनिक पदार्थ बनाते हैं। 3. एक परिपक्व चरम (क्लाइमैक्स) वन में पूरे समुदाय की शुद्ध उत्पादकता शून्य की ओर प्रवृत्त होती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं: NPP = GPP − उत्पादकों का R; द्वितीयक उत्पादकता उपभोक्ताओं का उत्पादन है; चरम अवस्था में पूरे समुदाय का कुल श्वसन GPP के लगभग बराबर हो जाता है, इसलिए शुद्ध पारिस्थितिकी तंत्र उत्पादकता शून्य के निकट पहुँचती है, भले ही NPP स्वयं धनात्मक रहे।"},
  {"id":"env-ecology-137","question":"The open ocean covers most of the Earth's surface yet has a low net primary productivity per unit area. The main reason is that its sunlit surface waters are:","options":["Too poorly lit for photosynthesis by phytoplankton","Short of nutrients like nitrate, phosphate and iron","Short of dissolved carbon dioxide for photosynthesis","Too cold throughout the year for algal growth"],"answer":1,"explanation":"Light is ample in the surface layer and dissolved inorganic carbon is plentiful; productivity is limited because nutrients sink below the sunlit zone, which is why upwelling zones and coasts are far more productive.","difficulty":"hard","source":"UPSC Prelims","questionHi":"खुला महासागर पृथ्वी की अधिकांश सतह को ढकता है, फिर भी उसकी प्रति इकाई क्षेत्र शुद्ध प्राथमिक उत्पादकता कम है। इसका मुख्य कारण यह है कि उसके प्रकाशित सतही जल में:","optionsHi":["पादपप्लवकों द्वारा प्रकाश-संश्लेषण के लिए बहुत कम प्रकाश है","नाइट्रेट, फॉस्फेट और लोहे जैसे पोषक तत्वों की कमी है","प्रकाश-संश्लेषण के लिए घुली कार्बन डाइऑक्साइड की कमी है","शैवाल की वृद्धि के लिए पूरे वर्ष बहुत ठंड रहती है"],"explanationHi":"सतही परत में प्रकाश प्रचुर है और घुला अकार्बनिक कार्बन भी भरपूर है; उत्पादकता इसलिए सीमित है क्योंकि पोषक तत्व प्रकाशित क्षेत्र से नीचे डूब जाते हैं, इसीलिए उत्स्रवण (अपवेलिंग) क्षेत्र और तट कहीं अधिक उत्पादक होते हैं।"},
  {"id":"env-ecology-138","question":"In a lake, the standing biomass of phytoplankton measured at one moment is smaller than that of the zooplankton that graze on it. This is possible because:","options":["Zooplankton are partly autotrophic and make some of their own food","In aquatic systems more energy reaches each higher trophic level","Phytoplankton reproduce fast, so a small standing crop feeds many","The pyramid of energy in such lakes is also inverted, as with biomass"],"answer":2,"explanation":"Biomass is a snapshot; fast turnover lets a small phytoplankton stock support a larger zooplankton stock. Energy flow over time still decreases upward, so the energy pyramid stays upright.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किसी झील में किसी क्षण मापा गया पादपप्लवकों का खड़ा जैवभार उन्हें चरने वाले जंतुप्लवकों के जैवभार से कम होता है। यह इसलिए संभव है क्योंकि:","optionsHi":["जंतुप्लवक आंशिक रूप से स्वपोषी होते हैं और अपना कुछ भोजन स्वयं बनाते हैं","जलीय तंत्रों में प्रत्येक उच्चतर पोषण स्तर तक अधिक ऊर्जा पहुँचती है","पादपप्लवक तेज़ी से प्रजनन करते हैं, इसलिए छोटी खड़ी फसल अनेक को पोषित करती है","ऐसी झीलों में ऊर्जा का पिरामिड भी जैवभार की तरह उलटा होता है"],"explanationHi":"जैवभार एक क्षणिक चित्र है; तेज़ आवर्तन के कारण पादपप्लवकों का छोटा भंडार जंतुप्लवकों के बड़े भंडार को सहारा दे सकता है। समय के साथ ऊर्जा प्रवाह ऊपर की ओर फिर भी घटता है, इसलिए ऊर्जा का पिरामिड सीधा रहता है।"},
  {"id":"env-ecology-139","question":"A grassland receives 2,000,000 J of sunlight and its producers convert 1 per cent of it into net primary production. If 10 per cent of the energy passes from one trophic level to the next, how much energy reaches the secondary consumers?","options":["2,000 J","20 J","20,000 J","200 J"],"answer":3,"explanation":"NPP = 20,000 J; primary consumers get 2,000 J; secondary consumers get 200 J. 2,000 J is the herbivore level and 20 J the tertiary level.","difficulty":"moderate","source":"UPSC Prelims · CDS","questionHi":"किसी घास के मैदान को 2,000,000 J सूर्य का प्रकाश प्राप्त होता है और उसके उत्पादक उसका 1 प्रतिशत शुद्ध प्राथमिक उत्पादन में बदल देते हैं। यदि ऊर्जा का 10 प्रतिशत एक पोषण स्तर से अगले में जाता है, तो द्वितीयक उपभोक्ताओं तक कितनी ऊर्जा पहुँचती है?","optionsHi":["2,000 J","20 J","20,000 J","200 J"],"explanationHi":"NPP = 20,000 J; प्राथमिक उपभोक्ताओं को 2,000 J मिलती है; द्वितीयक उपभोक्ताओं को 200 J मिलती है। 2,000 J शाकाहारी स्तर की और 20 J तृतीयक स्तर की ऊर्जा है।"},
  {"id":"env-ecology-140","question":"Consider the following statements about food chains: 1. In many forests, more energy flows through the detritus food chain than through the grazing food chain. 2. The detritus food chain begins with dead organic matter and its decomposers are mainly fungi and bacteria. 3. The detritus and grazing food chains are entirely separate, with no organism common to both. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Most forest NPP is never eaten alive and enters the detritus chain; the two chains are linked because animals of the grazing chain die into detritus and some detritivores are eaten by grazing-chain predators.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"खाद्य श्रृंखलाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. अनेक वनों में चारण खाद्य श्रृंखला की अपेक्षा अपरद खाद्य श्रृंखला से अधिक ऊर्जा प्रवाहित होती है। 2. अपरद खाद्य श्रृंखला मृत कार्बनिक पदार्थ से शुरू होती है और उसके अपघटक मुख्यतः कवक और जीवाणु होते हैं। 3. अपरद और चारण खाद्य श्रृंखलाएँ पूरी तरह पृथक हैं, उनमें कोई जीव दोनों में उभयनिष्ठ नहीं है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"वनों का अधिकांश NPP जीवित अवस्था में कभी खाया नहीं जाता और अपरद श्रृंखला में चला जाता है; दोनों श्रृंखलाएँ जुड़ी हुई हैं क्योंकि चारण श्रृंखला के जंतु मरकर अपरद बन जाते हैं और कुछ अपरदभक्षी चारण श्रृंखला के परभक्षियों द्वारा खाए जाते हैं।"},
  {"id":"env-ecology-141","question":"Consider the following statements about decomposition of leaf litter: 1. Litter rich in lignin and chitin decomposes more slowly than litter rich in nitrogen and water-soluble sugars. 2. Waterlogged, oxygen-poor conditions speed up decomposition. 3. Leaching carries water-soluble inorganic nutrients from the detritus down into the soil. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Lignin and chitin are resistant while nitrogen-rich, sugary litter breaks down fast; anaerobic waterlogging slows decomposition, which is why peat builds up in bogs.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पत्ती-कचरे (लीफ लिटर) के अपघटन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. लिग्निन और काइटिन से समृद्ध कचरा नाइट्रोजन और जल-विलेय शर्कराओं से समृद्ध कचरे की तुलना में अधिक धीरे अपघटित होता है। 2. जलमग्न, ऑक्सीजन-रहित परिस्थितियाँ अपघटन को तेज़ करती हैं। 3. निक्षालन (लीचिंग) अपरद से जल-विलेय अकार्बनिक पोषक तत्वों को नीचे मिट्टी में ले जाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"लिग्निन और काइटिन प्रतिरोधी होते हैं जबकि नाइट्रोजन-समृद्ध, शर्करायुक्त कचरा तेज़ी से विघटित होता है; अवायवीय जलभराव अपघटन को धीमा करता है, इसीलिए दलदलों में पीट जमा होती है।"},
  {"id":"env-ecology-142","question":"With reference to ecosystem terms, consider the following statements: 1. 'Standing crop' is the mass of living material present at a trophic level at a particular time. 2. 'Standing state' is the amount of inorganic nutrients present in the soil at a particular time. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both definitions are correct: standing crop is living biomass at a level, and standing state is the stock of nutrients such as N, P and Ca held in the soil at a given time.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पारिस्थितिकी तंत्र की शब्दावली के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए: 1. 'खड़ी फसल' (स्टैंडिंग क्रॉप) किसी विशेष समय पर किसी पोषण स्तर में उपस्थित जीवित पदार्थ का द्रव्यमान है। 2. 'खड़ी अवस्था' (स्टैंडिंग स्टेट) किसी विशेष समय पर मिट्टी में उपस्थित अकार्बनिक पोषक तत्वों की मात्रा है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों परिभाषाएँ सही हैं: खड़ी फसल किसी स्तर का जीवित जैवभार है, और खड़ी अवस्था किसी समय मिट्टी में संचित N, P और Ca जैसे पोषक तत्वों का भंडार है।"},
  {"id":"env-ecology-143","question":"Consider the following statements: 1. Photosynthetically active radiation makes up less than half of the solar radiation reaching the Earth's surface. 2. Green plants capture only a small fraction, of the order of 2–10 per cent, of the photosynthetically active radiation. 3. Energy flow in an ecosystem is cyclic, because decomposers return energy to the producers. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 3 only","2 and 3 only","1 and 2 only"],"answer":3,"explanation":"Nutrients cycle but energy flows one way and leaves as heat; decomposers release energy in respiration rather than handing it back to plants.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. प्रकाश-संश्लेषणात्मक सक्रिय विकिरण पृथ्वी की सतह तक पहुँचने वाले सौर विकिरण के आधे से भी कम होता है। 2. हरे पौधे प्रकाश-संश्लेषणात्मक सक्रिय विकिरण का केवल एक छोटा अंश, लगभग 2–10 प्रतिशत, ग्रहण करते हैं। 3. पारिस्थितिकी तंत्र में ऊर्जा प्रवाह चक्रीय होता है, क्योंकि अपघटक ऊर्जा को उत्पादकों को लौटा देते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 1 और 3","केवल 2 और 3","केवल 1 और 2"],"explanationHi":"पोषक तत्व चक्रित होते हैं, परंतु ऊर्जा एक ही दिशा में प्रवाहित होती है और ऊष्मा के रूप में बाहर चली जाती है; अपघटक ऊर्जा को पौधों को लौटाने के बजाय श्वसन में मुक्त करते हैं।"},
  {"id":"env-ecology-144","question":"Assertion (A): A complex food web is generally more stable than a single, simple food chain. Reason (R): In a food web, when one food source declines, consumers can switch to alternative prey. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Multiple feeding links give alternative pathways for energy, so the loss of one species does not collapse the whole system; that redundancy is exactly why webs are more stable.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अभिकथन (A): एक जटिल खाद्य जाल सामान्यतः किसी एकल, सरल खाद्य श्रृंखला की तुलना में अधिक स्थायी होता है। कारण (R): खाद्य जाल में, जब एक भोजन स्रोत घटता है, तो उपभोक्ता वैकल्पिक शिकार की ओर मुड़ सकते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"अनेक आहार संबंध ऊर्जा के लिए वैकल्पिक मार्ग देते हैं, इसलिए एक प्रजाति के लुप्त होने से पूरा तंत्र नहीं ढहता; यही अतिरिक्तता (रिडंडेंसी) जालों को अधिक स्थायी बनाती है।"},
  {"id":"env-ecology-145","question":"Consider the following statements: 1. A single species can occupy more than one trophic level in the same ecosystem at the same time. 2. A trophic level refers to a particular species rather than to a functional feeding position. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"A trophic level is a functional position, not a species; an omnivore such as a bear eating berries and fish is a primary and a higher consumer at once, so statement 2 is wrong.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. एक ही प्रजाति एक ही पारिस्थितिकी तंत्र में एक साथ एक से अधिक पोषण स्तर पर हो सकती है। 2. पोषण स्तर किसी कार्यात्मक आहार स्थिति के बजाय किसी विशेष प्रजाति को दर्शाता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"पोषण स्तर एक कार्यात्मक स्थिति है, प्रजाति नहीं; बेरी और मछली खाने वाला भालू जैसा सर्वाहारी एक ही समय में प्राथमिक और उच्चतर उपभोक्ता होता है, इसलिए कथन 2 गलत है।"},
  {"id":"env-ecology-146","question":"Food chains in nature rarely have more than four or five links. The main reason is that:","options":["Top predators would become too large to find enough space","Nutrients are not recycled to the higher trophic levels","Biomagnified poisons kill every predator above the fourth level","So much energy is lost at each transfer that too little remains"],"answer":3,"explanation":"Roughly 90 per cent of energy is lost as heat and in respiration at each step, so beyond four or five levels too little energy remains to sustain a viable population. Biomagnification harms top predators but does not set the length of food chains.","difficulty":"moderate","source":"UPSC Prelims · CDS","questionHi":"प्रकृति में खाद्य श्रृंखलाओं में शायद ही कभी चार या पाँच से अधिक कड़ियाँ होती हैं। इसका मुख्य कारण यह है कि:","optionsHi":["शीर्ष परभक्षी इतने बड़े हो जाएँगे कि उन्हें पर्याप्त स्थान नहीं मिलेगा","पोषक तत्व उच्चतर पोषण स्तरों तक पुनर्चक्रित नहीं होते","जैव आवर्धित विष चौथे स्तर से ऊपर के प्रत्येक परभक्षी को मार देते हैं","प्रत्येक स्थानांतरण पर इतनी अधिक ऊर्जा खो जाती है कि बहुत कम शेष रहती है"],"explanationHi":"प्रत्येक चरण पर लगभग 90 प्रतिशत ऊर्जा ऊष्मा के रूप में और श्वसन में खो जाती है, इसलिए चार या पाँच स्तरों के बाद किसी व्यवहार्य आबादी को पोषित करने लायक ऊर्जा नहीं बचती। जैव आवर्धन शीर्ष परभक्षियों को हानि पहुँचाता है, पर खाद्य श्रृंखलाओं की लंबाई तय नहीं करता।"},
  {"id":"env-ecology-147","question":"Which of the following are recognised limitations of ecological pyramids? 1. They do not account for the same species belonging to two or more trophic levels. 2. They give no place to saprophytes, even though these play a vital role in the ecosystem. 3. They assume a simple food chain, which seldom exists in nature. Select the correct answer.","options":["1 only","2 only","1, 2 and 3","1 and 3 only"],"answer":2,"explanation":"All three are standard limitations: pyramids ignore species spanning levels, leave out decomposers and saprophytes, and assume a linear chain rather than a web.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी पारिस्थितिक पिरामिडों की मान्य सीमाएँ हैं? 1. वे एक ही प्रजाति के दो या अधिक पोषण स्तरों से संबंधित होने का ध्यान नहीं रखते। 2. वे मृतोपजीवियों को कोई स्थान नहीं देते, जबकि पारिस्थितिकी तंत्र में उनकी महत्वपूर्ण भूमिका होती है। 3. वे एक सरल खाद्य श्रृंखला मानते हैं, जो प्रकृति में बहुत कम होती है। सही उत्तर चुनिए।","optionsHi":["केवल 1","केवल 2","1, 2 और 3","केवल 1 और 3"],"explanationHi":"तीनों मानक सीमाएँ हैं: पिरामिड कई स्तरों में फैली प्रजातियों की उपेक्षा करते हैं, अपघटकों और मृतोपजीवियों को छोड़ देते हैं, और जाल के बजाय रैखिक श्रृंखला मान लेते हैं।"},
  {"id":"env-ecology-148","question":"A pyramid of biomass can be inverted, but a pyramid of energy cannot. Which of the following best explains the difference?","options":["Biomass is a one-time snapshot; energy is a flow that must fall each level","Energy is measured as dry weight per area, while biomass is measured in joules","Decomposers are counted only in the pyramid of energy, not biomass","The pyramid of biomass leaves out the producers at its base"],"answer":0,"explanation":"Fast-turnover producers can have small standing biomass, but energy passed per unit time must fall at each level because of respiratory losses, so the energy pyramid is always upright.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैवभार का पिरामिड उलटा हो सकता है, परंतु ऊर्जा का पिरामिड नहीं। निम्नलिखित में से कौन-सा कथन इस अंतर की सबसे अच्छी व्याख्या करता है?","optionsHi":["जैवभार एक बार का क्षणिक चित्र है; ऊर्जा एक प्रवाह है जो प्रत्येक स्तर पर घटनी ही चाहिए","ऊर्जा प्रति क्षेत्र शुष्क भार के रूप में मापी जाती है, जबकि जैवभार जूल में मापा जाता है","अपघटक केवल ऊर्जा के पिरामिड में गिने जाते हैं, जैवभार में नहीं","जैवभार का पिरामिड अपने आधार पर उत्पादकों को छोड़ देता है"],"explanationHi":"तेज़ आवर्तन वाले उत्पादकों का खड़ा जैवभार कम हो सकता है, परंतु श्वसन हानियों के कारण प्रति इकाई समय स्थानांतरित ऊर्जा प्रत्येक स्तर पर घटनी ही है, इसलिए ऊर्जा का पिरामिड सदा सीधा रहता है।"},
  {"id":"env-ecology-149","question":"Consider the following statements: 1. According to Gause's principle, two species competing for the same limiting resource cannot coexist indefinitely. 2. Resource partitioning, such as related warblers feeding in different parts of the same tree, can allow similar species to coexist. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Competitive exclusion predicts that the inferior competitor is eliminated, unless the species divide the resource, as MacArthur showed for warblers foraging in different parts of a tree.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. गॉज़ के सिद्धांत के अनुसार, एक ही सीमित संसाधन के लिए प्रतिस्पर्धा करने वाली दो प्रजातियाँ अनिश्चित काल तक सह-अस्तित्व में नहीं रह सकतीं। 2. संसाधन विभाजन, जैसे एक ही वृक्ष के अलग-अलग भागों में भोजन ढूँढने वाली संबंधित वार्बलर चिड़ियाँ, समान प्रजातियों को सह-अस्तित्व में रहने दे सकता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"प्रतिस्पर्धी अपवर्जन के अनुसार कमज़ोर प्रतिस्पर्धी समाप्त हो जाता है, जब तक कि प्रजातियाँ संसाधन को बाँट न लें, जैसा मैकआर्थर ने वृक्ष के अलग-अलग भागों में भोजन खोजने वाली वार्बलरों के लिए दिखाया।"},
  {"id":"env-ecology-150","question":"In the classification of ecosystem services used by the Millennium Ecosystem Assessment, soil formation and nutrient cycling fall under:","options":["Regulating services","Supporting services","Provisioning services","Cultural services"],"answer":1,"explanation":"Supporting services underpin all others; regulating services include climate regulation and pollination, provisioning covers goods such as food and timber, and cultural covers recreation and spiritual value.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मिलेनियम इकोसिस्टम असेसमेंट द्वारा प्रयुक्त पारिस्थितिकी तंत्र सेवाओं के वर्गीकरण में मृदा निर्माण और पोषक चक्रण किसके अंतर्गत आते हैं?","optionsHi":["विनियमन सेवाएँ","सहायक सेवाएँ","प्रावधान सेवाएँ","सांस्कृतिक सेवाएँ"],"explanationHi":"सहायक सेवाएँ अन्य सभी का आधार हैं; विनियमन सेवाओं में जलवायु विनियमन और परागण शामिल हैं, प्रावधान सेवाओं में भोजन और इमारती लकड़ी जैसी वस्तुएँ आती हैं, और सांस्कृतिक सेवाओं में मनोरंजन और आध्यात्मिक मूल्य आते हैं।"},
  {"id":"env-ecology-151","question":"Consider the following statements about biomes: 1. The taiga is dominated by coniferous evergreen trees. 2. In tropical savannas, a long dry season and periodic fires help keep tree cover sparse. 3. Temperate grasslands have poor soils because most nutrients are locked up in the living vegetation. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Temperate grasslands have some of the most fertile soils (deep, humus-rich); it is the tropical rainforest whose nutrients are held mainly in the biomass.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बायोमों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. टैगा में शंकुधारी सदाबहार वृक्षों की प्रधानता होती है। 2. उष्णकटिबंधीय सवाना में लंबी शुष्क ऋतु और आवधिक आग वृक्षों के आवरण को विरल रखने में सहायक होती हैं। 3. शीतोष्ण घास के मैदानों की मिट्टी निर्धन होती है क्योंकि अधिकांश पोषक तत्व जीवित वनस्पति में बँधे होते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"शीतोष्ण घास के मैदानों की मिट्टी सबसे उपजाऊ मिट्टियों में से है (गहरी, ह्यूमस-समृद्ध); यह उष्णकटिबंधीय वर्षावन है जिसके पोषक तत्व मुख्यतः जैवभार में संचित होते हैं।"},
  {"id":"env-ecology-152","question":"When a patch of tropical rainforest is cleared for farming, the land often loses its fertility within a few years. This is mainly because:","options":["Rainforest soils are naturally saline and turn toxic","The canopy had been fixing all of the soil's nitrogen itself","Most nutrients were in the plants, and rain leaches the thin soil","Rainforest soils hold too much undecomposed humus that locks nutrients"],"answer":2,"explanation":"Rapid decomposition and uptake keep nutrients in the vegetation, not the soil; after clearing, intense rainfall leaches the remaining nutrients and lateritic soils harden.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जब उष्णकटिबंधीय वर्षावन के किसी भाग को खेती के लिए साफ़ किया जाता है, तो भूमि प्रायः कुछ ही वर्षों में अपनी उर्वरता खो देती है। इसका मुख्य कारण यह है कि:","optionsHi":["वर्षावन की मिट्टी प्राकृतिक रूप से लवणीय होती है और विषैली हो जाती है","वितान मिट्टी की सारी नाइट्रोजन का स्थिरीकरण स्वयं करता था","अधिकांश पोषक तत्व पौधों में थे, और वर्षा पतली मिट्टी का निक्षालन कर देती है","वर्षावन की मिट्टी में बहुत अधिक अपघटित न हुआ ह्यूमस होता है जो पोषक तत्वों को बाँध लेता है"],"explanationHi":"तीव्र अपघटन और अवशोषण पोषक तत्वों को मिट्टी के बजाय वनस्पति में रखते हैं; साफ़ करने के बाद तीव्र वर्षा शेष पोषक तत्वों का निक्षालन कर देती है और लैटेराइट मिट्टी कठोर हो जाती है।"},
  {"id":"env-ecology-153","question":"Consider the following statements about deep lakes in temperate regions: 1. Fresh water is densest at about 4 °C. 2. In spring and autumn, the whole lake may mix (overturn), carrying oxygen downwards and nutrients upwards. 3. In summer, the bottom layer (hypolimnion) is warmer than the surface layer (epilimnion). Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 and 3 only","1 only"],"answer":1,"explanation":"In summer warm, light water sits on top and cold dense water below, separated by the thermocline; when the surface reaches about 4 °C in autumn and spring the lake can mix.","difficulty":"hard","source":"UPSC Prelims","questionHi":"शीतोष्ण क्षेत्रों की गहरी झीलों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. मीठा जल लगभग 4 °C पर सबसे घना होता है। 2. वसंत और शरद ऋतु में पूरी झील का जल मिश्रित (पलट) हो सकता है, जिससे ऑक्सीजन नीचे और पोषक तत्व ऊपर पहुँचते हैं। 3. ग्रीष्म ऋतु में निचली परत (हाइपोलिम्नियन) सतही परत (एपिलिम्नियन) से अधिक गर्म होती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 1 और 2","केवल 2 और 3","केवल 1"],"explanationHi":"ग्रीष्म में गर्म, हल्का जल ऊपर और ठंडा, घना जल नीचे रहता है, जिन्हें तापप्रवण स्तर (थर्मोक्लाइन) अलग करता है; शरद और वसंत में जब सतह लगभग 4 °C पर पहुँचती है तो झील का जल मिश्रित हो सकता है।"},
  {"id":"env-ecology-154","question":"The profundal zone of a deep lake is best described as the zone where:","options":["Rooted plants grow thickly along the shallow, well-lit margins","Phytoplankton photosynthesis peaks in the open, sunlit surface water","Water temperature drops fastest with each metre of added depth","Light is too dim for photosynthesis, so life relies on sinking food"],"answer":3,"explanation":"The littoral zone has rooted plants and the limnetic zone holds most phytoplankton; the dark profundal zone relies on detritus raining down, while the rapid temperature change describes the thermocline.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"किसी गहरी झील के गहनतम (प्रोफंडल) क्षेत्र का सबसे उपयुक्त वर्णन वह क्षेत्र है जहाँ:","optionsHi":["जड़दार पौधे उथले, भली-भाँति प्रकाशित किनारों पर घने उगते हैं","पादपप्लवकों का प्रकाश-संश्लेषण खुले, प्रकाशित सतही जल में चरम पर होता है","प्रत्येक अतिरिक्त मीटर गहराई के साथ जल का तापमान सबसे तेज़ी से घटता है","प्रकाश प्रकाश-संश्लेषण के लिए बहुत मंद होता है, इसलिए जीवन डूबकर आने वाले भोजन पर निर्भर रहता है"],"explanationHi":"तटीय (लिटोरल) क्षेत्र में जड़दार पौधे और खुले जल (लिम्नेटिक) क्षेत्र में अधिकांश पादपप्लवक होते हैं; अंधकारमय गहनतम क्षेत्र ऊपर से बरसने वाले अपरद पर निर्भर रहता है, जबकि तापमान में तेज़ परिवर्तन तापप्रवण स्तर का वर्णन है।"},
  {"id":"env-ecology-155","question":"Consider the following statements: 1. In clear ocean water, the euphotic zone in which photosynthesis is possible extends to a depth of about 2,000 m. 2. Communities around deep-sea hydrothermal vents depend on chemosynthetic bacteria rather than sunlight as their primary energy source. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"The euphotic zone reaches only about 200 m at most; vent communities are built on bacteria that oxidise chemicals such as hydrogen sulphide.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. स्वच्छ समुद्री जल में, जिस प्रकाशित क्षेत्र (यूफोटिक ज़ोन) में प्रकाश-संश्लेषण संभव है, वह लगभग 2,000 m की गहराई तक फैला होता है। 2. गहरे समुद्र के जलतापीय छिद्रों के आसपास के समुदाय प्राथमिक ऊर्जा स्रोत के रूप में सूर्य के प्रकाश के बजाय रसायन-संश्लेषी जीवाणुओं पर निर्भर होते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"प्रकाशित क्षेत्र अधिकतम लगभग 200 m तक ही पहुँचता है; छिद्र समुदाय उन जीवाणुओं पर आधारित हैं जो हाइड्रोजन सल्फाइड जैसे रसायनों का ऑक्सीकरण करते हैं।"},
  {"id":"env-ecology-156","question":"Arctic foxes have noticeably shorter ears and limbs than foxes living in hot deserts. This pattern is described by:","options":["Allen's rule","Bergmann's rule","Gloger's rule","Liebig's law of the minimum"],"answer":0,"explanation":"Allen's rule: endotherms in cold climates have shorter extremities to reduce heat loss. Bergmann's rule concerns overall body size, and Gloger's rule concerns pigmentation.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आर्कटिक लोमड़ियों के कान और पैर गर्म मरुस्थलों में रहने वाली लोमड़ियों की तुलना में स्पष्ट रूप से छोटे होते हैं। यह पैटर्न किसके द्वारा वर्णित है?","optionsHi":["ऐलन का नियम","बर्गमान का नियम","ग्लोगर का नियम","लीबिग का न्यूनतम का नियम"],"explanationHi":"ऐलन का नियम: ठंडी जलवायु में रहने वाले समतापी जंतुओं के उपांग ऊष्मा हानि घटाने के लिए छोटे होते हैं। बर्गमान का नियम शरीर के समग्र आकार से और ग्लोगर का नियम वर्णकता से संबंधित है।"},
  {"id":"env-ecology-157","question":"Consider the following statements: 1. Liebig's law of the minimum says that growth is limited by the essential resource in shortest supply rather than by the total of all resources. 2. Shelford's law of tolerance says that an organism's distribution is limited by both the minimum and the maximum levels of an environmental factor. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Liebig focused on the scarcest factor; Shelford extended this by showing that too much of a factor can be as limiting as too little.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. लीबिग का न्यूनतम का नियम कहता है कि वृद्धि सभी संसाधनों के कुल योग से नहीं, बल्कि सबसे कम उपलब्ध आवश्यक संसाधन से सीमित होती है। 2. शेल्फोर्ड का सहनशीलता का नियम कहता है कि किसी जीव का वितरण किसी पर्यावरणीय कारक के न्यूनतम और अधिकतम, दोनों स्तरों से सीमित होता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"लीबिग ने सबसे दुर्लभ कारक पर ध्यान केंद्रित किया; शेल्फोर्ड ने इसे यह दिखाकर आगे बढ़ाया कि किसी कारक की अधिकता भी उसकी कमी जितनी ही सीमित करने वाली हो सकती है।"},
  {"id":"env-ecology-158","question":"Which of the following pairs are correctly matched? 1. Euryhaline — tolerates a wide range of salinity 2. Stenothermal — tolerates a wide range of temperature 3. Ectotherm — body temperature largely follows that of the surroundings. Select the correct answer.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"'Steno-' means narrow: stenothermal organisms tolerate only a narrow temperature range; the wide-range term is eurythermal.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी जोड़ियाँ सही सुमेलित हैं? 1. यूरीहैलाइन — लवणता की विस्तृत सीमा को सहन करता है 2. स्टेनोथर्मल — तापमान की विस्तृत सीमा को सहन करता है 3. बाह्योष्मी (एक्टोथर्म) — शरीर का तापमान काफ़ी हद तक परिवेश के तापमान के अनुसार चलता है। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"'स्टेनो-' का अर्थ संकीर्ण है: स्टेनोथर्मल जीव केवल संकीर्ण तापमान सीमा सहन करते हैं; विस्तृत सीमा के लिए शब्द यूरीथर्मल है।"},
  {"id":"env-ecology-159","question":"Very small mammals and birds, such as shrews and hummingbirds, are rarely found in polar regions. The best explanation is that:","options":["Their eggs cannot develop below freezing, even when incubated","Their high surface-to-volume ratio makes heat loss too costly","They are ectotherms and cannot regulate body temperature","Polar regions have no insects or nectar at any time of year"],"answer":1,"explanation":"Small endotherms lose heat rapidly through their relatively large surface and must burn energy fast to stay warm; shrews and hummingbirds are endotherms, not ectotherms.","difficulty":"hard","source":"UPSC Prelims","questionHi":"छछूंदर और हमिंगबर्ड जैसे बहुत छोटे स्तनधारी और पक्षी ध्रुवीय क्षेत्रों में बहुत कम पाए जाते हैं। इसकी सबसे अच्छी व्याख्या यह है कि:","optionsHi":["उनके अंडे हिमांक से नीचे विकसित नहीं हो सकते, भले ही उन्हें सेया जाए","उनके उच्च पृष्ठ-आयतन अनुपात के कारण ऊष्मा हानि बहुत महँगी पड़ती है","वे बाह्योष्मी हैं और शरीर का तापमान नियंत्रित नहीं कर सकते","ध्रुवीय क्षेत्रों में वर्ष के किसी भी समय कीट या मकरंद नहीं होते"],"explanationHi":"छोटे समतापी जंतु अपेक्षाकृत बड़ी सतह से तेज़ी से ऊष्मा खोते हैं और गर्म रहने के लिए उन्हें ऊर्जा तेज़ी से जलानी पड़ती है; छछूंदर और हमिंगबर्ड समतापी हैं, बाह्योष्मी नहीं।"},
  {"id":"env-ecology-160","question":"In hydrarch succession, which begins in a pond or lake, the pioneer community usually consists of:","options":["Lichens","Rooted submerged plants","Phytoplankton","Mosses"],"answer":2,"explanation":"Phytoplankton colonise open water first, followed by rooted submerged and floating plants, reed swamp, sedge meadow and finally woodland; lichens are pioneers on bare rock.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जलारंभी अनुक्रमण (हाइड्रार्क सक्सेशन) में, जो तालाब या झील में शुरू होता है, अग्रगामी समुदाय में सामान्यतः क्या होते हैं?","optionsHi":["लाइकेन","जड़दार जलमग्न पौधे","पादपप्लवक","काई"],"explanationHi":"खुले जल में सबसे पहले पादपप्लवक बसते हैं, उसके बाद जड़दार जलमग्न और तैरने वाले पौधे, नरकट दलदल, सेज घास का मैदान और अंत में वनभूमि; लाइकेन नंगी चट्टान पर अग्रगामी होते हैं।"},
  {"id":"env-ecology-161","question":"Consider the following statements about ecological succession: 1. Both hydrarch and xerarch successions tend to move towards a mesic (moderate moisture) climax. 2. Secondary succession is usually faster than primary succession because soil is already present. 3. Net community productivity is higher in a climax community than in early successional stages. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Early stages accumulate biomass fast; at climax respiration nearly balances production, so net community productivity falls towards zero.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पारिस्थितिक अनुक्रमण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. जलारंभी और शुष्कारंभी दोनों अनुक्रमण मध्यम नमी वाले (मीसिक) चरम की ओर बढ़ते हैं। 2. द्वितीयक अनुक्रमण सामान्यतः प्राथमिक अनुक्रमण से तेज़ होता है क्योंकि मिट्टी पहले से मौजूद होती है। 3. चरम समुदाय में शुद्ध समुदाय उत्पादकता प्रारंभिक अनुक्रमिक अवस्थाओं से अधिक होती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"प्रारंभिक अवस्थाओं में जैवभार तेज़ी से जमा होता है; चरम पर श्वसन उत्पादन के लगभग बराबर हो जाता है, इसलिए शुद्ध समुदाय उत्पादकता शून्य की ओर गिरती है।"},
  {"id":"env-ecology-162","question":"A species such as a reef-building coral or a giant kelp, whose physical structure creates the habitat on which a whole community depends, is best termed a:","options":["Keystone species","Flagship species","Indicator species","Foundation species"],"answer":3,"explanation":"Foundation species build habitat, usually by sheer abundance; keystone species have influence out of proportion to their abundance, often as predators.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रवाल भित्ति बनाने वाले प्रवाल या विशाल केल्प जैसी प्रजाति, जिसकी भौतिक संरचना उस आवास का निर्माण करती है जिस पर पूरा समुदाय निर्भर है, को सबसे उपयुक्त रूप से क्या कहा जाएगा?","optionsHi":["कीस्टोन प्रजाति","प्रमुख (फ्लैगशिप) प्रजाति","सूचक प्रजाति","आधारभूत (फाउंडेशन) प्रजाति"],"explanationHi":"आधारभूत प्रजातियाँ आवास का निर्माण करती हैं, सामान्यतः अपनी विशाल बहुतायत से; कीस्टोन प्रजातियों का प्रभाव उनकी बहुतायत के अनुपात से कहीं अधिक होता है, प्रायः परभक्षी के रूप में।"},
  {"id":"env-ecology-163","question":"After sea otters were hunted out of parts of the North Pacific coast, sea urchins multiplied and kelp forests collapsed. This sequence is an example of:","options":["A trophic cascade after loss of a keystone predator","Biomagnification of toxins along a marine food chain","Competitive exclusion of kelp by the expanding urchins","Bottom-up control by nutrient supply"],"answer":0,"explanation":"Removing the top predator released the herbivore, which overgrazed the producer: a classic top-down trophic cascade.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"उत्तरी प्रशांत तट के कुछ भागों से समुद्री ऊदबिलावों का शिकार कर समाप्त कर दिए जाने के बाद, समुद्री अर्चिन बढ़ गए और केल्प वन नष्ट हो गए। यह क्रम किसका उदाहरण है?","optionsHi":["कीस्टोन परभक्षी के लुप्त होने के बाद पोषण स्तरीय प्रपात (ट्रॉफिक कैस्केड)","समुद्री खाद्य श्रृंखला में विषैले पदार्थों का जैव आवर्धन","बढ़ते अर्चिनों द्वारा केल्प का प्रतिस्पर्धी अपवर्जन","पोषक तत्वों की आपूर्ति द्वारा निम्न-से-उच्च नियंत्रण (बॉटम-अप)"],"explanationHi":"शीर्ष परभक्षी के हट जाने से शाकाहारी मुक्त हो गया, जिसने उत्पादक को अतिचरा: यह उच्च-से-निम्न (टॉप-डाउन) पोषण स्तरीय प्रपात का क्लासिक उदाहरण है।"},
  {"id":"env-ecology-164","question":"Which of the following pairs of organism and what its presence indicates are correctly matched? 1. Lichens on tree bark — low sulphur dioxide pollution 2. Mayfly and stonefly nymphs — clean, well-oxygenated stream water 3. Dense populations of Tubifex worms — organically polluted, oxygen-poor water. Select the correct answer.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Lichens are SO2-sensitive, mayfly and stonefly nymphs need high dissolved oxygen, and Tubifex tolerates low oxygen, so it thrives where sewage pollution is heavy.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जीव और उसकी उपस्थिति जो संकेत देती है, उनकी निम्नलिखित जोड़ियों में से कौन-सी सही सुमेलित हैं? 1. पेड़ की छाल पर लाइकेन — कम सल्फर डाइऑक्साइड प्रदूषण 2. मेफ्लाई और स्टोनफ्लाई की निम्फ — स्वच्छ, भली-भाँति ऑक्सीजनित धारा का जल 3. ट्यूबीफेक्स कृमियों की सघन आबादी — कार्बनिक रूप से प्रदूषित, ऑक्सीजन-रहित जल। सही उत्तर चुनिए।","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"लाइकेन SO2 के प्रति संवेदनशील होते हैं, मेफ्लाई और स्टोनफ्लाई की निम्फ को उच्च घुली ऑक्सीजन चाहिए, और ट्यूबीफेक्स कम ऑक्सीजन सहन करता है, इसलिए वह वहाँ फलता-फूलता है जहाँ सीवेज प्रदूषण भारी हो।"},
  {"id":"env-ecology-165","question":"Which of the following properties make a chemical likely to biomagnify along a food chain? 1. It persists for a long time without breaking down. 2. It is highly soluble in water and easily excreted. 3. It is soluble in fat and stored in body tissues. Select the correct answer.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Persistent, fat-soluble compounds such as DDT and methylmercury accumulate; water-soluble substances are excreted and do not concentrate up the chain.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से गुण किसी रसायन को खाद्य श्रृंखला में जैव आवर्धित होने योग्य बनाते हैं? 1. वह बिना विघटित हुए लंबे समय तक बना रहता है। 2. वह जल में अत्यधिक विलेय है और आसानी से उत्सर्जित हो जाता है। 3. वह वसा में विलेय है और शरीर के ऊतकों में संचित रहता है। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"DDT और मिथाइलमरकरी जैसे स्थायी, वसा-विलेय यौगिक संचित होते हैं; जल-विलेय पदार्थ उत्सर्जित हो जाते हैं और श्रृंखला में ऊपर की ओर सांद्रित नहीं होते।"},
  {"id":"env-ecology-166","question":"Consider the following statements about population growth: 1. Exponential (J-shaped) growth occurs when resources are effectively unlimited. 2. In the logistic model, the absolute growth rate (dN/dt) is highest when the population is at its carrying capacity. 3. In exponential growth, the per capita growth rate r stays constant. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"In the logistic model dN/dt = rN(1 − N/K) peaks at N = K/2 and falls to zero at K; the trap is to think growth is fastest at the carrying capacity.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आबादी की वृद्धि के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. चरघातांकी (J-आकार की) वृद्धि तब होती है जब संसाधन प्रभावी रूप से असीमित हों। 2. लॉजिस्टिक मॉडल में, निरपेक्ष वृद्धि दर (dN/dt) तब सबसे अधिक होती है जब आबादी अपनी धारण क्षमता पर हो। 3. चरघातांकी वृद्धि में, प्रति व्यक्ति वृद्धि दर r स्थिर रहती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"लॉजिस्टिक मॉडल में dN/dt = rN(1 − N/K) का शिखर N = K/2 पर होता है और K पर शून्य हो जाता है; भूल यह मानने में होती है कि वृद्धि धारण क्षमता पर सबसे तेज़ होती है।"},
  {"id":"env-ecology-167","question":"Which of the following are typical of K-selected species? 1. Late maturity and a long life span 2. Few offspring with a high level of parental care 3. A Type III survivorship curve with very heavy juvenile mortality. Select the correct answer.","options":["1, 2 and 3","2 and 3 only","1 and 2 only","3 only"],"answer":2,"explanation":"K-selected species such as elephants and great apes invest heavily in few young and show a Type I curve; heavy early mortality (Type III) is typical of r-selected species such as oysters.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से K-चयनित प्रजातियों के विशिष्ट लक्षण हैं? 1. देर से परिपक्वता और लंबी जीवन अवधि 2. कम संतानें, जिनकी माता-पिता द्वारा अधिक देखभाल होती है 3. प्रकार III की उत्तरजीविता वक्र, जिसमें किशोरावस्था में बहुत अधिक मृत्यु होती है। सही उत्तर चुनिए।","optionsHi":["1, 2 और 3","केवल 2 और 3","केवल 1 और 2","केवल 3"],"explanationHi":"हाथी और महावानर जैसी K-चयनित प्रजातियाँ कम संतानों में भारी निवेश करती हैं और प्रकार I का वक्र दिखाती हैं; शुरुआती अवस्था में भारी मृत्यु (प्रकार III) सीप जैसी r-चयनित प्रजातियों की विशेषता है।"},
  {"id":"env-ecology-168","question":"In oysters and many fishes, the great majority of individuals die very young, and the few that survive live for a long time. Such populations show a survivorship curve of:","options":["Type I","Type III","Type II","A line that rises with age"],"answer":1,"explanation":"Type III curves fall steeply at the start; Type I (humans, large mammals) stays high until old age, and Type II shows a constant death rate.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"सीप और अनेक मछलियों में, अधिकांश जीव बहुत छोटी आयु में मर जाते हैं और जो थोड़े से बचते हैं वे लंबे समय तक जीवित रहते हैं। ऐसी आबादियाँ किस प्रकार की उत्तरजीविता वक्र दिखाती हैं?","optionsHi":["प्रकार I","प्रकार III","प्रकार II","आयु के साथ ऊपर उठती रेखा"],"explanationHi":"प्रकार III के वक्र शुरुआत में तेज़ी से गिरते हैं; प्रकार I (मनुष्य, बड़े स्तनधारी) वृद्धावस्था तक ऊँचा रहता है, और प्रकार II में मृत्यु दर स्थिर रहती है।"},
  {"id":"env-ecology-169","question":"An urn-shaped age pyramid, narrower at the base (young) than in the middle age groups, indicates a population that is:","options":["Expanding rapidly","Stable in size","Declining","At carrying capacity with a high birth rate"],"answer":2,"explanation":"Fewer young than adults means fewer future parents, so the population will shrink; a broad-based triangle shows growth and a bell shape a stable population.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"कलश-आकार का आयु पिरामिड, जिसका आधार (युवा) मध्य आयु वर्गों की तुलना में संकरा होता है, किस प्रकार की आबादी को दर्शाता है?","optionsHi":["तेज़ी से बढ़ती हुई","आकार में स्थिर","घटती हुई","धारण क्षमता पर, उच्च जन्म दर के साथ"],"explanationHi":"वयस्कों की तुलना में कम युवा का अर्थ है भविष्य में कम माता-पिता, इसलिए आबादी घटेगी; चौड़े आधार वाला त्रिभुज वृद्धि दर्शाता है और घंटी-आकार स्थिर आबादी को।"},
  {"id":"env-ecology-170","question":"The Asian koel lays its eggs in the nest of the house crow, which then raises the koel's chicks. This interaction is an example of:","options":["Commensalism","Amensalism","Interspecific competition","Brood parasitism"],"answer":3,"explanation":"The crow spends effort raising another species' young and gains nothing, so it is harmed; the koel's eggs often resemble the host's to avoid detection.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"एशियाई कोयल अपने अंडे घरेलू कौवे के घोंसले में देती है, जो फिर कोयल के चूज़ों को पालता है। यह अंतःक्रिया किसका उदाहरण है?","optionsHi":["सहभोजिता","अमेन्सलिज़्म","अंतरा-प्रजातीय प्रतिस्पर्धा","नीड़ परजीविता (ब्रूड पैरासिटिज़्म)"],"explanationHi":"कौवा दूसरी प्रजाति के बच्चों को पालने में प्रयास लगाता है और कुछ नहीं पाता, इसलिए उसे हानि होती है; पहचान से बचने के लिए कोयल के अंडे प्रायः पोषक के अंडों जैसे दिखते हैं।"},
  {"id":"env-ecology-171","question":"Consider the following pairs of interaction and its type: 1. Mycorrhiza between fungi and plant roots — mutualism 2. Cuscuta growing on hedge plants — parasitism 3. Cattle egrets foraging near grazing cattle — commensalism 4. Barnacles growing on the back of a whale — amensalism. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Barnacles gain a moving home while the whale is barely affected, which is commensalism, not amensalism; the other three pairs are correct.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अंतःक्रिया और उसके प्रकार की निम्नलिखित जोड़ियों पर विचार कीजिए: 1. कवक और पौधों की जड़ों के बीच माइकोराइज़ा — सहोपकारिता 2. बाड़ के पौधों पर उगती अमरबेल (कस्कुटा) — परजीविता 3. चरते पशुओं के पास भोजन खोजते पशु-बगुले — सहभोजिता 4. व्हेल की पीठ पर उगते बार्नेकल — अमेन्सलिज़्म। उपर्युक्त में से कितनी जोड़ियाँ सही सुमेलित हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"बार्नेकल को चलता-फिरता घर मिलता है जबकि व्हेल पर मुश्किल से कोई प्रभाव पड़ता है, यह सहभोजिता है, अमेन्सलिज़्म नहीं; शेष तीनों जोड़ियाँ सही हैं।"},
  {"id":"env-ecology-172","question":"The flower of the Mediterranean orchid Ophrys resembles the female of a bee species, so that males attempt to mate with it and carry away pollen. This is best described as:","options":["Pollination by sexual deceit (pseudocopulation)","Brood parasitism","Commensalism in which the bee benefits","Obligate mutualism in which both partners gain food"],"answer":0,"explanation":"The bee gets no reward; the orchid exploits the male's mating behaviour, so this is deceptive pollination rather than mutualism.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भूमध्यसागरीय ऑर्किड ओफ्रिस का फूल मधुमक्खी की एक प्रजाति की मादा जैसा दिखता है, जिससे नर उससे संभोग का प्रयास करते हैं और पराग ले जाते हैं। इसका सबसे उपयुक्त वर्णन है:","optionsHi":["यौन छल द्वारा परागण (छद्म-मैथुन)","नीड़ परजीविता","सहभोजिता जिसमें मधुमक्खी को लाभ होता है","बाध्यकारी सहोपकारिता जिसमें दोनों साथियों को भोजन मिलता है"],"explanationHi":"मधुमक्खी को कोई पुरस्कार नहीं मिलता; ऑर्किड नर के संभोग व्यवहार का लाभ उठाता है, इसलिए यह सहोपकारिता नहीं, छलपूर्ण परागण है।"},
  {"id":"env-ecology-173","question":"Which of the following are ecological roles of predators? 1. Transferring energy fixed by plants to higher trophic levels 2. Keeping prey populations in check 3. Helping maintain species diversity by reducing competition among prey species. Select the correct answer.","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":0,"explanation":"All three apply; Paine's experiment of removing the starfish Pisaster from a rocky shore led to the loss of more than ten invertebrate species as one dominant competitor took over.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी परभक्षियों की पारिस्थितिक भूमिकाएँ हैं? 1. पौधों द्वारा स्थिर की गई ऊर्जा को उच्चतर पोषण स्तरों तक पहुँचाना 2. शिकार की आबादी को नियंत्रित रखना 3. शिकार प्रजातियों के बीच प्रतिस्पर्धा घटाकर प्रजाति विविधता बनाए रखने में सहायता करना। सही उत्तर चुनिए।","optionsHi":["1, 2 और 3","केवल 1 और 2","केवल 2","केवल 1 और 3"],"explanationHi":"तीनों लागू होती हैं; पेन के प्रयोग में चट्टानी तट से तारामछली पिसैस्टर को हटाने पर दस से अधिक अकशेरुकी प्रजातियाँ लुप्त हो गईं क्योंकि एक प्रभावी प्रतिस्पर्धी हावी हो गया।"},
  {"id":"env-ecology-174","question":"The prickly pear cactus, introduced into Australia, spread over millions of hectares until a cactus-eating moth from its native range was released there. This episode best illustrates:","options":["Competitive exclusion of native plants by a superior alien cactus","Invasion without natural enemies, ended by biological control","Co-extinction of a plant and its specialist pollinator","Ecological succession of scrub reaching a stable climax"],"answer":1,"explanation":"Freed from its natural predators, the cactus became invasive; reintroducing a specialist herbivore (Cactoblastis) brought it under control.","difficulty":"hard","source":"UPSC Prelims","questionHi":"ऑस्ट्रेलिया में लाया गया नागफनी (प्रिकली पियर) कैक्टस लाखों हेक्टेयर में फैल गया, जब तक कि उसके मूल क्षेत्र से कैक्टस खाने वाला एक पतंगा वहाँ नहीं छोड़ा गया। यह घटना सबसे अच्छी तरह किसे दर्शाती है?","optionsHi":["श्रेष्ठ विदेशी कैक्टस द्वारा स्थानीय पौधों का प्रतिस्पर्धी अपवर्जन","प्राकृतिक शत्रुओं के बिना आक्रमण, जो जैविक नियंत्रण से समाप्त हुआ","किसी पौधे और उसके विशिष्ट परागणकर्ता का सह-विलोपन","झाड़ियों का एक स्थिर चरम तक पहुँचने वाला पारिस्थितिक अनुक्रमण"],"explanationHi":"अपने प्राकृतिक शत्रुओं से मुक्त होकर कैक्टस आक्रामक बन गया; एक विशिष्ट शाकाहारी (कैक्टोब्लास्टिस) को पुनः लाने से उस पर नियंत्रण पाया गया।"},
  {"id":"env-ecology-175","question":"Consider the following statements about the carbon cycle: 1. The oceans hold far more carbon than the atmosphere. 2. Photosynthesis and respiration are the main fluxes of carbon between living things and the atmosphere. 3. Weathering of carbonate rocks is the main way carbon returns quickly to the atmosphere. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Rock weathering and sedimentation move carbon over geological time, not quickly; the fast exchanges are photosynthesis, respiration, decomposition, ocean exchange and combustion.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कार्बन चक्र के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. महासागरों में वायुमंडल की तुलना में कहीं अधिक कार्बन संचित है। 2. प्रकाश-संश्लेषण और श्वसन जीवित प्राणियों और वायुमंडल के बीच कार्बन के मुख्य प्रवाह हैं। 3. कार्बोनेट चट्टानों का अपक्षय वह मुख्य तरीका है जिससे कार्बन शीघ्रता से वायुमंडल में लौटता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"चट्टानों का अपक्षय और अवसादन कार्बन को भूवैज्ञानिक समय-सीमा में ले जाते हैं, शीघ्रता से नहीं; तीव्र आदान-प्रदान प्रकाश-संश्लेषण, श्वसन, अपघटन, महासागरीय आदान-प्रदान और दहन के हैं।"},
  {"id":"env-ecology-176","question":"The ocean's 'biological pump' refers to:","options":["Upwelling currents that lift deep nutrients up to the sunlit surface","The exchange of CO2 between air and sea driven only by temperature","Oxygen pumped into deep water by migrating marine animals","Carbon fixed by surface plankton sinking to depth as dead matter"],"answer":3,"explanation":"The biological pump moves carbon downward through sinking organic matter; the temperature-driven exchange is called the solubility pump.","difficulty":"hard","source":"UPSC Prelims","questionHi":"महासागर के 'जैविक पंप' से तात्पर्य है:","optionsHi":["उत्स्रवण धाराएँ जो गहरे पोषक तत्वों को प्रकाशित सतह तक उठाती हैं","वायु और समुद्र के बीच CO2 का आदान-प्रदान जो केवल तापमान से संचालित होता है","प्रवासी समुद्री जंतुओं द्वारा गहरे जल में पंप की गई ऑक्सीजन","सतही प्लवकों द्वारा स्थिर किया गया कार्बन जो मृत पदार्थ के रूप में गहराई में डूबता है"],"explanationHi":"जैविक पंप डूबते कार्बनिक पदार्थ के माध्यम से कार्बन को नीचे ले जाता है; तापमान-संचालित आदान-प्रदान को विलेयता पंप कहते हैं।"},
  {"id":"env-ecology-177","question":"Consider the following statements about the nitrogen cycle: 1. Denitrification converts nitrate into nitrogen gas and takes place mainly in oxygen-poor soils. 2. Lightning fixes some atmospheric nitrogen into compounds that reach the soil with rain. 3. Ammonification converts nitrates into ammonia. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Ammonification is the release of ammonia from the organic nitrogen in dead matter and wastes by decomposers, not the conversion of nitrate.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नाइट्रोजन चक्र के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. विनाइट्रीकरण नाइट्रेट को नाइट्रोजन गैस में बदलता है और मुख्यतः ऑक्सीजन-रहित मिट्टियों में होता है। 2. आकाशीय बिजली कुछ वायुमंडलीय नाइट्रोजन को ऐसे यौगिकों में स्थिर करती है जो वर्षा के साथ मिट्टी में पहुँचते हैं। 3. अमोनीकरण नाइट्रेट को अमोनिया में बदलता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"अमोनीकरण अपघटकों द्वारा मृत पदार्थ और अपशिष्टों के कार्बनिक नाइट्रोजन से अमोनिया का मुक्त होना है, नाइट्रेट का रूपांतरण नहीं।"},
  {"id":"env-ecology-178","question":"Which one of the following pairs is NOT correctly matched?","options":["Azotobacter — free-living aerobic nitrogen fixer","Frankia — nitrogen fixer in the root nodules of non-legumes such as alder","Anabaena — cyanobacterium that fixes nitrogen in heterocysts","Nitrobacter — converts atmospheric nitrogen into ammonia"],"answer":3,"explanation":"Nitrobacter is a nitrifying bacterium that oxidises nitrite to nitrate; it does not fix atmospheric nitrogen.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["एज़ोटोबैक्टर — मुक्तजीवी वायवीय नाइट्रोजन स्थिरीकारक","फ्रैंकिया — एल्डर जैसे अफलीदार पौधों की जड़-ग्रंथिकाओं में नाइट्रोजन स्थिरीकारक","एनाबीना — सायनोबैक्टीरिया जो हेटेरोसिस्ट में नाइट्रोजन का स्थिरीकरण करता है","नाइट्रोबैक्टर — वायुमंडलीय नाइट्रोजन को अमोनिया में बदलता है"],"explanationHi":"नाइट्रोबैक्टर एक नाइट्रीकारी जीवाणु है जो नाइट्राइट का नाइट्रेट में ऑक्सीकरण करता है; यह वायुमंडलीय नाइट्रोजन का स्थिरीकरण नहीं करता।"},
  {"id":"env-ecology-179","question":"The pink pigment leghaemoglobin found in the root nodules of legumes helps nitrogen fixation by:","options":["Mopping up oxygen that would inactivate nitrogenase","Supplying the iron that the bacteria need to make ammonia","Storing the fixed nitrogen until the host plant needs it","Carrying carbon dioxide out of the nodule to the leaves"],"answer":0,"explanation":"Nitrogenase is inactivated by oxygen; leghaemoglobin acts as an oxygen scavenger while still supplying enough for bacterial respiration.","difficulty":"hard","source":"UPSC Prelims","questionHi":"फलीदार पौधों की जड़-ग्रंथिकाओं में पाया जाने वाला गुलाबी वर्णक लेघीमोग्लोबिन नाइट्रोजन स्थिरीकरण में किस प्रकार सहायक होता है?","optionsHi":["ऑक्सीजन को सोखकर, जो नाइट्रोजिनेज़ को निष्क्रिय कर देती","वह लोहा प्रदान करके जिसकी जीवाणुओं को अमोनिया बनाने के लिए आवश्यकता होती है","स्थिर की गई नाइट्रोजन को तब तक संचित करके जब तक पोषक पौधे को उसकी आवश्यकता न हो","कार्बन डाइऑक्साइड को ग्रंथिका से पत्तियों तक ले जाकर"],"explanationHi":"नाइट्रोजिनेज़ ऑक्सीजन से निष्क्रिय हो जाता है; लेघीमोग्लोबिन ऑक्सीजन-अवशोषक का कार्य करता है और साथ ही जीवाणु श्वसन के लिए पर्याप्त ऑक्सीजन भी देता है।"},
  {"id":"env-ecology-180","question":"Consider the following statements about the phosphorus cycle: 1. Sedimentary rocks are the main natural reservoir of phosphorus. 2. Guano deposited by seabirds returns some phosphorus from the sea to land. 3. Rainfall supplies more phosphorus to ecosystems than weathering of rocks does. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Phosphorus has no significant gaseous phase, so atmospheric input is tiny; weathering of phosphate rock is the main natural source.","difficulty":"hard","source":"UPSC Prelims","questionHi":"फॉस्फोरस चक्र के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. अवसादी चट्टानें फॉस्फोरस का मुख्य प्राकृतिक भंडार हैं। 2. समुद्री पक्षियों द्वारा जमा किया गया गुआनो कुछ फॉस्फोरस को समुद्र से स्थल पर लौटाता है। 3. वर्षा चट्टानों के अपक्षय की तुलना में पारिस्थितिकी तंत्रों को अधिक फॉस्फोरस प्रदान करती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"फॉस्फोरस की कोई महत्वपूर्ण गैसीय प्रावस्था नहीं होती, इसलिए वायुमंडलीय निवेश बहुत कम है; फॉस्फेट चट्टान का अपक्षय मुख्य प्राकृतिक स्रोत है।"},
  {"id":"env-ecology-181","question":"Consider the following statements about the sulphur cycle: 1. Dimethyl sulphide released by marine phytoplankton is a natural source of atmospheric sulphur that can help form cloud-condensation nuclei. 2. Volcanic eruptions release sulphur dioxide into the atmosphere. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are natural sulphur sources; sulphate aerosols formed from DMS and volcanic SO2 seed clouds and reflect sunlight.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सल्फर चक्र के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. समुद्री पादपप्लवकों द्वारा मुक्त डाइमेथिल सल्फाइड वायुमंडलीय सल्फर का एक प्राकृतिक स्रोत है जो मेघ-संघनन केंद्र बनाने में सहायक हो सकता है। 2. ज्वालामुखी विस्फोट वायुमंडल में सल्फर डाइऑक्साइड छोड़ते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों प्राकृतिक सल्फर स्रोत हैं; DMS और ज्वालामुखीय SO2 से बने सल्फेट एरोसोल बादलों के बीज बनते हैं और सूर्य के प्रकाश को परावर्तित करते हैं।"},
  {"id":"env-ecology-182","question":"The largest store of fresh water on Earth is held in:","options":["Groundwater aquifers","Ice caps and glaciers","Lakes and rivers","Water vapour in the atmosphere"],"answer":1,"explanation":"About two-thirds of fresh water is frozen in ice sheets and glaciers; groundwater is the next largest store, while lakes and rivers hold a very small fraction.","difficulty":"moderate","source":"UPSC Prelims · CDS","questionHi":"पृथ्वी पर मीठे जल का सबसे बड़ा भंडार किसमें है?","optionsHi":["भूजल जलभृत","हिम टोपियाँ और हिमनद","झीलें और नदियाँ","वायुमंडल में जलवाष्प"],"explanationHi":"मीठे जल का लगभग दो-तिहाई भाग हिम चादरों और हिमनदों में जमा है; भूजल अगला सबसे बड़ा भंडार है, जबकि झीलों और नदियों में बहुत छोटा अंश है।"},
  {"id":"env-ecology-183","question":"Assertion (A): Large-scale deforestation in the Amazon basin can reduce rainfall in regions downwind. Reason (R): A large share of the rainfall over the basin is moisture recycled into the air by the forest's evapotranspiration. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Forests pump soil water back into the air; removing them cuts this recycled moisture, so less rain falls further along the airflow.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): अमेज़न बेसिन में बड़े पैमाने पर वनों की कटाई से पवन की दिशा वाले क्षेत्रों में वर्षा घट सकती है। कारण (R): बेसिन के ऊपर होने वाली वर्षा का एक बड़ा भाग वह नमी है जो वन के वाष्पोत्सर्जन से वायु में पुनर्चक्रित होती है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"वन मिट्टी के जल को वापस वायु में पहुँचाते हैं; उन्हें हटाने से यह पुनर्चक्रित नमी घटती है, इसलिए वायु-प्रवाह के आगे के क्षेत्रों में कम वर्षा होती है।"},
  {"id":"env-ecology-184","question":"Which of the following biogeochemical cycles are conventionally classified as gaseous cycles? 1. Nitrogen 2. Phosphorus 3. Carbon. Select the correct answer.","options":["2 only","1, 2 and 3","1 and 2 only","1 and 3 only"],"answer":3,"explanation":"Nitrogen and carbon have large atmospheric pools; phosphorus is a sedimentary cycle with no significant gaseous phase.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से जैव-भू-रासायनिक चक्र परंपरागत रूप से गैसीय चक्रों के रूप में वर्गीकृत किए जाते हैं? 1. नाइट्रोजन 2. फॉस्फोरस 3. कार्बन। सही उत्तर चुनिए।","optionsHi":["केवल 2","1, 2 और 3","केवल 1 और 2","केवल 1 और 3"],"explanationHi":"नाइट्रोजन और कार्बन के वायुमंडल में बड़े भंडार हैं; फॉस्फोरस एक अवसादी चक्र है जिसकी कोई महत्वपूर्ण गैसीय प्रावस्था नहीं होती।"},
  {"id":"env-ecology-185","question":"David Tilman's long-term field experiments on grassland plots showed that plots with more plant species tended to have:","options":["Lower total biomass and greater swings from year to year","More invasion by alien species due to crowded niches","More stable biomass across years and higher productivity","No measurable difference from plots with fewer species"],"answer":2,"explanation":"The experiments supported the idea that greater diversity makes an ecosystem's productivity more stable over time.","difficulty":"hard","source":"UPSC Prelims","questionHi":"घास के मैदानों के भूखंडों पर डेविड टिलमैन के दीर्घकालिक क्षेत्र प्रयोगों से पता चला कि अधिक पादप प्रजातियों वाले भूखंडों में सामान्यतः क्या पाया गया?","optionsHi":["कुल जैवभार कम और वर्ष-दर-वर्ष अधिक उतार-चढ़ाव","संकुल निकेतों के कारण विदेशी प्रजातियों का अधिक आक्रमण","वर्षों में अधिक स्थिर जैवभार और अधिक उत्पादकता","कम प्रजातियों वाले भूखंडों से कोई मापने योग्य अंतर नहीं"],"explanationHi":"प्रयोगों ने इस विचार का समर्थन किया कि अधिक विविधता पारिस्थितिकी तंत्र की उत्पादकता को समय के साथ अधिक स्थिर बनाती है।"},
  {"id":"env-ecology-186","question":"The 'rivet popper' hypothesis, proposed by Paul Ehrlich, compares species in an ecosystem to the rivets in an aircraft wing. It suggests that:","options":["Every species is equally important, so losing any one causes immediate collapse","Losing species has no effect, because others always take over their roles","Only alien species weaken an ecosystem, while natives make it stronger","Early losses may not show, but each weakens the system and some matter more"],"answer":3,"explanation":"A plane can lose a few rivets safely, but each loss erodes the margin, and losing a key rivet on the wing is more dangerous than losing one on a seat.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पॉल एर्लिच द्वारा प्रस्तावित 'रिवेट पॉपर' परिकल्पना पारिस्थितिकी तंत्र की प्रजातियों की तुलना विमान के पंख की कीलों (रिवेट) से करती है। यह सुझाव देती है कि:","optionsHi":["प्रत्येक प्रजाति समान रूप से महत्वपूर्ण है, इसलिए किसी एक के खोने से तुरंत पतन हो जाता है","प्रजातियों के खोने का कोई प्रभाव नहीं पड़ता, क्योंकि अन्य सदा उनकी भूमिकाएँ संभाल लेती हैं","केवल विदेशी प्रजातियाँ पारिस्थितिकी तंत्र को कमज़ोर करती हैं, जबकि स्थानीय उसे मज़बूत बनाती हैं","प्रारंभिक हानियाँ दिखाई न दें, पर प्रत्येक तंत्र को कमज़ोर करती है और कुछ अधिक महत्वपूर्ण होती हैं"],"explanationHi":"विमान कुछ रिवेट सुरक्षित रूप से खो सकता है, पर प्रत्येक हानि सुरक्षा-सीमा को घटाती है, और पंख की एक प्रमुख रिवेट खोना सीट की किसी रिवेट को खोने से अधिक खतरनाक है।"},
  {"id":"env-ecology-187","question":"The medicinal plant Rauwolfia vomitoria growing in different Himalayan ranges varies in the potency and concentration of the chemical reserpine it produces. This is an example of:","options":["Genetic diversity","Species diversity","Ecological diversity","Gamma diversity"],"answer":0,"explanation":"The variation lies within one species, so it is genetic diversity; species and ecological diversity concern differences between species and between ecosystems.","difficulty":"hard","source":"UPSC Prelims","questionHi":"विभिन्न हिमालयी श्रेणियों में उगने वाले औषधीय पौधे राउवोल्फिया वोमिटोरिया में उसके द्वारा बनाए जाने वाले रसायन रेसरपीन की क्षमता और सांद्रता भिन्न-भिन्न होती है। यह किसका उदाहरण है?","optionsHi":["आनुवंशिक विविधता","प्रजाति विविधता","पारिस्थितिक विविधता","गामा विविधता"],"explanationHi":"भिन्नता एक ही प्रजाति के भीतर है, इसलिए यह आनुवंशिक विविधता है; प्रजाति और पारिस्थितिक विविधता क्रमशः प्रजातियों और पारिस्थितिकी तंत्रों के बीच अंतर से संबंधित हैं।"},
  {"id":"env-ecology-188","question":"Consider the following statements: 1. Gamma diversity is the diversity of a whole region or landscape. 2. Beta diversity between two communities is zero if they have exactly the same species. 3. Alpha diversity is the diversity within a single community or habitat. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Beta diversity measures turnover in species composition between habitats, so identical communities have zero beta diversity; alpha is local and gamma regional.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. गामा विविधता किसी पूरे क्षेत्र या भू-दृश्य की विविधता है। 2. यदि दो समुदायों में बिल्कुल समान प्रजातियाँ हों, तो उनके बीच बीटा विविधता शून्य होती है। 3. अल्फा विविधता किसी एक समुदाय या आवास के भीतर की विविधता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"बीटा विविधता आवासों के बीच प्रजाति संघटन में परिवर्तन मापती है, इसलिए समान समुदायों में बीटा विविधता शून्य होती है; अल्फा स्थानीय और गामा क्षेत्रीय होती है।"},
  {"id":"env-ecology-189","question":"Consider the following statements about the species–area relationship: 1. Within a region, the number of species rises as the area explored increases, but only up to a limit. 2. On a log–log plot, the slope of the line is much steeper when very large areas such as whole continents are compared. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Humboldt's relationship gives a slope Z of about 0.1–0.2 within regions, but about 0.6–1.2 for very large areas such as continents.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"प्रजाति–क्षेत्र संबंध के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. किसी क्षेत्र के भीतर, खोजे गए क्षेत्रफल के बढ़ने के साथ प्रजातियों की संख्या बढ़ती है, परंतु केवल एक सीमा तक। 2. लॉग–लॉग आलेख पर, जब महाद्वीपों जैसे बहुत बड़े क्षेत्रों की तुलना की जाती है तो रेखा की ढाल कहीं अधिक तीव्र होती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"हम्बोल्ट का संबंध क्षेत्रों के भीतर लगभग 0.1–0.2 की ढाल Z देता है, परंतु महाद्वीपों जैसे बहुत बड़े क्षेत्रों के लिए लगभग 0.6–1.2।"},
  {"id":"env-ecology-190","question":"Which of the following are proposed explanations for the greater species diversity of the tropics? 1. Tropical regions have remained relatively undisturbed for millions of years, with no glaciation. 2. Tropical environments are less seasonal and more predictable. 3. More solar energy is available, which supports higher productivity. Select the correct answer.","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":2,"explanation":"All three are standard hypotheses: long evolutionary time without glacial disturbance, environmental stability that favours niche specialisation, and greater energy input.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उष्णकटिबंधों में अधिक प्रजाति विविधता के लिए निम्नलिखित में से कौन-सी व्याख्याएँ प्रस्तावित हैं? 1. उष्णकटिबंधीय क्षेत्र लाखों वर्षों तक अपेक्षाकृत अबाधित रहे हैं, उनमें कोई हिमनदन नहीं हुआ। 2. उष्णकटिबंधीय परिवेश कम मौसमी और अधिक पूर्वानुमेय होते हैं। 3. अधिक सौर ऊर्जा उपलब्ध है, जो उच्च उत्पादकता को सहारा देती है। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1"],"explanationHi":"तीनों मानक परिकल्पनाएँ हैं: हिमनदीय बाधा के बिना लंबा विकासात्मक समय, पर्यावरणीय स्थिरता जो निकेत विशेषज्ञता को बढ़ावा देती है, और अधिक ऊर्जा निवेश।"},
  {"id":"env-ecology-191","question":"Which of the following is NOT one of the four causes of biodiversity loss grouped as the 'Evil Quartet'?","options":["Co-extinctions","Climate change","Alien species invasions","Over-exploitation"],"answer":1,"explanation":"The Evil Quartet is habitat loss and fragmentation, over-exploitation, alien species invasions and co-extinctions; climate change is a serious threat but is not one of the four.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा 'ईविल क्वार्टेट' के रूप में समूहित जैव विविधता ह्रास के चार कारणों में से एक नहीं है?","optionsHi":["सह-विलोपन","जलवायु परिवर्तन","विदेशी प्रजातियों का आक्रमण","अति-दोहन"],"explanationHi":"ईविल क्वार्टेट है आवास की हानि और विखंडन, अति-दोहन, विदेशी प्रजातियों का आक्रमण और सह-विलोपन; जलवायु परिवर्तन एक गंभीर खतरा है, पर इन चारों में नहीं है।"},
  {"id":"env-ecology-192","question":"The extinction of many native cichlid fish species in Lake Victoria after the Nile perch was introduced is an example of which cause of biodiversity loss?","options":["Co-extinction","Over-exploitation","Habitat loss and fragmentation","Invasion by an alien species"],"answer":3,"explanation":"The introduced predator ate its way through the native cichlids; co-extinction is when a dependent species is lost along with its host or partner.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"नील पर्च मछली के लाए जाने के बाद विक्टोरिया झील में अनेक स्थानीय सिक्लिड मछली प्रजातियों का विलुप्त होना जैव विविधता ह्रास के किस कारण का उदाहरण है?","optionsHi":["सह-विलोपन","अति-दोहन","आवास की हानि और विखंडन","विदेशी प्रजाति द्वारा आक्रमण"],"explanationHi":"लाए गए परभक्षी ने स्थानीय सिक्लिडों को खाकर समाप्त कर दिया; सह-विलोपन तब होता है जब कोई आश्रित प्रजाति अपने पोषक या साथी के साथ लुप्त हो जाती है।"},
  {"id":"env-ecology-193","question":"Consider the following statements about habitat fragmentation: 1. It increases the proportion of edge habitat relative to interior habitat. 2. Large mammals and birds that need big territories are badly affected. 3. It always increases the number of species that live in the forest interior. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"Fragmentation shrinks interior habitat and favours edge species; interior specialists and wide-ranging animals decline.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आवास विखंडन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह भीतरी आवास की तुलना में किनारे के आवास का अनुपात बढ़ाता है। 2. बड़े क्षेत्र की आवश्यकता वाले बड़े स्तनधारी और पक्षी बुरी तरह प्रभावित होते हैं। 3. यह वन के भीतरी भाग में रहने वाली प्रजातियों की संख्या सदैव बढ़ाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1","1, 2 और 3"],"explanationHi":"विखंडन भीतरी आवास को घटाता है और किनारे की प्रजातियों को बढ़ावा देता है; भीतरी विशेषज्ञ और दूर-दूर तक घूमने वाले जंतु घटते हैं।"},
  {"id":"env-ecology-194","question":"According to the theory of island biogeography, which of the following islands would be expected to hold the largest number of species at equilibrium?","options":["A small island far from the mainland","A large island close to the mainland","A small island close to the mainland","A large island far from the mainland"],"answer":1,"explanation":"Large islands have lower extinction rates and near islands receive more immigrants; the theory is also used to argue for large, connected protected areas.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"द्वीप जैव-भूगोल के सिद्धांत के अनुसार, निम्नलिखित में से किस द्वीप में संतुलन की स्थिति में सबसे अधिक प्रजातियाँ होने की अपेक्षा की जाएगी?","optionsHi":["मुख्य भूमि से दूर एक छोटा द्वीप","मुख्य भूमि के निकट एक बड़ा द्वीप","मुख्य भूमि के निकट एक छोटा द्वीप","मुख्य भूमि से दूर एक बड़ा द्वीप"],"explanationHi":"बड़े द्वीपों की विलोपन दर कम होती है और निकट के द्वीपों में अधिक आप्रवासी पहुँचते हैं; इस सिद्धांत का उपयोग बड़े, आपस में जुड़े संरक्षित क्षेत्रों के पक्ष में तर्क देने के लिए भी किया जाता है।"},
  {"id":"env-ecology-195","question":"Wildlife corridors that link separate protected areas mainly help conservation by:","options":["Raising tourist numbers and park revenue in each area","Keeping large predators out so that prey populations can recover","Allowing gene flow between populations, which reduces inbreeding","Ending the need for any buffer zone around the protected areas"],"answer":2,"explanation":"Isolated small populations lose genetic diversity and face local extinction; corridors reconnect them and allow seasonal movement and recolonisation.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अलग-अलग संरक्षित क्षेत्रों को जोड़ने वाले वन्यजीव गलियारे मुख्यतः संरक्षण में किस प्रकार सहायक होते हैं?","optionsHi":["प्रत्येक क्षेत्र में पर्यटकों की संख्या और उद्यान का राजस्व बढ़ाकर","बड़े परभक्षियों को बाहर रखकर ताकि शिकार की आबादी पुनः बढ़ सके","आबादियों के बीच जीन प्रवाह की अनुमति देकर, जिससे अंतःप्रजनन घटता है","संरक्षित क्षेत्रों के चारों ओर किसी बफर क्षेत्र की आवश्यकता समाप्त करके"],"explanationHi":"अलग-थलग छोटी आबादियाँ आनुवंशिक विविधता खो देती हैं और स्थानीय विलोपन का सामना करती हैं; गलियारे उन्हें पुनः जोड़ते हैं और मौसमी आवाजाही तथा पुनः बसावट की अनुमति देते हैं।"},
  {"id":"env-ecology-196","question":"Which of the following biodiversity hotspots include part of India's territory? 1. Himalaya 2. Indo-Burma 3. Sundaland 4. Mountains of Southwest China. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2 and 3 only","1, 2, 3 and 4"],"answer":1,"explanation":"India shares the Himalaya, Indo-Burma, Western Ghats–Sri Lanka and Sundaland (through the Nicobar Islands) hotspots; the Mountains of Southwest China hotspot lies wholly outside India.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से जैव विविधता हॉटस्पॉट में भारत का भू-भाग सम्मिलित है? 1. हिमालय 2. इंडो-बर्मा 3. सुंडालैंड 4. दक्षिण-पश्चिम चीन के पर्वत। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2 और 3","1, 2, 3 और 4"],"explanationHi":"भारत हिमालय, इंडो-बर्मा, पश्चिमी घाट–श्रीलंका और सुंडालैंड (निकोबार द्वीप समूह के माध्यम से) हॉटस्पॉट साझा करता है; दक्षिण-पश्चिम चीन के पर्वत हॉटस्पॉट पूरी तरह भारत के बाहर है।"},
  {"id":"env-ecology-197","question":"A species whose only surviving individuals are in zoos and captive-breeding centres, with none left in its natural range, is classified by the IUCN as:","options":["Critically Endangered","Extinct","Extinct in the Wild","Data Deficient"],"answer":2,"explanation":"'Extinct in the Wild' means it survives only in cultivation, in captivity or as a naturalised population well outside its past range; 'Extinct' means no individual survives anywhere.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"वह प्रजाति जिसके केवल जीवित बचे हुए सदस्य चिड़ियाघरों और बंदी-प्रजनन केंद्रों में हैं और अपने प्राकृतिक क्षेत्र में कोई नहीं बचा, उसे IUCN द्वारा किस श्रेणी में रखा जाता है?","optionsHi":["घोर संकटग्रस्त","विलुप्त","जंगल में विलुप्त","आँकड़ों का अभाव"],"explanationHi":"'जंगल में विलुप्त' का अर्थ है कि वह केवल संवर्धन में, बंदी अवस्था में या अपने पूर्व क्षेत्र से बहुत दूर प्राकृतीकृत आबादी के रूप में जीवित है; 'विलुप्त' का अर्थ है कि कहीं भी कोई सदस्य जीवित नहीं है।"},
  {"id":"env-ecology-198","question":"Which of the following IUCN Red List categories are grouped together as 'threatened'? 1. Near Threatened 2. Vulnerable 3. Endangered 4. Critically Endangered. Select the correct answer.","options":["2, 3 and 4 only","1, 2, 3 and 4","3 and 4 only","1 and 4 only"],"answer":0,"explanation":"Only Vulnerable, Endangered and Critically Endangered are 'threatened'; despite its name, Near Threatened is a separate category for species close to qualifying.","difficulty":"hard","source":"UPSC Prelims","questionHi":"IUCN रेड लिस्ट की निम्नलिखित श्रेणियों में से कौन-सी 'संकटग्रस्त (थ्रेटेंड)' के रूप में एक साथ समूहित हैं? 1. संकट के निकट 2. सुभेद्य 3. संकटग्रस्त 4. घोर संकटग्रस्त। सही उत्तर चुनिए।","optionsHi":["केवल 2, 3 और 4","1, 2, 3 और 4","केवल 3 और 4","केवल 1 और 4"],"explanationHi":"केवल सुभेद्य, संकटग्रस्त और घोर संकटग्रस्त ही 'थ्रेटेंड' हैं; नाम के बावजूद, संकट के निकट उन प्रजातियों की एक अलग श्रेणी है जो इस स्तर के निकट हैं।"},
  {"id":"env-ecology-199","question":"With reference to the IUCN Red List, consider the following statements: 1. 'Data Deficient' means a species has been assessed, but there is too little information to judge its risk of extinction. 2. 'Not Evaluated' means a species has not yet been assessed against the Red List criteria. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Both definitions are right; neither category is a threat category, and a Data Deficient species may in fact be at high risk.","difficulty":"hard","source":"UPSC Prelims","questionHi":"IUCN रेड लिस्ट के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए: 1. 'आँकड़ों का अभाव' का अर्थ है कि किसी प्रजाति का आकलन किया गया है, परंतु उसके विलुप्त होने के खतरे का निर्णय करने के लिए जानकारी बहुत कम है। 2. 'मूल्यांकन नहीं किया गया' का अर्थ है कि किसी प्रजाति का रेड लिस्ट मानदंडों के आधार पर अभी आकलन नहीं हुआ है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["1 और 2 दोनों","केवल 1","केवल 2","न तो 1 और न ही 2"],"explanationHi":"दोनों परिभाषाएँ सही हैं; कोई भी श्रेणी खतरे की श्रेणी नहीं है, और आँकड़ों के अभाव वाली प्रजाति वास्तव में उच्च खतरे में हो सकती है।"},
  {"id":"env-ecology-200","question":"Which of the following animals are endemic to the Western Ghats? 1. Lion-tailed macaque 2. Nilgiri tahr 3. Hoolock gibbon 4. Purple frog. Select the correct answer.","options":["1 and 2 only","1, 2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"The lion-tailed macaque, Nilgiri tahr and the burrowing purple frog are found only in the Western Ghats; the hoolock gibbon lives in north-east India and neighbouring countries.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से जंतु पश्चिमी घाट के स्थानिक हैं? 1. शेर-पूँछ वाला मकाक 2. नीलगिरि तहर 3. हूलॉक गिब्बन 4. बैंगनी मेंढक। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 4","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"शेर-पूँछ वाला मकाक, नीलगिरि तहर और बिल बनाने वाला बैंगनी मेंढक केवल पश्चिमी घाट में पाए जाते हैं; हूलॉक गिब्बन पूर्वोत्तर भारत और पड़ोसी देशों में रहता है।"},
  {"id":"env-ecology-201","question":"Consider the following statements about protected areas under the Wildlife (Protection) Act, 1972: 1. Grazing of livestock is not permitted in a national park. 2. Conservation reserves are usually declared on government land, typically adjoining national parks and sanctuaries. 3. Community reserves can be declared on community or private land where the community or individuals have volunteered to conserve wildlife. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The Act bars livestock grazing inside national parks; conservation reserves (government land) and community reserves (community or private land) were added later to link and buffer protected areas.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत संरक्षित क्षेत्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. राष्ट्रीय उद्यान में पशुओं की चराई की अनुमति नहीं है। 2. संरक्षण रिज़र्व सामान्यतः सरकारी भूमि पर घोषित किए जाते हैं, प्रायः राष्ट्रीय उद्यानों और अभयारण्यों से सटे हुए। 3. सामुदायिक रिज़र्व उस सामुदायिक या निजी भूमि पर घोषित किए जा सकते हैं जहाँ समुदाय या व्यक्तियों ने स्वेच्छा से वन्यजीव संरक्षण का दायित्व लिया हो। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अधिनियम राष्ट्रीय उद्यानों के भीतर पशुओं की चराई को रोकता है; संरक्षण रिज़र्व (सरकारी भूमि) और सामुदायिक रिज़र्व (सामुदायिक या निजी भूमि) बाद में संरक्षित क्षेत्रों को जोड़ने और उनके लिए बफर बनाने हेतु जोड़े गए।"},
  {"id":"env-ecology-202","question":"Consider the following statements about biosphere reserves in India: 1. They are notified under the Wildlife (Protection) Act, 1972. 2. The core zone of a biosphere reserve often consists of a national park or wildlife sanctuary. 3. A biosphere reserve must first be included in UNESCO's Man and the Biosphere network before India can designate it. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Biosphere reserves are not a category under the Wildlife Act; they are designated by the Central Government, and only some of India's reserves are in UNESCO's world network.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत के जैवमंडल आरक्षित क्षेत्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वे वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत अधिसूचित किए जाते हैं। 2. जैवमंडल आरक्षित क्षेत्र का कोर क्षेत्र प्रायः राष्ट्रीय उद्यान या वन्यजीव अभयारण्य से बना होता है। 3. भारत द्वारा किसी जैवमंडल आरक्षित क्षेत्र को नामित करने से पहले उसे यूनेस्को के मानव और जैवमंडल नेटवर्क में शामिल किया जाना आवश्यक है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"जैवमंडल आरक्षित क्षेत्र वन्यजीव अधिनियम के अंतर्गत कोई श्रेणी नहीं हैं; उन्हें केंद्र सरकार नामित करती है, और भारत के केवल कुछ आरक्षित क्षेत्र यूनेस्को के विश्व नेटवर्क में हैं।"},
  {"id":"env-ecology-203","question":"In the IUCN system of protected area management categories, Category II corresponds to:","options":["Strict nature reserve","National park","Protected landscape or seascape","Habitat or species management area"],"answer":1,"explanation":"Category Ia is strict nature reserve, Ib wilderness area, II national park, III natural monument, IV habitat/species management area, V protected landscape/seascape and VI protected area with sustainable use.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संरक्षित क्षेत्र प्रबंधन की IUCN श्रेणी प्रणाली में श्रेणी II किसके अनुरूप है?","optionsHi":["कठोर प्रकृति आरक्षित क्षेत्र","राष्ट्रीय उद्यान","संरक्षित भू-दृश्य या समुद्र-दृश्य","आवास या प्रजाति प्रबंधन क्षेत्र"],"explanationHi":"श्रेणी Ia कठोर प्रकृति आरक्षित क्षेत्र है, Ib वन्य क्षेत्र, II राष्ट्रीय उद्यान, III प्राकृतिक स्मारक, IV आवास/प्रजाति प्रबंधन क्षेत्र, V संरक्षित भू-दृश्य/समुद्र-दृश्य और VI प्राकृतिक संसाधनों के सतत उपयोग वाला संरक्षित क्षेत्र।"},
  {"id":"env-ecology-204","question":"Which IUCN protected area management category has the sustainable, low-level use of natural resources as one of its main aims?","options":["Category Ia","Category III","Category VI","Category Ib"],"answer":2,"explanation":"Category VI, protected area with sustainable use of natural resources, allows non-industrial use compatible with conservation; Ia and Ib are the strictest categories.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"किस IUCN संरक्षित क्षेत्र प्रबंधन श्रेणी का एक प्रमुख उद्देश्य प्राकृतिक संसाधनों का सतत, निम्न-स्तरीय उपयोग है?","optionsHi":["श्रेणी Ia","श्रेणी III","श्रेणी VI","श्रेणी Ib"],"explanationHi":"श्रेणी VI, प्राकृतिक संसाधनों के सतत उपयोग वाला संरक्षित क्षेत्र, संरक्षण के अनुकूल गैर-औद्योगिक उपयोग की अनुमति देती है; Ia और Ib सबसे कठोर श्रेणियाँ हैं।"},
  {"id":"env-ecology-205","question":"The Svalbard Global Seed Vault, which stores duplicate seed samples from gene banks around the world, is located in:","options":["Norway","Iceland","Greenland","Sweden"],"answer":0,"explanation":"The vault is dug into a mountain on the Arctic archipelago of Svalbard, which belongs to Norway; the permafrost keeps the samples cold even if power fails.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"स्वालबार्ड ग्लोबल सीड वॉल्ट, जो विश्व भर के जीन बैंकों के बीजों के प्रतिरूप नमूने संग्रहीत करता है, कहाँ स्थित है?","optionsHi":["नॉर्वे","आइसलैंड","ग्रीनलैंड","स्वीडन"],"explanationHi":"यह वॉल्ट आर्कटिक द्वीपसमूह स्वालबार्ड में एक पर्वत में खोदा गया है, जो नॉर्वे का भाग है; पर्माफ्रॉस्ट बिजली जाने पर भी नमूनों को ठंडा रखता है।"},
  {"id":"env-ecology-206","question":"Seeds of mango, jackfruit and cocoa are poorly suited to storage in a conventional seed bank. This is because such seeds:","options":["Are too small to be handled individually","Contain toxins that build up during storage","Germinate only after passing through an animal's gut","Are recalcitrant and die when dried for storage"],"answer":3,"explanation":"Seed banks dry and freeze 'orthodox' seeds; recalcitrant seeds die when dried, so they are conserved in field gene banks, by tissue culture or by cryopreserving embryos.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आम, कटहल और कोको के बीज पारंपरिक बीज बैंक में संग्रहण के लिए उपयुक्त नहीं होते। इसका कारण यह है कि ऐसे बीज:","optionsHi":["इतने छोटे होते हैं कि उन्हें अलग-अलग संभालना कठिन है","उनमें विषैले पदार्थ होते हैं जो भंडारण के दौरान जमा होते जाते हैं","केवल किसी जंतु की आँत से गुज़रने के बाद अंकुरित होते हैं","अशुष्कसह (रिकैल्सिट्रैंट) होते हैं और भंडारण के लिए सुखाने पर मर जाते हैं"],"explanationHi":"बीज बैंक 'ऑर्थोडॉक्स' बीजों को सुखाते और जमाते हैं; रिकैल्सिट्रैंट बीज सुखाने पर मर जाते हैं, इसलिए उनका संरक्षण क्षेत्रीय जीन बैंकों में, ऊतक संवर्धन से या भ्रूणों के क्रायोप्रिज़र्वेशन से किया जाता है।"},
  {"id":"env-ecology-207","question":"The 'Montreux Record' maintained under the Ramsar Convention is:","options":["A list of the largest wetlands in each member country","A register of wetlands nominated but not yet accepted as Ramsar sites","Ramsar sites where human activity has changed or may change ecology","A list of wetlands formally removed from the Ramsar List after degradation"],"answer":2,"explanation":"Sites are placed on the Montreux Record to flag them for priority conservation attention and can be removed once restored.","difficulty":"hard","source":"UPSC Prelims","questionHi":"रामसर कन्वेंशन के अंतर्गत रखा गया 'मॉन्ट्रो रिकॉर्ड' क्या है?","optionsHi":["प्रत्येक सदस्य देश की सबसे बड़ी आर्द्रभूमियों की सूची","नामित की गई परंतु अभी रामसर स्थल के रूप में स्वीकृत न हुई आर्द्रभूमियों का रजिस्टर","वे रामसर स्थल जहाँ मानवीय गतिविधि ने पारिस्थितिकी को बदल दिया है या बदल सकती है","क्षरण के बाद रामसर सूची से औपचारिक रूप से हटाई गई आर्द्रभूमियों की सूची"],"explanationHi":"स्थलों को प्राथमिकता वाले संरक्षण ध्यान के लिए चिह्नित करने हेतु मॉन्ट्रो रिकॉर्ड में रखा जाता है और पुनर्स्थापन के बाद हटाया जा सकता है।"},
  {"id":"env-ecology-208","question":"Consider the following statements about the definition of wetlands under the Ramsar Convention: 1. Areas of marine water whose depth at low tide does not exceed six metres can be wetlands. 2. Human-made sites such as rice paddies and fish ponds can be classified as wetlands. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"The Ramsar definition is very broad: it includes shallow marine waters up to six metres at low tide, and its classification lists human-made wetlands such as paddies, reservoirs and fish ponds.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"रामसर कन्वेंशन के अंतर्गत आर्द्रभूमियों की परिभाषा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. समुद्री जल के वे क्षेत्र जिनकी गहराई निम्न ज्वार पर छह मीटर से अधिक न हो, आर्द्रभूमि हो सकते हैं। 2. धान के खेत और मछली तालाब जैसे मानव-निर्मित स्थल आर्द्रभूमि के रूप में वर्गीकृत हो सकते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"रामसर की परिभाषा बहुत व्यापक है: इसमें निम्न ज्वार पर छह मीटर तक का उथला समुद्री जल शामिल है, और इसकी वर्गीकरण सूची में धान के खेत, जलाशय और मछली तालाब जैसी मानव-निर्मित आर्द्रभूमियाँ भी हैं।"},
  {"id":"env-ecology-209","question":"Consider the following statements: 1. The Ramsar Convention is not part of the United Nations system of environmental treaties, although UNESCO acts as its depositary. 2. World Wetlands Day is observed on 2 February, the date on which the Convention was adopted. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"The Ramsar Convention is an independent treaty with its own secretariat, and it was adopted at Ramsar, Iran, on 2 February 1971.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. रामसर कन्वेंशन संयुक्त राष्ट्र की पर्यावरण संधि प्रणाली का भाग नहीं है, यद्यपि यूनेस्को इसके निक्षेपागार (डिपॉज़िटरी) के रूप में कार्य करता है। 2. विश्व आर्द्रभूमि दिवस 2 फरवरी को मनाया जाता है, जिस दिन कन्वेंशन अपनाया गया था। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"रामसर कन्वेंशन अपने स्वयं के सचिवालय वाली एक स्वतंत्र संधि है, और इसे 2 फरवरी 1971 को ईरान के रामसर में अपनाया गया था।"},
  {"id":"env-ecology-210","question":"Consider the following statements about coral reefs in India: 1. Most of the Lakshadweep islands are coral atolls. 2. The reefs of the Gulf of Mannar are mainly fringing reefs around a chain of small islands. 3. Reef-building corals grow best in cold, nutrient-rich water. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Reef corals need warm, clear, nutrient-poor water; nutrient-rich water favours algae that smother corals.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत में प्रवाल भित्तियों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. लक्षद्वीप के अधिकांश द्वीप प्रवाल एटॉल हैं। 2. मन्नार की खाड़ी की भित्तियाँ मुख्यतः छोटे द्वीपों की एक शृंखला के चारों ओर तटीय (फ्रिंजिंग) भित्तियाँ हैं। 3. भित्ति-निर्माता प्रवाल ठंडे, पोषक-समृद्ध जल में सबसे अच्छे उगते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"भित्ति प्रवालों को गर्म, स्वच्छ, पोषक-निर्धन जल चाहिए; पोषक-समृद्ध जल उन शैवालों को बढ़ावा देता है जो प्रवालों को ढक लेते हैं।"},
  {"id":"env-ecology-211","question":"Reef-building corals are mostly restricted to shallow, clear water. The main reason is that:","options":["Water pressure at depth crushes their calcium carbonate skeletons","Their symbiotic zooxanthellae need sunlight to photosynthesise","Deep water is too salty and too cold for corals","Corals feed only on plankton found near the surface"],"answer":1,"explanation":"Much of a reef coral's food comes from the photosynthesis of zooxanthellae in its tissues, so reefs grow only where enough light penetrates.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"भित्ति-निर्माता प्रवाल अधिकांशतः उथले, स्वच्छ जल तक सीमित होते हैं। इसका मुख्य कारण यह है कि:","optionsHi":["गहराई पर जल का दाब उनके कैल्शियम कार्बोनेट कंकाल को कुचल देता है","उनके सहजीवी ज़ूज़ैन्थेली को प्रकाश-संश्लेषण के लिए सूर्य के प्रकाश की आवश्यकता होती है","गहरा जल प्रवालों के लिए बहुत खारा और बहुत ठंडा होता है","प्रवाल केवल सतह के निकट पाए जाने वाले प्लवकों पर निर्भर रहते हैं"],"explanationHi":"भित्ति प्रवाल के भोजन का बड़ा भाग उसके ऊतकों में स्थित ज़ूज़ैन्थेली के प्रकाश-संश्लेषण से आता है, इसलिए भित्तियाँ केवल वहीं उगती हैं जहाँ पर्याप्त प्रकाश पहुँचता है।"},
  {"id":"env-ecology-212","question":"Estuaries are among the most productive ecosystems on Earth. Which of the following contribute to this? 1. Rivers and tides bring in nutrients. 2. The mixing of fresh and salt water tends to trap nutrients within the estuary. 3. Salinity stays constant throughout the year. Select the correct answer.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Estuaries are nutrient traps fed from both river and sea; their salinity fluctuates widely with tides and seasons, so organisms there must be euryhaline.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मुहाने (एस्चुअरी) पृथ्वी के सबसे उत्पादक पारिस्थितिकी तंत्रों में से हैं। इसमें निम्नलिखित में से कौन-से योगदान करते हैं? 1. नदियाँ और ज्वार पोषक तत्व लाते हैं। 2. मीठे और खारे जल का मिश्रण पोषक तत्वों को मुहाने के भीतर फँसा लेता है। 3. लवणता पूरे वर्ष स्थिर रहती है। सही उत्तर चुनिए।","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"मुहाने पोषक तत्वों के जाल हैं जिन्हें नदी और समुद्र दोनों से पोषण मिलता है; उनकी लवणता ज्वार और ऋतुओं के साथ बहुत बदलती है, इसलिए वहाँ के जीवों को यूरीहैलाइन होना पड़ता है।"},
  {"id":"env-ecology-213","question":"Consider the following statements about seagrasses: 1. Seagrasses are flowering plants, not algae. 2. The dugong feeds mainly on seagrass. 3. Seagrass meadows store significant amounts of 'blue carbon' in their sediments. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":3,"explanation":"Seagrasses have roots, leaves and flowers, unlike seaweeds (algae); they are grazed by dugongs and turtles, and their sediments lock away carbon for long periods.","difficulty":"hard","source":"UPSC Prelims","questionHi":"समुद्री घासों (सीग्रास) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. समुद्री घास पुष्पीय पौधे हैं, शैवाल नहीं। 2. डुगोंग मुख्यतः समुद्री घास खाता है। 3. समुद्री घास के मैदान अपने तलछट में महत्वपूर्ण मात्रा में 'ब्लू कार्बन' संचित करते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1","1, 2 और 3"],"explanationHi":"समुद्री घासों में, समुद्री शैवालों (एल्गी) के विपरीत, जड़, पत्तियाँ और फूल होते हैं; उन्हें डुगोंग और कछुए चरते हैं, और उनका तलछट कार्बन को लंबे समय तक बाँधे रखता है।"},
  {"id":"env-ecology-214","question":"Assertion (A): Peatlands are important long-term stores of carbon. Reason (R): Peat forms because decomposition is unusually fast in waterlogged soils. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Peat builds up because waterlogged, oxygen-poor and often acidic conditions slow decomposition, so plant matter accumulates faster than it rots.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): पीटभूमियाँ कार्बन के महत्वपूर्ण दीर्घकालिक भंडार हैं। कारण (R): पीट इसलिए बनती है क्योंकि जलमग्न मिट्टी में अपघटन असामान्य रूप से तेज़ होता है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"पीट इसलिए जमा होती है क्योंकि जलमग्न, ऑक्सीजन-रहित और प्रायः अम्लीय परिस्थितियाँ अपघटन को धीमा कर देती हैं, इसलिए वनस्पति पदार्थ सड़ने से अधिक तेज़ी से जमा होता है।"},
  {"id":"env-ecology-215","question":"Consider the following statements: 1. Sholas are patches of stunted evergreen forest found together with grasslands in the high-altitude valleys of the southern Western Ghats. 2. The Banni grasslands lie in the Kachchh district of Gujarat. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"The shola–grassland mosaic is typical of the Nilgiris, Anamalais and Palanis; Banni is a large tropical grassland on the edge of the Rann of Kachchh.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. शोला दक्षिणी पश्चिमी घाट की ऊँची घाटियों में घास के मैदानों के साथ पाए जाने वाले बौने सदाबहार वन के टुकड़े हैं। 2. बन्नी घास के मैदान गुजरात के कच्छ ज़िले में स्थित हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["1 और 2 दोनों","केवल 1","केवल 2","न तो 1 और न ही 2"],"explanationHi":"शोला–घास के मैदान का मोज़ेक नीलगिरि, अन्नामलाई और पलनी पहाड़ियों की विशेषता है; बन्नी कच्छ के रण के किनारे स्थित एक बड़ा उष्णकटिबंधीय घास का मैदान है।"},
  {"id":"env-ecology-216","question":"Consider the following statements about India's biodiversity: 1. India has about 2.4 per cent of the world's land area. 2. India accounts for roughly 7–8 per cent of the world's recorded species. 3. India is counted among the megadiverse countries of the world. Which of the statements given above are correct?","options":["1 and 3 only","1, 2 and 3","2 only","3 only"],"answer":1,"explanation":"All three are standard: a small share of the land area holds a disproportionately large share of species, which places India among the megadiverse countries.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत की जैव विविधता के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. भारत के पास विश्व के भूभाग का लगभग 2.4 प्रतिशत है। 2. भारत में विश्व की दर्ज प्रजातियों का लगभग 7–8 प्रतिशत पाया जाता है। 3. भारत की गणना विश्व के महाविविध देशों में होती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","1, 2 और 3","केवल 2","केवल 3"],"explanationHi":"तीनों मानक तथ्य हैं: भूभाग का एक छोटा हिस्सा प्रजातियों के अनुपात से कहीं बड़े हिस्से को धारण करता है, जिससे भारत महाविविध देशों में गिना जाता है।"},
  {"id":"env-ecology-217","question":"Of the biogeographic zones into which India is divided, which one covers the largest area?","options":["Western Ghats","Himalaya","Deccan Peninsula","Gangetic Plain"],"answer":2,"explanation":"The Deccan Peninsula zone covers over two-fifths of the country; the Western Ghats, though rich in endemics, is a narrow zone.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत जिन जैव-भौगोलिक क्षेत्रों में विभाजित है, उनमें से कौन-सा सबसे बड़े क्षेत्रफल को घेरता है?","optionsHi":["पश्चिमी घाट","हिमालय","दक्कन प्रायद्वीप","गंगा का मैदान"],"explanationHi":"दक्कन प्रायद्वीप क्षेत्र देश के दो-पाँचवें से अधिक भाग को घेरता है; पश्चिमी घाट स्थानिक प्रजातियों में समृद्ध होने पर भी एक संकरा क्षेत्र है।"},
  {"id":"env-ecology-218","question":"Which of the following animals are characteristic of the Trans-Himalayan cold desert of Ladakh? 1. Kiang (Tibetan wild ass) 2. Black-necked crane 3. Nilgai 4. Tibetan antelope (chiru). Select the correct answer.","options":["1, 2 and 4 only","1 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"The kiang, chiru and breeding black-necked cranes belong to the high Tibetan plateau; the nilgai is an antelope of the plains and dry forests.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से जंतु लद्दाख के ट्रांस-हिमालयी शीत मरुस्थल के विशिष्ट हैं? 1. कियांग (तिब्बती जंगली गधा) 2. काली गर्दन वाला सारस 3. नीलगाय 4. तिब्बती चिरू (चिरू)। सही उत्तर चुनिए।","optionsHi":["केवल 1, 2 और 4","केवल 1 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"कियांग, चिरू और प्रजनन करते काली गर्दन वाले सारस ऊँचे तिब्बती पठार के हैं; नीलगाय मैदानों और शुष्क वनों का मृग है।"},
  {"id":"env-ecology-219","question":"In the wild, the Indian wild ass (khur) is now found only in:","options":["The Changthang plateau of Ladakh","The Desert National Park in Rajasthan","The Chambal ravines","The Rann of Kachchh region of Gujarat"],"answer":3,"explanation":"The khur survives in the Little Rann and surrounding areas of Gujarat; the wild ass of Ladakh is the kiang, a different species.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"जंगल में भारतीय जंगली गधा (खुर) अब केवल कहाँ पाया जाता है?","optionsHi":["लद्दाख का चांगथांग पठार","राजस्थान का डेज़र्ट नेशनल पार्क","चंबल के बीहड़","गुजरात का कच्छ का रण क्षेत्र"],"explanationHi":"खुर गुजरात के छोटे रण और आसपास के क्षेत्रों में जीवित है; लद्दाख का जंगली गधा कियांग है, जो एक भिन्न प्रजाति है।"},
  {"id":"env-ecology-220","question":"Consider the following statements: 1. The gharial is a fish-eating crocodilian with a long, narrow snout. 2. The National Chambal Sanctuary extends over Rajasthan, Madhya Pradesh and Uttar Pradesh. 3. The mugger crocodile is found only in brackish mangrove waters. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The mugger is a freshwater crocodile of rivers, lakes and reservoirs; the estuarine (saltwater) crocodile is the one found in mangroves such as Bhitarkanika and the Sundarbans.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. घड़ियाल मछली खाने वाला मगरमच्छ-वर्गीय जीव है जिसकी थूथन लंबी और पतली होती है। 2. राष्ट्रीय चंबल अभयारण्य राजस्थान, मध्य प्रदेश और उत्तर प्रदेश में फैला है। 3. मगर (मगरमच्छ) केवल खारे मैंग्रोव जल में पाया जाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"मगर नदियों, झीलों और जलाशयों का मीठे पानी का मगरमच्छ है; भितरकनिका और सुंदरबन जैसे मैंग्रोव में पाया जाने वाला खारे पानी का मगरमच्छ मुहाना (एस्चुअराइन) मगरमच्छ है।"},
  {"id":"env-ecology-221","question":"A species with very large area requirements, whose protection automatically conserves many other species that share its habitat, is called a(n):","options":["Keystone species","Indicator species","Flagship species","Umbrella species"],"answer":3,"explanation":"Umbrella species are chosen for their range; flagship species for public appeal, keystone species for their outsized ecological role, and indicator species for revealing environmental conditions.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वह प्रजाति जिसे बहुत बड़े क्षेत्र की आवश्यकता होती है और जिसकी रक्षा से उसके आवास में साथ रहने वाली अनेक अन्य प्रजातियाँ स्वतः संरक्षित हो जाती हैं, क्या कहलाती है?","optionsHi":["कीस्टोन प्रजाति","सूचक प्रजाति","प्रमुख (फ्लैगशिप) प्रजाति","छत्र (अम्ब्रेला) प्रजाति"],"explanationHi":"छत्र प्रजातियाँ अपने विचरण क्षेत्र के कारण चुनी जाती हैं; फ्लैगशिप प्रजातियाँ जन-अपील के लिए, कीस्टोन प्रजातियाँ अपनी असाधारण पारिस्थितिक भूमिका के लिए, और सूचक प्रजातियाँ पर्यावरणीय स्थितियों को प्रकट करने के लिए।"},
  {"id":"env-ecology-222","question":"Consider the following statements: 1. Biopiracy is the use of biological resources or traditional knowledge without proper authorisation or compensation to the communities concerned. 2. India's Traditional Knowledge Digital Library was created to help patent offices avoid granting patents on existing traditional knowledge. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Episodes such as patents on turmeric and neem led India to document traditional knowledge so that patent examiners could find it as prior art.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. जैव-चोरी (बायोपायरेसी) जैविक संसाधनों या पारंपरिक ज्ञान का संबंधित समुदायों की उचित अनुमति या क्षतिपूर्ति के बिना उपयोग है। 2. भारत की पारंपरिक ज्ञान डिजिटल लाइब्रेरी इसलिए बनाई गई ताकि पेटेंट कार्यालय मौजूदा पारंपरिक ज्ञान पर पेटेंट देने से बच सकें। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"हल्दी और नीम पर पेटेंट जैसी घटनाओं ने भारत को पारंपरिक ज्ञान का दस्तावेज़ीकरण करने के लिए प्रेरित किया ताकि पेटेंट परीक्षक उसे पूर्व-कला (प्रायर आर्ट) के रूप में पा सकें।"},
  {"id":"env-ecology-223","question":"Consider the following statements about the Biological Diversity Act, 2002: 1. The National Biodiversity Authority set up under it is headquartered at Chennai. 2. Biodiversity Management Committees are formed by local bodies and maintain People's Biodiversity Registers. 3. The Act was passed to give effect to India's commitments under the Convention on Biological Diversity. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The Act sets up a three-tier structure (NBA at Chennai, State Biodiversity Boards, local BMCs) to regulate access to biological resources and share benefits, as the CBD requires.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैविक विविधता अधिनियम, 2002 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसके अंतर्गत स्थापित राष्ट्रीय जैव विविधता प्राधिकरण का मुख्यालय चेन्नई में है। 2. जैव विविधता प्रबंधन समितियाँ स्थानीय निकायों द्वारा गठित की जाती हैं और लोक जैव विविधता रजिस्टर बनाए रखती हैं। 3. यह अधिनियम जैव विविधता पर कन्वेंशन के अंतर्गत भारत की प्रतिबद्धताओं को प्रभावी करने के लिए पारित किया गया। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अधिनियम जैविक संसाधनों तक पहुँच को विनियमित करने और लाभ बाँटने के लिए, जैसा CBD अपेक्षित करता है, त्रि-स्तरीय ढाँचा बनाता है (चेन्नई में NBA, राज्य जैव विविधता बोर्ड, स्थानीय BMCs)।"},
  {"id":"env-ecology-224","question":"Which one of the following pairs of extinct animal and its former home is NOT correctly matched?","options":["Dodo — Mauritius","Quagga — southern Africa","Thylacine — Tasmania and mainland Australia","Steller's sea cow — the Indian Ocean"],"answer":3,"explanation":"Steller's sea cow lived in the Bering Sea of the North Pacific and was hunted out within decades of its discovery in the eighteenth century.","difficulty":"hard","source":"UPSC Prelims","questionHi":"विलुप्त जंतु और उसके पूर्व निवास की निम्नलिखित जोड़ियों में से कौन-सी सही सुमेलित नहीं है?","optionsHi":["डोडो — मॉरीशस","क्वागा — दक्षिणी अफ्रीका","थायलासीन — तस्मानिया और मुख्य भूमि ऑस्ट्रेलिया","स्टेलर की समुद्री गाय — हिंद महासागर"],"explanationHi":"स्टेलर की समुद्री गाय उत्तरी प्रशांत के बेरिंग सागर में रहती थी और अठारहवीं शताब्दी में उसकी खोज के कुछ ही दशकों में शिकार करके समाप्त कर दी गई।"},
  {"id":"env-ecology-225","question":"Amphibians are often regarded as especially sensitive indicators of environmental change. Which of the following help explain this? 1. Their permeable skin readily absorbs chemicals from water and soil. 2. Their life cycle spans both water and land, exposing them to conditions in both. 3. Their hard-shelled eggs let toxins accumulate inside before hatching. Select the correct answer.","options":["1 and 2 only","1, 2 and 3","2 only","1 and 3 only"],"answer":0,"explanation":"Thin, permeable skin and a two-habitat life cycle expose amphibians to pollution in water and on land; their eggs are soft and jelly-coated, not hard-shelled, which is a reptile and bird feature.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उभयचरों को प्रायः पर्यावरणीय परिवर्तन के विशेष रूप से संवेदनशील सूचक माना जाता है। इसकी व्याख्या में निम्नलिखित में से कौन-से सहायक हैं? 1. उनकी पारगम्य त्वचा जल और मिट्टी से रसायनों को सहज रूप से अवशोषित कर लेती है। 2. उनका जीवन चक्र जल और स्थल दोनों में फैला होता है, जिससे वे दोनों की परिस्थितियों के संपर्क में आते हैं। 3. उनके कठोर आवरण वाले अंडे अंडे से निकलने से पहले भीतर विषैले पदार्थ जमा होने देते हैं। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","1, 2 और 3","केवल 2","केवल 1 और 3"],"explanationHi":"पतली, पारगम्य त्वचा और दो-आवासीय जीवन चक्र उभयचरों को जल और स्थल दोनों पर प्रदूषण के संपर्क में लाते हैं; उनके अंडे कोमल और जेली-लेपित होते हैं, कठोर आवरण वाले नहीं, जो सरीसृपों और पक्षियों की विशेषता है।"},
  {"id":"env-ecology-226","question":"Electrostatic precipitators fitted to the chimneys of coal-based thermal power plants are designed mainly to remove:","options":["Sulphur dioxide from the flue gas","Nitrogen oxides","Particulate matter (fly ash)","Carbon dioxide"],"answer":2,"explanation":"An ESP charges dust particles in the flue gas and collects them on oppositely charged plates; gases such as SO2 need scrubbers or flue-gas desulphurisation.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"कोयला-आधारित ताप विद्युत संयंत्रों की चिमनियों में लगाए गए स्थिर-वैद्युत अवक्षेपित्र (इलेक्ट्रोस्टैटिक प्रेसिपिटेटर) मुख्यतः किसे हटाने के लिए बनाए गए हैं?","optionsHi":["ग्रिप गैस से सल्फर डाइऑक्साइड","नाइट्रोजन ऑक्साइड","कणिकीय पदार्थ (फ्लाई ऐश)","कार्बन डाइऑक्साइड"],"explanationHi":"ESP ग्रिप गैस में धूल के कणों को आवेशित करता है और उन्हें विपरीत आवेशित प्लेटों पर एकत्र करता है; SO2 जैसी गैसों के लिए स्क्रबर या ग्रिप-गैस विसल्फरीकरण चाहिए।"},
  {"id":"env-ecology-227","question":"Consider the following statements about controlling emissions from power plants: 1. In flue-gas desulphurisation, limestone slurry reacts with sulphur dioxide to form gypsum. 2. A wet scrubber can remove gases such as sulphur dioxide as well as some particles. 3. The electrostatic precipitator is the main device for removing sulphur dioxide. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":1,"explanation":"ESPs remove particles, not gases; SO2 is absorbed in scrubbers, and limestone-based FGD gives gypsum as a by-product.","difficulty":"hard","source":"UPSC Prelims","questionHi":"विद्युत संयंत्रों से उत्सर्जन नियंत्रण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. ग्रिप-गैस विसल्फरीकरण में चूना-पत्थर की स्लरी सल्फर डाइऑक्साइड से अभिक्रिया कर जिप्सम बनाती है। 2. आर्द्र स्क्रबर सल्फर डाइऑक्साइड जैसी गैसों के साथ-साथ कुछ कणों को भी हटा सकता है। 3. स्थिर-वैद्युत अवक्षेपित्र सल्फर डाइऑक्साइड हटाने का मुख्य उपकरण है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 1 और 2","केवल 2","केवल 1 और 3"],"explanationHi":"ESP कणों को हटाते हैं, गैसों को नहीं; SO2 स्क्रबरों में अवशोषित होती है, और चूना-पत्थर आधारित FGD उप-उत्पाद के रूप में जिप्सम देता है।"},
  {"id":"env-ecology-228","question":"Consider the following statements about the three-way catalytic converter of a petrol vehicle: 1. It converts unburnt hydrocarbons into carbon dioxide and water. 2. It converts nitric oxide into nitrogen gas. 3. Vehicles fitted with it must use unleaded petrol, because lead inactivates the catalyst. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Platinum, palladium and rhodium oxidise CO and hydrocarbons and reduce NO to N2; lead coats and poisons the catalyst, which is one reason leaded petrol was phased out.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पेट्रोल वाहन के त्रि-मार्ग उत्प्रेरक परिवर्तक (थ्री-वे कैटेलिटिक कन्वर्टर) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह अदग्ध हाइड्रोकार्बनों को कार्बन डाइऑक्साइड और जल में बदलता है। 2. यह नाइट्रिक ऑक्साइड को नाइट्रोजन गैस में बदलता है। 3. इससे सुसज्जित वाहनों में सीसा-रहित पेट्रोल का ही उपयोग करना चाहिए, क्योंकि सीसा उत्प्रेरक को निष्क्रिय कर देता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"प्लैटिनम, पैलेडियम और रोडियम CO और हाइड्रोकार्बनों का ऑक्सीकरण करते हैं और NO को N2 में अपचयित करते हैं; सीसा उत्प्रेरक पर परत बनाकर उसे विषाक्त कर देता है, यही सीसायुक्त पेट्रोल को चरणबद्ध ढंग से हटाने का एक कारण था।"},
  {"id":"env-ecology-229","question":"Modern diesel vehicles inject a urea solution ('diesel exhaust fluid') into the exhaust ahead of a catalyst. This system is designed to reduce emissions of:","options":["Nitrogen oxides","Particulate matter (soot)","Carbon monoxide","Sulphur dioxide"],"answer":0,"explanation":"In selective catalytic reduction, ammonia from urea reduces NOx to nitrogen and water; soot is trapped by a separate particulate filter.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आधुनिक डीज़ल वाहन उत्प्रेरक से पहले निकास में यूरिया घोल ('डीज़ल एग्ज़ॉस्ट फ्लूइड') डालते हैं। यह प्रणाली किसके उत्सर्जन को घटाने के लिए बनाई गई है?","optionsHi":["नाइट्रोजन ऑक्साइड","कणिकीय पदार्थ (कालिख)","कार्बन मोनोऑक्साइड","सल्फर डाइऑक्साइड"],"explanationHi":"चयनात्मक उत्प्रेरकीय अपचयन में यूरिया से बनी अमोनिया NOx को नाइट्रोजन और जल में अपचयित करती है; कालिख एक अलग कणिका फ़िल्टर द्वारा रोकी जाती है।"},
  {"id":"env-ecology-230","question":"Consider the following statements about ozone near the ground: 1. It is a secondary pollutant. 2. Its concentration in cities usually peaks in the afternoon on sunny days. 3. It is emitted directly in large amounts from vehicle exhausts. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"Ground-level ozone is formed when nitrogen oxides and volatile organic compounds react in sunlight, so it is not emitted directly and builds up through the sunny part of the day.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भू-स्तर के निकट की ओज़ोन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह एक द्वितीयक प्रदूषक है। 2. धूप वाले दिनों में शहरों में इसकी सांद्रता सामान्यतः दोपहर बाद चरम पर होती है। 3. यह वाहनों के निकास से सीधे बड़ी मात्रा में उत्सर्जित होती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1","1, 2 और 3"],"explanationHi":"भू-स्तरीय ओज़ोन तब बनती है जब नाइट्रोजन ऑक्साइड और वाष्पशील कार्बनिक यौगिक सूर्य के प्रकाश में अभिक्रिया करते हैं, इसलिए यह सीधे उत्सर्जित नहीं होती और दिन के धूप वाले भाग में बढ़ती जाती है।"},
  {"id":"env-ecology-231","question":"Which of the following are secondary air pollutants, formed in the atmosphere rather than emitted directly? 1. Peroxyacetyl nitrate (PAN) 2. Ground-level ozone 3. Carbon monoxide 4. Sulphuric acid aerosol. Select the correct answer.","options":["1 and 2 only","1, 2 and 4 only","3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"PAN, ozone and sulphate aerosols form by reactions of emitted gases; carbon monoxide is emitted directly from incomplete combustion, so it is primary.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से द्वितीयक वायु प्रदूषक हैं, जो सीधे उत्सर्जित होने के बजाय वायुमंडल में बनते हैं? 1. परॉक्सीएसिटाइल नाइट्रेट (PAN) 2. भू-स्तरीय ओज़ोन 3. कार्बन मोनोऑक्साइड 4. सल्फ्यूरिक अम्ल एरोसोल। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 4","केवल 3 और 4","1, 2, 3 और 4"],"explanationHi":"PAN, ओज़ोन और सल्फेट एरोसोल उत्सर्जित गैसों की अभिक्रियाओं से बनते हैं; कार्बन मोनोऑक्साइड अपूर्ण दहन से सीधे उत्सर्जित होती है, इसलिए प्राथमिक है।"},
  {"id":"env-ecology-232","question":"Which of the following correctly describes classical (London-type) smog?","options":["It is oxidising in nature and forms on warm, sunny summer afternoons","Smoke, fog and SO2 mixed in cool, damp air; chemically reducing","Its main constituents are ozone and peroxyacetyl nitrate","It forms only in the upper troposphere, far above cities"],"answer":1,"explanation":"London smog (as in 1952) comes from coal smoke and SO2 in cold, damp, still air; ozone and PAN are the oxidising components of photochemical (Los Angeles-type) smog.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा परंपरागत (लंदन-प्रकार के) स्मॉग का सही वर्णन करता है?","optionsHi":["यह ऑक्सीकारी प्रकृति का होता है और गर्म, धूप वाली गर्मियों की दोपहर में बनता है","ठंडी, नम वायु में मिला धुआँ, कोहरा और SO2; रासायनिक रूप से अपचायक","इसके मुख्य घटक ओज़ोन और परॉक्सीएसिटाइल नाइट्रेट हैं","यह केवल ऊपरी क्षोभमंडल में, शहरों से बहुत ऊपर बनता है"],"explanationHi":"लंदन स्मॉग (जैसा 1952 में) ठंडी, नम, शांत वायु में कोयले के धुएँ और SO2 से बनता है; ओज़ोन और PAN प्रकाश-रासायनिक (लॉस एंजिल्स-प्रकार के) स्मॉग के ऑक्सीकारी घटक हैं।"},
  {"id":"env-ecology-233","question":"Consider the following statements about indoor air pollution: 1. Radon, a colourless, odourless radioactive gas, can seep into buildings from the ground. 2. Burning biomass in traditional cookstoves exposes women and children to high levels of particulates and carbon monoxide. 3. Formaldehyde can be given off by furniture made from pressed wood. Which of the statements given above are correct?","options":["1 only","1 and 2 only","1, 2 and 3","2 and 3 only"],"answer":2,"explanation":"All three are recognised indoor pollutants; radon from uranium-bearing soils and rocks is a leading cause of lung cancer among non-smokers.","difficulty":"hard","source":"UPSC Prelims","questionHi":"घरेलू (इनडोर) वायु प्रदूषण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. रेडॉन, एक रंगहीन, गंधहीन रेडियोधर्मी गैस, भूमि से इमारतों में रिस सकती है। 2. पारंपरिक चूल्हों में जैवभार जलाने से महिलाएँ और बच्चे कणिकीय पदार्थ और कार्बन मोनोऑक्साइड के उच्च स्तरों के संपर्क में आते हैं। 3. दबी हुई लकड़ी से बने फर्नीचर से फॉर्मेल्डिहाइड निकल सकती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","1, 2 और 3","केवल 2 और 3"],"explanationHi":"तीनों मान्य घरेलू प्रदूषक हैं; यूरेनियमयुक्त मिट्टी और चट्टानों से निकली रेडॉन धूम्रपान न करने वालों में फेफड़ों के कैंसर का एक प्रमुख कारण है।"},
  {"id":"env-ecology-234","question":"Which of the following is NOT among the pollutants covered by India's National Ambient Air Quality Standards notified in 2009?","options":["Ammonia","Benzene","Carbon dioxide","Benzo(a)pyrene"],"answer":2,"explanation":"The 2009 standards cover twelve pollutants, including PM10, PM2.5, SO2, NO2, CO, ozone, ammonia, lead, benzene, benzo(a)pyrene, arsenic and nickel; CO2 is a greenhouse gas, not a regulated ambient pollutant.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा 2009 में अधिसूचित भारत के राष्ट्रीय परिवेशी वायु गुणवत्ता मानकों में शामिल प्रदूषकों में से नहीं है?","optionsHi":["अमोनिया","बेंज़ीन","कार्बन डाइऑक्साइड","बेंज़ो(ए)पाइरीन"],"explanationHi":"2009 के मानक बारह प्रदूषकों को शामिल करते हैं, जिनमें PM10, PM2.5, SO2, NO2, CO, ओज़ोन, अमोनिया, सीसा, बेंज़ीन, बेंज़ो(ए)पाइरीन, आर्सेनिक और निकल शामिल हैं; CO2 एक हरितगृह गैस है, विनियमित परिवेशी प्रदूषक नहीं।"},
  {"id":"env-ecology-235","question":"Consider the following statements about India's National Air Quality Index: 1. It has six categories ranging from 'Good' to 'Severe'. 2. The overall index for a location is set by the highest sub-index among the pollutants measured. 3. Carbon dioxide is one of the pollutants used to calculate it. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The AQI uses pollutants such as PM10, PM2.5, NO2, SO2, CO, ozone, ammonia and lead; the worst sub-index decides the reported value. CO2 is not part of it.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत के राष्ट्रीय वायु गुणवत्ता सूचकांक के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसकी छह श्रेणियाँ हैं जो 'अच्छी' से 'गंभीर' तक हैं। 2. किसी स्थान का समग्र सूचकांक मापे गए प्रदूषकों में से सबसे उच्च उप-सूचकांक द्वारा निर्धारित होता है। 3. कार्बन डाइऑक्साइड इसकी गणना में प्रयुक्त प्रदूषकों में से एक है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"AQI में PM10, PM2.5, NO2, SO2, CO, ओज़ोन, अमोनिया और सीसा जैसे प्रदूषक प्रयुक्त होते हैं; सबसे खराब उप-सूचकांक रिपोर्ट किया जाने वाला मान तय करता है। CO2 इसका भाग नहीं है।"},
  {"id":"env-ecology-236","question":"Consider the following statements about alternatives to burning crop residue: 1. The Happy Seeder sows wheat directly into the stubble of the harvested rice crop without burning it. 2. The Pusa decomposer is a microbial preparation that speeds up the decomposition of stubble in the field. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Both are in-situ residue management options promoted to reduce paddy-stubble burning in north-west India; the decomposer is a fungal formulation from IARI.","difficulty":"hard","source":"UPSC Prelims","questionHi":"फसल अवशेष जलाने के विकल्पों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. हैप्पी सीडर कटी हुई धान की फसल के ठूँठ में बिना जलाए सीधे गेहूँ बोता है। 2. पूसा डीकम्पोज़र एक सूक्ष्मजैविक मिश्रण है जो खेत में ठूँठ के अपघटन को तेज़ करता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["1 और 2 दोनों","केवल 1","केवल 2","न तो 1 और न ही 2"],"explanationHi":"दोनों उत्तर-पश्चिम भारत में धान की पराली जलाना घटाने के लिए प्रोत्साहित किए गए स्व-स्थाने अवशेष प्रबंधन विकल्प हैं; डीकम्पोज़र IARI का एक कवकीय मिश्रण है।"},
  {"id":"env-ecology-237","question":"Rain is usually called 'acid rain' only when its pH falls below about 5.6, not below 7. This is because:","options":["Pure water itself has a pH of 5.6 at room temperature","Rain always contains dissolved sulphuric acid from volcanoes","pH values between 5.6 and 7 cannot be measured accurately","Even clean rain dissolves CO2 and forms weak carbonic acid"],"answer":3,"explanation":"CO2 in equilibrium with rainwater gives a pH of about 5.6; only acidity beyond that, from sulphur and nitrogen oxides, is counted as acid rain.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वर्षा को सामान्यतः 'अम्ल वर्षा' तभी कहा जाता है जब उसका pH लगभग 5.6 से नीचे गिरता है, 7 से नीचे नहीं। इसका कारण यह है कि:","optionsHi":["कमरे के तापमान पर शुद्ध जल का pH स्वयं 5.6 होता है","वर्षा में सदा ज्वालामुखियों से आया घुला सल्फ्यूरिक अम्ल होता है","5.6 और 7 के बीच के pH मान सही-सही मापे नहीं जा सकते","स्वच्छ वर्षा भी CO2 को घोलकर दुर्बल कार्बोनिक अम्ल बनाती है"],"explanationHi":"वर्षा के जल के साथ संतुलन में CO2 लगभग 5.6 का pH देती है; केवल उससे अधिक अम्लता, जो सल्फर और नाइट्रोजन ऑक्साइडों से आती है, अम्ल वर्षा मानी जाती है।"},
  {"id":"env-ecology-238","question":"Consider the following statements about acid deposition: 1. It can release toxic aluminium from soils into lakes, harming fish. 2. Adding lime to acidified lakes is one way of neutralising them. 3. Acid deposition can occur as dry particles and gases, not only as rain. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 and 3 only","1 only"],"answer":0,"explanation":"Acidity mobilises aluminium that damages fish gills; liming raises pH; and dry deposition of SO2, NOx and sulphate particles is as important as wet deposition.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अम्लीय निक्षेपण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह मिट्टी से विषैले एल्युमिनियम को झीलों में मुक्त कर सकता है, जिससे मछलियों को हानि होती है। 2. अम्लीकृत झीलों में चूना मिलाना उन्हें उदासीन करने का एक तरीका है। 3. अम्लीय निक्षेपण केवल वर्षा के रूप में ही नहीं, शुष्क कणों और गैसों के रूप में भी हो सकता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 1 और 2","केवल 2 और 3","केवल 1"],"explanationHi":"अम्लता एल्युमिनियम को गतिशील कर देती है जो मछलियों के गलफड़ों को हानि पहुँचाता है; चूना मिलाने से pH बढ़ता है; और SO2, NOx तथा सल्फेट कणों का शुष्क निक्षेपण आर्द्र निक्षेपण जितना ही महत्वपूर्ण है।"},
  {"id":"env-ecology-239","question":"Consider the following statements about noise: 1. On the decibel scale, an increase of 10 dB means a tenfold increase in sound intensity. 2. India's Noise Pollution (Regulation and Control) Rules, 2000 were framed under the Environment (Protection) Act, 1986. 3. Under these rules, the area within 100 metres of hospitals, educational institutions and courts can be declared a silence zone. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 only","1 and 3 only"],"answer":1,"explanation":"The decibel scale is logarithmic; the Noise Rules were made under the EPA, 1986 and define silence zones of at least 100 metres around such institutions.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ध्वनि के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. डेसिबल पैमाने पर, 10 dB की वृद्धि का अर्थ ध्वनि तीव्रता में दस गुना वृद्धि है। 2. भारत के ध्वनि प्रदूषण (विनियमन और नियंत्रण) नियम, 2000 पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत बनाए गए थे। 3. इन नियमों के अंतर्गत अस्पतालों, शैक्षणिक संस्थानों और न्यायालयों के 100 मीटर के भीतर के क्षेत्र को शांत क्षेत्र घोषित किया जा सकता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","1, 2 और 3","केवल 2","केवल 1 और 3"],"explanationHi":"डेसिबल पैमाना लघुगणकीय है; ध्वनि नियम EPA, 1986 के अंतर्गत बने थे और ऐसे संस्थानों के चारों ओर कम से कम 100 मीटर के शांत क्षेत्र परिभाषित करते हैं।"},
  {"id":"env-ecology-240","question":"The sound in a busy factory hall measures 90 dB, while a normal conversation measures about 60 dB. The sound intensity in the factory is greater than that of the conversation by a factor of:","options":["1.5","30","about 31.6","1,000"],"answer":3,"explanation":"Each 10 dB is a tenfold rise in intensity, so 30 dB is 10 × 10 × 10 = 1,000 times. 1.5 comes from dividing the decibel values, and 31.6 is the ratio of sound pressure (amplitude), not intensity.","difficulty":"moderate","source":"UPSC Prelims · CDS","questionHi":"किसी व्यस्त फैक्टरी हॉल में ध्वनि 90 dB मापी जाती है, जबकि सामान्य बातचीत लगभग 60 dB होती है। फैक्टरी में ध्वनि की तीव्रता बातचीत की तुलना में कितने गुना अधिक है?","optionsHi":["1.5","30","लगभग 31.6","1,000"],"explanationHi":"प्रत्येक 10 dB तीव्रता में दस गुना वृद्धि है, इसलिए 30 dB का अर्थ 10 × 10 × 10 = 1,000 गुना है। 1.5 डेसिबल मानों को भाग देने से आता है, और 31.6 ध्वनि दाब (आयाम) का अनुपात है, तीव्रता का नहीं।"},
  {"id":"env-ecology-241","question":"The amount of dissolved oxygen in a river is likely to fall when: 1. The water temperature rises. 2. Untreated organic sewage is discharged into it. 3. Aquatic plants photosynthesise actively in daylight. Select the correct answer.","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Warm water holds less oxygen and microbes decomposing sewage use it up; photosynthesis adds oxygen during the day.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"किसी नदी में घुली ऑक्सीजन की मात्रा के घटने की संभावना तब होती है जब: 1. जल का तापमान बढ़ता है। 2. उसमें अनुपचारित कार्बनिक सीवेज छोड़ा जाता है। 3. जलीय पौधे दिन के प्रकाश में सक्रिय रूप से प्रकाश-संश्लेषण करते हैं। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"गर्म जल में ऑक्सीजन कम घुलती है और सीवेज को विघटित करने वाले सूक्ष्मजीव उसे समाप्त कर देते हैं; प्रकाश-संश्लेषण दिन में ऑक्सीजन जोड़ता है।"},
  {"id":"env-ecology-242","question":"Consider the following statements about sewage treatment: 1. Primary treatment removes solids physically by screening and sedimentation. 2. Secondary treatment uses microbes to reduce the organic load (BOD) of the sewage. 3. Biogas from anaerobic sludge digesters is mainly methane, with carbon dioxide and hydrogen sulphide. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Primary treatment is physical; in secondary treatment aerobic microbes in flocs (activated sludge) consume organic matter; the settled sludge is digested anaerobically to give biogas.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सीवेज उपचार के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. प्राथमिक उपचार छानने और अवसादन द्वारा ठोस पदार्थों को भौतिक रूप से हटाता है। 2. द्वितीयक उपचार सीवेज के कार्बनिक भार (BOD) को घटाने के लिए सूक्ष्मजीवों का उपयोग करता है। 3. अवायवीय अवपंक पाचकों से निकली बायोगैस मुख्यतः मीथेन होती है, जिसके साथ कार्बन डाइऑक्साइड और हाइड्रोजन सल्फाइड होती हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"प्राथमिक उपचार भौतिक है; द्वितीयक उपचार में फ्लॉक (सक्रिय अवपंक) में स्थित वायवीय सूक्ष्मजीव कार्बनिक पदार्थ का उपभोग करते हैं; बैठे हुए अवपंक का अवायवीय पाचन बायोगैस देता है।"},
  {"id":"env-ecology-243","question":"In most freshwater lakes, controlling the input of which nutrient is usually the most effective way to prevent algal blooms?","options":["Nitrogen","Phosphorus","Potassium","Carbon"],"answer":1,"explanation":"Phosphorus is usually the limiting nutrient in fresh water, which is why phosphate detergents and sewage are key targets; in many coastal seas nitrogen is limiting instead.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अधिकांश मीठे जल की झीलों में शैवाल प्रस्फुटन रोकने का सबसे प्रभावी तरीका सामान्यतः किस पोषक तत्व के निवेश को नियंत्रित करना है?","optionsHi":["नाइट्रोजन","फॉस्फोरस","पोटैशियम","कार्बन"],"explanationHi":"मीठे जल में फॉस्फोरस सामान्यतः सीमित करने वाला पोषक तत्व होता है, इसीलिए फॉस्फेट डिटर्जेंट और सीवेज मुख्य लक्ष्य हैं; अनेक तटीय समुद्रों में इसके बजाय नाइट्रोजन सीमित करने वाली होती है।"},
  {"id":"env-ecology-244","question":"The high levels of arsenic in groundwater in parts of the Ganga–Brahmaputra delta are mainly:","options":["Arsenical pesticide run-off from paddy fields over decades","Leaked from tannery and chemical factory effluents","Geogenic, from the delta's own sediments, drawn up by pumping","Deposited from fly ash of coal-fired thermal power plants nearby"],"answer":2,"explanation":"The arsenic is geogenic: it comes from the delta's own sediments under oxygen-poor conditions, and is drawn up by tube wells, so it is not mainly industrial.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"गंगा–ब्रह्मपुत्र डेल्टा के कुछ भागों में भूजल में आर्सेनिक के उच्च स्तर मुख्यतः किसके कारण हैं?","optionsHi":["दशकों से धान के खेतों से आर्सेनिकयुक्त कीटनाशकों का बहाव","चर्मशोधन और रासायनिक कारखानों के बहिःस्राव से रिसाव","भू-जनित (जियोजेनिक), डेल्टा के अपने अवसादों से, जो पंपिंग द्वारा ऊपर खींचा जाता है","आस-पास के कोयला-चालित ताप विद्युत संयंत्रों की फ्लाई ऐश का निक्षेपण"],"explanationHi":"आर्सेनिक भू-जनित है: यह ऑक्सीजन-रहित परिस्थितियों में डेल्टा के अपने अवसादों से आता है और नलकूपों द्वारा ऊपर खींचा जाता है, इसलिए यह मुख्यतः औद्योगिक नहीं है।"},
  {"id":"env-ecology-245","question":"Warm cooling water discharged from a power plant can harm fish downstream chiefly because warmer water:","options":["Contains more dissolved salts that poison gills","Becomes more acidic as heat releases carbonic acid","Blocks sunlight from reaching plants on the river bed","Holds less dissolved oxygen as fish need more of it"],"answer":3,"explanation":"Oxygen is less soluble in warm water, and higher temperature speeds up the metabolism of cold-blooded fish, so oxygen stress comes from both sides.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"किसी विद्युत संयंत्र से छोड़ा गया गर्म शीतलन जल नीचे की ओर मछलियों को मुख्यतः इसलिए हानि पहुँचा सकता है क्योंकि गर्म जल:","optionsHi":["अधिक घुले हुए लवण रखता है जो गलफड़ों को विषाक्त करते हैं","अधिक अम्लीय हो जाता है क्योंकि ऊष्मा कार्बोनिक अम्ल को मुक्त करती है","नदी तल के पौधों तक सूर्य के प्रकाश को पहुँचने से रोकता है","कम घुली ऑक्सीजन रखता है जबकि मछलियों को उसकी अधिक आवश्यकता होती है"],"explanationHi":"गर्म जल में ऑक्सीजन कम घुलती है और ऊँचा तापमान शीत-रक्तीय मछलियों के उपापचय को तेज़ करता है, इसलिए ऑक्सीजन का दबाव दोनों ओर से पड़ता है।"},
  {"id":"env-ecology-246","question":"Consider the following statements about microplastics: 1. They are usually defined as plastic particles smaller than 5 mm. 2. Primary microplastics, such as microbeads, are made small, while secondary microplastics come from the breakdown of larger plastic items. 3. Plastics labelled 'compostable' break down quickly and fully in the open ocean. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Compostable plastics generally need the heat and microbes of industrial composting; in cold seawater they persist for long periods.","difficulty":"hard","source":"UPSC Prelims","questionHi":"माइक्रोप्लास्टिक के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इन्हें सामान्यतः 5 mm से छोटे प्लास्टिक कणों के रूप में परिभाषित किया जाता है। 2. प्राथमिक माइक्रोप्लास्टिक, जैसे माइक्रोबीड्स, छोटे ही बनाए जाते हैं, जबकि द्वितीयक माइक्रोप्लास्टिक बड़ी प्लास्टिक वस्तुओं के टूटने से आते हैं। 3. 'कम्पोस्टेबल' के रूप में लेबल किए गए प्लास्टिक खुले महासागर में शीघ्र और पूरी तरह विघटित हो जाते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"कम्पोस्टेबल प्लास्टिक को सामान्यतः औद्योगिक कम्पोस्टिंग की गर्मी और सूक्ष्मजीव चाहिए; ठंडे समुद्री जल में वे लंबे समय तक बने रहते हैं।"},
  {"id":"env-ecology-247","question":"Open burning of PVC-coated wires during informal e-waste recycling is especially dangerous because it releases:","options":["Ground-level ozone","Dioxins and furans","Methane and ammonia","Radioactive radon gas"],"answer":1,"explanation":"Burning chlorine-containing plastics produces dioxins and furans, persistent and highly toxic compounds; methane comes from anaerobic decay, not burning.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनौपचारिक ई-अपशिष्ट पुनर्चक्रण के दौरान PVC-लेपित तारों को खुले में जलाना विशेष रूप से खतरनाक है क्योंकि इससे निकलते हैं:","optionsHi":["भू-स्तरीय ओज़ोन","डाइऑक्सिन और फ्यूरान","मीथेन और अमोनिया","रेडियोधर्मी रेडॉन गैस"],"explanationHi":"क्लोरीनयुक्त प्लास्टिकों को जलाने से डाइऑक्सिन और फ्यूरान बनते हैं, जो स्थायी और अत्यंत विषैले यौगिक हैं; मीथेन अवायवीय अपघटन से आती है, जलाने से नहीं।"},
  {"id":"env-ecology-248","question":"Consider the following statements about the disposal of solid waste: 1. Leachate is the liquid that drains through waste and can contaminate groundwater. 2. A sanitary landfill uses an impermeable liner and a daily cover of soil. 3. Landfill gas is mainly nitrogen and oxygen. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Landfill gas from anaerobic decay is mainly methane and carbon dioxide, which is why landfills are both a fire hazard and a greenhouse gas source.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"ठोस अपशिष्ट के निपटान के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. निक्षालित द्रव (लीचेट) वह तरल है जो अपशिष्ट से रिसकर निकलता है और भूजल को दूषित कर सकता है। 2. स्वच्छता भूमि भराव (सैनिटरी लैंडफिल) में अपारगम्य अस्तर और मिट्टी का दैनिक आवरण उपयोग किया जाता है। 3. भूमि भराव गैस मुख्यतः नाइट्रोजन और ऑक्सीजन होती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अवायवीय अपघटन से बनी भूमि भराव गैस मुख्यतः मीथेन और कार्बन डाइऑक्साइड होती है, इसीलिए भूमि भराव आग का खतरा भी हैं और हरितगृह गैस का स्रोत भी।"},
  {"id":"env-ecology-249","question":"In the widely used hierarchy of waste management, which option is the most preferred?","options":["Recycling","Incineration with energy recovery","Reducing waste at its source","Disposal in a sanitary landfill"],"answer":2,"explanation":"The hierarchy runs prevention or reduction, reuse, recycling, recovery and, last, disposal; waste that is never produced needs no handling at all.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अपशिष्ट प्रबंधन के व्यापक रूप से प्रयुक्त पदानुक्रम में कौन-सा विकल्प सर्वाधिक वरीय है?","optionsHi":["पुनर्चक्रण","ऊर्जा पुनःप्राप्ति के साथ भस्मीकरण","स्रोत पर ही अपशिष्ट को कम करना","स्वच्छता भूमि भराव में निपटान"],"explanationHi":"पदानुक्रम इस क्रम में चलता है: रोकथाम या कमी, पुनः उपयोग, पुनर्चक्रण, पुनःप्राप्ति और अंत में निपटान; जो अपशिष्ट कभी उत्पन्न ही नहीं हुआ, उसे संभालने की आवश्यकता नहीं पड़ती।"},
  {"id":"env-ecology-250","question":"Which radioactive isotope released in nuclear accidents poses a particular threat to the thyroid gland, especially in children?","options":["Iodine-131","Caesium-137","Strontium-90","Radon-222"],"answer":0,"explanation":"The thyroid concentrates iodine, so radioactive iodine-131 builds up there; strontium-90 behaves like calcium and lodges in bones.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नाभिकीय दुर्घटनाओं में निकलने वाला कौन-सा रेडियोधर्मी समस्थानिक थायरॉइड ग्रंथि, विशेषकर बच्चों में, के लिए विशेष खतरा उत्पन्न करता है?","optionsHi":["आयोडीन-131","सीज़ियम-137","स्ट्रॉन्शियम-90","रेडॉन-222"],"explanationHi":"थायरॉइड आयोडीन को सांद्रित करता है, इसलिए रेडियोधर्मी आयोडीन-131 वहाँ जमा हो जाता है; स्ट्रॉन्शियम-90 कैल्शियम की तरह व्यवहार करता है और हड्डियों में जम जाता है।"},
  {"id":"env-ecology-251","question":"Waterlogging and soil salinity in parts of canal-irrigated Punjab and Haryana result mainly from:","options":["Sea water seeping inland through the river mouths and creeks","Excessive use of organic manure and green manure","Acid rain from thermal plants and nearby industries","Over-irrigation and seepage raising the saline water table"],"answer":3,"explanation":"Seepage and excess irrigation raise the groundwater; as it rises and evaporates near the surface, dissolved salts are left behind in the root zone.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नहर-सिंचित पंजाब और हरियाणा के कुछ भागों में जलभराव और मृदा लवणता मुख्यतः किसके कारण होती है?","optionsHi":["नदी मुहानों और खाड़ियों से होकर समुद्री जल का अंदर रिसना","जैविक खाद और हरी खाद का अत्यधिक उपयोग","ताप संयंत्रों और आस-पास के उद्योगों से अम्ल वर्षा","अति-सिंचाई और रिसाव जिससे खारे जल स्तर का ऊपर उठना"],"explanationHi":"रिसाव और अधिक सिंचाई भूजल को ऊपर उठाते हैं; जब वह ऊपर उठकर सतह के निकट वाष्पित होता है, तो घुले हुए लवण जड़ क्षेत्र में पीछे छूट जाते हैं।"},
  {"id":"env-ecology-252","question":"Consider the following statements about biofertilisers and biocontrol: 1. Azolla, with the cyanobacterium Anabaena in its leaves, is used as a biofertiliser in paddy fields. 2. Mycorrhizal fungi help plants take up phosphorus from the soil. 3. Trichoderma is a biofertiliser that fixes atmospheric nitrogen. Which of the statements given above are correct?","options":["1, 2 and 3","2 only","1 and 3 only","1 and 2 only"],"answer":3,"explanation":"Trichoderma is a free-living fungus used as a biocontrol agent against plant pathogens; it does not fix nitrogen.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जैव-उर्वरकों और जैव-नियंत्रण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. अज़ोला, जिसकी पत्तियों में सायनोबैक्टीरिया एनाबीना होता है, धान के खेतों में जैव-उर्वरक के रूप में प्रयुक्त होता है। 2. माइकोराइज़ा कवक पौधों को मिट्टी से फॉस्फोरस ग्रहण करने में सहायता करते हैं। 3. ट्राइकोडर्मा एक जैव-उर्वरक है जो वायुमंडलीय नाइट्रोजन का स्थिरीकरण करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 2","केवल 1 और 3","केवल 1 और 2"],"explanationHi":"ट्राइकोडर्मा एक मुक्तजीवी कवक है जो पादप रोगजनकों के विरुद्ध जैव-नियंत्रण कारक के रूप में प्रयुक्त होता है; यह नाइट्रोजन का स्थिरीकरण नहीं करता।"},
  {"id":"env-ecology-253","question":"Consider the following statements about atmospheric brown clouds over South Asia: 1. They reduce the sunlight reaching the ground (solar dimming). 2. The black carbon in them absorbs sunlight and warms the atmospheric layer in which it sits. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Brown clouds of soot, sulphates and other aerosols cool the surface by dimming sunlight while heating the air aloft, which can alter rainfall patterns.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"दक्षिण एशिया के ऊपर वायुमंडलीय भूरे बादलों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वे धरातल तक पहुँचने वाले सूर्य के प्रकाश को घटाते हैं (सौर मंदन)। 2. उनमें मौजूद ब्लैक कार्बन सूर्य के प्रकाश को अवशोषित करता है और जिस वायुमंडलीय परत में स्थित है उसे गर्म करता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"कालिख, सल्फेट और अन्य एरोसोल के भूरे बादल सूर्य के प्रकाश को मंद कर सतह को ठंडा करते हैं जबकि ऊपर की वायु को गर्म करते हैं, जिससे वर्षा के पैटर्न बदल सकते हैं।"},
  {"id":"env-ecology-254","question":"The urban heat island effect, by which a city is warmer than its surrounding countryside, is usually most pronounced:","options":["Around noon on windy, cloudy days","At night in calm, clear weather","Only during the monsoon","Only in coastal cities"],"answer":1,"explanation":"Concrete and asphalt store heat by day and release it at night; calm, clear nights let the countryside cool fast while the city stays warm, so the contrast is greatest then.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नगरीय ऊष्मा द्वीप प्रभाव, जिसमें कोई शहर अपने आस-पास के ग्रामीण क्षेत्र से अधिक गर्म होता है, सामान्यतः सबसे अधिक कब स्पष्ट होता है?","optionsHi":["हवादार, बादल भरे दिनों में दोपहर के आसपास","शांत, साफ़ मौसम में रात को","केवल मानसून के दौरान","केवल तटीय शहरों में"],"explanationHi":"कंक्रीट और डामर दिन में ऊष्मा संचित करते हैं और रात को छोड़ते हैं; शांत, साफ़ रातों में ग्रामीण क्षेत्र तेज़ी से ठंडा हो जाता है जबकि शहर गर्म रहता है, इसलिए अंतर तब सबसे अधिक होता है।"},
  {"id":"env-ecology-255","question":"Consider the following statements about vehicle emission norms in India: 1. India moved directly from Bharat Stage IV to Bharat Stage VI norms nationwide in April 2020, skipping Stage V. 2. Bharat Stage VI fuel has a much lower sulphur content than Bharat Stage IV fuel. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"BS-VI was introduced across the country from 1 April 2020, leapfrogging BS-V, and cut the sulphur limit in fuel from 50 ppm to 10 ppm.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत में वाहन उत्सर्जन मानदंडों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. भारत अप्रैल 2020 में देशव्यापी रूप से सीधे भारत स्टेज IV से भारत स्टेज VI मानदंडों पर चला गया, स्टेज V को छोड़ते हुए। 2. भारत स्टेज VI ईंधन में भारत स्टेज IV ईंधन की तुलना में सल्फर की मात्रा बहुत कम होती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"BS-VI को 1 अप्रैल 2020 से पूरे देश में लागू किया गया, BS-V को छोड़ते हुए, और ईंधन में सल्फर की सीमा 50 ppm से घटाकर 10 ppm कर दी गई।"},
  {"id":"env-ecology-256","question":"Which of the following best describes how greenhouse gases warm the Earth's surface?","options":["They reflect incoming ultraviolet radiation straight back to space","They trap incoming visible sunlight in the upper atmosphere","They let in short-wave sunlight but absorb outgoing infrared","They release heat through chemical reactions with oxygen"],"answer":2,"explanation":"The surface, warmed by sunlight, radiates infrared; greenhouse gases absorb it and re-radiate part back down, so the surface stays warmer than it would otherwise be.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा कथन सबसे अच्छी तरह बताता है कि हरितगृह गैसें पृथ्वी की सतह को कैसे गर्म करती हैं?","optionsHi":["वे आने वाली पराबैंगनी विकिरण को सीधे अंतरिक्ष में परावर्तित कर देती हैं","वे आने वाले दृश्य सूर्य प्रकाश को ऊपरी वायुमंडल में रोक लेती हैं","वे लघु-तरंग सूर्य प्रकाश को आने देती हैं पर बाहर जाने वाली अवरक्त विकिरण को अवशोषित कर लेती हैं","वे ऑक्सीजन के साथ रासायनिक अभिक्रियाओं द्वारा ऊष्मा छोड़ती हैं"],"explanationHi":"सूर्य के प्रकाश से गर्म सतह अवरक्त विकिरण उत्सर्जित करती है; हरितगृह गैसें उसे अवशोषित कर उसका कुछ भाग वापस नीचे विकीर्ण करती हैं, इसलिए सतह उससे अधिक गर्म रहती है जितनी वह अन्यथा होती।"},
  {"id":"env-ecology-257","question":"Nitrogen and oxygen together make up about 99 per cent of dry air, yet they are not greenhouse gases. The reason is that:","options":["Their symmetric two-atom molecules cannot absorb infrared","They are present mainly in the upper atmosphere","They absorb only ultraviolet radiation and convert it into heat","They are chemically inert and do not react with sunlight"],"answer":0,"explanation":"To absorb infrared, a molecule's vibration must change its dipole; N2 and O2 cannot, while CO2, H2O, CH4 and N2O can.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नाइट्रोजन और ऑक्सीजन मिलकर शुष्क वायु का लगभग 99 प्रतिशत बनाती हैं, फिर भी वे हरितगृह गैसें नहीं हैं। इसका कारण यह है कि:","optionsHi":["उनके सममित द्विपरमाणुक अणु अवरक्त विकिरण को अवशोषित नहीं कर सकते","वे मुख्यतः ऊपरी वायुमंडल में उपस्थित हैं","वे केवल पराबैंगनी विकिरण को अवशोषित करती हैं और उसे ऊष्मा में बदल देती हैं","वे रासायनिक रूप से अक्रिय हैं और सूर्य के प्रकाश से अभिक्रिया नहीं करतीं"],"explanationHi":"अवरक्त विकिरण को अवशोषित करने के लिए अणु के कंपन से उसके द्विध्रुव में परिवर्तन होना चाहिए; N2 और O2 में ऐसा नहीं होता, जबकि CO2, H2O, CH4 और N2O में होता है।"},
  {"id":"env-ecology-258","question":"Without the natural greenhouse effect, the Earth's average surface temperature, now about 15 °C, would be roughly:","options":["0 °C","+5 °C","−60 °C","−18 °C"],"answer":3,"explanation":"Radiative balance alone gives about −18 °C; the natural greenhouse effect adds roughly 33 °C, making the planet habitable.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"प्राकृतिक हरितगृह प्रभाव के बिना, पृथ्वी का औसत सतही तापमान, जो अब लगभग 15 °C है, लगभग कितना होता?","optionsHi":["0 °C","+5 °C","−60 °C","−18 °C"],"explanationHi":"केवल विकिरण संतुलन से लगभग −18 °C आता है; प्राकृतिक हरितगृह प्रभाव लगभग 33 °C जोड़ता है, जिससे ग्रह रहने योग्य बनता है।"},
  {"id":"env-ecology-259","question":"Arrange the following surfaces in decreasing order of their typical albedo (reflectivity): 1. Fresh snow 2. Open ocean 3. Desert sand 4. Coniferous forest","options":["1, 3, 4, 2","1, 4, 3, 2","3, 1, 4, 2","1, 3, 2, 4"],"answer":0,"explanation":"Fresh snow reflects most sunlight, bright sand about a third, dark conifer forest little, and open water at high sun least of all.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित सतहों को उनके विशिष्ट एल्बिडो (परावर्तकता) के घटते क्रम में व्यवस्थित कीजिए: 1. ताज़ी बर्फ़ 2. खुला महासागर 3. मरुस्थलीय रेत 4. शंकुधारी वन","optionsHi":["1, 3, 4, 2","1, 4, 3, 2","3, 1, 4, 2","1, 3, 2, 4"],"explanationHi":"ताज़ी बर्फ़ सूर्य के प्रकाश का सबसे अधिक परावर्तन करती है, चमकीली रेत लगभग एक-तिहाई, गहरा शंकुधारी वन कम, और ऊँचे सूर्य पर खुला जल सबसे कम।"},
  {"id":"env-ecology-260","question":"Which of the following are positive (amplifying) feedbacks in the climate system? 1. Melting sea ice exposing darker ocean water 2. A warmer atmosphere holding more water vapour 3. Thawing permafrost releasing carbon dioxide and methane 4. A warmer Earth radiating more long-wave energy to space. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"The first three add to warming; the rise in outgoing radiation with temperature (the Planck response) is the basic negative feedback that stabilises climate.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से जलवायु तंत्र में धनात्मक (प्रवर्धक) पुनर्निवेश (फीडबैक) हैं? 1. पिघलती समुद्री बर्फ़ से गहरे महासागरीय जल का उजागर होना 2. गर्म वायुमंडल का अधिक जलवाष्प धारण करना 3. पिघलता पर्माफ्रॉस्ट जो कार्बन डाइऑक्साइड और मीथेन छोड़ता है 4. गर्म पृथ्वी का अंतरिक्ष में अधिक दीर्घ-तरंग ऊर्जा विकीर्ण करना। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"पहले तीन तापन को बढ़ाते हैं; तापमान के साथ बाहर जाने वाले विकिरण का बढ़ना (प्लांक अनुक्रिया) वह मूल ऋणात्मक पुनर्निवेश है जो जलवायु को स्थिर करता है।"},
  {"id":"env-ecology-261","question":"Water vapour contributes more than any other gas to the natural greenhouse effect, yet it is treated as a feedback rather than a driver of climate change. This is because:","options":["Water vapour absorbs no infrared radiation at all","Human activities emit no water vapour at all","Water vapour is found only in the stratosphere, above the weather","Its amount is set by temperature, and excess rains out in days"],"answer":3,"explanation":"Water vapour stays in the air only for days and its amount depends on temperature, so it amplifies warming started by long-lived gases such as CO2.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जलवाष्प प्राकृतिक हरितगृह प्रभाव में किसी भी अन्य गैस से अधिक योगदान देती है, फिर भी उसे जलवायु परिवर्तन का प्रेरक नहीं, बल्कि पुनर्निवेश माना जाता है। इसका कारण यह है कि:","optionsHi":["जलवाष्प अवरक्त विकिरण को बिल्कुल अवशोषित नहीं करती","मानवीय गतिविधियाँ जलवाष्प का बिल्कुल उत्सर्जन नहीं करतीं","जलवाष्प केवल समतापमंडल में, मौसम से ऊपर पाई जाती है","इसकी मात्रा तापमान से निर्धारित होती है, और अधिकता कुछ ही दिनों में वर्षा बनकर गिर जाती है"],"explanationHi":"जलवाष्प वायु में केवल कुछ दिन रहती है और उसकी मात्रा तापमान पर निर्भर है, इसलिए यह CO2 जैसी दीर्घजीवी गैसों द्वारा आरंभ किए गए तापन को प्रवर्धित करती है।"},
  {"id":"env-ecology-262","question":"In climate science, 'radiative forcing' refers to:","options":["The force exerted by sunlight's pressure on the Earth's orbit","A factor's change to the net energy flux at the top of the atmosphere","The total heat stored in the oceans since pre-industrial times","The rate at which winds and currents carry heat from equator to poles"],"answer":1,"explanation":"Forcing is measured in watts per square metre; a positive value means the factor pushes the climate towards warming.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जलवायु विज्ञान में 'विकिरणीय प्रभाव (रेडिएटिव फोर्सिंग)' से तात्पर्य है:","optionsHi":["सूर्य के प्रकाश के दाब द्वारा पृथ्वी की कक्षा पर लगाया गया बल","वायुमंडल के शीर्ष पर शुद्ध ऊर्जा प्रवाह में किसी कारक द्वारा लाया गया परिवर्तन","पूर्व-औद्योगिक काल से महासागरों में संचित कुल ऊष्मा","वह दर जिससे पवन और धाराएँ ऊष्मा को भूमध्य रेखा से ध्रुवों तक ले जाती हैं"],"explanationHi":"प्रभाव को वाट प्रति वर्ग मीटर में मापा जाता है; धनात्मक मान का अर्थ है कि वह कारक जलवायु को तापन की ओर धकेलता है।"},
  {"id":"env-ecology-263","question":"Consider the following statements about aerosols: 1. Sulphate aerosols have a net cooling effect on climate. 2. Black carbon has a warming effect. 3. A large volcanic eruption that injects sulphur dioxide into the stratosphere can cool global climate for a year or two. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Sulphates reflect sunlight, soot absorbs it, and stratospheric sulphate from eruptions such as Pinatubo in 1991 cooled the planet measurably.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एरोसोल के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. सल्फेट एरोसोल का जलवायु पर शुद्ध शीतलन प्रभाव होता है। 2. ब्लैक कार्बन का तापन प्रभाव होता है। 3. समतापमंडल में सल्फर डाइऑक्साइड पहुँचाने वाला बड़ा ज्वालामुखी विस्फोट एक या दो वर्ष तक वैश्विक जलवायु को ठंडा कर सकता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"सल्फेट सूर्य के प्रकाश को परावर्तित करते हैं, कालिख उसे अवशोषित करती है, और 1991 के पिनाटुबो जैसे विस्फोटों से समतापमंडल में पहुँचे सल्फेट ने ग्रह को मापने योग्य रूप से ठंडा किया।"},
  {"id":"env-ecology-264","question":"The global warming potential of methane is much higher over a 20-year horizon than over a 100-year horizon. Why?","options":["Methane is removed in about a decade, front-loading its warming","Methane's ability to absorb infrared increases as it ages","Methane turns into carbon monoxide, which is a stronger greenhouse gas","Carbon dioxide's warming effect falls to zero after 20 years"],"answer":0,"explanation":"GWP compares warming with that of CO2 over a chosen period; a short-lived gas looks more powerful over a short window, because CO2 keeps acting for centuries.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मीथेन की वैश्विक तापन क्षमता 20-वर्षीय अवधि में 100-वर्षीय अवधि की तुलना में कहीं अधिक होती है। ऐसा क्यों?","optionsHi":["मीथेन लगभग एक दशक में हट जाती है, जिससे उसका तापन आरंभ में ही केंद्रित हो जाता है","मीथेन की अवरक्त विकिरण अवशोषित करने की क्षमता उम्र बढ़ने के साथ बढ़ती है","मीथेन कार्बन मोनोऑक्साइड में बदल जाती है, जो अधिक प्रबल हरितगृह गैस है","कार्बन डाइऑक्साइड का तापन प्रभाव 20 वर्ष बाद शून्य हो जाता है"],"explanationHi":"GWP किसी चुनी अवधि में तापन की तुलना CO2 से करती है; अल्पजीवी गैस छोटी अवधि में अधिक शक्तिशाली दिखती है, क्योंकि CO2 सदियों तक प्रभाव डालती रहती है।"},
  {"id":"env-ecology-265","question":"The main process that removes methane from the atmosphere is:","options":["Dissolution in rainwater and washout","Direct splitting by sunlight in the lower troposphere","Oxidation by hydroxyl (OH) radicals in the troposphere","Absorption by cold ocean surface waters near the poles"],"answer":2,"explanation":"The hydroxyl radical, the atmosphere's 'detergent', oxidises methane; soils remove a small additional amount. Methane does not absorb the sunlight that reaches the troposphere, so it is not split there by photolysis.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वायुमंडल से मीथेन को हटाने की मुख्य प्रक्रिया क्या है?","optionsHi":["वर्षा जल में घुलकर बह जाना","निचले क्षोभमंडल में सूर्य के प्रकाश द्वारा सीधे विखंडन","क्षोभमंडल में हाइड्रॉक्सिल (OH) मूलकों द्वारा ऑक्सीकरण","ध्रुवों के निकट ठंडे महासागरीय सतही जल द्वारा अवशोषण"],"explanationHi":"हाइड्रॉक्सिल मूलक, जो वायुमंडल का 'डिटर्जेंट' है, मीथेन का ऑक्सीकरण करता है; मिट्टियाँ थोड़ी अतिरिक्त मात्रा हटाती हैं। मीथेन क्षोभमंडल तक पहुँचने वाले सूर्य के प्रकाश को अवशोषित नहीं करती, इसलिए वहाँ प्रकाश-अपघटन से नहीं टूटती।"},
  {"id":"env-ecology-266","question":"Consider the following statements about nitrous oxide: 1. Agricultural soils treated with nitrogen fertilisers are the largest human source of it. 2. It is both a greenhouse gas and an ozone-depleting substance. 3. Its production is controlled under the Montreal Protocol. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"N2O is now a leading ozone-depleting emission, but it is not a controlled substance under the Montreal Protocol; it is covered as a greenhouse gas under the UNFCCC.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नाइट्रस ऑक्साइड के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. नाइट्रोजन उर्वरकों से उपचारित कृषि मिट्टियाँ इसका सबसे बड़ा मानवीय स्रोत हैं। 2. यह हरितगृह गैस और ओज़ोन-क्षयकारी पदार्थ दोनों है। 3. इसका उत्पादन मॉन्ट्रियल प्रोटोकॉल के अंतर्गत नियंत्रित है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"N2O अब एक प्रमुख ओज़ोन-क्षयकारी उत्सर्जन है, परंतु यह मॉन्ट्रियल प्रोटोकॉल के अंतर्गत नियंत्रित पदार्थ नहीं है; इसे UNFCCC के अंतर्गत हरितगृह गैस के रूप में शामिल किया गया है।"},
  {"id":"env-ecology-267","question":"Consider the following statements: 1. Hydrofluorocarbons (HFCs) do not deplete stratospheric ozone. 2. HFCs are powerful greenhouse gases. 3. Sulphur hexafluoride is used as an insulating gas in electrical switchgear. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 only"],"answer":1,"explanation":"HFCs replaced CFCs because they contain no chlorine, but their high warming potential led to the Kigali Amendment; SF6, used in switchgear, has the highest GWP of the major gases.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. हाइड्रोफ्लोरोकार्बन (HFCs) समतापमंडलीय ओज़ोन को क्षीण नहीं करते। 2. HFCs शक्तिशाली हरितगृह गैसें हैं। 3. सल्फर हेक्साफ्लोराइड का उपयोग विद्युत स्विचगियर में रोधक गैस के रूप में होता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","1, 2 और 3","केवल 2 और 3","केवल 1"],"explanationHi":"HFCs ने CFCs का स्थान इसलिए लिया क्योंकि उनमें क्लोरीन नहीं होती, परंतु उनकी उच्च तापन क्षमता के कारण किगाली संशोधन आया; स्विचगियर में प्रयुक्त SF6 की प्रमुख गैसों में सबसे अधिक GWP है।"},
  {"id":"env-ecology-268","question":"The record of carbon dioxide at Mauna Loa, Hawaii, shows a regular rise and fall within each year on top of the long-term increase. The fall during each northern summer is mainly due to:","options":["Lower fossil fuel burning for heating in the northern summer","Warmer surface oceans dissolving more CO2 during summer","Uptake by growing plants in the land-rich north","Less volcanic activity in the summer months"],"answer":2,"explanation":"The Northern Hemisphere holds most land plants, so its growing season draws CO2 down, and autumn decay and winter release raise it again. Warmer water actually holds less CO2, so ocean uptake cannot explain the summer dip.","difficulty":"hard","source":"UPSC Prelims","questionHi":"हवाई के मौना लोआ में कार्बन डाइऑक्साइड का अभिलेख दीर्घकालिक वृद्धि के साथ-साथ प्रत्येक वर्ष के भीतर नियमित चढ़ाव-उतार दर्शाता है। प्रत्येक उत्तरी ग्रीष्म में गिरावट मुख्यतः किसके कारण होती है?","optionsHi":["उत्तरी ग्रीष्म में तापन के लिए जीवाश्म ईंधन का कम जलना","गर्म सतही महासागरों द्वारा ग्रीष्म में अधिक CO2 का घुलना","स्थल-बहुल उत्तर में बढ़ते पौधों द्वारा अवशोषण","ग्रीष्म के महीनों में कम ज्वालामुखी गतिविधि"],"explanationHi":"उत्तरी गोलार्ध में अधिकांश स्थलीय पौधे हैं, इसलिए उसकी वृद्धि ऋतु CO2 को नीचे खींचती है, और शरद ऋतु का क्षय तथा शीत ऋतु में निष्कासन उसे फिर बढ़ाते हैं। गर्म जल वास्तव में कम CO2 धारण करता है, इसलिए महासागरीय अवशोषण ग्रीष्मकालीन गिरावट की व्याख्या नहीं कर सकता।"},
  {"id":"env-ecology-269","question":"Consider the following statements about ocean acidification: 1. The oceans absorb a substantial part of the carbon dioxide emitted by human activities. 2. Acidification lowers the concentration of the carbonate ions that corals and shellfish need to build shells and skeletons. 3. The average pH of seawater has already fallen below 7. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Seawater is still alkaline, with a pH of about 8.1; 'acidification' describes the downward shift, not a crossing of pH 7.","difficulty":"hard","source":"UPSC Prelims","questionHi":"महासागरीय अम्लीकरण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. महासागर मानवीय गतिविधियों से उत्सर्जित कार्बन डाइऑक्साइड का पर्याप्त भाग अवशोषित करते हैं। 2. अम्लीकरण उन कार्बोनेट आयनों की सांद्रता घटाता है जिनकी प्रवालों और शंख-जीवों को अपने खोल और कंकाल बनाने के लिए आवश्यकता होती है। 3. समुद्री जल का औसत pH पहले ही 7 से नीचे गिर चुका है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"समुद्री जल अभी भी क्षारीय है, जिसका pH लगभग 8.1 है; 'अम्लीकरण' नीचे की ओर बदलाव का वर्णन करता है, pH 7 को पार करने का नहीं।"},
  {"id":"env-ecology-270","question":"Which of the following contribute significantly to global sea-level rise? 1. Thermal expansion of seawater 2. Melting of glaciers and ice sheets on land 3. Melting of floating Arctic sea ice. Select the correct answer.","options":["1, 2 and 3","1 only","2 and 3 only","1 and 2 only"],"answer":3,"explanation":"Floating ice already displaces its own weight of water, so its melting adds almost nothing to sea level; land ice and warming water do.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से वैश्विक समुद्र-स्तर वृद्धि में महत्वपूर्ण योगदान देते हैं? 1. समुद्री जल का तापीय प्रसार 2. स्थल पर हिमनदों और हिम चादरों का पिघलना 3. तैरती आर्कटिक समुद्री बर्फ़ का पिघलना। सही उत्तर चुनिए।","optionsHi":["1, 2 और 3","केवल 1","केवल 2 और 3","केवल 1 और 2"],"explanationHi":"तैरती बर्फ़ पहले ही अपने भार के बराबर जल विस्थापित करती है, इसलिए उसके पिघलने से समुद्र-स्तर में लगभग कोई वृद्धि नहीं होती; स्थलीय बर्फ़ और गर्म होता जल इसमें योगदान देते हैं।"},
  {"id":"env-ecology-271","question":"Consider the following statements about ozone depletion: 1. CFCs are broken down by ultraviolet radiation in the stratosphere, releasing chlorine. 2. A single chlorine atom can destroy many thousands of ozone molecules because it acts as a catalyst. 3. Atom for atom, bromine is less effective than chlorine at destroying ozone. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Bromine is far more destructive per atom than chlorine, which is why halons and methyl bromide are strictly controlled.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ओज़ोन क्षरण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. CFCs समतापमंडल में पराबैंगनी विकिरण द्वारा टूटते हैं और क्लोरीन मुक्त करते हैं। 2. एक अकेला क्लोरीन परमाणु हज़ारों ओज़ोन अणुओं को नष्ट कर सकता है क्योंकि वह उत्प्रेरक की तरह कार्य करता है। 3. परमाणु-दर-परमाणु, ओज़ोन को नष्ट करने में ब्रोमीन क्लोरीन से कम प्रभावी है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"ब्रोमीन प्रति परमाणु क्लोरीन से कहीं अधिक विनाशकारी है, इसीलिए हैलोन और मिथाइल ब्रोमाइड पर कठोर नियंत्रण है।"},
  {"id":"env-ecology-272","question":"Consider the following statements: 1. The total amount of ozone in a column of the atmosphere is measured in Dobson units. 2. A region where total column ozone falls below 220 Dobson units is conventionally described as an 'ozone hole'. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Typical global ozone is about 300 DU; 220 DU is the threshold used to map the Antarctic ozone hole.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. वायुमंडल के किसी स्तंभ में ओज़ोन की कुल मात्रा डॉबसन इकाइयों में मापी जाती है। 2. जिस क्षेत्र में कुल स्तंभ ओज़ोन 220 डॉबसन इकाइयों से नीचे गिर जाती है, उसे परंपरागत रूप से 'ओज़ोन छिद्र' कहा जाता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"विशिष्ट वैश्विक ओज़ोन लगभग 300 DU है; 220 DU वह सीमा है जिसका उपयोग अंटार्कटिक ओज़ोन छिद्र का मानचित्रण करने में होता है।"},
  {"id":"env-ecology-273","question":"Which of the following are controlled as ozone-depleting substances under the Montreal Protocol? 1. Halons 2. Methyl bromide 3. Carbon tetrachloride 4. Methane. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Halons (fire extinguishers), methyl bromide (fumigant) and carbon tetrachloride (solvent) are controlled; methane is a greenhouse gas outside the Protocol.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से मॉन्ट्रियल प्रोटोकॉल के अंतर्गत ओज़ोन-क्षयकारी पदार्थों के रूप में नियंत्रित हैं? 1. हैलोन 2. मिथाइल ब्रोमाइड 3. कार्बन टेट्राक्लोराइड 4. मीथेन। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"हैलोन (अग्निशामक), मिथाइल ब्रोमाइड (धूमक) और कार्बन टेट्राक्लोराइड (विलायक) नियंत्रित हैं; मीथेन प्रोटोकॉल से बाहर एक हरितगृह गैस है।"},
  {"id":"env-ecology-274","question":"Which one of the following is NOT an expected effect of increased UV-B radiation reaching the Earth's surface?","options":["A higher incidence of eye cataracts","Damage to DNA and more skin cancer","Lower productivity of marine phytoplankton","More rickets from vitamin D deficiency"],"answer":3,"explanation":"UV-B drives vitamin D synthesis in the skin, so more of it would not cause deficiency; cataract, skin cancer and harm to phytoplankton are all expected.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पृथ्वी की सतह तक पहुँचने वाली UV-B विकिरण की वृद्धि का निम्नलिखित में से कौन-सा एक अपेक्षित प्रभाव नहीं है?","optionsHi":["आँखों में मोतियाबिंद की अधिक घटनाएँ","DNA को क्षति और त्वचा कैंसर में वृद्धि","समुद्री पादपप्लवकों की कम उत्पादकता","विटामिन D की कमी से अधिक रिकेट्स"],"explanationHi":"UV-B त्वचा में विटामिन D के संश्लेषण को प्रेरित करती है, इसलिए उसकी अधिकता कमी उत्पन्न नहीं करेगी; मोतियाबिंद, त्वचा कैंसर और पादपप्लवकों को हानि सभी अपेक्षित हैं।"},
  {"id":"env-ecology-275","question":"Ozone in the stratosphere is formed naturally when:","options":["Lightning in thunderstorms combines nitrogen and oxygen","Water vapour breaks down in strong sunlight","Ultraviolet light splits O2 and the atoms join other O2","CFCs react with oxygen at very low temperatures"],"answer":2,"explanation":"O2 is split by high-energy UV, and O + O2 gives O3; ozone in turn absorbs UV-B, which is why the layer shields the surface.","difficulty":"hard","source":"UPSC Prelims","questionHi":"समतापमंडल में ओज़ोन प्राकृतिक रूप से कब बनती है?","optionsHi":["आँधी में आकाशीय बिजली नाइट्रोजन और ऑक्सीजन को संयोजित करती है","तेज़ धूप में जलवाष्प टूटती है","पराबैंगनी प्रकाश O2 को विखंडित करता है और परमाणु अन्य O2 से जुड़ जाते हैं","CFCs बहुत कम तापमान पर ऑक्सीजन से अभिक्रिया करते हैं"],"explanationHi":"उच्च-ऊर्जा UV से O2 विखंडित होती है, और O + O2 से O3 बनती है; ओज़ोन स्वयं UV-B को अवशोषित करती है, इसीलिए यह परत सतह की रक्षा करती है।"},
  {"id":"env-ecology-276","question":"Consider the following statements about the Intergovernmental Panel on Climate Change (IPCC): 1. It was set up in 1988 by the World Meteorological Organization and the UN Environment Programme. 2. It carries out its own climate measurements and research programmes. 3. Its assessments are prepared by working groups dealing with the physical science, with impacts and adaptation, and with mitigation. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The IPCC does not conduct original research; it assesses published literature through Working Groups I, II and III.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जलवायु परिवर्तन पर अंतर-सरकारी पैनल (IPCC) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसकी स्थापना 1988 में विश्व मौसम विज्ञान संगठन और संयुक्त राष्ट्र पर्यावरण कार्यक्रम द्वारा की गई थी। 2. यह अपने स्वयं के जलवायु मापन और अनुसंधान कार्यक्रम चलाता है। 3. इसके आकलन भौतिक विज्ञान, प्रभावों और अनुकूलन, तथा शमन से संबंधित कार्य-समूहों द्वारा तैयार किए जाते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"IPCC मौलिक अनुसंधान नहीं करता; यह कार्य-समूह I, II और III के माध्यम से प्रकाशित साहित्य का आकलन करता है।"},
  {"id":"env-ecology-277","question":"Consider the following statements about Milankovitch cycles: 1. They involve changes in the Earth's orbital eccentricity, axial tilt and precession. 2. They operate over tens of thousands of years. 3. They are the main cause of the global warming observed since the mid-twentieth century. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Orbital cycles pace the ice ages over roughly 20,000 to 100,000 years; they are far too slow to explain warming over a few decades.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मिलैंकोविच चक्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इनमें पृथ्वी की कक्षीय उत्केंद्रता, अक्षीय झुकाव और पुरस्सरण में परिवर्तन शामिल हैं। 2. ये हज़ारों-हज़ार वर्षों की अवधि में कार्य करते हैं। 3. ये बीसवीं सदी के मध्य से देखे गए वैश्विक तापन का मुख्य कारण हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"कक्षीय चक्र लगभग 20,000 से 100,000 वर्षों में हिमयुगों की गति तय करते हैं; वे कुछ दशकों में हुए तापन की व्याख्या करने के लिए बहुत धीमे हैं।"},
  {"id":"env-ecology-278","question":"Air bubbles trapped in Antarctic ice cores give scientists:","options":["Precise ages of the bedrock beneath the ice","Records of past ocean salinity and sea-level changes","Direct counts of past sunspots and solar storm activity","Samples of past air, with its CO2 and methane"],"answer":3,"explanation":"As snow compacts into ice, it seals in air; cores going back hundreds of thousands of years show greenhouse gas levels rising and falling with temperature.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अंटार्कटिक हिम क्रोड में फँसे वायु के बुलबुले वैज्ञानिकों को क्या देते हैं?","optionsHi":["बर्फ़ के नीचे की आधारशैल की सटीक आयु","अतीत की महासागरीय लवणता और समुद्र-स्तर परिवर्तनों के अभिलेख","अतीत के सौर धब्बों और सौर तूफ़ान गतिविधि की प्रत्यक्ष गणना","अतीत की वायु के नमूने, उसकी CO2 और मीथेन के साथ"],"explanationHi":"जैसे-जैसे बर्फ़ संकुचित होकर हिम बनती है, वह वायु को भीतर बंद कर लेती है; सैकड़ों हज़ार वर्ष पीछे जाने वाले क्रोड तापमान के साथ हरितगृह गैसों के स्तरों का बढ़ना और घटना दर्शाते हैं।"},
  {"id":"env-ecology-279","question":"Observations show that while the lower atmosphere has warmed, the stratosphere has cooled. This pattern is strong evidence that recent warming is caused by:","options":["A rise in total solar output heating the whole atmosphere","Rising greenhouse gases trapping heat in the lower layers","Large volcanic eruptions injecting sulphate aerosols","Slow changes in the Earth's orbit and axial tilt"],"answer":1,"explanation":"A brighter Sun would warm all layers; cooling aloft with warming below is the fingerprint of greenhouse gases (with ozone loss adding to stratospheric cooling).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"प्रेक्षण दर्शाते हैं कि जहाँ निचला वायुमंडल गर्म हुआ है, वहीं समतापमंडल ठंडा हुआ है। यह पैटर्न इस बात का प्रबल प्रमाण है कि हाल का तापन किसके कारण है?","optionsHi":["कुल सौर उत्पादन में वृद्धि जो पूरे वायुमंडल को गर्म करती है","बढ़ती हरितगृह गैसें जो निचली परतों में ऊष्मा रोकती हैं","बड़े ज्वालामुखी विस्फोट जो सल्फेट एरोसोल पहुँचाते हैं","पृथ्वी की कक्षा और अक्षीय झुकाव में धीमे परिवर्तन"],"explanationHi":"अधिक चमकीला सूर्य सभी परतों को गर्म करता; ऊपर शीतलन और नीचे तापन हरितगृह गैसों की पहचान है (ओज़ोन क्षरण समतापमंडलीय शीतलन में योगदान देता है)।"},
  {"id":"env-ecology-280","question":"Which of the following currently act as net sinks of carbon? 1. Growing forests 2. The oceans 3. Drained peatlands that are being burned. Select the correct answer.","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Growing forests and the oceans take up a large share of human emissions; drained and burning peat releases long-stored carbon and is a source.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से वर्तमान में कार्बन के शुद्ध अवशोषक (सिंक) के रूप में कार्य करते हैं? 1. बढ़ते वन 2. महासागर 3. जल-निकासित पीटभूमियाँ जिन्हें जलाया जा रहा है। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"बढ़ते वन और महासागर मानवीय उत्सर्जन का बड़ा भाग सोखते हैं; जल-निकासित और जलती पीट लंबे समय से संचित कार्बन को मुक्त करती है और स्रोत है।"},
  {"id":"env-ecology-281","question":"Which of the following can deliver net negative emissions, i.e., remove more carbon dioxide from the air than they release? 1. Bioenergy with carbon capture and storage (BECCS) 2. Afforestation 3. Replacing coal-fired power with natural gas. Select the correct answer.","options":["1, 2 and 3","2 and 3 only","1 and 2 only","1 only"],"answer":2,"explanation":"Switching coal to gas only reduces emissions; it still adds CO2. BECCS and new forests draw CO2 out of the air.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से शुद्ध ऋणात्मक उत्सर्जन दे सकते हैं, अर्थात् वायु से जितनी कार्बन डाइऑक्साइड छोड़ते हैं उससे अधिक हटाते हैं? 1. कार्बन अधिग्रहण और भंडारण के साथ जैव-ऊर्जा (BECCS) 2. वनरोपण 3. कोयला-चालित विद्युत की जगह प्राकृतिक गैस का उपयोग। सही उत्तर चुनिए।","optionsHi":["1, 2 और 3","केवल 2 और 3","केवल 1 और 2","केवल 1"],"explanationHi":"कोयले की जगह गैस अपनाने से केवल उत्सर्जन घटता है; वह फिर भी CO2 जोड़ती है। BECCS और नए वन वायु से CO2 बाहर खींचते हैं।"},
  {"id":"env-ecology-282","question":"Which of the following is a form of solar radiation management rather than carbon dioxide removal?","options":["Ocean iron fertilisation","Stratospheric aerosol injection","Enhanced weathering of crushed basalt","Direct air capture"],"answer":1,"explanation":"Solar radiation management reflects sunlight to cool the planet without touching CO2 levels; the other three are attempts to pull CO2 out of the air.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा कार्बन डाइऑक्साइड निष्कासन के बजाय सौर विकिरण प्रबंधन का एक रूप है?","optionsHi":["महासागरीय लौह निषेचन","समतापमंडलीय एरोसोल अंतःक्षेपण","कुचले बेसाल्ट का संवर्धित अपक्षय","प्रत्यक्ष वायु अधिग्रहण"],"explanationHi":"सौर विकिरण प्रबंधन CO2 के स्तरों को छुए बिना सूर्य के प्रकाश को परावर्तित कर ग्रह को ठंडा करता है; शेष तीनों वायु से CO2 बाहर खींचने के प्रयास हैं।"},
  {"id":"env-ecology-283","question":"Consider the following statements: 1. During El Niño, sea-surface temperatures in the central and eastern equatorial Pacific are above normal. 2. El Niño years are often, though not always, associated with below-normal Indian monsoon rainfall. 3. A positive Indian Ocean Dipole can partly offset the effect of El Niño on the Indian monsoon. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three hold; in 1997, for example, a strong El Niño coincided with a near-normal monsoon, partly because of a positive Indian Ocean Dipole.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. एल नीनो के दौरान मध्य और पूर्वी भूमध्यरेखीय प्रशांत में समुद्र-सतह तापमान सामान्य से अधिक होता है। 2. एल नीनो वर्ष प्रायः, परंतु सदैव नहीं, भारतीय मानसून की सामान्य से कम वर्षा से जुड़े होते हैं। 3. धनात्मक हिंद महासागर द्विध्रुव (इंडियन ओशन डाइपोल) भारतीय मानसून पर एल नीनो के प्रभाव की आंशिक रूप से भरपाई कर सकता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं; उदाहरणतः 1997 में प्रबल एल नीनो के साथ लगभग सामान्य मानसून रहा, जिसका एक कारण धनात्मक हिंद महासागर द्विध्रुव था।"},
  {"id":"env-ecology-284","question":"Methane hydrates (clathrates) on the sea floor and in permafrost are a concern in the context of climate change because:","options":["They absorb carbon dioxide from the air when they warm","They block the ocean's heat transport to the poles","They make seawater more alkaline as they dissolve","Warming can destabilise them, releasing potent methane"],"answer":3,"explanation":"Hydrates are ice-like solids holding methane, stable only when cold and under pressure; their breakdown could be a positive feedback.","difficulty":"hard","source":"UPSC Prelims","questionHi":"समुद्र तल और पर्माफ्रॉस्ट में मीथेन हाइड्रेट (क्लैथ्रेट) जलवायु परिवर्तन के संदर्भ में चिंता का विषय हैं क्योंकि:","optionsHi":["गर्म होने पर वे वायु से कार्बन डाइऑक्साइड अवशोषित करते हैं","वे महासागर के ध्रुवों तक ऊष्मा परिवहन को अवरुद्ध करते हैं","घुलने पर वे समुद्री जल को अधिक क्षारीय बनाते हैं","तापन उन्हें अस्थिर कर सकता है, जिससे शक्तिशाली मीथेन मुक्त होती है"],"explanationHi":"हाइड्रेट बर्फ़ जैसे ठोस हैं जिनमें मीथेन होती है, जो केवल ठंड और दाब में स्थिर रहते हैं; उनका टूटना धनात्मक पुनर्निवेश बन सकता है।"},
  {"id":"env-ecology-285","question":"Assertion (A): The Arctic is warming faster than the global average. Reason (R): The loss of snow and sea ice lowers the surface albedo, so more sunlight is absorbed. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This 'Arctic amplification' is driven largely by the ice–albedo feedback, along with changes in atmospheric heat transport and the lapse rate.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अभिकथन (A): आर्कटिक वैश्विक औसत से अधिक तेज़ी से गर्म हो रहा है। कारण (R): बर्फ़ और समुद्री बर्फ़ के घटने से सतही एल्बिडो घटता है, इसलिए अधिक सूर्य प्रकाश अवशोषित होता है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"यह 'आर्कटिक प्रवर्धन' मुख्यतः हिम–एल्बिडो पुनर्निवेश से संचालित होता है, साथ ही वायुमंडलीय ऊष्मा परिवहन और ह्रास दर में परिवर्तनों से।"},
  {"id":"env-ecology-286","question":"Which of the following are among the three objectives of the Convention on Biological Diversity? 1. Conservation of biological diversity 2. Sustainable use of its components 3. Fair and equitable sharing of the benefits arising from the use of genetic resources 4. A ban on international trade in endangered species. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"The CBD's three objectives are conservation, sustainable use and benefit-sharing; regulating trade in endangered species is the job of CITES.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से जैव विविधता पर कन्वेंशन के तीन उद्देश्यों में से हैं? 1. जैव विविधता का संरक्षण 2. उसके घटकों का सतत उपयोग 3. आनुवंशिक संसाधनों के उपयोग से उत्पन्न लाभों का न्यायसंगत और समान बँटवारा 4. लुप्तप्राय प्रजातियों के अंतरराष्ट्रीय व्यापार पर प्रतिबंध। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"CBD के तीन उद्देश्य संरक्षण, सतत उपयोग और लाभ-बँटवारा हैं; लुप्तप्राय प्रजातियों के व्यापार का विनियमन CITES का कार्य है।"},
  {"id":"env-ecology-287","question":"Consider the following statements about the Convention on Biological Diversity: 1. It was opened for signature at the Rio Earth Summit in 1992. 2. The United States is not a party to it. 3. Its Cartagena Protocol deals with the safe handling and transboundary movement of living modified organisms. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three hold: the US signed the CBD but never ratified it, and the Cartagena Protocol on Biosafety governs living modified organisms.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैव विविधता पर कन्वेंशन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसे 1992 के रियो पृथ्वी शिखर सम्मेलन में हस्ताक्षर के लिए खोला गया था। 2. संयुक्त राज्य अमेरिका इसका पक्षकार नहीं है। 3. इसका कार्टाजेना प्रोटोकॉल जीवित रूपांतरित जीवों के सुरक्षित प्रबंधन और सीमा-पार आवाजाही से संबंधित है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं: अमेरिका ने CBD पर हस्ताक्षर किए पर कभी अनुसमर्थन नहीं किया, और जैव सुरक्षा पर कार्टाजेना प्रोटोकॉल जीवित रूपांतरित जीवों को नियंत्रित करता है।"},
  {"id":"env-ecology-288","question":"Consider the following statements about CITES: 1. Species in Appendix I are threatened with extinction, and commercial international trade in them is generally not permitted. 2. Species are placed in Appendix III at the request of a party that already regulates trade in them and needs other countries' help. 3. CITES regulates trade in wildlife within a country's own borders. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"CITES covers only international trade; domestic trade is left to national laws such as India's Wildlife (Protection) Act.","difficulty":"hard","source":"UPSC Prelims","questionHi":"CITES के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. परिशिष्ट I की प्रजातियाँ विलुप्ति के खतरे में हैं, और उनमें वाणिज्यिक अंतरराष्ट्रीय व्यापार सामान्यतः अनुमत नहीं है। 2. प्रजातियाँ परिशिष्ट III में उस पक्षकार के अनुरोध पर रखी जाती हैं जो पहले से उनके व्यापार को विनियमित करता है और जिसे अन्य देशों की सहायता चाहिए। 3. CITES किसी देश की अपनी सीमाओं के भीतर वन्यजीव व्यापार को विनियमित करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1","1, 2 और 3"],"explanationHi":"CITES केवल अंतरराष्ट्रीय व्यापार को शामिल करता है; घरेलू व्यापार राष्ट्रीय कानूनों, जैसे भारत के वन्यजीव (संरक्षण) अधिनियम, पर छोड़ा गया है।"},
  {"id":"env-ecology-289","question":"Which international agreement is also known as the 'Washington Convention'?","options":["The Bonn Convention on Migratory Species","The Ramsar Convention","CITES","The Basel Convention"],"answer":2,"explanation":"CITES was signed in Washington, D.C. in 1973 and came into force in 1975; the CMS was signed in Bonn and the Ramsar Convention in Iran.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"कौन-सा अंतरराष्ट्रीय समझौता 'वाशिंगटन कन्वेंशन' के नाम से भी जाना जाता है?","optionsHi":["प्रवासी प्रजातियों पर बॉन कन्वेंशन","रामसर कन्वेंशन","CITES","बेसल कन्वेंशन"],"explanationHi":"CITES पर 1973 में वाशिंगटन, डी.सी. में हस्ताक्षर हुए और यह 1975 में लागू हुआ; CMS पर बॉन में और रामसर कन्वेंशन पर ईरान में हस्ताक्षर हुए।"},
  {"id":"env-ecology-290","question":"Consider the following statements about the Convention on the Conservation of Migratory Species of Wild Animals (CMS): 1. It was signed at Bonn in 1979. 2. India hosted its thirteenth Conference of the Parties at Gandhinagar in 2020. 3. India is not a party to the convention. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"India is a party to the CMS and hosted COP-13 at Gandhinagar, whose mascot was the Great Indian Bustard.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वन्य जीवों की प्रवासी प्रजातियों के संरक्षण पर कन्वेंशन (CMS) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इस पर 1979 में बॉन में हस्ताक्षर हुए। 2. भारत ने 2020 में गांधीनगर में इसके तेरहवें पक्षकार सम्मेलन की मेज़बानी की। 3. भारत इस कन्वेंशन का पक्षकार नहीं है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"भारत CMS का पक्षकार है और उसने गांधीनगर में COP-13 की मेज़बानी की, जिसका शुभंकर ग्रेट इंडियन बस्टर्ड था।"},
  {"id":"env-ecology-291","question":"Consider the following statements: 1. The Vienna Convention (1985) was a framework convention, while the Montreal Protocol (1987) set binding phase-out schedules for ozone-depleting substances. 2. The Vienna Convention and the Montreal Protocol were the first treaties in UN history to achieve universal ratification. 3. A Multilateral Fund helps developing countries meet the costs of complying with the Montreal Protocol. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":2,"explanation":"All three are correct; the ozone treaties are often cited as the most successful environmental agreements, with every UN member a party.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. वियना कन्वेंशन (1985) एक रूपरेखा कन्वेंशन था, जबकि मॉन्ट्रियल प्रोटोकॉल (1987) ने ओज़ोन-क्षयकारी पदार्थों के लिए बाध्यकारी चरणबद्ध समाप्ति की समय-सारणियाँ तय कीं। 2. वियना कन्वेंशन और मॉन्ट्रियल प्रोटोकॉल संयुक्त राष्ट्र के इतिहास में सार्वभौमिक अनुसमर्थन प्राप्त करने वाली पहली संधियाँ थीं। 3. एक बहुपक्षीय कोष विकासशील देशों को मॉन्ट्रियल प्रोटोकॉल के अनुपालन की लागत वहन करने में सहायता करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1"],"explanationHi":"तीनों सही हैं; ओज़ोन संधियों को प्रायः सबसे सफल पर्यावरण समझौते बताया जाता है, जिनमें संयुक्त राष्ट्र का प्रत्येक सदस्य पक्षकार है।"},
  {"id":"env-ecology-292","question":"Consider the following statements about the UN Framework Convention on Climate Change (UNFCCC): 1. It entered into force in 1994. 2. It includes the principle of 'common but differentiated responsibilities and respective capabilities'. 3. It sets legally binding emission targets for each Annex I party. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The UNFCCC is a framework treaty without binding numerical targets; those came with the Kyoto Protocol for developed (Annex I) countries.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र जलवायु परिवर्तन फ्रेमवर्क कन्वेंशन (UNFCCC) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह 1994 में लागू हुआ। 2. इसमें 'साझा परंतु विभेदित उत्तरदायित्व और संबंधित क्षमताएँ' का सिद्धांत शामिल है। 3. यह प्रत्येक अनुलग्नक I पक्षकार के लिए विधिक रूप से बाध्यकारी उत्सर्जन लक्ष्य निर्धारित करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"UNFCCC बाध्यकारी संख्यात्मक लक्ष्यों के बिना एक रूपरेखा संधि है; वे क्योटो प्रोटोकॉल के साथ विकसित (अनुलग्नक I) देशों के लिए आए।"},
  {"id":"env-ecology-293","question":"Under the Kyoto Protocol, which mechanism allowed developed (Annex I) countries to earn emission credits from emission-reduction projects in developing countries?","options":["Joint Implementation","Clean Development Mechanism","International Emissions Trading","REDD+"],"answer":1,"explanation":"The CDM generated Certified Emission Reductions from projects in non-Annex I countries such as India; Joint Implementation involved projects between Annex I countries.","difficulty":"hard","source":"UPSC Prelims","questionHi":"क्योटो प्रोटोकॉल के अंतर्गत कौन-सा तंत्र विकसित (अनुलग्नक I) देशों को विकासशील देशों में उत्सर्जन-कटौती परियोजनाओं से उत्सर्जन क्रेडिट अर्जित करने की अनुमति देता था?","optionsHi":["संयुक्त कार्यान्वयन","स्वच्छ विकास तंत्र","अंतरराष्ट्रीय उत्सर्जन व्यापार","REDD+"],"explanationHi":"CDM ने भारत जैसे अनुलग्नक-रहित देशों की परियोजनाओं से प्रमाणित उत्सर्जन कटौतियाँ उत्पन्न कीं; संयुक्त कार्यान्वयन अनुलग्नक I देशों के बीच की परियोजनाओं से संबंधित था।"},
  {"id":"env-ecology-294","question":"Consider the following statements about the Kyoto Protocol: 1. It entered into force in 2005. 2. Its first commitment period ran from 2008 to 2012. 3. The United States ratified it but later withdrew. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"The US signed but never ratified Kyoto; it was Canada that ratified and later withdrew.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"क्योटो प्रोटोकॉल के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह 2005 में लागू हुआ। 2. इसकी पहली प्रतिबद्धता अवधि 2008 से 2012 तक चली। 3. संयुक्त राज्य अमेरिका ने इसका अनुसमर्थन किया परंतु बाद में उससे हट गया। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"अमेरिका ने क्योटो पर हस्ताक्षर किए पर कभी अनुसमर्थन नहीं किया; यह कनाडा था जिसने अनुसमर्थन किया और बाद में हट गया।"},
  {"id":"env-ecology-295","question":"Consider the following statements about the Paris Agreement: 1. Each party must prepare and communicate successive Nationally Determined Contributions. 2. It sets a legally binding emission target for each country, fixed by the Conference of the Parties. 3. It provides for a global stocktake every five years. Which of the statements given above are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Paris is 'bottom-up': submitting NDCs is binding, but each country sets its own targets; the global stocktake reviews collective progress every five years.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पेरिस समझौते के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. प्रत्येक पक्षकार को क्रमिक राष्ट्रीय स्तर पर निर्धारित योगदान (NDC) तैयार कर प्रस्तुत करने होते हैं। 2. यह प्रत्येक देश के लिए विधिक रूप से बाध्यकारी उत्सर्जन लक्ष्य तय करता है, जो पक्षकार सम्मेलन द्वारा निर्धारित होता है। 3. यह प्रत्येक पाँच वर्ष में वैश्विक समीक्षा (ग्लोबल स्टॉकटेक) का प्रावधान करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"पेरिस 'नीचे से ऊपर' (बॉटम-अप) है: NDC प्रस्तुत करना बाध्यकारी है, पर प्रत्येक देश अपने लक्ष्य स्वयं तय करता है; वैश्विक समीक्षा हर पाँच वर्ष में सामूहिक प्रगति की समीक्षा करती है।"},
  {"id":"env-ecology-296","question":"In REDD+, the '+' refers to:","options":["Additional finance mobilised from private carbon markets and firms","Reducing emissions from agriculture as well as forests","Including wetlands, peatlands and mangroves in the scheme","Conservation, sustainable management and enhancing forest carbon"],"answer":3,"explanation":"REDD stands for Reducing Emissions from Deforestation and forest Degradation; the '+' adds conservation, sustainable forest management and enhancement of carbon stocks.","difficulty":"hard","source":"UPSC Prelims","questionHi":"REDD+ में '+' का क्या अर्थ है?","optionsHi":["निजी कार्बन बाज़ारों और कंपनियों से जुटाया गया अतिरिक्त वित्त","वनों के साथ-साथ कृषि से उत्सर्जन घटाना","योजना में आर्द्रभूमियों, पीटभूमियों और मैंग्रोव को शामिल करना","संरक्षण, सतत प्रबंधन और वन कार्बन में वृद्धि"],"explanationHi":"REDD का अर्थ है वनोन्मूलन और वन निम्नीकरण से उत्सर्जन में कमी (Reducing Emissions from Deforestation and forest Degradation); '+' संरक्षण, सतत वन प्रबंधन और कार्बन भंडारों में वृद्धि जोड़ता है।"},
  {"id":"env-ecology-297","question":"The headquarters of the Green Climate Fund, set up under the UNFCCC, is located in:","options":["Songdo, South Korea","Bonn, Germany","Geneva, Switzerland","Nairobi, Kenya"],"answer":0,"explanation":"The GCF was set up at COP-16 in Cancún (2010) and is based in Songdo, Incheon; Bonn hosts the UNFCCC secretariat and Nairobi hosts UNEP.","difficulty":"hard","source":"UPSC Prelims","questionHi":"UNFCCC के अंतर्गत स्थापित हरित जलवायु कोष का मुख्यालय कहाँ स्थित है?","optionsHi":["सोंगदो, दक्षिण कोरिया","बॉन, जर्मनी","जिनेवा, स्विट्ज़रलैंड","नैरोबी, केन्या"],"explanationHi":"GCF की स्थापना कैनकन (2010) के COP-16 में हुई थी और यह सोंगदो, इंचियोन में स्थित है; बॉन में UNFCCC सचिवालय और नैरोबी में UNEP है।"},
  {"id":"env-ecology-298","question":"Consider the following statements about the UN Convention to Combat Desertification (UNCCD): 1. It deals with land degradation in arid, semi-arid and dry sub-humid areas. 2. Under it, 'desertification' means only the natural spreading of existing deserts. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Desertification means land degradation in drylands from various factors, including climatic variations and human activities; it is not just the advance of sand dunes.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र मरुस्थलीकरण रोकथाम कन्वेंशन (UNCCD) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह शुष्क, अर्ध-शुष्क और शुष्क उप-आर्द्र क्षेत्रों में भूमि निम्नीकरण से संबंधित है। 2. इसके अंतर्गत 'मरुस्थलीकरण' का अर्थ केवल मौजूदा मरुस्थलों का प्राकृतिक प्रसार है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"मरुस्थलीकरण का अर्थ जलवायु परिवर्तनों और मानवीय गतिविधियों सहित विभिन्न कारकों से शुष्क क्षेत्रों में भूमि निम्नीकरण है; यह केवल रेत के टीलों का आगे बढ़ना नहीं है।"},
  {"id":"env-ecology-299","question":"Which of the following are referred to as the 'Rio Conventions'? 1. UN Framework Convention on Climate Change 2. Convention on Biological Diversity 3. UN Convention to Combat Desertification 4. Ramsar Convention on Wetlands. Select the correct answer.","options":["1 and 2 only","1, 2 and 4 only","1, 2, 3 and 4","1, 2 and 3 only"],"answer":3,"explanation":"The three Rio Conventions arose from the 1992 Earth Summit; the UNCCD was negotiated soon after, as the Summit had called for. Ramsar dates from 1971.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से किन्हें 'रियो कन्वेंशन' कहा जाता है? 1. संयुक्त राष्ट्र जलवायु परिवर्तन फ्रेमवर्क कन्वेंशन 2. जैव विविधता पर कन्वेंशन 3. संयुक्त राष्ट्र मरुस्थलीकरण रोकथाम कन्वेंशन 4. आर्द्रभूमि पर रामसर कन्वेंशन। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 4","1, 2, 3 और 4","केवल 1, 2 और 3"],"explanationHi":"तीनों रियो कन्वेंशन 1992 के पृथ्वी शिखर सम्मेलन से उत्पन्न हुए; UNCCD पर, जैसा शिखर सम्मेलन ने आह्वान किया था, उसके शीघ्र बाद वार्ता हुई। रामसर 1971 का है।"},
  {"id":"env-ecology-300","question":"'Agenda 21', adopted at the Rio Earth Summit in 1992, is:","options":["A non-binding action plan for sustainable development","A legally binding protocol on greenhouse gas emissions","A list of 21 endangered species to be protected worldwide","A treaty on trade in hazardous chemicals"],"answer":0,"explanation":"Agenda 21 is a voluntary, comprehensive plan for sustainable development at global, national and local levels; it has no binding obligations.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"1992 के रियो पृथ्वी शिखर सम्मेलन में अपनाया गया 'एजेंडा 21' क्या है?","optionsHi":["सतत विकास की एक गैर-बाध्यकारी कार्य योजना","हरितगृह गैस उत्सर्जन पर एक विधिक रूप से बाध्यकारी प्रोटोकॉल","विश्व भर में संरक्षित की जाने वाली 21 लुप्तप्राय प्रजातियों की सूची","खतरनाक रसायनों के व्यापार पर एक संधि"],"explanationHi":"एजेंडा 21 वैश्विक, राष्ट्रीय और स्थानीय स्तरों पर सतत विकास की एक स्वैच्छिक, व्यापक योजना है; इसमें कोई बाध्यकारी दायित्व नहीं है।"},
  {"id":"env-ecology-301","question":"The widely cited definition of sustainable development as development that 'meets the needs of the present without compromising the ability of future generations to meet their own needs' comes from:","options":["The Limits to Growth (1972)","Silent Spring (1962)","The Brundtland Report (1987)","The Stockholm Declaration (1972)"],"answer":2,"explanation":"The World Commission on Environment and Development, chaired by Gro Harlem Brundtland, gave this definition in its report Our Common Future (1987); Silent Spring was Rachel Carson's book on pesticides.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"सतत विकास की व्यापक रूप से उद्धृत परिभाषा, कि यह ऐसा विकास है जो 'भावी पीढ़ियों की अपनी आवश्यकताएँ पूरी करने की क्षमता से समझौता किए बिना वर्तमान की आवश्यकताओं को पूरा करता है', किससे आती है?","optionsHi":["द लिमिट्स टू ग्रोथ (1972)","साइलेंट स्प्रिंग (1962)","ब्रंटलैंड रिपोर्ट (1987)","स्टॉकहोम घोषणा (1972)"],"explanationHi":"ग्रो हार्लेम ब्रंटलैंड की अध्यक्षता वाले विश्व पर्यावरण और विकास आयोग ने अपनी रिपोर्ट 'अवर कॉमन फ्यूचर' (1987) में यह परिभाषा दी; साइलेंट स्प्रिंग कीटनाशकों पर रेचल कार्सन की पुस्तक थी।"},
  {"id":"env-ecology-302","question":"Consider the following statements: 1. The UN Environment Programme was set up following the Stockholm Conference of 1972. 2. UNEP is headquartered at Nairobi. 3. World Environment Day, 5 June, marks the opening day of the Stockholm Conference. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct; the UN Conference on the Human Environment opened in Stockholm on 5 June 1972, and UNEP was created later that year with its base in Nairobi.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. संयुक्त राष्ट्र पर्यावरण कार्यक्रम की स्थापना 1972 के स्टॉकहोम सम्मेलन के बाद हुई। 2. UNEP का मुख्यालय नैरोबी में है। 3. विश्व पर्यावरण दिवस, 5 जून, स्टॉकहोम सम्मेलन के उद्घाटन दिवस को चिह्नित करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं; मानव पर्यावरण पर संयुक्त राष्ट्र सम्मेलन 5 जून 1972 को स्टॉकहोम में आरंभ हुआ, और UNEP उसी वर्ष बाद में नैरोबी में अपने मुख्यालय के साथ बना।"},
  {"id":"env-ecology-303","question":"Which of the following were among the original twelve persistent organic pollutants (the 'dirty dozen') listed under the Stockholm Convention? 1. DDT 2. Aldrin 3. Polychlorinated biphenyls (PCBs) 4. Glyphosate. Select the correct answer.","options":["1, 2, 3 and 4","1 and 2 only","2, 3 and 4 only","1, 2 and 3 only"],"answer":3,"explanation":"The dirty dozen included DDT, aldrin, dieldrin, endrin, chlordane, heptachlor, PCBs, dioxins and furans among others; glyphosate is not a listed POP.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से स्टॉकहोम कन्वेंशन के अंतर्गत सूचीबद्ध मूल बारह सतत कार्बनिक प्रदूषकों ('डर्टी डज़न') में से थे? 1. DDT 2. एल्ड्रिन 3. पॉलीक्लोरीनेटेड बाइफिनाइल (PCBs) 4. ग्लाइफोसेट। सही उत्तर चुनिए।","optionsHi":["1, 2, 3 और 4","केवल 1 और 2","केवल 2, 3 और 4","केवल 1, 2 और 3"],"explanationHi":"डर्टी डज़न में DDT, एल्ड्रिन, डाइएल्ड्रिन, एंड्रिन, क्लोरडेन, हेप्टाक्लोर, PCBs, डाइऑक्सिन और फ्यूरान सहित अन्य शामिल थे; ग्लाइफोसेट सूचीबद्ध POP नहीं है।"},
  {"id":"env-ecology-304","question":"Consider the following statements: 1. The Stockholm Convention permits the restricted use of DDT for controlling disease vectors such as malaria mosquitoes. 2. India is a party to the Stockholm Convention. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"DDT is listed with an acceptable-purpose exemption for vector control, which India uses; India ratified the Convention in 2006.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. स्टॉकहोम कन्वेंशन मलेरिया के मच्छरों जैसे रोग वाहकों के नियंत्रण के लिए DDT के सीमित उपयोग की अनुमति देता है। 2. भारत स्टॉकहोम कन्वेंशन का पक्षकार है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"DDT वाहक नियंत्रण के लिए स्वीकार्य उद्देश्य की छूट के साथ सूचीबद्ध है, जिसका भारत उपयोग करता है; भारत ने कन्वेंशन का 2006 में अनुसमर्थन किया।"},
  {"id":"env-ecology-305","question":"Consider the following statements about the Minamata Convention: 1. It is named after a Japanese city where people were poisoned by mercury in industrial waste water. 2. It prohibits new primary mercury mining. 3. It covers mercury use in artisanal and small-scale gold mining. Which of the statements given above are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Adopted in 2013, the Convention covers the whole life cycle of mercury: mining, products such as thermometers, emissions, and artisanal gold mining.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मिनामाता कन्वेंशन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसका नाम एक जापानी शहर के नाम पर है जहाँ औद्योगिक अपशिष्ट जल में पारे से लोग विषाक्त हुए थे। 2. यह नए प्राथमिक पारा खनन को प्रतिबंधित करता है। 3. यह कारीगरी और लघु-स्तरीय स्वर्ण खनन में पारे के उपयोग को शामिल करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"2013 में अपनाया गया यह कन्वेंशन पारे के संपूर्ण जीवन चक्र को शामिल करता है: खनन, थर्मामीटर जैसे उत्पाद, उत्सर्जन और कारीगरी स्वर्ण खनन।"},
  {"id":"env-ecology-306","question":"The Nagoya–Kuala Lumpur Supplementary Protocol relates to:","options":["Access to genetic resources and fair benefit-sharing","Liability and redress for damage caused by LMOs","Control of invasive alien species in island ecosystems","Marine biodiversity in areas beyond national jurisdiction"],"answer":1,"explanation":"It supplements the Cartagena Protocol on Biosafety, covering liability and redress for damage from living modified organisms (LMOs); access and benefit-sharing is the subject of the separate Nagoya Protocol.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नागोया–कुआलालंपुर पूरक प्रोटोकॉल किससे संबंधित है?","optionsHi":["आनुवंशिक संसाधनों तक पहुँच और न्यायसंगत लाभ-बँटवारा","LMOs से हुई क्षति के लिए दायित्व और उपचार","द्वीपीय पारिस्थितिकी तंत्रों में आक्रामक विदेशी प्रजातियों का नियंत्रण","राष्ट्रीय क्षेत्राधिकार से परे क्षेत्रों में समुद्री जैव विविधता"],"explanationHi":"यह जैव सुरक्षा पर कार्टाजेना प्रोटोकॉल का पूरक है, जो जीवित रूपांतरित जीवों (LMOs) से हुई क्षति के लिए दायित्व और उपचार को शामिल करता है; पहुँच और लाभ-बँटवारा अलग नागोया प्रोटोकॉल का विषय है।"},
  {"id":"env-ecology-307","question":"The global moratorium on commercial whaling was introduced by which body, taking effect from 1986?","options":["CITES","The Convention on Migratory Species (CMS)","UNCLOS","The International Whaling Commission"],"answer":3,"explanation":"The IWC, set up under the 1946 International Convention for the Regulation of Whaling, adopted the moratorium in 1982 to take effect from the 1986 season.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वाणिज्यिक व्हेल शिकार पर वैश्विक रोक किस निकाय ने लागू की, जो 1986 से प्रभावी हुई?","optionsHi":["CITES","प्रवासी प्रजातियों पर कन्वेंशन (CMS)","UNCLOS","अंतरराष्ट्रीय व्हेलिंग आयोग"],"explanationHi":"1946 के व्हेल शिकार के विनियमन हेतु अंतरराष्ट्रीय कन्वेंशन के अंतर्गत स्थापित IWC ने 1982 में यह रोक अपनाई, जो 1986 के मौसम से प्रभावी हुई।"},
  {"id":"env-ecology-308","question":"The MARPOL Convention deals with:","options":["Prevention of pollution of the sea by ships","Conservation of migratory marine mammals","Regulation of deep-sea mining on the seabed","Protection of coral reefs from tourism"],"answer":0,"explanation":"MARPOL, adopted under the International Maritime Organization, covers pollution from ships by oil, chemicals, sewage, garbage and air emissions.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"मार्पोल (MARPOL) कन्वेंशन किससे संबंधित है?","optionsHi":["जहाज़ों द्वारा समुद्री प्रदूषण की रोकथाम","प्रवासी समुद्री स्तनधारियों का संरक्षण","समुद्र तल पर गहरे समुद्र खनन का विनियमन","पर्यटन से प्रवाल भित्तियों की सुरक्षा"],"explanationHi":"अंतरराष्ट्रीय समुद्री संगठन के अंतर्गत अपनाया गया MARPOL जहाज़ों से तेल, रसायनों, सीवेज, कचरे और वायु उत्सर्जन द्वारा प्रदूषण को शामिल करता है।"},
  {"id":"env-ecology-309","question":"Consider the following statements: 1. The Antarctic Treaty, signed in 1959, reserves Antarctica for peaceful purposes and scientific research. 2. The Madrid Protocol (1991) prohibits any activity relating to mineral resources other than scientific research. 3. India's research stations in Antarctica include Maitri and Bharati. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 only"],"answer":1,"explanation":"All three hold; the Madrid Protocol on Environmental Protection designates Antarctica a natural reserve, and Maitri and Bharati are India's working stations.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. 1959 में हस्ताक्षरित अंटार्कटिक संधि अंटार्कटिका को शांतिपूर्ण उद्देश्यों और वैज्ञानिक अनुसंधान के लिए आरक्षित करती है। 2. मैड्रिड प्रोटोकॉल (1991) वैज्ञानिक अनुसंधान के अतिरिक्त खनिज संसाधनों से संबंधित किसी भी गतिविधि को प्रतिबंधित करता है। 3. अंटार्कटिका में भारत के अनुसंधान स्टेशनों में मैत्री और भारती शामिल हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","1, 2 और 3","केवल 2 और 3","केवल 1"],"explanationHi":"तीनों सही हैं; पर्यावरण संरक्षण पर मैड्रिड प्रोटोकॉल अंटार्कटिका को प्राकृतिक आरक्षित क्षेत्र घोषित करता है, और मैत्री तथा भारती भारत के कार्यरत स्टेशन हैं।"},
  {"id":"env-ecology-310","question":"Consider the following statements about the World Heritage Convention: 1. It was adopted under UNESCO in 1972. 2. It covers both cultural and natural heritage. 3. It maintains a 'List of World Heritage in Danger'. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":0,"explanation":"The 1972 Convention protects cultural, natural and mixed sites, and the List in Danger flags sites facing serious threats.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"विश्व धरोहर कन्वेंशन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसे 1972 में यूनेस्को के अंतर्गत अपनाया गया था। 2. यह सांस्कृतिक और प्राकृतिक दोनों धरोहरों को शामिल करता है। 3. यह 'संकटग्रस्त विश्व धरोहर की सूची' रखता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 1 और 2","केवल 2","केवल 1 और 3"],"explanationHi":"1972 का कन्वेंशन सांस्कृतिक, प्राकृतिक और मिश्रित स्थलों की रक्षा करता है, और संकटग्रस्त धरोहर सूची गंभीर खतरे का सामना कर रहे स्थलों को चिह्नित करती है।"},
  {"id":"env-ecology-311","question":"Consider the following statements: 1. The Aichi Biodiversity Targets were adopted at the tenth Conference of the Parties to the CBD at Nagoya in 2010. 2. The Nagoya Protocol on access and benefit-sharing was adopted at the same meeting. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"COP-10 in Nagoya adopted both the Strategic Plan for Biodiversity 2011–2020 with its twenty Aichi Targets and the Nagoya Protocol.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. आइची जैव विविधता लक्ष्य 2010 में नागोया में CBD के दसवें पक्षकार सम्मेलन में अपनाए गए थे। 2. पहुँच और लाभ-बँटवारे पर नागोया प्रोटोकॉल उसी बैठक में अपनाया गया था। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"नागोया के COP-10 ने अपने बीस आइची लक्ष्यों वाली जैव विविधता 2011–2020 की रणनीतिक योजना और नागोया प्रोटोकॉल दोनों को अपनाया।"},
  {"id":"env-ecology-312","question":"The UN Decade on Ecosystem Restoration (2021–2030) is led by:","options":["UNDP and the World Meteorological Organization","UNEP and the Food and Agriculture Organization","IUCN and WWF","UNESCO and UNDP"],"answer":1,"explanation":"The UN General Assembly declared the Decade and asked UNEP and FAO to lead it; IUCN and WWF are not UN bodies.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पारिस्थितिकी तंत्र पुनर्स्थापन पर संयुक्त राष्ट्र दशक (2021–2030) का नेतृत्व कौन करता है?","optionsHi":["UNDP और विश्व मौसम विज्ञान संगठन","UNEP और खाद्य एवं कृषि संगठन","IUCN और WWF","यूनेस्को और UNDP"],"explanationHi":"संयुक्त राष्ट्र महासभा ने इस दशक की घोषणा की और UNEP तथा FAO से इसका नेतृत्व करने को कहा; IUCN और WWF संयुक्त राष्ट्र निकाय नहीं हैं।"},
  {"id":"env-ecology-313","question":"Consider the following statements about the International Union for Conservation of Nature (IUCN): 1. Its members include both governments and civil-society organisations. 2. It is a specialised agency of the United Nations. 3. It is headquartered at Gland, Switzerland. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"IUCN is a membership union of states, government agencies and NGOs with observer status at the UN General Assembly; it is not a UN agency.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अंतरराष्ट्रीय प्रकृति संरक्षण संघ (IUCN) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसके सदस्यों में सरकारें और नागरिक समाज संगठन दोनों शामिल हैं। 2. यह संयुक्त राष्ट्र की एक विशिष्ट एजेंसी है। 3. इसका मुख्यालय ग्लैंड, स्विट्ज़रलैंड में है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"IUCN राज्यों, सरकारी एजेंसियों और NGOs का एक सदस्यता-आधारित संघ है जिसे संयुक्त राष्ट्र महासभा में पर्यवेक्षक का दर्जा प्राप्त है; यह संयुक्त राष्ट्र की एजेंसी नहीं है।"},
  {"id":"env-ecology-314","question":"TRAFFIC, often mentioned in news about the illegal wildlife trade, is:","options":["A UN convention on wildlife crime","An Interpol unit for environmental crime","A branch of the CITES secretariat","A wildlife trade monitoring NGO"],"answer":3,"explanation":"TRAFFIC was set up by WWF and IUCN to monitor wildlife trade and support CITES; it is not itself a treaty body or police agency.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"TRAFFIC, जिसका अवैध वन्यजीव व्यापार संबंधी समाचारों में प्रायः उल्लेख होता है, क्या है?","optionsHi":["वन्यजीव अपराध पर संयुक्त राष्ट्र का एक कन्वेंशन","पर्यावरणीय अपराध के लिए इंटरपोल की एक इकाई","CITES सचिवालय की एक शाखा","वन्यजीव व्यापार की निगरानी करने वाला एक NGO"],"explanationHi":"TRAFFIC की स्थापना WWF और IUCN ने वन्यजीव व्यापार की निगरानी करने और CITES का समर्थन करने के लिए की; यह स्वयं न तो संधि-निकाय है और न पुलिस एजेंसी।"},
  {"id":"env-ecology-315","question":"The Global Environment Facility serves as a financial mechanism for which of the following? 1. UNFCCC 2. Convention on Biological Diversity 3. Stockholm Convention on POPs 4. CITES. Select the correct answer.","options":["1, 2, 3 and 4","1 and 2 only","1, 2 and 3 only","2 and 4 only"],"answer":2,"explanation":"The GEF funds the climate, biodiversity, desertification, POPs and mercury conventions; CITES is not among the conventions it serves as financial mechanism for.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वैश्विक पर्यावरण सुविधा (GEF) निम्नलिखित में से किनके लिए वित्तीय तंत्र के रूप में कार्य करती है? 1. UNFCCC 2. जैव विविधता पर कन्वेंशन 3. POPs पर स्टॉकहोम कन्वेंशन 4. CITES। सही उत्तर चुनिए।","optionsHi":["1, 2, 3 और 4","केवल 1 और 2","केवल 1, 2 और 3","केवल 2 और 4"],"explanationHi":"GEF जलवायु, जैव विविधता, मरुस्थलीकरण, POPs और पारा कन्वेंशनों को वित्त देती है; CITES उन कन्वेंशनों में नहीं है जिनके लिए यह वित्तीय तंत्र है।"},
  {"id":"env-ecology-316","question":"Consider the following statements about the Water (Prevention and Control of Pollution) Act, 1974: 1. The Central Pollution Control Board was first constituted under this Act. 2. Parliament enacted it under Article 252, after the legislatures of several states passed resolutions asking it to do so. 3. It did not provide for State Pollution Control Boards. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":0,"explanation":"Water is a state subject, so Parliament legislated under Article 252 at the request of states; the Act created both the CPCB and the State Boards.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जल (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1974 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. केंद्रीय प्रदूषण नियंत्रण बोर्ड का गठन सर्वप्रथम इसी अधिनियम के अंतर्गत हुआ। 2. संसद ने इसे अनुच्छेद 252 के अंतर्गत अधिनियमित किया, जब कई राज्यों के विधान-मंडलों ने ऐसा करने का अनुरोध करते हुए प्रस्ताव पारित किए। 3. इसमें राज्य प्रदूषण नियंत्रण बोर्डों का प्रावधान नहीं था। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1"],"explanationHi":"जल राज्य का विषय है, इसलिए संसद ने राज्यों के अनुरोध पर अनुच्छेद 252 के अंतर्गत कानून बनाया; अधिनियम ने CPCB और राज्य बोर्ड दोनों बनाए।"},
  {"id":"env-ecology-317","question":"Consider the following statements: 1. Article 48A directs the State to protect and improve the environment and to safeguard forests and wildlife. 2. Article 51A(g) makes it a fundamental duty of every citizen to protect and improve the natural environment and to have compassion for living creatures. 3. Both provisions were inserted by the Constitution (Forty-second Amendment) Act, 1976. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The 42nd Amendment added Article 48A to the Directive Principles and Article 51A(g) to the new chapter on Fundamental Duties.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. अनुच्छेद 48A राज्य को पर्यावरण की रक्षा और सुधार करने तथा वनों और वन्यजीवों की सुरक्षा करने का निर्देश देता है। 2. अनुच्छेद 51A(g) प्रत्येक नागरिक का यह मौलिक कर्तव्य बनाता है कि वह प्राकृतिक पर्यावरण की रक्षा और सुधार करे तथा जीवधारियों के प्रति दयाभाव रखे। 3. दोनों प्रावधान संविधान (बयालीसवाँ संशोधन) अधिनियम, 1976 द्वारा जोड़े गए थे। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"42वें संशोधन ने राज्य के नीति निदेशक तत्वों में अनुच्छेद 48A और मौलिक कर्तव्यों के नए अध्याय में अनुच्छेद 51A(g) जोड़ा।"},
  {"id":"env-ecology-318","question":"After the Forty-second Amendment (1976), the subjects 'Forests' and 'Protection of wild animals and birds' are placed in the:","options":["State List","Union List","Concurrent List","Forests in the State List and wildlife in the Union List"],"answer":2,"explanation":"Both were moved from the State List to the Concurrent List, so Parliament and state legislatures can both legislate on them.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बयालीसवें संशोधन (1976) के बाद, 'वन' और 'वन्य पशुओं और पक्षियों का संरक्षण' विषय किसमें रखे गए हैं?","optionsHi":["राज्य सूची","संघ सूची","समवर्ती सूची","वन राज्य सूची में और वन्यजीव संघ सूची में"],"explanationHi":"दोनों को राज्य सूची से समवर्ती सूची में ले जाया गया, इसलिए संसद और राज्य विधान-मंडल दोनों उन पर कानून बना सकते हैं।"},
  {"id":"env-ecology-319","question":"The Supreme Court of India has recognised the right to a clean and healthy environment as part of:","options":["Article 14, the right to equality","Article 21, the right to life and personal liberty","Article 19(1)(g), the freedom of trade and profession","Article 48A, the Directive Principle on the environment"],"answer":1,"explanation":"The Court read environmental protection into the right to life under Article 21; Article 48A is a Directive Principle and is not enforceable as a right.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"भारत के सर्वोच्च न्यायालय ने स्वच्छ और स्वस्थ पर्यावरण के अधिकार को किसका भाग माना है?","optionsHi":["अनुच्छेद 14, समता का अधिकार","अनुच्छेद 21, जीवन और दैहिक स्वतंत्रता का अधिकार","अनुच्छेद 19(1)(g), व्यापार और वृत्ति की स्वतंत्रता","अनुच्छेद 48A, पर्यावरण पर नीति निदेशक तत्व"],"explanationHi":"न्यायालय ने पर्यावरण संरक्षण को अनुच्छेद 21 के अंतर्गत जीवन के अधिकार में पढ़ा; अनुच्छेद 48A एक नीति निदेशक तत्व है और अधिकार के रूप में प्रवर्तनीय नहीं है।"},
  {"id":"env-ecology-320","question":"In Vellore Citizens' Welfare Forum v. Union of India (1996), the Supreme Court held which of the following to be part of the environmental law of the country?","options":["The doctrine of eminent domain and the polluter pays principle","The public trust doctrine and absolute liability","Strict liability and the doctrine of laches","The precautionary principle and the polluter pays principle"],"answer":3,"explanation":"The case, about tannery pollution in Tamil Nadu, accepted both principles as part of sustainable development; the public trust doctrine came in the Kamal Nath case.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वेल्लोर सिटिज़न्स वेलफेयर फोरम बनाम भारत संघ (1996) में सर्वोच्च न्यायालय ने निम्नलिखित में से किसे देश के पर्यावरण कानून का भाग माना?","optionsHi":["सर्वोपरि अधिकार (एमिनेंट डोमेन) का सिद्धांत और प्रदूषक भुगतान सिद्धांत","लोक न्यास सिद्धांत और निरपेक्ष दायित्व","कठोर दायित्व और विलंब (लैचेस) का सिद्धांत","पूर्व-सावधानी सिद्धांत और प्रदूषक भुगतान सिद्धांत"],"explanationHi":"तमिलनाडु में चर्मशोधन प्रदूषण से संबंधित इस मामले ने दोनों सिद्धांतों को सतत विकास का भाग माना; लोक न्यास सिद्धांत कमल नाथ मामले में आया।"},
  {"id":"env-ecology-321","question":"The principle of 'absolute liability' for enterprises engaged in hazardous or inherently dangerous activities was laid down by the Supreme Court in:","options":["The Vellore Citizens' Welfare Forum case","Oleum gas leak case (M.C. Mehta)","The T.N. Godavarman Thirumulpad case","The M.C. Mehta v. Kamal Nath case"],"answer":1,"explanation":"After the 1986 oleum leak at a Delhi plant, the Court in M.C. Mehta v. Union of India held such enterprises absolutely liable, without the exceptions allowed under the older strict-liability rule. Kamal Nath is the public trust doctrine case.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"खतरनाक या अंतर्निहित रूप से जोखिम भरी गतिविधियों में लगे उद्यमों के लिए 'निरपेक्ष दायित्व' का सिद्धांत सर्वोच्च न्यायालय ने किसमें प्रतिपादित किया?","optionsHi":["वेल्लोर सिटिज़न्स वेलफेयर फोरम मामला","ओलियम गैस रिसाव मामला (एम.सी. मेहता)","टी.एन. गोदावर्मन थिरुमुलपाद मामला","एम.सी. मेहता बनाम कमल नाथ मामला"],"explanationHi":"दिल्ली के एक संयंत्र में 1986 के ओलियम रिसाव के बाद, एम.सी. मेहता बनाम भारत संघ में न्यायालय ने ऐसे उद्यमों को पुराने कठोर-दायित्व नियम में अनुमत अपवादों के बिना निरपेक्ष रूप से उत्तरदायी माना। कमल नाथ लोक न्यास सिद्धांत का मामला है।"},
  {"id":"env-ecology-322","question":"In the T.N. Godavarman Thirumulpad case (1996), the Supreme Court held that the word 'forest' in the Forest (Conservation) Act, 1980 must be understood:","options":["By its dictionary meaning, whatever the ownership or status","As only those areas notified as reserved or protected forests","As only forests owned and managed by the Central Government","As only areas with more than 40 per cent canopy cover"],"answer":0,"explanation":"The ruling greatly widened the Act's reach, bringing private and unclassified forests under its protection.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"टी.एन. गोदावर्मन थिरुमुलपाद मामले (1996) में सर्वोच्च न्यायालय ने निर्णय दिया कि वन (संरक्षण) अधिनियम, 1980 में 'वन' शब्द को किस प्रकार समझा जाना चाहिए?","optionsHi":["उसके शब्दकोशीय अर्थ के अनुसार, स्वामित्व या स्थिति कुछ भी हो","केवल उन क्षेत्रों के रूप में जो आरक्षित या संरक्षित वन के रूप में अधिसूचित हैं","केवल केंद्र सरकार के स्वामित्व और प्रबंधन वाले वनों के रूप में","केवल 40 प्रतिशत से अधिक वितान आच्छादन वाले क्षेत्रों के रूप में"],"explanationHi":"इस निर्णय ने अधिनियम की पहुँच को बहुत बढ़ाया, और निजी तथा अवर्गीकृत वनों को भी उसकी सुरक्षा के अंतर्गत ला दिया।"},
  {"id":"env-ecology-323","question":"The 'public trust doctrine', under which the State holds natural resources such as rivers, forests and seashores as a trustee for the public, was applied by the Supreme Court in:","options":["The Bhopal gas leak case","The oleum gas leak case","The Vellore Citizens' Welfare Forum case","M.C. Mehta v. Kamal Nath (1997)"],"answer":3,"explanation":"In Kamal Nath, about a motel built by diverting the Beas river, the Court held that the State cannot hand over such resources for private use.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"'लोक न्यास सिद्धांत', जिसके अंतर्गत राज्य नदियों, वनों और समुद्र तटों जैसे प्राकृतिक संसाधनों को जनता के न्यासी के रूप में धारण करता है, सर्वोच्च न्यायालय ने किसमें लागू किया?","optionsHi":["भोपाल गैस रिसाव मामला","ओलियम गैस रिसाव मामला","वेल्लोर सिटिज़न्स वेलफेयर फोरम मामला","एम.सी. मेहता बनाम कमल नाथ (1997)"],"explanationHi":"ब्यास नदी का मार्ग मोड़कर बनाए गए एक मोटल से संबंधित कमल नाथ मामले में न्यायालय ने निर्णय दिया कि राज्य ऐसे संसाधन निजी उपयोग के लिए नहीं सौंप सकता।"},
  {"id":"env-ecology-324","question":"Consider the following statements: 1. Under the Forest (Conservation) Act, 1980, a state government needs the prior approval of the Central Government to use forest land for non-forest purposes. 2. Money collected for compensatory afforestation is governed by the Compensatory Afforestation Fund Act, 2016. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"The 1980 Act requires central approval for diverting forest land, and the 2016 Act puts the money collected for such diversions into national and state funds.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. वन (संरक्षण) अधिनियम, 1980 के अंतर्गत, राज्य सरकार को वन भूमि का गैर-वन उद्देश्यों के लिए उपयोग करने हेतु केंद्र सरकार की पूर्व स्वीकृति आवश्यक है। 2. प्रतिकारात्मक वनरोपण के लिए एकत्र धनराशि प्रतिकारात्मक वनरोपण निधि अधिनियम, 2016 द्वारा नियंत्रित होती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"1980 का अधिनियम वन भूमि के अन्यत्र उपयोग के लिए केंद्रीय स्वीकृति आवश्यक बनाता है, और 2016 का अधिनियम ऐसे उपयोग के लिए एकत्र धन को राष्ट्रीय और राज्य निधियों में रखता है।"},
  {"id":"env-ecology-325","question":"Consider the following statements about the Indian Forest Act, 1927: 1. It classifies forests as reserved, protected and village forests. 2. It was amended in 2017 so that bamboo grown outside forest areas is no longer treated as a 'tree'. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Reserved forests have the strictest controls; the 2017 amendment freed bamboo grown on private and non-forest land from felling and transit permits.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारतीय वन अधिनियम, 1927 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह वनों को आरक्षित, संरक्षित और ग्राम वनों में वर्गीकृत करता है। 2. इसे 2017 में संशोधित किया गया ताकि वन क्षेत्रों के बाहर उगाए गए बाँस को अब 'वृक्ष' नहीं माना जाता। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"आरक्षित वनों पर सबसे कठोर नियंत्रण होते हैं; 2017 के संशोधन ने निजी और गैर-वन भूमि पर उगाए गए बाँस को कटाई और परिवहन परमिट से मुक्त कर दिया।"},
  {"id":"env-ecology-326","question":"Consider the following statements about the Wildlife (Protection) Act, 1972: 1. It provides for the protection of wild animals, birds and plants. 2. The 2022 amendment added a schedule for specimens listed in the Appendices of CITES. 3. Animals in Schedule I may not be hunted under any circumstances. Which of the statements given above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Chief Wildlife Warden may permit the hunting of even a Schedule I animal if it has become dangerous to human life or is diseased beyond recovery.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वन्यजीव (संरक्षण) अधिनियम, 1972 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह वन्य पशुओं, पक्षियों और पौधों के संरक्षण का प्रावधान करता है। 2. 2022 के संशोधन ने CITES के परिशिष्टों में सूचीबद्ध नमूनों के लिए एक अनुसूची जोड़ी। 3. अनुसूची I के पशुओं का किसी भी परिस्थिति में शिकार नहीं किया जा सकता। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"मुख्य वन्यजीव प्रतिपालक अनुसूची I के पशु का शिकार करने की अनुमति भी दे सकता है यदि वह मानव जीवन के लिए खतरनाक हो गया हो या ठीक न हो सकने की स्थिति तक रोगग्रस्त हो।"},
  {"id":"env-ecology-327","question":"Consider the following statements about declaring an animal 'vermin' under the Wildlife (Protection) Act, 1972: 1. The Central Government may declare a wild animal, other than one in Schedule I, to be vermin for a specified area and period. 2. Only State Governments have the power to declare an animal vermin. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Section 62 gives this power to the Central Government, usually acting on a state's request; animals in Schedule I cannot be declared vermin.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत किसी पशु को 'पीड़क (वर्मिन)' घोषित करने के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. केंद्र सरकार अनुसूची I के अतिरिक्त किसी वन्य पशु को किसी निर्दिष्ट क्षेत्र और अवधि के लिए पीड़क घोषित कर सकती है। 2. किसी पशु को पीड़क घोषित करने की शक्ति केवल राज्य सरकारों के पास है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"धारा 62 यह शक्ति केंद्र सरकार को देती है, जो सामान्यतः राज्य के अनुरोध पर कार्य करती है; अनुसूची I के पशुओं को पीड़क घोषित नहीं किया जा सकता।"},
  {"id":"env-ecology-328","question":"Consider the following statements about the Environment (Protection) Act, 1986: 1. The Central Government can direct the closure of an industry or the stoppage of its electricity or water supply. 2. A citizen can file a complaint in court for an offence under the Act after giving 60 days' notice to the government. 3. The Act does not apply to hazardous substances. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The Act expressly covers the handling of hazardous substances; Section 5 gives sweeping powers of direction and Section 19 allows citizen complaints after notice.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पर्यावरण (संरक्षण) अधिनियम, 1986 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. केंद्र सरकार किसी उद्योग को बंद करने या उसकी बिजली अथवा जल आपूर्ति रोकने का निर्देश दे सकती है। 2. कोई नागरिक सरकार को 60 दिन की सूचना देने के बाद अधिनियम के अंतर्गत किसी अपराध के लिए न्यायालय में शिकायत दर्ज कर सकता है। 3. यह अधिनियम खतरनाक पदार्थों पर लागू नहीं होता। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अधिनियम खतरनाक पदार्थों के प्रबंधन को स्पष्ट रूप से शामिल करता है; धारा 5 निर्देश देने की व्यापक शक्तियाँ देती है और धारा 19 सूचना के बाद नागरिक शिकायतों की अनुमति देती है।"},
  {"id":"env-ecology-329","question":"Consider the following statements about the Environmental Impact Assessment Notification, 2006: 1. It was issued under the Environment (Protection) Act, 1986. 2. Category A projects are appraised at the central level, and Category B projects by State-level Environment Impact Assessment Authorities. 3. Public consultation is required for all Category B2 projects. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Category B2 projects need neither a full EIA report nor public consultation; that is what separates them from B1 projects.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पर्यावरण प्रभाव आकलन अधिसूचना, 2006 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसे पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत जारी किया गया था। 2. श्रेणी A परियोजनाओं का मूल्यांकन केंद्रीय स्तर पर और श्रेणी B परियोजनाओं का मूल्यांकन राज्य-स्तरीय पर्यावरण प्रभाव आकलन प्राधिकरणों द्वारा किया जाता है। 3. सभी श्रेणी B2 परियोजनाओं के लिए जन-परामर्श आवश्यक है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"श्रेणी B2 परियोजनाओं को न पूर्ण EIA रिपोर्ट चाहिए और न जन-परामर्श; यही उन्हें B1 परियोजनाओं से अलग करता है।"},
  {"id":"env-ecology-330","question":"Arrange the stages of environmental clearance under the EIA Notification, 2006 in the correct order: 1. Appraisal 2. Scoping 3. Public consultation 4. Screening","options":["2, 4, 3, 1","4, 3, 2, 1","4, 2, 3, 1","2, 3, 4, 1"],"answer":2,"explanation":"Screening decides whether a B project needs an EIA, scoping sets the terms of reference, public consultation follows the draft report, and appraisal comes last.","difficulty":"hard","source":"UPSC Prelims","questionHi":"EIA अधिसूचना, 2006 के अंतर्गत पर्यावरणीय स्वीकृति के चरणों को सही क्रम में व्यवस्थित कीजिए: 1. मूल्यांकन 2. कार्यक्षेत्र निर्धारण (स्कोपिंग) 3. जन-परामर्श 4. जाँच-परख (स्क्रीनिंग)","optionsHi":["2, 4, 3, 1","4, 3, 2, 1","4, 2, 3, 1","2, 3, 4, 1"],"explanationHi":"स्क्रीनिंग तय करती है कि किसी B परियोजना को EIA की आवश्यकता है या नहीं, स्कोपिंग संदर्भ-शर्तें तय करती है, जन-परामर्श मसौदा रिपोर्ट के बाद होता है, और मूल्यांकन सबसे अंत में आता है।"},
  {"id":"env-ecology-331","question":"Consider the following statements about Coastal Regulation Zone notifications: 1. They are issued under the Environment (Protection) Act, 1986. 2. CRZ-I covers ecologically sensitive areas such as mangroves and coral reefs. 3. CRZ-IV covers the water area from the low tide line up to the limit of territorial waters (12 nautical miles). Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"CRZ-I is the most protected category; CRZ-II covers built-up areas, CRZ-III relatively undisturbed rural areas, and CRZ-IV the territorial waters and tidal water bodies.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"तटीय विनियमन क्षेत्र अधिसूचनाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वे पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत जारी की जाती हैं। 2. CRZ-I मैंग्रोव और प्रवाल भित्तियों जैसे पारिस्थितिक रूप से संवेदनशील क्षेत्रों को शामिल करता है। 3. CRZ-IV निम्न ज्वार रेखा से प्रादेशिक जल की सीमा (12 समुद्री मील) तक के जल क्षेत्र को शामिल करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"CRZ-I सबसे अधिक संरक्षित श्रेणी है; CRZ-II निर्मित क्षेत्रों को, CRZ-III अपेक्षाकृत अबाधित ग्रामीण क्षेत्रों को, और CRZ-IV प्रादेशिक जल तथा ज्वारीय जल निकायों को शामिल करता है।"},
  {"id":"env-ecology-332","question":"Consider the following statements about the National Green Tribunal: 1. It is not bound by the procedure of the Code of Civil Procedure, 1908, but is guided by the principles of natural justice. 2. Appeals against its orders lie to the Supreme Court. 3. It hears cases arising under the Wildlife (Protection) Act, 1972. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":1,"explanation":"The Wildlife (Protection) Act is not among the seven laws listed in Schedule I of the NGT Act, which include the Water, Air, Environment (Protection), Forest (Conservation) and Biological Diversity Acts.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"राष्ट्रीय हरित अधिकरण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह सिविल प्रक्रिया संहिता, 1908 की प्रक्रिया से बाध्य नहीं है, परंतु प्राकृतिक न्याय के सिद्धांतों से निर्देशित होता है। 2. इसके आदेशों के विरुद्ध अपील सर्वोच्च न्यायालय में होती है। 3. यह वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत उत्पन्न मामलों की सुनवाई करता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 1 और 2","केवल 2","केवल 1 और 3"],"explanationHi":"वन्यजीव (संरक्षण) अधिनियम NGT अधिनियम की अनुसूची I में सूचीबद्ध सात कानूनों में नहीं है, जिनमें जल, वायु, पर्यावरण (संरक्षण), वन (संरक्षण) और जैविक विविधता अधिनियम शामिल हैं।"},
  {"id":"env-ecology-333","question":"The Public Liability Insurance Act, 1991 provides for:","options":["Insurance of forest land diverted for industrial projects","Compensation to farmers for crop loss from pollution, decided by courts","Insurance cover for wildlife killed in road and rail accidents","Immediate no-fault relief to victims of hazardous-substance accidents"],"answer":3,"explanation":"Owners handling hazardous substances must take insurance so that victims get quick interim relief without proving negligence.","difficulty":"hard","source":"UPSC Prelims","questionHi":"लोक दायित्व बीमा अधिनियम, 1991 किसका प्रावधान करता है?","optionsHi":["औद्योगिक परियोजनाओं के लिए अन्यत्र उपयोग की गई वन भूमि का बीमा","प्रदूषण से फसल हानि के लिए किसानों को क्षतिपूर्ति, जो न्यायालयों द्वारा तय की जाती है","सड़क और रेल दुर्घटनाओं में मारे गए वन्यजीवों के लिए बीमा कवर","खतरनाक पदार्थों की दुर्घटनाओं के पीड़ितों को तत्काल बिना-दोष राहत"],"explanationHi":"खतरनाक पदार्थों का प्रबंधन करने वाले स्वामियों को बीमा कराना होता है ताकि पीड़ितों को लापरवाही सिद्ध किए बिना शीघ्र अंतरिम राहत मिल सके।"},
  {"id":"env-ecology-334","question":"Consider the following statements about the Biological Diversity Act, 2002: 1. Foreign nationals and companies need the approval of the National Biodiversity Authority before obtaining biological resources occurring in India. 2. Local people and communities, including growers and practitioners of indigenous medicine such as vaids and hakims, are exempt from giving prior intimation to the State Biodiversity Board for access. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"The Act regulates foreign access through the NBA and Indian commercial users through State Boards, while exempting local communities and traditional practitioners.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैविक विविधता अधिनियम, 2002 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. विदेशी नागरिकों और कंपनियों को भारत में पाए जाने वाले जैविक संसाधन प्राप्त करने से पहले राष्ट्रीय जैव विविधता प्राधिकरण की स्वीकृति आवश्यक है। 2. स्थानीय लोग और समुदाय, जिनमें उत्पादक तथा वैद्य और हकीम जैसे स्वदेशी चिकित्सा के चिकित्सक शामिल हैं, पहुँच के लिए राज्य जैव विविधता बोर्ड को पूर्व सूचना देने से मुक्त हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"अधिनियम विदेशी पहुँच को NBA के माध्यम से और भारतीय वाणिज्यिक उपयोगकर्ताओं को राज्य बोर्डों के माध्यम से विनियमित करता है, जबकि स्थानीय समुदायों और पारंपरिक चिकित्सकों को छूट देता है।"},
  {"id":"env-ecology-335","question":"Consider the following statements about the Scheduled Tribes and Other Traditional Forest Dwellers (Recognition of Forest Rights) Act, 2006: 1. 'Other traditional forest dwellers' must have lived primarily in and depended on forests for at least three generations (75 years) before 13 December 2005. 2. Rights recognised under the Act are heritable but cannot be sold or transferred. 3. The Act recognises community rights over minor forest produce and community forest resources. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 only","1 and 3 only"],"answer":1,"explanation":"All three are provisions of the Act; a generation is taken as 25 years, and rights pass to heirs but are not alienable.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुसूचित जनजाति और अन्य परंपरागत वन निवासी (वन अधिकारों की मान्यता) अधिनियम, 2006 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. 'अन्य परंपरागत वन निवासियों' को 13 दिसंबर 2005 से पहले कम से कम तीन पीढ़ियों (75 वर्ष) तक मुख्यतः वनों में रहना और उन पर निर्भर रहना चाहिए। 2. अधिनियम के अंतर्गत मान्यता प्राप्त अधिकार वंशानुगत हैं पर बेचे या हस्तांतरित नहीं किए जा सकते। 3. अधिनियम लघु वन उपज और सामुदायिक वन संसाधनों पर सामुदायिक अधिकारों को मान्यता देता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","1, 2 और 3","केवल 2","केवल 1 और 3"],"explanationHi":"तीनों अधिनियम के प्रावधान हैं; एक पीढ़ी 25 वर्ष मानी जाती है, और अधिकार उत्तराधिकारियों को मिलते हैं पर अंतरणीय नहीं हैं।"},
  {"id":"env-ecology-336","question":"Consider the following statements about tiger reserves: 1. A tiger reserve is notified by the State Government on the recommendation of the National Tiger Conservation Authority. 2. A tiger reserve consists of a core or critical tiger habitat and a buffer or peripheral area. 3. Tiger reserves are notified under the Environment (Protection) Act, 1986. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Tiger reserves are notified under Section 38V of the Wildlife (Protection) Act, inserted by the 2006 amendment, not under the EPA.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बाघ अभयारण्यों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. बाघ अभयारण्य राष्ट्रीय बाघ संरक्षण प्राधिकरण की अनुशंसा पर राज्य सरकार द्वारा अधिसूचित किया जाता है। 2. बाघ अभयारण्य में एक कोर या क्रांतिक बाघ आवास और एक बफर या परिधीय क्षेत्र होता है। 3. बाघ अभयारण्य पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत अधिसूचित किए जाते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"बाघ अभयारण्य वन्यजीव (संरक्षण) अधिनियम की धारा 38V के अंतर्गत अधिसूचित होते हैं, जो 2006 के संशोधन से जोड़ी गई थी, न कि EPA के अंतर्गत।"},
  {"id":"env-ecology-337","question":"Consider the following statements about the Solid Waste Management Rules, 2016: 1. Waste generators must segregate waste into biodegradable (wet), non-biodegradable (dry) and domestic hazardous waste. 2. The rules apply only to municipal areas and not to special economic zones, railways or airports. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The 2016 rules extended coverage beyond municipal areas to census towns, SEZs, railway and airport areas, industrial townships and more.","difficulty":"hard","source":"UPSC Prelims","questionHi":"ठोस अपशिष्ट प्रबंधन नियम, 2016 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. अपशिष्ट उत्पादकों को अपशिष्ट को जैव-निम्नीकरणीय (गीला), अजैव-निम्नीकरणीय (सूखा) और घरेलू खतरनाक अपशिष्ट में पृथक करना होगा। 2. नियम केवल नगरपालिका क्षेत्रों पर लागू होते हैं, विशेष आर्थिक क्षेत्रों, रेलवे या हवाई अड्डों पर नहीं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"2016 के नियमों ने कवरेज को नगरपालिका क्षेत्रों से आगे जनगणना कस्बों, SEZ, रेलवे और हवाई अड्डा क्षेत्रों, औद्योगिक टाउनशिपों आदि तक बढ़ाया।"},
  {"id":"env-ecology-338","question":"Under the Bio-Medical Waste Management Rules, 2016, used needles and other sharps are to be collected in:","options":["Yellow bags for incineration","Red bags for autoclaving and recycling","White puncture-proof translucent boxes","Blue cardboard boxes for glassware"],"answer":2,"explanation":"Yellow is for anatomical and soiled waste, red for contaminated recyclables such as tubing and gloves, white for sharps, and blue for glassware and metallic implants.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैव-चिकित्सा अपशिष्ट प्रबंधन नियम, 2016 के अंतर्गत प्रयुक्त सुइयाँ और अन्य नुकीली वस्तुएँ किसमें एकत्र की जानी हैं?","optionsHi":["भस्मीकरण के लिए पीली थैलियों में","आटोक्लेविंग और पुनर्चक्रण के लिए लाल थैलियों में","सफ़ेद, पंक्चर-रोधी पारभासी डिब्बों में","काँच के सामान के लिए नीले गत्ते के डिब्बों में"],"explanationHi":"पीला रंग शारीरिक और संदूषित अपशिष्ट के लिए, लाल नलिकाओं और दस्तानों जैसे संदूषित पुनर्चक्रणीय पदार्थों के लिए, सफ़ेद नुकीली वस्तुओं के लिए, और नीला काँच तथा धातु के उपकरणों के लिए है।"},
  {"id":"env-ecology-339","question":"Consider the following statements about the Wetlands (Conservation and Management) Rules, 2017: 1. They were framed under the Environment (Protection) Act, 1986. 2. They provide for a State Wetlands Authority in each state and union territory. 3. They exclude river channels and paddy fields from their definition of 'wetland'. Which of the statements given above are correct?","options":["1 only","1 and 2 only","1, 2 and 3","2 and 3 only"],"answer":2,"explanation":"Unlike the broad Ramsar definition, the Indian rules leave out river channels, paddy fields and certain human-made water bodies built for purposes such as drinking water or aquaculture.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आर्द्रभूमि (संरक्षण और प्रबंधन) नियम, 2017 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इन्हें पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत बनाया गया था। 2. वे प्रत्येक राज्य और संघ राज्य क्षेत्र में एक राज्य आर्द्रभूमि प्राधिकरण का प्रावधान करते हैं। 3. वे 'आर्द्रभूमि' की अपनी परिभाषा से नदी जलमार्गों और धान के खेतों को बाहर रखते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","1, 2 और 3","केवल 2 और 3"],"explanationHi":"व्यापक रामसर परिभाषा के विपरीत, भारतीय नियम नदी जलमार्गों, धान के खेतों और पेयजल या जलकृषि जैसे उद्देश्यों के लिए बने कुछ मानव-निर्मित जल निकायों को छोड़ देते हैं।"},
  {"id":"env-ecology-340","question":"The National Forest Policy, 1988 set the goal of having:","options":["Half of the country's area under dense natural forest","One-fourth of the country's area under protected areas","One-third of the plains and half of the hills under tree plantations","33% of land under forest or tree cover, two-thirds in hills"],"answer":3,"explanation":"The policy's national goal is 33 per cent forest or tree cover, rising to two-thirds in hilly and mountainous regions to prevent erosion.","difficulty":"hard","source":"UPSC Prelims","questionHi":"राष्ट्रीय वन नीति, 1988 ने किसका लक्ष्य निर्धारित किया?","optionsHi":["देश के आधे क्षेत्र को घने प्राकृतिक वन के अंतर्गत लाना","देश के एक-चौथाई क्षेत्र को संरक्षित क्षेत्रों के अंतर्गत लाना","मैदानों के एक-तिहाई और पहाड़ियों के आधे भाग को वृक्षारोपण के अंतर्गत लाना","भूमि के 33% भाग को वन या वृक्ष आच्छादन के अंतर्गत लाना, पहाड़ियों में दो-तिहाई"],"explanationHi":"नीति का राष्ट्रीय लक्ष्य 33 प्रतिशत वन या वृक्ष आच्छादन है, जो अपरदन रोकने के लिए पहाड़ी और पर्वतीय क्षेत्रों में बढ़कर दो-तिहाई हो जाता है।"},
  {"id":"env-ecology-341","question":"Consider the following statements about the Compensatory Afforestation Fund Act, 2016: 1. Money collected for compensatory afforestation is credited to funds in the public accounts of India and of the states. 2. Ninety per cent of the money goes to the state funds and ten per cent to the national fund. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"The Act created the National and State Compensatory Afforestation Funds under the public accounts, with a 90:10 split in favour of the states.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"प्रतिकारात्मक वनरोपण निधि अधिनियम, 2016 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. प्रतिकारात्मक वनरोपण के लिए एकत्र धनराशि भारत और राज्यों के लोक लेखा की निधियों में जमा की जाती है। 2. धन का नब्बे प्रतिशत राज्य निधियों में और दस प्रतिशत राष्ट्रीय निधि में जाता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"अधिनियम ने लोक लेखा के अंतर्गत राष्ट्रीय और राज्य प्रतिकारात्मक वनरोपण निधियाँ बनाईं, जिनमें राज्यों के पक्ष में 90:10 का बँटवारा है।"},
  {"id":"env-ecology-342","question":"Which of the following pairs of body and the law under which it was set up are correctly matched? 1. Wildlife Crime Control Bureau — Wildlife (Protection) Act, 1972 2. Central Zoo Authority — Wildlife (Protection) Act, 1972 3. State Biodiversity Boards — Environment (Protection) Act, 1986. Select the correct answer.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The WCCB (2006 amendment) and the Central Zoo Authority (1991 amendment) are bodies under the Wildlife Act; State Biodiversity Boards are set up under the Biological Diversity Act, 2002.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निकाय और उस कानून की निम्नलिखित जोड़ियों में से कौन-सी सही सुमेलित हैं जिसके अंतर्गत वह स्थापित हुआ? 1. वन्यजीव अपराध नियंत्रण ब्यूरो — वन्यजीव (संरक्षण) अधिनियम, 1972 2. केंद्रीय चिड़ियाघर प्राधिकरण — वन्यजीव (संरक्षण) अधिनियम, 1972 3. राज्य जैव विविधता बोर्ड — पर्यावरण (संरक्षण) अधिनियम, 1986। सही उत्तर चुनिए।","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"WCCB (2006 का संशोधन) और केंद्रीय चिड़ियाघर प्राधिकरण (1991 का संशोधन) वन्यजीव अधिनियम के अंतर्गत निकाय हैं; राज्य जैव विविधता बोर्ड जैविक विविधता अधिनियम, 2002 के अंतर्गत स्थापित होते हैं।"},
  {"id":"env-ecology-343","question":"By an amendment in 2023, the Forest (Conservation) Act, 1980 was renamed as the:","options":["Van (Sanrakshan Evam Samvardhan) Adhiniyam, 1980","Van Adhikar (Manyata) Adhiniyam, 1980","Rashtriya Van (Prabandhan) Adhiniyam, 1980","Van Evam Paryavaran (Sanrakshan) Adhiniyam, 1980"],"answer":0,"explanation":"The new name means Forest (Conservation and Augmentation) Act; 'Van Adhikar' (forest rights) belongs to the separate Forest Rights Act, 2006.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2023 के एक संशोधन द्वारा वन (संरक्षण) अधिनियम, 1980 का नाम बदलकर क्या कर दिया गया?","optionsHi":["वन (संरक्षण एवं संवर्धन) अधिनियम, 1980","वन अधिकार (मान्यता) अधिनियम, 1980","राष्ट्रीय वन (प्रबंधन) अधिनियम, 1980","वन एवं पर्यावरण (संरक्षण) अधिनियम, 1980"],"explanationHi":"नए नाम का अर्थ है वन (संरक्षण और संवर्धन) अधिनियम; 'वन अधिकार' अलग वन अधिकार अधिनियम, 2006 का है।"},
  {"id":"env-ecology-344","question":"Consider the following statements about the Air (Prevention and Control of Pollution) Act, 1981: 1. State Governments may declare any area an air pollution control area. 2. Noise was brought within the meaning of 'air pollutant' by an amendment in 1987. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct; the 1987 amendment added noise to the definition of air pollutant, before the separate Noise Rules of 2000.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1981 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. राज्य सरकारें किसी भी क्षेत्र को वायु प्रदूषण नियंत्रण क्षेत्र घोषित कर सकती हैं। 2. 1987 के एक संशोधन द्वारा शोर को 'वायु प्रदूषक' के अर्थ में शामिल किया गया। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं; 1987 के संशोधन ने 2000 के अलग शोर नियमों से पहले शोर को वायु प्रदूषक की परिभाषा में जोड़ा।"},
  {"id":"env-ecology-345","question":"The Environment (Protection) Act, 1986 was enacted by Parliament under Article 253, to implement decisions taken at:","options":["The Rio Earth Summit on Environment and Development, 1992","The Stockholm Conference on the Human Environment, 1972","The Montreal Protocol negotiations, 1987","The Brundtland Commission's 1987 report"],"answer":1,"explanation":"Article 253 lets Parliament legislate to give effect to international decisions; the Act's preamble refers to the Stockholm Conference. Rio came six years after the Act.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पर्यावरण (संरक्षण) अधिनियम, 1986 संसद द्वारा अनुच्छेद 253 के अंतर्गत किन निर्णयों को लागू करने के लिए अधिनियमित किया गया था?","optionsHi":["पर्यावरण और विकास पर रियो पृथ्वी शिखर सम्मेलन, 1992","मानव पर्यावरण पर स्टॉकहोम सम्मेलन, 1972","मॉन्ट्रियल प्रोटोकॉल वार्ताएँ, 1987","ब्रंटलैंड आयोग की 1987 की रिपोर्ट"],"explanationHi":"अनुच्छेद 253 संसद को अंतरराष्ट्रीय निर्णयों को प्रभावी करने के लिए कानून बनाने देता है; अधिनियम की उद्देशिका स्टॉकहोम सम्मेलन का उल्लेख करती है। रियो अधिनियम के छह वर्ष बाद आया।"},
  {"id":"env-ecology-346","question":"Consider the following statements: 1. Keibul Lamjao National Park floats on phumdis in Loktak Lake, Manipur. 2. It is the natural home of the sangai, or brow-antlered deer. 3. Phumdis are floating mats of vegetation, soil and organic matter. Which of the statements given above are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 only"],"answer":1,"explanation":"Keibul Lamjao is the world's only floating national park; the sangai's survival depends on the thickness of the phumdis, which change with the lake's water level.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. केइबुल लामजाओ राष्ट्रीय उद्यान मणिपुर की लोकटक झील में फुमदियों पर तैरता है। 2. यह संगाई, यानी भौंह-सींग वाले हिरण, का प्राकृतिक आवास है। 3. फुमदी वनस्पति, मिट्टी और कार्बनिक पदार्थ की तैरती परतें हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","1, 2 और 3","केवल 2 और 3","केवल 1"],"explanationHi":"केइबुल लामजाओ विश्व का एकमात्र तैरता राष्ट्रीय उद्यान है; संगाई का अस्तित्व फुमदियों की मोटाई पर निर्भर है, जो झील के जल-स्तर के साथ बदलती है।"},
  {"id":"env-ecology-347","question":"Consider the following statements about the leatherback turtle: 1. It is the largest living turtle and lacks a hard bony shell. 2. In India, it nests mainly on beaches of the Andaman and Nicobar Islands. 3. It feeds mainly on jellyfish. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Its carapace is leathery skin over small bones; Great and Little Nicobar and Little Andaman host its nesting beaches, and floating plastic bags are a hazard because they resemble jellyfish.","difficulty":"hard","source":"UPSC Prelims","questionHi":"चमड़ापीठ (लेदरबैक) कछुए के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह सबसे बड़ा जीवित कछुआ है और इसमें कठोर अस्थिमय खोल नहीं होता। 2. भारत में यह मुख्यतः अंडमान और निकोबार द्वीप समूह के समुद्र तटों पर अंडे देता है। 3. यह मुख्यतः जेलीफ़िश खाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"इसका पृष्ठवर्म छोटी हड्डियों पर चर्मीय त्वचा है; ग्रेट और लिटिल निकोबार तथा लिटिल अंडमान इसके नीड़न तटों के घर हैं, और तैरती प्लास्टिक थैलियाँ खतरा हैं क्योंकि वे जेलीफ़िश जैसी दिखती हैं।"},
  {"id":"env-ecology-348","question":"Consider the following statements about pangolins: 1. Two species of pangolin are found in India. 2. Pangolins feed mainly on ants and termites. 3. Pangolin scales are made of keratin. Which of the statements given above are correct?","options":["1, 2 and 3","1 and 2 only","2 only","1 and 3 only"],"answer":0,"explanation":"India has the Indian and the Chinese pangolin; their keratin scales, the same material as human nails, are smuggled for unproven medicinal uses.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पैंगोलिन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. भारत में पैंगोलिन की दो प्रजातियाँ पाई जाती हैं। 2. पैंगोलिन मुख्यतः चींटियों और दीमकों को खाते हैं। 3. पैंगोलिन के शल्क केराटिन के बने होते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["1, 2 और 3","केवल 1 और 2","केवल 2","केवल 1 और 3"],"explanationHi":"भारत में भारतीय और चीनी पैंगोलिन हैं; उनके केराटिन के शल्क, जो मानव नाखूनों जैसी ही सामग्री है, अप्रमाणित औषधीय उपयोगों के लिए तस्करी किए जाते हैं।"},
  {"id":"env-ecology-349","question":"The fishing cat, the state animal of West Bengal, is primarily a species of:","options":["High-altitude alpine grasslands","Dry thorn scrub and ravines","Wetlands, marshes and mangroves","Dense coniferous Himalayan forests"],"answer":2,"explanation":"It hunts fish in wetlands and mangroves such as the Sundarbans and Coringa; draining and converting wetlands is its main threat.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"पश्चिम बंगाल का राज्य पशु मछुआरा बिल्ली (फिशिंग कैट) मुख्यतः किस प्रकार का जीव है?","optionsHi":["उच्च-पर्वतीय अल्पाइन घास के मैदानों का","शुष्क काँटेदार झाड़ियों और बीहड़ों का","आर्द्रभूमियों, दलदलों और मैंग्रोव का","घने शंकुधारी हिमालयी वनों का"],"explanationHi":"यह सुंदरबन और कोरिंगा जैसी आर्द्रभूमियों और मैंग्रोव में मछली का शिकार करती है; आर्द्रभूमियों का जल-निकासन और रूपांतरण इसका मुख्य खतरा है।"},
  {"id":"env-ecology-350","question":"Consider the following statements about vultures in South Asia: 1. Their steep decline was traced to the veterinary drug diclofenac in the carcasses of treated cattle. 2. Diclofenac causes kidney failure in Gyps vultures. 3. Meloxicam is considered a vulture-safe alternative to diclofenac. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Vultures feeding on carcasses of cattle treated with diclofenac died of kidney failure; India banned its veterinary use in 2006 and meloxicam was found safe.","difficulty":"hard","source":"UPSC Prelims","questionHi":"दक्षिण एशिया के गिद्धों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. उनकी तीव्र गिरावट का कारण उपचारित पशुओं के शवों में पशु-चिकित्सा औषधि डाइक्लोफेनाक पाया गया। 2. डाइक्लोफेनाक जिप्स गिद्धों में गुर्दे की विफलता उत्पन्न करता है। 3. मेलोक्सिकैम को डाइक्लोफेनाक का गिद्ध-सुरक्षित विकल्प माना जाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"डाइक्लोफेनाक से उपचारित पशुओं के शव खाने वाले गिद्ध गुर्दे की विफलता से मर गए; भारत ने 2006 में इसके पशु-चिकित्सा उपयोग पर प्रतिबंध लगाया और मेलोक्सिकैम सुरक्षित पाया गया।"},
  {"id":"env-ecology-351","question":"The pygmy hog, the world's smallest wild pig, survives mainly in:","options":["Mangrove forests of the Sundarbans delta","Tall terai grasslands, notably Manas in Assam","Dry deciduous forests of central India","Shola grasslands of the Nilgiris and Anamalais"],"answer":1,"explanation":"It depends on undisturbed tall terai-duar grasslands; dry-season burning and grassland conversion pushed it to the edge of extinction.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पिग्मी हॉग (बौना सूअर), विश्व का सबसे छोटा जंगली सूअर, मुख्यतः कहाँ जीवित है?","optionsHi":["सुंदरबन डेल्टा के मैंग्रोव वनों में","ऊँचे तराई घास के मैदानों में, विशेषकर असम के मानस में","मध्य भारत के शुष्क पर्णपाती वनों में","नीलगिरि और अन्नामलाई के शोला घास के मैदानों में"],"explanationHi":"यह अबाधित ऊँचे तराई-द्वार घास के मैदानों पर निर्भर है; शुष्क ऋतु में जलाने और घास के मैदानों के रूपांतरण ने इसे विलुप्ति के कगार पर पहुँचा दिया।"},
  {"id":"env-ecology-352","question":"Chilika Lake in Odisha is well known for its population of the:","options":["Ganges river dolphin","Indus river dolphin","Irrawaddy dolphin","Finless porpoise"],"answer":2,"explanation":"Chilika, a brackish lagoon, holds one of the largest lagoon populations of the Irrawaddy dolphin; the Ganges dolphin lives in fresh rivers.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"ओडिशा की चिल्का झील किसकी आबादी के लिए प्रसिद्ध है?","optionsHi":["गंगा नदी की डॉल्फिन","सिंधु नदी की डॉल्फिन","इरावदी डॉल्फिन","बिना पंख वाली पोरपॉइज़"],"explanationHi":"चिल्का, एक खारी लैगून, इरावदी डॉल्फिन की सबसे बड़ी लैगून आबादियों में से एक का घर है; गंगा डॉल्फिन मीठे जल की नदियों में रहती है।"},
  {"id":"env-ecology-353","question":"Neelakurinji (Strobilanthes kunthiana), which carpets the shola grasslands of the Western Ghats with blue flowers, is notable because it:","options":["Flowers en masse only once in about twelve years","Flowers every year for a week at the monsoon's peak","Is an invasive weed introduced from Africa","Grows only in the mangrove swamps of Kerala"],"answer":0,"explanation":"This synchronised, long-interval flowering (as in the Munnar hills) is a famous example of gregarious plietesial flowering.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नीलकुरिंजी (स्ट्रोबिलैंथेस कुंथियाना), जो पश्चिमी घाट के शोला घास के मैदानों को नीले फूलों से ढक देती है, इसलिए उल्लेखनीय है क्योंकि:","optionsHi":["यह लगभग बारह वर्षों में केवल एक बार सामूहिक रूप से फूलती है","यह प्रत्येक वर्ष मानसून के चरम पर एक सप्ताह के लिए फूलती है","यह अफ्रीका से लाया गया एक आक्रामक खरपतवार है","यह केवल केरल के मैंग्रोव दलदलों में उगती है"],"explanationHi":"यह समकालिक, लंबे अंतराल वाला पुष्पन (जैसा मुन्नार की पहाड़ियों में) सामूहिक प्लीटीसियल पुष्पन का प्रसिद्ध उदाहरण है।"},
  {"id":"env-ecology-354","question":"Nepenthes khasiana, a plant found in the north-east of India, is:","options":["A mangrove species of the Sundarbans","A parasitic plant that grows on the roots of trees","A floating aquatic weed","A pitcher plant endemic to Meghalaya"],"answer":3,"explanation":"It traps insects in pitcher-shaped leaves to obtain nitrogen in poor soils and is India's only native pitcher plant species.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत के उत्तर-पूर्व में पाया जाने वाला पौधा नेपेंथीज़ खासियाना क्या है?","optionsHi":["सुंदरबन की एक मैंग्रोव प्रजाति","वृक्षों की जड़ों पर उगने वाला परजीवी पौधा","तैरने वाला जलीय खरपतवार","मेघालय का स्थानिक घटपर्णी (पिचर प्लांट)"],"explanationHi":"यह निर्धन मिट्टी में नाइट्रोजन पाने के लिए घट-आकार की पत्तियों में कीटों को फँसाता है और भारत की एकमात्र देशज घटपर्णी प्रजाति है।"},
  {"id":"env-ecology-355","question":"Which of the following are invasive alien species in India? 1. African catfish (Clarias gariepinus) 2. Giant African land snail 3. Golden mahseer. Select the correct answer.","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"The African catfish, introduced for aquaculture, preys on native fish, and the giant African snail damages crops; the golden mahseer is a native Himalayan game fish.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से भारत में आक्रामक विदेशी प्रजातियाँ हैं? 1. अफ्रीकी कैटफ़िश (क्लैरियास गैरीपिनस) 2. विशाल अफ्रीकी भूमि घोंघा 3. गोल्डन महसीर। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1","1, 2 और 3"],"explanationHi":"जलकृषि के लिए लाई गई अफ्रीकी कैटफ़िश स्थानीय मछलियों का शिकार करती है, और विशाल अफ्रीकी घोंघा फसलों को हानि पहुँचाता है; गोल्डन महसीर एक देशज हिमालयी खेल-मछली है।"},
  {"id":"env-ecology-356","question":"Sal and teak are characteristic trees of which forest type in India?","options":["Tropical wet evergreen forests","Tropical deciduous forests","Montane temperate forests","Littoral and swamp forests"],"answer":1,"explanation":"Both shed their leaves in the dry season; sal dominates moister deciduous forests of the north and east, and teak the drier peninsular ones.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"साल और सागौन भारत के किस वन प्रकार के विशिष्ट वृक्ष हैं?","optionsHi":["उष्णकटिबंधीय आर्द्र सदाबहार वन","उष्णकटिबंधीय पर्णपाती वन","पर्वतीय शीतोष्ण वन","तटीय और दलदली वन"],"explanationHi":"दोनों शुष्क ऋतु में पत्तियाँ गिरा देते हैं; साल उत्तर और पूर्व के अधिक नम पर्णपाती वनों में और सागौन अपेक्षाकृत शुष्क प्रायद्वीपीय वनों में प्रमुख होता है।"},
  {"id":"env-ecology-357","question":"Arrange the following vegetation types of the Himalaya in order of increasing altitude: 1. Alpine meadows 2. Tropical deciduous forests 3. Temperate coniferous forests","options":["2, 3, 1","3, 2, 1","2, 1, 3","1, 3, 2"],"answer":0,"explanation":"Deciduous forests clothe the foothills, conifers such as deodar and fir grow higher up, and alpine meadows (bugyals) lie above the tree line.","difficulty":"hard","source":"UPSC Prelims","questionHi":"हिमालय की निम्नलिखित वनस्पति प्रकारों को बढ़ती ऊँचाई के क्रम में व्यवस्थित कीजिए: 1. अल्पाइन घास के मैदान 2. उष्णकटिबंधीय पर्णपाती वन 3. शीतोष्ण शंकुधारी वन","optionsHi":["2, 3, 1","3, 2, 1","2, 1, 3","1, 3, 2"],"explanationHi":"पर्णपाती वन तलहटी को ढकते हैं, देवदार और फर जैसे शंकुधारी वृक्ष उससे ऊपर उगते हैं, और अल्पाइन घास के मैदान (बुग्याल) वृक्ष-रेखा के ऊपर होते हैं।"},
  {"id":"env-ecology-358","question":"Cacti and other CAM plants open their stomata at night rather than during the day. This helps them to:","options":["Absorb dew directly through the open stomata","Avoid insect herbivores, which mostly feed during the day","Fix CO2 with far less water loss, storing it as acids","Release oxygen faster in the cool dark"],"answer":2,"explanation":"Cool night air cuts evaporation; the CO2 fixed at night is released inside the leaf by day while the stomata stay shut.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कैक्टस और अन्य CAM पौधे दिन के बजाय रात में अपने रंध्र खोलते हैं। इससे उन्हें क्या सहायता मिलती है?","optionsHi":["खुले रंध्रों से ओस को सीधे अवशोषित करना","कीट शाकाहारियों से बचना, जो अधिकतर दिन में भोजन करते हैं","बहुत कम जल हानि के साथ CO2 का स्थिरीकरण करना और उसे अम्लों के रूप में संचित करना","ठंडे अंधेरे में ऑक्सीजन तेज़ी से छोड़ना"],"explanationHi":"ठंडी रात की वायु वाष्पीकरण घटाती है; रात में स्थिर की गई CO2 दिन में पत्ती के भीतर मुक्त की जाती है जबकि रंध्र बंद रहते हैं।"},
  {"id":"env-ecology-359","question":"Consider the following statements: 1. In hot, dry conditions, C4 plants use water more efficiently than C3 plants. 2. Wheat and rice are C4 plants. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"C4 plants such as maize, sugarcane and sorghum concentrate CO2 and avoid photorespiration; wheat and rice are C3 plants.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. गर्म, शुष्क परिस्थितियों में C4 पौधे C3 पौधों की तुलना में जल का अधिक कुशलता से उपयोग करते हैं। 2. गेहूँ और धान C4 पौधे हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"मक्का, गन्ना और ज्वार जैसे C4 पौधे CO2 को सांद्रित करते हैं और प्रकाश-श्वसन से बचते हैं; गेहूँ और धान C3 पौधे हैं।"},
  {"id":"env-ecology-360","question":"Alternate wetting and drying of paddy fields, instead of keeping them flooded throughout, reduces methane emissions because:","options":["Dry soil absorbs methane from the air as a sink","Draining aerates soil, suppressing anaerobic methanogens","Rice plants stop growing and respiring when the field is dry","Floodwater itself is the main source of the methane"],"answer":1,"explanation":"Methanogenic archaea work only in anaerobic, waterlogged soil; brief aerobic spells cut their activity, though they can raise nitrous oxide a little.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"धान के खेतों को पूरे समय जलमग्न रखने के बजाय बारी-बारी से गीला और सूखा करने से मीथेन उत्सर्जन घटता है क्योंकि:","optionsHi":["सूखी मिट्टी अवशोषक के रूप में वायु से मीथेन सोख लेती है","जल निकासी मिट्टी में वायु-संचार करती है, जिससे अवायवीय मीथेनोजेन दब जाते हैं","खेत सूखने पर धान के पौधे बढ़ना और श्वसन करना बंद कर देते हैं","बाढ़ का जल स्वयं मीथेन का मुख्य स्रोत है"],"explanationHi":"मीथेनोजेनिक आर्किया केवल अवायवीय, जलमग्न मिट्टी में कार्य करते हैं; संक्षिप्त वायवीय अवधियाँ उनकी गतिविधि घटाती हैं, यद्यपि इससे नाइट्रस ऑक्साइड थोड़ी बढ़ सकती है।"},
  {"id":"env-ecology-361","question":"Coating urea with neem oil mainly helps by:","options":["Making the urea dissolve faster in flood irrigation water","Adding phosphorus and potash to the fertiliser","Killing earthworms that consume soil nitrogen","Slowing nitrification, so nitrogen is released gradually"],"answer":3,"explanation":"Neem compounds inhibit nitrifying bacteria; this improves nitrogen-use efficiency, reduces leaching and nitrous oxide loss, and also discourages diversion of subsidised urea to industry.","difficulty":"hard","source":"UPSC Prelims","questionHi":"यूरिया पर नीम तेल की परत चढ़ाने से मुख्यतः क्या लाभ होता है?","optionsHi":["बाढ़ सिंचाई के जल में यूरिया का तेज़ी से घुलना","उर्वरक में फॉस्फोरस और पोटाश जोड़ना","मिट्टी की नाइट्रोजन का उपभोग करने वाले केंचुओं को मारना","नाइट्रीकरण को धीमा करना, जिससे नाइट्रोजन धीरे-धीरे मुक्त होती है"],"explanationHi":"नीम के यौगिक नाइट्रीकारी जीवाणुओं को बाधित करते हैं; इससे नाइट्रोजन-उपयोग दक्षता बढ़ती है, निक्षालन और नाइट्रस ऑक्साइड की हानि घटती है, और अनुदानित यूरिया के उद्योग की ओर मोड़े जाने को भी हतोत्साहित करता है।"},
  {"id":"env-ecology-362","question":"Ocean thermal energy conversion (OTEC) is best suited to tropical seas because it requires:","options":["A 20 °C gap between surface and deep water","Very high tides twice a day in narrow bays","Strong steady trade winds blowing over the ocean","Warm, highly saline water to improve heat conduction"],"answer":0,"explanation":"OTEC runs a heat engine between warm surface and cold deep water; only tropical waters give a large enough difference over a reasonable depth.","difficulty":"hard","source":"UPSC Prelims","questionHi":"महासागरीय तापीय ऊर्जा रूपांतरण (OTEC) उष्णकटिबंधीय समुद्रों के लिए सबसे उपयुक्त है क्योंकि इसके लिए आवश्यक है:","optionsHi":["सतह और गहरे जल के बीच 20 °C का अंतर","संकरी खाड़ियों में दिन में दो बार बहुत ऊँचे ज्वार","महासागर पर बहने वाली प्रबल, स्थिर व्यापारिक पवनें","ऊष्मा चालन बढ़ाने के लिए गर्म, अत्यधिक लवणीय जल"],"explanationHi":"OTEC गर्म सतही और ठंडे गहरे जल के बीच ऊष्मा इंजन चलाता है; केवल उष्णकटिबंधीय जल ही उचित गहराई पर पर्याप्त बड़ा अंतर देता है।"},
  {"id":"env-ecology-363","question":"The Puga valley in Ladakh is known for its potential for:","options":["Tidal energy","Wind energy","Geothermal energy","Uranium ore mining"],"answer":2,"explanation":"Hot springs and high subsurface temperatures make Puga one of India's most promising geothermal fields.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"लद्दाख की पुगा घाटी किसकी संभावना के लिए जानी जाती है?","optionsHi":["ज्वारीय ऊर्जा","पवन ऊर्जा","भू-तापीय ऊर्जा","यूरेनियम अयस्क खनन"],"explanationHi":"गर्म झरने और उच्च भूमिगत तापमान पुगा को भारत के सबसे आशाजनक भू-तापीय क्षेत्रों में से एक बनाते हैं।"},
  {"id":"env-ecology-364","question":"Consider the following statements: 1. Green hydrogen is produced by electrolysis of water using renewable electricity. 2. Grey hydrogen is produced from natural gas without capturing the carbon dioxide released. 3. Blue hydrogen is made from fossil fuels with the carbon dioxide captured and stored. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The colour labels describe how the hydrogen is made; only the green route avoids fossil fuels altogether.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. हरित हाइड्रोजन नवीकरणीय बिजली से जल के विद्युत-अपघटन द्वारा बनाई जाती है। 2. ग्रे हाइड्रोजन प्राकृतिक गैस से बनाई जाती है और उसमें निकली कार्बन डाइऑक्साइड को पकड़ा नहीं जाता। 3. नीली हाइड्रोजन जीवाश्म ईंधनों से बनाई जाती है और कार्बन डाइऑक्साइड को पकड़कर संग्रहीत किया जाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"रंगों के नाम बताते हैं कि हाइड्रोजन कैसे बनाई जाती है; केवल हरित मार्ग जीवाश्म ईंधनों से पूरी तरह बचता है।"},
  {"id":"env-ecology-365","question":"Second-generation (2G) ethanol is produced mainly from:","options":["Sugarcane juice, molasses and food grains","Lignocellulose, such as crop residues","Algae grown in open ponds or bioreactors","Used cooking oil and animal fats"],"answer":1,"explanation":"First-generation ethanol uses food crops; 2G ethanol breaks down the cellulose in residues such as rice straw, so it does not compete with food.","difficulty":"hard","source":"UPSC Prelims","questionHi":"द्वितीय-पीढ़ी (2G) इथेनॉल मुख्यतः किससे बनाया जाता है?","optionsHi":["गन्ने का रस, शीरा और खाद्यान्न","लिग्नोसेल्यूलोज, जैसे फसल अवशेष","खुले तालाबों या बायोरिएक्टरों में उगाए गए शैवाल","प्रयुक्त खाना पकाने का तेल और पशु वसा"],"explanationHi":"प्रथम-पीढ़ी का इथेनॉल खाद्य फसलों से बनता है; 2G इथेनॉल धान की पराली जैसे अवशेषों में मौजूद सेल्यूलोज को तोड़ता है, इसलिए यह खाद्य से प्रतिस्पर्धा नहीं करता।"},
  {"id":"env-ecology-366","question":"The Gaia hypothesis, which proposes that the Earth's living and non-living parts act together as a self-regulating system, was put forward by:","options":["Rachel Carson","James Lovelock","Aldo Leopold","Garrett Hardin"],"answer":1,"explanation":"Lovelock, later with Lynn Margulis, proposed it in the 1970s; Carson wrote Silent Spring and Hardin 'The Tragedy of the Commons'.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"गैया परिकल्पना, जो प्रस्तावित करती है कि पृथ्वी के जीवित और निर्जीव भाग मिलकर एक स्व-नियामक तंत्र के रूप में कार्य करते हैं, किसने प्रस्तुत की?","optionsHi":["रेचल कार्सन","जेम्स लवलॉक","एल्डो लियोपोल्ड","गैरेट हार्डिन"],"explanationHi":"लवलॉक ने, बाद में लिन मार्गुलिस के साथ, इसे 1970 के दशक में प्रस्तावित किया; कार्सन ने साइलेंट स्प्रिंग और हार्डिन ने 'द ट्रेजेडी ऑफ़ द कॉमन्स' लिखी।"},
  {"id":"env-ecology-367","question":"The Environmental Kuznets Curve hypothesis suggests that, as a country's income per head rises:","options":["Pollution falls steadily from the very start of growth","Pollution rises without limit as output keeps growing","Pollution first falls, then rises again past an income level","Pollution first rises, then falls: an inverted U"],"answer":3,"explanation":"The idea is that richer societies eventually demand and can afford cleaner technology; the curve holds for some local pollutants but is disputed for CO2.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पर्यावरणीय कुज़नेट्स वक्र परिकल्पना सुझाती है कि जैसे-जैसे किसी देश की प्रति व्यक्ति आय बढ़ती है:","optionsHi":["वृद्धि के आरंभ से ही प्रदूषण लगातार घटता है","उत्पादन बढ़ने के साथ प्रदूषण बिना सीमा के बढ़ता है","प्रदूषण पहले घटता है, फिर एक आय स्तर के बाद दोबारा बढ़ता है","प्रदूषण पहले बढ़ता है, फिर घटता है: उलटा U"],"explanationHi":"विचार यह है कि अधिक समृद्ध समाज अंततः स्वच्छ प्रौद्योगिकी की माँग करते हैं और उसे वहन कर सकते हैं; वक्र कुछ स्थानीय प्रदूषकों के लिए सही बैठता है पर CO2 के लिए विवादित है।"},
  {"id":"env-ecology-368","question":"Which one of the following is NOT one of the nine 'planetary boundaries' proposed by Johan Rockström and colleagues?","options":["Ocean acidification","Stratospheric ozone depletion","Size of the human population","Land-system change"],"answer":2,"explanation":"The boundaries cover climate change, biosphere integrity, land-system change, freshwater, biogeochemical flows, ocean acidification, aerosols, ozone and novel entities; population is a driver, not a boundary.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी जोहान रॉकस्ट्रॉम और सहयोगियों द्वारा प्रस्तावित नौ 'ग्रहीय सीमाओं' में से एक नहीं है?","optionsHi":["महासागरीय अम्लीकरण","समतापमंडलीय ओज़ोन क्षरण","मानव आबादी का आकार","भूमि-तंत्र परिवर्तन"],"explanationHi":"सीमाएँ जलवायु परिवर्तन, जैवमंडल अखंडता, भूमि-तंत्र परिवर्तन, मीठा जल, जैव-भू-रासायनिक प्रवाह, महासागरीय अम्लीकरण, एरोसोल, ओज़ोन और नवीन तत्वों को शामिल करती हैं; आबादी एक प्रेरक कारक है, सीमा नहीं।"},
  {"id":"env-ecology-369","question":"Populations of one plant species growing in different habitats show inherited differences in form that suit them to local conditions, which persist when they are grown together in the same garden. Such populations are called:","options":["Ecotypes","Ecads","Ecotones","Ecological equivalents"],"answer":0,"explanation":"Ecotypes differ genetically; ecads differ only because of the environment and lose those differences when grown under the same conditions.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"एक ही पादप प्रजाति की विभिन्न आवासों में उगने वाली आबादियाँ स्थानीय परिस्थितियों के अनुकूल रूप में वंशागत अंतर दिखाती हैं, जो उन्हें एक ही बगीचे में साथ उगाने पर भी बने रहते हैं। ऐसी आबादियाँ क्या कहलाती हैं?","optionsHi":["पारिस्थितिक प्रारूप (इकोटाइप)","इकैड","संक्रमण क्षेत्र (इकोटोन)","पारिस्थितिक समतुल्य"],"explanationHi":"इकोटाइप आनुवंशिक रूप से भिन्न होते हैं; इकैड केवल पर्यावरण के कारण भिन्न होते हैं और समान परिस्थितियों में उगाने पर उन अंतरों को खो देते हैं।"},
  {"id":"env-ecology-370","question":"The part of its potential range of conditions and resources that a species actually occupies in the presence of competitors is called its:","options":["Fundamental niche","Habitat","Ecotone","Realised niche"],"answer":3,"explanation":"The fundamental niche is what a species could use with no competitors; competition usually squeezes it into a smaller realised niche.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किसी प्रजाति द्वारा प्रतिस्पर्धियों की उपस्थिति में अपनी संभावित परिस्थितियों और संसाधनों की सीमा के जिस भाग पर वास्तव में अधिकार किया जाता है, उसे क्या कहते हैं?","optionsHi":["मूलभूत निकेत","आवास","संक्रमण क्षेत्र (इकोटोन)","प्राप्त (रियलाइज़्ड) निकेत"],"explanationHi":"मूलभूत निकेत वह है जिसका कोई प्रजाति प्रतिस्पर्धियों के बिना उपयोग कर सकती है; प्रतिस्पर्धा सामान्यतः उसे एक छोटे प्राप्त निकेत में सीमित कर देती है।"},
  {"id":"env-ecology-371","question":"Where two similar species of finch live on the same island, their beak sizes differ more than where each lives alone. This pattern is called:","options":["Convergent evolution","Character displacement","Competitive release","Adaptive radiation"],"answer":1,"explanation":"Competition favours divergence in the traits used for feeding where the species overlap; competitive release is a species widening its niche when a competitor is absent.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जहाँ एक ही द्वीप पर फिंच पक्षी की दो समान प्रजातियाँ रहती हैं, वहाँ उनकी चोंच के आकार में अंतर उस स्थिति से अधिक होता है जहाँ प्रत्येक अकेली रहती है। इस पैटर्न को क्या कहते हैं?","optionsHi":["अभिसारी विकास","लक्षण विस्थापन (कैरेक्टर डिस्प्लेसमेंट)","प्रतिस्पर्धी मुक्ति","अनुकूली विकिरण"],"explanationHi":"प्रतिस्पर्धा वहाँ भोजन में प्रयुक्त लक्षणों में अपसरण को बढ़ावा देती है जहाँ प्रजातियाँ अतिव्यापी होती हैं; प्रतिस्पर्धी मुक्ति तब है जब प्रतिस्पर्धी की अनुपस्थिति में कोई प्रजाति अपना निकेत फैला लेती है।"},
  {"id":"env-ecology-372","question":"A harmless hoverfly with black-and-yellow stripes that resembles a stinging wasp is an example of:","options":["Müllerian mimicry","Batesian mimicry","Camouflage","Aposematism"],"answer":1,"explanation":"In Batesian mimicry a harmless species copies a harmful one; in Müllerian mimicry two harmful species share the same warning pattern.","difficulty":"hard","source":"UPSC Prelims","questionHi":"काली-पीली धारियों वाली एक हानिरहित हॉवरफ्लाई जो डंक मारने वाली ततैया जैसी दिखती है, किसका उदाहरण है?","optionsHi":["मूलरियन अनुकरण","बेट्सियन अनुकरण","छद्मावरण","चेतावनी रंजन (एपोसेमैटिज़्म)"],"explanationHi":"बेट्सियन अनुकरण में हानिरहित प्रजाति हानिकारक प्रजाति की नकल करती है; मूलरियन अनुकरण में दो हानिकारक प्रजातियाँ समान चेतावनी पैटर्न साझा करती हैं।"},
  {"id":"env-ecology-373","question":"The breaking down of detritus into smaller particles by detritivores such as earthworms is called:","options":["Catabolism","Humification","Mineralisation","Fragmentation"],"answer":3,"explanation":"Fragmentation is physical breakdown by detritivores; catabolism is the chemical breakdown by bacterial and fungal enzymes that follows.","difficulty":"hard","source":"UPSC Prelims","questionHi":"केंचुओं जैसे अपरदभक्षियों द्वारा अपरद का छोटे कणों में टूटना क्या कहलाता है?","optionsHi":["अपचय","ह्यूमसीकरण","खनिजीकरण","खंडन (फ्रैगमेंटेशन)"],"explanationHi":"खंडन अपरदभक्षियों द्वारा भौतिक विघटन है; अपचय जीवाणु और कवक के एंजाइमों द्वारा रासायनिक विघटन है जो उसके बाद होता है।"},
  {"id":"env-ecology-374","question":"Consider the following statements: 1. Humus is highly resistant to microbial action and decomposes very slowly. 2. Mineralisation is the release of inorganic nutrients as humus is further broken down by microbes. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Humus is a dark, colloidal store of nutrients that breaks down slowly; its gradual mineralisation releases nutrients for plants.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. ह्यूमस सूक्ष्मजीवी क्रिया के प्रति अत्यधिक प्रतिरोधी होता है और बहुत धीरे अपघटित होता है। 2. खनिजीकरण वह प्रक्रिया है जिसमें सूक्ष्मजीवों द्वारा ह्यूमस के और विघटित होने पर अकार्बनिक पोषक तत्व मुक्त होते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"ह्यूमस पोषक तत्वों का गहरा, कोलॉइडी भंडार है जो धीरे-धीरे टूटता है; उसका क्रमिक खनिजीकरण पौधों के लिए पोषक तत्व मुक्त करता है।"},
  {"id":"env-ecology-375","question":"Although the oceans cover about 70 per cent of the Earth's surface, their share of the biosphere's total annual net primary productivity is roughly:","options":["Two-thirds","Nine-tenths","One-third","Seven-tenths"],"answer":2,"explanation":"Of about 170 billion tonnes of dry matter produced each year, the oceans contribute only about 55 billion, limited by nutrients and light.","difficulty":"hard","source":"UPSC Prelims","questionHi":"यद्यपि महासागर पृथ्वी की सतह के लगभग 70 प्रतिशत भाग को ढकते हैं, जैवमंडल की कुल वार्षिक शुद्ध प्राथमिक उत्पादकता में उनका हिस्सा लगभग कितना है?","optionsHi":["दो-तिहाई","नौ-दसवाँ","एक-तिहाई","सात-दसवाँ"],"explanationHi":"प्रतिवर्ष उत्पन्न लगभग 170 अरब टन शुष्क पदार्थ में से महासागर केवल लगभग 55 अरब का योगदान देते हैं, जो पोषक तत्वों और प्रकाश से सीमित है।"},
  {"id":"env-ecology-376","question":"Assertion (A): The pyramid of energy in an aquatic ecosystem is inverted. Reason (R): In the open ocean, the standing biomass of phytoplankton can be smaller than that of the zooplankton feeding on it. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Only the biomass pyramid can be inverted in the sea; the energy pyramid is always upright because each level receives less energy per unit time than the one below.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): जलीय पारिस्थितिकी तंत्र में ऊर्जा का पिरामिड उलटा होता है। कारण (R): खुले महासागर में पादपप्लवकों का खड़ा जैवभार उन्हें खाने वाले जंतुप्लवकों के जैवभार से कम हो सकता है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"समुद्र में केवल जैवभार का पिरामिड उलटा हो सकता है; ऊर्जा का पिरामिड सदा सीधा रहता है क्योंकि प्रत्येक स्तर को अपने नीचे के स्तर से प्रति इकाई समय कम ऊर्जा मिलती है।"},
  {"id":"env-ecology-377","question":"Assertion (A): Dead leaves decompose much faster on the floor of a tropical rainforest than in a coniferous forest of high latitudes. Reason (R): Warm and moist conditions favour the activity of decomposer microbes. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Temperature and moisture are the main climatic controls on decomposition; cold boreal soils with resinous litter build up thick organic layers instead.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अभिकथन (A): उष्णकटिबंधीय वर्षावन के धरातल पर मृत पत्तियाँ उच्च अक्षांशों के शंकुधारी वन की तुलना में कहीं अधिक तेज़ी से अपघटित होती हैं। कारण (R): गर्म और नम परिस्थितियाँ अपघटक सूक्ष्मजीवों की गतिविधि के अनुकूल होती हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"तापमान और नमी अपघटन के मुख्य जलवायवीय नियंत्रक हैं; रालयुक्त कचरे वाली ठंडी बोरियल मिट्टियों में इसके बजाय मोटी कार्बनिक परतें जमा हो जाती हैं।"},
  {"id":"env-ecology-378","question":"Assertion (A): Molecule for molecule, methane traps far more heat than carbon dioxide. Reason (R): Methane is produced by the anaerobic decomposition of organic matter in wetlands. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but methane's potency comes from how strongly it absorbs infrared in otherwise open parts of the spectrum, not from where it is produced.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): अणु-दर-अणु, मीथेन कार्बन डाइऑक्साइड से कहीं अधिक ऊष्मा रोकती है। कारण (R): मीथेन आर्द्रभूमियों में कार्बनिक पदार्थ के अवायवीय अपघटन से उत्पन्न होती है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"दोनों सही हैं, परंतु मीथेन की शक्ति इस बात से आती है कि वह स्पेक्ट्रम के अन्यथा खुले भागों में अवरक्त को कितनी प्रबलता से अवशोषित करती है, इस बात से नहीं कि वह कहाँ उत्पन्न होती है।"},
  {"id":"env-ecology-379","question":"Assertion (A): Chlorofluorocarbons were once widely used as refrigerants and aerosol propellants. Reason (R): CFCs are highly reactive and toxic in the lower atmosphere. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"CFCs were popular precisely because they are stable, non-flammable and non-toxic; that stability lets them survive long enough to reach the stratosphere.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): क्लोरोफ्लोरोकार्बन कभी रेफ्रिजरेंट और एरोसोल प्रणोदक के रूप में व्यापक रूप से प्रयुक्त होते थे। कारण (R): CFCs निचले वायुमंडल में अत्यधिक अभिक्रियाशील और विषैले होते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"CFCs ठीक इसलिए लोकप्रिय थे क्योंकि वे स्थिर, अज्वलनशील और विषरहित हैं; यही स्थिरता उन्हें समतापमंडल तक पहुँचने लायक लंबे समय तक बचे रहने देती है।"},
  {"id":"env-ecology-380","question":"Assertion (A): Mangrove forests are well developed in the Sundarbans delta. Reason (R): In many mangrove species, seeds germinate while still attached to the parent tree. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Vivipary is a real mangrove adaptation, but the Sundarbans' extensive mangroves are explained by its sheltered, silt-rich, tidal delta, not by vivipary.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): सुंदरबन डेल्टा में मैंग्रोव वन भली-भाँति विकसित हैं। कारण (R): अनेक मैंग्रोव प्रजातियों में बीज मातृ वृक्ष से जुड़े रहते हुए ही अंकुरित हो जाते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"जरायुजता मैंग्रोव का वास्तविक अनुकूलन है, परंतु सुंदरबन के विस्तृत मैंग्रोव की व्याख्या उसके सुरक्षित, गाद-समृद्ध, ज्वारीय डेल्टा से होती है, जरायुजता से नहीं।"},
  {"id":"env-ecology-381","question":"Assertion (A): In winter, a deep lake in a cold region freezes only at the surface, and fish survive in the water below. Reason (R): Water is densest at about 4 °C, so colder water and ice stay at the top. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Water below 4 °C is lighter and rises, so ice forms on top and insulates the denser, 4 °C water at the bottom.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): शीत ऋतु में, ठंडे क्षेत्र की गहरी झील केवल सतह पर जमती है, और मछलियाँ नीचे के जल में जीवित रहती हैं। कारण (R): जल लगभग 4 °C पर सबसे घना होता है, इसलिए ठंडा जल और बर्फ़ ऊपर रहते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"4 °C से नीचे का जल हल्का होकर ऊपर उठता है, इसलिए बर्फ़ ऊपर बनती है और तल पर स्थित अधिक घने, 4 °C के जल को ऊष्मारोधित कर देती है।"},
  {"id":"env-ecology-382","question":"Assertion (A): Depletion of the ozone layer is the main cause of global warming. Reason (R): Ozone in the stratosphere absorbs ultraviolet radiation from the Sun. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Ozone depletion and global warming are different problems; warming is driven mainly by CO2 and other greenhouse gases, though some ozone-depleting gases also trap heat.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अभिकथन (A): ओज़ोन परत का क्षरण वैश्विक तापन का मुख्य कारण है। कारण (R): समतापमंडल में ओज़ोन सूर्य से आने वाली पराबैंगनी विकिरण को अवशोषित करती है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"ओज़ोन क्षरण और वैश्विक तापन भिन्न समस्याएँ हैं; तापन मुख्यतः CO2 और अन्य हरितगृह गैसों से होता है, यद्यपि कुछ ओज़ोन-क्षयकारी गैसें भी ऊष्मा रोकती हैं।"},
  {"id":"env-ecology-383","question":"Assertion (A): DDT was used widely in India to control malaria mosquitoes. Reason (R): DDT breaks down rapidly in the environment and does not accumulate in food chains. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"DDT is persistent and fat-soluble, which is exactly why it biomagnifies; it is a persistent organic pollutant under the Stockholm Convention.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अभिकथन (A): भारत में मलेरिया के मच्छरों के नियंत्रण के लिए DDT का व्यापक उपयोग किया गया। कारण (R): DDT पर्यावरण में तेज़ी से विघटित हो जाता है और खाद्य श्रृंखलाओं में संचित नहीं होता। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"DDT स्थायी और वसा-विलेय है, इसीलिए यह जैव आवर्धित होता है; यह स्टॉकहोम कन्वेंशन के अंतर्गत एक सतत कार्बनिक प्रदूषक है।"},
  {"id":"env-ecology-384","question":"Assertion (A): Clear-felling the forest in a river's catchment often increases peak flood flows downstream. Reason (R): Forest soils, with their litter and root channels, let more rainwater soak in and so delay runoff. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Without forest cover, infiltration falls and rain runs off quickly, so floods peak higher and sooner and more silt reaches the river.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): किसी नदी के जलग्रहण क्षेत्र में वन की पूर्ण कटाई प्रायः नीचे की ओर बाढ़ के शिखर प्रवाह को बढ़ा देती है। कारण (R): वन की मिट्टी, अपने कचरे और जड़ मार्गों के साथ, अधिक वर्षा जल को सोखने देती है और इस प्रकार अपवाह में देरी करती है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"वन आवरण के बिना अंतःस्यंदन घटता है और वर्षा तेज़ी से बह जाती है, इसलिए बाढ़ अधिक ऊँची और जल्दी चरम पर पहुँचती है और अधिक गाद नदी में पहुँचती है।"},
  {"id":"env-ecology-385","question":"Assertion (A): Lichens are often the pioneer organisms on bare rock. Reason (R): Lichens are sensitive to sulphur dioxide pollution. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Lichens pioneer rock because they tolerate drought and secrete acids that weather it into soil; their SO2 sensitivity makes them pollution indicators but does not explain the pioneering.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): लाइकेन प्रायः नंगी चट्टान पर अग्रगामी जीव होते हैं। कारण (R): लाइकेन सल्फर डाइऑक्साइड प्रदूषण के प्रति संवेदनशील होते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"लाइकेन चट्टान पर अग्रगामी इसलिए बनते हैं क्योंकि वे सूखा सहन करते हैं और अम्ल स्रावित करते हैं जो उसे अपक्षयित कर मिट्टी बनाते हैं; उनकी SO2 संवेदनशीलता उन्हें प्रदूषण सूचक बनाती है, पर अग्रगामी होने की व्याख्या नहीं करती।"},
  {"id":"env-ecology-386","question":"Assertion (A): Mercury contamination of fish is a serious health concern for communities that eat a lot of fish. Reason (R): Inorganic mercury is absorbed and retained in body tissues far more readily than methylmercury. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"It is the other way round: bacteria convert inorganic mercury into methylmercury, which is readily absorbed, retained and biomagnified.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): मछली में पारे का संदूषण उन समुदायों के लिए गंभीर स्वास्थ्य चिंता है जो बहुत मछली खाते हैं। कारण (R): अकार्बनिक पारा मिथाइलमरकरी की तुलना में शरीर के ऊतकों में कहीं अधिक सहजता से अवशोषित और संचित होता है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"बात उलटी है: जीवाणु अकार्बनिक पारे को मिथाइलमरकरी में बदलते हैं, जो सहजता से अवशोषित, संचित और जैव आवर्धित होता है।"},
  {"id":"env-ecology-387","question":"Assertion (A): Secondary succession is usually slower than primary succession. Reason (R): In secondary succession, soil is already present at the start. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Because soil and often seeds survive, secondary succession is faster; primary succession on bare rock must first build soil, which can take centuries.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अभिकथन (A): द्वितीयक अनुक्रमण सामान्यतः प्राथमिक अनुक्रमण से धीमा होता है। कारण (R): द्वितीयक अनुक्रमण में आरंभ में मिट्टी पहले से मौजूद होती है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"क्योंकि मिट्टी और प्रायः बीज बचे रहते हैं, द्वितीयक अनुक्रमण तेज़ होता है; नंगी चट्टान पर प्राथमिक अनुक्रमण को पहले मिट्टी बनानी पड़ती है, जिसमें सदियाँ लग सकती हैं।"},
  {"id":"env-ecology-388","question":"Assertion (A): Coral reefs are often called the 'rainforests of the sea'. Reason (R): Coral reefs are built from the calcium carbonate skeletons of coral polyps. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"The nickname reflects their exceptional biodiversity and productivity, not the material they are built from.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): प्रवाल भित्तियों को प्रायः 'समुद्र के वर्षावन' कहा जाता है। कारण (R): प्रवाल भित्तियाँ प्रवाल पॉलिपों के कैल्शियम कार्बोनेट कंकालों से बनी होती हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"यह उपनाम उनकी असाधारण जैव विविधता और उत्पादकता को दर्शाता है, उस पदार्थ को नहीं जिससे वे बनी हैं।"},
  {"id":"env-ecology-389","question":"Assertion (A): Nitrogen often limits plant growth even though it makes up about 78 per cent of the atmosphere. Reason (R): Most plants can absorb atmospheric nitrogen directly through their leaves. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Plants cannot use N2 gas; they depend on nitrogen fixed into ammonium or nitrate by microbes, lightning or industry, which is why nitrogen is so often limiting.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): नाइट्रोजन वायुमंडल का लगभग 78 प्रतिशत होने पर भी प्रायः पौधों की वृद्धि को सीमित करती है। कारण (R): अधिकांश पौधे वायुमंडलीय नाइट्रोजन को अपनी पत्तियों से सीधे अवशोषित कर सकते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"पौधे N2 गैस का उपयोग नहीं कर सकते; वे सूक्ष्मजीवों, आकाशीय बिजली या उद्योग द्वारा अमोनियम या नाइट्रेट में स्थिर की गई नाइट्रोजन पर निर्भर रहते हैं, इसीलिए नाइट्रोजन प्रायः सीमित करने वाली होती है।"},
  {"id":"env-ecology-390","question":"Assertion (A): Monoculture plantations of eucalyptus restore biodiversity as effectively as natural regeneration of a native forest. Reason (R): Tree plantations can take up and store carbon. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Plantations store carbon, but single-species stands support far fewer species than diverse native forest, so tree cover alone is a poor measure of restoration.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): यूकेलिप्टस के एकल-फसली वृक्षारोपण जैव विविधता को उतनी ही प्रभावी ढंग से पुनर्स्थापित करते हैं जितना किसी देशज वन का प्राकृतिक पुनर्जनन। कारण (R): वृक्षारोपण कार्बन को अवशोषित और संचित कर सकते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"वृक्षारोपण कार्बन संचित करते हैं, परंतु एकल-प्रजाति के झुरमुट विविध देशज वन की तुलना में बहुत कम प्रजातियों को सहारा देते हैं, इसलिए केवल वृक्ष आच्छादन पुनर्स्थापन का खराब माप है।"},
  {"id":"env-ecology-391","question":"Assertion (A): Burning fossil fuels lowers the proportion of carbon-14 in the carbon dioxide of the atmosphere. Reason (R): Fossil fuels are millions of years old, so their carbon-14 has almost completely decayed. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This dilution, the Suess effect, is one of the isotopic fingerprints showing that the rise in atmospheric CO2 comes from fossil carbon.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): जीवाश्म ईंधन जलाने से वायुमंडल की कार्बन डाइऑक्साइड में कार्बन-14 का अनुपात घटता है। कारण (R): जीवाश्म ईंधन लाखों वर्ष पुराने हैं, इसलिए उनका कार्बन-14 लगभग पूरी तरह क्षय हो चुका है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"यह तनुकरण, सूएस प्रभाव, उन समस्थानिक पहचानों में से एक है जो दिखाती हैं कि वायुमंडलीय CO2 में वृद्धि जीवाश्म कार्बन से आ रही है।"},
  {"id":"env-ecology-392","question":"Consider the following statements about wetlands: 1. Many wetlands help recharge groundwater. 2. Wetlands filter sediments and pollutants and are sometimes called the 'kidneys of the landscape'. 3. Draining wetlands always reduces greenhouse gas emissions. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Draining peat-rich wetlands exposes stored carbon to oxygen, releasing large amounts of CO2, even if methane emissions fall.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आर्द्रभूमियों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. अनेक आर्द्रभूमियाँ भूजल पुनर्भरण में सहायक होती हैं। 2. आर्द्रभूमियाँ अवसादों और प्रदूषकों को छानती हैं और कभी-कभी उन्हें 'भू-दृश्य के गुर्दे' कहा जाता है। 3. आर्द्रभूमियों का जल-निकासन सदैव हरितगृह गैस उत्सर्जन को घटाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"पीट-समृद्ध आर्द्रभूमियों का जल-निकासन संचित कार्बन को ऑक्सीजन के संपर्क में लाता है, जिससे CO2 की बड़ी मात्रा मुक्त होती है, भले ही मीथेन उत्सर्जन घट जाए।"},
  {"id":"env-ecology-393","question":"The East Kolkata Wetlands, a Ramsar site, are internationally known for:","options":["Being the largest breeding ground of flamingos in India","Using the city's sewage to farm fish, naturally treating it","Hosting the only Irrawaddy dolphin population in West Bengal","Being a high-altitude glacial lake in the Himalaya"],"answer":1,"explanation":"Kolkata's sewage feeds fishponds (bheris) where sunlight and algae treat the water while producing fish and vegetables: a model of resource recovery.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पूर्वी कोलकाता आर्द्रभूमि, एक रामसर स्थल, अंतरराष्ट्रीय स्तर पर किसके लिए जानी जाती है?","optionsHi":["भारत में राजहंस (फ्लेमिंगो) का सबसे बड़ा प्रजनन स्थल होने के लिए","शहर के सीवेज का उपयोग मछली पालन के लिए करने और उसे प्राकृतिक रूप से उपचारित करने के लिए","पश्चिम बंगाल में इरावदी डॉल्फिन की एकमात्र आबादी का आवास होने के लिए","हिमालय की एक उच्च-पर्वतीय हिमनदीय झील होने के लिए"],"explanationHi":"कोलकाता का सीवेज मछली तालाबों (भेरी) को पोषण देता है जहाँ सूर्य का प्रकाश और शैवाल जल का उपचार करते हैं और साथ ही मछली तथा सब्ज़ियाँ पैदा होती हैं: संसाधन पुनःप्राप्ति का एक मॉडल।"},
  {"id":"env-ecology-394","question":"Sambhar Lake, a Ramsar site that hosts large numbers of flamingos, is:","options":["A freshwater lake formed by a volcanic crater in Maharashtra","A brackish coastal lagoon in Odisha","A glacial lake in Ladakh","India's largest inland saline lake, in Rajasthan"],"answer":3,"explanation":"Sambhar is a shallow saline wetland and a major source of salt; Lonar is the crater lake, Chilika the coastal lagoon.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"सांभर झील, एक रामसर स्थल जहाँ बड़ी संख्या में राजहंस (फ्लेमिंगो) आते हैं, क्या है?","optionsHi":["महाराष्ट्र में ज्वालामुखीय क्रेटर से बनी मीठे पानी की झील","ओडिशा की खारी तटीय लैगून","लद्दाख की हिमनदीय झील","राजस्थान में भारत की सबसे बड़ी अंतर्देशीय खारे पानी की झील"],"explanationHi":"सांभर एक उथली खारी आर्द्रभूमि और नमक का प्रमुख स्रोत है; लोनार क्रेटर झील है, चिल्का तटीय लैगून।"},
  {"id":"env-ecology-395","question":"Two river water samples have a Biochemical Oxygen Demand of 2 mg/L (sample A) and 25 mg/L (sample B). Which of the following is the correct inference?","options":["Sample B likely has more organic pollution and less dissolved oxygen","Sample A is more polluted, because a low BOD means little oxygen is present","BOD measures dissolved salts, so sample B is simply saltier","BOD says nothing about pollution, so the samples cannot be compared"],"answer":0,"explanation":"BOD is the oxygen microbes need to break down organic matter; a high value signals heavy organic (often sewage) load that depletes dissolved oxygen.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नदी के जल के दो नमूनों की जैव रासायनिक ऑक्सीजन माँग 2 mg/L (नमूना A) और 25 mg/L (नमूना B) है। निम्नलिखित में से कौन-सा निष्कर्ष सही है?","optionsHi":["नमूना B में संभवतः अधिक कार्बनिक प्रदूषण और कम घुली ऑक्सीजन है","नमूना A अधिक प्रदूषित है, क्योंकि कम BOD का अर्थ है कि ऑक्सीजन कम है","BOD घुले लवणों को मापती है, इसलिए नमूना B केवल अधिक खारा है","BOD प्रदूषण के बारे में कुछ नहीं बताती, इसलिए नमूनों की तुलना नहीं की जा सकती"],"explanationHi":"BOD वह ऑक्सीजन है जो सूक्ष्मजीवों को कार्बनिक पदार्थ विघटित करने के लिए चाहिए; उच्च मान भारी कार्बनिक (प्रायः सीवेज) भार का संकेत देता है जो घुली ऑक्सीजन को घटाता है।"},
  {"id":"env-ecology-396","question":"According to the monoclimax theory of F. E. Clements, the climax community of a region is determined mainly by:","options":["The type of soil","Climate","Topography","Periodic fire"],"answer":1,"explanation":"Clements held that each climatic region has a single climax; the polyclimax view later argued that soil, topography and fire can produce several stable climaxes.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"एफ. ई. क्लेमेंट्स के एकल-चरम (मोनोक्लाइमैक्स) सिद्धांत के अनुसार, किसी क्षेत्र का चरम समुदाय मुख्यतः किससे निर्धारित होता है?","optionsHi":["मिट्टी के प्रकार से","जलवायु से","भू-आकृति से","आवधिक आग से"],"explanationHi":"क्लेमेंट्स का मत था कि प्रत्येक जलवायु क्षेत्र का एक ही चरम होता है; बहु-चरम (पॉलीक्लाइमैक्स) मत ने बाद में तर्क दिया कि मिट्टी, भू-आकृति और आग कई स्थिर चरम उत्पन्न कर सकते हैं।"},
  {"id":"env-ecology-397","question":"E. P. Odum's 'Y-shaped' model of energy flow shows:","options":["Energy cycling back from top consumers to producers","Energy flowing in equal shares to all trophic levels","Grazing and detritus chains branching from one producer base","Producers and decomposers merged into a single trophic level"],"answer":2,"explanation":"The Y-shaped model splits the flow from producers into a grazing arm and a detritus arm, more realistic than a single-channel chain.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ई. पी. ओडम का ऊर्जा प्रवाह का 'Y-आकार' मॉडल क्या दर्शाता है?","optionsHi":["शीर्ष उपभोक्ताओं से उत्पादकों तक ऊर्जा का वापस चक्रण","सभी पोषण स्तरों को बराबर हिस्सों में ऊर्जा का प्रवाह","एक ही उत्पादक आधार से शाखा लेती चारण और अपरद श्रृंखलाएँ","उत्पादकों और अपघटकों का एक ही पोषण स्तर में विलय"],"explanationHi":"Y-आकार मॉडल उत्पादकों से प्रवाह को एक चारण भुजा और एक अपरद भुजा में विभाजित करता है, जो एकल-मार्ग श्रृंखला से अधिक यथार्थवादी है।"},
  {"id":"env-ecology-398","question":"Consider the following statements about lead pollution: 1. Exposure to lead can harm the neurological development of children. 2. Lead is not a cumulative poison, because the body excretes it quickly. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Lead accumulates in bones and tissues over time; there is no known safe level for children, which is why leaded petrol and lead paints were phased out.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सीसा प्रदूषण के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. सीसे के संपर्क से बच्चों के तंत्रिका-संबंधी विकास को हानि पहुँच सकती है। 2. सीसा संचयी विष नहीं है, क्योंकि शरीर उसे शीघ्र उत्सर्जित कर देता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"सीसा समय के साथ हड्डियों और ऊतकों में जमा होता है; बच्चों के लिए कोई ज्ञात सुरक्षित स्तर नहीं है, इसीलिए सीसायुक्त पेट्रोल और सीसे के रंगों को चरणबद्ध ढंग से हटाया गया।"},
  {"id":"env-ecology-399","question":"Effluents from leather tanneries, such as those along the Ganga at Kanpur, are a major source of which pollutant?","options":["Arsenic","Fluoride","Radon","Chromium"],"answer":3,"explanation":"Chrome tanning uses chromium salts; the hexavalent form that can arise is toxic and carcinogenic, while arsenic and fluoride in groundwater are largely geogenic.","difficulty":"hard","source":"UPSC Prelims","questionHi":"चमड़ा चर्मशोधन कारखानों का बहिःस्राव, जैसे कानपुर में गंगा के किनारे के, किस प्रदूषक का प्रमुख स्रोत है?","optionsHi":["आर्सेनिक","फ्लोराइड","रेडॉन","क्रोमियम"],"explanationHi":"क्रोम चर्मशोधन में क्रोमियम लवणों का उपयोग होता है; इससे बनने वाला षट्संयोजी रूप विषैला और कैंसरजनक है, जबकि भूजल में आर्सेनिक और फ्लोराइड मुख्यतः भू-जनित हैं।"},
  {"id":"env-ecology-400","question":"The Nalgonda technique, developed in India, is used for:","options":["Removing arsenic from groundwater by filtration","Treating chromium-laden tannery effluents","Removing excess fluoride from drinking water","Desalinating seawater for coastal towns"],"answer":2,"explanation":"It uses alum and lime to precipitate fluoride, a problem in groundwater in parts of Andhra Pradesh, Telangana, Rajasthan and other states.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत में विकसित नलगोंडा तकनीक का उपयोग किसके लिए होता है?","optionsHi":["निस्पंदन द्वारा भूजल से आर्सेनिक हटाने के लिए","क्रोमियम-युक्त चर्मशोधन बहिःस्राव का उपचार करने के लिए","पेयजल से अतिरिक्त फ्लोराइड हटाने के लिए","तटीय कस्बों के लिए समुद्री जल का विलवणीकरण करने के लिए"],"explanationHi":"यह फ्लोराइड को अवक्षेपित करने के लिए फिटकरी और चूने का उपयोग करती है, जो आंध्र प्रदेश, तेलंगाना, राजस्थान और अन्य राज्यों के कुछ भागों में भूजल की समस्या है।"},
  {"id":"env-ecology-401","question":"Acid mine drainage arises mainly when:","options":["Exposed pyrite oxidises in air and water to form sulphuric acid","Acid rain falls on open-cast mines and leaches their spoil heaps","Miners use strong acids to dissolve and wash coal","Limestone dust from mines dissolves in rivers as acid"],"answer":0,"explanation":"Oxidation of exposed iron sulphides makes the water acidic and loaded with dissolved metals; limestone, by contrast, neutralises acidity.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अम्लीय खदान जल निकासी मुख्यतः तब उत्पन्न होती है जब:","optionsHi":["उजागर पाइराइट वायु और जल में ऑक्सीकृत होकर सल्फ्यूरिक अम्ल बनाता है","खुली खदानों पर अम्ल वर्षा गिरती है और उनके अपशिष्ट ढेरों का निक्षालन करती है","खनिक कोयले को घोलने और धोने के लिए प्रबल अम्लों का उपयोग करते हैं","खदानों की चूना-पत्थर की धूल नदियों में अम्ल के रूप में घुलती है"],"explanationHi":"उजागर आयरन सल्फाइडों का ऑक्सीकरण जल को अम्लीय और घुली धातुओं से लदा बना देता है; इसके विपरीत, चूना-पत्थर अम्लता को उदासीन करता है।"},
  {"id":"env-ecology-402","question":"Coastal 'dead zones', such as the one that forms each summer in the Gulf of Mexico, are caused mainly by:","options":["Oil spills from tankers and offshore rigs","Nutrient-fed algal blooms whose decay strips the oxygen","Rising sea temperatures alone, which kill fish directly","Overfishing of predatory fish, letting prey overrun reefs"],"answer":1,"explanation":"Fertiliser-rich river water triggers blooms; as the algae die and decay, bottom water becomes hypoxic, so fish and shellfish flee or die.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"तटीय 'मृत क्षेत्र', जैसे मेक्सिको की खाड़ी में प्रत्येक ग्रीष्म में बनने वाला क्षेत्र, मुख्यतः किसके कारण होते हैं?","optionsHi":["टैंकरों और अपतटीय रिगों से तेल रिसाव","पोषक तत्वों से पोषित शैवाल प्रस्फुटन, जिनका अपघटन ऑक्सीजन समाप्त कर देता है","केवल समुद्र के बढ़ते तापमान, जो मछलियों को सीधे मार देते हैं","शिकारी मछलियों की अति-मछली पकड़ाई, जिससे शिकार प्रजातियाँ भित्तियों पर छा जाती हैं"],"explanationHi":"उर्वरक-समृद्ध नदी जल प्रस्फुटन को प्रेरित करता है; जैसे-जैसे शैवाल मरकर अपघटित होते हैं, तलहटी का जल ऑक्सीजन-अल्प हो जाता है, इसलिए मछलियाँ और शंख-जीव भाग जाते हैं या मर जाते हैं।"},
  {"id":"env-ecology-403","question":"Consider the following statements about 'red tides': 1. They are caused by blooms of certain dinoflagellates and other microalgae. 2. Toxins from such blooms can build up in shellfish and poison people who eat them. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Harmful algal blooms can discolour the sea and their toxins concentrate in filter-feeding shellfish, causing paralytic and other shellfish poisoning.","difficulty":"hard","source":"UPSC Prelims","questionHi":"'लाल ज्वार' (रेड टाइड) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. ये कुछ डाइनोफ्लैजेलेट और अन्य सूक्ष्म शैवालों के प्रस्फुटन से होते हैं। 2. ऐसे प्रस्फुटनों के विष शंख-जीवों में जमा हो सकते हैं और उन्हें खाने वाले लोगों को विषाक्त कर सकते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"हानिकारक शैवाल प्रस्फुटन समुद्र का रंग बदल सकते हैं और उनके विष छानकर भोजन करने वाले शंख-जीवों में सांद्रित हो जाते हैं, जिससे पक्षाघातकारी और अन्य शंख-जीव विषाक्तता होती है।"},
  {"id":"env-ecology-404","question":"Endosulfan, whose aerial spraying on cashew plantations in Kasaragod, Kerala was linked to serious health problems, is:","options":["A herbicide that breaks down within days in sunlight","A synthetic phosphorus fertiliser sprayed from the air","A biological pesticide made from neem seed extract","An organochlorine insecticide listed as a POP"],"answer":3,"explanation":"Endosulfan is persistent and toxic; it was added to the Stockholm Convention's list in 2011, the same year India's Supreme Court banned it.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एंडोसल्फान, जिसके केरल के कासरगोड में काजू बागानों पर हवाई छिड़काव को गंभीर स्वास्थ्य समस्याओं से जोड़ा गया, क्या है?","optionsHi":["एक शाकनाशी जो धूप में कुछ ही दिनों में विघटित हो जाता है","हवा से छिड़का जाने वाला एक संश्लेषित फॉस्फोरस उर्वरक","नीम के बीज के अर्क से बना जैविक कीटनाशक","POP के रूप में सूचीबद्ध एक ऑर्गेनोक्लोरीन कीटनाशक"],"explanationHi":"एंडोसल्फान स्थायी और विषैला है; इसे 2011 में स्टॉकहोम कन्वेंशन की सूची में जोड़ा गया, उसी वर्ष भारत के सर्वोच्च न्यायालय ने इस पर प्रतिबंध लगाया।"},
  {"id":"env-ecology-405","question":"Consider the following statements about biochar: 1. It is made by heating biomass with little or no oxygen (pyrolysis). 2. The carbon in biochar is far more stable in soil than the carbon in raw crop residues. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Pyrolysis converts biomass into a stable, porous charcoal that can store carbon in soil for centuries and improve water and nutrient retention.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बायोचार के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह जैवभार को कम या बिना ऑक्सीजन के गर्म करके (पायरोलिसिस) बनाया जाता है। 2. बायोचार का कार्बन मिट्टी में कच्चे फसल अवशेषों के कार्बन की तुलना में कहीं अधिक स्थिर होता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["1 और 2 दोनों","केवल 1","केवल 2","न तो 1 और न ही 2"],"explanationHi":"पायरोलिसिस जैवभार को एक स्थिर, सरंध्र चारकोल में बदल देती है जो मिट्टी में सदियों तक कार्बन संचित कर सकता है और जल तथा पोषक तत्व धारण क्षमता सुधार सकता है।"},
  {"id":"env-ecology-406","question":"Consider the following pairs of protected area and state: 1. Periyar — Kerala 2. Nagarhole — Karnataka 3. Sariska — Rajasthan 4. Nameri — Arunachal Pradesh. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Nameri is in Assam, on the north bank of the Brahmaputra; its neighbour across the border in Arunachal Pradesh is Pakke.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संरक्षित क्षेत्र और राज्य की निम्नलिखित जोड़ियों पर विचार कीजिए: 1. पेरियार — केरल 2. नागरहोले — कर्नाटक 3. सरिस्का — राजस्थान 4. नामेरी — अरुणाचल प्रदेश। उपर्युक्त में से कितनी जोड़ियाँ सही सुमेलित हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"नामेरी असम में, ब्रह्मपुत्र के उत्तरी तट पर है; सीमा के पार अरुणाचल प्रदेश में उसका पड़ोसी पक्के है।"},
  {"id":"env-ecology-407","question":"Consider the following protected areas: 1. Eravikulam 2. Kudremukh 3. Dampa 4. Papikonda. How many of them lie in the Western Ghats?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Eravikulam (Kerala) and Kudremukh (Karnataka) are in the Western Ghats; Dampa is in Mizoram and Papikonda in the Eastern Ghats of Andhra Pradesh.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित संरक्षित क्षेत्रों पर विचार कीजिए: 1. इराविकुलम 2. कुद्रेमुख 3. दम्पा 4. पापीकोंडा। उनमें से कितने पश्चिमी घाट में स्थित हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"इराविकुलम (केरल) और कुद्रेमुख (कर्नाटक) पश्चिमी घाट में हैं; दम्पा मिज़ोरम में और पापीकोंडा आंध्र प्रदेश के पूर्वी घाट में है।"},
  {"id":"env-ecology-408","question":"Consider the following pairs of pollutant and control technology: 1. Sulphur dioxide — flue-gas desulphurisation 2. Particulate matter — electrostatic precipitator 3. Nitrogen oxides — selective catalytic reduction 4. Carbon monoxide — electrostatic precipitator. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"An ESP captures charged particles and cannot remove a gas like CO, which is controlled by better combustion and oxidation catalysts.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रदूषक और नियंत्रण प्रौद्योगिकी की निम्नलिखित जोड़ियों पर विचार कीजिए: 1. सल्फर डाइऑक्साइड — ग्रिप-गैस विसल्फरीकरण 2. कणिकीय पदार्थ — स्थिर-वैद्युत अवक्षेपित्र 3. नाइट्रोजन ऑक्साइड — चयनात्मक उत्प्रेरकीय अपचयन 4. कार्बन मोनोऑक्साइड — स्थिर-वैद्युत अवक्षेपित्र। उपर्युक्त में से कितनी जोड़ियाँ सही सुमेलित हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"ESP आवेशित कणों को पकड़ता है और CO जैसी गैस को नहीं हटा सकता, जिसे बेहतर दहन और ऑक्सीकरण उत्प्रेरकों से नियंत्रित किया जाता है।"},
  {"id":"env-ecology-409","question":"Consider the following gases: 1. Methane 2. Sulphur hexafluoride 3. CFC-11 4. Water vapour. How many of them are in the basket of greenhouse gases covered by the Kyoto Protocol?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"The Kyoto basket covers CO2, methane, nitrous oxide, HFCs, PFCs and SF6 (with NF3 added later); CFCs are left to the Montreal Protocol, and water vapour is not regulated.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित गैसों पर विचार कीजिए: 1. मीथेन 2. सल्फर हेक्साफ्लोराइड 3. CFC-11 4. जलवाष्प। उनमें से कितनी क्योटो प्रोटोकॉल द्वारा शामिल हरितगृह गैसों की टोकरी में हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"क्योटो की टोकरी में CO2, मीथेन, नाइट्रस ऑक्साइड, HFCs, PFCs और SF6 शामिल हैं (NF3 बाद में जोड़ी गई); CFCs मॉन्ट्रियल प्रोटोकॉल पर छोड़े गए हैं, और जलवाष्प विनियमित नहीं है।"},
  {"id":"env-ecology-410","question":"Consider the following statements about Project Tiger: 1. It was launched in 1973. 2. It began with nine tiger reserves. 3. Corbett was among the first tiger reserves. How many of the statements given above are correct?","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"Project Tiger started on 1 April 1973 with nine reserves, including Corbett, Kanha, Manas, Palamau, Ranthambore, Similipal, Bandipur, Melghat and Sundarbans.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रोजेक्ट टाइगर के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसे 1973 में शुरू किया गया था। 2. यह नौ बाघ अभयारण्यों के साथ शुरू हुआ। 3. कॉर्बेट पहले बाघ अभयारण्यों में से था। उपर्युक्त कथनों में से कितने सही हैं?","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"प्रोजेक्ट टाइगर 1 अप्रैल 1973 को नौ अभयारण्यों के साथ शुरू हुआ, जिनमें कॉर्बेट, कान्हा, मानस, पलामू, रणथंभौर, सिमलीपाल, बांदीपुर, मेलघाट और सुंदरबन शामिल थे।"},
  {"id":"env-ecology-411","question":"Match the biosphere reserve with its state(s). A. Nokrek  B. Dibru-Saikhowa  C. Achanakmar-Amarkantak  D. Agasthyamala; 1. Assam  2. Kerala and Tamil Nadu  3. Meghalaya  4. Madhya Pradesh and Chhattisgarh","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2"],"answer":3,"explanation":"Nokrek is in the Garo Hills of Meghalaya, Dibru-Saikhowa in upper Assam, Achanakmar-Amarkantak spans MP and Chhattisgarh, and Agasthyamala lies at the southern tip of the Western Ghats.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैवमंडल आरक्षित क्षेत्र का उसके राज्य/राज्यों से मिलान कीजिए। A. नोकरेक  B. डिब्रू-सैखोवा  C. अचानकमार-अमरकंटक  D. अगस्त्यमलई; 1. असम  2. केरल और तमिलनाडु  3. मेघालय  4. मध्य प्रदेश और छत्तीसगढ़","optionsHi":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2"],"explanationHi":"नोकरेक मेघालय की गारो पहाड़ियों में, डिब्रू-सैखोवा ऊपरी असम में है, अचानकमार-अमरकंटक मध्य प्रदेश और छत्तीसगढ़ में फैला है, और अगस्त्यमलई पश्चिमी घाट के दक्षिणी छोर पर स्थित है।"},
  {"id":"env-ecology-412","question":"Match the person with the field of work for which they are best known. A. Salim Ali  B. M. S. Swaminathan  C. Sunderlal Bahuguna  D. Madhav Gadgil; 1. Chipko movement  2. Ornithology  3. Western Ghats Ecology Expert Panel  4. Green Revolution in India","options":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3"],"answer":1,"explanation":"Salim Ali was the 'Birdman of India', Swaminathan led the Green Revolution in wheat and rice, Bahuguna was a Chipko leader, and Gadgil chaired the 2011 Western Ghats panel.","difficulty":"hard","source":"UPSC Prelims","questionHi":"व्यक्ति का उस कार्य-क्षेत्र से मिलान कीजिए जिसके लिए वे सबसे अधिक जाने जाते हैं। A. सालिम अली  B. एम. एस. स्वामीनाथन  C. सुंदरलाल बहुगुणा  D. माधव गाडगिल; 1. चिपको आंदोलन  2. पक्षी विज्ञान  3. पश्चिमी घाट पारिस्थितिकी विशेषज्ञ पैनल  4. भारत में हरित क्रांति","optionsHi":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3"],"explanationHi":"सालिम अली 'भारत के पक्षी पुरुष' थे, स्वामीनाथन ने गेहूँ और धान में हरित क्रांति का नेतृत्व किया, बहुगुणा चिपको के नेता थे, और गाडगिल ने 2011 के पश्चिमी घाट पैनल की अध्यक्षता की।"},
  {"id":"env-ecology-413","question":"Consider the following refrigerants: 1. Ammonia 2. Carbon dioxide 3. Propane 4. HFC-134a. How many of them are 'natural' refrigerants with zero ozone-depleting potential and very low global warming potential?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Ammonia, CO2 and hydrocarbons such as propane are natural refrigerants; HFC-134a does not harm ozone but has a GWP of over a thousand.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित रेफ्रिजरेंटों पर विचार कीजिए: 1. अमोनिया 2. कार्बन डाइऑक्साइड 3. प्रोपेन 4. HFC-134a। उनमें से कितने शून्य ओज़ोन-क्षयकारी क्षमता और बहुत कम वैश्विक तापन क्षमता वाले 'प्राकृतिक' रेफ्रिजरेंट हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"अमोनिया, CO2 और प्रोपेन जैसे हाइड्रोकार्बन प्राकृतिक रेफ्रिजरेंट हैं; HFC-134a ओज़ोन को हानि नहीं पहुँचाता पर उसकी GWP एक हज़ार से अधिक है।"},
  {"id":"env-ecology-414","question":"Consider the following gases: 1. Ozone 2. Nitrogen 3. Argon 4. Water vapour. How many of them are greenhouse gases?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Ozone and water vapour absorb infrared; nitrogen (a symmetric two-atom molecule) and argon (a single atom) do not.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित गैसों पर विचार कीजिए: 1. ओज़ोन 2. नाइट्रोजन 3. ऑर्गन 4. जलवाष्प। उनमें से कितनी हरितगृह गैसें हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"ओज़ोन और जलवाष्प अवरक्त को अवशोषित करती हैं; नाइट्रोजन (एक सममित द्विपरमाणुक अणु) और ऑर्गन (एकल परमाणु) नहीं करतीं।"},
  {"id":"env-ecology-415","question":"Which of the following pairs are correctly matched? 1. Bhitarkanika — estuarine (saltwater) crocodiles 2. Gahirmatha — mass nesting of olive ridley turtles 3. Rushikulya — Irrawaddy dolphins. Select the correct answer.","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Rushikulya, like Gahirmatha, is an olive ridley mass-nesting beach in Odisha; Irrawaddy dolphins are associated with Chilika Lake.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी जोड़ियाँ सही सुमेलित हैं? 1. भितरकनिका — खारे पानी (मुहाना) के मगरमच्छ 2. गहिरमाथा — ऑलिव रिडले कछुओं का सामूहिक नीड़न 3. ऋषिकुल्या — इरावदी डॉल्फिन। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"ऋषिकुल्या, गहिरमाथा की तरह, ओडिशा में ऑलिव रिडले के सामूहिक नीड़न का तट है; इरावदी डॉल्फिन चिल्का झील से जुड़ी हैं।"},
  {"id":"env-ecology-416","question":"The greater one-horned rhinoceros is found in which of the following protected areas? 1. Pobitora 2. Jaldapara 3. Dudhwa 4. Bandipur. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Rhinos live in Kaziranga, Pobitora and Orang (Assam), Jaldapara and Gorumara (West Bengal), and Dudhwa (reintroduced); Bandipur in Karnataka has none.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बड़ा एक सींग वाला गैंडा निम्नलिखित में से किन संरक्षित क्षेत्रों में पाया जाता है? 1. पोबितोरा 2. जलदापारा 3. दुधवा 4. बांदीपुर। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"गैंडे काजीरंगा, पोबितोरा और ओरंग (असम), जलदापारा और गोरुमारा (पश्चिम बंगाल), तथा दुधवा (पुनःप्रवेशित) में रहते हैं; कर्नाटक के बांदीपुर में कोई नहीं है।"},
  {"id":"env-ecology-417","question":"Consider the following statements about hornbills: 1. They are important seed dispersers of large-fruited forest trees. 2. During nesting, the female great hornbill seals herself inside a tree cavity and is fed by the male through a narrow slit. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Hornbills swallow large fruits and spread the seeds widely; their dependence on big old trees for nest cavities makes them sensitive to logging.","difficulty":"hard","source":"UPSC Prelims","questionHi":"धनेश (हॉर्नबिल) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वे बड़े फल वाले वन वृक्षों के महत्वपूर्ण बीज-प्रकीर्णक हैं। 2. नीड़न के दौरान, मादा ग्रेट हॉर्नबिल स्वयं को वृक्ष की कोटर में बंद कर लेती है और नर उसे एक संकरी दरार से भोजन खिलाता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["1 और 2 दोनों","केवल 1","केवल 2","न तो 1 और न ही 2"],"explanationHi":"धनेश बड़े फलों को निगलकर बीजों को दूर-दूर तक फैलाते हैं; नीड़ की कोटरों के लिए बड़े पुराने वृक्षों पर उनकी निर्भरता उन्हें कटाई के प्रति संवेदनशील बनाती है।"},
  {"id":"env-ecology-418","question":"The Doyang reservoir area in Nagaland is known for:","options":["India's largest breeding colony of greater flamingos","Wintering grounds of the black-necked crane from Tibet","The only wild population of the white-winged duck","Autumn roosts of migrating Amur falcons, now protected"],"answer":3,"explanation":"Amur falcons stop in Nagaland on their migration from East Asia to southern Africa; communities such as Pangti turned from hunting them to protecting them.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नागालैंड का डोयांग जलाशय क्षेत्र किसके लिए जाना जाता है?","optionsHi":["ग्रेटर फ्लेमिंगो की भारत की सबसे बड़ी प्रजनन कॉलोनी","तिब्बत से आने वाले काली गर्दन वाले सारसों के शीतकालीन प्रवास स्थल","श्वेत-पंख बत्तख की एकमात्र जंगली आबादी","प्रवासी अमूर बाज़ों के शरदकालीन बसेरे, जो अब संरक्षित हैं"],"explanationHi":"अमूर बाज़ पूर्वी एशिया से दक्षिणी अफ्रीका की अपनी प्रवास यात्रा में नागालैंड में पड़ाव डालते हैं; पांगती जैसे समुदाय उनके शिकार से उनके संरक्षण की ओर मुड़ गए।"},
  {"id":"env-ecology-419","question":"Most of India lies within which of the world's major bird migration flyways?","options":["East Atlantic Flyway","Central Asian Flyway","Americas Flyway","Black Sea–Mediterranean Flyway"],"answer":1,"explanation":"The Central Asian Flyway links breeding grounds in Siberia and Central Asia to wintering areas in India; parts of the north-east also fall within the East Asian–Australasian Flyway.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत का अधिकांश भाग विश्व के प्रमुख पक्षी प्रवास मार्गों में से किसके अंतर्गत आता है?","optionsHi":["पूर्वी अटलांटिक प्रवास मार्ग","मध्य एशियाई प्रवास मार्ग","अमेरिका प्रवास मार्ग","काला सागर–भूमध्यसागरीय प्रवास मार्ग"],"explanationHi":"मध्य एशियाई प्रवास मार्ग साइबेरिया और मध्य एशिया के प्रजनन क्षेत्रों को भारत के शीतकालीन क्षेत्रों से जोड़ता है; उत्तर-पूर्व के कुछ भाग पूर्वी एशियाई–ऑस्ट्रेलेशियाई प्रवास मार्ग में भी आते हैं।"},
  {"id":"env-ecology-420","question":"Neonicotinoid pesticides have drawn concern from conservationists mainly because:","options":["They are fungicides that wipe out the beneficial soil bacteria too","They break down into ozone-depleting gases in sunlight","They are systemic, reaching pollen and nectar and harming bees","They sharply raise the acidity of farm soils"],"answer":2,"explanation":"Being systemic, they reach pollen and nectar, and even low doses can impair bees' foraging and navigation; several have been restricted in Europe.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नियोनिकोटिनॉइड कीटनाशक संरक्षणवादियों की चिंता का विषय मुख्यतः इसलिए बने हैं क्योंकि:","optionsHi":["वे कवकनाशी हैं जो लाभकारी मृदा जीवाणुओं को भी नष्ट कर देते हैं","वे धूप में ओज़ोन-क्षयकारी गैसों में विघटित हो जाते हैं","वे सर्वांगी (सिस्टमिक) हैं, पराग और मकरंद तक पहुँचते हैं और मधुमक्खियों को हानि पहुँचाते हैं","वे खेती की मिट्टी की अम्लता को तीव्रता से बढ़ा देते हैं"],"explanationHi":"सर्वांगी होने के कारण वे पराग और मकरंद तक पहुँचते हैं, और कम मात्रा भी मधुमक्खियों के भोजन खोजने और दिशा-ज्ञान को बाधित कर सकती है; यूरोप में कई पर प्रतिबंध लगे हैं।"},
  {"id":"env-ecology-421","question":"Consider the following statements about glacial lake outburst floods (GLOFs): 1. They occur when a moraine or ice dam holding back a glacial lake fails. 2. Warming that shrinks glaciers can increase the number and size of glacial lakes. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Meltwater collects behind loose moraine; a landslide, avalanche or erosion can breach it, releasing a sudden flood downstream, as in Sikkim in 2023.","difficulty":"hard","source":"UPSC Prelims","questionHi":"हिमनद झील विस्फोट बाढ़ (GLOF) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. ये तब होती हैं जब हिमनद झील को रोकने वाला हिमोढ़ या बर्फ़ का बाँध टूट जाता है। 2. हिमनदों को सिकोड़ने वाला तापन हिमनद झीलों की संख्या और आकार बढ़ा सकता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"पिघला जल ढीले हिमोढ़ के पीछे एकत्र होता है; भूस्खलन, हिमस्खलन या अपरदन उसे तोड़ सकता है, जिससे नीचे की ओर अचानक बाढ़ आती है, जैसे 2023 में सिक्किम में।"},
  {"id":"env-ecology-422","question":"High humidity makes a heat wave more dangerous to human health mainly because:","options":["Sweat cannot evaporate, so the body's main cooling fails","Humid air contains much less oxygen for breathing","Humidity amplifies the ultraviolet radiation at ground level","Moist air conducts heat away from the body too fast"],"answer":0,"explanation":"Evaporation of sweat removes body heat; as the wet-bulb temperature rises, this cooling fails, which is why heat-index and wet-bulb measures are used for warnings.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"उच्च आर्द्रता लू को मानव स्वास्थ्य के लिए मुख्यतः अधिक खतरनाक क्यों बनाती है?","optionsHi":["पसीना वाष्पित नहीं हो पाता, इसलिए शरीर का मुख्य शीतलन तंत्र विफल हो जाता है","आर्द्र वायु में साँस लेने के लिए ऑक्सीजन बहुत कम होती है","आर्द्रता धरातल पर पराबैंगनी विकिरण को बढ़ा देती है","नम वायु शरीर से ऊष्मा को बहुत तेज़ी से बाहर ले जाती है"],"explanationHi":"पसीने का वाष्पीकरण शरीर की ऊष्मा हटाता है; जैसे-जैसे आर्द्र-बल्ब तापमान बढ़ता है, यह शीतलन विफल हो जाता है, इसीलिए चेतावनियों के लिए ऊष्मा-सूचकांक और आर्द्र-बल्ब मापों का उपयोग होता है।"},
  {"id":"env-ecology-423","question":"GRIHA, often mentioned in the context of sustainable buildings, is:","options":["A scheme for rural housing loans to poor families","A pollution-monitoring network for Indian cities","An international treaty on building materials","India's national green-building rating system"],"answer":3,"explanation":"GRIHA (Green Rating for Integrated Habitat Assessment) was developed by TERI with the Ministry of New and Renewable Energy to rate buildings on energy, water and materials.","difficulty":"hard","source":"UPSC Prelims","questionHi":"GRIHA, जिसका उल्लेख प्रायः सतत भवनों के संदर्भ में होता है, क्या है?","optionsHi":["गरीब परिवारों के लिए ग्रामीण आवास ऋण की योजना","भारतीय शहरों का प्रदूषण-निगरानी नेटवर्क","भवन सामग्री पर एक अंतरराष्ट्रीय संधि","भारत की राष्ट्रीय हरित-भवन रेटिंग प्रणाली"],"explanationHi":"GRIHA (समेकित आवास आकलन के लिए हरित रेटिंग) को TERI ने नवीन और नवीकरणीय ऊर्जा मंत्रालय के साथ मिलकर विकसित किया ताकि भवनों को ऊर्जा, जल और सामग्री के आधार पर रेट किया जा सके।"},
  {"id":"env-ecology-424","question":"In a cap-and-trade system for controlling emissions:","options":["A fixed price per tonne is set, and firms emit as much as they pay for","Each firm must cut emissions by the same percentage, with no trading","Emissions are banned entirely in the capped sectors","A total cap is set and firms trade allowances, so price floats"],"answer":3,"explanation":"Cap-and-trade fixes the quantity and lets the price vary; a carbon tax does the reverse, fixing the price and letting the quantity vary.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उत्सर्जन नियंत्रण की कैप-एंड-ट्रेड प्रणाली में:","optionsHi":["प्रति टन एक निश्चित मूल्य तय किया जाता है, और फर्में उतना ही उत्सर्जन करती हैं जितने का वे भुगतान करें","प्रत्येक फर्म को उत्सर्जन में समान प्रतिशत की कटौती करनी होती है, व्यापार नहीं होता","सीमित क्षेत्रों में उत्सर्जन पूरी तरह प्रतिबंधित होता है","कुल सीमा तय की जाती है और फर्में भत्तों का व्यापार करती हैं, इसलिए मूल्य घटता-बढ़ता है"],"explanationHi":"कैप-एंड-ट्रेड मात्रा तय करता है और मूल्य को बदलने देता है; कार्बन कर इसके विपरीत मूल्य तय करता है और मात्रा को बदलने देता है।"},
  {"id":"env-ecology-425","question":"Under India's Perform, Achieve and Trade (PAT) scheme for energy-intensive industries, units that beat their targets receive tradable:","options":["Renewable energy certificates","Certified emission reductions","Energy saving certificates","Green credits"],"answer":2,"explanation":"PAT, run by the Bureau of Energy Efficiency under the Energy Conservation Act, 2001, issues ESCerts to over-achievers, which under-achievers can buy.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ऊर्जा-सघन उद्योगों के लिए भारत की प्रदर्शन, उपलब्धि और व्यापार (PAT) योजना के अंतर्गत, लक्ष्य से बेहतर प्रदर्शन करने वाली इकाइयों को किस व्यापार-योग्य प्रमाणपत्र की प्राप्ति होती है?","optionsHi":["नवीकरणीय ऊर्जा प्रमाणपत्र","प्रमाणित उत्सर्जन कटौतियाँ","ऊर्जा बचत प्रमाणपत्र","हरित क्रेडिट"],"explanationHi":"ऊर्जा संरक्षण अधिनियम, 2001 के अंतर्गत ऊर्जा दक्षता ब्यूरो द्वारा संचालित PAT, अधिक उपलब्धि वालों को ESCerts जारी करता है, जिन्हें कम उपलब्धि वाले खरीद सकते हैं।"},
  {"id":"env-ecology-426","question":"Consider the following statements: 1. The Bureau of Energy Efficiency was set up under the Energy Conservation Act, 2001. 2. Star labelling is mandatory for every electrical appliance sold in India. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The BEE runs the star-labelling programme, but labelling is mandatory only for notified appliances (such as air conditioners and refrigerators) and voluntary for others.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. ऊर्जा दक्षता ब्यूरो की स्थापना ऊर्जा संरक्षण अधिनियम, 2001 के अंतर्गत हुई। 2. भारत में बिकने वाले प्रत्येक विद्युत उपकरण पर स्टार लेबलिंग अनिवार्य है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"BEE स्टार लेबलिंग कार्यक्रम चलाता है, परंतु लेबलिंग केवल अधिसूचित उपकरणों (जैसे एयर कंडीशनर और रेफ्रिजरेटर) के लिए अनिवार्य है और अन्य के लिए स्वैच्छिक।"},
  {"id":"env-ecology-427","question":"Consider the following statements: 1. Solar photovoltaic cells convert light directly into electricity. 2. Concentrated solar power plants use mirrors to focus sunlight and heat a fluid that drives a turbine. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"PV relies on the photovoltaic effect in semiconductors, while CSP is a thermal route; CSP can store heat to generate power after sunset.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. सौर प्रकाश-वोल्टीय सेल प्रकाश को सीधे बिजली में बदलते हैं। 2. संकेंद्रित सौर ऊर्जा संयंत्र दर्पणों से सूर्य के प्रकाश को केंद्रित कर एक तरल को गर्म करते हैं जो टरबाइन चलाता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"PV अर्धचालकों में प्रकाश-वोल्टीय प्रभाव पर निर्भर है, जबकि CSP तापीय मार्ग है; CSP ऊष्मा संचित कर सूर्यास्त के बाद भी बिजली उत्पन्न कर सकता है।"},
  {"id":"env-ecology-428","question":"Consider the following statements about large dams: 1. Reservoirs in the tropics can emit significant amounts of methane as flooded vegetation decays. 2. Dams trap sediment, which can lead to erosion and shrinking of deltas downstream. Which of the statements given above is/are correct?","options":["1 only","Both 1 and 2","2 only","Neither 1 nor 2"],"answer":1,"explanation":"Hydropower is not always low-carbon: anaerobic decay in warm reservoirs releases methane, and sediment-starved deltas sink and erode.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बड़े बाँधों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. उष्णकटिबंध में जलाशय डूबी हुई वनस्पति के अपघटन से महत्वपूर्ण मात्रा में मीथेन उत्सर्जित कर सकते हैं। 2. बाँध अवसाद को रोक लेते हैं, जिससे नीचे की ओर डेल्टाओं का अपरदन और सिकुड़न हो सकती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","1 और 2 दोनों","केवल 2","न तो 1 और न ही 2"],"explanationHi":"जलविद्युत सदा कम-कार्बन नहीं होती: गर्म जलाशयों में अवायवीय अपघटन मीथेन छोड़ता है, और अवसाद-रहित डेल्टा धँसते और कटते हैं।"},
  {"id":"env-ecology-429","question":"The presence of faecal coliform bacteria such as E. coli in drinking water indicates that:","options":["The water has a high fluoride content","The water is hard because of calcium salts","The water has been treated with too much chlorine","The water is contaminated with faecal matter"],"answer":3,"explanation":"Coliforms themselves are mostly harmless, but they signal faecal contamination and hence the possible presence of disease-causing organisms.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"पेयजल में ई. कोलाई जैसे मल कॉलिफ़ॉर्म जीवाणुओं की उपस्थिति क्या दर्शाती है?","optionsHi":["जल में फ्लोराइड की मात्रा अधिक है","जल कैल्शियम लवणों के कारण कठोर है","जल का अत्यधिक क्लोरीन से उपचार किया गया है","जल मल पदार्थ से दूषित है"],"explanationHi":"कॉलिफ़ॉर्म स्वयं अधिकतर हानिरहित होते हैं, परंतु वे मल संदूषण और इसलिए रोगजनक जीवों की संभावित उपस्थिति का संकेत देते हैं।"},
  {"id":"env-ecology-430","question":"Which of the following is characteristic of an oligotrophic lake?","options":["Murky green water with frequent summer algal blooms","Shallow water with thick bottom sediments rich in organic matter","Very low oxygen in the deep water throughout summer","Clear, nutrient-poor water that stays oxygenated even at depth"],"answer":3,"explanation":"Oligotrophic lakes are nutrient-poor, so little algae grows and little organic matter decays at the bottom; the other options describe eutrophic lakes.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा अल्पपोषी (ऑलिगोट्रोफिक) झील का विशिष्ट लक्षण है?","optionsHi":["गँदला हरा जल जिसमें ग्रीष्म में बार-बार शैवाल प्रस्फुटन होता है","कार्बनिक पदार्थ से समृद्ध मोटे तलछट वाला उथला जल","पूरी ग्रीष्म ऋतु में गहरे जल में बहुत कम ऑक्सीजन","साफ़, पोषक-निर्धन जल जो गहराई पर भी ऑक्सीजनयुक्त रहता है"],"explanationHi":"अल्पपोषी झीलें पोषक-निर्धन होती हैं, इसलिए शैवाल कम उगते हैं और तल पर कम कार्बनिक पदार्थ अपघटित होता है; शेष विकल्प सुपोषित (यूट्रोफिक) झीलों का वर्णन करते हैं।"},
  {"id":"env-ecology-431","question":"The relationship between fig trees and fig wasps is best described as:","options":["Obligate mutualism: each fig has its own pollinating wasp","Parasitism, in which the wasp gains and the fig is harmed","Commensalism, in which only the wasp benefits","Amensalism, in which the fig is harmed and the wasp unaffected"],"answer":0,"explanation":"The wasp pollinates the fig while laying eggs in some of its flowers, and its larvae feed on some developing seeds; neither partner can reproduce without the other, so the seed loss does not make it parasitism.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अंजीर के वृक्षों और अंजीर ततैयों के बीच संबंध का सबसे उपयुक्त वर्णन है:","optionsHi":["बाध्यकारी सहोपकारिता: प्रत्येक अंजीर की अपनी परागण करने वाली ततैया होती है","परजीविता, जिसमें ततैया को लाभ होता है और अंजीर को हानि","सहभोजिता, जिसमें केवल ततैया को लाभ होता है","अमेन्सलिज़्म, जिसमें अंजीर को हानि होती है और ततैया अप्रभावित रहती है"],"explanationHi":"ततैया अंजीर के कुछ फूलों में अंडे देते हुए उसका परागण करती है, और उसके लार्वा कुछ विकसित हो रहे बीजों को खाते हैं; कोई भी साथी दूसरे के बिना प्रजनन नहीं कर सकता, इसलिए बीजों की हानि इसे परजीविता नहीं बनाती।"},
  {"id":"env-ecology-432","question":"Among animals, the group with the largest number of described species is:","options":["Insects","Fishes","Molluscs","Birds"],"answer":0,"explanation":"Insects account for well over half of all described animal species; fishes and birds are far fewer.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"जंतुओं में वर्णित प्रजातियों की सबसे अधिक संख्या वाला समूह कौन-सा है?","optionsHi":["कीट","मछलियाँ","मोलस्क","पक्षी"],"explanationHi":"वर्णित जंतु प्रजातियों के आधे से कहीं अधिक कीट हैं; मछलियाँ और पक्षी बहुत कम हैं।"},
  {"id":"env-ecology-433","question":"Robert May's widely quoted estimate of the total number of species on Earth, including those not yet described, is about:","options":["1.5 million","20 million","100 million","7 million"],"answer":3,"explanation":"About 1.5 million species have been described; May extrapolated from the ratio of tropical to temperate species to estimate roughly 7 million.","difficulty":"hard","source":"UPSC Prelims","questionHi":"रॉबर्ट मे का पृथ्वी पर कुल प्रजातियों की संख्या का, जिसमें अभी वर्णित न की गई प्रजातियाँ भी शामिल हैं, व्यापक रूप से उद्धृत अनुमान लगभग कितना है?","optionsHi":["1.5 मिलियन","20 मिलियन","100 मिलियन","7 मिलियन"],"explanationHi":"लगभग 1.5 मिलियन प्रजातियाँ वर्णित की जा चुकी हैं; मे ने उष्णकटिबंधीय और शीतोष्ण प्रजातियों के अनुपात से अनुमान लगाकर लगभग 7 मिलियन का आकलन किया।"},
  {"id":"env-ecology-434","question":"Biodiversity Heritage Sites in India are notified by:","options":["State Governments under the Biological Diversity Act, 2002","The Central Government under the Wildlife (Protection) Act, 1972","UNESCO on the recommendation of India","The National Green Tribunal"],"answer":0,"explanation":"Section 37 of the Biological Diversity Act lets state governments notify areas of biodiversity importance as heritage sites, in consultation with local bodies.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत में जैव विविधता धरोहर स्थल किसके द्वारा अधिसूचित किए जाते हैं?","optionsHi":["जैविक विविधता अधिनियम, 2002 के अंतर्गत राज्य सरकारें","वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत केंद्र सरकार","भारत की अनुशंसा पर यूनेस्को","राष्ट्रीय हरित अधिकरण"],"explanationHi":"जैविक विविधता अधिनियम की धारा 37 राज्य सरकारों को स्थानीय निकायों से परामर्श कर जैव विविधता महत्व के क्षेत्रों को धरोहर स्थल के रूप में अधिसूचित करने देती है।"},
  {"id":"env-ecology-435","question":"HCFCs were adopted as transitional substitutes for CFCs mainly because:","options":["They contain no chlorine at all, only fluorine","They are not greenhouse gases and do not warm the climate","Their C–H bonds let most break down in the troposphere","They react with ozone to regenerate more of it"],"answer":2,"explanation":"HCFCs still carry chlorine and have some ozone-depleting potential, which is why they too are being phased out under the Montreal Protocol.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"HCFCs को CFCs के संक्रमणकालीन विकल्प के रूप में मुख्यतः क्यों अपनाया गया?","optionsHi":["उनमें क्लोरीन बिल्कुल नहीं होती, केवल फ्लोरीन होती है","वे हरितगृह गैसें नहीं हैं और जलवायु को गर्म नहीं करतीं","उनके C–H बंध अधिकांश को क्षोभमंडल में टूटने देते हैं","वे ओज़ोन से अभिक्रिया करके उसे और अधिक पुनः उत्पन्न करते हैं"],"explanationHi":"HCFCs में अभी भी क्लोरीन होती है और कुछ ओज़ोन-क्षयकारी क्षमता होती है, इसीलिए उन्हें भी मॉन्ट्रियल प्रोटोकॉल के अंतर्गत चरणबद्ध ढंग से हटाया जा रहा है।"},
  {"id":"env-ecology-436","question":"A caterpillar eats leaves containing 1,000 J of energy. It passes 600 J out as faeces and uses 300 J in respiration; the rest goes into new tissue. What is its net production efficiency (new tissue as a share of the energy assimilated)?","options":["10%","25%","40%","33%"],"answer":1,"explanation":"Assimilated = 1,000 − 600 = 400 J; production = 400 − 300 = 100 J; 100/400 = 25%. 10% divides by the energy eaten, 40% is the assimilation efficiency, and 33% divides production by respiration.","difficulty":"very-hard","source":"UPSC Prelims · CDS","questionHi":"एक इल्ली 1,000 J ऊर्जा वाली पत्तियाँ खाती है। वह 600 J मल के रूप में बाहर निकालती है और 300 J श्वसन में उपयोग करती है; शेष नए ऊतक में जाती है। उसकी शुद्ध उत्पादन दक्षता (आत्मसात ऊर्जा के हिस्से के रूप में नए ऊतक) क्या है?","optionsHi":["10%","25%","40%","33%"],"explanationHi":"आत्मसात = 1,000 − 600 = 400 J; उत्पादन = 400 − 300 = 100 J; 100/400 = 25%। 10% खाई गई ऊर्जा से भाग देने पर, 40% आत्मसातीकरण दक्षता है, और 33% उत्पादन को श्वसन से भाग देने पर आता है।"},
  {"id":"env-ecology-437","question":"To estimate the number of fish in a pond, 40 fish are caught, tagged and released. A week later, 50 fish are caught, of which 10 carry tags. Using the mark–recapture method, the estimated population is:","options":["100","400","200","2,000"],"answer":2,"explanation":"N = (marked first time × total caught second time) ÷ marked recaptured = 40 × 50 ÷ 10 = 200. Multiplying the two catches without dividing gives the 2,000 trap.","difficulty":"very-hard","source":"UPSC Prelims · CDS","questionHi":"किसी तालाब में मछलियों की संख्या का अनुमान लगाने के लिए 40 मछलियाँ पकड़ी, चिह्नित की और छोड़ी जाती हैं। एक सप्ताह बाद 50 मछलियाँ पकड़ी जाती हैं, जिनमें से 10 पर चिह्न हैं। चिह्न–पुनः पकड़ विधि से अनुमानित आबादी है:","optionsHi":["100","400","200","2,000"],"explanationHi":"N = (पहली बार चिह्नित × दूसरी बार पकड़ी गई कुल) ÷ पुनः पकड़ी गई चिह्नित = 40 × 50 ÷ 10 = 200। दोनों पकड़ों को भाग दिए बिना गुणा करने पर 2,000 का जाल मिलता है।"},
  {"id":"env-ecology-438","question":"A population grows steadily at 2 per cent a year. Roughly how long will it take to double?","options":["20 years","50 years","70 years","35 years"],"answer":3,"explanation":"By the rule of 70, doubling time ≈ 70 ÷ 2 = 35 years (ln 2 ÷ ln 1.02 ≈ 35); 50 years is what simple, non-compounding growth would give.","difficulty":"moderate","source":"UPSC Prelims · CDS","questionHi":"कोई आबादी प्रति वर्ष 2 प्रतिशत की स्थिर दर से बढ़ती है। उसे दोगुना होने में लगभग कितना समय लगेगा?","optionsHi":["20 वर्ष","50 वर्ष","70 वर्ष","35 वर्ष"],"explanationHi":"70 के नियम से, दोगुना होने का समय ≈ 70 ÷ 2 = 35 वर्ष (ln 2 ÷ ln 1.02 ≈ 35); 50 वर्ष वह है जो सरल, चक्रवृद्धि-रहित वृद्धि देती।"},
  {"id":"env-ecology-439","question":"Consider the following statements: 1. In an ecosystem, both energy and nutrients flow in one direction only. 2. Gross primary productivity is the rate at which organic matter is produced in photosynthesis. 3. A considerable part of gross primary productivity is used by plants in their own respiration. Which of the statements given above are correct?","options":["2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Energy flows one way, but nutrients are recycled between living and non-living parts of the ecosystem; GPP minus plant respiration gives NPP.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. किसी पारिस्थितिकी तंत्र में ऊर्जा और पोषक तत्व दोनों केवल एक दिशा में प्रवाहित होते हैं। 2. सकल प्राथमिक उत्पादकता वह दर है जिस पर प्रकाश-संश्लेषण में कार्बनिक पदार्थ बनता है। 3. सकल प्राथमिक उत्पादकता का एक बड़ा भाग पौधे अपने ही श्वसन में उपयोग करते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"ऊर्जा एक ही दिशा में प्रवाहित होती है, परंतु पोषक तत्व पारिस्थितिकी तंत्र के जीवित और निर्जीव भागों के बीच पुनर्चक्रित होते हैं; GPP में से पौधों का श्वसन घटाने पर NPP मिलती है।"},
  {"id":"env-ecology-440","question":"Consider the following statements comparing the phosphorus and carbon cycles: 1. Atmospheric inputs of phosphorus through rain are much smaller than those of carbon. 2. Gaseous exchange of phosphorus between organisms and the environment is negligible. 3. The main reservoir of carbon is in the atmosphere and oceans, while that of phosphorus is in the Earth's crust. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are standard differences: phosphorus is a sedimentary cycle with no meaningful gas phase, whereas carbon cycles largely through the air and water.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"फॉस्फोरस और कार्बन चक्रों की तुलना के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वर्षा के माध्यम से फॉस्फोरस के वायुमंडलीय निवेश कार्बन के निवेश से बहुत कम हैं। 2. जीवों और पर्यावरण के बीच फॉस्फोरस का गैसीय आदान-प्रदान नगण्य है। 3. कार्बन का मुख्य भंडार वायुमंडल और महासागरों में है, जबकि फॉस्फोरस का पृथ्वी की भू-पर्पटी में। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"तीनों मानक अंतर हैं: फॉस्फोरस एक अवसादी चक्र है जिसकी कोई सार्थक गैसीय प्रावस्था नहीं है, जबकि कार्बन मुख्यतः वायु और जल से होकर चक्रित होता है।"},
  {"id":"env-ecology-441","question":"The ozone hole is far deeper over Antarctica than over the Arctic. The main reason is that:","options":["CFC emissions are much higher in the Southern Hemisphere","There is more sunlight over Antarctica during the winter","Its colder, stabler vortex forms more polar stratospheric clouds","Antarctic ice sheets release chlorine directly into the stratosphere"],"answer":2,"explanation":"Most CFCs were emitted in the north, but a stable, very cold vortex over Antarctica produces the clouds on which chlorine is activated, ready to destroy ozone when spring sunlight returns.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ओज़ोन छिद्र आर्कटिक की तुलना में अंटार्कटिका के ऊपर कहीं अधिक गहरा होता है। इसका मुख्य कारण यह है कि:","optionsHi":["दक्षिणी गोलार्ध में CFC उत्सर्जन कहीं अधिक है","शीत ऋतु में अंटार्कटिका के ऊपर अधिक सूर्य का प्रकाश रहता है","इसका अधिक ठंडा, अधिक स्थिर भँवर (वॉर्टेक्स) अधिक ध्रुवीय समतापमंडलीय बादल बनाता है","अंटार्कटिक हिम चादरें क्लोरीन को सीधे समतापमंडल में छोड़ती हैं"],"explanationHi":"अधिकांश CFCs का उत्सर्जन उत्तर में हुआ, परंतु अंटार्कटिका के ऊपर एक स्थिर, अत्यंत ठंडा भँवर वे बादल बनाता है जिन पर क्लोरीन सक्रिय होती है, और वसंत में सूर्य का प्रकाश लौटने पर ओज़ोन को नष्ट करने को तैयार रहती है।"},
  {"id":"env-ecology-442","question":"Consider the following statements about the Kigali Amendment: 1. It brought hydrofluorocarbons, which do not deplete ozone, under the Montreal Protocol. 2. Developed and developing countries follow the same timetable for phasing down HFCs. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Kigali used the Montreal Protocol's machinery to tackle HFCs as greenhouse gases, with differentiated schedules: developing countries such as India start later.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"किगाली संशोधन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसने हाइड्रोफ्लोरोकार्बनों को, जो ओज़ोन को क्षीण नहीं करते, मॉन्ट्रियल प्रोटोकॉल के अंतर्गत लाया। 2. विकसित और विकासशील देश HFCs को घटाने के लिए एक ही समय-सारणी का पालन करते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"किगाली ने HFCs से हरितगृह गैसों के रूप में निपटने के लिए मॉन्ट्रियल प्रोटोकॉल के तंत्र का उपयोग किया, विभेदित समय-सारणियों के साथ: भारत जैसे विकासशील देश बाद में शुरू करते हैं।"},
  {"id":"env-ecology-443","question":"Article 6 of the Paris Agreement deals with:","options":["Loss and damage from climate impacts","Adaptation goals and national adaptation planning by Parties","Cooperative approaches such as international carbon markets","The enhanced transparency framework for reporting"],"answer":2,"explanation":"Article 6 provides for cooperative approaches and a crediting mechanism; adaptation is Article 7, loss and damage Article 8, and transparency Article 13.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पेरिस समझौते का अनुच्छेद 6 किससे संबंधित है?","optionsHi":["जलवायु प्रभावों से हानि और क्षति","पक्षकारों द्वारा अनुकूलन लक्ष्य और राष्ट्रीय अनुकूलन योजना","अंतरराष्ट्रीय कार्बन बाज़ार जैसे सहकारी दृष्टिकोण","रिपोर्टिंग के लिए संवर्धित पारदर्शिता ढाँचा"],"explanationHi":"अनुच्छेद 6 सहकारी दृष्टिकोणों और क्रेडिटिंग तंत्र का प्रावधान करता है; अनुकूलन अनुच्छेद 7, हानि और क्षति अनुच्छेद 8, और पारदर्शिता अनुच्छेद 13 है।"},
  {"id":"env-ecology-444","question":"The Warsaw International Mechanism, set up at COP-19 of the UNFCCC in 2013, addresses:","options":["Reducing deforestation in developing countries","Loss and damage from climate change impacts","Technology transfer for renewable energy","Phasing down HFCs under a global schedule"],"answer":1,"explanation":"It deals with loss and damage, including extreme and slow-onset events in vulnerable countries; reducing deforestation is the subject of REDD+.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"2013 में UNFCCC के COP-19 में स्थापित वारसॉ अंतरराष्ट्रीय तंत्र किससे संबंधित है?","optionsHi":["विकासशील देशों में वनोन्मूलन घटाना","जलवायु परिवर्तन के प्रभावों से हानि और क्षति","नवीकरणीय ऊर्जा के लिए प्रौद्योगिकी हस्तांतरण","वैश्विक समय-सारणी के अंतर्गत HFCs को घटाना"],"explanationHi":"यह हानि और क्षति से संबंधित है, जिसमें संवेदनशील देशों में चरम और धीमी गति से आने वाली घटनाएँ शामिल हैं; वनोन्मूलन घटाना REDD+ का विषय है।"},
  {"id":"env-ecology-445","question":"The principle of 'common but differentiated responsibilities' was formally set out as a principle in:","options":["The Rio Declaration, 1992","The Stockholm Declaration, 1972","The Kyoto Protocol, 1997","The Paris Agreement, 2015"],"answer":0,"explanation":"Principle 7 of the Rio Declaration states it, and the UNFCCC adopted it the same year; Kyoto and Paris applied it in different ways.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"'साझा परंतु विभेदित उत्तरदायित्व' का सिद्धांत औपचारिक रूप से एक सिद्धांत के रूप में किसमें निर्धारित किया गया?","optionsHi":["रियो घोषणा, 1992","स्टॉकहोम घोषणा, 1972","क्योटो प्रोटोकॉल, 1997","पेरिस समझौता, 2015"],"explanationHi":"रियो घोषणा का सिद्धांत 7 इसे बताता है, और UNFCCC ने उसी वर्ष इसे अपनाया; क्योटो और पेरिस ने इसे भिन्न तरीकों से लागू किया।"},
  {"id":"env-ecology-446","question":"The 'precautionary approach', set out in Principle 15 of the Rio Declaration, holds that:","options":["Only scientifically proven damage justifies any regulation","The polluter must always pay the full cost of the clean-up","Development must stop wherever any environmental risk exists","Uncertainty is no reason to delay preventing serious harm"],"answer":3,"explanation":"It shifts the burden towards prevention under uncertainty; the polluter pays principle is a separate idea (Principle 16).","difficulty":"hard","source":"UPSC Prelims","questionHi":"रियो घोषणा के सिद्धांत 15 में निर्धारित 'पूर्व-सावधानी दृष्टिकोण' का मत है कि:","optionsHi":["केवल वैज्ञानिक रूप से सिद्ध क्षति ही किसी विनियमन को उचित ठहराती है","प्रदूषक को सदा सफ़ाई की पूरी लागत वहन करनी चाहिए","जहाँ कहीं भी कोई पर्यावरणीय जोखिम हो वहाँ विकास रुक जाना चाहिए","अनिश्चितता गंभीर क्षति को रोकने में देरी का कारण नहीं है"],"explanationHi":"यह अनिश्चितता की स्थिति में बोझ को रोकथाम की ओर ले जाता है; प्रदूषक भुगतान सिद्धांत एक अलग विचार है (सिद्धांत 16)।"},
  {"id":"env-ecology-447","question":"The Genetic Engineering Appraisal Committee, which approves genetically modified organisms for environmental release in India, functions under:","options":["The Biological Diversity Act, 2002","The Seeds Act, 1966","Rules made under the Environment (Protection) Act, 1986","The Protection of Plant Varieties and Farmers' Rights Act, 2001"],"answer":2,"explanation":"GEAC works in the Environment Ministry under the 1989 Rules for hazardous micro-organisms and genetically engineered organisms, framed under the EPA.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आनुवंशिक अभियांत्रिकी मूल्यांकन समिति, जो भारत में आनुवंशिक रूप से रूपांतरित जीवों को पर्यावरण में छोड़ने के लिए अनुमोदित करती है, किसके अंतर्गत कार्य करती है?","optionsHi":["जैविक विविधता अधिनियम, 2002","बीज अधिनियम, 1966","पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत बनाए गए नियम","पादप किस्म संरक्षण और कृषक अधिकार अधिनियम, 2001"],"explanationHi":"GEAC पर्यावरण मंत्रालय में खतरनाक सूक्ष्मजीवों और आनुवंशिक रूप से अभियांत्रित जीवों के लिए 1989 के नियमों के अंतर्गत कार्य करती है, जो EPA के अंतर्गत बनाए गए थे।"},
  {"id":"env-ecology-448","question":"Consider the following statements about Bt crops: 1. The Bt toxin is produced in the bacterium as an inactive protoxin and becomes active in the alkaline gut of the insect. 2. The bacterium Bacillus thuringiensis is killed by its own toxin. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The bacterium is unharmed because the toxin stays inactive inside it; in the insect gut it is activated, binds to gut cells and kills the larva.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"Bt फसलों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. Bt विष जीवाणु में निष्क्रिय प्रोटॉक्सिन के रूप में बनता है और कीट की क्षारीय आँत में सक्रिय हो जाता है। 2. जीवाणु बैसिलस थुरिन्जिएन्सिस अपने ही विष से मर जाता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"जीवाणु को हानि नहीं पहुँचती क्योंकि विष उसके भीतर निष्क्रिय रहता है; कीट की आँत में वह सक्रिय होता है, आँत की कोशिकाओं से जुड़ता है और लार्वा को मार देता है।"},
  {"id":"env-ecology-449","question":"Farmers growing Bt crops are advised to plant 'refuge' rows of non-Bt plants of the same crop. The purpose is to:","options":["Provide food and shelter for pollinating bees","Increase the total yield of the field through hybrid vigour","Prevent the Bt gene from spreading to nearby weeds by pollen","Maintain susceptible pests so resistance spreads more slowly"],"answer":3,"explanation":"Without refuges, only resistant pests survive and breed; failure to maintain them is one reason pink bollworm developed resistance to Bt cotton in India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"Bt फसल उगाने वाले किसानों को उसी फसल के गैर-Bt पौधों की 'शरण (रेफ्यूज)' पंक्तियाँ लगाने की सलाह दी जाती है। इसका उद्देश्य है:","optionsHi":["परागण करने वाली मधुमक्खियों को भोजन और आश्रय देना","संकर ओज द्वारा खेत की कुल उपज बढ़ाना","पराग द्वारा Bt जीन को आस-पास के खरपतवारों में फैलने से रोकना","संवेदनशील कीटों को बनाए रखना ताकि प्रतिरोध अधिक धीरे फैले"],"explanationHi":"शरण के बिना केवल प्रतिरोधी कीट जीवित रहते और प्रजनन करते हैं; इन्हें न बनाए रखना ही भारत में Bt कपास के प्रति गुलाबी सुंडी में प्रतिरोध विकसित होने का एक कारण है।"},
  {"id":"env-ecology-450","question":"A gradual, continuous change in the species composition of communities along an environmental gradient, without any sharp boundary, is called:","options":["An ecotone","An ecocline","An ecad","An ecotype"],"answer":1,"explanation":"An ecotone is a relatively narrow transition zone between two communities; an ecocline is a smooth gradient, such as vegetation changing with altitude.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"किसी पर्यावरणीय प्रवणता के साथ समुदायों के प्रजाति संघटन में बिना किसी स्पष्ट सीमा के होने वाला क्रमिक, सतत परिवर्तन क्या कहलाता है?","optionsHi":["संक्रमण क्षेत्र (इकोटोन)","इकोक्लाइन","इकैड","पारिस्थितिक प्रारूप (इकोटाइप)"],"explanationHi":"इकोटोन दो समुदायों के बीच अपेक्षाकृत संकरा संक्रमण क्षेत्र है; इकोक्लाइन एक सहज प्रवणता है, जैसे ऊँचाई के साथ वनस्पति का बदलना।"},
  {"id":"env-ecology-451","question":"Fig trees are often regarded as keystone species in tropical forests mainly because:","options":["Staggered fruiting feeds many frugivores in lean seasons","Their wood is the main timber harvested from these forests","They fix large amounts of atmospheric nitrogen in the soil","Their roots prevent all soil erosion on the forest floor"],"answer":0,"explanation":"Asynchronous fruiting makes figs a lean-season lifeline for hornbills, primates, bats and other frugivores; losing figs would ripple through the whole community.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अंजीर के वृक्षों को उष्णकटिबंधीय वनों में प्रायः कीस्टोन प्रजाति माना जाता है, मुख्यतः क्योंकि:","optionsHi":["क्रमिक फलन अनेक फलभक्षियों को अभाव की ऋतुओं में भोजन देता है","उनकी लकड़ी इन वनों से काटी जाने वाली मुख्य इमारती लकड़ी है","वे मिट्टी में वायुमंडलीय नाइट्रोजन की बड़ी मात्रा का स्थिरीकरण करते हैं","उनकी जड़ें वन तल पर सभी मृदा अपरदन को रोक देती हैं"],"explanationHi":"असमकालिक फलन अंजीर को धनेश, प्राइमेट, चमगादड़ों और अन्य फलभक्षियों के लिए अभाव ऋतु की जीवनरेखा बनाता है; अंजीर के लुप्त होने का प्रभाव पूरे समुदाय में फैलेगा।"},
  {"id":"env-ecology-452","question":"When a country exports large quantities of rice, it is said to be exporting 'virtual water'. This refers to:","options":["Water lost by evaporation during shipping","Groundwater that flows across national borders","Water used to grow and process the crop","Desalinated water used in the exporting country"],"answer":2,"explanation":"Virtual water is the water embedded in the production of goods; water-intensive exports such as rice and cotton effectively ship water abroad.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जब कोई देश बड़ी मात्रा में चावल का निर्यात करता है, तो कहा जाता है कि वह 'आभासी जल' का निर्यात कर रहा है। इसका अर्थ है:","optionsHi":["जहाज़ों द्वारा परिवहन के दौरान वाष्पीकरण से खोया जल","राष्ट्रीय सीमाओं के पार बहने वाला भूजल","फसल को उगाने और संसाधित करने में प्रयुक्त जल","निर्यातक देश में प्रयुक्त विलवणीकृत जल"],"explanationHi":"आभासी जल वह जल है जो वस्तुओं के उत्पादन में निहित होता है; चावल और कपास जैसे जल-सघन निर्यात प्रभावी रूप से जल को विदेश भेजते हैं।"},
  {"id":"env-ecology-453","question":"In water footprint accounting, the 'grey water footprint' refers to:","options":["Rainwater stored in the soil and used by crops","Surface water and groundwater consumed in production","Lightly used household waste water from sinks that can be reused","Fresh water needed to dilute pollutants to quality standards"],"answer":3,"explanation":"Green is rainwater used by crops, blue is surface and groundwater consumed, and grey is dilution water; the trap is the everyday meaning of 'greywater' from households.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जल पदचिह्न लेखांकन में, 'ग्रे वॉटर फुटप्रिंट' से तात्पर्य है:","optionsHi":["मिट्टी में संचित और फसलों द्वारा उपयोग किया गया वर्षा जल","उत्पादन में उपभोग किया गया सतही जल और भूजल","सिंक से निकला हल्का प्रयुक्त घरेलू अपशिष्ट जल जिसका पुनः उपयोग हो सकता है","प्रदूषकों को गुणवत्ता मानकों तक तनु करने के लिए आवश्यक मीठा जल"],"explanationHi":"हरा वह वर्षा जल है जिसका फसलें उपयोग करती हैं, नीला उपभोग किया गया सतही और भूजल है, और ग्रे तनुकरण जल है; घरों के 'ग्रे वॉटर' का रोज़मर्रा का अर्थ ही जाल है।"},
  {"id":"env-ecology-454","question":"Consider the following statements: 1. Coastal upwelling brings cold, nutrient-rich deep water to the surface, making such waters highly productive. 2. During El Niño, upwelling off the coast of Peru weakens and fisheries such as the anchovy catch decline. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Upwelling zones cover a tiny share of the ocean but yield a large share of the fish catch; weaker trade winds in El Niño years shut down the Peruvian upwelling.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. तटीय उत्स्रवण ठंडे, पोषक-समृद्ध गहरे जल को सतह पर लाता है, जिससे ऐसे जल अत्यधिक उत्पादक बनते हैं। 2. एल नीनो के दौरान, पेरू के तट पर उत्स्रवण कमज़ोर पड़ता है और ऐंकोवी पकड़ जैसे मत्स्य उद्योग घट जाते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"उत्स्रवण क्षेत्र महासागर के छोटे हिस्से को ढकते हैं पर मछली पकड़ का बड़ा भाग देते हैं; एल नीनो वर्षों में कमज़ोर व्यापारिक पवनें पेरू के उत्स्रवण को बंद कर देती हैं।"},
  {"id":"env-ecology-455","question":"Consider the following statements about corals: 1. Bleached corals are not necessarily dead and can recover if the stress ends quickly enough. 2. Ocean acidification makes it harder for corals to build their calcium carbonate skeletons. Which of the statements given above is/are correct?","options":["1 only","Both 1 and 2","2 only","Neither 1 nor 2"],"answer":1,"explanation":"Bleached corals can regain zooxanthellae if temperatures fall soon, but prolonged bleaching starves them; lower carbonate ion levels slow calcification.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"प्रवालों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. विरंजित प्रवाल आवश्यक रूप से मृत नहीं होते और यदि तनाव शीघ्र समाप्त हो जाए तो पुनः स्वस्थ हो सकते हैं। 2. महासागरीय अम्लीकरण प्रवालों के लिए अपने कैल्शियम कार्बोनेट कंकाल बनाना कठिन कर देता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","1 और 2 दोनों","केवल 2","न तो 1 और न ही 2"],"explanationHi":"यदि तापमान शीघ्र घटे तो विरंजित प्रवाल ज़ूज़ैन्थेली पुनः प्राप्त कर सकते हैं, परंतु लंबे समय का विरंजन उन्हें भूखा मार देता है; कम कार्बोनेट आयन स्तर कैल्सीकरण को धीमा करते हैं।"},
  {"id":"env-ecology-456","question":"Arctic sea ice usually reaches its minimum extent each year in:","options":["March","June","September","December"],"answer":2,"explanation":"It melts through the northern summer and bottoms out in September, then reaches its maximum around March; Antarctic sea ice follows the opposite cycle.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आर्कटिक समुद्री बर्फ़ प्रतिवर्ष सामान्यतः किस महीने में अपने न्यूनतम विस्तार पर पहुँचती है?","optionsHi":["मार्च","जून","सितंबर","दिसंबर"],"explanationHi":"यह उत्तरी ग्रीष्म में पिघलती है और सितंबर में न्यूनतम पर पहुँचती है, फिर मार्च के आसपास अधिकतम होती है; अंटार्कटिक समुद्री बर्फ़ का चक्र इसके विपरीत होता है।"},
  {"id":"env-ecology-457","question":"Permafrost is defined as:","options":["Any ground covered by snow for more than six months a year","Glacier ice resting on bedrock","The top layer of soil that freezes every winter and thaws every summer","Ground staying at or below 0 °C for two or more years running"],"answer":3,"explanation":"The seasonally thawing surface layer above permafrost is the 'active layer'; as warming deepens it, carbon frozen for millennia begins to decompose.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पर्माफ्रॉस्ट की परिभाषा क्या है?","optionsHi":["कोई भी भूमि जो वर्ष में छह महीने से अधिक समय तक बर्फ़ से ढकी रहे","आधारशैल पर टिकी हिमनद बर्फ़","मिट्टी की ऊपरी परत जो प्रत्येक शीत में जमती और प्रत्येक ग्रीष्म में पिघलती है","भूमि जो लगातार दो या अधिक वर्षों तक 0 °C या उससे नीचे रहे"],"explanationHi":"पर्माफ्रॉस्ट के ऊपर मौसमी रूप से पिघलने वाली सतही परत 'सक्रिय परत' है; जैसे-जैसे तापन उसे गहरा करता है, हज़ारों वर्षों से जमा कार्बन अपघटित होने लगता है।"},
  {"id":"env-ecology-458","question":"Unlike methane, carbon dioxide has no single atmospheric 'lifetime'. This is because:","options":["CO2 is destroyed by ultraviolet light in the stratosphere at a fixed rate","Several sinks act on different timescales, some over millennia","CO2 is removed entirely by rain within a few weeks","CO2 turns into methane in the atmosphere after a century"],"answer":1,"explanation":"Much of a CO2 pulse is absorbed by oceans and land within decades to centuries, but a significant share lingers for millennia until slow geological processes remove it.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मीथेन के विपरीत, कार्बन डाइऑक्साइड का कोई एकल वायुमंडलीय 'जीवनकाल' नहीं है। इसका कारण यह है कि:","optionsHi":["CO2 समतापमंडल में पराबैंगनी प्रकाश द्वारा एक निश्चित दर से नष्ट होती है","अनेक अवशोषक भिन्न समय-सीमाओं पर कार्य करते हैं, कुछ हज़ारों वर्षों में","CO2 कुछ सप्ताह में वर्षा द्वारा पूरी तरह हटा दी जाती है","CO2 एक शताब्दी बाद वायुमंडल में मीथेन में बदल जाती है"],"explanationHi":"CO2 के किसी स्पंद का अधिकांश भाग दशकों से सदियों में महासागरों और स्थल द्वारा अवशोषित हो जाता है, परंतु एक महत्वपूर्ण भाग हज़ारों वर्षों तक बना रहता है जब तक धीमी भूवैज्ञानिक प्रक्रियाएँ उसे हटा न दें।"},
  {"id":"env-ecology-459","question":"Warmer air can hold about 7 per cent more water vapour for each 1 °C rise in temperature. This physical fact helps explain why a warming climate is expected to bring:","options":["More intense episodes of extreme rainfall","Fewer clouds and less rain everywhere on Earth","Less evaporation from the warmer oceans","A steady fall in global absolute humidity"],"answer":0,"explanation":"This relationship (Clausius–Clapeyron) means storms have more moisture to rain out, so heavy downpours intensify even where total rainfall changes little.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"तापमान में प्रत्येक 1 °C वृद्धि के लिए गर्म वायु लगभग 7 प्रतिशत अधिक जलवाष्प धारण कर सकती है। यह भौतिक तथ्य समझाने में सहायक है कि गर्म होती जलवायु से क्या अपेक्षित है?","optionsHi":["अत्यधिक वर्षा की अधिक तीव्र घटनाएँ","पृथ्वी पर सर्वत्र कम बादल और कम वर्षा","गर्म महासागरों से कम वाष्पीकरण","वैश्विक निरपेक्ष आर्द्रता में लगातार गिरावट"],"explanationHi":"यह संबंध (क्लॉज़ियस–क्लैपेयरॉन) बताता है कि तूफ़ानों के पास बरसाने के लिए अधिक नमी होती है, इसलिए कुल वर्षा में कम परिवर्तन होने पर भी भारी वर्षा तीव्र होती है।"},
  {"id":"env-ecology-460","question":"The idea of a remaining 'carbon budget' for a temperature limit rests on the finding that:","options":["Only methane emissions matter for long-term warming","Warming stops immediately once emissions begin to fall","Warming roughly tracks cumulative total CO2 emitted","The oceans can absorb unlimited carbon dioxide"],"answer":2,"explanation":"Because warming tracks the total CO2 ever emitted, a temperature cap implies a finite amount that can still be emitted; slowing emissions alone does not stop warming.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"किसी तापमान सीमा के लिए शेष 'कार्बन बजट' का विचार किस निष्कर्ष पर आधारित है?","optionsHi":["दीर्घकालिक तापन के लिए केवल मीथेन उत्सर्जन मायने रखता है","उत्सर्जन घटने लगते ही तापन तुरंत रुक जाता है","तापन लगभग उत्सर्जित कुल संचयी CO2 का अनुसरण करता है","महासागर असीमित कार्बन डाइऑक्साइड अवशोषित कर सकते हैं"],"explanationHi":"चूँकि तापन अब तक उत्सर्जित कुल CO2 का अनुसरण करता है, तापमान की सीमा का अर्थ है कि अब भी केवल सीमित मात्रा उत्सर्जित की जा सकती है; केवल उत्सर्जन धीमा करने से तापन नहीं रुकता।"},
  {"id":"env-ecology-461","question":"'Equilibrium climate sensitivity' is defined as:","options":["The rise in sea level for each degree of warming","The warming at the moment CO2 doubles, before the oceans catch up","The change in global rainfall per degree of warming","Eventual warming from doubled CO2 once the climate fully adjusts"],"answer":3,"explanation":"It measures how strongly the climate responds to a doubling of CO2 once the oceans have caught up; the warming at the time of doubling is the transient climate response, a different and lower quantity.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"'साम्यावस्था जलवायु संवेदनशीलता' की परिभाषा क्या है?","optionsHi":["प्रत्येक डिग्री तापन के लिए समुद्र-स्तर में वृद्धि","जब CO2 दोगुनी होती है उस क्षण का तापन, महासागरों के पकड़ बनाने से पहले","प्रत्येक डिग्री तापन पर वैश्विक वर्षा में परिवर्तन","जलवायु के पूरी तरह समायोजित होने पर CO2 के दोगुना होने से अंततः होने वाला तापन"],"explanationHi":"यह मापती है कि महासागरों के पकड़ बना लेने पर जलवायु CO2 के दोगुना होने पर कितनी प्रबलता से प्रतिक्रिया करती है; दोगुना होने के समय का तापन क्षणिक जलवायु अनुक्रिया है, जो एक भिन्न और कम राशि है।"},
  {"id":"env-ecology-462","question":"Which of the following are counted as short-lived climate pollutants? 1. Black carbon 2. Methane 3. Tropospheric ozone 4. Nitrous oxide. Select the correct answer.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Black carbon lasts days, tropospheric ozone weeks and methane about a decade; nitrous oxide persists for over a century, so it is long-lived.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से किन्हें अल्पजीवी जलवायु प्रदूषक माना जाता है? 1. ब्लैक कार्बन 2. मीथेन 3. क्षोभमंडलीय ओज़ोन 4. नाइट्रस ऑक्साइड। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"ब्लैक कार्बन दिनों तक, क्षोभमंडलीय ओज़ोन सप्ताहों तक और मीथेन लगभग एक दशक तक टिकती है; नाइट्रस ऑक्साइड एक शताब्दी से अधिक टिकती है, इसलिए दीर्घजीवी है।"},
  {"id":"env-ecology-463","question":"Which of the following are usually counted as coastal 'blue carbon' ecosystems? 1. Mangroves 2. Seagrass meadows 3. Tidal salt marshes 4. Coral reefs. Select the correct answer.","options":["1, 2 and 3 only","1 and 2 only","2 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Mangroves, seagrasses and salt marshes bury carbon in their sediments; coral reefs are not counted, as building calcium carbonate skeletons releases CO2.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से किन्हें सामान्यतः तटीय 'ब्लू कार्बन' पारिस्थितिकी तंत्र माना जाता है? 1. मैंग्रोव 2. समुद्री घास के मैदान 3. ज्वारीय लवणीय दलदल 4. प्रवाल भित्तियाँ। सही उत्तर चुनिए।","optionsHi":["केवल 1, 2 और 3","केवल 1 और 2","केवल 2 और 4","1, 2, 3 और 4"],"explanationHi":"मैंग्रोव, समुद्री घास और लवणीय दलदल अपने तलछट में कार्बन दबाते हैं; प्रवाल भित्तियाँ नहीं गिनी जातीं, क्योंकि कैल्शियम कार्बोनेट के कंकाल बनाने से CO2 मुक्त होती है।"},
  {"id":"env-ecology-464","question":"Consider the following statements: 1. The world's soils hold more carbon than the atmosphere and all vegetation combined. 2. Repeated tillage generally increases the loss of organic carbon from soil. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Soil is the largest land carbon store; ploughing breaks up aggregates and aerates soil, speeding decomposition, which is why no-till and cover crops are promoted.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. विश्व की मिट्टियों में वायुमंडल और समस्त वनस्पति के संयुक्त कार्बन से अधिक कार्बन संचित है। 2. बार-बार जुताई सामान्यतः मिट्टी से कार्बनिक कार्बन की हानि बढ़ाती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["1 और 2 दोनों","केवल 1","केवल 2","न तो 1 और न ही 2"],"explanationHi":"मिट्टी स्थल का सबसे बड़ा कार्बन भंडार है; जुताई समुच्चयों को तोड़ती है और मिट्टी में वायु पहुँचाती है, जिससे अपघटन तेज़ होता है, इसीलिए शून्य-जुताई और आवरण फसलों को प्रोत्साहित किया जाता है।"},
  {"id":"env-ecology-465","question":"The average albedo of the Earth as a whole, i.e., the fraction of incoming sunlight reflected back to space, is about:","options":["0.03","0.7","0.9","0.3"],"answer":3,"explanation":"About 30 per cent of sunlight is reflected, mostly by clouds, with smaller shares from the surface and the air; 0.7 is the share absorbed, a common mix-up.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संपूर्ण पृथ्वी का औसत एल्बिडो, अर्थात् आने वाले सूर्य के प्रकाश का वह अंश जो अंतरिक्ष में परावर्तित हो जाता है, लगभग कितना है?","optionsHi":["0.03","0.7","0.9","0.3"],"explanationHi":"सूर्य के प्रकाश का लगभग 30 प्रतिशत परावर्तित होता है, अधिकांशतः बादलों द्वारा, और छोटे हिस्से सतह और वायु द्वारा; 0.7 अवशोषित होने वाला हिस्सा है, जो एक सामान्य भ्रम है।"},
  {"id":"env-ecology-466","question":"Under the Ramsar Convention's criteria for wetlands of international importance, a wetland qualifies on numbers alone if it regularly supports at least:","options":["2,000 waterbirds","10,000 waterbirds","20,000 waterbirds","1,00,000 waterbirds"],"answer":2,"explanation":"Criterion 5 sets the threshold at 20,000 or more waterbirds; Criterion 6 covers wetlands holding 1 per cent of a population of one waterbird species.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अंतरराष्ट्रीय महत्व की आर्द्रभूमियों के रामसर कन्वेंशन के मानदंडों के अंतर्गत, कोई आर्द्रभूमि केवल संख्या के आधार पर तब अर्हता प्राप्त करती है जब वह नियमित रूप से कम से कम कितने जलपक्षियों को सहारा देती है?","optionsHi":["2,000 जलपक्षी","10,000 जलपक्षी","20,000 जलपक्षी","1,00,000 जलपक्षी"],"explanationHi":"मानदंड 5 सीमा को 20,000 या अधिक जलपक्षियों पर निर्धारित करता है; मानदंड 6 उन आर्द्रभूमियों को शामिल करता है जिनमें किसी एक जलपक्षी प्रजाति की आबादी का 1 प्रतिशत होता है।"},
  {"id":"env-ecology-467","question":"Consider the following statements about the Wildlife (Protection) Act, 1972: 1. Once a national park is finally notified, no right of any person can, as a rule, continue to exist within it. 2. In a wildlife sanctuary, the Collector may allow certain rights of people to continue, in consultation with the Chief Wildlife Warden. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"This is the key legal difference: rights must be settled and extinguished before a national park is finally declared, while a sanctuary can retain some rights such as limited grazing.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वन्यजीव (संरक्षण) अधिनियम, 1972 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. राष्ट्रीय उद्यान के अंतिम रूप से अधिसूचित हो जाने पर, नियमतः उसके भीतर किसी व्यक्ति का कोई अधिकार बना नहीं रह सकता। 2. वन्यजीव अभयारण्य में, कलेक्टर मुख्य वन्यजीव प्रतिपालक से परामर्श कर लोगों के कुछ अधिकारों को जारी रहने दे सकता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"यह मुख्य कानूनी अंतर है: राष्ट्रीय उद्यान के अंतिम रूप से घोषित होने से पहले अधिकारों का निपटारा और समाप्ति आवश्यक है, जबकि अभयारण्य में सीमित चराई जैसे कुछ अधिकार बने रह सकते हैं।"},
  {"id":"env-ecology-468","question":"Under the guidelines for eco-sensitive zones around protected areas, which of the following activities is generally prohibited?","options":["Commercial mining","Rainwater harvesting","Organic farming","Construction of hotels and resorts"],"answer":0,"explanation":"Commercial mining, saw mills and polluting industries are prohibited; hotels and similar construction are regulated, while rainwater harvesting and organic farming are encouraged.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संरक्षित क्षेत्रों के आसपास पारिस्थितिक रूप से संवेदनशील क्षेत्रों के दिशानिर्देशों के अंतर्गत निम्नलिखित में से कौन-सी गतिविधि सामान्यतः प्रतिबंधित है?","optionsHi":["वाणिज्यिक खनन","वर्षा जल संचयन","जैविक खेती","होटलों और रिसॉर्टों का निर्माण"],"explanationHi":"वाणिज्यिक खनन, आरा मिलें और प्रदूषणकारी उद्योग प्रतिबंधित हैं; होटलों और ऐसे निर्माण को विनियमित किया जाता है, जबकि वर्षा जल संचयन और जैविक खेती को प्रोत्साहित किया जाता है।"},
  {"id":"env-ecology-469","question":"Camera-trap surveys used to estimate tiger numbers in India rely mainly on the fact that:","options":["Tigers are drawn to the camera's infrared flash and keep returning","Unique stripe patterns allow capture–recapture of individuals","Tiger pugmarks differ by sex and show up in photographs","Tigers always use the same trail at the same time each night"],"answer":1,"explanation":"Stripes are like fingerprints; photographing both flanks lets researchers identify individuals and estimate density statistically, replacing the old pugmark census.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत में बाघों की संख्या का अनुमान लगाने के लिए प्रयुक्त कैमरा-ट्रैप सर्वेक्षण मुख्यतः किस तथ्य पर निर्भर करते हैं?","optionsHi":["बाघ कैमरे की अवरक्त फ़्लैश से आकर्षित होते हैं और बार-बार लौटते हैं","अद्वितीय धारी पैटर्न व्यक्तिगत बाघों की पकड़–पुनः पकड़ की अनुमति देते हैं","बाघ के पगचिह्न नर-मादा के अनुसार भिन्न होते हैं और तस्वीरों में दिखते हैं","बाघ हर रात एक ही समय पर सदा एक ही रास्ते का उपयोग करते हैं"],"explanationHi":"धारियाँ उँगलियों के निशान जैसी होती हैं; दोनों पार्श्वों की तस्वीर लेने से शोधकर्ता व्यक्तिगत बाघों की पहचान कर सकते हैं और सांख्यिकीय रूप से घनत्व का अनुमान लगा सकते हैं, जिसने पुरानी पगचिह्न गणना का स्थान लिया।"},
  {"id":"env-ecology-470","question":"Hot, dry summers and mild, wet winters, with evergreen scrub (maquis or chaparral) adapted to periodic fires, describe which biome?","options":["Tropical savanna","Mediterranean","Temperate deciduous forest","Temperate grassland (steppe)"],"answer":1,"explanation":"The Mediterranean biome occurs on west coasts at about 30–40° latitude, including California, central Chile, the Cape and south-west Australia, not just around the Mediterranean.","difficulty":"hard","source":"UPSC Prelims","questionHi":"गर्म, शुष्क ग्रीष्म और सौम्य, आर्द्र शीत, साथ में आवधिक आग के अनुकूल सदाबहार झाड़ियाँ (माक्विस या चैपरल), किस बायोम का वर्णन करती हैं?","optionsHi":["उष्णकटिबंधीय सवाना","भूमध्यसागरीय","शीतोष्ण पर्णपाती वन","शीतोष्ण घास का मैदान (स्टेपी)"],"explanationHi":"भूमध्यसागरीय बायोम लगभग 30–40° अक्षांश पर पश्चिमी तटों पर पाया जाता है, जिसमें कैलिफ़ोर्निया, मध्य चिली, केप और दक्षिण-पश्चिम ऑस्ट्रेलिया शामिल हैं, केवल भूमध्य सागर के आसपास ही नहीं।"},
  {"id":"env-ecology-471","question":"Consider the following statements about the tundra: 1. Permafrost prevents plants from developing deep roots. 2. Decomposition is rapid because of the long daylight of summer. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Cold, waterlogged soils keep decomposition very slow despite the long summer days, so organic matter piles up as peat.","difficulty":"hard","source":"UPSC Prelims","questionHi":"टुंड्रा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. पर्माफ्रॉस्ट पौधों को गहरी जड़ें विकसित करने से रोकता है। 2. ग्रीष्म के लंबे दिन के प्रकाश के कारण अपघटन तेज़ होता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"ठंडी, जलमग्न मिट्टी ग्रीष्म के लंबे दिनों के बावजूद अपघटन को बहुत धीमा रखती है, इसलिए कार्बनिक पदार्थ पीट के रूप में जमा होता जाता है।"},
  {"id":"env-ecology-472","question":"The soils beneath the coniferous taiga forests are typically:","options":["Deep, black and highly fertile, rich in humus like chernozems","Red, iron-rich laterites from intense weathering","Saline soils formed by high evaporation","Acidic, leached podzols under slowly decaying needle litter"],"answer":3,"explanation":"Acidic needle litter and percolating snowmelt leach nutrients and iron from the upper layer, leaving a pale, infertile horizon typical of podzols.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"शंकुधारी टैगा वनों के नीचे की मिट्टियाँ सामान्यतः कैसी होती हैं?","optionsHi":["गहरी, काली और अत्यंत उपजाऊ, चर्नोज़ेम की तरह ह्यूमस-समृद्ध","तीव्र अपक्षय से बनी लाल, लौह-समृद्ध लैटेराइट","उच्च वाष्पीकरण से बनी लवणीय मिट्टियाँ","धीरे-धीरे अपघटित होने वाले सुई-पत्ती कचरे के नीचे अम्लीय, निक्षालित पॉडज़ोल"],"explanationHi":"अम्लीय सुई-कचरा और रिसता बर्फ़ पिघला जल ऊपरी परत से पोषक तत्वों और लोहे का निक्षालन कर देते हैं, जिससे पॉडज़ोल की विशिष्ट पीली, अनुपजाऊ परत बचती है।"},
  {"id":"env-ecology-473","question":"Grasses withstand grazing and fire better than many other plants mainly because:","options":["They have deep tap roots that store water and food","Their leaves contain toxins that deter most grazers","Their meristems lie at or near ground level","They reproduce only by seeds that survive the fire"],"answer":2,"explanation":"Because growth comes from near the ground, grasses regrow after their tops are eaten or burnt, which is why fire and grazing maintain grasslands against trees.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"घासें चराई और आग को अनेक अन्य पौधों से बेहतर सहन करती हैं, मुख्यतः क्योंकि:","optionsHi":["उनकी गहरी मूसला जड़ें जल और भोजन संचित करती हैं","उनकी पत्तियों में विष होते हैं जो अधिकांश चरने वालों को रोकते हैं","उनके विभज्योतक भूमि स्तर पर या उसके निकट होते हैं","वे केवल उन बीजों से प्रजनन करती हैं जो आग में बच जाते हैं"],"explanationHi":"क्योंकि वृद्धि भूमि के निकट से होती है, घासें अपने ऊपरी भाग खाए या जलाए जाने के बाद पुनः उग आती हैं, इसीलिए आग और चराई घास के मैदानों को वृक्षों के विरुद्ध बनाए रखती हैं।"},
  {"id":"env-ecology-474","question":"Consider the following statements: 1. Deserts are defined mainly by very low precipitation, not by high temperature. 2. By that definition, much of Antarctica is a desert. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Cold deserts such as Ladakh, the Gobi and interior Antarctica receive very little precipitation even though they are cold.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. मरुस्थलों की परिभाषा मुख्यतः बहुत कम वर्षण से होती है, उच्च तापमान से नहीं। 2. इस परिभाषा के अनुसार, अंटार्कटिका का अधिकांश भाग मरुस्थल है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"लद्दाख, गोबी और अंटार्कटिका के आंतरिक भाग जैसे शीत मरुस्थलों में ठंडे होने पर भी बहुत कम वर्षण होता है।"},
  {"id":"env-ecology-475","question":"A peat-forming wetland fed mainly by rain, with acidic, nutrient-poor water and dominated by Sphagnum moss, is called a:","options":["Fen","Marsh","Bog","Swamp"],"answer":2,"explanation":"Fens are fed by mineral-rich groundwater and are less acidic; marshes are dominated by grasses and reeds, swamps by trees.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मुख्यतः वर्षा से पोषित, अम्लीय, पोषक-निर्धन जल वाली और स्फैग्नम काई की प्रधानता वाली पीट बनाने वाली आर्द्रभूमि क्या कहलाती है?","optionsHi":["फेन (दलदली पीटभूमि)","मार्श (दलदल)","बोग (अम्लीय पीट दलदल)","स्वैम्प (वृक्षीय दलदल)"],"explanationHi":"फेन खनिज-समृद्ध भूजल से पोषित और कम अम्लीय होते हैं; मार्श में घास और नरकट प्रधान होते हैं, स्वैम्प में वृक्ष।"},
  {"id":"env-ecology-476","question":"The Navdanya movement, founded by Vandana Shiva, focuses mainly on:","options":["Conserving native seeds and promoting organic farming","Protesting against large dams on the Narmada river","Protecting sacred groves in the Western Ghats","Saving the khejri trees of Rajasthan's Bishnoi villages"],"answer":0,"explanation":"Navdanya ('nine seeds') runs community seed banks and promotes organic farming; the Narmada protests were the Narmada Bachao Andolan, and the khejri episode is the Bishnoi sacrifice of 1730.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"वंदना शिवा द्वारा स्थापित नवधान्य आंदोलन मुख्यतः किस पर केंद्रित है?","optionsHi":["देशज बीजों का संरक्षण और जैविक खेती को बढ़ावा","नर्मदा नदी पर बड़े बाँधों के विरुद्ध विरोध","पश्चिमी घाट के पवित्र उपवनों की रक्षा","राजस्थान के बिश्नोई गाँवों के खेजड़ी वृक्षों को बचाना"],"explanationHi":"नवधान्य ('नौ बीज') सामुदायिक बीज बैंक चलाता है और जैविक खेती को बढ़ावा देता है; नर्मदा के विरोध नर्मदा बचाओ आंदोलन के थे, और खेजड़ी प्रकरण 1730 का बिश्नोई बलिदान है।"},
  {"id":"env-ecology-477","question":"The Plachimada struggle in Kerala was directed against:","options":["Illegal sand mining on the Bharathapuzha river bed","Water mining blamed on a soft-drink bottling plant","A nuclear power project planned on the coast","Clearing of mangroves for a container port"],"answer":1,"explanation":"Villagers in Palakkad district protested that the Coca-Cola plant had drawn down and polluted local groundwater; the case became a landmark in debates on water rights.","difficulty":"hard","source":"UPSC Prelims","questionHi":"केरल का प्लाचीमाडा संघर्ष किसके विरुद्ध था?","optionsHi":["भरतपुझा नदी तल में अवैध रेत खनन","एक शीतल पेय बोतलबंदी संयंत्र को दोषी ठहराया गया जल दोहन","तट पर प्रस्तावित एक नाभिकीय ऊर्जा परियोजना","कंटेनर बंदरगाह के लिए मैंग्रोव की सफ़ाई"],"explanationHi":"पलक्कड़ ज़िले के ग्रामीणों ने विरोध किया कि कोका-कोला संयंत्र ने स्थानीय भूजल को घटाया और प्रदूषित किया; यह मामला जल अधिकारों पर बहस में एक मील का पत्थर बना।"},
  {"id":"env-ecology-478","question":"Consider the following pairs of Sustainable Development Goal and its theme: 1. SDG 13 — Climate action 2. SDG 14 — Life on land 3. SDG 15 — Life below water 4. SDG 6 — Clean water and sanitation. How many of the pairs given above are correctly matched?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"SDG 14 is Life below water and SDG 15 is Life on land, so pairs 2 and 3 are swapped; SDG 13 and SDG 6 are correct.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सतत विकास लक्ष्य (SDG) और उसके विषय की निम्नलिखित जोड़ियों पर विचार कीजिए: 1. SDG 13 — जलवायु कार्रवाई 2. SDG 14 — स्थल पर जीवन 3. SDG 15 — जल के नीचे जीवन 4. SDG 6 — स्वच्छ जल और स्वच्छता। उपर्युक्त में से कितनी जोड़ियाँ सही सुमेलित हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"SDG 14 जल के नीचे जीवन और SDG 15 स्थल पर जीवन है, इसलिए जोड़ियाँ 2 और 3 आपस में बदली हुई हैं; SDG 13 और SDG 6 सही हैं।"},
  {"id":"env-ecology-479","question":"Consider the following statements about ground-level ozone and crops: 1. It can reduce the yields of crops such as wheat. 2. It enters plant leaves mainly through the stomata. Which of the statements given above is/are correct?","options":["Both 1 and 2","1 only","2 only","Neither 1 nor 2"],"answer":0,"explanation":"Ozone taken in through the stomata oxidises leaf tissues and lowers photosynthesis; studies in South Asia link it to significant wheat and rice losses.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भू-स्तरीय ओज़ोन और फसलों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह गेहूँ जैसी फसलों की उपज घटा सकती है। 2. यह पौधों की पत्तियों में मुख्यतः रंध्रों के माध्यम से प्रवेश करती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["1 और 2 दोनों","केवल 1","केवल 2","न तो 1 और न ही 2"],"explanationHi":"रंध्रों से ली गई ओज़ोन पत्ती के ऊतकों का ऑक्सीकरण करती है और प्रकाश-संश्लेषण घटाती है; दक्षिण एशिया के अध्ययन इसे गेहूँ और धान की महत्वपूर्ण हानियों से जोड़ते हैं।"},
  {"id":"env-ecology-480","question":"Ammonia released from fertilisers and livestock contributes to fine particulate (PM2.5) pollution in cities mainly because it:","options":["Is itself emitted as fine solid particles from fields and sheds","Reacts with ozone in sunlight to form black carbon soot particles","Absorbs water vapour and falls out as acid rain","Reacts with acids from SO2 and NOx to form ammonium salts"],"answer":3,"explanation":"These secondary inorganic aerosols form a large share of winter PM2.5 in north India, which is why cutting ammonia can lower particulate levels even though ammonia is a gas.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उर्वरकों और पशुधन से निकली अमोनिया शहरों में महीन कणिकीय (PM2.5) प्रदूषण में मुख्यतः इसलिए योगदान देती है क्योंकि वह:","optionsHi":["स्वयं खेतों और बाड़ों से महीन ठोस कणों के रूप में उत्सर्जित होती है","सूर्य के प्रकाश में ओज़ोन से अभिक्रिया कर ब्लैक कार्बन कालिख कण बनाती है","जलवाष्प को अवशोषित करती है और अम्ल वर्षा के रूप में गिरती है","SO2 और NOx से बने अम्लों से अभिक्रिया कर अमोनियम लवण बनाती है"],"explanationHi":"ये द्वितीयक अकार्बनिक एरोसोल उत्तर भारत में शीतकालीन PM2.5 का बड़ा हिस्सा बनाते हैं, इसीलिए अमोनिया घटाने से कणिकीय स्तर घट सकते हैं, भले ही अमोनिया एक गैस है।"},
  {"id":"env-ecology-481","question":"Mesothelioma, a cancer of the lining of the lungs or abdomen, is most closely linked with exposure to:","options":["Crystalline silica dust","Coal dust","Asbestos fibres","Cotton dust"],"answer":2,"explanation":"Inhaled asbestos fibres cause asbestosis and mesothelioma; silica causes silicosis, coal dust black lung, and cotton dust byssinosis.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मेसोथेलियोमा, फेफड़ों या उदर की परत का कैंसर, किसके संपर्क से सबसे अधिक निकटता से जुड़ा है?","optionsHi":["क्रिस्टलीय सिलिका की धूल","कोयले की धूल","एस्बेस्टस के रेशे","कपास की धूल"],"explanationHi":"साँस के साथ गए एस्बेस्टस के रेशे एस्बेस्टोसिस और मेसोथेलियोमा उत्पन्न करते हैं; सिलिका सिलिकोसिस, कोयले की धूल ब्लैक लंग और कपास की धूल बिसिनोसिस उत्पन्न करती है।"},
  {"id":"env-ecology-482","question":"Which of the following pairs of occupational lung disease and its cause are correctly matched? 1. Byssinosis — cotton dust 2. Silicosis — silica dust from stone quarrying and cutting 3. Coal workers' pneumoconiosis — asbestos. Select the correct answer.","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Coal workers' pneumoconiosis ('black lung') is caused by coal dust, not asbestos.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"व्यावसायिक फेफड़े के रोग और उसके कारण की निम्नलिखित जोड़ियों में से कौन-सी सही सुमेलित हैं? 1. बिसिनोसिस — कपास की धूल 2. सिलिकोसिस — पत्थर की खुदाई और कटाई से सिलिका की धूल 3. कोयला श्रमिकों का न्यूमोकोनियोसिस — एस्बेस्टस। सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"कोयला श्रमिकों का न्यूमोकोनियोसिस ('ब्लैक लंग') कोयले की धूल से होता है, एस्बेस्टस से नहीं।"},
  {"id":"env-ecology-483","question":"The sievert is a unit used to measure:","options":["The number of radioactive decays per second","The energy absorbed per kilogram of tissue, without regard to the type of radiation","The effective dose of radiation, which allows for its biological effect on the body","The half-life of a radioactive isotope"],"answer":2,"explanation":"Becquerel measures activity and gray the absorbed dose; the sievert weights the dose by radiation type and tissue sensitivity to express health risk.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सीवर्ट (sievert) किसे मापने की इकाई है?","optionsHi":["प्रति सेकंड रेडियोधर्मी क्षयों की संख्या","ऊतक के प्रति किलोग्राम अवशोषित ऊर्जा, विकिरण के प्रकार का ध्यान रखे बिना","विकिरण की प्रभावी मात्रा, जो शरीर पर उसके जैविक प्रभाव को ध्यान में रखती है","किसी रेडियोधर्मी समस्थानिक की अर्ध-आयु"],"explanationHi":"बेकरेल सक्रियता और ग्रे अवशोषित मात्रा मापता है; सीवर्ट स्वास्थ्य जोखिम व्यक्त करने के लिए मात्रा को विकिरण के प्रकार और ऊतक की संवेदनशीलता से भारित करता है।"},
  {"id":"env-ecology-484","question":"'Vitrification' of high-level radioactive waste refers to:","options":["Burning the waste at very high temperatures to destroy it","Locking it into stable glass for long-term storage","Diluting it in deep seawater","Converting it into non-radioactive elements"],"answer":1,"explanation":"Mixing the waste with glass-forming materials and melting it immobilises the radionuclides; radioactivity itself cannot be destroyed by burning or chemistry.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उच्च-स्तरीय रेडियोधर्मी अपशिष्ट के 'काचीकरण (विट्रिफिकेशन)' से तात्पर्य है:","optionsHi":["अपशिष्ट को नष्ट करने के लिए बहुत उच्च तापमान पर जलाना","उसे दीर्घकालिक भंडारण के लिए स्थिर काँच में बाँध देना","उसे गहरे समुद्री जल में तनु करना","उसे अरेडियोधर्मी तत्वों में बदलना"],"explanationHi":"अपशिष्ट को काँच-निर्माता पदार्थों के साथ मिलाकर पिघलाने से रेडियोन्यूक्लाइड स्थिर हो जाते हैं; रेडियोधर्मिता को स्वयं जलाने या रसायन से नष्ट नहीं किया जा सकता।"},
  {"id":"env-ecology-485","question":"The main environmental concern with seawater desalination by reverse osmosis is:","options":["Release of chlorofluorocarbons from the membranes","Radioactive contamination of the product water","The large volumes of CO2 it pulls from the air","Brine discharge and high energy demand"],"answer":3,"explanation":"Dense, highly saline brine (often with treatment chemicals) can harm seabed life near outfalls, and the energy demand adds emissions if supplied by fossil fuels.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रतिलोम परासरण (रिवर्स ऑस्मोसिस) द्वारा समुद्री जल के विलवणीकरण की मुख्य पर्यावरणीय चिंता क्या है?","optionsHi":["झिल्लियों से क्लोरोफ्लोरोकार्बन का निकलना","उत्पाद जल का रेडियोधर्मी संदूषण","वायु से उसके द्वारा खींची गई CO2 की बड़ी मात्रा","लवण-जल (ब्राइन) का निर्वहन और उच्च ऊर्जा माँग"],"explanationHi":"सघन, अत्यधिक लवणीय ब्राइन (प्रायः उपचार रसायनों के साथ) निकास के निकट समुद्र-तल के जीवन को हानि पहुँचा सकता है, और ऊर्जा माँग जीवाश्म ईंधन से आपूर्ति होने पर उत्सर्जन जोड़ती है।"},
  {"id":"env-ecology-486","question":"Gypsum is applied to reclaim which kind of problem soil?","options":["Acidic soils","Sodic (alkali) soils","Waterlogged peat soils","Lateritic soils rich in iron"],"answer":1,"explanation":"Calcium from gypsum displaces exchangeable sodium, which is then leached away; acidic soils are corrected with lime instead.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जिप्सम का उपयोग किस प्रकार की समस्याग्रस्त मिट्टी के सुधार के लिए किया जाता है?","optionsHi":["अम्लीय मिट्टियाँ","सोडिक (क्षारीय) मिट्टियाँ","जलमग्न पीट मिट्टियाँ","लोहे से समृद्ध लैटेराइट मिट्टियाँ"],"explanationHi":"जिप्सम का कैल्शियम विनिमेय सोडियम को विस्थापित करता है, जो फिर निक्षालित हो जाता है; अम्लीय मिट्टियों को इसके बजाय चूने से सुधारा जाता है।"},
  {"id":"env-ecology-487","question":"LaCONES, a facility in Hyderabad, is associated with:","options":["Conserving endangered wildlife using biotechnology","Monitoring cyclones over the Bay of Bengal","Testing pesticides for residue levels in food","Breeding high-yielding rice varieties for dry areas"],"answer":0,"explanation":"The Laboratory for the Conservation of Endangered Species, part of CCMB, stores genetic material and supports captive breeding, an ex situ conservation tool.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"हैदराबाद स्थित सुविधा LaCONES किससे संबंधित है?","optionsHi":["जैव प्रौद्योगिकी द्वारा संकटग्रस्त वन्यजीवों का संरक्षण","बंगाल की खाड़ी के ऊपर चक्रवातों की निगरानी","खाद्य में अवशेष स्तरों के लिए कीटनाशकों का परीक्षण","शुष्क क्षेत्रों के लिए अधिक उपज वाली धान की किस्मों का प्रजनन"],"explanationHi":"संकटग्रस्त प्रजातियों के संरक्षण की प्रयोगशाला, CCMB का भाग, आनुवंशिक सामग्री संग्रहीत करती है और बंदी-प्रजनन में सहायता करती है, जो बहिःस्थाने संरक्षण का एक साधन है।"},
  {"id":"env-ecology-488","question":"India's National Gene Bank for the long-term storage of plant germplasm is maintained by the:","options":["Botanical Survey of India, Kolkata","ICRISAT, Hyderabad","NBPGR (ICAR), New Delhi","Forest Research Institute, Dehradun"],"answer":2,"explanation":"The National Bureau of Plant Genetic Resources (NBPGR) runs the National Gene Bank, storing seeds at sub-zero temperatures and other material by cryopreservation; the BSI surveys and documents wild flora.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पादप जननद्रव्य के दीर्घकालिक भंडारण के लिए भारत का राष्ट्रीय जीन बैंक किसके द्वारा संचालित है?","optionsHi":["भारतीय वनस्पति सर्वेक्षण, कोलकाता","ICRISAT, हैदराबाद","NBPGR (ICAR), नई दिल्ली","वन अनुसंधान संस्थान, देहरादून"],"explanationHi":"राष्ट्रीय पादप आनुवंशिक संसाधन ब्यूरो (NBPGR) राष्ट्रीय जीन बैंक चलाता है, जो बीजों को शून्य से नीचे के तापमान पर और अन्य सामग्री को क्रायोप्रिज़र्वेशन से संग्रहीत करता है; BSI जंगली वनस्पतियों का सर्वेक्षण और दस्तावेज़ीकरण करता है।"},
  {"id":"env-ecology-489","question":"Consider the following statements: 1. The Botanical Survey of India was established in 1890. 2. The Zoological Survey of India was established in 1916. 3. Both are headquartered in Kolkata. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct; both bodies, under the Environment Ministry, survey, document and describe India's flora and fauna.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. भारतीय वनस्पति सर्वेक्षण की स्थापना 1890 में हुई। 2. भारतीय प्राणी सर्वेक्षण की स्थापना 1916 में हुई। 3. दोनों का मुख्यालय कोलकाता में है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं; पर्यावरण मंत्रालय के अंतर्गत दोनों निकाय भारत की वनस्पतियों और जीव-जंतुओं का सर्वेक्षण, दस्तावेज़ीकरण और वर्णन करते हैं।"},
  {"id":"env-ecology-490","question":"Consider the following statements about clouds and climate: 1. Low, thick clouds tend to cool the surface, mainly by reflecting sunlight. 2. High, thin cirrus clouds tend to warm the surface, because they trap outgoing infrared more than they reflect sunlight. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Cloud type and height decide the net effect, which is why clouds remain a major source of uncertainty in climate projections.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"बादलों और जलवायु के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. निचले, मोटे बादल मुख्यतः सूर्य के प्रकाश को परावर्तित कर सतह को ठंडा करते हैं। 2. ऊँचे, पतले सिरस बादल सतह को गर्म करते हैं, क्योंकि वे सूर्य के प्रकाश को परावर्तित करने से अधिक बाहर जाने वाली अवरक्त को रोकते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"बादल का प्रकार और ऊँचाई शुद्ध प्रभाव तय करते हैं, इसीलिए जलवायु अनुमानों में बादल अनिश्चितता का एक प्रमुख स्रोत बने हुए हैं।"},
  {"id":"env-ecology-491","question":"Consider the following statements about the Atlantic Meridional Overturning Circulation: 1. It is driven partly by cold, salty, dense water sinking in the North Atlantic. 2. Large inflows of fresh meltwater could weaken it. Which of the statements given above is/are correct?","options":["1 only","Both 1 and 2","2 only","Neither 1 nor 2"],"answer":1,"explanation":"Fresh water lowers salinity and density, reducing sinking; a weaker AMOC would alter heat transport to Europe and could shift tropical rain belts.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अटलांटिक मेरिडियनल ओवरटर्निंग सर्कुलेशन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह आंशिक रूप से उत्तरी अटलांटिक में डूबते ठंडे, खारे, घने जल से संचालित होता है। 2. मीठे पिघले जल का बड़ा प्रवाह इसे कमज़ोर कर सकता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","1 और 2 दोनों","केवल 2","न तो 1 और न ही 2"],"explanationHi":"मीठा जल लवणता और घनत्व घटाता है, जिससे डूबना कम होता है; कमज़ोर AMOC यूरोप तक ऊष्मा परिवहन को बदल देगा और उष्णकटिबंधीय वर्षा पट्टियों को खिसका सकता है।"},
  {"id":"env-ecology-492","question":"Assertion (A): The Montreal Protocol has also helped to slow global warming. Reason (R): Many of the ozone-depleting substances it controls are also potent greenhouse gases. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"CFCs have warming potentials thousands of times that of CO2, so phasing them out avoided a large amount of warming as well as ozone loss.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): मॉन्ट्रियल प्रोटोकॉल ने वैश्विक तापन को धीमा करने में भी सहायता की है। कारण (R): इसके द्वारा नियंत्रित अनेक ओज़ोन-क्षयकारी पदार्थ प्रबल हरितगृह गैसें भी हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"CFCs की तापन क्षमता CO2 की हज़ारों गुना है, इसलिए उन्हें चरणबद्ध ढंग से हटाने से ओज़ोन हानि के साथ-साथ बड़ी मात्रा में तापन भी टला।"},
  {"id":"env-ecology-493","question":"The Aarhus Convention (1998) concerns:","options":["Transboundary movement and disposal of hazardous waste","Conservation of European wild flora, fauna and natural habitats","Long-range transboundary air pollution in Europe","Citizens' rights to environmental information and justice"],"answer":3,"explanation":"Aarhus is a UNECE treaty on environmental rights of citizens; hazardous waste is the Basel Convention and European wildlife the Bern Convention.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आरहूस कन्वेंशन (1998) किससे संबंधित है?","optionsHi":["खतरनाक अपशिष्ट की सीमा-पार आवाजाही और निपटान","यूरोप की वन्य वनस्पतियों, जीव-जंतुओं और प्राकृतिक आवासों का संरक्षण","यूरोप में दीर्घ-दूरी सीमा-पार वायु प्रदूषण","नागरिकों के पर्यावरणीय सूचना और न्याय के अधिकार"],"explanationHi":"आरहूस नागरिकों के पर्यावरणीय अधिकारों पर UNECE की संधि है; खतरनाक अपशिष्ट बेसल कन्वेंशन और यूरोपीय वन्यजीव बर्न कन्वेंशन का विषय है।"},
  {"id":"env-ecology-494","question":"The Convention on Long-Range Transboundary Air Pollution (1979) was prompted chiefly by:","options":["The ozone hole discovered over Antarctica by British scientists","Acid rain in Scandinavia from other countries' emissions","Photochemical smog over Los Angeles","Radioactive fallout from the Chernobyl accident"],"answer":1,"explanation":"Scandinavian scientists showed that sulphur emitted elsewhere in Europe was acidifying their lakes, leading to the first legally binding treaty on air pollution. The Antarctic ozone hole (1985) and Chernobyl (1986) came after 1979.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"दीर्घ-दूरी सीमा-पार वायु प्रदूषण पर कन्वेंशन (1979) मुख्यतः किससे प्रेरित हुआ?","optionsHi":["ब्रिटिश वैज्ञानिकों द्वारा अंटार्कटिका के ऊपर खोजा गया ओज़ोन छिद्र","अन्य देशों के उत्सर्जन से स्कैंडिनेविया में अम्ल वर्षा","लॉस एंजिल्स के ऊपर प्रकाश-रासायनिक स्मॉग","चेर्नोबिल दुर्घटना से रेडियोधर्मी विकिरण पतन"],"explanationHi":"स्कैंडिनेवियाई वैज्ञानिकों ने दिखाया कि यूरोप में अन्यत्र उत्सर्जित सल्फर उनकी झीलों को अम्लीय बना रहा था, जिससे वायु प्रदूषण पर पहली विधिक रूप से बाध्यकारी संधि बनी। अंटार्कटिक ओज़ोन छिद्र (1985) और चेर्नोबिल (1986) 1979 के बाद आए।"},
  {"id":"env-ecology-495","question":"The idea of 'strong sustainability' holds that:","options":["Any loss of natural resources is acceptable if total wealth rises","Economic growth alone guarantees environmental protection","Natural capital cannot be fully replaced by human-made capital","Only renewable resources need to be conserved"],"answer":2,"explanation":"Weak sustainability lets man-made capital substitute for nature as long as total capital does not fall; strong sustainability denies that full substitution is possible.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"'प्रबल सततता (स्ट्रॉन्ग सस्टेनेबिलिटी)' का विचार मानता है कि:","optionsHi":["यदि कुल संपदा बढ़ती है तो प्राकृतिक संसाधनों की कोई भी हानि स्वीकार्य है","अकेली आर्थिक वृद्धि पर्यावरण संरक्षण की गारंटी देती है","प्राकृतिक पूँजी की पूरी तरह मानव-निर्मित पूँजी से प्रतिस्थापन नहीं हो सकती","केवल नवीकरणीय संसाधनों का ही संरक्षण आवश्यक है"],"explanationHi":"दुर्बल सततता तब तक मानव-निर्मित पूँजी को प्रकृति का स्थान लेने देती है जब तक कुल पूँजी न घटे; प्रबल सततता इस बात से इनकार करती है कि पूर्ण प्रतिस्थापन संभव है।"},
  {"id":"env-ecology-496","question":"'Green GDP' refers to:","options":["GDP net of resource depletion and environmental damage","The share of GDP spent on renewable energy and climate","GDP from agriculture, forestry and fisheries only","The GDP of countries with over a third of land under forest"],"answer":0,"explanation":"Green accounting subtracts resource depletion and degradation, so growth that eats into natural capital no longer looks as large.","difficulty":"hard","source":"UPSC Prelims","questionHi":"'ग्रीन GDP' से तात्पर्य है:","optionsHi":["संसाधन ह्रास और पर्यावरणीय क्षति घटाने के बाद का GDP","नवीकरणीय ऊर्जा और जलवायु पर व्यय किया गया GDP का हिस्सा","केवल कृषि, वानिकी और मत्स्य उद्योग से प्राप्त GDP","उन देशों का GDP जिनकी एक-तिहाई से अधिक भूमि वन के अंतर्गत है"],"explanationHi":"हरित लेखांकन संसाधन ह्रास और निम्नीकरण घटाता है, इसलिए प्राकृतिक पूँजी को खाने वाली वृद्धि अब उतनी बड़ी नहीं दिखती।"},
  {"id":"env-ecology-497","question":"Which of the following best describes a 'circular economy'?","options":["One that relies mainly on exports and imports","One where goods are made, used once and then sent to landfill","One driven only by recycling of plastics","One that designs out waste by reuse, repair and recycling"],"answer":3,"explanation":"The circular model replaces the linear take–make–dispose pattern; recycling is only one of several loops, and the higher loops such as reuse and repair save more.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा 'चक्रीय अर्थव्यवस्था' का सबसे उपयुक्त वर्णन करता है?","optionsHi":["जो मुख्यतः निर्यात और आयात पर निर्भर हो","जहाँ वस्तुएँ बनाई जाती हैं, एक बार उपयोग होती हैं और फिर भूमि भराव में भेज दी जाती हैं","जो केवल प्लास्टिक के पुनर्चक्रण से संचालित हो","जो पुनः उपयोग, मरम्मत और पुनर्चक्रण द्वारा अपशिष्ट को डिज़ाइन से ही हटा दे"],"explanationHi":"चक्रीय मॉडल रैखिक लो–बनाओ–फेंको प्रतिरूप का स्थान लेता है; पुनर्चक्रण अनेक चक्रों में से केवल एक है, और पुनः उपयोग तथा मरम्मत जैसे ऊपरी चक्र अधिक बचत करते हैं।"},
  {"id":"env-ecology-498","question":"In a food chain, producers fix 10,000 J. If the ecological efficiency between each level is 20 per cent instead of the usual 10 per cent, how much energy reaches the tertiary consumers?","options":["10 J","80 J","200 J","400 J"],"answer":1,"explanation":"10,000 × 0.2 × 0.2 × 0.2 = 80 J; 400 J is the secondary-consumer level and 10 J is what the 10 per cent rule would give.","difficulty":"hard","source":"UPSC Prelims · CDS","questionHi":"किसी खाद्य श्रृंखला में उत्पादक 10,000 J ऊर्जा स्थिर करते हैं। यदि प्रत्येक स्तर के बीच पारिस्थितिक दक्षता सामान्य 10 प्रतिशत के स्थान पर 20 प्रतिशत हो, तो तृतीयक उपभोक्ताओं तक कितनी ऊर्जा पहुँचती है?","optionsHi":["10 J","80 J","200 J","400 J"],"explanationHi":"10,000 × 0.2 × 0.2 × 0.2 = 80 J; 400 J द्वितीयक उपभोक्ता स्तर है और 10 J वह है जो 10 प्रतिशत का नियम देता।"},
  {"id":"env-ecology-499","question":"Lake water contains 0.02 ppm of a persistent pesticide. If its concentration rises tenfold at each step from water to plankton, plankton to small fish, small fish to large fish, and large fish to fish-eating birds, its concentration in the birds will be:","options":["0.2 ppm","2 ppm","20 ppm","200 ppm"],"answer":3,"explanation":"Four tenfold steps multiply by 10,000: 0.02 × 10,000 = 200 ppm. Stopping one step short gives the 20 ppm trap.","difficulty":"hard","source":"UPSC Prelims · CDS","questionHi":"झील के जल में एक स्थायी कीटनाशक की मात्रा 0.02 ppm है। यदि जल से प्लवक, प्लवक से छोटी मछली, छोटी मछली से बड़ी मछली, और बड़ी मछली से मछली खाने वाले पक्षियों तक प्रत्येक चरण में उसकी सांद्रता दस गुना बढ़ती है, तो पक्षियों में उसकी सांद्रता होगी:","optionsHi":["0.2 ppm","2 ppm","20 ppm","200 ppm"],"explanationHi":"चार दस-गुना चरण 10,000 से गुणा करते हैं: 0.02 × 10,000 = 200 ppm। एक चरण पहले रुकने पर 20 ppm का जाल मिलता है।"},
  {"id":"env-ecology-500","question":"In long-term records of predator and prey numbers, such as the lynx and snowshoe hare in Canada, the peaks in predator numbers typically:","options":["Follow the prey peaks after a time lag","Come before the peaks in prey numbers","Occur at exactly the same time as the prey peaks","Show no relation to prey numbers"],"answer":0,"explanation":"Abundant prey lets predators breed and increase, which then drives prey down and is followed by a predator decline: a lagged cycle.","difficulty":"hard","source":"UPSC Prelims","questionHi":"शिकारी और शिकार की संख्या के दीर्घकालिक अभिलेखों में, जैसे कनाडा में लिंक्स और स्नोशू खरगोश, शिकारियों की संख्या के शिखर सामान्यतः:","optionsHi":["शिकार के शिखरों के बाद, कुछ समय के अंतराल पर आते हैं","शिकार की संख्या के शिखरों से पहले आते हैं","शिकार के शिखरों के ठीक उसी समय होते हैं","शिकार की संख्या से कोई संबंध नहीं दर्शाते"],"explanationHi":"प्रचुर शिकार शिकारियों को प्रजनन और वृद्धि करने देता है, जो फिर शिकार को घटाता है और उसके बाद शिकारियों में गिरावट आती है: एक विलंबित चक्र।"},
  {"id":"env-ecology-501","question":"In a grassland, plants fix 50,000 kJ per m² per year as gross primary production and use 30,000 kJ per m² per year in their own respiration. Grazing animals eat 2,000 kJ per m² per year of plant material. What percentage of the net primary production do the grazers consume?","options":["4 per cent","10 per cent","6.7 per cent","40 per cent"],"answer":1,"explanation":"NPP = GPP − respiration = 50,000 − 30,000 = 20,000; grazers take 2,000/20,000 = 10%. Dividing by GPP gives the 4% trap, and 40% is just NPP as a share of GPP.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"एक घास के मैदान में पौधे प्रति वर्ष 50,000 kJ प्रति m² सकल प्राथमिक उत्पादन के रूप में स्थिर करते हैं और अपने श्वसन में प्रति वर्ष 30,000 kJ प्रति m² उपयोग कर लेते हैं। चरने वाले जंतु प्रति वर्ष 2,000 kJ प्रति m² पादप पदार्थ खाते हैं। चरने वाले जंतु शुद्ध प्राथमिक उत्पादन का कितना प्रतिशत उपभोग करते हैं?","optionsHi":["4 प्रतिशत","10 प्रतिशत","6.7 प्रतिशत","40 प्रतिशत"],"explanationHi":"NPP = GPP − श्वसन = 50,000 − 30,000 = 20,000; चरने वाले जंतु 2,000/20,000 = 10% लेते हैं। GPP से भाग देने पर 4% का भ्रम वाला उत्तर आता है, और 40% केवल GPP में NPP का हिस्सा है।"},
  {"id":"env-ecology-502","question":"In ecology, 'secondary productivity' is best defined as the:","options":["Rate at which green plants fix energy, minus what they lose in respiration","Total mass of living consumers present in a given area at one particular moment","Rate at which consumers form new organic matter from the food they assimilate","Rate at which decomposers release mineral nutrients from dead organic matter in soil"],"answer":2,"explanation":"Secondary productivity is the rate of formation of new organic matter by consumers (heterotrophs). The first option is net primary productivity and the second is a standing crop, which is a stock, not a rate.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"पारिस्थितिकी में 'द्वितीयक उत्पादकता' की सबसे उपयुक्त परिभाषा है:","optionsHi":["वह दर जिससे हरे पौधे ऊर्जा स्थिर करते हैं, श्वसन में हुई हानि घटाकर","किसी निश्चित क्षेत्र में किसी विशेष क्षण पर उपस्थित जीवित उपभोक्ताओं का कुल द्रव्यमान","वह दर जिससे उपभोक्ता अपने द्वारा अवशोषित भोजन से नया कार्बनिक पदार्थ बनाते हैं","वह दर जिससे अपघटक मृदा में मृत कार्बनिक पदार्थ से खनिज पोषक तत्व मुक्त करते हैं"],"explanationHi":"द्वितीयक उत्पादकता उपभोक्ताओं (विषमपोषियों) द्वारा नया कार्बनिक पदार्थ बनने की दर है। पहला विकल्प शुद्ध प्राथमिक उत्पादकता है और दूसरा खड़ी फसल (स्टैंडिंग क्रॉप) है, जो एक भंडार है, दर नहीं।"},
  {"id":"env-ecology-503","question":"A lake's phytoplankton has a standing biomass of 10 g per m², while its net primary productivity is 500 g per m² per year. On average, about how long does it take for this standing biomass to be replaced?","options":["About 50 days","About 7 days","About 20 days","About 0.02 days"],"answer":1,"explanation":"Turnover time = biomass ÷ productivity = 10/500 = 0.02 year ≈ 7.3 days. This rapid turnover is why a small phytoplankton stock can support a much larger biomass of consumers.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"एक झील के फाइटोप्लैंकटन का खड़ा जैवभार 10 g प्रति m² है, जबकि उसकी शुद्ध प्राथमिक उत्पादकता 500 g प्रति m² प्रति वर्ष है। औसतन इस खड़े जैवभार को बदलने में लगभग कितना समय लगता है?","optionsHi":["लगभग 50 दिन","लगभग 7 दिन","लगभग 20 दिन","लगभग 0.02 दिन"],"explanationHi":"आवर्तन काल = जैवभार ÷ उत्पादकता = 10/500 = 0.02 वर्ष ≈ 7.3 दिन। यही तीव्र आवर्तन कारण है कि फाइटोप्लैंकटन का छोटा भंडार उपभोक्ताओं के कहीं बड़े जैवभार को पोषित कर सकता है।"},
  {"id":"env-ecology-504","question":"Consider the following statements: 1. In a mature terrestrial forest, the larger part of net primary production passes through the detritus food chain rather than the grazing food chain. 2. In the open ocean, the grazing food chain carries a larger share of the energy flow than it does in a forest. 3. The detritus food chain does not depend on solar energy, since it begins with dead organic matter. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Most forest NPP is never eaten alive and enters the detritus pathway, while ocean phytoplankton are grazed heavily. Statement 3 is wrong: dead organic matter itself came from photosynthesis, so the detritus chain also rests on solar energy.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. एक परिपक्व स्थलीय वन में शुद्ध प्राथमिक उत्पादन का बड़ा भाग चारण खाद्य श्रृंखला के बजाय अपरद खाद्य श्रृंखला से होकर गुजरता है। 2. खुले महासागर में चारण खाद्य श्रृंखला, वन की तुलना में ऊर्जा प्रवाह का बड़ा हिस्सा वहन करती है। 3. अपरद खाद्य श्रृंखला सौर ऊर्जा पर निर्भर नहीं करती, क्योंकि यह मृत कार्बनिक पदार्थ से शुरू होती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"वनों का अधिकांश NPP जीवित अवस्था में खाया नहीं जाता और अपरद मार्ग में चला जाता है, जबकि महासागर के फाइटोप्लैंकटन को बड़े पैमाने पर चरा जाता है। कथन 3 गलत है: मृत कार्बनिक पदार्थ स्वयं प्रकाश संश्लेषण से बना था, इसलिए अपरद श्रृंखला भी सौर ऊर्जा पर आधारित है।"},
  {"id":"env-ecology-505","question":"In a light-and-dark bottle experiment, pond water starts with 8 mg/L of dissolved oxygen. After some hours, the light bottle holds 11 mg/L and the dark bottle 5 mg/L. What are the net and gross primary production, expressed as oxygen?","options":["Net 6 mg/L; gross 3 mg/L","Net 3 mg/L; gross 3 mg/L","Net 6 mg/L; gross 11 mg/L","Net 3 mg/L; gross 6 mg/L"],"answer":3,"explanation":"Net = light − initial = 11 − 8 = 3; respiration = initial − dark = 8 − 5 = 3; gross = net + respiration = light − dark = 6 mg/L.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"प्रकाश-और-अंधकार बोतल प्रयोग में तालाब के पानी में आरंभ में 8 mg/L घुलित ऑक्सीजन है। कुछ घंटों बाद प्रकाश वाली बोतल में 11 mg/L और अंधकार वाली बोतल में 5 mg/L है। ऑक्सीजन के रूप में व्यक्त करने पर शुद्ध और सकल प्राथमिक उत्पादन क्या हैं?","optionsHi":["शुद्ध 6 mg/L; सकल 3 mg/L","शुद्ध 3 mg/L; सकल 3 mg/L","शुद्ध 6 mg/L; सकल 11 mg/L","शुद्ध 3 mg/L; सकल 6 mg/L"],"explanationHi":"शुद्ध = प्रकाश − प्रारंभिक = 11 − 8 = 3; श्वसन = प्रारंभिक − अंधकार = 8 − 5 = 3; सकल = शुद्ध + श्वसन = प्रकाश − अंधकार = 6 mg/L।"},
  {"id":"env-ecology-506","question":"A house sparrow eats grain and also eats caterpillars that feed on the same grain crop. In this system the sparrow occupies:","options":["The second trophic level only","The second and third trophic levels","The third trophic level only","The first and second trophic levels"],"answer":1,"explanation":"Eating grain makes it a primary consumer (level 2); eating herbivorous caterpillars makes it a secondary consumer (level 3). Omnivores routinely occupy more than one trophic level, which is why real systems form webs, not chains.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"एक गौरैया अनाज खाती है और उन इल्लियों को भी खाती है जो उसी अनाज की फसल को खाती हैं। इस तंत्र में गौरैया किस स्तर पर है?","optionsHi":["केवल दूसरे पोषी स्तर पर","दूसरे और तीसरे पोषी स्तर पर","केवल तीसरे पोषी स्तर पर","पहले और दूसरे पोषी स्तर पर"],"explanationHi":"अनाज खाने से यह प्राथमिक उपभोक्ता (स्तर 2) है; शाकाहारी इल्लियों को खाने से यह द्वितीयक उपभोक्ता (स्तर 3) है। सर्वाहारी प्रायः एक से अधिक पोषी स्तर पर होते हैं, इसीलिए वास्तविक तंत्र श्रृंखला के बजाय जाल बनाते हैं।"},
  {"id":"env-ecology-507","question":"How many of the following statements about the capture of solar energy are correct? I. Photosynthetically active radiation (PAR) makes up less than half of the solar radiation falling on the Earth. II. PAR lies roughly in the 400–700 nm range of wavelengths. III. Plants capture only about 2–10 per cent of the PAR they receive. IV. Leaves absorb green light most strongly, which is why they look green.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are standard figures. IV reverses the truth: chlorophyll absorbs blue and red light strongly and reflects much of the green, which is why leaves look green.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सौर ऊर्जा के ग्रहण के संबंध में निम्नलिखित में से कितने कथन सही हैं? I. प्रकाश संश्लेषणीय सक्रिय विकिरण (PAR) पृथ्वी पर पड़ने वाले सौर विकिरण के आधे से कम होता है। II. PAR लगभग 400–700 nm तरंगदैर्ध्य के बीच होता है। III. पौधे प्राप्त PAR का केवल लगभग 2–10 प्रतिशत ही ग्रहण करते हैं। IV. पत्तियाँ हरे प्रकाश को सबसे अधिक अवशोषित करती हैं, इसीलिए वे हरी दिखती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III मानक आँकड़े हैं। IV सच्चाई का उलटा है: क्लोरोफिल नीले और लाल प्रकाश को अधिक अवशोषित करता है और हरे प्रकाश का बड़ा भाग परावर्तित करता है, इसीलिए पत्तियाँ हरी दिखती हैं।"},
  {"id":"env-ecology-508","question":"During decomposition, water-soluble inorganic nutrients move down into the soil horizon and get precipitated as unavailable salts. This step is called:","options":["Leaching","Catabolism","Humification","Mineralisation"],"answer":0,"explanation":"Leaching is the downward movement of soluble nutrients. Catabolism is the enzymatic breakdown of detritus, humification forms humus, and mineralisation releases inorganic nutrients from humus.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"अपघटन के दौरान जल में घुलनशील अकार्बनिक पोषक तत्व मृदा संस्तर में नीचे चले जाते हैं और अनुपलब्ध लवणों के रूप में अवक्षेपित हो जाते हैं। इस चरण को क्या कहते हैं?","optionsHi":["निक्षालन (लीचिंग)","अपचय","ह्यूमस निर्माण","खनिजीकरण"],"explanationHi":"निक्षालन घुलनशील पोषक तत्वों का नीचे की ओर बहना है। अपचय अपरद का एंजाइमी विघटन है, ह्यूमस निर्माण से ह्यूमस बनता है, और खनिजीकरण में ह्यूमस से अकार्बनिक पोषक तत्व मुक्त होते हैं।"},
  {"id":"env-ecology-509","question":"Which of the following would speed up the decomposition of leaf litter? 1. A higher content of lignin and chitin 2. A higher content of nitrogen and water-soluble sugars 3. Warm, moist and well-aerated conditions 4. A higher carbon-to-nitrogen ratio in the litter. Select the correct answer:","options":["1 and 3 only","2 and 4 only","1, 3 and 4 only","2 and 3 only"],"answer":3,"explanation":"Nitrogen-rich, sugar-rich litter in warm, moist, aerated soil breaks down fastest. Lignin and chitin resist microbial attack, and a high C:N ratio starves decomposers of nitrogen, both slowing decay.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-से पत्ती अवकर्कट (लीफ लिटर) के अपघटन को तेज़ करेंगे? 1. लिग्निन और काइटिन की अधिक मात्रा 2. नाइट्रोजन और जल में घुलनशील शर्कराओं की अधिक मात्रा 3. गर्म, नम और अच्छी तरह हवादार परिस्थितियाँ 4. अवकर्कट में कार्बन-नाइट्रोजन अनुपात का अधिक होना। सही उत्तर चुनिए:","optionsHi":["केवल 1 और 3","केवल 2 और 4","केवल 1, 3 और 4","केवल 2 और 3"],"explanationHi":"गर्म, नम, हवादार मृदा में नाइट्रोजन-समृद्ध और शर्करा-समृद्ध अवकर्कट सबसे तेज़ी से सड़ता है। लिग्निन और काइटिन सूक्ष्मजीवी आक्रमण का प्रतिरोध करते हैं, और उच्च C:N अनुपात अपघटकों को नाइट्रोजन से वंचित कर देता है; दोनों अपघटन को धीमा करते हैं।"},
  {"id":"env-ecology-510","question":"In 1997, Robert Costanza and colleagues tried to put a price on the world's ecosystem services. Their estimate of the average annual value of these services was roughly:","options":["US$ 3.3 trillion, about a fifth of global GNP then","US$ 18 trillion, about equal to global GNP then","US$ 33 trillion, nearly double global GNP then","US$ 330 trillion, about twenty times global GNP then"],"answer":2,"explanation":"Costanza et al. estimated about US$33 trillion a year, close to twice the global GNP of about US$18 trillion at the time, showing that nature's services are enormous though unpriced.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"1997 में रॉबर्ट कॉन्स्टैंज़ा और उनके सहयोगियों ने विश्व की पारिस्थितिकी तंत्र सेवाओं का मूल्य आँकने का प्रयास किया। इन सेवाओं के औसत वार्षिक मूल्य का उनका अनुमान लगभग था:","optionsHi":["US$ 3.3 ट्रिलियन, तत्कालीन वैश्विक GNP का लगभग पाँचवाँ भाग","US$ 18 ट्रिलियन, तत्कालीन वैश्विक GNP के लगभग बराबर","US$ 33 ट्रिलियन, तत्कालीन वैश्विक GNP का लगभग दोगुना","US$ 330 ट्रिलियन, तत्कालीन वैश्विक GNP का लगभग बीस गुना"],"explanationHi":"कॉन्स्टैंज़ा और अन्य ने लगभग US$33 ट्रिलियन प्रति वर्ष का अनुमान लगाया, जो उस समय के लगभग US$18 ट्रिलियन वैश्विक GNP का लगभग दोगुना है; इससे पता चलता है कि प्रकृति की सेवाएँ विशाल हैं, पर उनका कोई मूल्य नहीं लगाया जाता।"},
  {"id":"env-ecology-511","question":"When Paramecium aurelia and Paramecium caudatum were grown together in the same culture with limited food, P. caudatum died out, though each species thrived when grown alone. This result led to the formulation of:","options":["The principle of resource partitioning","The principle of character displacement","The Allee principle of undercrowding","The competitive exclusion principle"],"answer":3,"explanation":"G. F. Gause's experiments showed that two species competing for the same limiting resource cannot coexist indefinitely; the inferior competitor is eliminated. Partitioning and displacement are ways species escape this outcome.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जब सीमित भोजन वाले एक ही संवर्धन में पैरामीशियम ऑरीलिया और पैरामीशियम कॉडेटम को साथ उगाया गया, तो P. caudatum समाप्त हो गया, जबकि अकेले उगाने पर दोनों प्रजातियाँ फलती-फूलती रहीं। इस परिणाम से किस सिद्धांत का निरूपण हुआ?","optionsHi":["संसाधन विभाजन का सिद्धांत","लक्षण विस्थापन का सिद्धांत","अल्प-भीड़ का एली सिद्धांत","प्रतिस्पर्धी अपवर्जन सिद्धांत"],"explanationHi":"जी. एफ. गॉज़ के प्रयोगों ने दिखाया कि एक ही सीमित संसाधन के लिए प्रतिस्पर्धा करने वाली दो प्रजातियाँ अनिश्चित काल तक साथ नहीं रह सकतीं; कमज़ोर प्रतिस्पर्धी समाप्त हो जाता है। विभाजन और विस्थापन वे तरीके हैं जिनसे प्रजातियाँ इस परिणाम से बच जाती हैं।"},
  {"id":"env-ecology-512","question":"Robert MacArthur found that five closely related species of warbler lived on the same spruce trees without one excluding the others, because each fed mostly in a different part of the canopy. This is an example of:","options":["Interspecific facilitation","Competitive release","Interference competition","Resource partitioning"],"answer":3,"explanation":"By foraging in different zones and in different ways, the warblers divided the shared resource, which reduces competition and lets similar species coexist. Competitive release is the expansion of a niche after a competitor disappears.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"रॉबर्ट मैकआर्थर ने पाया कि वार्बलर की पाँच निकट संबंधी प्रजातियाँ एक ही स्प्रूस वृक्षों पर बिना एक-दूसरे को हटाए रहती थीं, क्योंकि प्रत्येक मुख्यतः वितान के अलग-अलग भाग में भोजन करती थी। यह किसका उदाहरण है?","optionsHi":["अंतरजातीय सुगमता","प्रतिस्पर्धा से मुक्ति","हस्तक्षेप प्रतिस्पर्धा","संसाधन विभाजन"],"explanationHi":"अलग-अलग क्षेत्रों में और अलग-अलग ढंग से भोजन खोजकर वार्बलर ने साझा संसाधन को बाँट लिया, जिससे प्रतिस्पर्धा घटती है और समान प्रजातियाँ सह-अस्तित्व में रह पाती हैं। प्रतिस्पर्धा से मुक्ति का अर्थ है किसी प्रतिस्पर्धी के हट जाने पर निकेत का विस्तार।"},
  {"id":"env-ecology-513","question":"'Each organism has a minimum and a maximum limit for every environmental factor, and excess of a factor can limit it just as much as deficiency.' This idea is associated with:","options":["Shelford's law of tolerance","Liebig's law of the minimum","Blackman's law of limiting factors","Gause's principle of exclusion"],"answer":0,"explanation":"Victor Shelford extended Liebig's idea: both too little and too much of a factor can limit an organism, so each species has a range of tolerance. Liebig considered only the scarcest nutrient.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'प्रत्येक जीव की प्रत्येक पर्यावरणीय कारक के लिए एक न्यूनतम और एक अधिकतम सीमा होती है, और किसी कारक की अधिकता भी उसे उतना ही सीमित कर सकती है जितना कमी।' यह विचार किससे जुड़ा है?","optionsHi":["शेल्फ़र्ड का सहनशीलता नियम","लीबिग का न्यूनतम का नियम","ब्लैकमैन का सीमाकारी कारकों का नियम","गॉज़ का अपवर्जन सिद्धांत"],"explanationHi":"विक्टर शेल्फ़र्ड ने लीबिग के विचार का विस्तार किया: किसी कारक की कमी और अधिकता दोनों जीव को सीमित कर सकती हैं, इसलिए प्रत्येक प्रजाति की सहनशीलता की एक सीमा होती है। लीबिग ने केवल सबसे दुर्लभ पोषक तत्व को माना था।"},
  {"id":"env-ecology-514","question":"How many of the following pairs of response and example are correctly matched? 1. Hibernation — some snails and fish during summer 2. Aestivation — bears during winter 3. Diapause — zooplankton in lakes under unfavourable conditions 4. Diapause — bacteria forming thick-walled spores","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only pair 3 is correct: zooplankton enter diapause. Bears hibernate in winter and some snails and fish aestivate in summer, so 1 and 2 are swapped. Bacterial spore formation is not diapause.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अनुक्रिया और उदाहरण के निम्नलिखित जोड़ों में से कितने सही सुमेलित हैं? 1. शीतनिष्क्रियता (हाइबरनेशन) — गर्मियों में कुछ घोंघे और मछलियाँ 2. ग्रीष्मनिष्क्रियता (एस्टिवेशन) — सर्दियों में भालू 3. डायपॉज़ — प्रतिकूल परिस्थितियों में झीलों के प्राणिप्लवक (ज़ूप्लैंकटन) 4. डायपॉज़ — मोटी भित्ति वाले बीजाणु बनाने वाले जीवाणु","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल जोड़ा 3 सही है: ज़ूप्लैंकटन डायपॉज़ में जाते हैं। भालू सर्दियों में शीतनिष्क्रियता करते हैं और कुछ घोंघे और मछलियाँ गर्मियों में ग्रीष्मनिष्क्रियता करती हैं, इसलिए 1 और 2 आपस में बदले हुए हैं। जीवाणुओं द्वारा बीजाणु बनाना डायपॉज़ नहीं है।"},
  {"id":"env-ecology-515","question":"Robert Whittaker's classic diagram showing where the world's major biomes occur plots them against which two variables?","options":["Mean annual temperature and mean annual precipitation","Latitude and altitude above sea level","Soil fertility and the length of the frost-free growing season","Mean annual temperature and soil pH"],"answer":0,"explanation":"Whittaker showed that biomes are arranged mainly by annual temperature and rainfall. Latitude and altitude matter only through their effect on those two climate variables.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"विश्व के प्रमुख बायोम कहाँ पाए जाते हैं, यह दर्शाने वाला रॉबर्ट व्हिटेकर का प्रसिद्ध आरेख बायोम को किन दो चरों के विरुद्ध आलेखित करता है?","optionsHi":["औसत वार्षिक तापमान और औसत वार्षिक वर्षा","अक्षांश और समुद्र तल से ऊँचाई","मृदा उर्वरता और पाला-रहित वृद्धि ऋतु की अवधि","औसत वार्षिक तापमान और मृदा pH"],"explanationHi":"व्हिटेकर ने दिखाया कि बायोम मुख्यतः वार्षिक तापमान और वर्षा के अनुसार व्यवस्थित होते हैं। अक्षांश और ऊँचाई केवल इन्हीं दो जलवायु चरों पर अपने प्रभाव के कारण महत्त्वपूर्ण हैं।"},
  {"id":"env-ecology-516","question":"Assertion (A): Food chains in nature rarely have more than four or five trophic levels. Reason (R): Only a small fraction of the energy at one trophic level is passed on to the next, so too little remains to support a viable population at very high levels. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because roughly 90% of energy is lost at each transfer, energy available after four or five steps is too small to sustain another level of consumers. R directly explains A.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): प्रकृति में खाद्य श्रृंखलाओं में प्रायः चार या पाँच से अधिक पोषी स्तर नहीं होते। कारण (R): एक पोषी स्तर की ऊर्जा का केवल एक छोटा अंश अगले स्तर को जाता है, इसलिए बहुत ऊँचे स्तरों पर किसी जीवनक्षम समष्टि को पोषित करने के लिए बहुत कम ऊर्जा बचती है। सही विकल्प चुनिए:","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"प्रत्येक स्थानांतरण में लगभग 90% ऊर्जा नष्ट हो जाती है, इसलिए चार या पाँच चरणों के बाद उपलब्ध ऊर्जा उपभोक्ताओं के अगले स्तर को पोषित करने के लिए बहुत कम रह जाती है। R सीधे A की व्याख्या करता है।"},
  {"id":"env-ecology-517","question":"Which one of the following is a structural rather than a functional aspect of an ecosystem?","options":["Decomposition of detritus","Nutrient cycling","Energy flow","Vertical stratification"],"answer":3,"explanation":"Stratification, the vertical layering of species, describes how an ecosystem is built. Productivity, decomposition, energy flow and nutrient cycling are its functional aspects.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सा पारिस्थितिकी तंत्र का कार्यात्मक नहीं, बल्कि संरचनात्मक पहलू है?","optionsHi":["अपरद का अपघटन","पोषक तत्व चक्रण","ऊर्जा प्रवाह","ऊर्ध्वाधर स्तरीकरण"],"explanationHi":"स्तरीकरण, यानी प्रजातियों की ऊर्ध्वाधर परतें, बताता है कि पारिस्थितिकी तंत्र कैसे गठित है। उत्पादकता, अपघटन, ऊर्जा प्रवाह और पोषक तत्व चक्रण इसके कार्यात्मक पहलू हैं।"},
  {"id":"env-ecology-518","question":"In large parts of the Southern Ocean, surface water has plenty of nitrate and phosphate, yet phytoplankton remain sparse. The nutrient generally found to limit their growth in these waters is:","options":["Iron","Silicon","Nitrogen","Phosphorus"],"answer":0,"explanation":"These are 'high-nutrient, low-chlorophyll' waters, far from dust sources, where iron is the limiting micronutrient; iron-fertilisation experiments trigger blooms there. Nitrogen and phosphorus are already abundant.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"दक्षिणी महासागर के बड़े भागों में सतही जल में नाइट्रेट और फॉस्फेट प्रचुर हैं, फिर भी फाइटोप्लैंकटन विरल हैं। इन जलों में उनकी वृद्धि को सामान्यतः सीमित करने वाला पोषक तत्व है:","optionsHi":["आयरन (लोहा)","सिलिकॉन","नाइट्रोजन","फॉस्फोरस"],"explanationHi":"ये 'उच्च-पोषक, निम्न-क्लोरोफिल' जल हैं, जो धूल के स्रोतों से दूर हैं, जहाँ आयरन सीमाकारी सूक्ष्म पोषक तत्व है; आयरन-निषेचन प्रयोग वहाँ शैवाल प्रस्फुटन उत्पन्न करते हैं। नाइट्रोजन और फॉस्फोरस पहले से प्रचुर हैं।"},
  {"id":"env-ecology-519","question":"In a food web, grass is eaten by grasshoppers, mice and rabbits; frogs eat grasshoppers; snakes eat frogs and mice; hawks eat rabbits and snakes. At which trophic levels does the hawk feed?","options":["Third and fourth only","Fourth, fifth and sixth","Third, fourth and fifth","Third and fifth only"],"answer":2,"explanation":"Grass→rabbit→hawk puts it at level 3; grass→mouse→snake→hawk at level 4; grass→grasshopper→frog→snake→hawk at level 5. The snake itself sits at levels 3 and 4.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"एक खाद्य जाल में घास को टिड्डे, चूहे और खरगोश खाते हैं; मेंढक टिड्डों को खाते हैं; साँप मेंढकों और चूहों को खाते हैं; बाज खरगोशों और साँपों को खाते हैं। बाज किन पोषी स्तरों पर भोजन करता है?","optionsHi":["केवल तीसरे और चौथे","चौथे, पाँचवें और छठे","तीसरे, चौथे और पाँचवें","केवल तीसरे और पाँचवें"],"explanationHi":"घास→खरगोश→बाज इसे स्तर 3 पर रखता है; घास→चूहा→साँप→बाज स्तर 4 पर; घास→टिड्डा→मेंढक→साँप→बाज स्तर 5 पर। साँप स्वयं स्तर 3 और 4 पर है।"},
  {"id":"env-ecology-520","question":"Insects typically turn a larger fraction of the energy they assimilate into new body tissue than cattle or deer do. The main reason is that:","options":["Insects assimilate a much smaller share of their food than mammals manage to do","Cattle and deer eat food that is poorer in nitrogen than insects eat","Insects need fewer trophic steps to obtain their energy from plants","Mammals spend much assimilated energy keeping their body warm"],"answer":3,"explanation":"Endotherms burn a large share of assimilated energy in respiration to stay warm, so their production efficiency is only a few per cent, against roughly ten times that in many ectotherms such as insects.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"कीट सामान्यतः अपने द्वारा अवशोषित ऊर्जा का अधिक बड़ा भाग नए शरीर ऊतक में बदलते हैं, गाय-बैल या हिरण की तुलना में। इसका मुख्य कारण यह है कि:","optionsHi":["कीट अपने भोजन का बहुत छोटा भाग ही अवशोषित कर पाते हैं, जबकि स्तनधारी कहीं अधिक कर लेते हैं","गाय-बैल और हिरण जो भोजन खाते हैं उसमें कीटों के भोजन की तुलना में नाइट्रोजन कम होती है","कीटों को पादपों से ऊर्जा पाने के लिए कम पोषी चरण चाहिए","स्तनधारी अवशोषित ऊर्जा का बड़ा भाग शरीर को गर्म रखने में खर्च करते हैं"],"explanationHi":"समतापी जंतु शरीर को गर्म रखने के लिए अवशोषित ऊर्जा का बड़ा भाग श्वसन में जला देते हैं, इसलिए उनकी उत्पादन दक्षता केवल कुछ प्रतिशत होती है, जबकि कीट जैसे अनेक असमतापी जंतुओं में यह लगभग दस गुना होती है।"},
  {"id":"env-ecology-521","question":"How many of the following pairs are correctly matched? 1. Lentic — ponds and lakes 2. Lotic — rivers and streams 3. Nekton — tiny organisms drifting with water currents 4. Benthos — organisms living on or in the bottom sediments","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Lentic means still water and lotic flowing water; benthos live on the bottom. Nekton are active swimmers such as fish; drifting organisms are plankton.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कितने जोड़े सही सुमेलित हैं? 1. स्थिर जलीय (लेंटिक) — तालाब और झीलें 2. प्रवाही जलीय (लोटिक) — नदियाँ और धाराएँ 3. नेक्टन — जल धाराओं के साथ बहने वाले सूक्ष्म जीव 4. बेन्थोस — तलछट के तल पर या उसके भीतर रहने वाले जीव","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"लेंटिक का अर्थ स्थिर जल और लोटिक का प्रवाही जल है; बेन्थोस तल पर रहते हैं। नेक्टन मछली जैसे सक्रिय तैराक हैं; बहने वाले जीव प्लवक (प्लैंकटन) हैं।"},
  {"id":"env-ecology-522","question":"Birds and mammals living in warm, humid regions tend to be more darkly pigmented than related forms in cool, dry regions. This generalisation is known as:","options":["Bergmann's rule","Gloger's rule","Allen's rule","Jordan's rule"],"answer":1,"explanation":"Gloger's rule links darker pigmentation with warm, humid climates. Bergmann's rule concerns larger body size in colder climates, and Allen's rule shorter extremities in colder climates.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"गर्म, आर्द्र क्षेत्रों में रहने वाले पक्षी और स्तनधारी ठंडे, शुष्क क्षेत्रों के संबंधित रूपों की तुलना में अधिक गहरे रंग के होते हैं। यह सामान्यीकरण किस नाम से जाना जाता है?","optionsHi":["बर्गमैन का नियम","ग्लोगर का नियम","ऐलन का नियम","जॉर्डन का नियम"],"explanationHi":"ग्लोगर का नियम गहरे रंजकता को गर्म, आर्द्र जलवायु से जोड़ता है। बर्गमैन का नियम ठंडी जलवायु में बड़े शरीर के आकार से और ऐलन का नियम ठंडी जलवायु में छोटे उपांगों से संबंधित है।"},
  {"id":"env-ecology-523","question":"The idea of the ecological niche as an 'n-dimensional hypervolume', in which each axis is an environmental condition or resource, was proposed by:","options":["Charles S. Elton","Joseph Grinnell","Eugene P. Odum","G. E. Hutchinson"],"answer":3,"explanation":"Hutchinson (1957) defined the niche as an n-dimensional hypervolume and distinguished fundamental from realised niches. Grinnell stressed the habitat niche and Elton the functional role of a species in its community.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"पारिस्थितिक निकेत को 'n-आयामी अतिआयतन' मानने का विचार, जिसमें प्रत्येक अक्ष एक पर्यावरणीय स्थिति या संसाधन है, किसने प्रस्तावित किया?","optionsHi":["चार्ल्स एस. एल्टन","जोसेफ ग्रिनेल","यूजीन पी. ओडम","जी. ई. हचिंसन"],"explanationHi":"हचिंसन (1957) ने निकेत को n-आयामी अतिआयतन के रूप में परिभाषित किया और मूलभूत तथा वास्तविकृत निकेत में अंतर किया। ग्रिनेल ने आवासीय निकेत पर और एल्टन ने समुदाय में प्रजाति की कार्यात्मक भूमिका पर बल दिया।"},
  {"id":"env-ecology-524","question":"The term 'ecosystem' was coined in 1935 by:","options":["Ernst Haeckel","Arthur Tansley","Raymond Lindeman","Eugene Odum"],"answer":1,"explanation":"Arthur Tansley introduced 'ecosystem' in 1935. Haeckel coined 'ecology' (1866), Lindeman worked on trophic energy transfer and Odum popularised ecosystem ecology later.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"'पारिस्थितिकी तंत्र' शब्द 1935 में किसने गढ़ा?","optionsHi":["अर्नस्ट हैकेल","आर्थर टैन्सले","रेमंड लिंडमैन","यूजीन ओडम"],"explanationHi":"आर्थर टैन्सले ने 1935 में 'पारिस्थितिकी तंत्र' शब्द प्रस्तुत किया। हैकेल ने 'पारिस्थितिकी' (ecology, 1866) शब्द गढ़ा, लिंडमैन ने पोषी ऊर्जा स्थानांतरण पर कार्य किया और ओडम ने बाद में पारिस्थितिकी तंत्र पारिस्थितिकी को लोकप्रिय बनाया।"},
  {"id":"env-ecology-525","question":"Biomass in ecological pyramids is usually expressed as dry weight rather than fresh weight mainly because:","options":["Water content varies greatly between organisms and seasons and supplies no energy","Dry weight is always larger than fresh weight and so is easier to read accurately on a balance","Fresh weight cannot be measured at all for microscopic organisms such as phytoplankton","Dry weight includes the energy lost in respiration while fresh weight does not"],"answer":0,"explanation":"Removing water gives a comparable measure of organic matter, since the proportion of water differs widely and has no calorific value. Dry weight is of course smaller than fresh weight.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पारिस्थितिक पिरामिडों में जैवभार को सामान्यतः ताज़े भार के बजाय शुष्क भार के रूप में व्यक्त किया जाता है, मुख्यतः क्योंकि:","optionsHi":["जीवों और ऋतुओं के बीच जल की मात्रा बहुत भिन्न होती है और वह कोई ऊर्जा नहीं देता","शुष्क भार सदैव ताज़े भार से अधिक होता है, इसलिए तराजू पर उसे सटीक पढ़ना आसान होता है","फाइटोप्लैंकटन जैसे सूक्ष्म जीवों के लिए ताज़ा भार मापा ही नहीं जा सकता","शुष्क भार में श्वसन में नष्ट हुई ऊर्जा शामिल होती है, जबकि ताज़े भार में नहीं"],"explanationHi":"जल हटाने से कार्बनिक पदार्थ का तुलनीय माप मिलता है, क्योंकि जल का अनुपात बहुत भिन्न होता है और उसका कोई ऊष्मीय मान नहीं होता। शुष्क भार, निश्चय ही, ताज़े भार से कम होता है।"},
  {"id":"env-ecology-526","question":"India's National Air Quality Index, launched in 2014, computes sub-indices for eight pollutants. Consider the following: 1. Ammonia 2. Benzene 3. Lead 4. Carbon dioxide 5. Ozone. How many of these are among those eight pollutants?","options":["Only two","Only three","Only four","All five"],"answer":1,"explanation":"The eight AQI pollutants are PM10, PM2.5, NO2, SO2, CO, O3, NH3 and Pb, so ammonia, lead and ozone count. Benzene is in the 2009 ambient standards but not in the AQI, and CO2 is not a criteria pollutant at all.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2014 में शुरू किया गया भारत का राष्ट्रीय वायु गुणवत्ता सूचकांक आठ प्रदूषकों के उप-सूचकांकों की गणना करता है। निम्नलिखित पर विचार कीजिए: 1. अमोनिया 2. बेंज़ीन 3. सीसा 4. कार्बन डाइऑक्साइड 5. ओज़ोन। इनमें से कितने उन आठ प्रदूषकों में शामिल हैं?","optionsHi":["केवल दो","केवल तीन","केवल चार","सभी पाँच"],"explanationHi":"AQI के आठ प्रदूषक PM10, PM2.5, NO2, SO2, CO, O3, NH3 और Pb हैं, इसलिए अमोनिया, सीसा और ओज़ोन गिने जाते हैं। बेंज़ीन 2009 के परिवेशी मानकों में है, पर AQI में नहीं, और CO2 कसौटी प्रदूषक है ही नहीं।"},
  {"id":"env-ecology-527","question":"Consider the following statements: 1. The Commission for Air Quality Management in the National Capital Region and Adjoining Areas is a statutory body set up under an Act of Parliament of 2021. 2. The Environment Pollution (Prevention and Control) Authority that it replaced had been constituted under the Air (Prevention and Control of Pollution) Act, 1981. 3. The Graded Response Action Plan for Delhi-NCR is now implemented by this Commission. Which of the statements given above are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"CAQM was created by the CAQM in NCR and Adjoining Areas Act, 2021 and now runs GRAP. The EPCA it replaced (1998) was set up under Section 3 of the Environment (Protection) Act, 1986 on Supreme Court directions, not under the Air Act.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. राष्ट्रीय राजधानी क्षेत्र और आसपास के क्षेत्रों में वायु गुणवत्ता प्रबंधन आयोग 2021 के संसद के एक अधिनियम के अंतर्गत स्थापित एक सांविधिक निकाय है। 2. पर्यावरण प्रदूषण (निवारण और नियंत्रण) प्राधिकरण, जिसकी जगह इसने ली, वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1981 के अंतर्गत गठित था। 3. दिल्ली-NCR के लिए ग्रेडेड रिस्पॉन्स एक्शन प्लान अब इसी आयोग द्वारा लागू किया जाता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"CAQM का गठन राष्ट्रीय राजधानी क्षेत्र और आसपास के क्षेत्रों में वायु गुणवत्ता प्रबंधन आयोग अधिनियम, 2021 द्वारा हुआ और अब वही GRAP चलाता है। जिस EPCA (1998) की जगह इसने ली, वह उच्चतम न्यायालय के निर्देशों पर पर्यावरण (संरक्षण) अधिनियम, 1986 की धारा 3 के अंतर्गत बना था, वायु अधिनियम के अंतर्गत नहीं।"},
  {"id":"env-ecology-528","question":"A factory must cut its emissions of fine particles (PM2.5) from flue gas. Which of the following control devices would be the LEAST effective for this purpose?","options":["Fabric (bag-house) filter","Electrostatic precipitator","Cyclone separator","Venturi wet scrubber"],"answer":2,"explanation":"A cyclone uses centrifugal force, which works well only for coarse particles (above roughly 10 µm); fine particles follow the gas stream out. Bag filters and ESPs capture fine dust at efficiencies of 99 per cent or more, and venturi scrubbers also handle fine particles.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"एक कारखाने को अपने ग्रिप गैस से महीन कणों (PM2.5) का उत्सर्जन घटाना है। इस उद्देश्य के लिए निम्नलिखित में से कौन-सी नियंत्रण युक्ति सबसे कम प्रभावी होगी?","optionsHi":["कपड़े का (बैग-हाउस) फ़िल्टर","स्थिर-वैद्युत अवक्षेपित्र (इलेक्ट्रोस्टैटिक प्रेसिपिटेटर)","साइक्लोन पृथक्कारक","वेंचुरी आर्द्र स्क्रबर"],"explanationHi":"साइक्लोन अपकेंद्री बल का उपयोग करता है, जो केवल मोटे कणों (लगभग 10 µm से ऊपर) के लिए अच्छा काम करता है; महीन कण गैस धारा के साथ बाहर निकल जाते हैं। बैग फ़िल्टर और ESP महीन धूल को 99 प्रतिशत या उससे अधिक दक्षता से पकड़ते हैं, और वेंचुरी स्क्रबर भी महीन कणों को संभालते हैं।"},
  {"id":"env-ecology-529","question":"Which of the following correctly describes the relationship between PM10 and PM2.5?","options":["PM2.5 is a subset of PM10, as any particle under 2.5 µm is also under 10 µm","PM10 and PM2.5 are two separate size classes, so a particle can belong to only one of them","PM2.5 refers to all particles of 2.5 µm or larger, so it includes the whole of PM10","PM10 particles are about ten times heavier than PM2.5 particles of the same diameter"],"answer":0,"explanation":"PM10 covers all inhalable particles of aerodynamic diameter up to 10 µm, which includes the fine fraction under 2.5 µm. That is why PM10 readings are always at least as high as PM2.5 readings at the same place and time.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"PM10 और PM2.5 के बीच संबंध का सही वर्णन निम्नलिखित में से कौन-सा है?","optionsHi":["PM2.5, PM10 का एक उपसमुच्चय है, क्योंकि 2.5 µm से छोटा कोई भी कण 10 µm से भी छोटा होता है","PM10 और PM2.5 दो अलग आकार वर्ग हैं, इसलिए कोई कण केवल एक ही में आ सकता है","PM2.5 का अर्थ 2.5 µm या उससे बड़े सभी कण हैं, इसलिए उसमें संपूर्ण PM10 शामिल है","PM10 के कण समान व्यास वाले PM2.5 कणों से लगभग दस गुना भारी होते हैं"],"explanationHi":"PM10 में वायुगतिकीय व्यास 10 µm तक के सभी श्वसन योग्य कण आते हैं, जिनमें 2.5 µm से छोटा महीन अंश भी शामिल है। इसीलिए एक ही स्थान और समय पर PM10 का मान PM2.5 के मान से सदैव कम से कम उतना ही होता है।"},
  {"id":"env-ecology-530","question":"The 'Pusa Decomposer', promoted as an alternative to burning paddy stubble in north-west India, is:","options":["A tractor-mounted machine that chops paddy straw and spreads it evenly over the field","A low-cost kiln that converts loose paddy straw into biochar briquettes for sale","A chemical spray that dries out green stubble so that it can be ploughed in quickly","A microbial formulation of fungi that speeds up the decay of straw in the field"],"answer":3,"explanation":"Developed by the Indian Agricultural Research Institute (Pusa), it is a consortium of fungal strains, applied as a solution, that breaks down stubble in situ so it enriches the soil. Straw choppers and the Happy Seeder are mechanical options.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"उत्तर-पश्चिम भारत में धान की पराली जलाने के विकल्प के रूप में प्रचारित 'पूसा डीकंपोज़र' है:","optionsHi":["ट्रैक्टर पर लगी मशीन जो धान के पुआल को काटकर खेत में समान रूप से बिखेरती है","कम लागत वाली भट्टी जो ढीले धान के पुआल को बिक्री के लिए बायोचार ब्रिकेट में बदलती है","रासायनिक छिड़काव जो हरी पराली को सुखा देता है ताकि उसे जल्दी जोता जा सके","कवकों का सूक्ष्मजीवी निरूपण जो खेत में पुआल के सड़ने की गति बढ़ाता है"],"explanationHi":"भारतीय कृषि अनुसंधान संस्थान (पूसा) द्वारा विकसित यह कवक प्रभेदों का एक समूह है, जिसे घोल के रूप में डाला जाता है और जो पराली को खेत में ही विघटित कर देता है, जिससे मृदा समृद्ध होती है। स्ट्रॉ चॉपर और हैप्पी सीडर यांत्रिक विकल्प हैं।"},
  {"id":"env-ecology-531","question":"Ground-level ozone readings are often higher in suburbs and rural areas downwind of a city than at busy traffic junctions in the city centre. The best explanation is that:","options":["Ozone is emitted directly by vehicle exhausts, but mainly from fast-moving traffic on highways outside the city","Rural vegetation emits ozone directly from its leaves, which adds to the ozone carried out from the city","Fresh nitric oxide from traffic destroys ozone nearby, while more ozone forms as air moves downwind","Ozone is heavier than air, so at night it drains out of the elevated city centre towards low-lying rural areas"],"answer":2,"explanation":"Ozone is a secondary pollutant; near heavy traffic, freshly emitted NO 'titrates' it (NO + O3 gives NO2 + O2). Downwind, sunlight keeps driving reactions of NOx and VOCs, so ozone builds up away from the sources.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भू-स्तरीय ओज़ोन का स्तर प्रायः शहर के केंद्र के व्यस्त यातायात चौराहों की तुलना में शहर की हवा की दिशा वाले उपनगरों और ग्रामीण क्षेत्रों में अधिक होता है। इसकी सबसे अच्छी व्याख्या यह है कि:","optionsHi":["ओज़ोन सीधे वाहनों के निकास से उत्सर्जित होती है, परंतु मुख्यतः शहर के बाहर राजमार्गों पर तेज़ चलने वाले यातायात से","ग्रामीण वनस्पति अपनी पत्तियों से सीधे ओज़ोन उत्सर्जित करती है, जो शहर से आई ओज़ोन में जुड़ जाती है","यातायात से ताज़ा निकली नाइट्रिक ऑक्साइड आसपास ओज़ोन को नष्ट कर देती है, जबकि हवा के साथ आगे बढ़ने पर अधिक ओज़ोन बनती है","ओज़ोन हवा से भारी होती है, इसलिए रात में वह ऊँचे शहर के केंद्र से निचले ग्रामीण क्षेत्रों की ओर बह जाती है"],"explanationHi":"ओज़ोन एक द्वितीयक प्रदूषक है; भारी यातायात के पास ताज़ा उत्सर्जित NO उसे 'अनुमापित' कर देती है (NO + O3 से NO2 + O2 बनता है)। हवा की दिशा में आगे, सूर्य का प्रकाश NOx और VOC की अभिक्रियाओं को चलाता रहता है, इसलिए स्रोतों से दूर ओज़ोन जमा हो जाती है।"},
  {"id":"env-ecology-532","question":"Apart from the direct health hazard of lead, why was unleaded petrol essential for vehicles fitted with catalytic converters?","options":["Lead raises the octane rating so much that engines with converters overheat","Lead compounds coat and deactivate the precious-metal catalyst, 'poisoning' it","Lead reacts with the catalyst to produce large amounts of sulphur dioxide","Lead makes the exhaust too cool for the catalyst to reach its working temperature"],"answer":1,"explanation":"Tetraethyl lead was added as an anti-knock agent, but lead deposits on platinum, palladium and rhodium surfaces and permanently deactivates them. So converters and unleaded fuel had to come together.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सीसे के प्रत्यक्ष स्वास्थ्य संकट के अलावा, उत्प्रेरक परिवर्तक (कैटेलिटिक कन्वर्टर) लगे वाहनों के लिए सीसा-रहित पेट्रोल क्यों आवश्यक था?","optionsHi":["सीसा ऑक्टेन रेटिंग को इतना बढ़ा देता है कि परिवर्तक वाले इंजन अत्यधिक गर्म हो जाते हैं","सीसे के यौगिक कीमती-धातु उत्प्रेरक पर परत चढ़ाकर उसे निष्क्रिय कर देते हैं, यानी उसे 'विषाक्त' कर देते हैं","सीसा उत्प्रेरक से अभिक्रिया करके बड़ी मात्रा में सल्फर डाइऑक्साइड बनाता है","सीसा निकास को इतना ठंडा कर देता है कि उत्प्रेरक अपने कार्यकारी तापमान तक नहीं पहुँच पाता"],"explanationHi":"टेट्राएथिल लेड को नॉक-रोधी के रूप में मिलाया जाता था, परंतु सीसा प्लेटिनम, पैलेडियम और रोडियम की सतहों पर जमकर उन्हें स्थायी रूप से निष्क्रिय कर देता है। इसलिए परिवर्तक और सीसा-रहित ईंधन साथ-साथ आने ही थे।"},
  {"id":"env-ecology-533","question":"The yellowing and pitting of the Taj Mahal's marble, linked to emissions from industries and a refinery in the Agra–Mathura region, is mainly due to sulphur dioxide converting the marble surface into:","options":["Calcium sulphate (gypsum)","Calcium hydroxide (slaked lime)","Calcium oxide (quicklime)","Calcium chloride"],"answer":0,"explanation":"SO2 forms sulphurous and sulphuric acid with moisture, which reacts with calcium carbonate to form gypsum; the gypsum crust traps soot and flakes off. This 'marble cancer' led the Supreme Court to regulate industries in the Taj Trapezium Zone.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"आगरा–मथुरा क्षेत्र के उद्योगों और एक तेल शोधक कारखाने के उत्सर्जन से जुड़ा ताजमहल के संगमरमर का पीला पड़ना और उस पर गड्ढे पड़ना मुख्यतः सल्फर डाइऑक्साइड के संगमरमर की सतह को किसमें बदल देने के कारण है?","optionsHi":["कैल्शियम सल्फेट (जिप्सम)","कैल्शियम हाइड्रॉक्साइड (बुझा चूना)","कैल्शियम ऑक्साइड (अनबुझा चूना)","कैल्शियम क्लोराइड"],"explanationHi":"SO2 नमी के साथ सल्फ्यूरस और सल्फ्यूरिक अम्ल बनाती है, जो कैल्शियम कार्बोनेट से अभिक्रिया करके जिप्सम बनाते हैं; जिप्सम की परत कालिख को रोक लेती है और झड़ जाती है। इस 'संगमरमर कैंसर' के कारण उच्चतम न्यायालय ने ताज ट्रैपेज़ियम क्षेत्र में उद्योगों को विनियमित किया।"},
  {"id":"env-ecology-534","question":"Assertion (A): Building very tall chimneys at coal-fired power plants can worsen acid rain in regions far away from the plants. Reason (R): Emissions released high in the atmosphere stay aloft longer and are carried farther before they are deposited. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Tall stacks dilute pollution near the plant but do not remove the SO2 and NOx; they export it, which is how acid deposition in Scandinavia was traced to emissions from Britain and central Europe.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): कोयला-चालित विद्युत संयंत्रों पर बहुत ऊँची चिमनियाँ बनाने से संयंत्रों से दूर के क्षेत्रों में अम्ल वर्षा बदतर हो सकती है। कारण (R): वायुमंडल में ऊँचाई पर छोड़े गए उत्सर्जन अधिक देर तक ऊपर रहते हैं और जमा होने से पहले दूर तक ले जाए जाते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"ऊँची चिमनियाँ संयंत्र के निकट प्रदूषण को तनु करती हैं, परंतु SO2 और NOx को हटाती नहीं; वे उसे दूर भेज देती हैं, इसीलिए स्कैंडिनेविया में अम्लीय निक्षेपण का पता ब्रिटेन और मध्य यूरोप के उत्सर्जन से लगाया गया।"},
  {"id":"env-ecology-535","question":"Consider the following statements about fluidised bed combustion of coal: 1. Limestone added to the bed captures much of the sulphur dioxide inside the furnace itself. 2. Its relatively low combustion temperature reduces the formation of thermal nitrogen oxides. 3. It removes most of the carbon dioxide produced by burning the coal. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"In FBC, limestone in the bed reacts with SO2 to form calcium sulphate, and the bed runs at around 800–900 °C, too cool for much thermal NOx. CO2 is still released in full; it is not a carbon-capture technology.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कोयले के तरलीकृत शय्या दहन (फ्लूडाइज़्ड बेड कम्बशन) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. शय्या में मिलाया गया चूना पत्थर भट्टी के भीतर ही सल्फर डाइऑक्साइड का बड़ा भाग ग्रहण कर लेता है। 2. इसका अपेक्षाकृत कम दहन तापमान तापीय नाइट्रोजन ऑक्साइडों का बनना घटाता है। 3. यह कोयला जलाने से उत्पन्न अधिकांश कार्बन डाइऑक्साइड को हटा देता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"FBC में शय्या का चूना पत्थर SO2 से अभिक्रिया करके कैल्शियम सल्फेट बनाता है, और शय्या लगभग 800–900 °C पर चलती है, जो अधिक तापीय NOx के लिए बहुत ठंडी है। CO2 फिर भी पूरी निकलती है; यह कार्बन अभिग्रहण तकनीक नहीं है।"},
  {"id":"env-ecology-536","question":"Exhaust gas recirculation (EGR), used in many engines, reduces the emission of nitrogen oxides mainly because it:","options":["Converts the nitrogen oxides into ammonia inside the exhaust pipe","Adds extra oxygen to the cylinder so that the fuel burns more completely","Burns the nitrogen oxides a second time at a much higher temperature","Dilutes the intake charge and so lowers peak combustion temperature"],"answer":3,"explanation":"Most engine NOx is 'thermal NOx', formed when N2 and O2 combine at very high flame temperatures. Feeding some inert exhaust back into the intake lowers the peak temperature and so cuts NOx formation.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अनेक इंजनों में प्रयुक्त निकास गैस पुनर्परिसंचरण (EGR) नाइट्रोजन ऑक्साइडों का उत्सर्जन मुख्यतः इसलिए घटाता है क्योंकि वह:","optionsHi":["निकास पाइप के भीतर नाइट्रोजन ऑक्साइडों को अमोनिया में बदल देता है","सिलिंडर में अतिरिक्त ऑक्सीजन जोड़ता है जिससे ईंधन अधिक पूर्णता से जलता है","नाइट्रोजन ऑक्साइडों को बहुत अधिक तापमान पर दूसरी बार जला देता है","अंतर्ग्रहण मिश्रण को तनु करता है और इस प्रकार दहन का शिखर तापमान घटाता है"],"explanationHi":"इंजन का अधिकांश NOx 'तापीय NOx' होता है, जो बहुत ऊँचे ज्वाला तापमान पर N2 और O2 के संयोग से बनता है। कुछ अक्रिय निकास को वापस अंतर्ग्रहण में भेजने से शिखर तापमान घटता है और NOx का बनना कम होता है।"},
  {"id":"env-ecology-537","question":"Consider the following statements about compressed natural gas (CNG) as a vehicle fuel: 1. It consists mainly of methane. 2. Shifting buses from diesel to CNG sharply reduces their particulate emissions. 3. CNG vehicles emit no nitrogen oxides. Which of the statements given above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"CNG is mostly methane and burns with very little soot, which is why Delhi's bus fleet was converted on Supreme Court orders. But any high-temperature combustion in air still forms NOx, so statement 3 is wrong.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"वाहन ईंधन के रूप में संपीड़ित प्राकृतिक गैस (CNG) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसमें मुख्यतः मीथेन होती है। 2. बसों को डीज़ल से CNG पर ले जाने से उनका कणिकीय उत्सर्जन बहुत घट जाता है। 3. CNG वाहन कोई नाइट्रोजन ऑक्साइड उत्सर्जित नहीं करते। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"CNG अधिकांशतः मीथेन है और बहुत कम कालिख के साथ जलती है, इसीलिए उच्चतम न्यायालय के आदेश पर दिल्ली का बस बेड़ा परिवर्तित किया गया। परंतु हवा में कोई भी उच्च तापमान दहन फिर भी NOx बनाता है, इसलिए कथन 3 गलत है।"},
  {"id":"env-ecology-538","question":"The 'ventilation coefficient', used to judge how well the air over a city can disperse pollutants, is the product of:","options":["Air temperature and relative humidity measured near the ground","Rainfall intensity and the number of hours of rain in a day","Mixing height and the average wind speed within that layer","Surface atmospheric pressure and the lapse rate of temperature"],"answer":2,"explanation":"A deep mixing layer and strong winds dilute pollutants. In north Indian winters both the mixing height and wind speed drop, so the ventilation coefficient falls and pollution accumulates.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"किसी शहर के ऊपर की हवा प्रदूषकों को कितनी अच्छी तरह फैला सकती है, यह आँकने के लिए प्रयुक्त 'वेंटिलेशन गुणांक' किसका गुणनफल है?","optionsHi":["भूमि के निकट मापे गए वायु तापमान और सापेक्ष आर्द्रता का","वर्षा की तीव्रता और एक दिन में वर्षा के घंटों की संख्या का","मिश्रण ऊँचाई और उस परत में औसत पवन चाल का","पृष्ठीय वायुमंडलीय दाब और तापमान के ह्रास दर का"],"explanationHi":"गहरी मिश्रण परत और तेज़ हवाएँ प्रदूषकों को तनु करती हैं। उत्तर भारत की सर्दियों में मिश्रण ऊँचाई और पवन चाल दोनों घट जाती हैं, इसलिए वेंटिलेशन गुणांक गिरता है और प्रदूषण जमा होता है।"},
  {"id":"env-ecology-539","question":"Which of the following is an important natural (biogenic) precursor of ground-level ozone, emitted in large amounts by many trees on hot, sunny days?","options":["Carbon dioxide","Nitrous oxide","Sulphur dioxide","Isoprene"],"answer":3,"explanation":"Isoprene is a reactive volatile organic compound released by trees such as oaks and eucalyptus; with NOx and sunlight it helps form ozone. CO2 and N2O are too unreactive in the lower atmosphere to drive ozone formation.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सा भू-स्तरीय ओज़ोन का एक महत्त्वपूर्ण प्राकृतिक (जैविक) पूर्ववर्ती (precursor) है, जो गर्म, धूप वाले दिनों में अनेक वृक्षों द्वारा बड़ी मात्रा में उत्सर्जित होता है?","optionsHi":["कार्बन डाइऑक्साइड","नाइट्रस ऑक्साइड","सल्फर डाइऑक्साइड","आइसोप्रीन"],"explanationHi":"आइसोप्रीन एक अभिक्रियाशील वाष्पशील कार्बनिक यौगिक है जो ओक और यूकेलिप्टस जैसे वृक्षों से निकलता है; NOx और सूर्य के प्रकाश के साथ यह ओज़ोन बनाने में सहायक होता है। CO2 और N2O निचले वायुमंडल में ओज़ोन निर्माण को चलाने के लिए बहुत कम अभिक्रियाशील हैं।"},
  {"id":"env-ecology-540","question":"Consider the following statements about the Noise Pollution (Regulation and Control) Rules, 2000: 1. They were framed under the Environment (Protection) Act, 1986. 2. An area of not less than 100 metres around hospitals, educational institutions and courts may be declared a silence zone. 3. 'Night time' under the rules runs from 10 p.m. to 6 a.m. 4. The daytime ambient noise limit for residential areas is higher than that for commercial areas. How many of the statements given above are correct?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements 1–3 are correct. The daytime limits are 75 dB(A) industrial, 65 commercial, 55 residential and 50 in silence zones, so residential limits are lower than commercial ones.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"ध्वनि प्रदूषण (विनियमन और नियंत्रण) नियम, 2000 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इन्हें पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत बनाया गया था। 2. अस्पतालों, शैक्षणिक संस्थानों और न्यायालयों के आसपास कम से कम 100 मीटर का क्षेत्र शांत क्षेत्र घोषित किया जा सकता है। 3. नियमों के अनुसार 'रात्रि समय' रात 10 बजे से प्रातः 6 बजे तक होता है। 4. आवासीय क्षेत्रों के लिए दिन के समय परिवेशी ध्वनि की सीमा वाणिज्यिक क्षेत्रों से अधिक है। उपर्युक्त कथनों में से कितने सही हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"कथन 1–3 सही हैं। दिन की सीमाएँ औद्योगिक 75 dB(A), वाणिज्यिक 65, आवासीय 55 और शांत क्षेत्रों में 50 हैं, इसलिए आवासीय सीमाएँ वाणिज्यिक से कम हैं।"},
  {"id":"env-ecology-541","question":"Which of the following statements about fluoride in drinking water is correct?","options":["Fluoride gives no benefit to teeth, so BIS sets its permissible limit in drinking water at 0.05 mg/L","Small amounts protect teeth, but above about 1.5 mg/L fluoride causes dental and skeletal fluorosis","Fluorosis is a fluoride-deficiency disease, which is why some countries add fluoride to public water","High fluoride in Indian groundwater comes mainly from phosphate fertilisers and industrial effluents"],"answer":1,"explanation":"The Indian standard sets 1.0 mg/L as acceptable and 1.5 mg/L as the permissible limit; low levels help prevent caries while excess causes fluorosis. Fertilisers and effluents are a tempting source, but high fluoride in states such as Rajasthan and Telangana is mainly geogenic, leached from fluoride-bearing rocks.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पेयजल में फ्लोराइड के बारे में निम्नलिखित में से कौन-सा कथन सही है?","optionsHi":["फ्लोराइड से दाँतों को कोई लाभ नहीं होता, इसलिए BIS पेयजल में इसकी अनुमेय सीमा 0.05 mg/L रखता है","अल्प मात्रा दाँतों की रक्षा करती है, परंतु लगभग 1.5 mg/L से अधिक फ्लोराइड दंत और कंकालीय फ्लोरोसिस उत्पन्न करता है","फ्लोरोसिस फ्लोराइड की कमी से होने वाला रोग है, इसीलिए कुछ देश सार्वजनिक जल में फ्लोराइड मिलाते हैं","भारतीय भूजल में उच्च फ्लोराइड मुख्यतः फॉस्फेट उर्वरकों और औद्योगिक बहिःस्रावों से आता है"],"explanationHi":"भारतीय मानक 1.0 mg/L को स्वीकार्य और 1.5 mg/L को अनुमेय सीमा निर्धारित करता है; कम मात्रा दंत क्षय रोकने में सहायक है, जबकि अधिकता फ्लोरोसिस करती है। उर्वरक और बहिःस्राव आकर्षक स्रोत लगते हैं, पर राजस्थान और तेलंगाना जैसे राज्यों में उच्च फ्लोराइड मुख्यतः भूजनित है, जो फ्लोराइड-युक्त चट्टानों से निक्षालित होता है।"},
  {"id":"env-ecology-542","question":"In the activated sludge process of sewage treatment, part of the sludge that settles in the secondary clarifier is pumped back into the aeration tank. The purpose is to:","options":["Add chemical coagulants so that fine suspended particles settle faster","Raise the temperature of the sewage so that the bacteria grow more quickly","Dilute toxic heavy metals before the treated water is discharged into a river","Keep a large, active population of microbes to digest the organic matter"],"answer":3,"explanation":"The returned sludge carries the flocs of aerobic bacteria and protozoa that consume the organic load, so recycling it keeps the BOD-removing biomass high. The excess sludge goes to anaerobic digesters, which produce biogas.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मलजल उपचार की सक्रियित अवपंक (एक्टिवेटेड स्लज) प्रक्रिया में द्वितीयक स्पष्टक में बैठने वाले अवपंक का एक भाग वापस वातन टंकी में पंप कर दिया जाता है। इसका उद्देश्य है:","optionsHi":["रासायनिक स्कंदक मिलाना ताकि महीन निलंबित कण तेज़ी से बैठें","मलजल का तापमान बढ़ाना ताकि जीवाणु अधिक तेज़ी से बढ़ें","उपचारित जल को नदी में छोड़ने से पहले विषैली भारी धातुओं को तनु करना","कार्बनिक पदार्थ को पचाने के लिए सूक्ष्मजीवों की बड़ी, सक्रिय समष्टि बनाए रखना"],"explanationHi":"लौटाए गए अवपंक में वायवीय जीवाणुओं और प्रोटोज़ोआ के फ्लॉक होते हैं जो कार्बनिक भार का उपभोग करते हैं, इसलिए उसे पुनःचक्रित करने से BOD हटाने वाला जैवभार ऊँचा बना रहता है। अतिरिक्त अवपंक अवायवीय पाचकों में जाता है, जहाँ बायोगैस बनती है।"},
  {"id":"env-ecology-543","question":"Consider the following statements: 1. The Ganga was declared India's 'National River' in 2008. 2. The National Ganga River Basin Authority was constituted under the Environment (Protection) Act, 1986. 3. The National Mission for Clean Ganga is a constitutional body. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Ganga became the National River in November 2008, and the NGRBA was set up in 2009 under Section 3 of the EP Act. NMCG was registered as a society and later made an authority under the same Act; no constitutional provision created it.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. गंगा को 2008 में भारत की 'राष्ट्रीय नदी' घोषित किया गया। 2. राष्ट्रीय गंगा नदी बेसिन प्राधिकरण का गठन पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत हुआ। 3. राष्ट्रीय स्वच्छ गंगा मिशन एक संवैधानिक निकाय है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"गंगा नवंबर 2008 में राष्ट्रीय नदी बनी, और NGRBA की स्थापना 2009 में EP अधिनियम की धारा 3 के अंतर्गत हुई। NMCG एक सोसायटी के रूप में पंजीकृत था और बाद में उसी अधिनियम के अंतर्गत प्राधिकरण बनाया गया; किसी संवैधानिक प्रावधान ने उसे नहीं बनाया।"},
  {"id":"env-ecology-544","question":"An industrial unit described as achieving 'zero liquid discharge' (ZLD):","options":["Uses no water at any stage of its production process","Treats its effluent only up to the standard for discharge into rivers","Treats and recycles its wastewater, so no liquid effluent leaves","Sends all of its wastewater to a common effluent treatment plant nearby"],"answer":2,"explanation":"ZLD plants recover water through treatment, reverse osmosis and evaporators, reuse it, and leave only solid residues. Meeting discharge standards or sending effluent to a CETP still releases liquid effluent.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"'शून्य तरल निस्सरण' (ZLD) प्राप्त करने वाली औद्योगिक इकाई:","optionsHi":["अपनी उत्पादन प्रक्रिया के किसी भी चरण में जल का उपयोग नहीं करती","अपने बहिःस्राव का उपचार केवल नदियों में छोड़ने के मानक तक करती है","अपने अपशिष्ट जल का उपचार और पुनःचक्रण करती है, इसलिए कोई तरल बहिःस्राव बाहर नहीं जाता","अपना सारा अपशिष्ट जल पास के सामूहिक बहिःस्राव उपचार संयंत्र को भेजती है"],"explanationHi":"ZLD संयंत्र उपचार, प्रतिलोम परासरण और वाष्पित्रों से जल पुनः प्राप्त करते हैं, उसका पुनः उपयोग करते हैं, और केवल ठोस अवशेष छोड़ते हैं। निस्सरण मानक पूरे करना या बहिःस्राव को CETP भेजना फिर भी तरल बहिःस्राव छोड़ता है।"},
  {"id":"env-ecology-545","question":"Ballast water carried by ships is a major environmental concern mainly because it:","options":["Contains crude oil residues that leak into harbours when it is pumped out","Transfers aquatic organisms, including invasive species, between distant seas","Is heavily chlorinated before discharge and so kills corals near shipping lanes","Raises the salinity of rivers sharply when it is discharged at inland river ports"],"answer":1,"explanation":"Ships take in seawater with plankton, larvae and pathogens at one port and release it at another, spreading species such as the zebra mussel. The IMO's Ballast Water Management Convention (2004) addresses this.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जहाज़ों द्वारा ले जाया जाने वाला गिट्टी जल (बैलास्ट वाटर) एक बड़ी पर्यावरणीय चिंता मुख्यतः इसलिए है क्योंकि वह:","optionsHi":["इसमें कच्चे तेल के अवशेष होते हैं जो पंप करके निकालने पर बंदरगाहों में रिस जाते हैं","आक्रामक प्रजातियों सहित जलीय जीवों को दूर-दूर के समुद्रों के बीच पहुँचाता है","निस्सरण से पहले उसमें भारी क्लोरीनीकरण होता है, इसलिए वह जहाज़ी मार्गों के निकट प्रवाल को मार देता है","अंतर्देशीय नदी बंदरगाहों पर छोड़े जाने पर नदियों की लवणता को तेज़ी से बढ़ा देता है"],"explanationHi":"जहाज़ एक बंदरगाह पर प्लवक, लार्वा और रोगाणुओं सहित समुद्री जल भरते हैं और उसे दूसरे बंदरगाह पर छोड़ देते हैं, जिससे ज़ेब्रा मसल जैसी प्रजातियाँ फैलती हैं। IMO का गिट्टी जल प्रबंधन अभिसमय (2004) इसी का समाधान करता है।"},
  {"id":"env-ecology-546","question":"Below a sewage outfall, a river's dissolved oxygen falls and then recovers, tracing an 'oxygen sag curve'. Where is the lowest point of this curve usually found, and why?","options":["Exactly at the outfall, because the oxygen demand is greatest where the sewage enters","Upstream of the outfall, because polluted water mixes back against the river's current","Far downstream at the river mouth, because oxygen keeps falling until the river meets the sea","Some distance downstream, where oxygen used in decay still exceeds re-aeration"],"answer":3,"explanation":"Microbial decomposition takes time, so oxygen keeps falling as the water flows on. The minimum (critical point) lies where the rate of deoxygenation equals the rate of re-aeration from the air; beyond it, oxygen recovers.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"किसी मलजल निकास के नीचे नदी की घुलित ऑक्सीजन पहले घटती है और फिर बहाल होती है, जिससे 'ऑक्सीजन अवनमन वक्र' बनता है। इस वक्र का निम्नतम बिंदु सामान्यतः कहाँ होता है, और क्यों?","optionsHi":["ठीक निकास पर, क्योंकि जहाँ मलजल प्रवेश करता है वहाँ ऑक्सीजन की माँग सबसे अधिक होती है","निकास के ऊपरी प्रवाह में, क्योंकि प्रदूषित जल नदी की धारा के विरुद्ध वापस मिल जाता है","नदी के मुहाने पर बहुत आगे, क्योंकि जब तक नदी समुद्र से नहीं मिलती तब तक ऑक्सीजन घटती रहती है","निचले प्रवाह में कुछ दूरी पर, जहाँ अपघटन में प्रयुक्त ऑक्सीजन अब भी पुनःवातन से अधिक है"],"explanationHi":"सूक्ष्मजीवी अपघटन में समय लगता है, इसलिए जल के आगे बहने के साथ ऑक्सीजन घटती रहती है। निम्नतम (क्रांतिक) बिंदु वहाँ होता है जहाँ ऑक्सीजन ह्रास की दर वायु से पुनःवातन की दर के बराबर हो जाती है; उसके आगे ऑक्सीजन बहाल होती है।"},
  {"id":"env-ecology-547","question":"A survey of a stream bed finds large numbers of Tubifex (sludge) worms and red chironomid larvae, but no stonefly or mayfly nymphs. This most likely indicates that the stream:","options":["Is heavily polluted with organic matter and low in dissolved oxygen","Is clean, cold and well oxygenated, typical of a fast mountain stream","Is acidified by mine drainage but otherwise has normal oxygen levels","Has been polluted mainly by excess heat from a power plant upstream"],"answer":0,"explanation":"Tubifex and red 'bloodworm' larvae tolerate very low oxygen, while stonefly and mayfly nymphs need clean, oxygen-rich water. Such biotic indices are used to grade organic pollution.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"किसी धारा के तल के सर्वेक्षण में ट्यूबिफेक्स (अवपंक) कृमि और लाल काइरोनोमिड लार्वा बड़ी संख्या में मिलते हैं, परंतु स्टोनफ्लाई या मेफ्लाई की निम्फ नहीं मिलतीं। इससे सबसे अधिक संभावना यह इंगित होती है कि धारा:","optionsHi":["कार्बनिक पदार्थ से अत्यधिक प्रदूषित है और उसमें घुलित ऑक्सीजन कम है","स्वच्छ, ठंडी और अच्छी तरह ऑक्सीजनित है, जैसी किसी तेज़ पहाड़ी धारा में होती है","खदान के अपवाह से अम्लीकृत है, पर अन्यथा ऑक्सीजन स्तर सामान्य है","मुख्यतः ऊपरी प्रवाह में स्थित विद्युत संयंत्र की अतिरिक्त ऊष्मा से प्रदूषित हुई है"],"explanationHi":"ट्यूबिफेक्स और लाल 'ब्लडवर्म' लार्वा बहुत कम ऑक्सीजन सह लेते हैं, जबकि स्टोनफ्लाई और मेफ्लाई की निम्फ को स्वच्छ, ऑक्सीजन-समृद्ध जल चाहिए। ऐसे जैविक सूचकांकों से कार्बनिक प्रदूषण का श्रेणीकरण किया जाता है।"},
  {"id":"env-ecology-548","question":"Tannery effluent treatment aims to keep chromium in its trivalent form, Cr(III), rather than the hexavalent form, Cr(VI). This is because:","options":["Cr(III) evaporates easily and leaves the water as a harmless gas","Cr(VI) is insoluble and clogs treatment plants, while Cr(III) dissolves","Cr(VI) is far more toxic, soluble and carcinogenic than Cr(III)","Cr(III) is a plant nutrient that raises crop yields on irrigated fields"],"answer":2,"explanation":"Hexavalent chromium is highly soluble, mobile and carcinogenic; treatment reduces it to Cr(III), which precipitates as hydroxide and is far less toxic. Tanneries at Kanpur and Vellore are known sources.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"चर्मशोधन (टेनरी) बहिःस्राव उपचार का लक्ष्य क्रोमियम को षट्संयोजी रूप Cr(VI) के बजाय त्रिसंयोजी रूप Cr(III) में रखना होता है। इसका कारण यह है कि:","optionsHi":["Cr(III) आसानी से वाष्पित होकर हानिरहित गैस के रूप में जल से निकल जाता है","Cr(VI) अविलेय है और उपचार संयंत्रों को अवरुद्ध करता है, जबकि Cr(III) घुल जाता है","Cr(VI), Cr(III) की तुलना में कहीं अधिक विषैला, विलेय और कैंसरकारी है","Cr(III) एक पादप पोषक तत्व है जो सिंचित खेतों में उपज बढ़ाता है"],"explanationHi":"षट्संयोजी क्रोमियम अत्यंत विलेय, गतिशील और कैंसरकारी होता है; उपचार उसे Cr(III) में अपचयित कर देता है, जो हाइड्रॉक्साइड के रूप में अवक्षेपित होता है और कहीं कम विषैला है। कानपुर और वेल्लोर की टेनरियाँ इसके ज्ञात स्रोत हैं।"},
  {"id":"env-ecology-549","question":"In discussions of marine pollution, 'ghost gear' refers to:","options":["Plastic pellets that leak from factories into rivers and the sea","Oil residues released when ships wash out their cargo tanks","Sunken shipwrecks that slowly leak fuel and heavy metals","Abandoned, lost or discarded fishing nets, lines and traps"],"answer":3,"explanation":"Lost fishing gear keeps trapping and killing fish, turtles, dolphins and seabirds for years ('ghost fishing') and is a large share of large plastic debris in the oceans.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"समुद्री प्रदूषण की चर्चाओं में 'घोस्ट गियर' से तात्पर्य है:","optionsHi":["प्लास्टिक के छर्रे जो कारखानों से नदियों और समुद्र में रिस जाते हैं","तेल के अवशेष जो जहाज़ों द्वारा अपने कार्गो टैंक धोने पर छोड़े जाते हैं","डूबे हुए जहाज़ी मलबे जो धीरे-धीरे ईंधन और भारी धातुएँ रिसाते हैं","परित्यक्त, खोए हुए या फेंके गए मछली पकड़ने के जाल, डोरियाँ और पिंजरे"],"explanationHi":"खोए हुए मछली पकड़ने के उपकरण वर्षों तक मछलियों, कछुओं, डॉल्फ़िनों और समुद्री पक्षियों को फँसाते और मारते रहते हैं ('घोस्ट फिशिंग'), और महासागरों के बड़े प्लास्टिक मलबे का बड़ा हिस्सा हैं।"},
  {"id":"env-ecology-550","question":"Wells in some coastal areas of Gujarat and Tamil Nadu have turned saline over the years even though no polluted effluent was discharged nearby. The most likely cause is:","options":["Acid rain dissolving salts out of the coastal rocks and carrying them into the groundwater","Over-pumping of fresh groundwater, letting seawater move inland into the aquifer","Evaporation of irrigation water from fields, leaving salt that seeps down to the water table","Seepage of untreated sewage from towns, which carries dissolved salts into the wells"],"answer":1,"explanation":"Fresh groundwater normally holds back seawater; when pumping lowers the water table, the freshwater–saltwater interface advances inland (saltwater intrusion). Recharge structures and pumping limits are the usual remedies.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"गुजरात और तमिलनाडु के कुछ तटीय क्षेत्रों के कुएँ वर्षों में खारे हो गए हैं, जबकि पास में कोई प्रदूषित बहिःस्राव नहीं छोड़ा गया। इसका सबसे संभावित कारण है:","optionsHi":["अम्ल वर्षा द्वारा तटीय चट्टानों से लवण घोलकर भूजल में पहुँचा देना","मीठे भूजल का अत्यधिक पंपन, जिससे समुद्री जल जलभृत में स्थल की ओर आ जाता है","खेतों से सिंचाई जल का वाष्पीकरण, जिससे बचा नमक रिसकर भूजल स्तर तक पहुँच जाता है","नगरों से अनुपचारित मलजल का रिसाव, जो घुले हुए लवणों को कुओं में पहुँचा देता है"],"explanationHi":"मीठा भूजल सामान्यतः समुद्री जल को रोके रखता है; जब पंपन से जलस्तर नीचे गिरता है तो मीठे-खारे जल की सीमा स्थल की ओर बढ़ जाती है (लवण जल अंतः प्रवेश)। पुनर्भरण संरचनाएँ और पंपन की सीमा इसके सामान्य उपाय हैं।"},
  {"id":"env-ecology-551","question":"Consider a food chain in which one large banyan tree supports a few hundred fruit-eating birds, and each bird carries many lice and other ectoparasites. The pyramid of numbers for this chain is:","options":["Fully inverted, widening at every level from producer to parasite","Upright, narrowing at every level from producer to parasite","Spindle-shaped, widest at the bird level and narrow at both ends","Upright at the base but inverted between the birds and parasites only"],"answer":0,"explanation":"One tree < hundreds of birds < many thousands of parasites, so every level is larger than the one below and the pyramid is fully inverted. A tree–insect–bird chain, by contrast, gives a spindle shape.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"एक ऐसी खाद्य श्रृंखला पर विचार कीजिए जिसमें एक विशाल बरगद का वृक्ष कुछ सौ फलभक्षी पक्षियों को पोषित करता है, और प्रत्येक पक्षी पर अनेक जूँ और अन्य बाह्य परजीवी रहते हैं। इस श्रृंखला का संख्या पिरामिड है:","optionsHi":["पूर्णतः उलटा, उत्पादक से परजीवी तक हर स्तर पर चौड़ा होता हुआ","सीधा, उत्पादक से परजीवी तक हर स्तर पर संकरा होता हुआ","तकुए के आकार का, पक्षी स्तर पर सबसे चौड़ा और दोनों सिरों पर संकरा","आधार पर सीधा, परंतु केवल पक्षियों और परजीवियों के बीच उलटा"],"explanationHi":"एक वृक्ष < सैकड़ों पक्षी < अनेक हज़ारों परजीवी, इसलिए प्रत्येक स्तर अपने नीचे वाले स्तर से बड़ा है और पिरामिड पूर्णतः उलटा है। इसके विपरीत, वृक्ष–कीट–पक्षी श्रृंखला तकुए का आकार देती है।"},
  {"id":"env-ecology-552","question":"How many of the following are recognised limitations of ecological pyramids? I. They do not account for one species occupying two or more trophic levels. II. They assume a simple food chain, which seldom exists in nature, rather than a food web. III. They give no place to saprophytes, though these play a vital role in the ecosystem. IV. A pyramid of energy can turn inverted when the producers are very small and short-lived.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I–III are the standard limitations. IV is false: a pyramid of energy is always upright, because energy is lost at each transfer, even when a biomass pyramid is inverted.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कितने पारिस्थितिक पिरामिडों की मान्य सीमाएँ हैं? I. वे एक प्रजाति के दो या अधिक पोषी स्तरों पर होने का लेखा नहीं रखते। II. वे खाद्य जाल के बजाय एक सरल खाद्य श्रृंखला मानकर चलते हैं, जो प्रकृति में शायद ही कभी होती है। III. वे मृतोपजीवियों को कोई स्थान नहीं देते, जबकि पारिस्थितिकी तंत्र में उनकी भूमिका अत्यंत महत्त्वपूर्ण है। IV. जब उत्पादक बहुत छोटे और अल्पजीवी होते हैं, तब ऊर्जा पिरामिड उलटा हो सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I–III मानक सीमाएँ हैं। IV असत्य है: ऊर्जा पिरामिड सदैव सीधा होता है, क्योंकि हर स्थानांतरण में ऊर्जा नष्ट होती है, भले ही जैवभार पिरामिड उलटा हो।"},
  {"id":"env-ecology-553","question":"Arrange the following steps in the order in which nitrogen in the proteins of a dead animal becomes available to plants as nitrate: 1. Conversion of nitrite into nitrate by Nitrobacter 2. Release of ammonia by decomposers (ammonification) 3. Oxidation of ammonia into nitrite by Nitrosomonas","options":["3-2-1","2-1-3","2-3-1","1-3-2"],"answer":2,"explanation":"Decomposers first release ammonia from organic nitrogen; Nitrosomonas oxidises it to nitrite, and Nitrobacter then oxidises nitrite to nitrate. Mixing up the two nitrifiers gives the 2-1-3 trap.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"किसी मृत जंतु के प्रोटीनों में मौजूद नाइट्रोजन के पौधों को नाइट्रेट के रूप में उपलब्ध होने के चरणों को उनके क्रम में व्यवस्थित कीजिए: 1. नाइट्रोबैक्टर द्वारा नाइट्राइट का नाइट्रेट में रूपांतरण 2. अपघटकों द्वारा अमोनिया का मुक्त होना (अमोनीकरण) 3. नाइट्रोसोमोनास द्वारा अमोनिया का नाइट्राइट में ऑक्सीकरण","optionsHi":["3-2-1","2-1-3","2-3-1","1-3-2"],"explanationHi":"अपघटक पहले कार्बनिक नाइट्रोजन से अमोनिया मुक्त करते हैं; नाइट्रोसोमोनास उसे नाइट्राइट में ऑक्सीकृत करता है, और फिर नाइट्रोबैक्टर नाइट्राइट को नाइट्रेट में ऑक्सीकृत करता है। दोनों नाइट्रीकारकों को आपस में उलझाने पर 2-1-3 का भ्रम वाला उत्तर बनता है।"},
  {"id":"env-ecology-554","question":"The actinomycete Frankia fixes atmospheric nitrogen in nodules formed on:","options":["Roots of leguminous crops such as pea, gram, lentil and soybean","Leaf cavities of the small aquatic fern Azolla","Coralloid roots of the gymnosperm Cycas","Roots of non-leguminous trees such as alder and Casuarina"],"answer":3,"explanation":"Frankia forms actinorhizal nodules on non-legumes like Alnus and Casuarina. Legume nodules hold Rhizobium, while Azolla and Cycas harbour cyanobacteria (Anabaena, Nostoc).","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"एक्टिनोमाइसीट फ्रैंकिया वायुमंडलीय नाइट्रोजन का स्थिरीकरण किन पर बनी ग्रंथिकाओं में करता है?","optionsHi":["मटर, चना, मसूर और सोयाबीन जैसी दलहनी फसलों की जड़ों पर","छोटे जलीय फर्न एज़ोला की पत्ती गुहिकाओं में","अनावृतबीजी साइकस की प्रवाल-सदृश जड़ों में","एल्डर और कैज़ुआरिना जैसे अदलहनी वृक्षों की जड़ों पर"],"explanationHi":"फ्रैंकिया एल्नस और कैज़ुआरिना जैसे अदलहनी पौधों पर एक्टिनोराइज़ल ग्रंथिकाएँ बनाता है। दलहनी पौधों की ग्रंथिकाओं में राइज़ोबियम होता है, जबकि एज़ोला और साइकस में सायनोबैक्टीरिया (एनाबीना, नॉस्टॉक) रहते हैं।"},
  {"id":"env-ecology-555","question":"Consider the following statements: 1. Lightning converts some atmospheric nitrogen into oxides of nitrogen that reach the soil in rain. 2. The Haber–Bosch process fixes atmospheric nitrogen industrially as ammonia. 3. The enzyme nitrogenase works best in oxygen-rich conditions. Which of the statements given above is/are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Lightning and industrial fixation both add reactive nitrogen. Nitrogenase is inactivated by oxygen, which is why nodules use leghaemoglobin and cyanobacteria fix nitrogen in thick-walled heterocysts.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. आकाशीय बिजली वायुमंडलीय नाइट्रोजन के कुछ भाग को नाइट्रोजन के ऑक्साइडों में बदल देती है, जो वर्षा के साथ मृदा में पहुँचते हैं। 2. हैबर–बॉश प्रक्रिया औद्योगिक रूप से वायुमंडलीय नाइट्रोजन को अमोनिया के रूप में स्थिर करती है। 3. नाइट्रोजिनेज एंज़ाइम ऑक्सीजन-समृद्ध परिस्थितियों में सबसे अच्छा कार्य करता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"आकाशीय बिजली और औद्योगिक स्थिरीकरण दोनों अभिक्रियाशील नाइट्रोजन जोड़ते हैं। नाइट्रोजिनेज ऑक्सीजन से निष्क्रिय हो जाता है, इसीलिए ग्रंथिकाएँ लेगहीमोग्लोबिन का उपयोग करती हैं और सायनोबैक्टीरिया मोटी भित्ति वाली हेटेरोसिस्ट में नाइट्रोजन स्थिर करते हैं।"},
  {"id":"env-ecology-556","question":"Fungi of the genus Glomus form mycorrhizal associations with the roots of many crop plants. The main benefit the plant gets from this association is:","options":["Better uptake of phosphorus from the soil","Fixation of nitrogen gas directly from the air","Protection of leaves from insect grazers","Release of potassium from organic matter"],"answer":0,"explanation":"The fungal hyphae extend far beyond the roots and absorb phosphorus, which moves slowly in soil, and pass it to the plant in exchange for sugars. Mycorrhizal fungi do not fix nitrogen.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ग्लोमस वंश के कवक अनेक फसली पौधों की जड़ों के साथ कवकमूल (माइकोराइज़ा) संबंध बनाते हैं। इस संबंध से पौधे को मिलने वाला मुख्य लाभ है:","optionsHi":["मृदा से फॉस्फोरस का बेहतर अवशोषण","सीधे वायु से नाइट्रोजन गैस का स्थिरीकरण","पत्तियों को कीट चरने वालों से सुरक्षा","कार्बनिक पदार्थ से पोटैशियम का मुक्त होना"],"explanationHi":"कवक तंतु जड़ों से कहीं आगे तक फैलकर फॉस्फोरस को अवशोषित करते हैं, जो मृदा में धीरे-धीरे गतिशील होता है, और शर्कराओं के बदले उसे पौधे को दे देते हैं। कवकमूल कवक नाइट्रोजन का स्थिरीकरण नहीं करते।"},
  {"id":"env-ecology-557","question":"The 'rotten egg' smell of the black, oxygen-poor mud of mangroves and marshes comes from hydrogen sulphide produced mainly by:","options":["Sulphur-oxidising bacteria such as Thiobacillus","Sulphate-reducing bacteria such as Desulfovibrio","Methane-producing archaea living in the deeper mud layers","Nitrifying bacteria such as Nitrosomonas"],"answer":1,"explanation":"Without oxygen, Desulfovibrio uses sulphate as an electron acceptor and reduces it to H₂S. Thiobacillus does the opposite, oxidising reduced sulphur back to sulphate.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मैंग्रोव और दलदलों के काले, ऑक्सीजन-रहित कीचड़ की 'सड़े अंडे' जैसी गंध हाइड्रोजन सल्फाइड से आती है, जो मुख्यतः किसके द्वारा उत्पन्न होती है?","optionsHi":["थायोबैसिलस जैसे सल्फर-ऑक्सीकारी जीवाणु","डीसल्फोविब्रियो जैसे सल्फेट-अपचायक जीवाणु","गहरी कीचड़ परतों में रहने वाले मीथेन उत्पादक आर्किया","नाइट्रोसोमोनास जैसे नाइट्रीकारी जीवाणु"],"explanationHi":"ऑक्सीजन के अभाव में डीसल्फोविब्रियो सल्फेट को इलेक्ट्रॉन ग्राही के रूप में उपयोग करता है और उसे H₂S में अपचयित करता है। थायोबैसिलस इसका उलटा करता है, अपचयित सल्फर को फिर सल्फेट में ऑक्सीकृत करता है।"},
  {"id":"env-ecology-558","question":"The average time that a water molecule stays in the atmosphere before falling back as precipitation is about:","options":["Nine months","Nine years","Ninety days","Nine days"],"answer":3,"explanation":"Atmospheric water is replaced roughly every 9–10 days, far faster than water in oceans (thousands of years) or deep groundwater. This short residence time is why weather responds so quickly to evaporation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जल का एक अणु वर्षण के रूप में वापस गिरने से पहले औसतन वायुमंडल में कितनी देर रहता है?","optionsHi":["नौ महीने","नौ वर्ष","नब्बे दिन","नौ दिन"],"explanationHi":"वायुमंडलीय जल लगभग हर 9–10 दिन में बदल जाता है, जो महासागरों (हज़ारों वर्ष) या गहरे भूजल के जल की तुलना में कहीं तेज़ है। यही अल्प आवास काल कारण है कि मौसम वाष्पीकरण पर इतनी शीघ्र प्रतिक्रिया करता है।"},
  {"id":"env-ecology-559","question":"Which of the following holds the largest amount of carbon on Earth?","options":["Sedimentary rocks such as limestone and shale","The dissolved inorganic carbon of the deep ocean","Organic matter held in the world's soils","The proven reserves of coal, oil and natural gas"],"answer":0,"explanation":"Carbonate rocks and organic carbon in sediments hold tens of millions of gigatonnes, far more than the deep ocean (tens of thousands of gigatonnes). Among the active, fast-exchanging pools, the ocean is the largest.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से पृथ्वी पर सर्वाधिक मात्रा में कार्बन किसमें संचित है?","optionsHi":["चूना पत्थर और शेल जैसी अवसादी चट्टानें","गहरे महासागर का घुलित अकार्बनिक कार्बन","विश्व की मृदाओं में संचित कार्बनिक पदार्थ","कोयले, तेल और प्राकृतिक गैस के प्रमाणित भंडार"],"explanationHi":"कार्बोनेट चट्टानों और अवसादों में कार्बनिक कार्बन दसियों लाख गीगाटन है, जो गहरे महासागर (दसियों हज़ार गीगाटन) से कहीं अधिक है। सक्रिय, तेज़ी से विनिमय करने वाले भंडारों में महासागर सबसे बड़ा है।"},
  {"id":"env-ecology-560","question":"Sedimentary nutrient cycles, such as that of phosphorus, are often described as less 'perfect' than gaseous cycles. This is because:","options":["Their elements are needed by organisms only in very small trace amounts","Their elements cannot be absorbed by plants without fungi","Much of the element gets locked in deep sediments for very long periods","Their elements are rapidly lost to space from the upper atmosphere"],"answer":2,"explanation":"Elements with a sedimentary reservoir can be carried to the deep sea or buried, and return only through slow geological uplift. Gaseous cycles self-adjust quickly through the large, well-mixed atmospheric pool.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"फॉस्फोरस जैसे अवसादी पोषक चक्रों को प्रायः गैसीय चक्रों की तुलना में कम 'पूर्ण' बताया जाता है। इसका कारण यह है कि:","optionsHi":["उनके तत्वों की जीवों को केवल अत्यल्प सूक्ष्म मात्रा में ही आवश्यकता होती है","उनके तत्वों को पौधे कवकों के बिना अवशोषित नहीं कर सकते","तत्व का बड़ा भाग बहुत लंबे समय तक गहरे अवसादों में बंद हो जाता है","उनके तत्व ऊपरी वायुमंडल से अंतरिक्ष में तेज़ी से खो जाते हैं"],"explanationHi":"जिन तत्वों का भंडार अवसादी होता है, वे गहरे समुद्र में पहुँचकर दब सकते हैं और केवल धीमे भूवैज्ञानिक उत्थान से लौटते हैं। गैसीय चक्र विशाल, भली-भाँति मिश्रित वायुमंडलीय भंडार के कारण शीघ्र स्व-समायोजित हो जाते हैं।"},
  {"id":"env-ecology-561","question":"Legume crops on some acid soils nodulate poorly and fix little nitrogen until a small dose of a micronutrient that forms part of the enzyme nitrogenase is applied. This micronutrient is:","options":["Zinc","Molybdenum","Boron","Manganese"],"answer":1,"explanation":"Nitrogenase contains a molybdenum–iron cofactor, so molybdenum deficiency, common on acid soils, directly cuts nitrogen fixation. Zinc, boron and manganese have other roles in plants.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"कुछ अम्लीय मृदाओं पर दलहनी फसलों में ग्रंथिकाएँ कम बनती हैं और वे बहुत कम नाइट्रोजन स्थिर करती हैं, जब तक कि एक सूक्ष्म पोषक तत्व की थोड़ी मात्रा न दी जाए, जो नाइट्रोजिनेज एंज़ाइम का एक भाग है। यह सूक्ष्म पोषक तत्व है:","optionsHi":["ज़िंक","मॉलिब्डेनम","बोरॉन","मैंगनीज़"],"explanationHi":"नाइट्रोजिनेज में मॉलिब्डेनम–आयरन सहकारक होता है, इसलिए अम्लीय मृदाओं में आम मॉलिब्डेनम की कमी नाइट्रोजन स्थिरीकरण को सीधे घटा देती है। ज़िंक, बोरॉन और मैंगनीज़ की पौधों में अन्य भूमिकाएँ हैं।"},
  {"id":"env-ecology-562","question":"A classic study of energy flow through every trophic level of a whole ecosystem, carried out at Silver Springs in Florida in the 1950s, is associated with:","options":["Raymond Lindeman","Arthur Tansley","Charles Elton","Howard T. Odum"],"answer":3,"explanation":"H. T. Odum's Silver Springs study (1957) produced a full energy budget and pyramid. Lindeman's earlier trophic-dynamic work was on Cedar Bog Lake in Minnesota.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"1950 के दशक में फ्लोरिडा के सिल्वर स्प्रिंग्स में किया गया, संपूर्ण पारिस्थितिकी तंत्र के प्रत्येक पोषी स्तर से होकर ऊर्जा प्रवाह का एक क्लासिक अध्ययन किससे जुड़ा है?","optionsHi":["रेमंड लिंडमैन","आर्थर टैन्सले","चार्ल्स एल्टन","हावर्ड टी. ओडम"],"explanationHi":"एच. टी. ओडम के सिल्वर स्प्रिंग्स अध्ययन (1957) से संपूर्ण ऊर्जा बजट और पिरामिड प्राप्त हुआ। लिंडमैन का पूर्व का पोषी-गतिकी कार्य मिनेसोटा की सीडर बॉग झील पर था।"},
  {"id":"env-ecology-563","question":"In the phosphorus cycle, which of the following correctly pairs the reservoir pool with the exchange (cycling) pool?","options":["Reservoir: the atmosphere; exchange pool: rocks, sediments and ocean-floor deposits","Reservoir: rocks and sediments; exchange pool: soil solution and living organisms","Reservoir: living organisms; exchange pool: atmosphere and ocean water","Reservoir: ocean water; exchange pool: the atmosphere, soil air and living organisms"],"answer":1,"explanation":"Phosphorus is stored mainly in phosphate rocks and sediments and moves quickly only between soil or water and organisms. It has no significant atmospheric pool.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"फॉस्फोरस चक्र में निम्नलिखित में से कौन-सा संचय भंडार और विनिमय (चक्रण) भंडार का सही जोड़ा बनाता है?","optionsHi":["संचय भंडार: वायुमंडल; विनिमय भंडार: चट्टानें, अवसाद और महासागर-तल के निक्षेप","संचय भंडार: चट्टानें और अवसाद; विनिमय भंडार: मृदा विलयन और जीवित जीव","संचय भंडार: जीवित जीव; विनिमय भंडार: वायुमंडल और महासागरीय जल","संचय भंडार: महासागरीय जल; विनिमय भंडार: वायुमंडल, मृदा वायु और जीवित जीव"],"explanationHi":"फॉस्फोरस मुख्यतः फॉस्फेट चट्टानों और अवसादों में संचित रहता है और केवल मृदा या जल तथा जीवों के बीच ही तेज़ी से गतिशील होता है। उसका कोई उल्लेखनीय वायुमंडलीय भंडार नहीं है।"},
  {"id":"env-ecology-564","question":"How many of the following statements about the slow, geological carbon cycle are correct? I. Chemical weathering of silicate rocks removes carbon dioxide from the atmosphere over long periods. II. Volcanic outgassing returns carbon dioxide to the atmosphere. III. This cycle operates over tens to hundreds of years. IV. Volcanoes today release more carbon dioxide each year than human activities do.","options":["Only one","Only two","All four","Only three"],"answer":1,"explanation":"I and II are correct. III is wrong: the geological carbon cycle works over hundreds of thousands to millions of years. IV is wrong: human CO₂ emissions are roughly a hundred times average volcanic emissions.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"धीमे, भूवैज्ञानिक कार्बन चक्र के बारे में निम्नलिखित में से कितने कथन सही हैं? I. सिलिकेट चट्टानों का रासायनिक अपक्षय लंबे समय में वायुमंडल से कार्बन डाइऑक्साइड हटाता है। II. ज्वालामुखीय निर्गमन कार्बन डाइऑक्साइड को वायुमंडल में लौटाता है। III. यह चक्र दसियों से सैकड़ों वर्षों में चलता है। IV. आज ज्वालामुखी प्रति वर्ष मानवीय गतिविधियों से अधिक कार्बन डाइऑक्साइड छोड़ते हैं।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"I और II सही हैं। III गलत है: भूवैज्ञानिक कार्बन चक्र सैकड़ों हज़ार से लाखों वर्षों में चलता है। IV गलत है: मानवीय CO₂ उत्सर्जन औसत ज्वालामुखीय उत्सर्जन का लगभग सौ गुना है।"},
  {"id":"env-ecology-565","question":"Consider the following statements about the global water cycle: 1. Over the oceans, evaporation exceeds precipitation. 2. Over the land, precipitation exceeds evaporation, and the difference returns to the sea as runoff. 3. Most of the water vapour in the atmosphere comes from transpiration by land plants. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The oceans are a net source of vapour carried over land, and rivers return the surplus. Statement 3 is wrong: most atmospheric moisture evaporates from the oceans.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"वैश्विक जल चक्र के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. महासागरों के ऊपर वाष्पीकरण वर्षण से अधिक होता है। 2. स्थल के ऊपर वर्षण वाष्पीकरण से अधिक होता है, और अंतर अपवाह के रूप में समुद्र को लौटता है। 3. वायुमंडल में जलवाष्प का अधिकांश भाग स्थलीय पौधों के वाष्पोत्सर्जन से आता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"महासागर स्थल पर ले जाए जाने वाले वाष्प के शुद्ध स्रोत हैं, और नदियाँ अधिशेष लौटाती हैं। कथन 3 गलत है: वायुमंडलीय नमी का अधिकांश भाग महासागरों से वाष्पित होता है।"},
  {"id":"env-ecology-566","question":"The ocean's 'solubility pump' moves carbon dioxide from the surface to the deep sea mainly because:","options":["Phytoplankton fix carbon dioxide at the surface and their remains sink to great depths","Coral reefs lock carbon dioxide into limestone at the sea floor","Carbon dioxide is more soluble in cold water, and cold, dense polar water sinks","Warm tropical water sinks and carries dissolved carbon dioxide down with it"],"answer":2,"explanation":"Cold high-latitude water absorbs more CO₂ and, being dense, sinks into the deep ocean. Sinking organic matter is the separate biological pump; warm water does not sink.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"महासागर का 'विलेयता पंप' कार्बन डाइऑक्साइड को सतह से गहरे समुद्र में मुख्यतः इसलिए पहुँचाता है क्योंकि:","optionsHi":["फाइटोप्लैंकटन सतह पर कार्बन डाइऑक्साइड स्थिर करते हैं और उनके अवशेष बड़ी गहराइयों तक डूब जाते हैं","प्रवाल भित्तियाँ कार्बन डाइऑक्साइड को समुद्र तल पर चूना पत्थर में बंद कर देती हैं","कार्बन डाइऑक्साइड ठंडे जल में अधिक विलेय होती है, और ठंडा, सघन ध्रुवीय जल डूब जाता है","गर्म उष्णकटिबंधीय जल डूबता है और घुली कार्बन डाइऑक्साइड को अपने साथ नीचे ले जाता है"],"explanationHi":"ठंडा उच्च-अक्षांशीय जल अधिक CO₂ अवशोषित करता है और सघन होने के कारण गहरे महासागर में डूब जाता है। डूबता हुआ कार्बनिक पदार्थ अलग जैविक पंप है; गर्म जल नहीं डूबता।"},
  {"id":"env-ecology-567","question":"Ecological pyramids, also called Eltonian pyramids, were first described by:","options":["Charles Elton","Raymond Lindeman","Eugene Odum","Ernst Haeckel"],"answer":0,"explanation":"Charles Elton introduced the pyramid of numbers in his book Animal Ecology (1927). Lindeman later developed the trophic-dynamic concept of energy transfer.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"पारिस्थितिक पिरामिड, जिन्हें एल्टोनियन पिरामिड भी कहते हैं, का सर्वप्रथम वर्णन किसने किया?","optionsHi":["चार्ल्स एल्टन","रेमंड लिंडमैन","यूजीन ओडम","अर्नस्ट हैकेल"],"explanationHi":"चार्ल्स एल्टन ने अपनी पुस्तक एनिमल इकोलॉजी (1927) में संख्या पिरामिड प्रस्तुत किया। लिंडमैन ने बाद में ऊर्जा स्थानांतरण की पोषी-गतिकी अवधारणा विकसित की।"},
  {"id":"env-ecology-568","question":"Which of the following elements follow a sedimentary rather than a gaseous biogeochemical cycle? 1. Calcium 2. Potassium 3. Oxygen 4. Phosphorus. Select the correct answer:","options":["1, 2 and 4 only","1 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Calcium, potassium and phosphorus are stored mainly in rocks and soils. Oxygen, like carbon and nitrogen, has its main reservoir in the atmosphere and follows a gaseous cycle.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-से तत्व गैसीय के बजाय अवसादी जैव-भू-रासायनिक चक्र का अनुसरण करते हैं? 1. कैल्शियम 2. पोटैशियम 3. ऑक्सीजन 4. फॉस्फोरस। सही उत्तर चुनिए:","optionsHi":["केवल 1, 2 और 4","केवल 1 और 4","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"कैल्शियम, पोटैशियम और फॉस्फोरस मुख्यतः चट्टानों और मृदाओं में संचित रहते हैं। ऑक्सीजन का मुख्य भंडार, कार्बन और नाइट्रोजन की तरह, वायुमंडल में है और वह गैसीय चक्र का अनुसरण करती है।"},
  {"id":"env-ecology-569","question":"Plants absorb nitrogen from the soil mainly in the form of:","options":["Free nitrogen gas taken in through the stomata","Nitrite and nitrous oxide dissolved in soil water","Nitrate and ammonium ions dissolved in soil water","Amino acids released from decomposing humus"],"answer":2,"explanation":"Roots take up nitrogen mainly as NO₃⁻ and NH₄⁺. Plants cannot use N₂ directly, and nitrite is toxic and short-lived in well-aerated soil.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पौधे मृदा से नाइट्रोजन मुख्यतः किस रूप में अवशोषित करते हैं?","optionsHi":["रंध्रों से ली गई मुक्त नाइट्रोजन गैस","मृदा जल में घुले नाइट्राइट और नाइट्रस ऑक्साइड","मृदा जल में घुले नाइट्रेट और अमोनियम आयन","अपघटित होते ह्यूमस से मुक्त अमीनो अम्ल"],"explanationHi":"जड़ें नाइट्रोजन मुख्यतः NO₃⁻ और NH₄⁺ के रूप में लेती हैं। पौधे N₂ को सीधे उपयोग नहीं कर सकते, और नाइट्राइट अच्छी तरह हवादार मृदा में विषैला और अल्पजीवी होता है।"},
  {"id":"env-ecology-570","question":"The sharp rise in the oxygen content of the Earth's atmosphere about 2.4 billion years ago, the 'Great Oxidation Event', resulted mainly from:","options":["Splitting of water vapour by ultraviolet light in the upper atmosphere","Photosynthesis by cyanobacteria in the oceans","Release of oxygen gas from volcanic eruptions","Weathering of iron-rich rocks exposed on land"],"answer":1,"explanation":"Oxygenic photosynthesis by cyanobacteria built up free oxygen once natural sinks were saturated. Weathering of iron-rich rocks actually consumed oxygen, and volcanoes emit almost none.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"लगभग 2.4 अरब वर्ष पूर्व पृथ्वी के वायुमंडल की ऑक्सीजन मात्रा में तीव्र वृद्धि, 'महान ऑक्सीकरण घटना', मुख्यतः किसके कारण हुई?","optionsHi":["ऊपरी वायुमंडल में पराबैंगनी प्रकाश द्वारा जलवाष्प का विखंडन","महासागरों में सायनोबैक्टीरिया द्वारा प्रकाश संश्लेषण","ज्वालामुखी विस्फोटों से ऑक्सीजन गैस का निकलना","स्थल पर उजागर लौह-समृद्ध चट्टानों का अपक्षय"],"explanationHi":"सायनोबैक्टीरिया के ऑक्सीजनी प्रकाश संश्लेषण ने मुक्त ऑक्सीजन तब संचित की जब प्राकृतिक अवशोषक संतृप्त हो गए। लौह-समृद्ध चट्टानों का अपक्षय वास्तव में ऑक्सीजन की खपत करता था, और ज्वालामुखी लगभग कोई ऑक्सीजन नहीं छोड़ते।"},
  {"id":"env-ecology-571","question":"When urea is spread on the surface of an alkaline soil and not worked in, a large part of its nitrogen is lost to the air as ammonia gas. This loss is called:","options":["Denitrification","Volatilisation","Leaching","Immobilisation"],"answer":1,"explanation":"Urea hydrolyses to ammonium, which at high pH turns into ammonia gas and escapes: volatilisation. Denitrification loses nitrogen as N₂ or N₂O from nitrate under anaerobic conditions.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जब यूरिया को क्षारीय मृदा की सतह पर फैला दिया जाता है और उसे मिलाया नहीं जाता, तो उसकी नाइट्रोजन का बड़ा भाग अमोनिया गैस के रूप में वायु में नष्ट हो जाता है। इस हानि को कहते हैं:","optionsHi":["विनाइट्रीकरण","वाष्पशीलीकरण","निक्षालन","अचलीकरण (इम्मोबिलाइज़ेशन)"],"explanationHi":"यूरिया का जल-अपघटन अमोनियम बनाता है, जो उच्च pH पर अमोनिया गैस में बदलकर उड़ जाता है: वाष्पशीलीकरण। विनाइट्रीकरण में अवायवीय परिस्थितियों में नाइट्रेट से नाइट्रोजन N₂ या N₂O के रूप में नष्ट होती है।"},
  {"id":"env-ecology-572","question":"Which of the following are free-living (non-symbiotic) nitrogen-fixing micro-organisms? 1. Azotobacter 2. Clostridium 3. Rhizobium 4. Nostoc. Select the correct answer:","options":["1 and 3 only","1, 2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Azotobacter (aerobic), Clostridium (anaerobic) and the cyanobacterium Nostoc fix nitrogen while living freely. Rhizobium fixes significant nitrogen only inside legume root nodules.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-से मुक्तजीवी (असहजीवी) नाइट्रोजन-स्थिरीकारी सूक्ष्मजीव हैं? 1. एज़ोटोबैक्टर 2. क्लॉस्ट्रिडियम 3. राइज़ोबियम 4. नॉस्टॉक। सही उत्तर चुनिए:","optionsHi":["केवल 1 और 3","केवल 1, 2 और 4","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"एज़ोटोबैक्टर (वायवीय), क्लॉस्ट्रिडियम (अवायवीय) और सायनोबैक्टीरिया नॉस्टॉक मुक्त रहते हुए नाइट्रोजन स्थिर करते हैं। राइज़ोबियम उल्लेखनीय नाइट्रोजन केवल दलहनी जड़ ग्रंथिकाओं के भीतर स्थिर करता है।"},
  {"id":"env-ecology-573","question":"The pyramid of energy narrows at each higher trophic level because, in every transfer, some energy is degraded to heat. This is a consequence of:","options":["The first law of thermodynamics","The law of conservation of mass and energy","The second law of thermodynamics","The law of the minimum"],"answer":2,"explanation":"The second law says every energy conversion produces some unusable heat, so less energy is available at each step. The first law only says energy is conserved in total.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ऊर्जा पिरामिड प्रत्येक उच्चतर पोषी स्तर पर संकरा होता जाता है, क्योंकि प्रत्येक स्थानांतरण में कुछ ऊर्जा ऊष्मा में निम्नीकृत हो जाती है। यह किसका परिणाम है?","optionsHi":["ऊष्मागतिकी का प्रथम नियम","द्रव्य और ऊर्जा संरक्षण का नियम","ऊष्मागतिकी का द्वितीय नियम","न्यूनतम का नियम"],"explanationHi":"द्वितीय नियम कहता है कि प्रत्येक ऊर्जा रूपांतरण कुछ अनुपयोगी ऊष्मा उत्पन्न करता है, इसलिए प्रत्येक चरण पर कम ऊर्जा उपलब्ध रहती है। प्रथम नियम केवल यह कहता है कि कुल ऊर्जा संरक्षित रहती है।"},
  {"id":"env-ecology-574","question":"Plants normally take up sulphur from the soil in the form of:","options":["Hydrogen sulphide gas","Elemental sulphur","Sulphite ions","Sulphate ions"],"answer":3,"explanation":"Sulphate (SO₄²⁻) is the form absorbed by roots; elemental sulphur and sulphides must first be oxidised, for example by Thiobacillus. H₂S is toxic to most plants.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"पौधे सामान्यतः मृदा से सल्फर किस रूप में लेते हैं?","optionsHi":["हाइड्रोजन सल्फाइड गैस","मौलिक सल्फर","सल्फाइट आयन","सल्फेट आयन"],"explanationHi":"सल्फेट (SO₄²⁻) वह रूप है जिसे जड़ें अवशोषित करती हैं; मौलिक सल्फर और सल्फाइडों को पहले ऑक्सीकृत होना पड़ता है, जैसे थायोबैसिलस द्वारा। H₂S अधिकांश पौधों के लिए विषैली है।"},
  {"id":"env-ecology-575","question":"Methane released from wetlands and flooded rice fields is produced mainly by:","options":["Methanotrophic bacteria working in oxygen-rich surface water","Nitrifying bacteria working in well-drained soils","Cyanobacteria growing on the surface of the water","Methanogenic archaea working in oxygen-free mud"],"answer":3,"explanation":"Methanogenic archaea produce methane as they break down organic matter without oxygen. Methanotrophs do the opposite: they consume methane in oxygenated layers, reducing what escapes.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"आर्द्रभूमियों और जलमग्न धान के खेतों से निकलने वाली मीथेन मुख्यतः किसके द्वारा उत्पन्न होती है?","optionsHi":["ऑक्सीजन-समृद्ध सतही जल में कार्य करने वाले मीथेनोट्रॉफ़िक जीवाणु","अच्छी जल निकासी वाली मृदाओं में कार्य करने वाले नाइट्रीकारी जीवाणु","जल की सतह पर उगने वाले सायनोबैक्टीरिया","ऑक्सीजन-रहित कीचड़ में कार्य करने वाले मीथेनोजेनिक आर्किया"],"explanationHi":"मीथेनोजेनिक आर्किया ऑक्सीजन के बिना कार्बनिक पदार्थ का विघटन करते समय मीथेन बनाते हैं। मीथेनोट्रॉफ़ इसका उलटा करते हैं: वे ऑक्सीजनित परतों में मीथेन की खपत करते हैं, जिससे बाहर निकलने वाली मात्रा घटती है।"},
  {"id":"env-ecology-576","question":"Under the Plastic Waste Management Rules, 2016 as amended in 2021, the minimum thickness of plastic carry bags was raised in two steps. From 31 December 2022 the minimum thickness became:","options":["50 microns","75 microns","120 microns","150 microns"],"answer":2,"explanation":"The 2021 amendment raised the limit from 50 to 75 microns from 30 September 2021, and to 120 microns from 31 December 2022, so that thicker bags would be reused and be worth collecting.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"प्लास्टिक अपशिष्ट प्रबंधन नियम, 2016 (2021 में संशोधित) के अंतर्गत प्लास्टिक कैरी बैगों की न्यूनतम मोटाई दो चरणों में बढ़ाई गई। 31 दिसंबर 2022 से न्यूनतम मोटाई हो गई:","optionsHi":["50 माइक्रॉन","75 माइक्रॉन","120 माइक्रॉन","150 माइक्रॉन"],"explanationHi":"2021 के संशोधन ने सीमा को 50 से बढ़ाकर 30 सितंबर 2021 से 75 माइक्रॉन और 31 दिसंबर 2022 से 120 माइक्रॉन कर दिया, ताकि मोटे थैलों का पुनः उपयोग हो और उन्हें इकट्ठा करना सार्थक हो।"},
  {"id":"env-ecology-577","question":"Consider the following statements about the E-Waste (Management) Rules, 2016: 1. They brought compact fluorescent lamps and other mercury-containing lamps within their scope. 2. They provided for Producer Responsibility Organisations to help producers meet their collection duties. 3. They were framed under the Air (Prevention and Control of Pollution) Act, 1981. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The 2016 rules widened the scope to CFLs and mercury lamps, set EPR collection targets and introduced PROs. Like all waste rules, they were framed under the Environment (Protection) Act, 1986.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ई-अपशिष्ट (प्रबंधन) नियम, 2016 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इन्होंने कॉम्पैक्ट फ्लोरोसेंट लैंपों और पारा-युक्त अन्य लैंपों को अपने दायरे में लिया। 2. इनमें उत्पादकों को संग्रहण दायित्व पूरे करने में सहायता के लिए उत्पादक उत्तरदायित्व संगठनों का प्रावधान था। 3. इन्हें वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1981 के अंतर्गत बनाया गया था। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"2016 के नियमों ने दायरा CFL और पारा लैंपों तक बढ़ाया, EPR संग्रहण लक्ष्य निर्धारित किए और PRO की व्यवस्था की। सभी अपशिष्ट नियमों की तरह इन्हें भी पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत बनाया गया था।"},
  {"id":"env-ecology-578","question":"Match the e-waste component with the hazardous substance it is best known for. A. Cathode-ray tube glass  B. Fluorescent lamps and older LCD backlights  C. Nickel-based rechargeable batteries  D. Plastic casings and circuit boards; 1. Brominated flame retardants  2. Cadmium  3. Lead  4. Mercury","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-2, B-4, C-3, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"CRT glass contains several kilograms of lead, lamps and CCFL backlights contain mercury, Ni-Cd cells contain cadmium, and plastics are treated with brominated flame retardants that form dioxins when burnt.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"ई-अपशिष्ट घटक का उस हानिकारक पदार्थ से मिलान कीजिए जिसके लिए वह सबसे अधिक जाना जाता है। A. कैथोड-रे ट्यूब का काँच B. फ्लोरोसेंट लैंप और पुराने LCD बैकलाइट C. निकल-आधारित पुनरावेश्य बैटरियाँ D. प्लास्टिक के आवरण और परिपथ बोर्ड; 1. ब्रोमीनयुक्त ज्वालारोधी 2. कैडमियम 3. सीसा 4. पारा","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-2, B-4, C-3, D-1","A-3, B-4, C-2, D-1"],"explanationHi":"CRT काँच में कई किलोग्राम सीसा होता है, लैंपों और CCFL बैकलाइटों में पारा होता है, Ni-Cd सेलों में कैडमियम होता है, और प्लास्टिकों पर ब्रोमीनयुक्त ज्वालारोधी लगाए जाते हैं जो जलने पर डाइऑक्सिन बनाते हैं।"},
  {"id":"env-ecology-579","question":"Which one of the following statements about bioplastics is correct?","options":["Every plastic made from plant material breaks down quickly in both soil and water","A bio-based plastic need not be biodegradable; bio-polyethylene from cane is not","Polylactic acid (PLA) breaks down within a few weeks in ordinary seawater or soil","A plastic can be labelled biodegradable only if it is made from plant raw material"],"answer":1,"explanation":"'Bio-based' describes the raw material and 'biodegradable' describes the end of life. Bio-PE is chemically identical to fossil polyethylene, PLA needs industrial composting conditions, and some fossil-based plastics such as PBAT are biodegradable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जैव-प्लास्टिक के बारे में निम्नलिखित में से कौन-सा कथन सही है?","optionsHi":["पादप पदार्थ से बना प्रत्येक प्लास्टिक मृदा और जल दोनों में शीघ्र विघटित हो जाता है","जैव-आधारित प्लास्टिक का जैव-निम्नीकरणीय होना आवश्यक नहीं; गन्ने से बनी बायो-पॉलीएथिलीन नहीं होती","पॉलीलैक्टिक अम्ल (PLA) साधारण समुद्री जल या मृदा में कुछ सप्ताह में विघटित हो जाता है","प्लास्टिक को जैव-निम्नीकरणीय तभी कहा जा सकता है जब वह पादप कच्चे माल से बना हो"],"explanationHi":"'जैव-आधारित' कच्चे माल को और 'जैव-निम्नीकरणीय' जीवन के अंत को बताता है। बायो-PE रासायनिक रूप से जीवाश्म पॉलीएथिलीन के समान है, PLA को औद्योगिक कंपोस्टिंग परिस्थितियाँ चाहिए, और PBAT जैसे कुछ जीवाश्म-आधारित प्लास्टिक जैव-निम्नीकरणीय हैं।"},
  {"id":"env-ecology-580","question":"Environmental agencies have criticised 'oxo-degradable' plastics, which contain additives that make them break down on exposure to heat and light. The main criticism is that they:","options":["They need high-temperature industrial composting and do not break down in home compost","They are made from food crops such as maize, competing with food production for land","They fragment into microplastics instead of being fully broken down by microbes","They give off methane as they break down in landfills, adding to greenhouse emissions"],"answer":2,"explanation":"Pro-oxidant additives make conventional plastic brittle so it crumbles, but the fragments are not mineralised by microbes on a useful time scale and persist as microplastics. The composting and food-crop criticisms are tempting but apply to bio-based compostable plastics such as PLA, not to oxo-degradable polyethylene.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पर्यावरण एजेंसियों ने 'ऑक्सो-निम्नीकरणीय' प्लास्टिकों की आलोचना की है, जिनमें ऐसे योजक होते हैं जो उन्हें ऊष्मा और प्रकाश के संपर्क में विघटित कर देते हैं। मुख्य आलोचना यह है कि वे:","optionsHi":["उन्हें उच्च-तापमान औद्योगिक कंपोस्टिंग चाहिए और वे घरेलू कंपोस्ट में विघटित नहीं होते","वे मक्का जैसी खाद्य फसलों से बने होते हैं, जो भूमि के लिए खाद्य उत्पादन से प्रतिस्पर्धा करते हैं","वे सूक्ष्मजीवों द्वारा पूरी तरह विघटित होने के बजाय सूक्ष्म प्लास्टिक में टूट जाते हैं","भूभरावों में विघटित होते समय वे मीथेन छोड़ते हैं, जिससे हरितगृह उत्सर्जन बढ़ता है"],"explanationHi":"प्रो-ऑक्सीडेंट योजक सामान्य प्लास्टिक को भंगुर बना देते हैं जिससे वह बिखर जाता है, परंतु उसके टुकड़े उपयोगी समय-सीमा में सूक्ष्मजीवों द्वारा खनिजीकृत नहीं होते और सूक्ष्म प्लास्टिक के रूप में बने रहते हैं। कंपोस्टिंग और खाद्य-फसल वाली आलोचनाएँ आकर्षक हैं, पर वे PLA जैसे जैव-आधारित कंपोस्टेबल प्लास्टिकों पर लागू होती हैं, ऑक्सो-निम्नीकरणीय पॉलीएथिलीन पर नहीं।"},
  {"id":"env-ecology-581","question":"Shredded waste plastic is mixed into the hot stone aggregate when laying bituminous roads, a technique popularised in India. The method works mainly because the molten plastic:","options":["Coats the aggregate and improves its bond with bitumen and its water resistance","Burns off completely at the mixing temperature, leaving no plastic in the road","Replaces all of the bitumen, so that no petroleum product is needed for the road","Reacts chemically with the stone to form cement, so no other binder is required"],"answer":0,"explanation":"Plastic-coated aggregate bonds better with bitumen and absorbs less water, reducing potholes, while using up low-value plastic waste. The plastic is only a partial additive; bitumen is still the binder.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"बिटुमिनस सड़कें बिछाते समय गर्म पत्थर के रोड़ी (एग्रीगेट) में कतरा हुआ अपशिष्ट प्लास्टिक मिलाया जाता है, यह तकनीक भारत में लोकप्रिय हुई है। यह विधि मुख्यतः इसलिए कारगर है क्योंकि पिघला हुआ प्लास्टिक:","optionsHi":["रोड़ी पर परत चढ़ाता है और बिटुमेन के साथ उसका बंधन तथा जल-प्रतिरोध सुधारता है","मिश्रण के तापमान पर पूरी तरह जल जाता है, जिससे सड़क में कोई प्लास्टिक नहीं रहता","पूरे बिटुमेन का स्थान ले लेता है, इसलिए सड़क के लिए किसी पेट्रोलियम उत्पाद की आवश्यकता नहीं रहती","पत्थर से रासायनिक अभिक्रिया करके सीमेंट बना देता है, इसलिए किसी अन्य बंधक की आवश्यकता नहीं रहती"],"explanationHi":"प्लास्टिक-लेपित रोड़ी बिटुमेन के साथ बेहतर जुड़ती है और कम जल सोखती है, जिससे गड्ढे घटते हैं, और साथ ही कम मूल्य का प्लास्टिक अपशिष्ट खप जाता है। प्लास्टिक केवल आंशिक योजक है; बंधक अब भी बिटुमेन ही है।"},
  {"id":"env-ecology-582","question":"Which of the following is the most suitable measure to reduce wind erosion of soil in the arid parts of western Rajasthan?","options":["Building contour bunds and bench terraces across the steeper slopes","Flooding the fields through the winter to keep the topsoil wet and heavy","Deep ploughing of all fields at the start of the dry, windy summer season","Planting rows of trees and shrubs as shelterbelts across the wind"],"answer":3,"explanation":"Shelterbelts and windbreaks reduce wind speed near the ground and trap blowing sand. Contour bunds and terracing target water erosion on slopes, and ploughing before the windy season loosens the soil and worsens erosion.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"पश्चिमी राजस्थान के शुष्क भागों में मृदा के पवन अपरदन को घटाने का सबसे उपयुक्त उपाय निम्नलिखित में से कौन-सा है?","optionsHi":["अधिक तीव्र ढालों पर समोच्च रेखीय बाँध और सीढ़ीदार खेत बनाना","ऊपरी मृदा को नम और भारी रखने के लिए सर्दियों भर खेतों में पानी भरना","शुष्क, तेज़ हवा वाली गर्मी की ऋतु के आरंभ में सभी खेतों की गहरी जुताई करना","हवा के आर-पार रक्षक पट्टी के रूप में वृक्षों और झाड़ियों की पंक्तियाँ लगाना"],"explanationHi":"रक्षक पट्टियाँ और पवनरोधक भूमि के निकट पवन की चाल घटाते हैं और उड़ती रेत को रोकते हैं। समोच्च बाँध और सीढ़ीदार खेत ढालों पर जल अपरदन के लिए हैं, और तेज़ हवा की ऋतु से पहले जुताई मृदा को ढीला करके अपरदन को और बढ़ाती है।"},
  {"id":"env-ecology-583","question":"For most Indian soils and crops, the nitrogen–phosphorus–potassium (N:P:K) fertiliser use ratio generally recommended as balanced is about:","options":["1:2:4","4:2:1","2:1:4","8:4:1"],"answer":1,"explanation":"The commonly cited balanced ratio is 4:2:1. Heavily subsidised urea has pushed actual use far towards nitrogen, degrading soil health and contributing to nitrate pollution and nitrous oxide emissions.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अधिकांश भारतीय मृदाओं और फसलों के लिए नाइट्रोजन–फॉस्फोरस–पोटैशियम (N:P:K) उर्वरक उपयोग का सामान्यतः संतुलित अनुशंसित अनुपात लगभग है:","optionsHi":["1:2:4","4:2:1","2:1:4","8:4:1"],"explanationHi":"प्रायः उद्धृत संतुलित अनुपात 4:2:1 है। भारी रियायती यूरिया ने वास्तविक उपयोग को नाइट्रोजन की ओर बहुत खींच दिया है, जिससे मृदा स्वास्थ्य बिगड़ता है और नाइट्रेट प्रदूषण तथा नाइट्रस ऑक्साइड उत्सर्जन बढ़ता है।"},
  {"id":"env-ecology-584","question":"Parts of the Kerala coast around Karunagappally and Chavara have some of the highest natural background radiation in the world. This is because of:","options":["Fallout carried by monsoon winds from nuclear weapons tests","Leakage from the nuclear power station located on that coast","Thorium-bearing monazite in the beach sands of the area","Radon released from the oil and gas wells offshore"],"answer":2,"explanation":"The black sands of this coast are rich in monazite, which contains thorium. Kerala has no nuclear power station; the radiation is entirely natural.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"केरल तट के करुनागप्पल्ली और चवरा के आसपास के भागों में विश्व की सबसे अधिक प्राकृतिक पृष्ठभूमि विकिरण में से कुछ पाया जाता है। इसका कारण है:","optionsHi":["परमाणु हथियार परीक्षणों से मानसूनी हवाओं द्वारा लाया गया रेडियोधर्मी विकिरण पतन","उस तट पर स्थित परमाणु विद्युत केंद्र से रिसाव","क्षेत्र की समुद्र तट रेत में थोरियम-युक्त मोनाज़ाइट","अपतटीय तेल और गैस कुओं से निकलने वाली रेडॉन"],"explanationHi":"इस तट की काली रेत मोनाज़ाइट से समृद्ध है, जिसमें थोरियम होता है। केरल में कोई परमाणु विद्युत केंद्र नहीं है; यह विकिरण पूर्णतः प्राकृतिक है।"},
  {"id":"env-ecology-585","question":"Under the Bio-Medical Waste Management Rules, 2016, match the waste with the colour of its container. A. Human anatomical waste and soiled dressings  B. Contaminated recyclable items such as tubing, catheters and gloves  C. Broken or discarded glassware such as vials; 1. Blue  2. Yellow  3. Red","options":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"answer":3,"explanation":"Yellow bags take incinerable waste such as anatomical and soiled waste; red takes contaminated plastics that are to be recycled after disinfection; blue cardboard boxes take glassware and metal implants, and white puncture-proof containers take sharps.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जैव-चिकित्सा अपशिष्ट प्रबंधन नियम, 2016 के अंतर्गत अपशिष्ट का उसके कंटेनर के रंग से मिलान कीजिए। A. मानव शारीरिक अपशिष्ट और मैली पट्टियाँ B. संदूषित पुनःचक्रणीय वस्तुएँ जैसे नलिकाएँ, कैथेटर और दस्ताने C. टूटे या फेंके गए काँच के सामान जैसे शीशियाँ; 1. नीला 2. पीला 3. लाल","optionsHi":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"explanationHi":"पीले थैले भस्मीकरण योग्य अपशिष्ट जैसे शारीरिक और मैला अपशिष्ट लेते हैं; लाल थैले संदूषित प्लास्टिक लेते हैं जिन्हें कीटाणुशोधन के बाद पुनःचक्रित किया जाना है; नीले गत्ते के डिब्बे काँच के सामान और धातु प्रत्यारोपण लेते हैं, और सफ़ेद छिद्र-रोधी कंटेनर नुकीली वस्तुएँ (शार्प्स) लेते हैं।"},
  {"id":"env-ecology-586","question":"The gas collected from a mature municipal solid waste landfill consists mainly of:","options":["Methane and carbon dioxide in roughly equal proportions","Hydrogen sulphide with small amounts of ammonia","Carbon monoxide and nitrogen in roughly equal proportions","Nearly pure methane with traces of oxygen"],"answer":0,"explanation":"Anaerobic decomposition of organic waste gives landfill gas of roughly 45–60 per cent methane, the rest mainly CO2, with traces of H2S and other gases. It can be captured for energy; if vented it is a major methane source.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"एक परिपक्व नगरपालिका ठोस अपशिष्ट भूभराव से एकत्र की गई गैस में मुख्यतः क्या होता है?","optionsHi":["लगभग समान अनुपात में मीथेन और कार्बन डाइऑक्साइड","हाइड्रोजन सल्फाइड के साथ अल्प मात्रा में अमोनिया","लगभग समान अनुपात में कार्बन मोनोऑक्साइड और नाइट्रोजन","ऑक्सीजन के अंशों सहित लगभग शुद्ध मीथेन"],"explanationHi":"कार्बनिक अपशिष्ट के अवायवीय अपघटन से भूभराव गैस में लगभग 45–60 प्रतिशत मीथेन होती है, शेष मुख्यतः CO2, तथा H2S और अन्य गैसों के अंश। इसे ऊर्जा के लिए एकत्र किया जा सकता है; खुले में छोड़ने पर यह मीथेन का बड़ा स्रोत है।"},
  {"id":"env-ecology-587","question":"Several waste-to-energy incineration plants in Indian cities have run below capacity or needed extra fuel. The main technical reason is that unsegregated Indian municipal waste:","options":["Contains too much plastic, which melts in the furnace and blocks the grates","Is high in moisture, organics and inerts, so its calorific value is low","Has so much paper and cardboard that it burns too hot and damages the boilers","Contains almost no carbon at all, so it cannot release heat when it is burnt"],"answer":1,"explanation":"Wet kitchen waste, silt and debris make up a large share of Indian MSW, so it burns poorly without support fuel. Segregation, removing wet waste for composting or biogas, is the key to viable incineration.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारतीय शहरों में अनेक अपशिष्ट-से-ऊर्जा भस्मीकरण संयंत्र क्षमता से कम पर चले हैं या उन्हें अतिरिक्त ईंधन की आवश्यकता पड़ी है। इसका मुख्य तकनीकी कारण यह है कि अपृथक्कृत भारतीय नगरपालिका अपशिष्ट:","optionsHi":["में बहुत अधिक प्लास्टिक होता है, जो भट्टी में पिघलकर जालियों को अवरुद्ध कर देता है","में नमी, कार्बनिक पदार्थ और अक्रिय पदार्थ अधिक होते हैं, इसलिए उसका ऊष्मीय मान कम है","में इतना अधिक कागज़ और गत्ता होता है कि वह बहुत गर्म जलता है और बॉयलरों को हानि पहुँचाता है","में लगभग कोई कार्बन होता ही नहीं, इसलिए जलने पर वह ऊष्मा नहीं छोड़ सकता"],"explanationHi":"गीला रसोई कचरा, गाद और मलबा भारतीय MSW का बड़ा हिस्सा है, इसलिए सहायक ईंधन के बिना वह ठीक से नहीं जलता। पृथक्करण, यानी गीले अपशिष्ट को कंपोस्ट या बायोगैस के लिए अलग करना, भस्मीकरण को व्यवहार्य बनाने की कुंजी है।"},
  {"id":"env-ecology-588","question":"Refuse-derived fuel (RDF), increasingly used in cement kilns in India, is:","options":["Biogas produced by anaerobic digestion of the wet fraction of kitchen waste","Liquid fuel re-refined from used engine oil collected at garages and workshops","The dry, combustible fraction of waste, such as plastics and paper, shredded","Charcoal briquettes made by heating garden waste in the absence of air"],"answer":2,"explanation":"RDF is prepared by removing wet organics and inert material and shredding the high-calorific remainder. Cement kilns can 'co-process' it because their very high temperatures destroy pollutants and the ash is absorbed into clinker.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अपशिष्ट-व्युत्पन्न ईंधन (RDF), जिसका भारत में सीमेंट भट्टियों में प्रयोग बढ़ रहा है, क्या है?","optionsHi":["रसोई अपशिष्ट के गीले अंश के अवायवीय पाचन से उत्पन्न बायोगैस","गैरेजों और कार्यशालाओं से एकत्र प्रयुक्त इंजन तेल से पुनः परिष्कृत द्रव ईंधन","अपशिष्ट का शुष्क, दहनशील अंश, जैसे प्लास्टिक और कागज़, जिसे कतरा गया हो","वायु के अभाव में बगीचे के अपशिष्ट को गर्म करके बनाई गई चारकोल ब्रिकेट"],"explanationHi":"RDF गीले कार्बनिक और अक्रिय पदार्थ को हटाकर बचे उच्च ऊष्मीय मान वाले अंश को कतरकर तैयार किया जाता है। सीमेंट भट्टियाँ इसे 'सह-संसाधित' कर सकती हैं, क्योंकि उनके बहुत ऊँचे तापमान प्रदूषकों को नष्ट कर देते हैं और राख क्लिंकर में समा जाती है।"},
  {"id":"env-ecology-589","question":"'Biomining' of a legacy dumpsite, such as old garbage mountains in Indian cities, refers to:","options":["Extracting gold and copper from e-waste using bacteria inside sealed steel reactors","Capping the dumpsite with clay and planting grass on it so that it stops emitting gas","Injecting micro-organisms into the dump so that all of the waste is turned into methane","Digging out aged waste and sieving it into fines, recyclables and combustibles"],"answer":3,"explanation":"After bio-stabilisation, the old waste is dug out and sieved: the fine fraction is used as fill or soil, combustibles go as RDF, and inerts go to construction, freeing the land. Capping leaves the waste in place.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"किसी पुराने डंपसाइट का 'बायोमाइनिंग', जैसे भारतीय शहरों के पुराने कचरे के पहाड़, किसे कहते हैं?","optionsHi":["बंद स्टील रिएक्टरों के भीतर जीवाणुओं द्वारा ई-अपशिष्ट से सोना और ताँबा निकालना","डंपसाइट को मिट्टी से ढककर उस पर घास लगाना ताकि वह गैस उत्सर्जित करना बंद कर दे","डंप में सूक्ष्मजीव डालना ताकि सारा अपशिष्ट मीथेन में बदल जाए","पुराने अपशिष्ट को खोदकर निकालना और उसे महीन कणों, पुनःचक्रणीय और दहनशील पदार्थों में छानना"],"explanationHi":"जैव-स्थिरीकरण के बाद पुराना अपशिष्ट खोदकर निकाला और छाना जाता है: महीन अंश भराव या मृदा के रूप में प्रयुक्त होता है, दहनशील पदार्थ RDF के रूप में जाते हैं, और अक्रिय पदार्थ निर्माण में जाते हैं, जिससे भूमि मुक्त होती है। ढकने से अपशिष्ट अपनी जगह पर ही रहता है।"},
  {"id":"env-ecology-590","question":"Two identical machines each produce a noise level of 70 dB at a point when running alone. If both run together, the noise level at that point will be:","options":["140 dB","70 dB","about 73 dB","about 76 dB"],"answer":2,"explanation":"Decibels are logarithmic: doubling the sound intensity adds 10 log10(2), about 3 dB. So two equal 70 dB sources give about 73 dB, not 140 dB.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"दो एकसमान मशीनें अकेले चलने पर किसी बिंदु पर प्रत्येक 70 dB का ध्वनि स्तर उत्पन्न करती हैं। यदि दोनों साथ चलें, तो उस बिंदु पर ध्वनि स्तर होगा:","optionsHi":["140 dB","70 dB","लगभग 73 dB","लगभग 76 dB"],"explanationHi":"डेसिबल लघुगणकीय होते हैं: ध्वनि तीव्रता दोगुनी करने पर 10 log10(2), यानी लगभग 3 dB जुड़ता है। इसलिए दो बराबर 70 dB स्रोत लगभग 73 dB देते हैं, 140 dB नहीं।"},
  {"id":"env-ecology-591","question":"For a small, steady noise source in open air, the sound level falls by about how much each time the distance from the source is doubled?","options":["About 6 dB","About 3 dB","About 10 dB","About 20 dB"],"answer":0,"explanation":"Intensity from a point source falls with the square of distance, so doubling the distance cuts intensity to a quarter: 10 log10(4), about 6 dB. A 3 dB drop corresponds to halving the intensity.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"खुली हवा में किसी छोटे, स्थिर ध्वनि स्रोत के लिए, स्रोत से दूरी को हर बार दोगुना करने पर ध्वनि स्तर लगभग कितना घटता है?","optionsHi":["लगभग 6 dB","लगभग 3 dB","लगभग 10 dB","लगभग 20 dB"],"explanationHi":"बिंदु स्रोत से तीव्रता दूरी के वर्ग के अनुसार घटती है, इसलिए दूरी दोगुनी करने पर तीव्रता एक-चौथाई रह जाती है: 10 log10(4), यानी लगभग 6 dB। 3 dB की गिरावट तीव्रता के आधा होने के अनुरूप है।"},
  {"id":"env-ecology-592","question":"Organophosphate insecticides such as malathion largely replaced organochlorines such as DDT. Which of the following correctly compares the two groups?","options":["Organophosphates are more persistent and biomagnify more than organochlorines","Organophosphates break down faster, but many are more acutely toxic to people","Organochlorines are water-soluble and so are flushed quickly out of animal bodies","Both groups act only on insects and are harmless to birds and mammals"],"answer":1,"explanation":"Organochlorines are fat-soluble and persistent, hence biomagnification. Organophosphates degrade in days or weeks but inhibit the enzyme acetylcholinesterase and cause many acute poisonings among farm workers.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मैलाथियॉन जैसे ऑर्गेनोफॉस्फेट कीटनाशकों ने DDT जैसे ऑर्गेनोक्लोरीन कीटनाशकों का काफ़ी हद तक स्थान ले लिया। दोनों समूहों की तुलना निम्नलिखित में से कौन-सा सही करता है?","optionsHi":["ऑर्गेनोफॉस्फेट ऑर्गेनोक्लोरीन की तुलना में अधिक स्थायी होते हैं और अधिक जैव-आवर्धन करते हैं","ऑर्गेनोफॉस्फेट तेज़ी से विघटित होते हैं, परंतु अनेक मनुष्यों के लिए अधिक तीव्र विषैले होते हैं","ऑर्गेनोक्लोरीन जल में विलेय होते हैं, इसलिए जंतुओं के शरीर से शीघ्र बाहर निकल जाते हैं","दोनों समूह केवल कीटों पर कार्य करते हैं और पक्षियों तथा स्तनधारियों के लिए हानिरहित हैं"],"explanationHi":"ऑर्गेनोक्लोरीन वसा में विलेय और स्थायी होते हैं, इसीलिए जैव-आवर्धन होता है। ऑर्गेनोफॉस्फेट दिनों या सप्ताहों में निम्नीकृत होते हैं, परंतु एसिटाइलकोलिनेस्टरेज़ एंज़ाइम को संदमित करते हैं और खेत मज़दूरों में अनेक तीव्र विषाक्तता के मामले उत्पन्न करते हैं।"},
  {"id":"env-ecology-593","question":"India's Recycling of Ships Act, 2019, which governs ship-breaking yards such as Alang in Gujarat, was enacted in line with which international convention?","options":["The Basel Convention on hazardous wastes","The MARPOL Convention on pollution from ships","The Rotterdam Convention on prior informed consent","The Hong Kong Convention on ship recycling"],"answer":3,"explanation":"India acceded to the Hong Kong International Convention for the Safe and Environmentally Sound Recycling of Ships (2009) in 2019 and passed the Act alongside. Basel deals with hazardous waste trade in general, and MARPOL with pollution from operating ships.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत का जहाज़ पुनःचक्रण अधिनियम, 2019, जो गुजरात के अलंग जैसे जहाज़ तोड़ने के यार्डों का नियमन करता है, किस अंतर्राष्ट्रीय अभिसमय के अनुरूप बनाया गया?","optionsHi":["खतरनाक अपशिष्टों पर बेसल अभिसमय","जहाज़ों से प्रदूषण पर MARPOL अभिसमय","पूर्व सूचित सहमति पर रॉटरडैम अभिसमय","जहाज़ पुनःचक्रण पर हॉन्गकॉन्ग अभिसमय"],"explanationHi":"भारत ने 2019 में जहाज़ों के सुरक्षित और पर्यावरण-अनुकूल पुनःचक्रण के लिए हॉन्गकॉन्ग अंतर्राष्ट्रीय अभिसमय (2009) को अपनाया और साथ ही यह अधिनियम पारित किया। बेसल सामान्यतः खतरनाक अपशिष्ट के व्यापार से संबंधित है और MARPOL संचालित जहाज़ों से प्रदूषण से।"},
  {"id":"env-ecology-594","question":"Some plants take up selenium or mercury from contaminated soil, convert it into volatile compounds and release them into the air through their leaves. This form of phytoremediation is called:","options":["Phytovolatilisation","Phytostabilisation","Rhizofiltration","Phytoextraction"],"answer":0,"explanation":"In phytovolatilisation the contaminant leaves through the plant as a gas. Phytoextraction stores metals in harvestable shoots, phytostabilisation locks them in the root zone, and rhizofiltration uses roots to absorb pollutants from water.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कुछ पौधे संदूषित मृदा से सेलेनियम या पारा अवशोषित करते हैं, उसे वाष्पशील यौगिकों में बदल देते हैं और अपनी पत्तियों से वायु में छोड़ देते हैं। फाइटोरेमेडिएशन (पादप उपचार) के इस रूप को कहते हैं:","optionsHi":["फाइटोवोलेटिलाइज़ेशन (पादप वाष्पीकरण)","फाइटोस्टेबिलाइज़ेशन (पादप स्थिरीकरण)","राइज़ोफिल्ट्रेशन (मूल निस्यंदन)","फाइटोएक्सट्रैक्शन (पादप निष्कर्षण)"],"explanationHi":"फाइटोवोलेटिलाइज़ेशन में संदूषक पौधे से होकर गैस के रूप में निकल जाता है। फाइटोएक्सट्रैक्शन धातुओं को कटाई योग्य प्ररोहों में संचित करता है, फाइटोस्टेबिलाइज़ेशन उन्हें जड़ क्षेत्र में बाँध देता है, और राइज़ोफिल्ट्रेशन जड़ों से जल के प्रदूषकों को अवशोषित करता है।"},
  {"id":"env-ecology-595","question":"In the resin identification codes printed inside the recycling triangle on plastic items, code 3 denotes:","options":["Polyethylene terephthalate (PET)","Polyvinyl chloride (PVC)","High-density polyethylene (HDPE)","Polystyrene (PS)"],"answer":1,"explanation":"The codes are 1 PET, 2 HDPE, 3 PVC, 4 LDPE, 5 PP, 6 PS and 7 others. PVC is the hardest common plastic to recycle and releases hydrogen chloride and dioxins when burnt.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"प्लास्टिक की वस्तुओं पर पुनःचक्रण त्रिभुज के भीतर छपे रेज़िन पहचान कोडों में कोड 3 का अर्थ है:","optionsHi":["पॉलीएथिलीन टेरेफ्थेलेट (PET)","पॉलीविनाइल क्लोराइड (PVC)","उच्च-घनत्व पॉलीएथिलीन (HDPE)","पॉलीस्टाइरीन (PS)"],"explanationHi":"कोड हैं: 1 PET, 2 HDPE, 3 PVC, 4 LDPE, 5 PP, 6 PS और 7 अन्य। PVC सामान्य प्लास्टिकों में पुनःचक्रण के लिए सबसे कठिन है और जलने पर हाइड्रोजन क्लोराइड तथा डाइऑक्सिन छोड़ता है।"},
  {"id":"env-ecology-596","question":"Integrated Pest Management (IPM), promoted in India as a way to cut pesticide use, is best described as:","options":["Spraying a fixed calendar of pesticides every season so that pests never get a chance to appear","Banning all chemical pesticides and relying entirely on genetically modified, pest-resistant crops","Using cultural, biological and mechanical controls, with chemicals only past a pest threshold","Rotating different chemical pesticides each season so that pests cannot build up resistance to any"],"answer":2,"explanation":"IPM uses crop rotation, resistant varieties, natural enemies such as Trichoderma or Trichogramma, traps and monitoring, and allows chemicals only when pests exceed an economic threshold level.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"एकीकृत नाशीजीव प्रबंधन (IPM), जिसे भारत में कीटनाशकों का उपयोग घटाने के उपाय के रूप में बढ़ावा दिया जाता है, का सबसे उपयुक्त वर्णन है:","optionsHi":["हर मौसम में कीटनाशकों का निश्चित कैलेंडर के अनुसार छिड़काव, ताकि नाशीजीवों को कभी पनपने का अवसर न मिले","सभी रासायनिक कीटनाशकों पर प्रतिबंध लगाकर पूरी तरह आनुवंशिक रूप से संशोधित, नाशीजीव-प्रतिरोधी फसलों पर निर्भर रहना","सांस्कृतिक, जैविक और यांत्रिक नियंत्रण का उपयोग, तथा रसायनों का प्रयोग केवल नाशीजीव सीमा-स्तर पार होने पर","हर मौसम अलग-अलग रासायनिक कीटनाशकों का चक्रण, ताकि नाशीजीव किसी एक के प्रति प्रतिरोध न बना सकें"],"explanationHi":"IPM में फसल चक्र, प्रतिरोधी किस्में, ट्राइकोडर्मा या ट्राइकोग्रामा जैसे प्राकृतिक शत्रु, जाल और निगरानी का उपयोग होता है, और रसायनों की अनुमति तभी दी जाती है जब नाशीजीव आर्थिक सीमा-स्तर से ऊपर हो जाएँ।"},
  {"id":"env-ecology-597","question":"Which feature distinguishes a properly engineered sanitary landfill from an open dump?","options":["Waste is burnt in the open every few days to reduce its volume and smell","Waste is spread thinly over a large area so that it dries quickly in the sun","Only wet kitchen waste is accepted, while all dry waste is sent elsewhere","An impermeable liner, leachate collection and a daily soil cover"],"answer":3,"explanation":"Liners and leachate collection protect groundwater, daily cover controls odour, flies and fires, and gas can be vented or captured. Open dumps have none of these and often catch fire.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"कौन-सी विशेषता उचित रूप से अभियांत्रिक स्वच्छता भूभराव (सैनिटरी लैंडफिल) को खुले डंप से अलग करती है?","optionsHi":["आयतन और दुर्गंध घटाने के लिए हर कुछ दिन में अपशिष्ट को खुले में जलाया जाता है","अपशिष्ट को बड़े क्षेत्र में पतला फैलाया जाता है ताकि वह धूप में शीघ्र सूख जाए","केवल गीला रसोई अपशिष्ट स्वीकार किया जाता है, जबकि सारा शुष्क अपशिष्ट कहीं और भेजा जाता है","अपारगम्य अस्तर, निक्षालित द्रव (लीचेट) संग्रहण और प्रतिदिन मिट्टी का आवरण"],"explanationHi":"अस्तर और लीचेट संग्रहण भूजल की रक्षा करते हैं, दैनिक आवरण दुर्गंध, मक्खियों और आग को नियंत्रित करता है, और गैस को निकाला या एकत्र किया जा सकता है। खुले डंपों में इनमें से कुछ नहीं होता और उनमें प्रायः आग लग जाती है।"},
  {"id":"env-ecology-598","question":"Consider the following statements about the Hazardous and Other Wastes (Management and Transboundary Movement) Rules, 2016: 1. They were framed under the Environment (Protection) Act, 1986. 2. Import of hazardous and other wastes into India for disposal is not permitted. 3. They regulate transboundary movement of hazardous waste in line with the Basel Convention. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":2,"explanation":"All three are correct. The rules allow import only for recycling, recovery or reuse with permission, never for disposal, and they give effect to India's obligations under the Basel Convention.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"खतरनाक और अन्य अपशिष्ट (प्रबंधन और सीमापारीय संचलन) नियम, 2016 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इन्हें पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत बनाया गया था। 2. निपटान के लिए खतरनाक और अन्य अपशिष्टों का भारत में आयात अनुमत नहीं है। 3. ये बेसल अभिसमय के अनुरूप खतरनाक अपशिष्ट के सीमापारीय संचलन का विनियमन करते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1 और 3"],"explanationHi":"तीनों सही हैं। नियम आयात की अनुमति केवल अनुमति के साथ पुनःचक्रण, पुनःप्राप्ति या पुनः उपयोग के लिए देते हैं, निपटान के लिए कभी नहीं, और वे बेसल अभिसमय के अंतर्गत भारत के दायित्वों को प्रभावी बनाते हैं।"},
  {"id":"env-ecology-599","question":"Strontium-90, released by nuclear weapon tests and reactor accidents, is especially dangerous because it:","options":["Collects in the thyroid gland in place of iodine","Mimics calcium and is stored in bones and teeth","Is a gas that is breathed in and lodges in the lungs","Concentrates in body fat in the same way as DDT"],"answer":1,"explanation":"Strontium is chemically similar to calcium, so Sr-90 enters milk and is deposited in bone, where it irradiates the marrow for years (half-life about 29 years). The thyroid hazard comes from iodine-131.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"परमाणु हथियार परीक्षणों और रिएक्टर दुर्घटनाओं से निकलने वाला स्ट्रॉन्शियम-90 विशेष रूप से खतरनाक इसलिए है क्योंकि वह:","optionsHi":["आयोडीन के स्थान पर थायरॉइड ग्रंथि में एकत्र हो जाता है","कैल्शियम की नकल करता है और हड्डियों तथा दाँतों में संचित हो जाता है","एक गैस है जिसे साँस के साथ लिया जाता है और जो फेफड़ों में जम जाती है","DDT की तरह शरीर की वसा में सांद्रित हो जाता है"],"explanationHi":"स्ट्रॉन्शियम रासायनिक रूप से कैल्शियम के समान है, इसलिए Sr-90 दूध में पहुँचता है और हड्डी में जमा हो जाता है, जहाँ वह वर्षों तक अस्थि-मज्जा को विकिरणित करता है (अर्धायु लगभग 29 वर्ष)। थायरॉइड का खतरा आयोडीन-131 से आता है।"},
  {"id":"env-ecology-600","question":"Tributyltin (TBT), once used in anti-fouling paints on ship hulls, was banned under an IMO convention mainly because it:","options":["Disrupts hormones in marine snails, causing females to develop male organs","Corrodes the steel of ship hulls from outside and causes fuel oil to leak into the sea","Depletes the ozone layer when it slowly evaporates from freshly painted surfaces","Raises the acidity of harbour water enough to dissolve nearby coral reefs and shells"],"answer":0,"explanation":"Even at a few nanograms per litre, TBT causes 'imposex' in dog whelks and other gastropods, collapsing their populations. The IMO's AFS Convention (2001) banned organotin anti-fouling paints.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"ट्राइब्यूटिलटिन (TBT), जिसका कभी जहाज़ों के पेंदे के फाउलिंग-रोधी रंगों में उपयोग होता था, IMO के एक अभिसमय के अंतर्गत मुख्यतः इसलिए प्रतिबंधित किया गया क्योंकि वह:","optionsHi":["समुद्री घोंघों में हार्मोन बिगाड़ता है, जिससे मादाओं में नर अंग विकसित हो जाते हैं","जहाज़ के पेंदे के स्टील को बाहर से संक्षारित करता है और ईंधन तेल को समुद्र में रिसवा देता है","ताज़ा रंगी गई सतहों से धीरे-धीरे वाष्पित होते समय ओज़ोन परत को क्षीण करता है","बंदरगाह के जल की अम्लता इतनी बढ़ा देता है कि पास की प्रवाल भित्तियाँ और कवच घुल जाते हैं"],"explanationHi":"प्रति लीटर कुछ नैनोग्राम पर भी TBT डॉग व्हेल्क और अन्य गैस्ट्रोपॉडों में 'इम्पोसेक्स' उत्पन्न करता है, जिससे उनकी समष्टियाँ ढह जाती हैं। IMO के AFS अभिसमय (2001) ने ऑर्गेनोटिन फाउलिंग-रोधी रंगों पर प्रतिबंध लगाया।"},
  {"id":"env-ecology-601","question":"In a xerosere developing on bare rock, the very first (pioneer) stage is usually formed by:","options":["Foliose lichens","Crustose lichens","Mosses","Annual herbs"],"answer":1,"explanation":"Crustose lichens, pressed flat against the rock, secrete acids that start weathering it; foliose lichens follow, then mosses, herbs, shrubs and finally trees.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"नंगी चट्टान पर विकसित होने वाली मरुद्भिदी अनुक्रमण (ज़ेरोसियर) में सबसे पहला (अग्रणी) चरण सामान्यतः किसके द्वारा बनता है?","optionsHi":["पर्णिल (फोलियोज़) लाइकेन","पर्पटीय (क्रस्टोज़) लाइकेन","मॉस","एकवर्षी शाक"],"explanationHi":"चट्टान से चिपके पर्पटीय लाइकेन अम्ल स्रावित करके उसका अपक्षय आरंभ करते हैं; उसके बाद पर्णिल लाइकेन, फिर मॉस, शाक, झाड़ियाँ और अंत में वृक्ष आते हैं।"},
  {"id":"env-ecology-602","question":"Arrange the following stages of a hydrosere in the order in which they replace one another in a filling pond: 1. Reed-swamp stage (Typha, Phragmites) 2. Rooted floating stage (Nymphaea, Trapa) 3. Rooted submerged stage (Hydrilla, Vallisneria) 4. Sedge-meadow stage","options":["2-3-1-4","3-2-4-1","3-2-1-4","2-3-4-1"],"answer":2,"explanation":"After phytoplankton, rooted submerged plants raise the bottom, then rooted floating plants, then amphibious reed-swamp species, then sedges on the near-dry margin, before woodland takes over.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भरते हुए तालाब में जलीय अनुक्रमण (हाइड्रोसियर) के निम्नलिखित चरणों को उस क्रम में व्यवस्थित कीजिए जिसमें वे एक-दूसरे का स्थान लेते हैं: 1. नरकुल-दलदल चरण (टाइफा, फ्रैग्माइटीज़) 2. जड़ित तैरता चरण (निम्फिया, ट्रापा) 3. जड़ित निमग्न चरण (हाइड्रिला, वैलिस्नेरिया) 4. सेज-चरागाह चरण","optionsHi":["2-3-1-4","3-2-4-1","3-2-1-4","2-3-4-1"],"explanationHi":"फाइटोप्लैंकटन के बाद जड़ित निमग्न पौधे तल को ऊँचा करते हैं, फिर जड़ित तैरते पौधे, फिर उभयचर नरकुल-दलदल की प्रजातियाँ, फिर लगभग शुष्क किनारे पर सेज, और अंत में वन भूमि आ जाती है।"},
  {"id":"env-ecology-603","question":"The entire sequence of communities that replace one another in a given area during ecological succession is called a:","options":["Sere","Biome","Ecotone","Ecocline"],"answer":0,"explanation":"A sere is the whole sequence; each transitional community is a seral stage. An ecotone is a boundary zone between two communities, and an ecocline a gradual change along a gradient.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"पारिस्थितिक अनुक्रमण के दौरान किसी दिए गए क्षेत्र में एक-दूसरे का स्थान लेने वाले समुदायों के संपूर्ण अनुक्रम को क्या कहते हैं?","optionsHi":["सियर (अनुक्रम श्रेणी)","बायोम","इकोटोन (पारिस्थितिक संक्रमण क्षेत्र)","इकोक्लाइन"],"explanationHi":"सियर संपूर्ण अनुक्रम है; प्रत्येक संक्रमणकालीन समुदाय एक सीरल चरण है। इकोटोन दो समुदायों के बीच की सीमा पट्टी है, और इकोक्लाइन किसी प्रवणता के अनुदिश क्रमिक परिवर्तन है।"},
  {"id":"env-ecology-604","question":"The view that a region can have several stable climax communities, controlled by local soil, drainage and topography as well as by climate, is called the:","options":["Monoclimax theory of Clements","Climax-pattern hypothesis of Whittaker","Individualistic concept of Gleason","Polyclimax theory of Tansley"],"answer":3,"explanation":"Tansley's polyclimax theory allowed many climaxes in one climatic region. Clements held that climate alone sets a single climax, and Whittaker saw climax as a continuous pattern along gradients.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"यह मत कि किसी क्षेत्र में स्थानीय मृदा, जल निकास और भू-आकृति तथा जलवायु द्वारा नियंत्रित अनेक स्थिर चरम समुदाय हो सकते हैं, कहलाता है:","optionsHi":["क्लेमेंट्स का एकल चरम (मोनोक्लाइमैक्स) सिद्धांत","व्हिटेकर की चरम-प्रतिरूप परिकल्पना","ग्लीसन की व्यक्तिवादी संकल्पना","टैन्सले का बहु-चरम (पॉलीक्लाइमैक्स) सिद्धांत"],"explanationHi":"टैन्सले के बहु-चरम सिद्धांत ने एक ही जलवायु क्षेत्र में अनेक चरम समुदायों की अनुमति दी। क्लेमेंट्स का मत था कि केवल जलवायु एक ही चरम निर्धारित करती है, और व्हिटेकर ने चरम को प्रवणताओं के अनुदिश एक सतत प्रतिरूप के रूप में देखा।"},
  {"id":"env-ecology-605","question":"Consider the following statements about the models of succession proposed by Connell and Slatyer: 1. In the facilitation model, early species modify the site and make it more suitable for later species. 2. In the inhibition model, early species hold the site and hinder later ones until they die or are damaged. 3. In the tolerance model, later species can establish only after early species have modified the site for them. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Statement 3 describes facilitation, not tolerance. In the tolerance model, later species are neither helped nor hindered much by earlier ones; they simply tolerate lower resource levels and come to dominate.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कोनेल और स्लेटियर द्वारा प्रस्तावित अनुक्रमण के मॉडलों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. सुगमता मॉडल में आरंभिक प्रजातियाँ स्थल को बदलकर उसे परवर्ती प्रजातियों के लिए अधिक उपयुक्त बना देती हैं। 2. संदमन मॉडल में आरंभिक प्रजातियाँ स्थल पर अधिकार जमाए रखती हैं और परवर्ती प्रजातियों को तब तक रोकती हैं जब तक वे मर न जाएँ या क्षतिग्रस्त न हों। 3. सहनशीलता मॉडल में परवर्ती प्रजातियाँ तभी स्थापित हो सकती हैं जब आरंभिक प्रजातियाँ स्थल को उनके लिए बदल दें। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"कथन 3 सुगमता का वर्णन करता है, सहनशीलता का नहीं। सहनशीलता मॉडल में परवर्ती प्रजातियों को पूर्ववर्तियों से न अधिक सहायता मिलती है न बाधा; वे केवल कम संसाधन स्तरों को सहन करती हैं और प्रभावी हो जाती हैं।"},
  {"id":"env-ecology-606","question":"A small lake gradually turns into marsh because a deforested catchment upstream washes large amounts of silt into it every monsoon. This change is an example of:","options":["Allogenic succession","Autogenic succession","Primary succession on rock","Retrogressive succession"],"answer":0,"explanation":"Allogenic succession is driven by forces from outside the community, here silt from the catchment. Autogenic succession is driven by the organisms themselves, for example by the build-up of their own dead remains.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"एक छोटी झील धीरे-धीरे दलदल में बदल जाती है क्योंकि ऊपरी प्रवाह का वनविहीन जलग्रहण क्षेत्र हर मानसून में उसमें बहुत सारी गाद बहा लाता है। यह परिवर्तन किसका उदाहरण है?","optionsHi":["बाह्यजनित अनुक्रमण (एलोजेनिक सक्सेशन)","स्वजनित अनुक्रमण (ऑटोजेनिक सक्सेशन)","चट्टान पर प्राथमिक अनुक्रमण","प्रतिगामी अनुक्रमण"],"explanationHi":"बाह्यजनित अनुक्रमण समुदाय के बाहर की शक्तियों से चलता है, यहाँ जलग्रहण क्षेत्र की गाद। स्वजनित अनुक्रमण जीवों द्वारा स्वयं चलाया जाता है, जैसे अपने ही मृत अवशेषों के जमाव से।"},
  {"id":"env-ecology-607","question":"Succession on a fallen, decaying log, or in a stream receiving organic sewage, where heterotrophs dominate and community respiration exceeds production, is known as:","options":["Autotrophic succession","Heterotrophic succession","Secondary succession","Cyclic succession"],"answer":1,"explanation":"In heterotrophic succession the P/R ratio is below 1 and the community runs down a stock of organic matter. Autotrophic succession, as on new land, begins with green plants and P/R above 1.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"किसी गिरे, सड़ते लट्ठे पर या कार्बनिक मलजल प्राप्त करने वाली धारा में अनुक्रमण, जहाँ विषमपोषी प्रभावी होते हैं और समुदाय का श्वसन उत्पादन से अधिक होता है, क्या कहलाता है?","optionsHi":["स्वपोषी अनुक्रमण","विषमपोषी अनुक्रमण","द्वितीयक अनुक्रमण","चक्रीय अनुक्रमण"],"explanationHi":"विषमपोषी अनुक्रमण में P/R अनुपात 1 से कम होता है और समुदाय कार्बनिक पदार्थ के भंडार को घटाता जाता है। स्वपोषी अनुक्रमण, जैसे नई भूमि पर, हरे पौधों से शुरू होता है और P/R 1 से अधिक होता है।"},
  {"id":"env-ecology-608","question":"Which of the following are generally observed as ecological succession proceeds towards a climax? 1. Total biomass increases. 2. Net community productivity reaches its highest value at the climax. 3. The ratio of gross production to community respiration approaches 1. 4. Nutrient cycles become more closed, with fewer losses. Select the correct answer:","options":["1 and 2 only","2, 3 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"Mature communities store more biomass, recycle nutrients tightly and spend almost all their production on respiration, so P/R nears 1. Net community production is therefore highest in developing stages, not at the climax.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जैसे-जैसे पारिस्थितिक अनुक्रमण चरम की ओर बढ़ता है, निम्नलिखित में से क्या सामान्यतः देखा जाता है? 1. कुल जैवभार बढ़ता है। 2. शुद्ध समुदाय उत्पादकता चरम पर अपने उच्चतम मान पर पहुँचती है। 3. सकल उत्पादन और समुदाय श्वसन का अनुपात 1 के निकट पहुँचता है। 4. पोषक चक्र अधिक बंद हो जाते हैं, जिनमें हानियाँ कम होती हैं। सही उत्तर चुनिए:","optionsHi":["केवल 1 और 2","केवल 2, 3 और 4","केवल 1, 3 और 4","1, 2, 3 और 4"],"explanationHi":"परिपक्व समुदाय अधिक जैवभार संचित करते हैं, पोषक तत्वों का कसकर पुनःचक्रण करते हैं और अपने लगभग सारे उत्पादन को श्वसन में खर्च कर देते हैं, इसलिए P/R 1 के निकट पहुँचता है। अतः शुद्ध समुदाय उत्पादन विकासशील चरणों में सर्वाधिक होता है, चरम पर नहीं।"},
  {"id":"env-ecology-609","question":"Which one of the following is an attribute of a population but NOT of an individual organism?","options":["Body size","Metabolic rate","Life span","Sex ratio"],"answer":3,"explanation":"Sex ratio, like birth rate, death rate and age distribution, exists only for a group. An individual has a size, a metabolic rate and a life span, but no ratio of sexes.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सा समष्टि का गुण है, परंतु किसी व्यक्तिगत जीव का नहीं?","optionsHi":["शरीर का आकार","उपापचय दर","जीवन काल","लिंग अनुपात"],"explanationHi":"लिंग अनुपात, जन्म दर, मृत्यु दर और आयु वितरण की तरह, केवल किसी समूह के लिए होता है। किसी व्यक्ति का आकार, उपापचय दर और जीवन काल होता है, परंतु लिंगों का अनुपात नहीं।"},
  {"id":"env-ecology-610","question":"A deer population of 500 records, over one year, 60 births, 40 deaths, 20 animals arriving from outside and 30 animals leaving. What is the population at the end of the year?","options":["520","530","510","490"],"answer":2,"explanation":"Nₜ₊₁ = Nₜ + (B + I) − (D + E) = 500 + (60 + 20) − (40 + 30) = 510. Ignoring migration gives 520, and swapping immigration with emigration gives 530.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"500 की हिरण समष्टि एक वर्ष में 60 जन्म, 40 मृत्यु, बाहर से आए 20 जंतु और चले गए 30 जंतु दर्ज करती है। वर्ष के अंत में समष्टि कितनी है?","optionsHi":["520","530","510","490"],"explanationHi":"Nₜ₊₁ = Nₜ + (B + I) − (D + E) = 500 + (60 + 20) − (40 + 30) = 510। प्रवास को अनदेखा करने पर 520 आता है, और अप्रवास तथा उत्प्रवास को आपस में बदलने पर 530।"},
  {"id":"env-ecology-611","question":"Under logistic (S-shaped) growth, the number of individuals added to a population per unit time is greatest when the population size N is:","options":["Very small, just after colonisation","About one-quarter of carrying capacity","About half of carrying capacity","Equal to carrying capacity"],"answer":2,"explanation":"dN/dt = rN(K − N)/K is a parabola in N with its peak at N = K/2. Near zero there are too few breeders; near K the brake (K − N)/K approaches zero.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"लॉजिस्टिक (S-आकार) वृद्धि के अंतर्गत प्रति इकाई समय में समष्टि में जुड़ने वाले व्यक्तियों की संख्या सर्वाधिक तब होती है जब समष्टि आकार N होता है:","optionsHi":["बहुत छोटा, बसने के ठीक बाद","वहन क्षमता का लगभग एक-चौथाई","वहन क्षमता का लगभग आधा","वहन क्षमता के बराबर"],"explanationHi":"dN/dt = rN(K − N)/K, N का एक परवलय है जिसका शिखर N = K/2 पर है। शून्य के निकट प्रजनन करने वाले बहुत कम होते हैं; K के निकट रोक (K − N)/K शून्य की ओर जाती है।"},
  {"id":"env-ecology-612","question":"A population follows logistic growth with r = 0.2 per year and carrying capacity K = 1,000. When N = 250, how many individuals are added per year?","options":["50","12.5","150","37.5"],"answer":3,"explanation":"dN/dt = rN(K − N)/K = 0.2 × 250 × 750/1,000 = 37.5. The trap 50 ignores the logistic brake, 12.5 uses N/K instead of (K − N)/K, and 150 multiplies r by (K − N).","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"एक समष्टि r = 0.2 प्रति वर्ष और वहन क्षमता K = 1,000 के साथ लॉजिस्टिक वृद्धि का अनुसरण करती है। जब N = 250 है, तब प्रति वर्ष कितने व्यक्ति जुड़ते हैं?","optionsHi":["50","12.5","150","37.5"],"explanationHi":"dN/dt = rN(K − N)/K = 0.2 × 250 × 750/1,000 = 37.5। 50 का भ्रम वाला उत्तर लॉजिस्टिक रोक को अनदेखा करता है, 12.5 में (K − N)/K के स्थान पर N/K लिया गया है, और 150 में r को (K − N) से गुणा किया गया है।"},
  {"id":"env-ecology-613","question":"In very small populations of some species, survival and breeding success fall because individuals cannot find mates or defend themselves in groups. This phenomenon is called the:","options":["Allee effect","Founder effect","Edge effect","Bottleneck effect"],"answer":0,"explanation":"The Allee effect is a fall in per-capita growth at low density, which can push small populations to extinction. The founder and bottleneck effects describe loss of genetic variation, not of growth rate.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"कुछ प्रजातियों की बहुत छोटी समष्टियों में उत्तरजीविता और प्रजनन सफलता घट जाती है क्योंकि व्यक्ति साथी नहीं खोज पाते या समूह में अपनी रक्षा नहीं कर पाते। इस परिघटना को कहते हैं:","optionsHi":["एली प्रभाव","संस्थापक प्रभाव","किनारा प्रभाव","अड़चन (बॉटलनेक) प्रभाव"],"explanationHi":"एली प्रभाव कम घनत्व पर प्रति-व्यक्ति वृद्धि में गिरावट है, जो छोटी समष्टियों को विलुप्ति की ओर धकेल सकती है। संस्थापक और बॉटलनेक प्रभाव आनुवंशिक विविधता की हानि का वर्णन करते हैं, वृद्धि दर का नहीं।"},
  {"id":"env-ecology-614","question":"Which of the following act on a population as density-dependent factors? 1. Spread of an infectious disease 2. A severe, unseasonal frost 3. Competition for limited food 4. A forest fire started by lightning. Select the correct answer:","options":["1 and 3 only","2 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Disease spreads and competition intensifies as crowding rises, so their effect depends on density. Frost and a lightning fire kill a similar proportion whatever the density, so they are density-independent.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-से समष्टि पर घनत्व-निर्भर कारकों के रूप में कार्य करते हैं? 1. किसी संक्रामक रोग का फैलाव 2. एक भीषण, असामयिक पाला 3. सीमित भोजन के लिए प्रतिस्पर्धा 4. आकाशीय बिजली से लगी वन अग्नि। सही उत्तर चुनिए:","optionsHi":["केवल 1 और 3","केवल 2 और 4","केवल 1, 3 और 4","1, 2, 3 और 4"],"explanationHi":"भीड़ बढ़ने के साथ रोग फैलता है और प्रतिस्पर्धा तीव्र होती है, इसलिए उनका प्रभाव घनत्व पर निर्भर करता है। पाला और बिजली से लगी आग घनत्व जो भी हो, लगभग समान अनुपात को मारते हैं, इसलिए वे घनत्व-स्वतंत्र हैं।"},
  {"id":"env-ecology-615","question":"On a survivorship graph drawn with a logarithmic scale, a population shows a straight diagonal line, meaning that a constant proportion of individuals dies at every age. This is a:","options":["Type I curve","Type II curve","Type III curve","Logistic curve"],"answer":1,"explanation":"A constant mortality rate gives a straight line on a log scale: Type II. Type I populations die mostly in old age; Type III populations suffer heavy losses among the very young.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"लघुगणकीय पैमाने पर खींचे गए उत्तरजीविता आलेख पर एक समष्टि सीधी तिरछी रेखा दर्शाती है, जिसका अर्थ है कि हर आयु पर व्यक्तियों का एक स्थिर अनुपात मरता है। यह है:","optionsHi":["प्रकार I वक्र","प्रकार II वक्र","प्रकार III वक्र","लॉजिस्टिक वक्र"],"explanationHi":"स्थिर मृत्यु दर लघुगणकीय पैमाने पर सीधी रेखा देती है: प्रकार II। प्रकार I समष्टियों में अधिकांश मृत्यु वृद्धावस्था में होती है; प्रकार III समष्टियों में बहुत छोटी आयु के जीवों में भारी हानि होती है।"},
  {"id":"env-ecology-616","question":"An age pyramid in which the pre-reproductive and reproductive age groups are of nearly equal size, giving a bell shape, indicates a population that is:","options":["Growing rapidly","Declining steadily","Stable","Collapsing suddenly"],"answer":2,"explanation":"A bell shape means births roughly replace the breeding cohort, so the population is stable. A broad-based triangle indicates growth and an urn shape a decline.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"एक आयु पिरामिड जिसमें प्रजनन-पूर्व और प्रजनन आयु वर्ग लगभग समान आकार के हैं और घंटी का आकार बनता है, किस प्रकार की समष्टि को इंगित करता है?","optionsHi":["तेज़ी से बढ़ती","लगातार घटती","स्थिर","अचानक ढहती"],"explanationHi":"घंटी के आकार का अर्थ है कि जन्म लगभग प्रजनन करने वाले समूह की जगह ले लेते हैं, इसलिए समष्टि स्थिर है। चौड़े आधार वाला त्रिभुज वृद्धि को और कलश का आकार गिरावट को दर्शाता है।"},
  {"id":"env-ecology-617","question":"Consider the following statements: 1. A metapopulation is a set of local populations in separate habitat patches linked by dispersal. 2. In a metapopulation, a patch whose local population dies out cannot be recolonised later. 3. In source–sink dynamics, a sink population has more births than deaths and supplies emigrants to other patches. How many of the statements given above are correct?","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only 1 is correct. In a metapopulation, extinct patches are recolonised by dispersal (2 wrong), and a sink has more deaths than births and persists through immigration; 3 describes a source.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. मेटा-समष्टि अलग-अलग आवास खंडों में स्थित स्थानीय समष्टियों का वह समूह है जो प्रकीर्णन से जुड़ा होता है। 2. मेटा-समष्टि में जिस खंड की स्थानीय समष्टि समाप्त हो जाती है, वह बाद में पुनः बसाया नहीं जा सकता। 3. स्रोत–अवशोषक (सोर्स–सिंक) गतिकी में अवशोषक समष्टि में मृत्यु से अधिक जन्म होते हैं और वह अन्य खंडों को उत्प्रवासी देती है। उपर्युक्त कथनों में से कितने सही हैं?","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल 1 सही है। मेटा-समष्टि में विलुप्त खंड प्रकीर्णन से पुनः बसाए जाते हैं (2 गलत), और अवशोषक (सिंक) में जन्म से अधिक मृत्यु होती है तथा वह अप्रवास के सहारे टिकी रहती है; 3 स्रोत का वर्णन करता है।"},
  {"id":"env-ecology-618","question":"The Lotka–Volterra equations, first developed in the 1920s, are mathematical models of:","options":["Energy transfer efficiency between trophic levels","Predator–prey interaction and interspecific competition","Logistic growth of a single population towards carrying capacity","The relation between island area and species number"],"answer":1,"explanation":"Lotka and Volterra independently modelled coupled predator–prey cycles and competition between two species. Logistic growth is Verhulst's equation, and the species–area relation comes from island biogeography.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1920 के दशक में पहली बार विकसित लॉटका–वोल्टेरा समीकरण किसके गणितीय मॉडल हैं?","optionsHi":["पोषी स्तरों के बीच ऊर्जा स्थानांतरण की दक्षता","परभक्षी–शिकार अंतःक्रिया और अंतरजातीय प्रतिस्पर्धा","वहन क्षमता की ओर एकल समष्टि की लॉजिस्टिक वृद्धि","द्वीप के क्षेत्रफल और प्रजातियों की संख्या के बीच संबंध"],"explanationHi":"लॉटका और वोल्टेरा ने स्वतंत्र रूप से युग्मित परभक्षी–शिकार चक्रों और दो प्रजातियों के बीच प्रतिस्पर्धा का मॉडल बनाया। लॉजिस्टिक वृद्धि वरहुल्स्ट का समीकरण है, और प्रजाति–क्षेत्रफल संबंध द्वीप जैव-भूगोल से आता है।"},
  {"id":"env-ecology-619","question":"Pacific salmon and many bamboos reproduce only once in their lifetime, putting all their resources into a single burst of breeding, and then die. This life-history strategy is called:","options":["Iteroparity","Parthenogenesis","Polyembryony","Semelparity"],"answer":3,"explanation":"Semelparous organisms breed once and die; iteroparous ones, such as most mammals and trees, breed repeatedly. Parthenogenesis is reproduction without fertilisation.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"प्रशांत सैल्मन और अनेक बाँस अपने जीवनकाल में केवल एक बार प्रजनन करते हैं, अपने सारे संसाधन एक ही बार के प्रजनन में लगा देते हैं, और फिर मर जाते हैं। इस जीवन-इतिहास रणनीति को कहते हैं:","optionsHi":["इटेरोपैरिटी (बहुप्रजनन)","अनिषेकजनन","बहुभ्रूणता","सेमेलपैरिटी (एकल प्रजनन)"],"explanationHi":"सेमेलपैरस जीव एक बार प्रजनन करते हैं और मर जाते हैं; इटेरोपैरस जीव, जैसे अधिकांश स्तनधारी और वृक्ष, बार-बार प्रजनन करते हैं। अनिषेकजनन निषेचन के बिना प्रजनन है।"},
  {"id":"env-ecology-620","question":"A population of 100 grows continuously and exponentially at an intrinsic rate r = 0.1 per year. Approximately what will its size be after 10 years?","options":["200","259","272","110"],"answer":2,"explanation":"Nₜ = N₀e^(rt) = 100 × e¹ ≈ 272. Compounding once a year (1.1¹⁰) gives the 259 trap, and assuming linear addition of 10% of the original each year gives 200.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"100 की एक समष्टि आंतरिक दर r = 0.1 प्रति वर्ष से सतत और चरघातांकी रूप से बढ़ती है। 10 वर्ष बाद उसका आकार लगभग कितना होगा?","optionsHi":["200","259","272","110"],"explanationHi":"Nₜ = N₀e^(rt) = 100 × e¹ ≈ 272। वर्ष में एक बार चक्रवृद्धि (1.1¹⁰) करने पर 259 का भ्रम वाला उत्तर मिलता है, और हर वर्ष मूल का 10% रैखिक रूप से जोड़ने पर 200।"},
  {"id":"env-ecology-621","question":"The gap between a population's biotic potential and the growth it actually achieves in nature is attributed to:","options":["Environmental resistance","Intrinsic rate of increase","Reproductive isolation","Genetic drift"],"answer":0,"explanation":"Biotic potential is maximum growth under ideal conditions; environmental resistance (limits of food, space, predators, disease) holds actual growth below it, giving the S-shaped curve.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"किसी समष्टि की जैविक क्षमता और प्रकृति में उसकी वास्तविक वृद्धि के बीच के अंतर का श्रेय किसे दिया जाता है?","optionsHi":["पर्यावरणीय प्रतिरोध","आंतरिक वृद्धि दर","प्रजनन पृथक्करण","आनुवंशिक अपप्रवाह"],"explanationHi":"जैविक क्षमता आदर्श परिस्थितियों में अधिकतम वृद्धि है; पर्यावरणीय प्रतिरोध (भोजन, स्थान, परभक्षियों, रोग की सीमाएँ) वास्तविक वृद्धि को उससे नीचे रखता है, जिससे S-आकार का वक्र बनता है।"},
  {"id":"env-ecology-622","question":"Match the type of sere with the habitat in which it begins. A. Psammosere  B. Halosere  C. Lithosere  D. Hydrosere; 1. Saline soil or water  2. Bare rock  3. Sand  4. Fresh water","options":["A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-2, B-1, C-3, D-4","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"Psammo- refers to sand, halo- to salt, litho- to rock and hydro- to water. Xerosere is the broad term for successions starting in dry habitats such as rock and sand.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अनुक्रम श्रेणी (सियर) के प्रकार का उस आवास से मिलान कीजिए जिसमें वह आरंभ होती है। A. सैमोसियर B. हेलोसियर C. लिथोसियर D. हाइड्रोसियर; 1. लवणीय मृदा या जल 2. नंगी चट्टान 3. रेत 4. मीठा जल","optionsHi":["A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-2, B-1, C-3, D-4","A-3, B-1, C-2, D-4"],"explanationHi":"सैमो- का अर्थ रेत, हेलो- का नमक, लिथो- का चट्टान और हाइड्रो- का जल है। ज़ेरोसियर चट्टान और रेत जैसे शुष्क आवासों से शुरू होने वाले अनुक्रमणों के लिए व्यापक शब्द है।"},
  {"id":"env-ecology-623","question":"Grasslands kept open for centuries by repeated burning and heavy grazing, in a climate where forest would otherwise develop, are best described as a:","options":["Climatic climax (monoclimax)","Disclimax (biotic climax)","Pioneer community","Edaphic climax"],"answer":1,"explanation":"A disclimax is a stable community held short of the climatic climax by continued disturbance such as fire, grazing or cutting. An edaphic climax is set by soil conditions rather than by disturbance.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जिस जलवायु में अन्यथा वन विकसित होता, वहाँ बार-बार जलाने और भारी चराई से सदियों तक खुले रखे गए घास के मैदानों का सबसे उपयुक्त वर्णन है:","optionsHi":["जलवायवी चरम (एकल चरम)","अपचरम (डिसक्लाइमैक्स, जैविक चरम)","अग्रणी समुदाय","मृदीय चरम (एडैफिक क्लाइमैक्स)"],"explanationHi":"अपचरम एक स्थिर समुदाय है जिसे आग, चराई या कटाई जैसे लगातार विक्षोभ जलवायवी चरम तक पहुँचने से रोके रखते हैं। मृदीय चरम विक्षोभ से नहीं, बल्कि मृदा की परिस्थितियों से निर्धारित होता है।"},
  {"id":"env-ecology-624","question":"The cheetah shows remarkably low genetic variation, so that skin grafts between unrelated individuals are often not rejected. This is generally attributed to:","options":["A population bottleneck in its past","Its strictly solitary hunting habit","Hybridisation with the leopard","Its very short generation time"],"answer":0,"explanation":"A drastic fall in numbers long ago left survivors with only a fraction of the original genetic diversity. Low variation reduces a species' ability to adapt to disease or environmental change.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"चीते में आनुवंशिक विविधता उल्लेखनीय रूप से कम है, इसलिए असंबंधित व्यक्तियों के बीच त्वचा प्रत्यारोपण प्रायः अस्वीकृत नहीं होते। इसका सामान्यतः श्रेय किसे दिया जाता है?","optionsHi":["उसके अतीत की समष्टि अड़चन (बॉटलनेक) को","उसकी पूर्णतः एकाकी शिकार आदत को","तेंदुए के साथ संकरण को","उसके बहुत कम पीढ़ी काल को"],"explanationHi":"बहुत पहले संख्या में तीव्र गिरावट ने बचे हुए जीवों के पास मूल आनुवंशिक विविधता का केवल एक अंश छोड़ा। कम विविधता किसी प्रजाति की रोग या पर्यावरणीय परिवर्तन के प्रति अनुकूलन की क्षमता घटाती है।"},
  {"id":"env-ecology-625","question":"In a mark–recapture study, animals that were caught and marked once become 'trap-shy' and avoid traps afterwards. The Lincoln–Petersen estimate of population size will then be:","options":["Unaffected, since marks are not lost","Too low, an underestimate","Exactly halved","Too high, an overestimate"],"answer":3,"explanation":"N = (marked × second catch) ÷ recaptured marked. Trap-shy marked animals make the recaptured count too small, so N comes out too large. 'Trap-happy' animals cause the opposite error.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"चिह्नांकन–पुनर्ग्रहण अध्ययन में, जो जंतु एक बार पकड़े और चिह्नित किए गए वे 'जाल-भीरु' हो जाते हैं और बाद में जालों से बचते हैं। तब समष्टि आकार का लिंकन–पीटरसन अनुमान होगा:","optionsHi":["अप्रभावित, क्योंकि चिह्न खोते नहीं","बहुत कम, न्यून-अनुमान","ठीक आधा","बहुत अधिक, अति-अनुमान"],"explanationHi":"N = (चिह्नित × दूसरा पकड़ा गया) ÷ पुनः पकड़े गए चिह्नित। जाल-भीरु चिह्नित जंतु पुनर्ग्रहण की गिनती को बहुत कम कर देते हैं, इसलिए N बहुत अधिक आता है। 'जाल-प्रेमी' जंतु विपरीत त्रुटि उत्पन्न करते हैं।"},
  {"id":"env-ecology-626","question":"As atmospheric CO2 has risen, the ratio of carbon-13 to carbon-12 in that CO2 has steadily fallen. Why is this taken as a fingerprint of fossil-fuel burning?","options":["Volcanic CO2 is rich in carbon-12, and volcanic activity has increased sharply since 1850","Carbon-13 is radioactive and decays away faster in a warmer atmosphere","Fossil fuels come from ancient plants, which took up carbon-12 in preference to carbon-13","The oceans release mostly carbon-13 when they warm, so seawater becomes depleted in it"],"answer":2,"explanation":"Photosynthesis discriminates against the heavier 13C, so plant-derived fossil carbon is 13C-poor; adding it dilutes atmospheric 13C. Carbon-13 is a stable isotope, and volcanic emissions are small and have not risen.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जैसे-जैसे वायुमंडलीय CO2 बढ़ी है, उस CO2 में कार्बन-13 और कार्बन-12 का अनुपात लगातार घटा है। इसे जीवाश्म ईंधन जलने का 'अंगुलिछाप' क्यों माना जाता है?","optionsHi":["ज्वालामुखीय CO2 कार्बन-12 से समृद्ध होती है, और 1850 के बाद ज्वालामुखी गतिविधि तेज़ी से बढ़ी है","कार्बन-13 रेडियोधर्मी है और गर्म वायुमंडल में तेज़ी से क्षय हो जाता है","जीवाश्म ईंधन प्राचीन पौधों से बने हैं, जिन्होंने कार्बन-12 को कार्बन-13 की तुलना में वरीयता दी","गर्म होने पर महासागर मुख्यतः कार्बन-13 मुक्त करते हैं, इसलिए समुद्री जल उसमें क्षीण हो जाता है"],"explanationHi":"प्रकाश संश्लेषण भारी 13C के विरुद्ध भेद करता है, इसलिए पादप-व्युत्पन्न जीवाश्म कार्बन 13C में निर्धन होता है; उसे जोड़ने से वायुमंडलीय 13C तनु हो जाता है। कार्बन-13 स्थिर समस्थानिक है, और ज्वालामुखीय उत्सर्जन छोटे हैं और बढ़े नहीं हैं।"},
  {"id":"env-ecology-627","question":"Precise measurements show that the oxygen content of the atmosphere has been falling very slightly while CO2 rises. This observation mainly supports the conclusion that:","options":["The extra CO2 comes from burning carbon-rich fuels, which consumes oxygen","Volcanic eruptions are the main source of the extra CO2, since they absorb oxygen","The oceans are releasing CO2 because they are warming, and this uses up oxygen","Photosynthesis on land has increased sharply, which removes oxygen from the air"],"answer":0,"explanation":"Burning carbon consumes O2 in proportion to the fuel burnt, and the measured O2 decline matches fossil-fuel use. CO2 released from warming oceans or volcanoes would not consume atmospheric oxygen, and more photosynthesis would add O2.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"सटीक मापों से पता चलता है कि CO2 बढ़ने के साथ वायुमंडल की ऑक्सीजन मात्रा बहुत थोड़ी घट रही है। यह प्रेक्षण मुख्यतः किस निष्कर्ष का समर्थन करता है?","optionsHi":["अतिरिक्त CO2 कार्बन-समृद्ध ईंधन जलाने से आती है, जो ऑक्सीजन की खपत करता है","ज्वालामुखी विस्फोट अतिरिक्त CO2 का मुख्य स्रोत हैं, क्योंकि वे ऑक्सीजन अवशोषित करते हैं","महासागर गर्म होने के कारण CO2 मुक्त कर रहे हैं, और इसमें ऑक्सीजन खर्च होती है","स्थल पर प्रकाश संश्लेषण तेज़ी से बढ़ा है, जो वायु से ऑक्सीजन हटाता है"],"explanationHi":"कार्बन जलाने से जले ईंधन के अनुपात में O2 की खपत होती है, और मापी गई O2 की गिरावट जीवाश्म ईंधन के उपयोग से मेल खाती है। गर्म होते महासागरों या ज्वालामुखियों से निकली CO2 वायुमंडलीय ऑक्सीजन की खपत नहीं करती, और अधिक प्रकाश संश्लेषण O2 जोड़ता।"},
  {"id":"env-ecology-628","question":"Of the CO2 emitted each year by human activities, roughly what share stays in the atmosphere (the 'airborne fraction'), the rest being taken up by land and ocean sinks?","options":["About 10 per cent","About 45 per cent","About 80 per cent","Nearly all of it"],"answer":1,"explanation":"Over recent decades a little under half of emitted CO2 has remained airborne; the oceans and land ecosystems have each absorbed roughly a quarter. That is why concentrations rise more slowly than cumulative emissions alone would suggest.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मानवीय गतिविधियों द्वारा प्रति वर्ष उत्सर्जित CO2 का लगभग कितना अंश वायुमंडल में रह जाता है ('वायुवाहित अंश'), शेष को स्थल और महासागर के अवशोषक ले लेते हैं?","optionsHi":["लगभग 10 प्रतिशत","लगभग 45 प्रतिशत","लगभग 80 प्रतिशत","लगभग सारा"],"explanationHi":"हाल के दशकों में उत्सर्जित CO2 के आधे से थोड़ा कम भाग वायु में बना रहा है; महासागरों और स्थलीय पारिस्थितिकी तंत्रों ने प्रत्येक ने लगभग एक-चौथाई अवशोषित किया है। इसीलिए सांद्रता संचयी उत्सर्जन से अनुमानित गति की तुलना में धीमी बढ़ती है।"},
  {"id":"env-ecology-629","question":"The pre-industrial concentration of carbon dioxide in the atmosphere, as recorded in ice cores, was about:","options":["180 parts per million","350 parts per million","420 parts per million","280 parts per million"],"answer":3,"explanation":"Ice cores show CO2 near 280 ppm before about 1750. Around 180 ppm is typical of glacial maxima, 350 ppm was passed in the late 1980s, and levels crossed 400 ppm in the 2010s.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"हिम क्रोड (आइस कोर) में दर्ज वायुमंडल में कार्बन डाइऑक्साइड की पूर्व-औद्योगिक सांद्रता लगभग थी:","optionsHi":["180 भाग प्रति मिलियन","350 भाग प्रति मिलियन","420 भाग प्रति मिलियन","280 भाग प्रति मिलियन"],"explanationHi":"हिम क्रोड लगभग 1750 से पहले CO2 को 280 ppm के निकट दर्शाते हैं। लगभग 180 ppm हिमनदीय अधिकतम काल की विशेषता है, 350 ppm 1980 के दशक के अंत में पार हुआ, और स्तर 2010 के दशक में 400 ppm से ऊपर निकल गए।"},
  {"id":"env-ecology-630","question":"Consider the following statements: 1. The atmospheric concentration of methane has more than doubled since pre-industrial times. 2. The atmospheric concentration of carbon dioxide has more than doubled since pre-industrial times. 3. In proportional terms, methane has risen more than carbon dioxide since pre-industrial times. Which of the statements given above are correct?","options":["1 and 3 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Methane has risen from about 0.7 to well over 1.8 parts per million, more than two and a half times. CO2 has risen from about 280 ppm to the low 400s, roughly 50 per cent, far short of doubling.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. पूर्व-औद्योगिक काल से वायुमंडल में मीथेन की सांद्रता दोगुनी से अधिक हो गई है। 2. पूर्व-औद्योगिक काल से वायुमंडल में कार्बन डाइऑक्साइड की सांद्रता दोगुनी से अधिक हो गई है। 3. अनुपात की दृष्टि से, पूर्व-औद्योगिक काल से मीथेन में कार्बन डाइऑक्साइड से अधिक वृद्धि हुई है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"मीथेन लगभग 0.7 से बढ़कर 1.8 भाग प्रति मिलियन से काफ़ी ऊपर पहुँच गई है, यानी ढाई गुना से अधिक। CO2 लगभग 280 ppm से बढ़कर 400 के आरंभिक दशकों में पहुँची है, लगभग 50 प्रतिशत, जो दोगुना होने से बहुत कम है।"},
  {"id":"env-ecology-631","question":"Why can a very small amount of CFCs reaching the stratosphere destroy a very large amount of ozone?","options":["Each CFC molecule splits into thousands of separate chlorine atoms once it reaches the stratosphere","CFCs absorb all of the ultraviolet light that would otherwise be used to make new ozone molecules","Chlorine acts as a catalyst: it is regenerated after each reaction and destroys more ozone","CFCs combine permanently with ozone, so each CFC molecule keeps removing ozone for centuries"],"answer":2,"explanation":"In the cycle Cl + O3 gives ClO + O2, then ClO + O gives Cl + O2, the chlorine atom is freed again, so a single atom can destroy tens of thousands of ozone molecules before it is locked up in a reservoir species.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"समतापमंडल में पहुँचने वाली CFC की बहुत थोड़ी मात्रा भी ओज़ोन की बहुत बड़ी मात्रा को क्यों नष्ट कर सकती है?","optionsHi":["समतापमंडल में पहुँचने पर प्रत्येक CFC अणु हज़ारों अलग-अलग क्लोरीन परमाणुओं में टूट जाता है","CFC वह सारा पराबैंगनी प्रकाश अवशोषित कर लेते हैं जो अन्यथा नए ओज़ोन अणु बनाने में प्रयुक्त होता","क्लोरीन उत्प्रेरक की तरह कार्य करती है: हर अभिक्रिया के बाद वह पुनः बन जाती है और और अधिक ओज़ोन नष्ट करती है","CFC ओज़ोन से स्थायी रूप से संयोजित हो जाते हैं, इसलिए प्रत्येक CFC अणु सदियों तक ओज़ोन हटाता रहता है"],"explanationHi":"चक्र में Cl + O3 से ClO + O2 बनता है, फिर ClO + O से Cl + O2, और क्लोरीन परमाणु फिर मुक्त हो जाता है; इसलिए एक परमाणु किसी भंडारण प्रजाति में बंद होने से पहले दसियों हज़ार ओज़ोन अणुओं को नष्ट कर सकता है।"},
  {"id":"env-ecology-632","question":"Halons, used in fire extinguishers, have far higher ozone-depleting potentials than CFC-11. The main reason is that halons:","options":["Are released into the air in much larger quantities than CFCs ever were","Contain bromine, which destroys ozone far more efficiently than chlorine","Reach the stratosphere within days because they are much lighter than air","Absorb ultraviolet light so strongly that no new ozone can form near them"],"answer":1,"explanation":"Bromine is roughly 60 times more effective than chlorine per atom, as less of it is held in inactive reservoir forms. Halon-1301 has an ODP of about 10, against 1 for CFC-11, though far less halon was produced.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"अग्निशामकों में प्रयुक्त हैलॉनों की ओज़ोन क्षयकारी क्षमता CFC-11 से कहीं अधिक होती है। इसका मुख्य कारण यह है कि हैलॉन:","optionsHi":["CFC की तुलना में वायु में कहीं बड़ी मात्रा में छोड़े जाते रहे हैं","में ब्रोमीन होती है, जो क्लोरीन से कहीं अधिक दक्षता से ओज़ोन को नष्ट करती है","हवा से बहुत हल्के होने के कारण कुछ ही दिनों में समतापमंडल में पहुँच जाते हैं","पराबैंगनी प्रकाश को इतना प्रबल रूप से अवशोषित करते हैं कि उनके निकट कोई नई ओज़ोन नहीं बन पाती"],"explanationHi":"ब्रोमीन प्रति परमाणु क्लोरीन से लगभग 60 गुना अधिक प्रभावी है, क्योंकि उसका कम भाग निष्क्रिय भंडारण रूपों में रहता है। हैलॉन-1301 की ODP लगभग 10 है, जबकि CFC-11 की 1, यद्यपि हैलॉन का उत्पादन कहीं कम हुआ।"},
  {"id":"env-ecology-633","question":"Which of the following substances is now considered the largest ozone-depleting emission from human activity, yet is not controlled under the Montreal Protocol?","options":["Methyl bromide","Carbon tetrachloride","HCFC-22","Nitrous oxide"],"answer":3,"explanation":"N2O, mainly from fertilised soils, breaks down in the stratosphere to nitric oxide, which destroys ozone catalytically. It is covered as a greenhouse gas under the UNFCCC but not by the Montreal Protocol, unlike the other three.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सा पदार्थ अब मानवीय गतिविधि से होने वाला सबसे बड़ा ओज़ोन-क्षयकारी उत्सर्जन माना जाता है, फिर भी मॉन्ट्रियल प्रोटोकॉल के अंतर्गत नियंत्रित नहीं है?","optionsHi":["मेथिल ब्रोमाइड","कार्बन टेट्राक्लोराइड","HCFC-22","नाइट्रस ऑक्साइड"],"explanationHi":"N2O, मुख्यतः उर्वरित मृदाओं से, समतापमंडल में नाइट्रिक ऑक्साइड में टूट जाती है, जो उत्प्रेरकीय रूप से ओज़ोन को नष्ट करती है। यह UNFCCC के अंतर्गत हरितगृह गैस के रूप में आती है, परंतु अन्य तीनों के विपरीत मॉन्ट्रियल प्रोटोकॉल में नहीं।"},
  {"id":"env-ecology-634","question":"Which of the following correctly describes how the atmosphere filters the Sun's ultraviolet radiation?","options":["UV-C is absorbed completely, UV-B mostly, and most UV-A reaches the ground","UV-A is absorbed completely, UV-B mostly, and most UV-C reaches the ground","All three types are absorbed equally, so ozone loss raises each of them alike","UV-B is absorbed completely, while UV-A and UV-C both reach the ground"],"answer":0,"explanation":"The shortest, most energetic UV-C is fully absorbed by oxygen and ozone; ozone absorbs most UV-B, so ozone thinning mainly increases UV-B at the surface; UV-A passes largely unaffected.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"वायुमंडल सूर्य के पराबैंगनी विकिरण को कैसे छानता है, इसका सही वर्णन निम्नलिखित में से कौन-सा है?","optionsHi":["UV-C पूरी तरह अवशोषित होती है, UV-B अधिकांशतः, और अधिकांश UV-A भूमि तक पहुँचती है","UV-A पूरी तरह अवशोषित होती है, UV-B अधिकांशतः, और अधिकांश UV-C भूमि तक पहुँचती है","तीनों प्रकार समान रूप से अवशोषित होते हैं, इसलिए ओज़ोन हानि प्रत्येक को समान बढ़ाती है","UV-B पूरी तरह अवशोषित होती है, जबकि UV-A और UV-C दोनों भूमि तक पहुँचती हैं"],"explanationHi":"सबसे छोटी, सर्वाधिक ऊर्जावान UV-C ऑक्सीजन और ओज़ोन द्वारा पूरी तरह अवशोषित हो जाती है; ओज़ोन अधिकांश UV-B अवशोषित करती है, इसलिए ओज़ोन के पतले होने से मुख्यतः सतह पर UV-B बढ़ती है; UV-A बड़े पैमाने पर अप्रभावित गुज़र जाती है।"},
  {"id":"env-ecology-635","question":"Most stratospheric ozone is produced over the tropics, where sunlight is strongest, yet the total ozone column (outside the ozone-hole season) is usually lowest over the tropics. The main reason is that:","options":["Tropical thunderstorms carry CFCs upward and destroy most of the ozone made there","Ozone made over the tropics is carried poleward and downward by stratospheric circulation","The tropical stratosphere is too warm for ozone to form at all, so it all comes from the poles","Tropical forests release gases that destroy ozone as soon as it forms overhead"],"answer":1,"explanation":"The slow Brewer–Dobson circulation lifts air in the tropics and moves it towards the poles, where it descends and ozone piles up, especially in late winter and spring. So production and column amount peak in different places.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"समतापमंडलीय ओज़ोन का अधिकांश उत्पादन उष्णकटिबंध के ऊपर होता है, जहाँ सूर्य का प्रकाश सबसे प्रबल है, फिर भी कुल ओज़ोन स्तंभ (ओज़ोन छिद्र की ऋतु को छोड़कर) सामान्यतः उष्णकटिबंध में सबसे कम होता है। इसका मुख्य कारण यह है कि:","optionsHi":["उष्णकटिबंधीय तड़ित-झंझाएँ CFC को ऊपर ले जाती हैं और वहाँ बनी अधिकांश ओज़ोन को नष्ट कर देती हैं","उष्णकटिबंध के ऊपर बनी ओज़ोन को समतापमंडलीय परिसंचरण ध्रुवों की ओर और नीचे की ओर ले जाता है","उष्णकटिबंधीय समतापमंडल ओज़ोन बनने के लिए बहुत गर्म है, इसलिए सारी ओज़ोन ध्रुवों से आती है","उष्णकटिबंधीय वन ऐसी गैसें छोड़ते हैं जो ऊपर बनते ही ओज़ोन को नष्ट कर देती हैं"],"explanationHi":"धीमा ब्रूअर–डॉब्सन परिसंचरण उष्णकटिबंध में वायु को ऊपर उठाता है और ध्रुवों की ओर ले जाता है, जहाँ वह नीचे उतरती है और ओज़ोन जमा हो जाती है, विशेषकर देर सर्दियों और वसंत में। इसलिए उत्पादन और स्तंभ मात्रा के शिखर अलग-अलग स्थानों पर होते हैं।"},
  {"id":"env-ecology-636","question":"Molecule for molecule, CFCs are thousands of times more powerful greenhouse gases than CO2. An important reason is that they:","options":["Absorb incoming visible sunlight strongly before it reaches the ground","Remain in the atmosphere for only a few days, so their effect is concentrated","Make clouds brighter, so they reflect more of the heat back to the surface","Absorb infrared in the 'atmospheric window' where other gases absorb little"],"answer":3,"explanation":"Between roughly 8 and 13 µm, water vapour and CO2 absorb weakly, so the Earth's heat escapes to space there. Gases absorbing in this window, such as CFCs, close a gap and so have a large effect per molecule.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"अणु-दर-अणु, CFC, CO2 की तुलना में हज़ारों गुना शक्तिशाली हरितगृह गैसें हैं। इसका एक महत्त्वपूर्ण कारण यह है कि वे:","optionsHi":["भूमि तक पहुँचने से पहले आने वाले दृश्य सूर्य के प्रकाश को प्रबल रूप से अवशोषित करते हैं","वायुमंडल में केवल कुछ दिन रहते हैं, इसलिए उनका प्रभाव केंद्रित होता है","बादलों को अधिक चमकीला बनाते हैं, जिससे वे ऊष्मा को सतह की ओर अधिक परावर्तित करते हैं","'वायुमंडलीय खिड़की' में अवरक्त को अवशोषित करते हैं, जहाँ अन्य गैसें बहुत कम अवशोषित करती हैं"],"explanationHi":"लगभग 8 से 13 µm के बीच जलवाष्प और CO2 कमज़ोर अवशोषण करते हैं, इसलिए पृथ्वी की ऊष्मा वहाँ अंतरिक्ष में निकल जाती है। इस खिड़की में अवशोषण करने वाली गैसें, जैसे CFC, एक अंतर को बंद कर देती हैं, इसलिए प्रति अणु उनका प्रभाव बड़ा होता है।"},
  {"id":"env-ecology-637","question":"Each additional part per million of CO2 adds a little less warming effect than the one before. This is mainly because:","options":["CO2 molecules bind to one another at high concentrations and form inactive clusters","The core of CO2's absorption band is already saturated, so forcing rises logarithmically","The oceans absorb a larger share of each extra part per million than of the previous one","Rising CO2 cools the stratosphere, which cancels most of the extra warming near the ground"],"answer":1,"explanation":"Where CO2 already absorbs almost all outgoing radiation, more gas adds little; extra absorption happens mainly in the band's wings. So each doubling of CO2 adds roughly the same forcing, about 3.7 W/m².","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"CO2 का प्रत्येक अतिरिक्त भाग प्रति मिलियन पहले वाले की तुलना में थोड़ा कम तापन प्रभाव जोड़ता है। इसका मुख्य कारण यह है कि:","optionsHi":["उच्च सांद्रता पर CO2 अणु एक-दूसरे से बँध जाते हैं और निष्क्रिय गुच्छे बनाते हैं","CO2 के अवशोषण बैंड का केंद्र पहले ही संतृप्त है, इसलिए विकिरणी बलन लघुगणकीय रूप से बढ़ता है","महासागर प्रत्येक अतिरिक्त भाग प्रति मिलियन का पिछले की तुलना में अधिक हिस्सा अवशोषित करते हैं","बढ़ती CO2 समतापमंडल को ठंडा करती है, जो भूमि के निकट अतिरिक्त तापन के अधिकांश को निरस्त कर देता है"],"explanationHi":"जहाँ CO2 पहले ही लगभग सारे बहिर्गामी विकिरण को अवशोषित करती है, वहाँ और गैस थोड़ा ही जोड़ती है; अतिरिक्त अवशोषण मुख्यतः बैंड के पार्श्वों में होता है। इसलिए CO2 का प्रत्येक दोगुना होना लगभग समान बलन, लगभग 3.7 W/m², जोड़ता है।"},
  {"id":"env-ecology-638","question":"Where has most of the extra heat trapped by the enhanced greenhouse effect since the 1970s gone?","options":["Into the oceans, which have taken up over 90 per cent of it","Into the atmosphere, which has taken up about two-thirds of it","Into melting ice, which has taken up about half of it","Into the land surface, which has taken up most of it"],"answer":0,"explanation":"Water's high heat capacity means the oceans have absorbed over 90 per cent of the accumulated energy; the atmosphere, land and melting ice share the small remainder. Ocean warming drives thermal expansion and coral bleaching.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1970 के दशक से संवर्धित हरितगृह प्रभाव द्वारा फँसाई गई अतिरिक्त ऊष्मा का अधिकांश भाग कहाँ गया है?","optionsHi":["महासागरों में, जिन्होंने उसका 90 प्रतिशत से अधिक भाग ले लिया है","वायुमंडल में, जिसने उसका लगभग दो-तिहाई भाग ले लिया है","पिघलती बर्फ़ में, जिसने उसका लगभग आधा भाग ले लिया है","स्थल की सतह में, जिसने उसका अधिकांश भाग ले लिया है"],"explanationHi":"जल की उच्च ऊष्मा धारिता के कारण महासागरों ने संचित ऊर्जा का 90 प्रतिशत से अधिक अवशोषित किया है; वायुमंडल, स्थल और पिघलती बर्फ़ शेष छोटे भाग को बाँटते हैं। महासागरीय तापन से तापीय प्रसार और प्रवाल विरंजन होता है।"},
  {"id":"env-ecology-639","question":"Newly hatched olive ridley turtles on a brightly lit beach often crawl inland, towards roads and buildings, instead of towards the sea. This happens mainly because:","options":["Artificial lights outshine the brighter seaward horizon they head for","Warm sand near lit buildings feels like the shallow sea water they are seeking","Hatchlings move downhill, and the lit ground behind most beaches lies lower","Lights drown out the stars that hatchlings use as a compass to find the sea"],"answer":0,"explanation":"Hatchlings find the sea by heading for the lowest, brightest horizon, which on a natural beach is over the water; artificial light inland overrides this cue. They do not navigate by star patterns, and beaches slope down towards the sea, not inland.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"तेज़ रोशनी वाले समुद्र तट पर नए निकले ऑलिव रिडले कछुए के बच्चे प्रायः समुद्र की ओर जाने के बजाय भीतर की ओर, सड़कों और इमारतों की ओर रेंगते हैं। यह मुख्यतः इसलिए होता है क्योंकि:","optionsHi":["कृत्रिम बत्तियाँ उस अधिक चमकीले समुद्री क्षितिज को फीका कर देती हैं जिसकी ओर वे जाते हैं","रोशनी वाली इमारतों के पास की गर्म रेत उन्हें उस उथले समुद्री जल जैसी लगती है जिसे वे खोज रहे होते हैं","बच्चे ढलान की ओर चलते हैं, और अधिकांश तटों के पीछे की रोशनी वाली भूमि नीची होती है","बत्तियाँ उन तारों को ढक देती हैं जिन्हें बच्चे समुद्र खोजने के लिए दिशासूचक के रूप में उपयोग करते हैं"],"explanationHi":"बच्चे सबसे नीचे, सबसे चमकीले क्षितिज की ओर जाकर समुद्र खोजते हैं, जो प्राकृतिक तट पर जल के ऊपर होता है; भीतर की कृत्रिम रोशनी इस संकेत को दबा देती है। वे तारों के प्रतिरूपों से दिशा नहीं खोजते, और तट समुद्र की ओर ढलते हैं, भीतर की ओर नहीं।"},
  {"id":"env-ecology-640","question":"Over millions of years, the chemical weathering of silicate rocks is thought to act as a 'thermostat' for the Earth's climate. This is because:","options":["Weathering releases CO2 from the rocks, so a colder climate quickly leads to faster warming","Weathered rock fragments reflect more sunlight, so faster weathering cools the whole planet","Silicate rocks absorb infrared radiation, so exposing more of them steadily warms the planet","Weathering draws down CO2 and speeds up in warmer, wetter climates, pulling CO2 back"],"answer":3,"explanation":"Rain carrying dissolved CO2 weathers silicates, and the carbon ends up in ocean carbonate sediments. Warmer, wetter conditions speed this up and remove more CO2, a negative feedback that is far too slow to offset present-day emissions.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"लाखों वर्षों में सिलिकेट चट्टानों का रासायनिक अपक्षय पृथ्वी की जलवायु के लिए 'थर्मोस्टेट' का कार्य करता माना जाता है। इसका कारण यह है कि:","optionsHi":["अपक्षय चट्टानों से CO2 मुक्त करता है, इसलिए ठंडी जलवायु शीघ्र तेज़ तापन की ओर ले जाती है","अपक्षयित चट्टान के टुकड़े अधिक सूर्य प्रकाश परावर्तित करते हैं, इसलिए तेज़ अपक्षय पूरे ग्रह को ठंडा कर देता है","सिलिकेट चट्टानें अवरक्त विकिरण अवशोषित करती हैं, इसलिए उनके अधिक उजागर होने से ग्रह लगातार गर्म होता है","अपक्षय CO2 को खींचता है और गर्म, अधिक आर्द्र जलवायु में तेज़ हो जाता है, जिससे CO2 वापस खिंच जाती है"],"explanationHi":"घुली CO2 लेकर आने वाली वर्षा सिलिकेटों का अपक्षय करती है, और कार्बन महासागरीय कार्बोनेट अवसादों में पहुँच जाता है। गर्म, अधिक आर्द्र परिस्थितियाँ इसे तेज़ करती हैं और अधिक CO2 हटाती हैं; यह एक ऋणात्मक पुनर्निवेश है जो आज के उत्सर्जन को संतुलित करने के लिए बहुत धीमा है।"},
  {"id":"env-ecology-641","question":"Consider the following statements about volcanoes and climate: 1. A large explosive eruption can cool the global climate for a year or two by putting sulphur dioxide into the stratosphere. 2. Volcanoes emit more CO2 each year than human activities do. 3. The eruption of Mount Pinatubo in 1991 was followed by a temporary global cooling of about half a degree Celsius. Which of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Stratospheric sulphate aerosols reflect sunlight for a year or two, as after Pinatubo. But volcanic CO2 output is around one per cent of human emissions, so statement 2 is wrong.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ज्वालामुखियों और जलवायु के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. एक बड़ा विस्फोटक उद्गार समतापमंडल में सल्फर डाइऑक्साइड पहुँचाकर एक-दो वर्ष के लिए वैश्विक जलवायु को ठंडा कर सकता है। 2. ज्वालामुखी प्रति वर्ष मानवीय गतिविधियों से अधिक CO2 उत्सर्जित करते हैं। 3. 1991 में माउंट पिनातुबो के उद्गार के बाद लगभग आधा डिग्री सेल्सियस का अस्थायी वैश्विक शीतलन हुआ। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"समतापमंडलीय सल्फेट एरोसॉल एक-दो वर्ष तक सूर्य प्रकाश परावर्तित करते हैं, जैसा पिनातुबो के बाद हुआ। परंतु ज्वालामुखीय CO2 उत्पादन मानवीय उत्सर्जन का लगभग एक प्रतिशत है, इसलिए कथन 2 गलत है।"},
  {"id":"env-ecology-642","question":"Land areas have warmed faster than the oceans in recent decades. The main reasons are that land:","options":["Has lower heat capacity and less water available for evaporative cooling","Receives more sunlight per square metre than the ocean does at the same latitude","Contains more greenhouse gases in the air directly above it than the ocean does","Reflects much less sunlight than the open ocean, so it absorbs more energy"],"answer":0,"explanation":"Water stores heat and mixes it downward, and evaporation from the sea removes heat; land heats up quickly at the surface. The open ocean is in fact darker (lower albedo) than most land.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"हाल के दशकों में स्थल क्षेत्र महासागरों की तुलना में तेज़ी से गर्म हुए हैं। इसके मुख्य कारण यह हैं कि स्थल:","optionsHi":["की ऊष्मा धारिता कम है और वाष्पीकरणीय शीतलन के लिए कम जल उपलब्ध है","को समान अक्षांश पर महासागर की तुलना में प्रति वर्ग मीटर अधिक सूर्य प्रकाश मिलता है","के ठीक ऊपर की वायु में महासागर के ऊपर की वायु से अधिक हरितगृह गैसें होती हैं","खुले महासागर की तुलना में बहुत कम सूर्य प्रकाश परावर्तित करता है, इसलिए अधिक ऊर्जा अवशोषित करता है"],"explanationHi":"जल ऊष्मा का भंडारण करता है और उसे नीचे की ओर मिलाता है, और समुद्र से वाष्पीकरण ऊष्मा हटाता है; स्थल की सतह शीघ्र गर्म हो जाती है। वास्तव में खुला महासागर अधिकांश स्थल से अधिक गहरा (निम्न एल्बिडो) है।"},
  {"id":"env-ecology-643","question":"Rising CO2 can raise plant photosynthesis (the 'CO2 fertilisation effect'). This effect is expected to be stronger in wheat and rice than in maize and sugarcane because:","options":["Wheat and rice are grown in winter, when the CO2 level in the air is noticeably higher","Wheat and rice carry many more leaves per plant than maize and sugarcane usually do","Wheat and rice are C3 plants; C4 crops already concentrate CO2 inside their leaves","Maize and sugarcane are unable to open their stomata at all when CO2 levels are high"],"answer":2,"explanation":"C4 plants pump CO2 into bundle-sheath cells, so their photosynthesis is nearly saturated at present CO2. C3 plants lose carbon to photorespiration, which higher CO2 suppresses, so they respond more.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"बढ़ती CO2 पौधों के प्रकाश संश्लेषण को बढ़ा सकती है ('CO2 निषेचन प्रभाव')। यह प्रभाव मक्का और गन्ने की तुलना में गेहूँ और चावल में अधिक प्रबल होने की अपेक्षा है क्योंकि:","optionsHi":["गेहूँ और चावल सर्दियों में उगाए जाते हैं, जब वायु में CO2 का स्तर स्पष्ट रूप से अधिक होता है","गेहूँ और चावल में प्रति पौधा मक्का और गन्ने की तुलना में सामान्यतः कहीं अधिक पत्तियाँ होती हैं","गेहूँ और चावल C3 पौधे हैं; C4 फसलें पहले से ही अपनी पत्तियों के भीतर CO2 को सांद्रित कर लेती हैं","मक्का और गन्ना CO2 का स्तर अधिक होने पर अपने रंध्र बिल्कुल नहीं खोल पाते"],"explanationHi":"C4 पौधे CO2 को पूलावरण कोशिकाओं में पंप करते हैं, इसलिए वर्तमान CO2 पर उनका प्रकाश संश्लेषण लगभग संतृप्त है। C3 पौधे प्रकाशश्वसन में कार्बन खोते हैं, जिसे अधिक CO2 दबा देती है, इसलिए वे अधिक प्रतिक्रिया देते हैं।"},
  {"id":"env-ecology-644","question":"Which of the following is the largest NATURAL source of methane emissions to the atmosphere?","options":["Termites in tropical grasslands","Geological seeps on the sea floor","Wild ruminants such as deer and antelope","Natural wetlands"],"answer":3,"explanation":"Waterlogged, oxygen-poor wetland soils host methanogenic archaea and supply the largest natural share of methane. Termites, geological seeps and wild animals are much smaller natural sources.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"वायुमंडल में मीथेन उत्सर्जन का सबसे बड़ा प्राकृतिक स्रोत निम्नलिखित में से कौन-सा है?","optionsHi":["उष्णकटिबंधीय घास के मैदानों में दीमक","समुद्र तल पर भूवैज्ञानिक रिसाव","हिरण और मृग जैसे वन्य जुगाली करने वाले जंतु","प्राकृतिक आर्द्रभूमियाँ"],"explanationHi":"जलमग्न, ऑक्सीजन-रहित आर्द्रभूमि मृदाओं में मीथेनोजेनिक आर्किया होते हैं और वे मीथेन का सबसे बड़ा प्राकृतिक हिस्सा प्रदान करती हैं। दीमक, भूवैज्ञानिक रिसाव और वन्य जंतु कहीं छोटे प्राकृतिक स्रोत हैं।"},
  {"id":"env-ecology-645","question":"Which greenhouse gas was added to the Kyoto Protocol's basket of gases for its second commitment period by the Doha Amendment?","options":["Sulphur hexafluoride","Nitrogen trifluoride","Hydrofluorocarbons","Tropospheric ozone"],"answer":1,"explanation":"The original Kyoto basket had six gases: CO2, CH4, N2O, HFCs, PFCs and SF6. The Doha Amendment (2012) added nitrogen trifluoride, used in making flat-panel displays and solar cells.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"दोहा संशोधन द्वारा क्योटो प्रोटोकॉल की दूसरी प्रतिबद्धता अवधि के लिए उसकी गैसों की टोकरी में कौन-सी हरितगृह गैस जोड़ी गई?","optionsHi":["सल्फर हेक्साफ्लोराइड","नाइट्रोजन ट्राइफ्लोराइड","हाइड्रोफ्लोरोकार्बन","क्षोभमंडलीय ओज़ोन"],"explanationHi":"मूल क्योटो टोकरी में छह गैसें थीं: CO2, CH4, N2O, HFC, PFC और SF6। दोहा संशोधन (2012) ने नाइट्रोजन ट्राइफ्लोराइड जोड़ी, जिसका उपयोग फ़्लैट-पैनल डिस्प्ले और सौर सेल बनाने में होता है।"},
  {"id":"env-ecology-646","question":"Counting all of Earth's carbon, including that locked in rocks, the largest reservoir is in:","options":["Sedimentary rocks such as limestone and shale","The deep ocean, as dissolved inorganic carbon","The atmosphere, as carbon dioxide","Soils and permafrost, as organic matter"],"answer":0,"explanation":"Carbonate rocks and organic kerogen in shales hold tens of millions of gigatonnes of carbon, far more than the ocean (about 38,000 Gt). This 'slow' carbon cycle exchanges with the surface over millions of years.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"चट्टानों में बंद कार्बन सहित पृथ्वी के समस्त कार्बन को गिना जाए, तो कार्बन का सबसे बड़ा भंडार किसमें है?","optionsHi":["चूना पत्थर और शेल जैसी अवसादी चट्टानों में","गहरे महासागर में, घुलित अकार्बनिक कार्बन के रूप में","वायुमंडल में, कार्बन डाइऑक्साइड के रूप में","मृदाओं और पर्माफ्रॉस्ट में, कार्बनिक पदार्थ के रूप में"],"explanationHi":"कार्बोनेट चट्टानों और शेलों के कार्बनिक केरोजन में करोड़ों गीगाटन कार्बन है, जो महासागर (लगभग 38,000 Gt) से कहीं अधिक है। यह 'धीमा' कार्बन चक्र सतह के साथ लाखों वर्षों में विनिमय करता है।"},
  {"id":"env-ecology-647","question":"Oxygen levels in large parts of the ocean have declined in recent decades. Which of the following best explains this?","options":["Seawater is becoming saltier, and the extra salt reacts chemically with dissolved oxygen","Phytoplankton have begun using dissolved oxygen in place of carbon dioxide for growth","Warmer water holds less oxygen, and stronger layering cuts mixing with deep water","Ocean acidification converts the dissolved oxygen into carbonic acid near the surface"],"answer":2,"explanation":"Gas solubility falls as water warms, and a warmer, lighter surface layer mixes less with deeper water, so less oxygen reaches depth. Nutrient run-off adds coastal dead zones on top of this.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हाल के दशकों में महासागर के बड़े भागों में ऑक्सीजन का स्तर घटा है। इसकी सबसे अच्छी व्याख्या निम्नलिखित में से कौन-सी है?","optionsHi":["समुद्री जल अधिक खारा हो रहा है, और अतिरिक्त नमक घुली ऑक्सीजन से रासायनिक अभिक्रिया करता है","फाइटोप्लैंकटन ने वृद्धि के लिए कार्बन डाइऑक्साइड के स्थान पर घुली ऑक्सीजन का उपयोग शुरू कर दिया है","गर्म जल कम ऑक्सीजन धारण करता है, और प्रबल स्तरण गहरे जल के साथ मिश्रण घटा देता है","महासागर अम्लीकरण सतह के निकट घुली ऑक्सीजन को कार्बोनिक अम्ल में बदल देता है"],"explanationHi":"जल के गर्म होने पर गैस की विलेयता घटती है, और गर्म, हल्की सतही परत गहरे जल के साथ कम मिश्रित होती है, इसलिए गहराई तक कम ऑक्सीजन पहुँचती है। पोषक तत्वों का अपवाह इसके ऊपर तटीय मृत क्षेत्र जोड़ देता है।"},
  {"id":"env-ecology-648","question":"Consider the following statements: 1. A mature old-growth forest usually stores more carbon per hectare than a young plantation. 2. A young, fast-growing plantation usually absorbs carbon faster each year than an old-growth forest. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Stock and flow differ: old forests hold large stocks in big trees and soil, while young stands take up carbon faster as they grow. Clearing old forest to plant new trees releases far more carbon than the plantation soon recovers.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. एक परिपक्व पुरातन वन सामान्यतः युवा वृक्षारोपण की तुलना में प्रति हेक्टेयर अधिक कार्बन संचित करता है। 2. एक युवा, तेज़ी से बढ़ता वृक्षारोपण सामान्यतः पुरातन वन की तुलना में प्रति वर्ष अधिक तेज़ी से कार्बन अवशोषित करता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"भंडार और प्रवाह में अंतर होता है: पुराने वन बड़े वृक्षों और मृदा में बड़े भंडार धारण करते हैं, जबकि युवा वृक्ष-समूह बढ़ने के साथ कार्बन तेज़ी से लेते हैं। पुराने वन को काटकर नए वृक्ष लगाने से जितना कार्बन मुक्त होता है, उसे वृक्षारोपण शीघ्र पुनः प्राप्त नहीं कर पाता।"},
  {"id":"env-ecology-649","question":"The Hindu Kush–Himalaya and Tibetan Plateau region is often called the 'Third Pole' because:","options":["It has the third-highest rainfall of any region in the world","It holds the largest store of ice outside the polar regions","It lies at the third-highest average elevation among regions","Its magnetic field is nearly as strong as at the two poles"],"answer":1,"explanation":"Its glaciers and snowfields form the largest ice mass after Antarctica and Greenland and feed rivers such as the Indus, Ganga, Brahmaputra and Yangtze, which is why their retreat is a major concern.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"हिंदू कुश–हिमालय और तिब्बती पठार क्षेत्र को प्रायः 'तीसरा ध्रुव' कहा जाता है क्योंकि:","optionsHi":["यहाँ विश्व के किसी भी क्षेत्र की तीसरी सर्वाधिक वर्षा होती है","इसमें ध्रुवीय क्षेत्रों के बाहर बर्फ़ का सबसे बड़ा भंडार है","औसत ऊँचाई में यह क्षेत्रों में तीसरे स्थान पर है","इसका चुंबकीय क्षेत्र दोनों ध्रुवों जितना ही प्रबल है"],"explanationHi":"इसके हिमनद और हिमक्षेत्र अंटार्कटिका और ग्रीनलैंड के बाद सबसे बड़ा बर्फ़ द्रव्यमान बनाते हैं और सिंधु, गंगा, ब्रह्मपुत्र और यांग्त्ज़े जैसी नदियों को जल देते हैं, इसीलिए उनका पीछे हटना एक बड़ी चिंता है।"},
  {"id":"env-ecology-650","question":"Greenhouse gases let most incoming sunlight through but absorb the heat radiated by the Earth. This difference arises mainly because:","options":["Sunlight arrives only by day, while the Earth radiates heat only at night","Incoming sunlight is mostly ultraviolet, which no gas in the atmosphere can absorb","The Earth's surface is far cooler than the Sun, so it emits longer, infrared waves","Greenhouse gases are found only near the ground, below the level that sunlight passes through"],"answer":2,"explanation":"By Wien's law, the Sun at about 5,800 K emits mostly visible and near-infrared light, while the Earth at about 288 K emits thermal infrared around 10 µm, where CO2, water vapour and methane absorb strongly.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हरितगृह गैसें आने वाले सूर्य प्रकाश के अधिकांश भाग को गुज़रने देती हैं, परंतु पृथ्वी द्वारा विकिरित ऊष्मा को अवशोषित कर लेती हैं। यह अंतर मुख्यतः इसलिए उत्पन्न होता है क्योंकि:","optionsHi":["सूर्य का प्रकाश केवल दिन में आता है, जबकि पृथ्वी केवल रात में ऊष्मा विकिरित करती है","आने वाला सूर्य प्रकाश अधिकांशतः पराबैंगनी होता है, जिसे वायुमंडल की कोई गैस अवशोषित नहीं कर सकती","पृथ्वी की सतह सूर्य की तुलना में बहुत ठंडी है, इसलिए वह लंबी, अवरक्त तरंगें उत्सर्जित करती है","हरितगृह गैसें केवल भूमि के निकट, उस स्तर के नीचे पाई जाती हैं जहाँ से सूर्य का प्रकाश गुज़रता है"],"explanationHi":"वीन के नियम के अनुसार, लगभग 5,800 K का सूर्य मुख्यतः दृश्य और निकट-अवरक्त प्रकाश उत्सर्जित करता है, जबकि लगभग 288 K की पृथ्वी लगभग 10 µm के आसपास तापीय अवरक्त उत्सर्जित करती है, जहाँ CO2, जलवाष्प और मीथेन प्रबल रूप से अवशोषण करती हैं।"},
  {"id":"env-ecology-651","question":"Several unrelated species of butterfly that are all distasteful to birds share very similar bright warning patterns, so that a bird which learns to avoid one avoids them all. This is an example of:","options":["Batesian mimicry","Müllerian mimicry","Aggressive mimicry","Cryptic colouration"],"answer":1,"explanation":"In Müllerian mimicry all the look-alikes are unpalatable and share the cost of 'educating' predators. In Batesian mimicry a harmless species copies a harmful one.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"तितलियों की कई असंबंधित प्रजातियाँ, जो सभी पक्षियों को अरुचिकर हैं, बहुत मिलते-जुलते चटक चेतावनी प्रतिरूप साझा करती हैं, ताकि जो पक्षी एक से बचना सीख ले वह सभी से बचे। यह किसका उदाहरण है?","optionsHi":["बेट्सियन अनुकरण","म्यूलेरियन अनुकरण","आक्रामक अनुकरण","छद्मावरण रंगाई"],"explanationHi":"म्यूलेरियन अनुकरण में सभी सदृश प्रजातियाँ अरुचिकर होती हैं और परभक्षियों को 'शिक्षित' करने की लागत बाँट लेती हैं। बेट्सियन अनुकरण में एक हानिरहित प्रजाति किसी हानिकारक की नकल करती है।"},
  {"id":"env-ecology-652","question":"The monarch butterfly is highly distasteful to birds. It acquires this protection by:","options":["Synthesising alkaloids in its wing scales during the pupal stage","Absorbing toxic heavy metals from the nectar of flowers it visits","Mimicking the appearance of a stinging wasp in flight","Storing toxins from the milkweed plants its caterpillars eat"],"answer":3,"explanation":"Caterpillars feeding on milkweeds sequester cardiac glycosides, which make the adult butterfly toxic to predators, and its bright colours advertise this. Defence acquired from the host plant is a classic predator–prey–plant link.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मोनार्क तितली पक्षियों को अत्यंत अरुचिकर होती है। वह यह सुरक्षा कैसे प्राप्त करती है?","optionsHi":["प्यूपा अवस्था में अपने पंख के शल्कों में एल्कलॉइड संश्लेषित करके","जिन फूलों पर जाती है उनके मकरंद से विषैली भारी धातुएँ अवशोषित करके","उड़ान में डंक मारने वाले ततैया का रूप धरकर","मिल्कवीड पौधों से विष संचित करके, जिन्हें उसकी इल्लियाँ खाती हैं"],"explanationHi":"मिल्कवीड खाने वाली इल्लियाँ कार्डियक ग्लाइकोसाइड संचित करती हैं, जो वयस्क तितली को परभक्षियों के लिए विषैला बनाते हैं, और उसके चटक रंग इसकी सूचना देते हैं। पोषी पौधे से प्राप्त सुरक्षा परभक्षी–शिकार–पौधा संबंध का क्लासिक उदाहरण है।"},
  {"id":"env-ecology-653","question":"Cattle and goats usually avoid grazing the common wasteland shrub Calotropis (aak). This is mainly because the plant:","options":["Produces highly poisonous cardiac glycosides","Is covered in long, sharp thorns on its stems","Grows only on salt-encrusted alkaline soils","Has leaves too high for the animals to reach"],"answer":0,"explanation":"Calotropis defends itself chemically with cardiac glycosides in its milky latex. Chemical defences against herbivores are widespread in plants; Calotropis has no thorns.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"गाय-बैल और बकरियाँ सामान्यतः बंजर भूमि की आम झाड़ी कैलोट्रॉपिस (आक) को चरने से बचते हैं। इसका मुख्य कारण यह है कि पौधा:","optionsHi":["अत्यंत विषैले कार्डियक ग्लाइकोसाइड बनाता है","अपने तनों पर लंबे, तीखे काँटों से ढका होता है","केवल लवण-परत वाली क्षारीय मृदाओं पर उगता है","इसकी पत्तियाँ इतनी ऊँची होती हैं कि जंतु उन तक नहीं पहुँच पाते"],"explanationHi":"कैलोट्रॉपिस अपने दूधिया लेटेक्स में कार्डियक ग्लाइकोसाइड द्वारा रासायनिक रूप से अपनी रक्षा करता है। शाकाहारियों के विरुद्ध रासायनिक सुरक्षा पौधों में व्यापक है; कैलोट्रॉपिस में काँटे नहीं होते।"},
  {"id":"env-ecology-654","question":"The Abingdon Island tortoise of the Galápagos declined to extinction within about a decade after goats were introduced to its island. The interaction mainly responsible is best described as:","options":["Predation of tortoise eggs and hatchlings by the feral goats","Parasitism of tortoises by mites and ticks carried by goats","Amensalism through trampling of nests","Competition for plants, which goats browse more efficiently"],"answer":3,"explanation":"Goats and tortoises used the same food, and the goats' greater browsing efficiency left the tortoises without enough to eat: interspecific competition between unrelated species.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"गैलापागोस का एबिंगडन द्वीप का कछुआ अपने द्वीप पर बकरियाँ लाए जाने के लगभग एक दशक में विलुप्त हो गया। इसके लिए मुख्यतः उत्तरदायी अंतःक्रिया का सबसे उपयुक्त वर्णन है:","optionsHi":["जंगली बकरियों द्वारा कछुओं के अंडों और बच्चों का परभक्षण","बकरियों द्वारा लाए गए चिचड़ियों और किलनियों द्वारा कछुओं का परजीविता","घोंसलों को कुचलने के द्वारा अंतःहानि (एमेन्सलिज़्म)","पौधों के लिए प्रतिस्पर्धा, जिन्हें बकरियाँ अधिक दक्षता से चरती हैं"],"explanationHi":"बकरियाँ और कछुए एक ही भोजन का उपयोग करते थे, और बकरियों की अधिक चराई दक्षता ने कछुओं के पास खाने को पर्याप्त नहीं छोड़ा: असंबंधित प्रजातियों के बीच अंतरजातीय प्रतिस्पर्धा।"},
  {"id":"env-ecology-655","question":"On the rocky Scottish coast, Joseph Connell found that the barnacle Chthamalus occupied only the upper intertidal zone, though it could survive lower down when the larger barnacle Balanus was removed. This showed that:","options":["Competition from Balanus narrowed the realised niche of Chthamalus","Chthamalus is a parasite that depends on Balanus for its food supply","Balanus is a keystone predator that feeds on Chthamalus larvae","The two barnacles share a mutualistic relationship on the rocks"],"answer":0,"explanation":"Competition from Balanus excluded Chthamalus from the lower zone it could physically tolerate, shrinking its realised niche. Connell's field experiment is a classic demonstration of competitive exclusion in nature.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"स्कॉटलैंड के चट्टानी तट पर जोसेफ कोनेल ने पाया कि बार्नेकल कैथैमैलस केवल ऊपरी अंतराज्वारीय क्षेत्र में रहता था, यद्यपि बड़े बार्नेकल बैलैनस को हटा दिए जाने पर वह नीचे भी जीवित रह सकता था। इससे यह दर्शित हुआ कि:","optionsHi":["बैलैनस की प्रतिस्पर्धा ने कैथैमैलस का वास्तविकृत निकेत संकुचित कर दिया","कैथैमैलस एक परजीवी है जो अपने भोजन के लिए बैलैनस पर निर्भर है","बैलैनस एक आधारशिला परभक्षी है जो कैथैमैलस के लार्वा खाता है","दोनों बार्नेकल चट्टानों पर पारस्परिकता संबंध साझा करते हैं"],"explanationHi":"बैलैनस की प्रतिस्पर्धा ने कैथैमैलस को निचले क्षेत्र से बाहर कर दिया जिसे वह भौतिक रूप से सहन कर सकता था, जिससे उसका वास्तविकृत निकेत सिकुड़ गया। कोनेल का क्षेत्र प्रयोग प्रकृति में प्रतिस्पर्धी अपवर्जन का क्लासिक प्रदर्शन है।"},
  {"id":"env-ecology-656","question":"The human liver fluke completes its life cycle using:","options":["Only one host, the human, throughout its life cycle","Two intermediate hosts, a snail and a fish","Pigs as the only intermediate host before humans","A mosquito as the intermediate host"],"answer":1,"explanation":"Fluke larvae develop first in a snail and then in a fish, and people are infected by eating raw or undercooked fish. Complex life cycles with several hosts are a common parasitic adaptation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"मानव यकृत पर्णाभकृमि (लिवर फ्लूक) अपना जीवन चक्र किसके उपयोग से पूरा करता है?","optionsHi":["संपूर्ण जीवन चक्र में केवल एक पोषी, मनुष्य","दो मध्यवर्ती पोषी, एक घोंघा और एक मछली","मनुष्यों से पहले सूअर एकमात्र मध्यवर्ती पोषी के रूप में","एक मच्छर मध्यवर्ती पोषी के रूप में"],"explanationHi":"फ्लूक के लार्वा पहले घोंघे में और फिर मछली में विकसित होते हैं, और लोग कच्ची या अधपकी मछली खाने से संक्रमित होते हैं। अनेक पोषियों वाले जटिल जीवन चक्र परजीवियों का एक सामान्य अनुकूलन हैं।"},
  {"id":"env-ecology-657","question":"Two forest plots each contain the same four tree species and 100 trees in all. Plot P has 25 trees of each species; plot Q has 97 trees of one species and one tree of each of the others. Which statement is correct?","options":["Both have equal diversity, since species richness is the same","Q is more diverse, since it has a clearly dominant species","P is more diverse, because its species are more evenly represented","Neither can be compared without first knowing the areas of the plots"],"answer":2,"explanation":"Diversity indices such as Shannon's combine richness with evenness. With equal richness, the evenly spread plot P scores much higher than the strongly dominated plot Q.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"दो वन खंडों में प्रत्येक में वही चार वृक्ष प्रजातियाँ और कुल 100 वृक्ष हैं। खंड P में प्रत्येक प्रजाति के 25 वृक्ष हैं; खंड Q में एक प्रजाति के 97 वृक्ष और अन्य प्रत्येक का एक-एक वृक्ष है। कौन-सा कथन सही है?","optionsHi":["दोनों में विविधता समान है, क्योंकि प्रजाति समृद्धि समान है","Q अधिक विविध है, क्योंकि उसमें स्पष्ट रूप से प्रभावी प्रजाति है","P अधिक विविध है, क्योंकि उसकी प्रजातियाँ अधिक समान रूप से प्रतिनिधित्व पाती हैं","खंडों के क्षेत्रफल जाने बिना किसी की तुलना नहीं की जा सकती"],"explanationHi":"शैनन जैसे विविधता सूचकांक समृद्धि को समरूपता के साथ जोड़ते हैं। समान समृद्धि होने पर समान रूप से फैला खंड P, दृढ़ता से प्रभुत्व वाले खंड Q से बहुत अधिक अंक पाता है।"},
  {"id":"env-ecology-658","question":"According to the intermediate disturbance hypothesis, the species diversity of a community tends to be highest when disturbance is:","options":["Absent, so the community reaches a stable climax","Of intermediate frequency and intensity","Very frequent and severe, so pioneers keep arriving","Restricted to the edges of the community"],"answer":1,"explanation":"With little disturbance strong competitors exclude others; with too much only a few tolerant pioneers survive. Moderate disturbance lets both pioneer and late-successional species coexist.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"मध्यवर्ती विक्षोभ परिकल्पना के अनुसार, किसी समुदाय की प्रजाति विविधता तब सर्वाधिक होती है जब विक्षोभ:","optionsHi":["अनुपस्थित हो, ताकि समुदाय स्थिर चरम पर पहुँच जाए","मध्यम आवृत्ति और तीव्रता का हो","बहुत बार-बार और गंभीर हो, ताकि अग्रणी प्रजातियाँ आती रहें","समुदाय के किनारों तक सीमित हो"],"explanationHi":"कम विक्षोभ में प्रबल प्रतिस्पर्धी दूसरों को हटा देते हैं; बहुत अधिक विक्षोभ में केवल कुछ सहनशील अग्रणी प्रजातियाँ बचती हैं। मध्यम विक्षोभ अग्रणी और परवर्ती अनुक्रमण दोनों प्रकार की प्रजातियों को सह-अस्तित्व में रहने देता है।"},
  {"id":"env-ecology-659","question":"When Robert Paine removed the starfish Pisaster from patches of rocky shore, mussels spread over the rocks and the number of invertebrate species fell sharply. The starfish was acting as a:","options":["Foundation species that physically builds the habitat","Keystone predator preventing competitive exclusion","Flagship species that draws public support for the shore","Pioneer species starting succession"],"answer":1,"explanation":"By eating the dominant competitor (mussels), Pisaster kept space open for many other species. Its loss allowed competitive exclusion; the term 'keystone species' came from this work.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जब रॉबर्ट पेन ने चट्टानी तट के खंडों से तारामीन पिसैस्टर को हटाया, तो सीपियाँ चट्टानों पर फैल गईं और अकशेरुकी प्रजातियों की संख्या तेज़ी से घट गई। तारामीन किस रूप में कार्य कर रही थी?","optionsHi":["आधार प्रजाति, जो भौतिक रूप से आवास का निर्माण करती है","आधारशिला परभक्षी, जो प्रतिस्पर्धी अपवर्जन को रोकता है","ध्वजवाहक प्रजाति, जो तट के लिए जन समर्थन जुटाती है","अग्रणी प्रजाति, जो अनुक्रमण आरंभ करती है"],"explanationHi":"प्रभावी प्रतिस्पर्धी (सीपियों) को खाकर पिसैस्टर ने अन्य अनेक प्रजातियों के लिए स्थान खुला रखा। उसके हटने से प्रतिस्पर्धी अपवर्जन हुआ; 'आधारशिला प्रजाति' शब्द इसी कार्य से आया।"},
  {"id":"env-ecology-660","question":"Kangaroos in Australian grasslands and antelopes in African savannas are unrelated but play similar roles as large grazers in similar habitats. Such species are called:","options":["Ecological equivalents","Allopatric sibling species","Ecotypes","Keystone species"],"answer":0,"explanation":"Ecological equivalents occupy similar niches in different geographical regions. Sibling species are closely related look-alikes, and ecotypes are locally adapted forms of one species.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ऑस्ट्रेलियाई घास के मैदानों के कंगारू और अफ्रीकी सवाना के मृग असंबंधित हैं, पर समान आवासों में बड़े चरने वालों की समान भूमिकाएँ निभाते हैं। ऐसी प्रजातियाँ कहलाती हैं:","optionsHi":["पारिस्थितिक समतुल्य","अपरंपरागत (एलोपैट्रिक) सहोदर प्रजातियाँ","पारिस्थितिक प्ररूप (इकोटाइप)","आधारशिला प्रजातियाँ"],"explanationHi":"पारिस्थितिक समतुल्य विभिन्न भौगोलिक क्षेत्रों में समान निकेत धारण करते हैं। सहोदर प्रजातियाँ निकट संबंधी सदृश जीव हैं, और इकोटाइप किसी एक प्रजाति के स्थानीय रूप से अनुकूलित रूप हैं।"},
  {"id":"env-ecology-661","question":"Match the temperate grassland with its region. A. Pampas  B. Veld  C. Downs  D. Steppe; 1. South Africa  2. Eurasia  3. Argentina  4. Australia","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"answer":0,"explanation":"Pampas are in Argentina, the veld in South Africa, the downs in Australia and the steppes across Eurasia; the North American equivalent is the prairie.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"शीतोष्ण घास के मैदान का उसके क्षेत्र से मिलान कीजिए। A. पम्पास B. वेल्ड C. डाउन्स D. स्टेपी; 1. दक्षिण अफ्रीका 2. यूरेशिया 3. अर्जेंटीना 4. ऑस्ट्रेलिया","optionsHi":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"explanationHi":"पम्पास अर्जेंटीना में, वेल्ड दक्षिण अफ्रीका में, डाउन्स ऑस्ट्रेलिया में और स्टेपी पूरे यूरेशिया में हैं; उत्तरी अमेरिका में इनका समतुल्य प्रेयरी है।"},
  {"id":"env-ecology-662","question":"Consider the following statements about tropical rainforests: 1. Lianas are woody climbers rooted in the ground that use trees for support to reach light. 2. Epiphytes such as many orchids grow on trees and draw their food from the host's tissues. 3. Emergent trees rise above the general canopy. Which of the statements given above is/are correct?","options":["1 and 3 only","2 only","1, 2 and 3","2 and 3 only"],"answer":0,"explanation":"Epiphytes use trees only for support and make their own food; they are not parasites. Lianas and emergents are standard features of the multi-layered rainforest.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"उष्णकटिबंधीय वर्षावनों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. लायनाएँ भूमि में जड़ें रखने वाली काष्ठीय आरोही होती हैं जो प्रकाश तक पहुँचने के लिए वृक्षों का सहारा लेती हैं। 2. अनेक ऑर्किड जैसे अधिपादप वृक्षों पर उगते हैं और पोषी के ऊतकों से अपना भोजन लेते हैं। 3. उद्गामी वृक्ष सामान्य वितान से ऊपर उठे होते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 3","केवल 2","1, 2 और 3","केवल 2 और 3"],"explanationHi":"अधिपादप वृक्षों का उपयोग केवल सहारे के लिए करते हैं और अपना भोजन स्वयं बनाते हैं; वे परजीवी नहीं हैं। लायनाएँ और उद्गामी वृक्ष बहुस्तरीय वर्षावन की मानक विशेषताएँ हैं।"},
  {"id":"env-ecology-663","question":"Assertion (A): Climbing from the foothills to the snowline of the Himalaya, one passes through vegetation belts resembling those met when travelling from the tropics towards the poles. Reason (R): Temperature falls with altitude, much as it falls with increasing latitude. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Air cools by about 6.5 °C per kilometre of ascent, so altitude zones repeat the latitudinal sequence: tropical forest, temperate forest, conifers, alpine meadows and then snow.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): हिमालय की तलहटी से हिमरेखा तक चढ़ते समय हम उन वनस्पति पट्टियों से गुज़रते हैं जो उष्णकटिबंध से ध्रुवों की ओर यात्रा में मिलने वाली पट्टियों के समान होती हैं। कारण (R): ऊँचाई के साथ तापमान उसी प्रकार घटता है जैसे बढ़ते अक्षांश के साथ। सही विकल्प चुनिए:","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"प्रति किलोमीटर चढ़ाई पर वायु लगभग 6.5 °C ठंडी होती है, इसलिए ऊँचाई के क्षेत्र अक्षांशीय क्रम को दोहराते हैं: उष्णकटिबंधीय वन, शीतोष्ण वन, शंकुधारी वन, अल्पाइन चारागाह और फिर बर्फ़।"},
  {"id":"env-ecology-664","question":"Which of the following pairs of interaction are correctly matched? 1. Cattle egret feeding on insects disturbed by grazing cattle — commensalism 2. Barnacles growing on the skin of a whale — commensalism 3. Honeybees and the flowering plants they visit — mutualism 4. Tapeworm in the human intestine — amensalism. Select the correct answer:","options":["1 and 3 only","2, 3 and 4 only","1, 2 and 3 only","1, 2, 3 and 4"],"answer":2,"explanation":"The egret and the barnacles gain while their hosts are largely unaffected, and bees and flowers both benefit. A tapeworm harms its host while benefiting itself, which is parasitism, not amensalism.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अंतःक्रिया के निम्नलिखित में से कौन-से जोड़े सही सुमेलित हैं? 1. चरते मवेशियों द्वारा उड़ाए गए कीटों को खाने वाला गोवंश बगुला — सहभोजिता 2. व्हेल की त्वचा पर उगने वाले बार्नेकल — सहभोजिता 3. मधुमक्खियाँ और वे पुष्पीय पौधे जिन पर वे जाती हैं — पारस्परिकता 4. मानव आंत्र में फीताकृमि — अंतःहानि। सही उत्तर चुनिए:","optionsHi":["केवल 1 और 3","केवल 2, 3 और 4","केवल 1, 2 और 3","1, 2, 3 और 4"],"explanationHi":"बगुले और बार्नेकल को लाभ होता है जबकि उनके पोषी बड़े पैमाने पर अप्रभावित रहते हैं, और मधुमक्खियों तथा फूलों दोनों को लाभ होता है। फीताकृमि अपने पोषी को हानि पहुँचाता है और स्वयं लाभ लेता है, जो परजीविता है, अंतःहानि नहीं।"},
  {"id":"env-ecology-665","question":"In community ecology, a group of species that exploit the same kind of resource in a similar way, such as all the birds that glean insects from foliage in a forest, is called a:","options":["Trophic level","Population","Guild","Biome"],"answer":2,"explanation":"A guild groups species by how they use a resource, regardless of relatedness. A trophic level is broader, including all organisms at the same feeding step.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"समुदाय पारिस्थितिकी में, ऐसी प्रजातियों का समूह जो एक ही प्रकार के संसाधन का समान ढंग से दोहन करती हैं, जैसे वन में पत्तियों से कीट चुगने वाले सभी पक्षी, क्या कहलाता है?","optionsHi":["पोषी स्तर","समष्टि","गिल्ड (संघ)","बायोम"],"explanationHi":"गिल्ड प्रजातियों को इस आधार पर समूहित करता है कि वे संसाधन का कैसे उपयोग करती हैं, उनके संबंध की परवाह किए बिना। पोषी स्तर अधिक व्यापक है, जिसमें एक ही भोजन चरण के सभी जीव आते हैं।"},
  {"id":"env-ecology-666","question":"In Opuntia and many other cacti, leaves are reduced to spines. Photosynthesis in these plants is carried out mainly by:","options":["Underground storage roots","The spines themselves","Specialised root hairs","Flattened green stems"],"answer":3,"explanation":"The flattened, green stems (phylloclades) take over photosynthesis, while spines cut water loss and deter herbivores. Many cacti also use CAM to keep stomata closed by day.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"ओपंशिया और अनेक अन्य कैक्टसों में पत्तियाँ काँटों में बदल गई हैं। इन पौधों में प्रकाश संश्लेषण मुख्यतः किसके द्वारा होता है?","optionsHi":["भूमिगत संचयी जड़ों द्वारा","स्वयं काँटों द्वारा","विशिष्ट मूल रोमों द्वारा","चपटे हरे तनों द्वारा"],"explanationHi":"चपटे, हरे तने (पर्णाभ स्तंभ) प्रकाश संश्लेषण का कार्य संभालते हैं, जबकि काँटे जल हानि घटाते हैं और शाकाहारियों को रोकते हैं। अनेक कैक्टस दिन में रंध्र बंद रखने के लिए CAM का भी उपयोग करते हैं।"},
  {"id":"env-ecology-667","question":"The kangaroo rat of North American deserts can live without ever drinking water. It manages this mainly by:","options":["Storing large volumes of water in its swollen tail to use during dry spells","Absorbing atmospheric moisture through its skin and fur during cool nights","Making water by oxidising fat and excreting very concentrated urine","Feeding only on juicy cactus stems that are rich in stored water and salts"],"answer":2,"explanation":"Metabolic water from fat oxidation, very concentrated urine and nocturnal habits let it balance its water budget on dry seeds alone.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"उत्तरी अमेरिका के मरुस्थलों का कंगारू चूहा बिना कभी पानी पिए जीवित रह सकता है। वह यह मुख्यतः कैसे करता है?","optionsHi":["शुष्क काल में उपयोग के लिए अपनी फूली पूँछ में जल की बड़ी मात्रा संचित करके","ठंडी रातों में अपनी त्वचा और रोमों से वायुमंडलीय नमी अवशोषित करके","वसा के ऑक्सीकरण से जल बनाकर और अत्यंत सांद्र मूत्र उत्सर्जित करके","केवल रसीले कैक्टस तनों को खाकर, जो संचित जल और लवणों से समृद्ध होते हैं"],"explanationHi":"वसा के ऑक्सीकरण से बना उपापचयी जल, अत्यंत सांद्र मूत्र और निशाचर आदतें उसे केवल सूखे बीजों पर अपना जल बजट संतुलित करने देती हैं।"},
  {"id":"env-ecology-668","question":"The roots and fallen leaves of the black walnut tree release juglone, a chemical that stops many other plants from growing near it. This phenomenon is called:","options":["Mutualism","Allelopathy","Commensalism","Competitive release"],"answer":1,"explanation":"Allelopathy is chemical inhibition of one plant by another, a form of amensalism. Competitive release is the expansion of a species' niche after a competitor is removed.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"काले अखरोट के वृक्ष की जड़ें और गिरी पत्तियाँ जग्लोन नामक रसायन छोड़ती हैं, जो उसके निकट अनेक अन्य पौधों को उगने से रोकता है। इस परिघटना को कहते हैं:","optionsHi":["पारस्परिकता","एलीलोपैथी (अपरासरण)","सहभोजिता","प्रतिस्पर्धा से मुक्ति"],"explanationHi":"एलीलोपैथी एक पौधे द्वारा दूसरे का रासायनिक संदमन है, जो अंतःहानि का एक रूप है। प्रतिस्पर्धा से मुक्ति किसी प्रतिस्पर्धी के हटाए जाने पर प्रजाति के निकेत का विस्तार है।"},
  {"id":"env-ecology-669","question":"In many forests, eagles and hawks hunt small mammals by day, while owls hunt similar prey at night. Their coexistence is an example of:","options":["Temporal resource partitioning","Commensalism between predators","Batesian mimicry","Competitive exclusion"],"answer":0,"explanation":"Dividing the use of a shared resource by time of day reduces direct competition. Partitioning can also be spatial or by type of food.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"अनेक वनों में चील और बाज दिन में छोटे स्तनधारियों का शिकार करते हैं, जबकि उल्लू समान शिकार रात में करते हैं। उनका सह-अस्तित्व किसका उदाहरण है?","optionsHi":["कालिक संसाधन विभाजन","परभक्षियों के बीच सहभोजिता","बेट्सियन अनुकरण","प्रतिस्पर्धी अपवर्जन"],"explanationHi":"साझा संसाधन के उपयोग को दिन के समय के अनुसार बाँटने से प्रत्यक्ष प्रतिस्पर्धा घटती है। विभाजन स्थानिक या भोजन के प्रकार के आधार पर भी हो सकता है।"},
  {"id":"env-ecology-670","question":"After examining a Madagascar orchid whose nectar lay at the bottom of a spur about 30 cm long, Charles Darwin predicted the existence of a moth with an equally long proboscis, which was later discovered. This illustrates:","options":["Convergent evolution","Coevolution","Adaptive radiation","Industrial melanism"],"answer":1,"explanation":"Plant and pollinator evolved reciprocally, the flower's spur lengthening with the moth's tongue. Convergent evolution concerns unrelated species becoming alike, not paired adaptation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"लगभग 30 cm लंबे स्पर के तल में मकरंद रखने वाले मेडागास्कर के एक ऑर्किड की जाँच के बाद चार्ल्स डार्विन ने उतनी ही लंबी सूंड वाले एक पतंगे के अस्तित्व की भविष्यवाणी की, जो बाद में खोजा गया। यह किसे दर्शाता है?","optionsHi":["अभिसारी विकास","सह-विकास","अनुकूली विकिरण","औद्योगिक मेलैनिज़्म"],"explanationHi":"पौधा और परागणकर्ता एक-दूसरे के प्रत्युत्तर में विकसित हुए, फूल का स्पर पतंगे की जीभ के साथ लंबा होता गया। अभिसारी विकास असंबंधित प्रजातियों के एक-दूसरे जैसी बन जाने से संबंधित है, युग्मित अनुकूलन से नहीं।"},
  {"id":"env-ecology-671","question":"In Central America, certain ants live in the hollow thorns of bullhorn acacias, feed on nectar and protein-rich bodies produced by the tree, and aggressively attack herbivores and clear competing plants around it. This relationship is:","options":["Parasitism of the tree by the ants","Commensalism, the tree being unaffected","Amensalism, the ants harming the tree","Mutualism benefiting both partners"],"answer":3,"explanation":"The tree provides food and shelter while the ants defend it; experiments show acacias without ants grow poorly. Both partners benefit, so it is mutualism.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मध्य अमेरिका में कुछ चींटियाँ बुलहॉर्न बबूल के खोखले काँटों में रहती हैं, वृक्ष द्वारा उत्पन्न मकरंद और प्रोटीन-समृद्ध पिंडों को खाती हैं, और शाकाहारियों पर आक्रामक रूप से हमला करती हैं तथा उसके चारों ओर प्रतिस्पर्धी पौधों को साफ़ कर देती हैं। यह संबंध है:","optionsHi":["चींटियों द्वारा वृक्ष का परजीविता","सहभोजिता, जिसमें वृक्ष अप्रभावित रहता है","अंतःहानि, जिसमें चींटियाँ वृक्ष को हानि पहुँचाती हैं","पारस्परिकता, जिससे दोनों साझेदारों को लाभ होता है"],"explanationHi":"वृक्ष भोजन और आश्रय देता है जबकि चींटियाँ उसकी रक्षा करती हैं; प्रयोग दिखाते हैं कि चींटियों के बिना बबूल खराब बढ़ते हैं। दोनों साझेदारों को लाभ होता है, इसलिए यह पारस्परिकता है।"},
  {"id":"env-ecology-672","question":"'Reindeer moss', a major winter food of reindeer and caribou in the tundra, is actually a:","options":["Moss","Fern","Liverwort","Lichen"],"answer":3,"explanation":"Reindeer moss (Cladonia) is a lichen, a fungus–alga partnership, despite its name. Its slow growth makes tundra pastures vulnerable to overgrazing.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"'रेनडियर मॉस', जो टुंड्रा में रेनडियर और कैरिबू का प्रमुख शीतकालीन भोजन है, वास्तव में है:","optionsHi":["मॉस","फर्न","लिवरवर्ट","लाइकेन"],"explanationHi":"रेनडियर मॉस (क्लैडोनिया) नाम के बावजूद एक लाइकेन है, जो कवक–शैवाल की साझेदारी है। इसकी धीमी वृद्धि टुंड्रा चारागाहों को अतिचराई के प्रति संवेदनशील बनाती है।"},
  {"id":"env-ecology-673","question":"In which of the following biomes is the share of ecosystem organic carbon held in the soil, rather than in living vegetation, the greatest?","options":["Tropical rainforest","Tropical savanna","Hot desert","Arctic tundra"],"answer":3,"explanation":"Cold, waterlogged tundra soils decompose organic matter very slowly, so most carbon lies in soil and permafrost. In tropical rainforests much of the carbon is in the trees themselves.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से किस बायोम में पारिस्थितिकी तंत्र का कार्बनिक कार्बन जीवित वनस्पति के बजाय मृदा में अधिकतम अनुपात में संचित होता है?","optionsHi":["उष्णकटिबंधीय वर्षावन","उष्णकटिबंधीय सवाना","उष्ण मरुस्थल","आर्कटिक टुंड्रा"],"explanationHi":"ठंडी, जलमग्न टुंड्रा मृदाओं में कार्बनिक पदार्थ बहुत धीमे अपघटित होता है, इसलिए अधिकांश कार्बन मृदा और पर्माफ्रॉस्ट में रहता है। उष्णकटिबंधीय वर्षावनों में कार्बन का बड़ा भाग वृक्षों में ही होता है।"},
  {"id":"env-ecology-674","question":"Which one of the following is NOT a typical adaptation of endoparasites such as tapeworms?","options":["Hooks or suckers for attachment to the host","Very high reproductive capacity","Well-developed sense organs","Loss or reduction of the digestive system"],"answer":2,"explanation":"Living inside a host with food all around, endoparasites lose unnecessary organs, including sense organs and often the gut, while developing attachment organs and huge reproductive output.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सा फीताकृमि जैसे अंतःपरजीवियों का एक विशिष्ट अनुकूलन नहीं है?","optionsHi":["पोषी से चिपकने के लिए अंकुश या चूषक","बहुत उच्च प्रजनन क्षमता","भली-भाँति विकसित संवेदी अंग","पाचन तंत्र का लोप या ह्रास"],"explanationHi":"पोषी के भीतर रहते हुए जहाँ चारों ओर भोजन है, अंतःपरजीवी अनावश्यक अंग खो देते हैं, जिनमें संवेदी अंग और प्रायः आहारनाल शामिल हैं, जबकि चिपकने के अंग और विशाल प्रजनन उत्पादन विकसित करते हैं।"},
  {"id":"env-ecology-675","question":"Trees of the temperate deciduous forest shed their broad leaves in autumn. The main advantage of this is that it helps them:","options":["Get rid of salts that have built up in the leaves before spring growth","Let more sunlight reach the herbs of the forest floor in winter","Avoid water loss and frost damage while soil water is frozen in winter","Return nitrogen to the soil quickly in time for the next season"],"answer":2,"explanation":"In winter, frozen soil makes water unavailable while broad leaves would keep losing it and suffer frost damage, so shedding them is a drought-and-cold adaptation. Most leaf nitrogen is actually withdrawn into the tree before leaf fall.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"शीतोष्ण पर्णपाती वन के वृक्ष शरद ऋतु में अपनी चौड़ी पत्तियाँ गिरा देते हैं। इसका मुख्य लाभ यह है कि इससे उन्हें सहायता मिलती है:","optionsHi":["वसंत की वृद्धि से पहले पत्तियों में जमा हुए लवणों से छुटकारा पाने में","सर्दियों में वन के तल की शाकों तक अधिक सूर्य प्रकाश पहुँचने देने में","सर्दियों में मृदा जल जम जाने पर जल हानि और पाले की क्षति से बचने में","अगली ऋतु के लिए समय पर नाइट्रोजन को शीघ्र मृदा में लौटाने में"],"explanationHi":"सर्दियों में जमी मृदा जल को अनुपलब्ध कर देती है, जबकि चौड़ी पत्तियाँ जल खोती रहतीं और पाले से क्षतिग्रस्त होतीं, इसलिए उन्हें गिराना सूखे और ठंड के प्रति अनुकूलन है। पत्तियों की अधिकांश नाइट्रोजन वास्तव में पत्ती गिरने से पहले वृक्ष में वापस खींच ली जाती है।"},
  {"id":"env-ecology-676","question":"Consider the following measures: 1. Breeding drought-tolerant crop varieties 2. Restoring mangrove belts to buffer storm surges 3. Replacing a coal power plant with a solar park 4. Running a city heat action plan with early warnings and cool shelters. How many of these are primarily adaptation (rather than mitigation) measures?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Adaptation reduces harm from climate change that is already happening or expected; measures 1, 2 and 4 do that. Replacing coal with solar cuts emissions, which is mitigation (mangroves also store carbon, but buffering surges is an adaptation aim).","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित उपायों पर विचार कीजिए: 1. सूखा-सहिष्णु फसल किस्मों का प्रजनन 2. तूफ़ानी लहरों को रोकने के लिए मैंग्रोव पट्टियों की बहाली 3. कोयला विद्युत संयंत्र को सौर पार्क से बदलना 4. पूर्व चेतावनी और शीतल आश्रयों के साथ शहर की ऊष्मा कार्य योजना चलाना। इनमें से कितने मुख्यतः अनुकूलन (न कि शमन) के उपाय हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"अनुकूलन जलवायु परिवर्तन से हो चुकी या अपेक्षित हानि को घटाता है; उपाय 1, 2 और 4 यही करते हैं। कोयले को सौर से बदलना उत्सर्जन घटाता है, जो शमन है (मैंग्रोव कार्बन भी संचित करते हैं, परंतु तूफ़ानी लहरों को रोकना अनुकूलन का उद्देश्य है)।"},
  {"id":"env-ecology-677","question":"The first city in South Asia to adopt a formal Heat Action Plan, in 2013, after a deadly heat wave in 2010 was:","options":["Ahmedabad","Nagpur","Jaipur","Hyderabad"],"answer":0,"explanation":"Ahmedabad's plan, prepared with public health experts, set up early warnings, cool shelters, hospital readiness and public outreach; it later became a model for heat action plans across Indian cities and states.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2010 की घातक लू के बाद 2013 में औपचारिक ऊष्मा कार्य योजना अपनाने वाला दक्षिण एशिया का पहला शहर कौन-सा था?","optionsHi":["अहमदाबाद","नागपुर","जयपुर","हैदराबाद"],"explanationHi":"अहमदाबाद की योजना, जो जन स्वास्थ्य विशेषज्ञों के साथ तैयार की गई, में पूर्व चेतावनी, शीतल आश्रय, अस्पताल तत्परता और जन संपर्क की व्यवस्था थी; बाद में यह भारतीय शहरों और राज्यों की ऊष्मा कार्य योजनाओं के लिए आदर्श बनी।"},
  {"id":"env-ecology-678","question":"Under India's National Adaptation Fund for Climate Change (NAFCC), the National Implementing Entity that appraises and channels funds to state adaptation projects is:","options":["The Indian Renewable Energy Development Agency (IREDA)","The Bureau of Energy Efficiency","The Small Industries Development Bank of India (SIDBI)","The National Bank for Agriculture and Rural Development"],"answer":3,"explanation":"NABARD is the National Implementing Entity for the NAFCC, launched in 2015, and also for the UNFCCC's Adaptation Fund in India. BEE deals with energy efficiency, a mitigation area.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत के राष्ट्रीय जलवायु परिवर्तन अनुकूलन कोष (NAFCC) के अंतर्गत राज्यों की अनुकूलन परियोजनाओं का मूल्यांकन करने और उनके लिए निधि भेजने वाला राष्ट्रीय क्रियान्वयन निकाय कौन-सा है?","optionsHi":["भारतीय नवीकरणीय ऊर्जा विकास एजेंसी (IREDA)","ऊर्जा दक्षता ब्यूरो","भारतीय लघु उद्योग विकास बैंक (SIDBI)","राष्ट्रीय कृषि और ग्रामीण विकास बैंक"],"explanationHi":"नाबार्ड 2015 में शुरू हुए NAFCC का, और भारत में UNFCCC के अनुकूलन कोष का भी, राष्ट्रीय क्रियान्वयन निकाय है। BEE ऊर्जा दक्षता, यानी शमन क्षेत्र, से संबंधित है।"},
  {"id":"env-ecology-679","question":"State Action Plans on Climate Change (SAPCCs) in India are:","options":["Prepared by the Central Pollution Control Board for each state","Prepared by state governments in line with the NAPCC and its national missions","Binding emission-reduction targets set for each state under the Paris Agreement","Plans that each state must submit directly to the UNFCCC secretariat every five years"],"answer":1,"explanation":"States were asked from about 2009 onward to prepare SAPCCs that apply the NAPCC's missions to local conditions. Only the national government reports to the UNFCCC, and the Paris Agreement sets no state-level targets.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भारत में जलवायु परिवर्तन पर राज्य कार्य योजनाएँ (SAPCCs) हैं:","optionsHi":["केंद्रीय प्रदूषण नियंत्रण बोर्ड द्वारा प्रत्येक राज्य के लिए तैयार की गई","NAPCC और उसके राष्ट्रीय मिशनों के अनुरूप राज्य सरकारों द्वारा तैयार की गई","पेरिस समझौते के अंतर्गत प्रत्येक राज्य के लिए निर्धारित बाध्यकारी उत्सर्जन-कटौती लक्ष्य","ऐसी योजनाएँ जिन्हें प्रत्येक राज्य को हर पाँच वर्ष में सीधे UNFCCC सचिवालय को प्रस्तुत करना होता है"],"explanationHi":"राज्यों से लगभग 2009 से SAPCC तैयार करने को कहा गया जो NAPCC के मिशनों को स्थानीय परिस्थितियों पर लागू करती हैं। केवल केंद्र सरकार UNFCCC को रिपोर्ट करती है, और पेरिस समझौता कोई राज्य-स्तरीय लक्ष्य निर्धारित नहीं करता।"},
  {"id":"env-ecology-680","question":"In its Nationally Determined Contribution, India committed to create an additional carbon sink through additional forest and tree cover by 2030 of:","options":["0.5 to 1 billion tonnes of CO2 equivalent","1 to 1.5 billion tonnes of CO2 equivalent","2.5 to 3 billion tonnes of CO2 equivalent","5 to 6 billion tonnes of CO2 equivalent"],"answer":2,"explanation":"The forestry target of 2.5–3 billion tonnes CO2e, set in 2015, was retained in the 2022 update, which also raised the emissions-intensity target to 45 per cent below 2005 and the non-fossil power capacity target to about 50 per cent by 2030.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"अपने राष्ट्रीय स्तर पर निर्धारित योगदान में भारत ने 2030 तक अतिरिक्त वन और वृक्ष आवरण द्वारा कितना अतिरिक्त कार्बन अवशोषक बनाने की प्रतिबद्धता जताई?","optionsHi":["0.5 से 1 अरब टन CO2 समतुल्य","1 से 1.5 अरब टन CO2 समतुल्य","2.5 से 3 अरब टन CO2 समतुल्य","5 से 6 अरब टन CO2 समतुल्य"],"explanationHi":"2015 में निर्धारित 2.5–3 अरब टन CO2e का वानिकी लक्ष्य 2022 के अद्यतन में बनाए रखा गया, जिसमें उत्सर्जन-तीव्रता लक्ष्य को 2005 से 45 प्रतिशत नीचे और गैर-जीवाश्म विद्युत क्षमता लक्ष्य को 2030 तक लगभग 50 प्रतिशत भी बढ़ाया गया।"},
  {"id":"env-ecology-681","question":"Which one of the following was NOT among the five commitments ('Panchamrit') announced by India at COP-26 in Glasgow in 2021?","options":["Reaching 500 GW of non-fossil energy capacity by 2030","Reducing projected carbon emissions by one billion tonnes by 2030","Reaching net-zero emissions by 2070","Phasing out all coal-based power generation by 2040"],"answer":3,"explanation":"The Panchamrit were 500 GW non-fossil capacity, 50 per cent of energy needs from renewables, a one-billion-tonne cut in projected emissions and under 45 per cent carbon intensity, all by 2030, and net zero by 2070. India made no coal phase-out date.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2021 में ग्लासगो के COP-26 में भारत द्वारा घोषित पाँच प्रतिबद्धताओं ('पंचामृत') में निम्नलिखित में से कौन-सी शामिल नहीं थी?","optionsHi":["500 GW गैर-जीवाश्म ऊर्जा क्षमता प्राप्त करना, 2030 तक","2030 तक अनुमानित कार्बन उत्सर्जन में एक अरब टन की कमी","2070 तक शुद्ध-शून्य उत्सर्जन प्राप्त करना","2040 तक सभी कोयला-आधारित विद्युत उत्पादन को चरणबद्ध रूप से समाप्त करना"],"explanationHi":"पंचामृत थे: 500 GW गैर-जीवाश्म क्षमता, ऊर्जा आवश्यकताओं का 50 प्रतिशत नवीकरणीय से, अनुमानित उत्सर्जन में एक अरब टन की कटौती और कार्बन तीव्रता में 45 प्रतिशत से कम, सब 2030 तक, और 2070 तक शुद्ध-शून्य। भारत ने कोयला समाप्ति की कोई तिथि नहीं दी।"},
  {"id":"env-ecology-682","question":"Mission LiFE, promoted by India from 2021–22, stands for:","options":["Lifestyle for Environment, a movement for mindful, sustainable consumption","Low-Impact Forest Ecosystems, a national programme to restore degraded forests","Livelihoods in Fragile Ecosystems, a scheme for Himalayan and coastal communities","Legal Initiative for the Environment, a plan to revise and update India's green laws"],"answer":0,"explanation":"LiFE was announced by India at COP-26 in 2021 and launched as Mission LiFE in 2022; it urges individuals and communities to adopt habits such as saving energy and water and reducing waste.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"2021–22 से भारत द्वारा प्रवर्तित मिशन LiFE का पूर्ण रूप क्या है?","optionsHi":["पर्यावरण के लिए जीवन शैली (Lifestyle for Environment), सजग, सतत उपभोग का एक आंदोलन","निम्न-प्रभाव वन पारिस्थितिकी तंत्र (Low-Impact Forest Ecosystems), निम्नीकृत वनों की बहाली का राष्ट्रीय कार्यक्रम","नाज़ुक पारिस्थितिकी तंत्रों में आजीविका (Livelihoods in Fragile Ecosystems), हिमालयी और तटीय समुदायों के लिए योजना","पर्यावरण के लिए वैधानिक पहल (Legal Initiative for the Environment), भारत के हरित कानूनों को संशोधित और अद्यतन करने की योजना"],"explanationHi":"LiFE की घोषणा भारत ने 2021 में COP-26 में की और 2022 में मिशन LiFE के रूप में शुरू किया; यह व्यक्तियों और समुदायों से ऊर्जा और जल की बचत तथा अपशिष्ट घटाने जैसी आदतें अपनाने का आग्रह करता है।"},
  {"id":"env-ecology-683","question":"Consider the following statements about the Green Credit Programme notified by India in 2023: 1. It was notified under the Environment (Protection) Act, 1986. 2. It rewards voluntary environmental actions such as tree plantation and water conservation with tradable green credits. 3. It replaces India's commitments under the Paris Agreement. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The Green Credit Rules, 2023 were framed under the EP Act, with the Indian Council of Forestry Research and Education as administrator, to reward voluntary actions. It is a domestic market-based scheme and does not replace India's NDC.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2023 में भारत द्वारा अधिसूचित हरित ऋण कार्यक्रम के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसे पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत अधिसूचित किया गया। 2. यह वृक्षारोपण और जल संरक्षण जैसी स्वैच्छिक पर्यावरणीय कार्रवाइयों को व्यापार-योग्य हरित ऋणों से पुरस्कृत करता है। 3. यह पेरिस समझौते के अंतर्गत भारत की प्रतिबद्धताओं का स्थान लेता है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"हरित ऋण नियम, 2023 स्वैच्छिक कार्रवाइयों को पुरस्कृत करने के लिए EP अधिनियम के अंतर्गत बनाए गए, जिसमें भारतीय वानिकी अनुसंधान और शिक्षा परिषद प्रशासक है। यह घरेलू बाज़ार-आधारित योजना है और भारत के NDC का स्थान नहीं लेती।"},
  {"id":"env-ecology-684","question":"India's Carbon Credit Trading Scheme, notified in 2023, draws its legal authority from:","options":["The Environment (Protection) Act, 1986","The Air (Prevention and Control of Pollution) Act, 1981","The Energy Conservation Act, 2001, as amended in 2022","The Electricity Act, 2003, as amended in 2021"],"answer":2,"explanation":"The 2022 amendment to the Energy Conservation Act empowered the Centre to specify a carbon credit trading scheme, and the Bureau of Energy Efficiency acts as its administrator; the PAT scheme also stems from this Act.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2023 में अधिसूचित भारत की कार्बन क्रेडिट व्यापार योजना अपना कानूनी अधिकार किससे प्राप्त करती है?","optionsHi":["पर्यावरण (संरक्षण) अधिनियम, 1986","वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1981","ऊर्जा संरक्षण अधिनियम, 2001, जैसा 2022 में संशोधित","विद्युत अधिनियम, 2003, जैसा 2021 में संशोधित"],"explanationHi":"ऊर्जा संरक्षण अधिनियम के 2022 के संशोधन ने केंद्र को कार्बन क्रेडिट व्यापार योजना निर्दिष्ट करने का अधिकार दिया, और ऊर्जा दक्षता ब्यूरो उसका प्रशासक है; PAT योजना भी इसी अधिनियम से निकलती है।"},
  {"id":"env-ecology-685","question":"Consider the following statements about the International Solar Alliance: 1. It was launched by India and France at COP-21 in Paris in 2015. 2. Its headquarters is at Gurugram in India. 3. Membership is restricted to countries lying between the Tropics of Cancer and Capricorn. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The ISA began as an alliance of sunshine-rich tropical countries, but its framework agreement was later amended to open membership to all UN member states. It is headquartered in Gurugram.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अंतर्राष्ट्रीय सौर गठबंधन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसे 2015 में पेरिस के COP-21 में भारत और फ्रांस ने शुरू किया। 2. इसका मुख्यालय भारत में गुरुग्राम में है। 3. सदस्यता कर्क रेखा और मकर रेखा के बीच स्थित देशों तक सीमित है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"ISA की शुरुआत धूप-समृद्ध उष्णकटिबंधीय देशों के गठबंधन के रूप में हुई, परंतु बाद में उसके रूपरेखा समझौते को संशोधित करके सदस्यता सभी संयुक्त राष्ट्र सदस्य देशों के लिए खोल दी गई। इसका मुख्यालय गुरुग्राम में है।"},
  {"id":"env-ecology-686","question":"The Coalition for Disaster Resilient Infrastructure (CDRI), whose secretariat is in New Delhi, was launched in 2019 at:","options":["The G20 summit at Osaka","COP-25 of the UNFCCC at Madrid","The Sendai conference on disaster risk reduction","The UN Climate Action Summit in New York"],"answer":3,"explanation":"India launched CDRI at the UN Secretary-General's Climate Action Summit in September 2019 as a partnership of countries and agencies to make infrastructure resilient to climate and disaster risks.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"आपदा-सह अवसंरचना गठबंधन (CDRI), जिसका सचिवालय नई दिल्ली में है, 2019 में कहाँ शुरू किया गया?","optionsHi":["ओसाका में G20 शिखर सम्मेलन में","मैड्रिड में UNFCCC के COP-25 में","आपदा जोखिम न्यूनीकरण पर सेंडाई सम्मेलन में","न्यूयॉर्क में संयुक्त राष्ट्र जलवायु कार्रवाई शिखर सम्मेलन में"],"explanationHi":"भारत ने CDRI को सितंबर 2019 में संयुक्त राष्ट्र महासचिव के जलवायु कार्रवाई शिखर सम्मेलन में, जलवायु और आपदा जोखिमों के प्रति अवसंरचना को सुदृढ़ बनाने के लिए देशों और एजेंसियों की साझेदारी के रूप में शुरू किया।"},
  {"id":"env-ecology-687","question":"The Leadership Group for Industry Transition (LeadIT), which works on decarbonising heavy industries such as steel and cement, was launched in 2019 by India together with:","options":["France","Sweden","Germany","Japan"],"answer":1,"explanation":"India and Sweden launched LeadIT at the UN Climate Action Summit in 2019. France partnered India in founding the International Solar Alliance, a frequent source of confusion.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"इस्पात और सीमेंट जैसे भारी उद्योगों के कार्बन-मुक्तिकरण पर कार्य करने वाला औद्योगिक संक्रमण नेतृत्व समूह (LeadIT) 2019 में भारत ने किसके साथ मिलकर शुरू किया?","optionsHi":["फ्रांस","स्वीडन","जर्मनी","जापान"],"explanationHi":"भारत और स्वीडन ने 2019 में संयुक्त राष्ट्र जलवायु कार्रवाई शिखर सम्मेलन में LeadIT शुरू किया। फ्रांस ने अंतर्राष्ट्रीय सौर गठबंधन की स्थापना में भारत का साथ दिया था, जो भ्रम का एक आम कारण है।"},
  {"id":"env-ecology-688","question":"Which of the following is the best example of 'maladaptation' to climate change?","options":["Restoring floodplain wetlands so that they store floodwater during heavy rain","Planting heat-tolerant wheat varieties in the plains ahead of hotter summers","A sea wall that saves one beach but speeds up erosion further along the coast","Shifting school hours to the cooler early morning during heat-wave weeks"],"answer":2,"explanation":"Maladaptation is an action meant to reduce climate risk that ends up raising vulnerability elsewhere, for others or in the future. A sea wall that diverts erosion to neighbouring coasts is a classic case; the other options reduce risk without such side effects.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जलवायु परिवर्तन के प्रति 'कुअनुकूलन' का सबसे अच्छा उदाहरण निम्नलिखित में से कौन-सा है?","optionsHi":["बाढ़ के मैदानों की आर्द्रभूमियों की बहाली ताकि वे भारी वर्षा में बाढ़ का जल संचित करें","गर्मियों से पहले मैदानों में ऊष्मा-सहिष्णु गेहूँ की किस्में लगाना","समुद्री दीवार जो एक तट को बचाती है परंतु आगे तट पर अपरदन को तेज़ कर देती है","लू के सप्ताहों में स्कूलों का समय ठंडी तड़के सुबह में कर देना"],"explanationHi":"कुअनुकूलन ऐसी कार्रवाई है जो जलवायु जोखिम घटाने के लिए की जाती है, परंतु कहीं और, दूसरों के लिए या भविष्य में, संवेदनशीलता बढ़ा देती है। पड़ोसी तटों की ओर अपरदन मोड़ने वाली समुद्री दीवार इसका क्लासिक उदाहरण है; अन्य विकल्प ऐसे पार्श्व प्रभावों के बिना जोखिम घटाते हैं।"},
  {"id":"env-ecology-689","question":"The decision to establish a dedicated fund for responding to loss and damage from climate change, for vulnerable developing countries, was taken at:","options":["COP-27 at Sharm el-Sheikh","COP-28 at Dubai, United Arab Emirates","COP-19 at Warsaw, Poland","COP-26 at Glasgow, UK"],"answer":0,"explanation":"COP-27 (2022) agreed to set up the fund, and COP-28 at Dubai (2023) made it operational. COP-19 at Warsaw created the Warsaw International Mechanism, which deals with loss and damage but is not a fund.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"असुरक्षित विकासशील देशों के लिए जलवायु परिवर्तन से होने वाली हानि और क्षति से निपटने के लिए समर्पित कोष स्थापित करने का निर्णय कहाँ लिया गया?","optionsHi":["शर्म अल-शेख़ में COP-27","दुबई, संयुक्त अरब अमीरात में COP-28","वारसॉ, पोलैंड में COP-19","ग्लासगो, यूके में COP-26"],"explanationHi":"COP-27 (2022) ने कोष स्थापित करने पर सहमति दी, और दुबई में COP-28 (2023) ने उसे प्रचालित किया। वारसॉ में COP-19 ने वारसॉ अंतर्राष्ट्रीय तंत्र बनाया, जो हानि और क्षति से निपटता है परंतु कोष नहीं है।"},
  {"id":"env-ecology-690","question":"Consider the following statements about the 'Global Stocktake' under the Paris Agreement: 1. It assesses the collective progress of all parties towards the agreement's long-term goals. 2. It is held every five years. 3. The first one was concluded at COP-28 in 2023. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Under Article 14, the stocktake reviews collective, not individual, progress every five years and informs the next round of NDCs. The first was completed at COP-28 in Dubai.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पेरिस समझौते के अंतर्गत 'वैश्विक समीक्षा (ग्लोबल स्टॉकटेक)' के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह समझौते के दीर्घकालिक लक्ष्यों की दिशा में सभी पक्षों की सामूहिक प्रगति का आकलन करती है। 2. यह प्रत्येक पाँच वर्ष में की जाती है। 3. पहली 2023 में COP-28 में संपन्न हुई। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अनुच्छेद 14 के अंतर्गत यह समीक्षा प्रत्येक पाँच वर्ष में व्यक्तिगत नहीं, सामूहिक प्रगति का पुनरावलोकन करती है और NDC के अगले दौर को सूचित करती है। पहली दुबई में COP-28 में पूरी हुई।"},
  {"id":"env-ecology-691","question":"The pledge by developed countries to mobilise 100 billion US dollars a year in climate finance for developing countries by 2020 was first made at:","options":["COP-3 at Kyoto in 1997","COP-15 at Copenhagen in 2009","COP-21 at Paris in 2015","COP-16 at Cancún, Mexico, in 2010"],"answer":1,"explanation":"The goal appeared in the Copenhagen Accord (2009), was formalised at Cancún in 2010 and extended to 2025 at Paris. Kyoto set emission targets; Cancún only formalised a goal already pledged.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"विकसित देशों द्वारा 2020 तक विकासशील देशों के लिए जलवायु वित्त में प्रति वर्ष 100 अरब अमेरिकी डॉलर जुटाने का वचन पहली बार कहाँ दिया गया?","optionsHi":["क्योटो में COP-3, 1997 में","कोपेनहेगन में COP-15, 2009 में","पेरिस में COP-21, 2015 में","कैनकुन, मेक्सिको में COP-16, 2010 में"],"explanationHi":"यह लक्ष्य कोपेनहेगन समझौते (2009) में आया, 2010 में कैनकुन में औपचारिक बना और पेरिस में 2025 तक बढ़ाया गया। क्योटो ने उत्सर्जन लक्ष्य निर्धारित किए; कैनकुन ने केवल पहले ही दिए गए वचन को औपचारिक रूप दिया।"},
  {"id":"env-ecology-692","question":"Under the Kyoto Protocol, 'Joint Implementation' allowed:","options":["A developed country to earn credits from emission-reduction projects in a developing country","Developing countries to trade surplus emission allowances among themselves","One developed country to earn credits from emission-cutting projects in another","Two or more developing countries to pool their targets into a single shared target"],"answer":2,"explanation":"Joint Implementation operated between Annex I parties and generated Emission Reduction Units. Projects in developing countries came under the Clean Development Mechanism, and developing countries had no Kyoto targets to trade or pool.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"क्योटो प्रोटोकॉल के अंतर्गत 'संयुक्त क्रियान्वयन' ने किसकी अनुमति दी?","optionsHi":["किसी विकसित देश को विकासशील देश में उत्सर्जन-कटौती परियोजनाओं से क्रेडिट अर्जित करने की","विकासशील देशों को आपस में अधिशेष उत्सर्जन भत्तों का व्यापार करने की","एक विकसित देश को दूसरे में उत्सर्जन-कटौती परियोजनाओं से क्रेडिट अर्जित करने की","दो या अधिक विकासशील देशों को अपने लक्ष्यों को एक साझा लक्ष्य में मिलाने की"],"explanationHi":"संयुक्त क्रियान्वयन अनुलग्नक I के पक्षों के बीच संचालित होता था और उत्सर्जन न्यूनीकरण इकाइयाँ उत्पन्न करता था। विकासशील देशों की परियोजनाएँ स्वच्छ विकास तंत्र के अंतर्गत आती थीं, और विकासशील देशों के पास क्योटो के अंतर्गत व्यापार या मिलाने के लिए कोई लक्ष्य नहीं था।"},
  {"id":"env-ecology-693","question":"Which of the following correctly contrasts a carbon tax with a cap-and-trade system?","options":["A carbon tax fixes the price of emissions but not the quantity, while cap-and-trade fixes the quantity but lets the price vary","A carbon tax fixes the quantity of emissions but not the price, while cap-and-trade fixes the price but lets the quantity vary","Both fix the quantity of emissions in advance, but only a carbon tax lets firms trade permits among themselves","Both fix the price of emissions in advance, but only cap-and-trade raises revenue for the government"],"answer":0,"explanation":"A tax sets a known price per tonne and leaves total emissions to firms' responses; a cap limits total permits and lets the market set the price. Auctioned permits can also raise revenue, so revenue does not separate them.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कार्बन कर और कैप-एंड-ट्रेड प्रणाली में अंतर निम्नलिखित में से कौन-सा सही बताता है?","optionsHi":["कार्बन कर उत्सर्जन की कीमत निश्चित करता है, मात्रा नहीं, जबकि कैप-एंड-ट्रेड मात्रा निश्चित करता है परंतु कीमत को बदलने देता है","कार्बन कर उत्सर्जन की मात्रा निश्चित करता है, कीमत नहीं, जबकि कैप-एंड-ट्रेड कीमत निश्चित करता है परंतु मात्रा को बदलने देता है","दोनों उत्सर्जन की मात्रा पहले से निश्चित करते हैं, परंतु केवल कार्बन कर फर्मों को आपस में परमिट का व्यापार करने देता है","दोनों उत्सर्जन की कीमत पहले से निश्चित करते हैं, परंतु केवल कैप-एंड-ट्रेड सरकार के लिए राजस्व जुटाता है"],"explanationHi":"कर प्रति टन की ज्ञात कीमत निर्धारित करता है और कुल उत्सर्जन को फर्मों की प्रतिक्रिया पर छोड़ देता है; कैप कुल परमिट सीमित करता है और बाज़ार को कीमत तय करने देता है। नीलाम किए गए परमिट भी राजस्व जुटा सकते हैं, इसलिए राजस्व दोनों में अंतर नहीं करता।"},
  {"id":"env-ecology-694","question":"The European Union's Carbon Border Adjustment Mechanism (CBAM), which affects exports of steel and aluminium from India, is designed mainly to:","options":["Ban all imports from countries that have not yet ratified the Paris Agreement","Fund adaptation projects in developing countries through a levy on all flights","Exempt developing countries from any emission targets under the UNFCCC","Prevent 'carbon leakage' by pricing the embedded emissions of some imports"],"answer":3,"explanation":"CBAM requires importers of goods such as steel, aluminium, cement and fertilisers to pay a price for their embedded carbon, so that EU industry does not simply move to places with weaker carbon pricing. India has criticised it as a unilateral trade barrier.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"यूरोपीय संघ का कार्बन सीमा समायोजन तंत्र (CBAM), जो भारत के इस्पात और एल्युमिनियम के निर्यात को प्रभावित करता है, मुख्यतः किसलिए बनाया गया है?","optionsHi":["उन सभी देशों से आयात पर प्रतिबंध लगाना जिन्होंने अभी तक पेरिस समझौते की अभिपुष्टि नहीं की है","सभी उड़ानों पर शुल्क लगाकर विकासशील देशों में अनुकूलन परियोजनाओं को वित्त पोषित करना","UNFCCC के अंतर्गत विकासशील देशों को किसी भी उत्सर्जन लक्ष्य से छूट देना","कुछ आयातों में निहित उत्सर्जन का मूल्य निर्धारित करके 'कार्बन रिसाव' को रोकना"],"explanationHi":"CBAM इस्पात, एल्युमिनियम, सीमेंट और उर्वरक जैसे माल के आयातकों से उनके निहित कार्बन का मूल्य चुकाने को कहता है, ताकि यूरोपीय संघ का उद्योग कमज़ोर कार्बन मूल्य निर्धारण वाले स्थानों पर न चला जाए। भारत ने इसकी एकपक्षीय व्यापार बाधा कहकर आलोचना की है।"},
  {"id":"env-ecology-695","question":"A 'green bond', such as the sovereign green bonds first issued by India in 2023, differs from an ordinary bond mainly in that:","options":["It pays no interest at all, since investors are rewarded with carbon credits","Its proceeds are ring-fenced for environmental or climate projects","It can be bought only by government-owned banks, insurers and pension funds","It must be repaid within one year so that the funded projects finish quickly"],"answer":1,"explanation":"A green bond is an ordinary debt instrument with interest and maturity, except that the money raised is ring-fenced for eligible green projects such as renewable energy or clean transport.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"'हरित बॉन्ड', जैसे 2023 में भारत द्वारा पहली बार जारी संप्रभु हरित बॉन्ड, साधारण बॉन्ड से मुख्यतः इस बात में भिन्न है कि:","optionsHi":["यह कोई ब्याज नहीं देता, क्योंकि निवेशकों को कार्बन क्रेडिट से पुरस्कृत किया जाता है","इसकी आय पर्यावरणीय या जलवायु परियोजनाओं के लिए सुरक्षित रखी जाती है","इसे केवल सरकारी स्वामित्व वाले बैंक, बीमाकर्ता और पेंशन कोष ही खरीद सकते हैं","इसे एक वर्ष के भीतर चुकाना आवश्यक है ताकि वित्त पोषित परियोजनाएँ शीघ्र पूरी हों"],"explanationHi":"हरित बॉन्ड ब्याज और परिपक्वता वाला साधारण ऋण लिखत है, अंतर केवल यह है कि जुटाया गया धन नवीकरणीय ऊर्जा या स्वच्छ परिवहन जैसी पात्र हरित परियोजनाओं के लिए सुरक्षित रखा जाता है।"},
  {"id":"env-ecology-696","question":"UJALA, launched by the Government of India in 2015 and run by Energy Efficiency Services Limited, mainly aimed at:","options":["Installing rooftop solar panels on rural homes free of cost to the families","Replacing kerosene lamps with solar lanterns in tribal and forest villages","Distributing LED bulbs to households at low cost in place of old bulbs","Providing free LPG cooking gas connections to women from poor households"],"answer":2,"explanation":"UJALA used bulk procurement to cut LED prices sharply and distributed over 36 crore bulbs, saving electricity and peak demand. Free LPG connections came under the separate Ujjwala scheme, a common confusion.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भारत सरकार द्वारा 2015 में शुरू की गई और एनर्जी एफ़िशिएंसी सर्विसेज़ लिमिटेड द्वारा संचालित उजाला का मुख्य उद्देश्य था:","optionsHi":["ग्रामीण घरों पर परिवारों को निःशुल्क रूफटॉप सौर पैनल लगाना","आदिवासी और वन गाँवों में मिट्टी के तेल के लैंपों को सौर लालटेनों से बदलना","पुराने बल्बों के स्थान पर घरों में कम लागत पर LED बल्ब वितरित करना","गरीब परिवारों की महिलाओं को निःशुल्क LPG रसोई गैस कनेक्शन देना"],"explanationHi":"उजाला ने थोक खरीद से LED की कीमतें तेज़ी से घटाईं और 36 करोड़ से अधिक बल्ब वितरित किए, जिससे बिजली और अधिकतम माँग की बचत हुई। निःशुल्क LPG कनेक्शन अलग उज्ज्वला योजना के अंतर्गत आए, जो एक आम भ्रम है।"},
  {"id":"env-ecology-697","question":"National Innovations in Climate Resilient Agriculture (NICRA), which studies crops, livestock and fisheries under climate stress, is a network project of:","options":["The Indian Council of Agricultural Research","The India Meteorological Department","The National Bank for Agriculture and Rural Development","The Ministry of Earth Sciences"],"answer":0,"explanation":"ICAR launched NICRA in 2011 to develop and demonstrate climate-resilient technologies, including in climate-vulnerable villages. IMD provides weather data but does not run this research programme.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जलवायु तनाव में फसलों, पशुधन और मत्स्य का अध्ययन करने वाली जलवायु अनुकूल कृषि में राष्ट्रीय नवाचार (NICRA) किसकी नेटवर्क परियोजना है?","optionsHi":["भारतीय कृषि अनुसंधान परिषद","भारत मौसम विज्ञान विभाग","राष्ट्रीय कृषि और ग्रामीण विकास बैंक","पृथ्वी विज्ञान मंत्रालय"],"explanationHi":"ICAR ने 2011 में NICRA को जलवायु-अनुकूल प्रौद्योगिकियाँ विकसित और प्रदर्शित करने के लिए शुरू किया, जिनमें जलवायु-संवेदनशील गाँव भी शामिल हैं। IMD मौसम आँकड़े देता है, परंतु यह अनुसंधान कार्यक्रम नहीं चलाता।"},
  {"id":"env-ecology-698","question":"In transport policy, the 'Avoid–Shift–Improve' framework for cutting emissions refers to:","options":["Avoiding new road building, shifting freight to coastal ships and improving tyre quality","Avoiding fuel taxes, shifting subsidies to private car owners and improving road surfaces","Avoiding electric vehicles, shifting all fleets to biofuels and improving engine design","Avoiding needless trips, shifting to transit and walking, improving vehicles"],"answer":3,"explanation":"The framework ranks options: first reduce travel demand (through land use, telework), then move trips to buses, rail, walking and cycling, and finally make vehicles and fuels cleaner.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"परिवहन नीति में उत्सर्जन घटाने का 'टालो–बदलो–सुधारो' ढाँचा किससे संबंधित है?","optionsHi":["नई सड़कों के निर्माण से बचना, माल को तटीय जहाज़ों में बदलना और टायरों की गुणवत्ता सुधारना","ईंधन करों से बचना, रियायतों को निजी कार मालिकों की ओर बदलना और सड़क की सतह सुधारना","इलेक्ट्रिक वाहनों से बचना, सभी बेड़ों को जैव ईंधन में बदलना और इंजन डिज़ाइन सुधारना","अनावश्यक यात्राओं से बचना, सार्वजनिक परिवहन और पैदल चलने में बदलना, वाहनों में सुधार करना"],"explanationHi":"यह ढाँचा विकल्पों को क्रमबद्ध करता है: पहले यात्रा माँग घटाना (भूमि उपयोग, घर से कार्य के द्वारा), फिर यात्राओं को बसों, रेल, पैदल और साइकिल में बदलना, और अंत में वाहनों और ईंधनों को स्वच्छ बनाना।"},
  {"id":"env-ecology-699","question":"The Global Methane Pledge, launched at COP-26 in 2021, aims to cut global methane emissions by at least 30 per cent from 2020 levels by 2030. Which of the following is correct about India's position?","options":["India co-founded the pledge in 2021 along with the USA and the European Union","India has not joined the pledge, citing methane's link to farm livelihoods","India joined the pledge, but only for methane emitted from its coal mines","India joined the pledge with a deeper national target of 50 per cent by 2030"],"answer":1,"explanation":"Most of India's methane comes from livestock and paddy fields, tied to small farmers' livelihoods, and India has declined to sign. The pledge was led by the USA and the European Union.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2021 में COP-26 में शुरू किया गया वैश्विक मीथेन प्रतिज्ञा 2030 तक वैश्विक मीथेन उत्सर्जन को 2020 के स्तरों से कम से कम 30 प्रतिशत घटाने का लक्ष्य रखता है। भारत की स्थिति के बारे में निम्नलिखित में से कौन-सा सही है?","optionsHi":["भारत ने 2021 में अमेरिका और यूरोपीय संघ के साथ प्रतिज्ञा की सह-स्थापना की","भारत इस प्रतिज्ञा में शामिल नहीं हुआ है, क्योंकि मीथेन का संबंध कृषि आजीविका से है","भारत प्रतिज्ञा में शामिल हुआ, परंतु केवल अपनी कोयला खदानों से उत्सर्जित मीथेन के लिए","भारत 50 प्रतिशत के गहरे राष्ट्रीय लक्ष्य के साथ, 2030 तक, प्रतिज्ञा में शामिल हुआ"],"explanationHi":"भारत की अधिकांश मीथेन पशुधन और धान के खेतों से आती है, जो छोटे किसानों की आजीविका से जुड़ी है, और भारत ने हस्ताक्षर करने से मना किया है। प्रतिज्ञा का नेतृत्व अमेरिका और यूरोपीय संघ ने किया।"},
  {"id":"env-ecology-700","question":"The Glasgow Climate Pact (COP-26, 2021), after a late intervention led by India, called on countries to accelerate efforts towards the:","options":["Phase-out of all coal power by 2040 in developed countries and 2050 elsewhere","Phase-out of all fossil fuels, including oil and gas, by the middle of the century","Phase-down of unabated coal and phase-out of inefficient fossil subsidies","Phase-down of all coal use, including coal used for steel making, by 2030"],"answer":2,"explanation":"The draft spoke of 'phase-out' of unabated coal; India's amendment changed it to 'phase-down', and the pact also targeted inefficient fossil fuel subsidies. It was the first COP text to mention coal explicitly.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ग्लासगो जलवायु समझौते (COP-26, 2021) ने, भारत के नेतृत्व में अंतिम समय के हस्तक्षेप के बाद, देशों से किस दिशा में प्रयास तेज़ करने का आह्वान किया?","optionsHi":["विकसित देशों में 2040 तक और अन्यत्र 2050 तक सभी कोयला विद्युत को चरणबद्ध रूप से समाप्त करना","सदी के मध्य तक तेल और गैस सहित सभी जीवाश्म ईंधनों को चरणबद्ध रूप से समाप्त करना","अनियंत्रित कोयले में चरणबद्ध कमी और अक्षम जीवाश्म रियायतों की चरणबद्ध समाप्ति","2030 तक इस्पात बनाने में प्रयुक्त कोयले सहित सभी कोयला उपयोग में चरणबद्ध कमी"],"explanationHi":"मसौदे में अनियंत्रित कोयले के 'चरणबद्ध समाप्ति (फेज़-आउट)' की बात थी; भारत के संशोधन ने उसे 'चरणबद्ध कमी (फेज़-डाउन)' कर दिया, और समझौते ने अक्षम जीवाश्म ईंधन रियायतों को भी लक्षित किया। यह कोयले का स्पष्ट उल्लेख करने वाला पहला COP पाठ था।"},
  {"id":"env-ecology-701","question":"Following the addition of the Forests of East Australia in 2016, how many global biodiversity hotspots are recognised by Conservation International?","options":["25","34","36","40"],"answer":2,"explanation":"Myers' original 2000 list had 25 hotspots; it grew to 34 and then 35, and with the Forests of East Australia the count became 36, four of which extend into India.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2016 में पूर्वी ऑस्ट्रेलिया के वनों के जुड़ने के बाद, कंज़र्वेशन इंटरनेशनल द्वारा कितने वैश्विक जैव विविधता हॉटस्पॉट मान्य हैं?","optionsHi":["25","34","36","40"],"explanationHi":"मायर्स की 2000 की मूल सूची में 25 हॉटस्पॉट थे; यह बढ़कर 34 और फिर 35 हुई, और पूर्वी ऑस्ट्रेलिया के वनों के साथ संख्या 36 हो गई, जिनमें से चार भारत तक फैले हैं।"},
  {"id":"env-ecology-702","question":"How many of the following statements about megadiverse countries are correct? I. Conservation International identified 17 countries that together hold a majority of the world's species. II. India is one of these megadiverse countries. III. The group of Like-Minded Megadiverse Countries was formed through the Cancún Declaration of 2002. IV. All the megadiverse countries lie wholly within the tropics.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I–III are correct. IV is wrong: the list includes the USA, China, Australia and South Africa, which extend far outside the tropics.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"अति-विविध देशों के बारे में निम्नलिखित में से कितने कथन सही हैं? I. कंज़र्वेशन इंटरनेशनल ने 17 देशों की पहचान की जिनमें मिलाकर विश्व की अधिकांश प्रजातियाँ हैं। II. भारत इन अति-विविध देशों में से एक है। III. समान-विचार वाले अति-विविध देशों का समूह 2002 की कैनकुन घोषणा से बना। IV. सभी अति-विविध देश पूर्णतः उष्णकटिबंध के भीतर स्थित हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I–III सही हैं। IV गलत है: सूची में अमेरिका, चीन, ऑस्ट्रेलिया और दक्षिण अफ्रीका शामिल हैं, जो उष्णकटिबंध से बहुत बाहर तक फैले हैं।"},
  {"id":"env-ecology-703","question":"India, with deserts, rainforests, mangroves, coral reefs, wetlands, estuaries and alpine meadows, is said to be far richer than a Scandinavian country such as Norway in which level of biodiversity?","options":["Genetic diversity","Ecosystem diversity","Alpha diversity","Taxonomic diversity"],"answer":1,"explanation":"The variety of habitats and ecosystems within a country is ecosystem (ecological) diversity. Genetic diversity is variation within a species, and alpha diversity is the count within one habitat.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"मरुस्थलों, वर्षावनों, मैंग्रोव, प्रवाल भित्तियों, आर्द्रभूमियों, ज्वारनदमुखों और अल्पाइन चारागाहों वाला भारत नॉर्वे जैसे स्कैंडिनेवियाई देश की तुलना में जैव विविधता के किस स्तर पर कहीं अधिक समृद्ध कहा जाता है?","optionsHi":["आनुवंशिक विविधता","पारिस्थितिकी तंत्र विविधता","अल्फा विविधता","वर्गिकीय विविधता"],"explanationHi":"किसी देश के भीतर आवासों और पारिस्थितिकी तंत्रों की विविधता पारिस्थितिकी तंत्र (पारिस्थितिक) विविधता है। आनुवंशिक विविधता एक प्रजाति के भीतर भिन्नता है, और अल्फा विविधता एक आवास के भीतर की गणना है।"},
  {"id":"env-ecology-704","question":"In the Western Ghats, which of the following animal groups shows the highest proportion of endemic species?","options":["Birds","Mammals","Butterflies","Amphibians"],"answer":3,"explanation":"Most Western Ghats frogs and caecilians occur nowhere else, because amphibians disperse poorly and are tied to moist local habitats. Birds, being mobile, have a low share of endemics.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पश्चिमी घाट में निम्नलिखित में से किस जंतु समूह में स्थानिक प्रजातियों का अनुपात सर्वाधिक है?","optionsHi":["पक्षी","स्तनधारी","तितलियाँ","उभयचर"],"explanationHi":"पश्चिमी घाट के अधिकांश मेंढक और सीसिलियन कहीं और नहीं पाए जाते, क्योंकि उभयचर कम फैलते हैं और स्थानीय नम आवासों से बँधे होते हैं। पक्षी गतिशील होने के कारण स्थानिकों का अनुपात कम रखते हैं।"},
  {"id":"env-ecology-705","question":"The closest living relatives of the purple frog (Nasikabatrachus) of the Western Ghats are found in the Seychelles. This distribution is best explained by:","options":["Recent introduction of frogs by traders sailing across the Indian Ocean","The break-up of the Gondwana supercontinent","Rafting of frogs on floating vegetation during monsoon storms","A land bridge through Arabia during the last ice age"],"answer":1,"explanation":"India and the Seychelles separated as Gondwana broke up, so their frog lineages diverged from a common ancestor. The purple frog is thus an ancient relict, not a recent arrival.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पश्चिमी घाट के बैंगनी मेंढक (नासिकाबैट्रेकस) के निकटतम जीवित संबंधी सेशेल्स में पाए जाते हैं। इस वितरण की सबसे अच्छी व्याख्या है:","optionsHi":["हिंद महासागर में नौचालन करने वाले व्यापारियों द्वारा मेंढकों का हालिया आगमन","गोंडवाना महाद्वीप का टूटना","मानसूनी तूफ़ानों के दौरान तैरती वनस्पति पर मेंढकों का बहकर पहुँचना","पिछले हिमयुग में अरब से होकर एक स्थल सेतु"],"explanationHi":"गोंडवाना के टूटने के साथ भारत और सेशेल्स अलग हुए, इसलिए उनकी मेंढक वंश-परंपराएँ एक साझा पूर्वज से अलग हो गईं। इस प्रकार बैंगनी मेंढक एक प्राचीन अवशेष है, हालिया आगंतुक नहीं।"},
  {"id":"env-ecology-706","question":"The Nicobar Islands lie in the Sundaland hotspot. In which biodiversity hotspot do the Andaman Islands lie?","options":["Sundaland","Western Ghats and Sri Lanka","Indo-Burma","Himalaya"],"answer":2,"explanation":"The Andamans' flora and fauna are allied to Myanmar and are included in Indo-Burma, while the Nicobars, nearer Sumatra, belong to Sundaland. The Ten Degree Channel lies roughly between them.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निकोबार द्वीप समूह सुंडालैंड हॉटस्पॉट में आते हैं। अंडमान द्वीप समूह किस जैव विविधता हॉटस्पॉट में आते हैं?","optionsHi":["सुंडालैंड","पश्चिमी घाट और श्रीलंका","इंडो-बर्मा","हिमालय"],"explanationHi":"अंडमान की वनस्पति और जीव म्यांमार से संबंधित हैं और इंडो-बर्मा में शामिल हैं, जबकि सुमात्रा के निकट निकोबार सुंडालैंड में आते हैं। टेन डिग्री चैनल लगभग उनके बीच स्थित है।"},
  {"id":"env-ecology-707","question":"The Wallace Line, a boundary between Asian and Australasian faunas, runs between:","options":["Sri Lanka and the Maldives","Sumatra and the Malay Peninsula","New Guinea and Australia","Bali and Lombok"],"answer":3,"explanation":"Deep water between Bali and Lombok, and between Borneo and Sulawesi, kept these islands apart even at low ice-age sea levels, so placental mammals stay west and marsupials east of the line.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"एशियाई और ऑस्ट्रेलेशियाई जीवजातों के बीच की सीमा, वैलेस रेखा, किनके बीच से गुज़रती है?","optionsHi":["श्रीलंका और मालदीव","सुमात्रा और मलय प्रायद्वीप","न्यू गिनी और ऑस्ट्रेलिया","बाली और लोम्बोक"],"explanationHi":"बाली और लोम्बोक के बीच तथा बोर्नियो और सुलावेसी के बीच गहरे जल ने हिमयुग के निम्न समुद्र स्तरों पर भी इन द्वीपों को अलग रखा, इसलिए अपरायुक स्तनधारी रेखा के पश्चिम में और शिशुधानी पूर्व में रहते हैं।"},
  {"id":"env-ecology-708","question":"In the classification prepared for the Wildlife Institute of India by Rodgers and Panwar, India is divided into how many biogeographic zones?","options":["Eight","Ten","Twelve","Fifteen"],"answer":1,"explanation":"There are ten zones, from the Trans-Himalaya to the Islands, further split into biotic provinces; the Deccan Peninsula is the largest zone by area.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"रॉजर्स और पंवार द्वारा भारतीय वन्यजीव संस्थान के लिए तैयार वर्गीकरण में भारत को कितने जैव-भौगोलिक क्षेत्रों में बाँटा गया है?","optionsHi":["आठ","दस","बारह","पंद्रह"],"explanationHi":"ट्रांस-हिमालय से द्वीपों तक दस क्षेत्र हैं, जो आगे जैविक प्रांतों में बँटे हैं; क्षेत्रफल की दृष्टि से दक्कन प्रायद्वीप सबसे बड़ा क्षेत्र है।"},
  {"id":"env-ecology-709","question":"Consider the following statements about the species–area relationship, log S = log C + Z log A: 1. For areas within a region, Z usually lies in the range of about 0.1 to 0.2, whatever the taxonomic group. 2. When very large areas such as whole continents are compared, the slope becomes much steeper. 3. A larger Z means that species number changes less with area. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Z is typically 0.1–0.2 but rises to about 0.6–1.2 between continents. A larger Z means a steeper line, so species number changes more, not less, with area.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"प्रजाति–क्षेत्रफल संबंध, log S = log C + Z log A, के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. किसी क्षेत्र के भीतर के क्षेत्रफलों के लिए Z सामान्यतः लगभग 0.1 से 0.2 की सीमा में होता है, चाहे वर्गिकीय समूह कोई भी हो। 2. जब संपूर्ण महाद्वीपों जैसे बहुत बड़े क्षेत्रफलों की तुलना की जाती है, तो ढाल बहुत अधिक तीव्र हो जाता है। 3. बड़े Z का अर्थ है कि क्षेत्रफल के साथ प्रजातियों की संख्या कम बदलती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"Z सामान्यतः 0.1–0.2 होता है, परंतु महाद्वीपों के बीच बढ़कर लगभग 0.6–1.2 हो जाता है। बड़े Z का अर्थ अधिक तीव्र रेखा है, इसलिए प्रजातियों की संख्या क्षेत्रफल के साथ अधिक बदलती है, कम नहीं।"},
  {"id":"env-ecology-710","question":"If the species–area relationship S = cA^z holds with z = 0.3, then destroying 90 per cent of a habitat would be expected eventually to eliminate roughly what share of the species it held?","options":["About 50 per cent","About 90 per cent","About 27 per cent","About 70 per cent"],"answer":0,"explanation":"The remaining 10% of area keeps 0.1^0.3 ≈ 0.50 of the species, so about half are lost. Species loss is less than proportional to habitat loss, but still severe.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"यदि प्रजाति–क्षेत्रफल संबंध S = cA^z, z = 0.3 के साथ लागू होता है, तो किसी आवास के 90 प्रतिशत के नष्ट होने पर उसमें मौजूद प्रजातियों का लगभग कितना अंश अंततः समाप्त होने की अपेक्षा की जाएगी?","optionsHi":["लगभग 50 प्रतिशत","लगभग 90 प्रतिशत","लगभग 27 प्रतिशत","लगभग 70 प्रतिशत"],"explanationHi":"शेष 10% क्षेत्रफल 0.1^0.3 ≈ 0.50 प्रजातियाँ बचाए रखता है, इसलिए लगभग आधी समाप्त हो जाती हैं। प्रजाति हानि आवास हानि के अनुपात से कम होती है, फिर भी गंभीर है।"},
  {"id":"env-ecology-711","question":"When a fish species becomes extinct, the parasites that could live only in that fish also disappear. This process is called:","options":["Co-extinction","Background extinction","Mass extinction","Pseudo-extinction"],"answer":0,"explanation":"Co-extinction is the loss of species that depend obligately on another, such as specialist parasites or pollinators; it is one of the 'Evil Quartet' of causes of biodiversity loss.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"जब कोई मछली प्रजाति विलुप्त होती है, तो वे परजीवी भी लुप्त हो जाते हैं जो केवल उसी मछली में रह सकते थे। इस प्रक्रिया को कहते हैं:","optionsHi":["सह-विलुप्ति","पृष्ठभूमि विलुप्ति","सामूहिक विलुप्ति","छद्म-विलुप्ति"],"explanationHi":"सह-विलुप्ति उन प्रजातियों की हानि है जो किसी अन्य पर अनिवार्य रूप से निर्भर हैं, जैसे विशिष्ट परजीवी या परागणकर्ता; यह जैव विविधता ह्रास के कारणों के 'दुष्ट चतुष्टय' में से एक है।"},
  {"id":"env-ecology-712","question":"Compared with the 'background' rate in the fossil record before humans, present-day rates of species extinction are estimated to be roughly:","options":["About the same as the background rate","Two to five times the background rate","100–1,000 times the background rate","A million times the background rate"],"answer":2,"explanation":"Estimates of 100–1,000 times the background rate are why many scientists speak of a sixth mass extinction, this time driven by human activity.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मानव से पहले जीवाश्म अभिलेख की 'पृष्ठभूमि' दर की तुलना में, आज की प्रजाति विलुप्ति दरें अनुमानतः लगभग हैं:","optionsHi":["पृष्ठभूमि दर के लगभग बराबर","पृष्ठभूमि दर की दो से पाँच गुना","पृष्ठभूमि दर की 100–1,000 गुना","पृष्ठभूमि दर की दस लाख गुना"],"explanationHi":"पृष्ठभूमि दर की 100–1,000 गुना के अनुमान ही कारण हैं कि अनेक वैज्ञानिक छठी सामूहिक विलुप्ति की बात करते हैं, जो इस बार मानवीय गतिविधि से संचालित है।"},
  {"id":"env-ecology-713","question":"Exploring molecular, genetic and species-level diversity for products of economic value, such as new medicines, is known as:","options":["Biopiracy","Bioremediation","Biomagnification","Bioprospecting"],"answer":3,"explanation":"Bioprospecting is the search for useful products in nature; when it uses resources or traditional knowledge without consent or benefit-sharing, it becomes biopiracy.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"नई औषधियों जैसे आर्थिक मूल्य के उत्पादों के लिए आणविक, आनुवंशिक और प्रजाति-स्तरीय विविधता की खोज को क्या कहते हैं?","optionsHi":["जैव-चोरी (बायोपायरेसी)","जैव-उपचार (बायोरेमेडिएशन)","जैव-आवर्धन (बायोमैग्निफिकेशन)","जैव-अन्वेषण (बायोप्रॉस्पेक्टिंग)"],"explanationHi":"जैव-अन्वेषण प्रकृति में उपयोगी उत्पादों की खोज है; जब वह सहमति या लाभ-साझाकरण के बिना संसाधनों या पारंपरिक ज्ञान का उपयोग करता है, तो वह जैव-चोरी बन जाता है।"},
  {"id":"env-ecology-714","question":"The argument that biodiversity should be conserved because it provides services such as pollination, oxygen production and climate regulation, on which human well-being depends, is called the:","options":["Narrowly utilitarian argument","Ethical argument","Aesthetic argument","Broadly utilitarian argument"],"answer":3,"explanation":"Broadly utilitarian arguments rest on ecosystem services. Narrowly utilitarian ones point to direct products such as food, timber and drugs, while the ethical argument holds that every species has intrinsic value.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"यह तर्क कि जैव विविधता का संरक्षण इसलिए किया जाना चाहिए क्योंकि वह परागण, ऑक्सीजन उत्पादन और जलवायु नियमन जैसी सेवाएँ देती है, जिन पर मानव कल्याण निर्भर है, कहलाता है:","optionsHi":["संकीर्ण उपयोगितावादी तर्क","नैतिक तर्क","सौंदर्यपरक तर्क","व्यापक उपयोगितावादी तर्क"],"explanationHi":"व्यापक उपयोगितावादी तर्क पारिस्थितिकी तंत्र सेवाओं पर आधारित हैं। संकीर्ण उपयोगितावादी तर्क भोजन, इमारती लकड़ी और औषधियों जैसे प्रत्यक्ष उत्पादों की ओर इंगित करते हैं, जबकि नैतिक तर्क कहता है कि प्रत्येक प्रजाति का अंतर्निहित मूल्य है।"},
  {"id":"env-ecology-715","question":"Two sites together contain 40 species. Site A has 20 species and site B has 30. Using Whittaker's measure, beta diversity = gamma diversity ÷ mean alpha diversity, what is the beta diversity?","options":["0.625","1.6","2.0","15"],"answer":1,"explanation":"Mean alpha = (20 + 30)/2 = 25, so beta = 40/25 = 1.6. A value of 1 would mean both sites hold identical species; 2 would mean they share none.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"दो स्थलों में मिलाकर 40 प्रजातियाँ हैं। स्थल A में 20 प्रजातियाँ और स्थल B में 30 हैं। व्हिटेकर के माप, बीटा विविधता = गामा विविधता ÷ औसत अल्फा विविधता, का उपयोग करते हुए बीटा विविधता क्या है?","optionsHi":["0.625","1.6","2.0","15"],"explanationHi":"औसत अल्फा = (20 + 30)/2 = 25, इसलिए बीटा = 40/25 = 1.6। 1 का मान दर्शाता कि दोनों स्थलों में समान प्रजातियाँ हैं; 2 का अर्थ होता कि वे कोई भी साझा नहीं करते।"},
  {"id":"env-ecology-716","question":"The Narcondam hornbill is found naturally only on:","options":["A small volcanic island in the Andaman Sea","The wet evergreen forests of Silent Valley in Kerala","The Garo Hills of western Meghalaya","The Car Nicobar island in the Nicobar group"],"answer":0,"explanation":"Narcondam is a tiny volcanic island east of the Andamans and is the only home of this hornbill, a striking case of island endemism.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"नारकोंडम धनेश स्वाभाविक रूप से केवल कहाँ पाया जाता है?","optionsHi":["अंडमान सागर में एक छोटे ज्वालामुखीय द्वीप पर","केरल की साइलेंट वैली के आर्द्र सदाबहार वनों में","पश्चिमी मेघालय की गारो पहाड़ियों में","निकोबार समूह के कार निकोबार द्वीप पर"],"explanationHi":"नारकोंडम अंडमान के पूर्व में एक छोटा ज्वालामुखीय द्वीप है और इस धनेश का एकमात्र घर है, जो द्वीपीय स्थानिकता का उल्लेखनीय उदाहरण है।"},
  {"id":"env-ecology-717","question":"According to N. I. Vavilov's centres of origin of cultivated plants, which one of the following crops did NOT originate in the Indian (Hindustan) centre?","options":["Mango","Brinjal","Black pepper","Maize"],"answer":3,"explanation":"Maize was domesticated in Mexico, in the Central American centre. Mango, brinjal and black pepper all trace to the Indian region, which also contributed sugarcane and several pulses.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"एन. आई. वाविलोव के कृष्य पौधों के उत्पत्ति केंद्रों के अनुसार, निम्नलिखित में से कौन-सी फसल भारतीय (हिंदुस्तान) केंद्र में उत्पन्न नहीं हुई?","optionsHi":["आम","बैंगन","काली मिर्च","मक्का"],"explanationHi":"मक्का का पालतूकरण मेक्सिको में, मध्य अमेरिकी केंद्र में, हुआ। आम, बैंगन और काली मिर्च सभी भारतीय क्षेत्र से संबद्ध हैं, जिसने गन्ना और अनेक दलहनों का भी योगदान दिया।"},
  {"id":"env-ecology-718","question":"In India, the Important Bird and Biodiversity Areas (IBAs) programme of BirdLife International has been coordinated by:","options":["The Zoological Survey of India","The Wildlife Institute of India, Dehradun","The Botanical Survey of India","The Bombay Natural History Society"],"answer":3,"explanation":"BNHS, BirdLife's partner in India, identified the country's IBAs using standard criteria for threatened, range-restricted and congregatory birds.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत में बर्डलाइफ इंटरनेशनल का महत्त्वपूर्ण पक्षी और जैव विविधता क्षेत्र (IBA) कार्यक्रम किसके द्वारा समन्वित किया गया है?","optionsHi":["भारतीय प्राणी सर्वेक्षण","भारतीय वन्यजीव संस्थान, देहरादून","भारतीय वनस्पति सर्वेक्षण","बॉम्बे नैचुरल हिस्ट्री सोसायटी"],"explanationHi":"भारत में बर्डलाइफ के साझेदार BNHS ने संकटग्रस्त, सीमित-परास और समूहन वाले पक्षियों के मानक मानदंडों से देश के IBA की पहचान की।"},
  {"id":"env-ecology-719","question":"Assertion (A): Species endemic to small islands are especially prone to extinction. Reason (R): They often have small populations and ranges and have evolved without mainland predators and competitors. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Small, isolated populations have nowhere to retreat and little defence against introduced rats, cats or diseases, which is why most recorded bird extinctions have been on islands.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): छोटे द्वीपों की स्थानिक प्रजातियाँ विशेष रूप से विलुप्ति की प्रवृत्त होती हैं। कारण (R): उनकी समष्टियाँ और परास प्रायः छोटे होते हैं और वे मुख्य भूमि के परभक्षियों और प्रतिस्पर्धियों के बिना विकसित हुई होती हैं। सही विकल्प चुनिए:","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"छोटी, पृथक समष्टियों के पास पीछे हटने की कोई जगह नहीं होती और लाए गए चूहों, बिल्लियों या रोगों के विरुद्ध बहुत कम रक्षा होती है, इसीलिए अधिकांश दर्ज पक्षी विलुप्तियाँ द्वीपों पर हुई हैं।"},
  {"id":"env-ecology-720","question":"The 'Satpura hypothesis' proposed by S. L. Hora sought to explain:","options":["Why the Deccan plateau has very few endemic plant species","How the Narmada valley acts as a barrier to tigers moving south","How Malayan fauna reached the Western Ghats via the central hills","Why the Satpura forests receive more rainfall than the Western Ghats"],"answer":2,"explanation":"Hora suggested the Satpura and associated ranges once formed a moist forest corridor from north-east India to the Western Ghats, explaining the Malayan affinities of some Ghats fauna.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"एस. एल. होरा द्वारा प्रस्तावित 'सतपुड़ा परिकल्पना' किसकी व्याख्या करने का प्रयास करती थी?","optionsHi":["दक्कन पठार में बहुत कम स्थानिक पादप प्रजातियाँ क्यों हैं","नर्मदा घाटी बाघों के दक्षिण की ओर जाने में अवरोध कैसे बनती है","मलायी जीव मध्य पहाड़ियों से होकर पश्चिमी घाट तक कैसे पहुँचे","सतपुड़ा के वनों में पश्चिमी घाट से अधिक वर्षा क्यों होती है"],"explanationHi":"होरा ने सुझाव दिया कि सतपुड़ा और संबद्ध पर्वत श्रेणियाँ कभी उत्तर-पूर्व भारत से पश्चिमी घाट तक नम वन गलियारा बनाती थीं, जिससे घाट के कुछ जीवों की मलायी समानताएँ समझाई जाती हैं।"},
  {"id":"env-ecology-721","question":"Myristica swamps, an ancient type of freshwater swamp forest dominated by trees of the nutmeg family, are found in India mainly in:","options":["The Western Ghats","The Sundarbans delta","The Terai of Uttar Pradesh","The Andaman Islands"],"answer":0,"explanation":"These relict swamps survive in small patches in Kerala, Karnataka and Goa, with trees bearing stilt and knee roots. The Sundarbans are tidal mangroves, a different ecosystem.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जायफल कुल के वृक्षों से प्रभावित मीठे जल के दलदली वन का प्राचीन प्रकार, मिरिस्टिका दलदल, भारत में मुख्यतः कहाँ पाया जाता है?","optionsHi":["पश्चिमी घाट में","सुंदरबन डेल्टा में","उत्तर प्रदेश के तराई में","अंडमान द्वीप समूह में"],"explanationHi":"ये अवशेषी दलदल केरल, कर्नाटक और गोवा में छोटे खंडों में बचे हैं, जिनके वृक्षों में स्तंभ और जानु जड़ें होती हैं। सुंदरबन ज्वारीय मैंग्रोव हैं, जो भिन्न पारिस्थितिकी तंत्र है।"},
  {"id":"env-ecology-722","question":"The '30 by 30' target in the Kunming–Montreal Global Biodiversity Framework (2022) calls for:","options":["Cutting the extinction rate of known species by 30 per cent by 2030","Effectively conserving 30 per cent of land and of oceans by 2030","Raising global finance for biodiversity by 30 per cent before 2030","Restoring 30 per cent of degraded wetlands in each country by 2030"],"answer":1,"explanation":"Target 3 of the framework, adopted at CBD COP-15, seeks effective conservation of at least 30% of terrestrial, inland water, coastal and marine areas by 2030.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"कुनमिंग–मॉन्ट्रियल वैश्विक जैव विविधता ढाँचे (2022) में '30 बाय 30' लक्ष्य किसका आह्वान करता है?","optionsHi":["ज्ञात प्रजातियों की विलुप्ति दर में 30 प्रतिशत की कमी, 2030 तक","भूमि और महासागरों के 30 प्रतिशत का प्रभावी संरक्षण, 2030 तक","जैव विविधता के लिए वैश्विक वित्त में 30 प्रतिशत की वृद्धि, 2030 से पहले","प्रत्येक देश में निम्नीकृत आर्द्रभूमियों के 30 प्रतिशत की बहाली, 2030 तक"],"explanationHi":"CBD COP-15 में अपनाए गए ढाँचे का लक्ष्य 3, 2030 तक स्थलीय, अंतर्देशीय जल, तटीय और समुद्री क्षेत्रों के कम से कम 30% का प्रभावी संरक्षण चाहता है।"},
  {"id":"env-ecology-723","question":"The replacement of thousands of traditional rice landraces in Indian fields by a few high-yielding varieties after the Green Revolution is an example of:","options":["Genetic erosion","Ecological succession","Adaptive radiation","Co-extinction"],"answer":0,"explanation":"Genetic erosion is the loss of genetic diversity within crops or species. Landraces carry genes for drought, pest and flood tolerance, which is why gene banks try to save them.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हरित क्रांति के बाद भारतीय खेतों में हज़ारों पारंपरिक धान देशी किस्मों का कुछ उच्च उपज किस्मों से प्रतिस्थापित हो जाना किसका उदाहरण है?","optionsHi":["आनुवंशिक अपक्षरण","पारिस्थितिक अनुक्रमण","अनुकूली विकिरण","सह-विलुप्ति"],"explanationHi":"आनुवंशिक अपक्षरण फसलों या प्रजातियों के भीतर आनुवंशिक विविधता की हानि है। देशी किस्मों में सूखे, कीट और बाढ़ सहनशीलता के जीन होते हैं, इसीलिए जीन बैंक उन्हें बचाने का प्रयास करते हैं।"},
  {"id":"env-ecology-724","question":"Consider the following statements: 1. Every exotic species introduced into a new region becomes invasive. 2. An invasive species is one that spreads in its new range and harms native species or ecosystems. 3. Oceanic islands are particularly vulnerable to invasive species. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Most introduced species never spread widely; only a minority become invasive. Islands, whose species evolved in isolation, suffer the heaviest damage from invaders.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. किसी नए क्षेत्र में लाई गई प्रत्येक विदेशी प्रजाति आक्रामक बन जाती है। 2. आक्रामक प्रजाति वह है जो अपने नए परास में फैलती है और स्थानीय प्रजातियों या पारिस्थितिकी तंत्रों को हानि पहुँचाती है। 3. महासागरीय द्वीप आक्रामक प्रजातियों के प्रति विशेष रूप से असुरक्षित होते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"अधिकांश लाई गई प्रजातियाँ कभी व्यापक रूप से नहीं फैलतीं; केवल अल्पसंख्यक ही आक्रामक बनती हैं। द्वीप, जिनकी प्रजातियाँ पृथकता में विकसित हुईं, आक्रामकों से सबसे भारी क्षति झेलते हैं।"},
  {"id":"env-ecology-725","question":"The Nicobar megapode, a bird endemic to the Nicobar Islands, is notable because it:","options":["Is flightless and nests in burrows dug on sandy beaches","Lays its eggs in the nests of crows, which then raise its chicks","Incubates its eggs in mounds of decaying vegetation and sand","Lives only in mangroves and feeds entirely on crabs at night"],"answer":2,"explanation":"Megapodes bury their eggs in large mounds where the heat of decomposition (or of the sun) incubates them, and the chicks dig themselves out able to fend for themselves.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निकोबार मेगापोड, जो निकोबार द्वीप समूह का स्थानिक पक्षी है, इसलिए उल्लेखनीय है क्योंकि वह:","optionsHi":["उड़ने में असमर्थ है और रेतीले तटों पर खोदे बिलों में घोंसला बनाता है","अपने अंडे कौओं के घोंसलों में देता है, जो फिर उसके चूजे पालते हैं","अपने अंडों को सड़ती वनस्पति और रेत के ढेरों में सेता है","केवल मैंग्रोव में रहता है और रात में पूरी तरह केकड़ों पर निर्भर रहता है"],"explanationHi":"मेगापोड अपने अंडों को बड़े ढेरों में गाड़ देते हैं जहाँ अपघटन (या सूर्य) की ऊष्मा उन्हें सेती है, और चूजे स्वयं खोदकर निकलते हैं तथा अपना ध्यान रखने में सक्षम होते हैं।"},
  {"id":"env-ecology-726","question":"Which of the following Indian wetlands are on the Montreux Record of the Ramsar Convention? 1. Keoladeo National Park 2. Loktak Lake 3. Chilika Lake 4. Wular Lake. Select the correct answer using the code given below.","options":["1 and 2 only","1, 2 and 3 only","2 and 4 only","1, 3 and 4 only"],"answer":0,"explanation":"Keoladeo (since 1990) and Loktak (since 1993) remain on the Montreux Record of sites with adverse ecological change. Chilika was added in 1993 but removed in 2002 after the reopening of its sea mouth restored it, a common trap.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सी भारतीय आर्द्रभूमियाँ रामसर अभिसमय के मॉन्ट्रो रिकॉर्ड पर हैं? 1. केओलादेव राष्ट्रीय उद्यान 2. लोकटक झील 3. चिल्का झील 4. वुलर झील। नीचे दिए गए कूट का उपयोग करके सही उत्तर चुनिए।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2 और 4","केवल 1, 3 और 4"],"explanationHi":"केओलादेव (1990 से) और लोकटक (1993 से) प्रतिकूल पारिस्थितिक परिवर्तन वाले स्थलों के मॉन्ट्रो रिकॉर्ड पर बने हुए हैं। चिल्का को 1993 में जोड़ा गया था परंतु 2002 में हटा दिया गया, जब उसके समुद्री मुहाने के पुनः खुलने से वह बहाल हो गई; यह एक आम भ्रम है।"},
  {"id":"env-ecology-727","question":"By area, the largest Ramsar site in India is:","options":["Chilika Lake in Odisha","Vembanad–Kol wetland in Kerala","The Sundarbans in West Bengal","Wular Lake in Jammu and Kashmir"],"answer":2,"explanation":"The Indian Sundarbans, designated in 2019, cover over 4,000 sq km, ahead of Vembanad–Kol (about 1,500 sq km) and Chilika (about 1,165 sq km).","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"क्षेत्रफल की दृष्टि से भारत का सबसे बड़ा रामसर स्थल है:","optionsHi":["ओडिशा की चिल्का झील","केरल का वेम्बनाड–कोल आर्द्रभूमि","पश्चिम बंगाल का सुंदरबन","जम्मू और कश्मीर की वुलर झील"],"explanationHi":"2019 में नामित भारतीय सुंदरबन 4,000 वर्ग किमी से अधिक में फैला है, जो वेम्बनाड–कोल (लगभग 1,500 वर्ग किमी) और चिल्का (लगभग 1,165 वर्ग किमी) से आगे है।"},
  {"id":"env-ecology-728","question":"Consider the following statements about CITES: 1. It is legally binding on the countries that are parties to it. 2. It replaces the national wildlife laws of its parties. 3. Its secretariat, in Geneva, is administered by UNEP. Which of the statements given above are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"CITES binds its parties but does not take the place of national laws; each party must enforce it through its own legislation, which India does through the Wildlife (Protection) Act. The secretariat is in Geneva under UNEP.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"CITES के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह अपने पक्षकार देशों पर विधिक रूप से बाध्यकारी है। 2. यह अपने पक्षकारों के राष्ट्रीय वन्यजीव कानूनों का स्थान लेता है। 3. जिनेवा में स्थित इसका सचिवालय UNEP द्वारा प्रशासित है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"CITES अपने पक्षकारों को बाध्य करता है परंतु राष्ट्रीय कानूनों का स्थान नहीं लेता; प्रत्येक पक्षकार को उसे अपने कानून से लागू करना होता है, जो भारत वन्यजीव (संरक्षण) अधिनियम के माध्यम से करता है। सचिवालय UNEP के अंतर्गत जिनेवा में है।"},
  {"id":"env-ecology-729","question":"In 2020, India hosted the 13th Conference of the Parties to the Convention on Migratory Species (CMS), at which the Great Indian Bustard was added to Appendix I. The venue was:","options":["Hyderabad","Greater Noida","New Delhi","Gandhinagar"],"answer":3,"explanation":"CMS COP-13 met at Gandhinagar in February 2020 and also listed the Asian elephant and Bengal florican in Appendix I. Hyderabad hosted CBD COP-11 (2012) and Greater Noida hosted UNCCD COP-14 (2019).","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2020 में भारत ने प्रवासी प्रजातियों पर अभिसमय (CMS) के पक्षकारों के 13वें सम्मेलन की मेज़बानी की, जिसमें ग्रेट इंडियन बस्टर्ड को परिशिष्ट I में जोड़ा गया। स्थल था:","optionsHi":["हैदराबाद","ग्रेटर नोएडा","नई दिल्ली","गांधीनगर"],"explanationHi":"CMS COP-13 फरवरी 2020 में गांधीनगर में हुआ और उसने एशियाई हाथी तथा बंगाल फ्लोरिकन को भी परिशिष्ट I में सूचीबद्ध किया। हैदराबाद ने CBD COP-11 (2012) और ग्रेटर नोएडा ने UNCCD COP-14 (2019) की मेज़बानी की।"},
  {"id":"env-ecology-730","question":"The 'Advance Informed Agreement' procedure, under which an importing country must consent before the first transboundary movement of certain living modified organisms meant for release into the environment, is a feature of the:","options":["Cartagena Protocol on Biosafety","Nagoya Protocol on Access and Benefit-sharing","Rotterdam Convention","Basel Convention"],"answer":0,"explanation":"The Cartagena Protocol (2000) to the CBD applies the AIA procedure to LMOs such as GM seeds for planting. Rotterdam uses a similar-sounding 'prior informed consent' procedure, but for hazardous chemicals and pesticides.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'अग्रिम सूचित सहमति' (AIA) प्रक्रिया, जिसके अंतर्गत पर्यावरण में छोड़े जाने वाले कुछ जीवित संशोधित जीवों (LMO) के प्रथम सीमापार संचलन से पहले आयातक देश की सहमति आवश्यक होती है, किसकी विशेषता है?","optionsHi":["जैव सुरक्षा पर कार्टाजेना प्रोटोकॉल","पहुँच और लाभ-साझाकरण पर नागोया प्रोटोकॉल","रॉटरडैम अभिसमय","बेसल अभिसमय"],"explanationHi":"CBD का कार्टाजेना प्रोटोकॉल (2000) रोपण के लिए GM बीज जैसे LMO पर AIA प्रक्रिया लागू करता है। रॉटरडैम समान-ध्वनि वाली 'पूर्व सूचित सहमति' प्रक्रिया का उपयोग करता है, परंतु खतरनाक रसायनों और कीटनाशकों के लिए।"},
  {"id":"env-ecology-731","question":"Hot water discharged from a thermal power plant's condenser into a river harms fish mainly because the warmer water:","options":["Contains more dissolved oxygen, which damages the delicate tissue of fish gills","Dissolves more carbon dioxide, which sharply raises the alkalinity of the river","Holds less dissolved oxygen even as it raises the fish's own demand for oxygen","Becomes denser, so fish must spend more energy to stay at their usual depth"],"answer":2,"explanation":"Gas solubility falls as temperature rises, while a cold-blooded fish's metabolism, and so its oxygen need, rises; the two effects together cause stress and kills. Warm water also holds less CO2, not more, and is less dense than cold water.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ताप विद्युत संयंत्र के संघनित्र से नदी में छोड़ा गया गर्म जल मछलियों को मुख्यतः इसलिए हानि पहुँचाता है क्योंकि गर्म जल:","optionsHi":["में अधिक घुलित ऑक्सीजन होती है, जो मछलियों के गलफड़ों के नाज़ुक ऊतक को क्षति पहुँचाती है","अधिक कार्बन डाइऑक्साइड घोलता है, जो नदी की क्षारीयता को तेज़ी से बढ़ा देती है","कम घुलित ऑक्सीजन धारण करता है, जबकि मछली की स्वयं की ऑक्सीजन माँग बढ़ा देता है","सघन हो जाता है, इसलिए मछलियों को अपनी सामान्य गहराई पर रहने के लिए अधिक ऊर्जा खर्च करनी पड़ती है"],"explanationHi":"तापमान बढ़ने पर गैस की विलेयता घटती है, जबकि शीतरक्त मछली का उपापचय, और इसलिए ऑक्सीजन की आवश्यकता, बढ़ती है; दोनों प्रभाव मिलकर तनाव और मृत्यु उत्पन्न करते हैं। गर्म जल CO2 भी कम धारण करता है, अधिक नहीं, और ठंडे जल से कम सघन होता है।"},
  {"id":"env-ecology-732","question":"Which was the first treaty in the history of the United Nations to achieve universal ratification by all member states?","options":["The Ramsar Convention","The Montreal Protocol","The UN Framework Convention on Climate Change","The Convention on Biological Diversity"],"answer":1,"explanation":"In 2009, the Vienna Convention and its Montreal Protocol became the first UN treaties ratified by every country. The CBD is not universal because the United States has not ratified it.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"संयुक्त राष्ट्र के इतिहास में वह पहली संधि कौन-सी थी जिसकी सभी सदस्य देशों द्वारा सार्वभौमिक अभिपुष्टि हुई?","optionsHi":["रामसर अभिसमय","मॉन्ट्रियल प्रोटोकॉल","संयुक्त राष्ट्र जलवायु परिवर्तन रूपरेखा अभिसमय","जैव विविधता पर अभिसमय"],"explanationHi":"2009 में वियना अभिसमय और उसका मॉन्ट्रियल प्रोटोकॉल प्रत्येक देश द्वारा अभिपुष्ट की जाने वाली पहली संयुक्त राष्ट्र संधियाँ बनीं। CBD सार्वभौमिक नहीं है क्योंकि अमेरिका ने उसकी अभिपुष्टि नहीं की है।"},
  {"id":"env-ecology-733","question":"The Multilateral Fund, which pays the extra costs incurred by developing countries in phasing out ozone-depleting substances, was set up by:","options":["The Vienna Convention itself when it was adopted in 1985","The Kigali Amendment to the Montreal Protocol in 2016","The London Amendment to the Montreal Protocol in 1990","The Global Environment Facility at its launch in 1991"],"answer":2,"explanation":"The London Amendment created the Multilateral Fund for the Implementation of the Montreal Protocol, run by an executive committee with secretariat in Montreal. The GEF is a separate mechanism, and the Vienna Convention set no binding controls.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"बहुपक्षीय कोष, जो ओज़ोन-क्षयकारी पदार्थों को चरणबद्ध रूप से समाप्त करने में विकासशील देशों द्वारा वहन किए गए अतिरिक्त खर्चों का भुगतान करता है, किसके द्वारा स्थापित किया गया?","optionsHi":["स्वयं वियना अभिसमय द्वारा, जब उसे 1985 में अपनाया गया","2016 में मॉन्ट्रियल प्रोटोकॉल के किगाली संशोधन द्वारा","1990 में मॉन्ट्रियल प्रोटोकॉल के लंदन संशोधन द्वारा","1991 में अपनी शुरुआत पर वैश्विक पर्यावरण सुविधा (GEF) द्वारा"],"explanationHi":"लंदन संशोधन ने मॉन्ट्रियल प्रोटोकॉल के क्रियान्वयन के लिए बहुपक्षीय कोष बनाया, जिसे एक कार्यकारी समिति चलाती है और जिसका सचिवालय मॉन्ट्रियल में है। GEF एक अलग तंत्र है, और वियना अभिसमय ने कोई बाध्यकारी नियंत्रण निर्धारित नहीं किए।"},
  {"id":"env-ecology-734","question":"Under the UN Framework Convention on Climate Change, the parties listed in Annex II are:","options":["All developing countries, which are entitled to receive finance and technology","The economies in transition of eastern Europe, such as Russia and Ukraine","The small island developing states that are most at risk from rising seas","Developed (OECD) countries obliged to provide finance to developing ones"],"answer":3,"explanation":"Annex I includes the developed countries and economies in transition; Annex II is the subset of OECD members of 1992 that must help developing countries with finance and technology. Economies in transition are in Annex I but not Annex II.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"संयुक्त राष्ट्र जलवायु परिवर्तन रूपरेखा अभिसमय के अंतर्गत अनुलग्नक II में सूचीबद्ध पक्ष हैं:","optionsHi":["सभी विकासशील देश, जो वित्त और प्रौद्योगिकी प्राप्त करने के हकदार हैं","पूर्वी यूरोप की संक्रमणशील अर्थव्यवस्थाएँ, जैसे रूस और यूक्रेन","लघु द्वीपीय विकासशील राज्य जिन्हें समुद्र के बढ़ने से सबसे अधिक जोखिम है","विकसित (OECD) देश जो विकासशील देशों को वित्त उपलब्ध कराने के लिए बाध्य हैं"],"explanationHi":"अनुलग्नक I में विकसित देश और संक्रमणशील अर्थव्यवस्थाएँ शामिल हैं; अनुलग्नक II 1992 के OECD सदस्यों का वह उपसमूह है जिन्हें विकासशील देशों की वित्त और प्रौद्योगिकी से सहायता करनी होती है। संक्रमणशील अर्थव्यवस्थाएँ अनुलग्नक I में हैं पर अनुलग्नक II में नहीं।"},
  {"id":"env-ecology-735","question":"Match the convention with the city where its secretariat is located. A. UNFCCC  B. Convention on Biological Diversity  C. Ramsar Convention  D. CITES; 1. Montreal  2. Gland  3. Geneva  4. Bonn","options":["A-4, B-1, C-2, D-3","A-4, B-2, C-1, D-3","A-1, B-4, C-2, D-3","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"The UNFCCC (with UNCCD and CMS) is in Bonn, the CBD in Montreal, the Ramsar secretariat at Gland, Switzerland, alongside IUCN, and CITES in Geneva. Montreal is also home to the Montreal Protocol's Multilateral Fund, not its ozone secretariat (Nairobi).","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अभिसमय का उस शहर से मिलान कीजिए जहाँ उसका सचिवालय स्थित है। A. UNFCCC B. जैव विविधता पर अभिसमय C. रामसर अभिसमय D. CITES; 1. मॉन्ट्रियल 2. ग्लैंड 3. जिनेवा 4. बॉन","optionsHi":["A-4, B-1, C-2, D-3","A-4, B-2, C-1, D-3","A-1, B-4, C-2, D-3","A-4, B-1, C-3, D-2"],"explanationHi":"UNFCCC (UNCCD और CMS के साथ) बॉन में है, CBD मॉन्ट्रियल में, रामसर सचिवालय स्विट्ज़रलैंड के ग्लैंड में IUCN के साथ, और CITES जिनेवा में। मॉन्ट्रियल में मॉन्ट्रियल प्रोटोकॉल का बहुपक्षीय कोष भी है, उसका ओज़ोन सचिवालय नहीं (वह नैरोबी में है)।"},
  {"id":"env-ecology-736","question":"Consider the following statements about the Kyoto Protocol: 1. The United States signed it but never ratified it. 2. Canada withdrew from it during the first commitment period. 3. India accepted binding emission-reduction targets under it. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 3 only","1 and 2 only"],"answer":3,"explanation":"The USA signed in 1998 but never ratified, and Canada announced its withdrawal in 2011. Developing countries such as India had no binding targets; they could host CDM projects instead.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"क्योटो प्रोटोकॉल के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. संयुक्त राज्य अमेरिका ने उस पर हस्ताक्षर किए पर कभी अभिपुष्टि नहीं की। 2. कनाडा प्रथम प्रतिबद्धता अवधि के दौरान उससे हट गया। 3. भारत ने उसके अंतर्गत बाध्यकारी उत्सर्जन-कटौती लक्ष्य स्वीकार किए। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 3","केवल 1 और 2"],"explanationHi":"अमेरिका ने 1998 में हस्ताक्षर किए पर कभी अभिपुष्टि नहीं की, और कनाडा ने 2011 में अपने हटने की घोषणा की। भारत जैसे विकासशील देशों के कोई बाध्यकारी लक्ष्य नहीं थे; वे इसके बजाय CDM परियोजनाओं की मेज़बानी कर सकते थे।"},
  {"id":"env-ecology-737","question":"The Paris Agreement could enter into force only after it had been ratified by at least:","options":["55 parties accounting for at least 55 per cent of global emissions","All of the developed-country parties listed in Annex I of the UNFCCC","Two-thirds of all UN member states, regardless of their share of emissions","100 parties together accounting for at least 75 per cent of global emissions"],"answer":0,"explanation":"The 'double threshold' of 55 parties and 55 per cent of emissions was crossed in October 2016, and the agreement entered into force on 4 November 2016, much faster than Kyoto, which took until 2005.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"पेरिस समझौता तभी प्रभावी हो सकता था जब कम से कम किनके द्वारा उसकी अभिपुष्टि हो जाती?","optionsHi":["55 पक्ष जो वैश्विक उत्सर्जन के कम से कम 55 प्रतिशत के लिए उत्तरदायी हों","UNFCCC के अनुलग्नक I में सूचीबद्ध सभी विकसित-देश पक्ष","संयुक्त राष्ट्र के सभी सदस्य देशों में से दो-तिहाई, उनके उत्सर्जन हिस्से की परवाह किए बिना","100 पक्ष जो मिलकर वैश्विक उत्सर्जन के कम से कम 75 प्रतिशत के लिए उत्तरदायी हों"],"explanationHi":"55 पक्षों और 55 प्रतिशत उत्सर्जन की 'दोहरी सीमा' अक्तूबर 2016 में पार हुई, और समझौता 4 नवंबर 2016 को प्रभावी हुआ, क्योटो की तुलना में कहीं तेज़ी से, जिसे 2005 तक लगा।"},
  {"id":"env-ecology-738","question":"The 'Ban Amendment' to the Basel Convention, which entered into force in 2019, prohibits:","options":["All international trade in hazardous wastes between any two countries","Exports of hazardous wastes from OECD and EU states to others","Imports of plastic waste of any kind into any developing country","Dumping of hazardous wastes at sea by ships of any party"],"answer":1,"explanation":"The Ban Amendment bars Annex VII parties (OECD members, the EU and Liechtenstein) from exporting hazardous wastes for any purpose to non-Annex VII countries. Trade among other countries remains under the prior informed consent rules, and dumping at sea is covered by the London Convention.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"बेसल अभिसमय का 'प्रतिबंध संशोधन', जो 2019 में प्रभावी हुआ, किसे प्रतिबंधित करता है?","optionsHi":["किन्हीं भी दो देशों के बीच खतरनाक अपशिष्टों का सभी अंतर्राष्ट्रीय व्यापार","OECD और EU राज्यों से अन्य देशों को खतरनाक अपशिष्टों का निर्यात","किसी भी विकासशील देश में किसी भी प्रकार के प्लास्टिक अपशिष्ट का आयात","किसी भी पक्षकार के जहाज़ों द्वारा समुद्र में खतरनाक अपशिष्टों का डंपिंग"],"explanationHi":"प्रतिबंध संशोधन अनुलग्नक VII के पक्षों (OECD सदस्य, EU और लिकटेंस्टाइन) को किसी भी प्रयोजन से अनुलग्नक VII के बाहर के देशों को खतरनाक अपशिष्टों का निर्यात करने से रोकता है। अन्य देशों के बीच व्यापार पूर्व सूचित सहमति नियमों के अंतर्गत बना रहता है, और समुद्र में डंपिंग लंदन अभिसमय के अंतर्गत आती है।"},
  {"id":"env-ecology-739","question":"The 2019 amendments to the Basel Convention on plastic waste mean that:","options":["All production of single-use plastic items is banned in every party to the convention","Plastic waste can no longer be recycled in any country other than the one producing it","Exports of most mixed or contaminated plastic waste need importers' prior consent","Developed countries must pay a fixed levy for every tonne of plastic waste they export"],"answer":2,"explanation":"From 2021, hard-to-recycle or contaminated plastic waste was brought under the Basel prior informed consent procedure, giving importing countries the right to refuse it. Clean, sorted plastic for recycling largely remains outside it.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"प्लास्टिक अपशिष्ट पर बेसल अभिसमय के 2019 के संशोधनों का अर्थ है कि:","optionsHi":["अभिसमय के प्रत्येक पक्षकार में एकल-उपयोग प्लास्टिक वस्तुओं का सारा उत्पादन प्रतिबंधित है","प्लास्टिक अपशिष्ट का पुनःचक्रण अब उसे उत्पन्न करने वाले देश के अलावा किसी देश में नहीं हो सकता","अधिकांश मिश्रित या संदूषित प्लास्टिक अपशिष्ट के निर्यात के लिए आयातकों की पूर्व सहमति आवश्यक है","विकसित देशों को निर्यात किए गए प्रत्येक टन प्लास्टिक अपशिष्ट के लिए निश्चित शुल्क देना होगा"],"explanationHi":"2021 से पुनःचक्रण में कठिन या संदूषित प्लास्टिक अपशिष्ट को बेसल पूर्व सूचित सहमति प्रक्रिया के अंतर्गत लाया गया, जिससे आयातक देशों को उसे अस्वीकार करने का अधिकार मिला। पुनःचक्रण के लिए स्वच्छ, छँटा हुआ प्लास्टिक बड़े पैमाने पर इसके बाहर रहता है।"},
  {"id":"env-ecology-740","question":"Consider the following statements: 1. The Basel, Rotterdam and Stockholm Conventions share a joint secretariat. 2. The secretariat of the Rotterdam Convention is provided jointly by UNEP and the FAO. 3. The Minamata Convention on mercury is serviced by the same joint secretariat. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Since 2012 the BRS conventions have shared one secretariat under UNEP, with FAO co-hosting the Rotterdam part because it covers pesticides. The Minamata Convention has its own separate secretariat, though it is also in Geneva.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. बेसल, रॉटरडैम और स्टॉकहोम अभिसमयों का एक संयुक्त सचिवालय है। 2. रॉटरडैम अभिसमय का सचिवालय UNEP और FAO द्वारा संयुक्त रूप से प्रदान किया जाता है। 3. पारे पर मिनामाता अभिसमय की सेवा उसी संयुक्त सचिवालय द्वारा की जाती है। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"2012 से BRS अभिसमयों का UNEP के अंतर्गत एक ही सचिवालय है, जिसमें FAO रॉटरडैम भाग की सह-मेज़बानी करता है क्योंकि वह कीटनाशकों को शामिल करता है। मिनामाता अभिसमय का अपना अलग सचिवालय है, यद्यपि वह भी जिनेवा में है।"},
  {"id":"env-ecology-741","question":"Under the Stockholm Convention, dioxins and furans are listed in Annex C. This means that parties must:","options":["Eliminate their deliberate production and use within five years of listing","Restrict their use to disease-vector control only, as is done for DDT","Report all exports to the secretariat under the prior informed consent procedure","Cut their unintentional release, as from open burning and industrial processes"],"answer":3,"explanation":"Annex A covers chemicals to be eliminated, Annex B those to be restricted (such as DDT), and Annex C by-products formed unintentionally, such as dioxins and furans from open burning and incineration, whose releases must be minimised.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"स्टॉकहोम अभिसमय के अंतर्गत डाइऑक्सिन और फ्यूरान अनुलग्नक C में सूचीबद्ध हैं। इसका अर्थ है कि पक्षों को:","optionsHi":["सूचीबद्ध होने के पाँच वर्ष के भीतर उनका जानबूझकर उत्पादन और उपयोग समाप्त करना होगा","उनका उपयोग केवल रोग-वाहक नियंत्रण तक सीमित करना होगा, जैसा DDT के लिए किया जाता है","पूर्व सूचित सहमति प्रक्रिया के अंतर्गत सभी निर्यातों की सचिवालय को रिपोर्ट देनी होगी","उनके अनपेक्षित उत्सर्जन को घटाना होगा, जैसे खुले में जलाने और औद्योगिक प्रक्रियाओं से"],"explanationHi":"अनुलग्नक A में समाप्त किए जाने वाले रसायन, अनुलग्नक B में प्रतिबंधित किए जाने वाले (जैसे DDT), और अनुलग्नक C में अनपेक्षित रूप से बनने वाले उप-उत्पाद, जैसे खुले में जलाने और भस्मीकरण से डाइऑक्सिन और फ्यूरान, आते हैं जिनके उत्सर्जन को न्यूनतम करना होता है।"},
  {"id":"env-ecology-742","question":"At COP-14 of the UN Convention to Combat Desertification in 2019, India announced a target to restore degraded land by 2030 of:","options":["5 million hectares","13 million hectares","21 million hectares","26 million hectares"],"answer":3,"explanation":"India raised its target from 21 to 26 million hectares of degraded land to be restored by 2030, as part of its goal of land degradation neutrality, which it also links to the Bonn Challenge.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2019 में मरुस्थलीकरण से निपटने के संयुक्त राष्ट्र अभिसमय के COP-14 में भारत ने 2030 तक निम्नीकृत भूमि को बहाल करने का कितना लक्ष्य घोषित किया?","optionsHi":["5 मिलियन हेक्टेयर","13 मिलियन हेक्टेयर","21 मिलियन हेक्टेयर","26 मिलियन हेक्टेयर"],"explanationHi":"भारत ने 2030 तक बहाल की जाने वाली निम्नीकृत भूमि के अपने लक्ष्य को 21 से बढ़ाकर 26 मिलियन हेक्टेयर कर दिया, जो भूमि निम्नीकरण तटस्थता के उसके लक्ष्य का हिस्सा है, जिसे वह बॉन चैलेंज से भी जोड़ता है।"},
  {"id":"env-ecology-743","question":"The Intergovernmental Science-Policy Platform on Biodiversity and Ecosystem Services (IPBES), set up in 2012, is best described as:","options":["A binding protocol under the CBD that sets each country's national biodiversity targets","The body that compiles and maintains the IUCN Red List of threatened species worldwide","A fund that pays developing countries for protecting and restoring their tropical forests","A body that assesses biodiversity science for policy, like the IPCC for climate"],"answer":3,"explanation":"IPBES produces assessments such as its 2019 Global Assessment, which warned that about a million species face extinction. It sets no targets and holds no funds; the Red List is compiled by IUCN.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2012 में स्थापित जैव विविधता और पारिस्थितिकी तंत्र सेवाओं पर अंतर-सरकारी विज्ञान-नीति मंच (IPBES) का सबसे उपयुक्त वर्णन है:","optionsHi":["CBD के अंतर्गत बाध्यकारी प्रोटोकॉल जो प्रत्येक देश के राष्ट्रीय जैव विविधता लक्ष्य निर्धारित करता है","वह निकाय जो विश्व भर की संकटग्रस्त प्रजातियों की IUCN रेड लिस्ट संकलित और बनाए रखता है","वह कोष जो विकासशील देशों को उनके उष्णकटिबंधीय वनों की रक्षा और बहाली के लिए भुगतान करता है","वह निकाय जो नीति के लिए जैव विविधता विज्ञान का आकलन करता है, जैसे जलवायु के लिए IPCC"],"explanationHi":"IPBES अपने 2019 के वैश्विक आकलन जैसे आकलन तैयार करता है, जिसने चेतावनी दी कि लगभग दस लाख प्रजातियाँ विलुप्ति का सामना कर रही हैं। यह कोई लक्ष्य निर्धारित नहीं करता और कोई कोष नहीं रखता; रेड लिस्ट IUCN संकलित करता है।"},
  {"id":"env-ecology-744","question":"The UN Conference on Sustainable Development (Rio+20) held in 2012 is best known for its outcome document 'The Future We Want', which:","options":["Began the process that led to the SDGs","Adopted the Kyoto Protocol's second commitment period","Created the UN Environment Programme in Nairobi","Opened the Convention on Biological Diversity for signature"],"answer":0,"explanation":"Rio+20 agreed to set up a process for SDGs, adopted in 2015, and to strengthen UNEP. UNEP itself dates from 1972, the CBD from Rio 1992, and the second Kyoto period from Doha in 2012.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2012 में आयोजित संयुक्त राष्ट्र सतत विकास सम्मेलन (रियो+20) अपने परिणाम दस्तावेज़ 'द फ्यूचर वी वांट' के लिए सबसे अधिक जाना जाता है, जिसने:","optionsHi":["उस प्रक्रिया का आरंभ किया जिससे SDG बने","क्योटो प्रोटोकॉल की दूसरी प्रतिबद्धता अवधि को अपनाया","नैरोबी में संयुक्त राष्ट्र पर्यावरण कार्यक्रम की रचना की","जैव विविधता अभिसमय को हस्ताक्षर के लिए खोला"],"explanationHi":"रियो+20 ने SDG के लिए एक प्रक्रिया स्थापित करने, जो 2015 में अपनाए गए, और UNEP को सुदृढ़ करने पर सहमति दी। UNEP स्वयं 1972 का है, CBD रियो 1992 का, और क्योटो की दूसरी अवधि 2012 के दोहा की।"},
  {"id":"env-ecology-745","question":"The 2030 Agenda for Sustainable Development, adopted by the UN General Assembly in 2015, contains:","options":["8 goals and 21 targets","17 goals and 169 targets","17 goals and 232 targets","15 goals and 169 targets"],"answer":1,"explanation":"The SDGs comprise 17 goals with 169 targets, tracked by a set of indicators numbering over 230. The Millennium Development Goals they replaced had 8 goals and 21 targets.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"2015 में संयुक्त राष्ट्र महासभा द्वारा अपनाए गए सतत विकास के 2030 एजेंडा में क्या सम्मिलित है?","optionsHi":["8 लक्ष्य और 21 उप-लक्ष्य","17 लक्ष्य और 169 उप-लक्ष्य","17 लक्ष्य और 232 उप-लक्ष्य","15 लक्ष्य और 169 उप-लक्ष्य"],"explanationHi":"SDG में 17 लक्ष्य और 169 उप-लक्ष्य हैं, जिनकी निगरानी 230 से अधिक संकेतकों के समूह से होती है। जिन सहस्राब्दी विकास लक्ष्यों का इन्होंने स्थान लिया, उनमें 8 लक्ष्य और 21 उप-लक्ष्य थे।"},
  {"id":"env-ecology-746","question":"The international treaty that regulates the dumping of wastes and other matter at sea from ships and aircraft is the:","options":["MARPOL Convention of 1973","Basel Convention of 1989","London Convention of 1972","Ramsar Convention of 1971"],"answer":2,"explanation":"The London Convention (and its 1996 Protocol), under the IMO, controls deliberate dumping at sea. MARPOL deals with pollution arising from the normal operation of ships, such as oil and sewage discharges.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जहाज़ों और विमानों से समुद्र में अपशिष्टों और अन्य पदार्थों के डंपिंग का नियमन करने वाली अंतर्राष्ट्रीय संधि है:","optionsHi":["1973 का MARPOL अभिसमय","1989 का बेसल अभिसमय","1972 का लंदन अभिसमय","1971 का रामसर अभिसमय"],"explanationHi":"IMO के अंतर्गत लंदन अभिसमय (और उसका 1996 का प्रोटोकॉल) समुद्र में जानबूझकर डंपिंग को नियंत्रित करता है। MARPOL जहाज़ों के सामान्य संचालन से होने वाले प्रदूषण, जैसे तेल और मलजल के निस्सरण, से निपटता है।"},
  {"id":"env-ecology-747","question":"The 'High Seas Treaty' (BBNJ Agreement), adopted in 2023 under the UN Convention on the Law of the Sea, deals with:","options":["Marine biodiversity in areas beyond national jurisdiction","Fishing quotas inside the exclusive economic zones of coastal states","Disputes over seabed mining in territorial waters","Shipping lanes and freedom of navigation through straits"],"answer":0,"explanation":"The agreement covers the high seas and international seabed, about two-thirds of the ocean, providing for marine protected areas there, environmental impact assessments and sharing of benefits from marine genetic resources.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"समुद्र विधि पर संयुक्त राष्ट्र अभिसमय के अंतर्गत 2023 में अपनाई गई 'उच्च सागर संधि' (BBNJ समझौता) किससे संबंधित है?","optionsHi":["राष्ट्रीय क्षेत्राधिकार से परे क्षेत्रों में समुद्री जैव विविधता","तटीय राज्यों के अनन्य आर्थिक क्षेत्रों के भीतर मछली पकड़ने के कोटे","प्रादेशिक जल में समुद्र-तल खनन के विवाद","जहाज़ी मार्ग और जलडमरूमध्यों से होकर नौवहन की स्वतंत्रता"],"explanationHi":"यह समझौता उच्च सागर और अंतर्राष्ट्रीय समुद्र-तल को, जो महासागर का लगभग दो-तिहाई है, शामिल करता है, और वहाँ समुद्री संरक्षित क्षेत्रों, पर्यावरण प्रभाव आकलन और समुद्री आनुवंशिक संसाधनों से लाभों के साझाकरण का प्रावधान करता है।"},
  {"id":"env-ecology-748","question":"In 2022, the UN Environment Assembly resolved to negotiate a legally binding international instrument on plastic pollution. Which statement about it is correct?","options":["It applies only to plastic floating in the open ocean beyond national waters","It was adopted as an amendment to the Stockholm Convention on persistent pollutants","It addresses the full life cycle of plastic, from production and design to disposal","It sets a target to end all plastic production worldwide by the year 2030"],"answer":2,"explanation":"Resolution 5/14 at UNEA-5.2 in Nairobi mandated an intergovernmental negotiating committee for a treaty covering the full life cycle of plastics, including in the marine environment. It is a new instrument, not an amendment to an existing convention.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2022 में संयुक्त राष्ट्र पर्यावरण सभा ने प्लास्टिक प्रदूषण पर विधिक रूप से बाध्यकारी अंतर्राष्ट्रीय लिखत पर वार्ता करने का संकल्प लिया। इसके बारे में कौन-सा कथन सही है?","optionsHi":["यह केवल राष्ट्रीय जल से परे खुले महासागर में तैरते प्लास्टिक पर लागू होता है","इसे स्थायी प्रदूषकों पर स्टॉकहोम अभिसमय के संशोधन के रूप में अपनाया गया","यह प्लास्टिक के संपूर्ण जीवन चक्र को संबोधित करता है, उत्पादन और डिज़ाइन से निपटान तक","यह 2030 तक विश्व भर में सारा प्लास्टिक उत्पादन समाप्त करने का लक्ष्य निर्धारित करता है"],"explanationHi":"नैरोबी में UNEA-5.2 के संकल्प 5/14 ने प्लास्टिक के संपूर्ण जीवन चक्र को, समुद्री पर्यावरण सहित, शामिल करने वाली संधि के लिए अंतर-सरकारी वार्ता समिति को अधिदेश दिया। यह नया लिखत है, किसी मौजूदा अभिसमय का संशोधन नहीं।"},
  {"id":"env-ecology-749","question":"Which one of the following countries is NOT a party to the Convention on Biological Diversity?","options":["Australia","United States","New Zealand","Saudi Arabia"],"answer":1,"explanation":"The USA signed the CBD in 1993 but the Senate has not ratified it, so it is one of the very few non-parties. Australia, New Zealand and Saudi Arabia, like almost every other country, are parties.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सा देश जैव विविधता अभिसमय का पक्षकार नहीं है?","optionsHi":["ऑस्ट्रेलिया","संयुक्त राज्य अमेरिका","न्यूज़ीलैंड","सऊदी अरब"],"explanationHi":"अमेरिका ने 1993 में CBD पर हस्ताक्षर किए, परंतु सीनेट ने अभिपुष्टि नहीं की, इसलिए वह बहुत थोड़े गैर-पक्षकारों में से एक है। ऑस्ट्रेलिया, न्यूज़ीलैंड और सऊदी अरब, लगभग हर अन्य देश की तरह, पक्षकार हैं।"},
  {"id":"env-ecology-750","question":"World Wetlands Day is observed on 2 February each year because that date marks:","options":["The entry into force of the Ramsar Convention in 1975","The adoption of the Ramsar Convention in 1971","The designation of the first Ramsar site in India","The founding of the IUCN in Switzerland in 1948"],"answer":1,"explanation":"The Convention on Wetlands was signed at Ramsar, Iran, on 2 February 1971; it entered into force in 1975. India's first Ramsar sites, Chilika and Keoladeo, were designated in 1981.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"विश्व आर्द्रभूमि दिवस प्रतिवर्ष 2 फरवरी को मनाया जाता है क्योंकि वह तिथि चिह्नित करती है:","optionsHi":["1975 में रामसर अभिसमय का लागू होना","1971 में रामसर अभिसमय को अपनाया जाना","भारत में पहले रामसर स्थल का नामांकन","1948 में स्विट्ज़रलैंड में IUCN की स्थापना"],"explanationHi":"आर्द्रभूमि अभिसमय पर रामसर, ईरान में 2 फरवरी 1971 को हस्ताक्षर हुए; यह 1975 में लागू हुआ। भारत के पहले रामसर स्थल, चिल्का और केओलादेव, 1981 में नामित हुए।"},
  {"id":"env-ecology-751","question":"The current IUCN Red List system (version 3.1) places every species into one of how many categories, from 'Extinct' to 'Not Evaluated'?","options":["Seven","Eight","Nine","Eleven"],"answer":2,"explanation":"The nine categories are Extinct, Extinct in the Wild, Critically Endangered, Endangered, Vulnerable, Near Threatened, Least Concern, Data Deficient and Not Evaluated.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"वर्तमान IUCN रेड लिस्ट प्रणाली (संस्करण 3.1) प्रत्येक प्रजाति को 'विलुप्त' से 'अमूल्यांकित' तक कितनी श्रेणियों में से किसी एक में रखती है?","optionsHi":["सात","आठ","नौ","ग्यारह"],"explanationHi":"नौ श्रेणियाँ हैं: विलुप्त, वन में विलुप्त, घोर संकटग्रस्त, संकटग्रस्त, सुभेद्य, निकट संकटग्रस्त, अल्प चिंताजनक, आँकड़ा अपर्याप्त और अमूल्यांकित।"},
  {"id":"env-ecology-752","question":"Match the IUCN Red List criterion with what it is based on. A. Criterion A  B. Criterion B  C. Criterion D  D. Criterion E; 1. Quantitative analysis of the probability of extinction  2. Reduction in population size  3. Very small or restricted population  4. Geographic range, with fragmentation, decline or fluctuation","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"answer":3,"explanation":"A is population reduction, B geographic range, C small population with decline, D very small or restricted population, and E a quantitative extinction-probability analysis. A species needs to meet only one criterion to be listed.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"IUCN रेड लिस्ट मानदंड का उस आधार से मिलान कीजिए जिस पर वह टिका है। A. मानदंड A B. मानदंड B C. मानदंड D D. मानदंड E; 1. विलुप्ति की संभावना का मात्रात्मक विश्लेषण 2. समष्टि आकार में कमी 3. बहुत छोटी या सीमित समष्टि 4. भौगोलिक परास, जिसमें विखंडन, ह्रास या उतार-चढ़ाव हो","optionsHi":["A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"explanationHi":"A समष्टि में कमी है, B भौगोलिक परास, C ह्रास के साथ छोटी समष्टि, D बहुत छोटी या सीमित समष्टि, और E विलुप्ति-संभावना का मात्रात्मक विश्लेषण। किसी प्रजाति को सूचीबद्ध होने के लिए केवल एक मानदंड पूरा करना होता है।"},
  {"id":"env-ecology-753","question":"Under criterion E of the IUCN Red List, a species qualifies as Critically Endangered if quantitative analysis shows a probability of extinction in the wild of at least:","options":["20 per cent within 20 years or five generations","50 per cent within 10 years or three generations","10 per cent within 100 years","90 per cent within 50 years or ten generations"],"answer":1,"explanation":"The CR threshold is ≥50% in 10 years or 3 generations. A 20% chance in 20 years or 5 generations corresponds to Endangered, and 10% in 100 years to Vulnerable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"IUCN रेड लिस्ट के मानदंड E के अंतर्गत, कोई प्रजाति घोर संकटग्रस्त तब मानी जाती है जब मात्रात्मक विश्लेषण वन में विलुप्ति की कम से कम कितनी संभावना दर्शाता है?","optionsHi":["20 प्रतिशत, 20 वर्ष या पाँच पीढ़ियों के भीतर","50 प्रतिशत, 10 वर्ष या तीन पीढ़ियों के भीतर","10 प्रतिशत, 100 वर्ष के भीतर","90 प्रतिशत, 50 वर्ष या दस पीढ़ियों के भीतर"],"explanationHi":"CR की सीमा 10 वर्ष या 3 पीढ़ियों में ≥50% है। 20 वर्ष या 5 पीढ़ियों में 20% संभावना संकटग्रस्त के अनुरूप है, और 100 वर्ष में 10% सुभेद्य के।"},
  {"id":"env-ecology-754","question":"Under criterion D of the IUCN Red List, a species whose entire wild population numbers more than 50 but fewer than 250 mature individuals qualifies as:","options":["Critically Endangered","Endangered","Vulnerable","Near Threatened"],"answer":1,"explanation":"For criterion D the thresholds are fewer than 50 mature individuals for CR, fewer than 250 for EN and fewer than 1,000 for VU. Counting juveniles as well is a common error.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"IUCN रेड लिस्ट के मानदंड D के अंतर्गत, वह प्रजाति जिसकी संपूर्ण वन्य समष्टि में 50 से अधिक परंतु 250 से कम परिपक्व व्यक्ति हैं, किस श्रेणी की होगी?","optionsHi":["घोर संकटग्रस्त","संकटग्रस्त","सुभेद्य","निकट संकटग्रस्त"],"explanationHi":"मानदंड D के लिए सीमाएँ हैं: CR के लिए 50 से कम परिपक्व व्यक्ति, EN के लिए 250 से कम और VU के लिए 1,000 से कम। किशोरों को भी गिनना एक आम त्रुटि है।"},
  {"id":"env-ecology-755","question":"A bird has not been reliably recorded for several decades, but surveys of its remote range have not been thorough enough to rule out its survival. On the IUCN Red List it would normally appear as:","options":["Extinct, since decades have passed without a record","Data Deficient, until further surveys are done","Critically Endangered (Possibly Extinct)","Near Threatened, pending new survey results"],"answer":2,"explanation":"IUCN lists a species as Extinct only when there is no reasonable doubt the last individual has died. Until then such a species stays CR with a 'Possibly Extinct' tag; Data Deficient is for species too poorly known to assess.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"किसी पक्षी का कई दशकों से विश्वसनीय रूप से कोई अभिलेख नहीं मिला है, परंतु उसके दूरस्थ परास के सर्वेक्षण इतने गहन नहीं रहे कि उसके जीवित रहने की संभावना नकारी जा सके। IUCN रेड लिस्ट में वह सामान्यतः किस रूप में दिखेगा?","optionsHi":["विलुप्त, क्योंकि दशकों से कोई अभिलेख नहीं मिला","आँकड़ा अपर्याप्त, जब तक और सर्वेक्षण न हों","घोर संकटग्रस्त (संभवतः विलुप्त)","निकट संकटग्रस्त, नए सर्वेक्षण परिणामों की प्रतीक्षा में"],"explanationHi":"IUCN किसी प्रजाति को विलुप्त तभी सूचीबद्ध करता है जब इसमें कोई उचित संदेह न हो कि अंतिम व्यक्ति मर चुका है। तब तक ऐसी प्रजाति 'संभवतः विलुप्त' टैग के साथ CR बनी रहती है; आँकड़ा अपर्याप्त उन प्रजातियों के लिए है जो आकलन के लिए बहुत कम ज्ञात हैं।"},
  {"id":"env-ecology-756","question":"In national or regional Red Lists prepared using IUCN guidelines, an additional category is used for a species that has disappeared from that region but survives elsewhere. This category is:","options":["Regionally Extinct","Extinct in the Wild","Locally Endangered","Not Applicable"],"answer":0,"explanation":"Regionally Extinct (RE) covers species lost from the assessed region only, such as the cheetah in India before its reintroduction. Extinct in the Wild applies globally, when a species survives only in captivity.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"IUCN दिशानिर्देशों से तैयार राष्ट्रीय या क्षेत्रीय रेड लिस्टों में उस प्रजाति के लिए एक अतिरिक्त श्रेणी का उपयोग होता है जो उस क्षेत्र से लुप्त हो चुकी है परंतु अन्यत्र जीवित है। यह श्रेणी है:","optionsHi":["क्षेत्रीय रूप से विलुप्त","वन में विलुप्त","स्थानीय रूप से संकटग्रस्त","लागू नहीं"],"explanationHi":"क्षेत्रीय रूप से विलुप्त (RE) केवल आकलित क्षेत्र से लुप्त प्रजातियों को दर्शाता है, जैसे पुनःप्रवेश से पहले भारत में चीता। वन में विलुप्त वैश्विक रूप से लागू होता है, जब प्रजाति केवल बंदी अवस्था में जीवित हो।"},
  {"id":"env-ecology-757","question":"Which of the following are listed as Critically Endangered on the IUCN Red List? 1. Gharial 2. Hawksbill turtle 3. Greater one-horned rhinoceros 4. Bengal florican. Select the correct answer:","options":["1 and 2 only","1, 2 and 4 only","2, 3 and 4 only","1, 3 and 4 only"],"answer":1,"explanation":"The gharial, hawksbill turtle and Bengal florican are all Critically Endangered. The greater one-horned rhinoceros recovered enough to be listed as Vulnerable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-से IUCN रेड लिस्ट में घोर संकटग्रस्त के रूप में सूचीबद्ध हैं? 1. घड़ियाल 2. हॉक्सबिल कछुआ 3. एक सींग वाला बड़ा गैंडा 4. बंगाल फ्लोरिकन। सही उत्तर चुनिए:","optionsHi":["केवल 1 और 2","केवल 1, 2 और 4","केवल 2, 3 और 4","केवल 1, 3 और 4"],"explanationHi":"घड़ियाल, हॉक्सबिल कछुआ और बंगाल फ्लोरिकन तीनों घोर संकटग्रस्त हैं। एक सींग वाले बड़े गैंडे में इतनी सुधार हुई कि उसे सुभेद्य के रूप में सूचीबद्ध किया गया।"},
  {"id":"env-ecology-758","question":"Which one of the following pairs of animal and IUCN Red List status is NOT correctly matched?","options":["Gharial — Critically Endangered","Asian elephant — Endangered","Red panda — Endangered","Snow leopard — Endangered"],"answer":3,"explanation":"The snow leopard was moved from Endangered to Vulnerable in 2017. The gharial is Critically Endangered, and the Asian elephant and red panda are Endangered.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जंतु और IUCN रेड लिस्ट स्थिति के निम्नलिखित जोड़ों में से कौन-सा सही सुमेलित नहीं है?","optionsHi":["घड़ियाल — घोर संकटग्रस्त","एशियाई हाथी — संकटग्रस्त","रेड पांडा — संकटग्रस्त","हिम तेंदुआ — संकटग्रस्त"],"explanationHi":"हिम तेंदुए को 2017 में संकटग्रस्त से सुभेद्य में ले जाया गया। घड़ियाल घोर संकटग्रस्त है, और एशियाई हाथी तथा रेड पांडा संकटग्रस्त हैं।"},
  {"id":"env-ecology-759","question":"Banana, potato, sugarcane and cassava are usually conserved ex situ as living plants or in tissue culture rather than as seeds in a seed bank. The main reason is that:","options":["Their seeds lose viability within a few days of harvest","They are protected under law and cannot be stored as seeds","They spread vegetatively, and seed poorly or not true to type","Their seeds are too large to fit into standard storage packets"],"answer":2,"explanation":"These crops are multiplied by suckers, tubers or cuttings and many varieties set little viable seed, which in any case would not reproduce the variety. They are kept in field gene banks or in vitro.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"केला, आलू, गन्ना और कसावा का संरक्षण सामान्यतः बीज बैंक में बीजों के रूप में नहीं, बल्कि जीवित पौधों या ऊतक संवर्धन के रूप में बाह्य-स्थाने किया जाता है। इसका मुख्य कारण यह है कि:","optionsHi":["उनके बीज कटाई के कुछ ही दिनों में जीवनक्षमता खो देते हैं","वे विधि द्वारा संरक्षित हैं और बीजों के रूप में भंडारित नहीं किए जा सकते","वे कायिक रूप से फैलते हैं, और बीज कम बनाते हैं या शुद्ध प्ररूप के नहीं बनाते","उनके बीज मानक भंडारण पैकेटों में समाने के लिए बहुत बड़े होते हैं"],"explanationHi":"ये फसलें अन्तःभूस्तारी, कंदों या कलमों से गुणित की जाती हैं और अनेक किस्में बहुत कम जीवनक्षम बीज बनाती हैं, जो वैसे भी किस्म को पुनः उत्पन्न नहीं करते। इन्हें क्षेत्र जीन बैंकों या परखनली में रखा जाता है।"},
  {"id":"env-ecology-760","question":"For long-term storage in base collections, dried orthodox seeds in gene banks such as the National Gene Bank in New Delhi are typically kept at about:","options":["−196 °C","+4 °C","0 °C","−18 °C"],"answer":3,"explanation":"Seeds dried to low moisture are sealed and stored at about −18 °C, where many species stay viable for decades. −196 °C (liquid nitrogen) is used for cryopreservation, and +4 °C only for short-term working collections.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"नई दिल्ली के राष्ट्रीय जीन बैंक जैसे जीन बैंकों में आधार संग्रहों में दीर्घकालिक भंडारण के लिए सुखाए गए ऑर्थोडॉक्स बीज सामान्यतः लगभग किस तापमान पर रखे जाते हैं?","optionsHi":["−196 °C","+4 °C","0 °C","−18 °C"],"explanationHi":"कम नमी तक सुखाए गए बीजों को सीलबंद करके लगभग −18 °C पर रखा जाता है, जहाँ अनेक प्रजातियाँ दशकों तक जीवनक्षम रहती हैं। −196 °C (द्रव नाइट्रोजन) का उपयोग क्रायोसंरक्षण के लिए होता है, और +4 °C केवल अल्पकालिक कार्यशील संग्रहों के लिए।"},
  {"id":"env-ecology-761","question":"A high-altitude seed vault set up in 2010 by the DRDO with the National Bureau of Plant Genetic Resources, using the natural cold to store seeds without electricity, is located at:","options":["Chang La in Ladakh","Rohtang Pass in Himachal Pradesh","Nathu La in Sikkim","Badrinath in Uttarakhand"],"answer":0,"explanation":"The Chang La facility, at over 5,000 m, stays below freezing year-round, providing low-cost backup storage for India's crop germplasm.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2010 में DRDO द्वारा राष्ट्रीय पादप आनुवंशिक संसाधन ब्यूरो के साथ स्थापित उच्च-ऊँचाई का बीज भंडार, जो बिना बिजली के प्राकृतिक ठंड का उपयोग करके बीज संग्रहित करता है, कहाँ स्थित है?","optionsHi":["लद्दाख में चांग ला","हिमाचल प्रदेश में रोहतांग दर्रा","सिक्किम में नाथू ला","उत्तराखंड में बद्रीनाथ"],"explanationHi":"5,000 m से अधिक ऊँचाई पर स्थित चांग ला की सुविधा साल भर हिमांक से नीचे रहती है, जो भारत के फसल जनन-द्रव्य के लिए कम लागत वाला बैकअप भंडारण प्रदान करती है।"},
  {"id":"env-ecology-762","question":"In 1975, India launched the Crocodile Conservation Project with UNDP and FAO support, whose main approach for the gharial was:","options":["Moving all wild gharials permanently into closed zoos and breeding centres","Rearing wild-collected eggs in captivity and releasing young in rivers","Culling mugger crocodiles that compete with gharials for fish in the rivers","Introducing gharials into large reservoirs behind dams in southern India"],"answer":1,"explanation":"Under 'rear and release', wild eggs were hatched and the young raised past their most vulnerable stage before release, for example into the Chambal. Natural hatchling survival in the wild is very low.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1975 में भारत ने UNDP और FAO के सहयोग से मगरमच्छ संरक्षण परियोजना शुरू की, जिसमें घड़ियाल के लिए मुख्य उपाय था:","optionsHi":["सभी वन्य घड़ियालों को स्थायी रूप से बंद चिड़ियाघरों और प्रजनन केंद्रों में ले जाना","वन से एकत्र अंडों को बंदी अवस्था में पालना और बच्चों को नदियों में छोड़ना","नदियों में मछली के लिए घड़ियालों से प्रतिस्पर्धा करने वाले मगर मगरमच्छों को मारना","दक्षिण भारत में बाँधों के पीछे बड़े जलाशयों में घड़ियालों को लाना"],"explanationHi":"'पालो और छोड़ो' में वन्य अंडे सेए गए और बच्चों को सबसे असुरक्षित चरण पार कराकर, उदाहरण के लिए चंबल में, छोड़ा गया। वन में नवजातों की प्राकृतिक उत्तरजीविता बहुत कम होती है।"},
  {"id":"env-ecology-763","question":"India's first conservation breeding centre for Gyps vultures, set up after the collapse of their populations, is located at:","options":["Rajabhatkhawa, West Bengal","Rani, Assam","Bhopal, Madhya Pradesh","Pinjore, Haryana"],"answer":3,"explanation":"The Jatayu Conservation Breeding Centre at Pinjore, begun in 2001, was the first; centres in West Bengal, Assam and Madhya Pradesh followed. Captive breeding paired with the veterinary diclofenac ban is meant to restore wild flocks.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जिप्स गिद्धों की समष्टियों के ढहने के बाद स्थापित भारत का पहला गिद्ध संरक्षण प्रजनन केंद्र कहाँ स्थित है?","optionsHi":["राजाभातखावा, पश्चिम बंगाल","रानी, असम","भोपाल, मध्य प्रदेश","पिंजौर, हरियाणा"],"explanationHi":"2001 में आरंभ हुआ पिंजौर का जटायु संरक्षण प्रजनन केंद्र पहला था; उसके बाद पश्चिम बंगाल, असम और मध्य प्रदेश के केंद्र आए। बंदी प्रजनन को पशु-चिकित्सीय डाइक्लोफेनाक प्रतिबंध के साथ जोड़ने का उद्देश्य वन्य झुंडों को बहाल करना है।"},
  {"id":"env-ecology-764","question":"The Great Banyan, a single tree whose aerial roots make it look like a small forest, stands in the:","options":["Lloyd Botanical Garden, Darjeeling","Lalbagh Botanical Garden, Bengaluru","Indian Botanic Garden, Howrah (Shibpur)","National Botanical Research Institute garden, Lucknow"],"answer":2,"explanation":"The Great Banyan at Shibpur, Howrah, in the Acharya Jagadish Chandra Bose Indian Botanic Garden, is the garden's best-known feature. Botanical gardens are a key ex situ method, holding living plant collections.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"महान बरगद, एक ऐसा अकेला वृक्ष जिसकी हवाई जड़ें उसे छोटे वन जैसा बना देती हैं, कहाँ स्थित है?","optionsHi":["लॉयड वनस्पति उद्यान, दार्जिलिंग","लालबाग वनस्पति उद्यान, बेंगलुरु","भारतीय वनस्पति उद्यान, हावड़ा (शिबपुर)","राष्ट्रीय वनस्पति अनुसंधान संस्थान का उद्यान, लखनऊ"],"explanationHi":"आचार्य जगदीश चंद्र बोस भारतीय वनस्पति उद्यान, शिबपुर, हावड़ा का महान बरगद उद्यान की सबसे प्रसिद्ध विशेषता है। वनस्पति उद्यान एक प्रमुख बाह्य-स्थाने विधि हैं, जिनमें जीवित पादप संग्रह रखे जाते हैं।"},
  {"id":"env-ecology-765","question":"The Central Zoo Authority, which recognises and regulates zoos in India, was set up in 1992 under:","options":["The Environment (Protection) Act, 1986","The Biological Diversity Act, 2002","The Wildlife (Protection) Act, 1972","The Prevention of Cruelty to Animals Act, 1960"],"answer":2,"explanation":"A 1991 amendment to the Wildlife (Protection) Act provided for the Central Zoo Authority, constituted in 1992. No zoo may operate without its recognition.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत में चिड़ियाघरों को मान्यता देने और विनियमित करने वाला केंद्रीय चिड़ियाघर प्राधिकरण 1992 में किसके अंतर्गत स्थापित हुआ?","optionsHi":["पर्यावरण (संरक्षण) अधिनियम, 1986","जैविक विविधता अधिनियम, 2002","वन्यजीव (संरक्षण) अधिनियम, 1972","पशु क्रूरता निवारण अधिनियम, 1960"],"explanationHi":"वन्यजीव (संरक्षण) अधिनियम के 1991 के संशोधन ने केंद्रीय चिड़ियाघर प्राधिकरण का प्रावधान किया, जिसका गठन 1992 में हुआ। उसकी मान्यता के बिना कोई चिड़ियाघर संचालित नहीं हो सकता।"},
  {"id":"env-ecology-766","question":"India's first gene sanctuary, created to conserve wild citrus species in their natural habitat, is in the:","options":["Nilgiri Hills of Tamil Nadu","Kumaon Hills of Uttarakhand","Garo Hills of Meghalaya","Aravalli Hills of Rajasthan"],"answer":2,"explanation":"The citrus gene sanctuary in the Garo Hills (Nokrek area) protects wild relatives such as Citrus indica, an in situ way of preserving crop genetic diversity.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत का पहला जीन अभयारण्य, जो जंगली नींबू-वर्गीय प्रजातियों को उनके प्राकृतिक आवास में संरक्षित करने के लिए बनाया गया, कहाँ है?","optionsHi":["तमिलनाडु की नीलगिरि पहाड़ियों में","उत्तराखंड की कुमाऊँ पहाड़ियों में","मेघालय की गारो पहाड़ियों में","राजस्थान की अरावली पहाड़ियों में"],"explanationHi":"गारो पहाड़ियों (नोकरेक क्षेत्र) का साइट्रस जीन अभयारण्य साइट्रस इंडिका जैसे जंगली संबंधियों की रक्षा करता है, जो फसल आनुवंशिक विविधता को संरक्षित करने की एक स्वस्थाने विधि है।"},
  {"id":"env-ecology-767","question":"Under IUCN guidelines, releasing individuals of a species into an area where a population of that species already exists, to increase its numbers or genetic diversity, is called:","options":["Reintroduction","Assisted colonisation","Ecological replacement","Reinforcement"],"answer":3,"explanation":"Reinforcement (supplementation) adds to an existing population. Reintroduction returns a species to part of its former range where it has died out, and assisted colonisation moves it outside its native range.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"IUCN दिशानिर्देशों के अंतर्गत, किसी प्रजाति के व्यक्तियों को उस क्षेत्र में छोड़ना जहाँ उस प्रजाति की समष्टि पहले से मौजूद है, ताकि उसकी संख्या या आनुवंशिक विविधता बढ़े, क्या कहलाता है?","optionsHi":["पुनःप्रवेश","सहायित उपनिवेशन","पारिस्थितिक प्रतिस्थापन","सुदृढ़ीकरण (रीइनफोर्समेंट)"],"explanationHi":"सुदृढ़ीकरण (अनुपूरण) मौजूदा समष्टि में जोड़ता है। पुनःप्रवेश प्रजाति को उसके पूर्व परास के उस भाग में लौटाता है जहाँ वह समाप्त हो गई थी, और सहायित उपनिवेशन उसे उसके मूल परास से बाहर ले जाता है।"},
  {"id":"env-ecology-768","question":"The IUCN Red List of Threatened Species was first established in:","options":["1948","1964","1972","1992"],"answer":1,"explanation":"The Red List began in 1964. IUCN itself was founded in 1948, the Stockholm Conference was held in 1972 and the CBD opened for signature in 1992.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"संकटग्रस्त प्रजातियों की IUCN रेड लिस्ट की स्थापना पहली बार किस वर्ष हुई?","optionsHi":["1948","1964","1972","1992"],"explanationHi":"रेड लिस्ट की शुरुआत 1964 में हुई। IUCN की स्थापना 1948 में हुई, स्टॉकहोम सम्मेलन 1972 में हुआ और CBD 1992 में हस्ताक्षर के लिए खुला।"},
  {"id":"env-ecology-769","question":"Assertion (A): Ex situ conservation in zoos and gene banks cannot by itself secure the long-term future of most species. Reason (R): Captive populations are usually small and isolated from natural selection in the wild, so they lose genetic diversity and adaptive behaviour. Choose the correct option:","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Ex situ methods are a back-up; species keep evolving with their habitats only in situ. Small captive populations suffer inbreeding and drift and can lose skills such as foraging and predator avoidance.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): चिड़ियाघरों और जीन बैंकों में बाह्य-स्थाने संरक्षण अपने आप में अधिकांश प्रजातियों के दीर्घकालिक भविष्य को सुरक्षित नहीं कर सकता। कारण (R): बंदी समष्टियाँ प्रायः छोटी और वन की प्राकृतिक वरण से पृथक होती हैं, इसलिए वे आनुवंशिक विविधता और अनुकूली व्यवहार खो देती हैं। सही विकल्प चुनिए:","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बाह्य-स्थाने विधियाँ एक बैकअप हैं; प्रजातियाँ अपने आवासों के साथ केवल स्वस्थाने ही विकसित होती रहती हैं। छोटी बंदी समष्टियाँ अंतःप्रजनन और अपप्रवाह से ग्रस्त होती हैं और भोजन खोजने तथा परभक्षी से बचने जैसे कौशल खो सकती हैं।"},
  {"id":"env-ecology-770","question":"Which of the following are methods of in situ conservation? 1. On-farm conservation of traditional landraces by farmers 2. A gene sanctuary for wild relatives of crops 3. A field gene bank of mango varieties at a research station 4. A sacred grove protected by a village community. Select the correct answer:","options":["1, 2 and 4 only","2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"On-farm conservation keeps landraces evolving in the farming systems where they arose, so it counts as in situ. A field gene bank grows plants away from their native setting and is ex situ.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-से स्वस्थाने संरक्षण की विधियाँ हैं? 1. किसानों द्वारा पारंपरिक देशी किस्मों का खेत पर संरक्षण 2. फसलों के जंगली संबंधियों के लिए जीन अभयारण्य 3. किसी अनुसंधान केंद्र पर आम की किस्मों का क्षेत्र जीन बैंक 4. ग्राम समुदाय द्वारा संरक्षित पवित्र उपवन। सही उत्तर चुनिए:","optionsHi":["केवल 1, 2 और 4","केवल 2 और 4","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"खेत पर संरक्षण देशी किस्मों को उन कृषि तंत्रों में विकसित होते रहने देता है जहाँ वे उत्पन्न हुईं, इसलिए यह स्वस्थाने माना जाता है। क्षेत्र जीन बैंक पौधों को उनके मूल परिवेश से दूर उगाता है और बाह्य-स्थाने है।"},
  {"id":"env-ecology-771","question":"Under the IUCN Red List, a species is classified as 'Extinct' when:","options":["No individual has been seen in the wild for at least ten years","Its population has fallen by more than 90 per cent in three generations","Its last wild population is confined to a single protected area","There is no reasonable doubt that the last individual has died"],"answer":3,"explanation":"Extinct requires exhaustive surveys over the species' range and time that fail to find any individual. A fixed number of years without sightings is not enough, and a 90% fall can at most qualify a species as Critically Endangered.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"IUCN रेड लिस्ट के अंतर्गत किसी प्रजाति को 'विलुप्त' तब वर्गीकृत किया जाता है जब:","optionsHi":["वन में कम से कम दस वर्षों से कोई व्यक्ति नहीं देखा गया हो","तीन पीढ़ियों में उसकी समष्टि 90 प्रतिशत से अधिक गिर गई हो","उसकी अंतिम वन्य समष्टि किसी एक संरक्षित क्षेत्र तक सीमित हो","इसमें कोई उचित संदेह न हो कि अंतिम व्यक्ति मर चुका है"],"explanationHi":"विलुप्त के लिए प्रजाति के परास और समय में व्यापक सर्वेक्षण आवश्यक हैं जिनमें कोई व्यक्ति न मिले। बिना दिखे वर्षों की निश्चित संख्या पर्याप्त नहीं है, और 90% की गिरावट अधिक से अधिक किसी प्रजाति को घोर संकटग्रस्त बना सकती है।"},
  {"id":"env-ecology-772","question":"The IUCN Green Status of Species, launched in 2021, complements the Red List by measuring:","options":["The trade volume of a species under CITES permits","How far a species has recovered across its historical range","The carbon stored in the habitats of a threatened species","The share of a species' range that lies inside protected areas"],"answer":1,"explanation":"While the Red List measures extinction risk, the Green Status scores how close a species is to full ecological recovery and what conservation has achieved or could achieve.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2021 में शुरू की गई प्रजातियों की IUCN ग्रीन स्थिति रेड लिस्ट की पूरक है, यह किसे मापकर:","optionsHi":["CITES परमिटों के अंतर्गत किसी प्रजाति के व्यापार की मात्रा","किसी प्रजाति ने अपने ऐतिहासिक परास में कितनी पुनर्प्राप्ति की है","किसी संकटग्रस्त प्रजाति के आवासों में संचित कार्बन","किसी प्रजाति के परास का कितना भाग संरक्षित क्षेत्रों के भीतर है"],"explanationHi":"जहाँ रेड लिस्ट विलुप्ति जोखिम को मापती है, ग्रीन स्थिति यह अंक देती है कि कोई प्रजाति पूर्ण पारिस्थितिक पुनर्प्राप्ति के कितने निकट है और संरक्षण ने क्या प्राप्त किया है या क्या कर सकता है।"},
  {"id":"env-ecology-773","question":"The Millennium Seed Bank, one of the largest ex situ collections of wild plant seeds in the world, is run by:","options":["The Royal Botanic Gardens, Kew, at Wakehurst in England","The Norwegian government on the island of Spitsbergen","The Food and Agriculture Organization at its headquarters in Rome","The International Rice Research Institute in the Philippines"],"answer":0,"explanation":"Kew's Millennium Seed Bank focuses on wild species. The Svalbard vault on Spitsbergen is a back-up store for duplicate crop seed from gene banks, and IRRI holds rice germplasm.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मिलेनियम सीड बैंक, जो विश्व में जंगली पौधों के बीजों के सबसे बड़े बाह्य-स्थाने संग्रहों में से एक है, किसके द्वारा संचालित है?","optionsHi":["इंग्लैंड में वेकहर्स्ट स्थित रॉयल बॉटैनिक गार्डन्स, क्यू","स्पिट्सबर्गेन द्वीप पर नॉर्वे सरकार","रोम में अपने मुख्यालय में खाद्य और कृषि संगठन","फिलीपींस में अंतर्राष्ट्रीय चावल अनुसंधान संस्थान"],"explanationHi":"क्यू का मिलेनियम सीड बैंक जंगली प्रजातियों पर केंद्रित है। स्पिट्सबर्गेन का स्वालबार्ड भंडार जीन बैंकों के प्रतिलिपि फसल बीजों का बैकअप भंडार है, और IRRI धान का जनन-द्रव्य रखता है।"},
  {"id":"env-ecology-774","question":"Semen, embryos and other genetic material of indigenous livestock breeds are conserved ex situ in India by the:","options":["National Bureau of Plant Genetic Resources, New Delhi","National Dairy Development Board, Anand","National Bureau of Animal Genetic Resources, Karnal","Indian Veterinary Research Institute, Izatnagar"],"answer":2,"explanation":"NBAGR at Karnal characterises, documents and cryopreserves livestock germplasm. NBPGR does the equivalent for crop plants.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत में देशी पशुधन नस्लों के वीर्य, भ्रूण और अन्य आनुवंशिक सामग्री का बाह्य-स्थाने संरक्षण किसके द्वारा किया जाता है?","optionsHi":["राष्ट्रीय पादप आनुवंशिक संसाधन ब्यूरो, नई दिल्ली","राष्ट्रीय डेयरी विकास बोर्ड, आणंद","राष्ट्रीय पशु आनुवंशिक संसाधन ब्यूरो, करनाल","भारतीय पशु-चिकित्सा अनुसंधान संस्थान, इज़्ज़तनगर"],"explanationHi":"करनाल का NBAGR पशुधन जनन-द्रव्य का लक्षण-निरूपण, दस्तावेज़ीकरण और क्रायोसंरक्षण करता है। NBPGR फसली पौधों के लिए यही करता है।"},
  {"id":"env-ecology-775","question":"In the Red Data Book, the pink pages and the green pages traditionally list, respectively:","options":["Critically endangered species; once-endangered species now recovered","Endemic species of islands; widespread species of the continents","Species threatened by trade; species threatened by loss of habitat","Threatened plant species; threatened animal species of the same region"],"answer":0,"explanation":"Pink pages highlight critically endangered species at high risk, while green pages record species that were once endangered but have recovered to the point of no longer being threatened.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"रेड डेटा बुक में, गुलाबी पृष्ठ और हरे पृष्ठ पारंपरिक रूप से क्रमशः क्या सूचीबद्ध करते हैं?","optionsHi":["घोर संकटग्रस्त प्रजातियाँ; कभी संकटग्रस्त रही प्रजातियाँ जो अब पुनः प्राप्त हो गई हैं","द्वीपों की स्थानिक प्रजातियाँ; महाद्वीपों की व्यापक प्रजातियाँ","व्यापार से संकटग्रस्त प्रजातियाँ; आवास हानि से संकटग्रस्त प्रजातियाँ","एक ही क्षेत्र की संकटग्रस्त पादप प्रजातियाँ; संकटग्रस्त जंतु प्रजातियाँ"],"explanationHi":"गुलाबी पृष्ठ उच्च जोखिम वाली घोर संकटग्रस्त प्रजातियों को दर्शाते हैं, जबकि हरे पृष्ठ उन प्रजातियों को दर्ज करते हैं जो कभी संकटग्रस्त थीं पर अब इतनी उबर गई हैं कि संकट में नहीं रहीं।"},
  {"id":"env-ecology-776","question":"A person aggrieved by an award or order of the National Green Tribunal can appeal against it:","options":["To the High Court of the state concerned, within 30 days","To the Supreme Court, within 90 days of the order","To the Union Ministry of Environment, within 60 days","To a larger bench of the NGT only, as no further appeal lies"],"answer":1,"explanation":"Section 22 of the NGT Act, 2010 provides an appeal to the Supreme Court within 90 days. High Courts have no appellate role over the NGT, which is why the Act is said to reduce delays in environmental cases.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"राष्ट्रीय हरित अधिकरण के किसी पंचाट या आदेश से व्यथित व्यक्ति उसके विरुद्ध अपील कर सकता है:","optionsHi":["संबंधित राज्य के उच्च न्यायालय में, 30 दिनों के भीतर","उच्चतम न्यायालय में, आदेश के 90 दिनों के भीतर","केंद्रीय पर्यावरण मंत्रालय में, 60 दिनों के भीतर","केवल NGT की बड़ी पीठ में, क्योंकि आगे कोई अपील नहीं होती"],"explanationHi":"NGT अधिनियम, 2010 की धारा 22 90 दिनों के भीतर उच्चतम न्यायालय में अपील का प्रावधान करती है। उच्च न्यायालयों की NGT पर कोई अपीलीय भूमिका नहीं है, इसीलिए कहा जाता है कि अधिनियम पर्यावरण मामलों में विलंब घटाता है।"},
  {"id":"env-ecology-777","question":"The National Green Tribunal hears civil cases arising under the Acts listed in Schedule I of the NGT Act, 2010. Which one of the following Acts is NOT in that Schedule?","options":["The Biological Diversity Act, 2002","The Wild Life (Protection) Act, 1972","The Public Liability Insurance Act, 1991","The Forest (Conservation) Act, 1980"],"answer":1,"explanation":"Schedule I lists seven Acts: the Water Act, Water Cess Act, Forest (Conservation) Act, Air Act, Environment (Protection) Act, Public Liability Insurance Act and Biological Diversity Act. The Wild Life (Protection) Act and the Indian Forest Act are not included.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"राष्ट्रीय हरित अधिकरण NGT अधिनियम, 2010 की अनुसूची I में सूचीबद्ध अधिनियमों से उत्पन्न दीवानी मामलों की सुनवाई करता है। निम्नलिखित में से कौन-सा अधिनियम उस अनुसूची में नहीं है?","optionsHi":["जैविक विविधता अधिनियम, 2002","वन्यजीव (संरक्षण) अधिनियम, 1972","लोक दायित्व बीमा अधिनियम, 1991","वन (संरक्षण) अधिनियम, 1980"],"explanationHi":"अनुसूची I में सात अधिनियम हैं: जल अधिनियम, जल उपकर अधिनियम, वन (संरक्षण) अधिनियम, वायु अधिनियम, पर्यावरण (संरक्षण) अधिनियम, लोक दायित्व बीमा अधिनियम और जैविक विविधता अधिनियम। वन्यजीव (संरक्षण) अधिनियम और भारतीय वन अधिनियम शामिल नहीं हैं।"},
  {"id":"env-ecology-778","question":"The National Green Tribunal has its principal bench at New Delhi. Which one of the following cities is NOT a seat of one of its zonal benches?","options":["Pune","Bhopal","Hyderabad","Kolkata"],"answer":2,"explanation":"The four zonal benches are at Bhopal (central), Pune (western), Kolkata (eastern) and Chennai (southern). Hyderabad has no NGT bench; southern cases go to Chennai.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"राष्ट्रीय हरित अधिकरण की प्रमुख पीठ नई दिल्ली में है। निम्नलिखित में से कौन-सा शहर उसकी किसी क्षेत्रीय पीठ का स्थान नहीं है?","optionsHi":["पुणे","भोपाल","हैदराबाद","कोलकाता"],"explanationHi":"चार क्षेत्रीय पीठें भोपाल (मध्य), पुणे (पश्चिमी), कोलकाता (पूर्वी) और चेन्नई (दक्षिणी) में हैं। हैदराबाद में कोई NGT पीठ नहीं है; दक्षिणी मामले चेन्नई जाते हैं।"},
  {"id":"env-ecology-779","question":"Consider the following statements: 1. The definition of 'environment' in the Environment (Protection) Act, 1986 includes property. 2. The Air (Prevention and Control of Pollution) Act was amended in 1987 to include noise within the meaning of 'air pollutant'. 3. Under the Environment (Protection) Act, only state governments can set standards for emission of pollutants. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Section 2(a) of the EP Act covers water, air and land and their interrelationship with human beings, other living creatures, plants, micro-organisms and property; the 1987 Air Act amendment added noise. Standard-setting under Section 3 rests with the Central Government.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. पर्यावरण (संरक्षण) अधिनियम, 1986 में 'पर्यावरण' की परिभाषा में संपत्ति शामिल है। 2. वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम में 1987 में संशोधन करके 'वायु प्रदूषक' के अर्थ में शोर को शामिल किया गया। 3. पर्यावरण (संरक्षण) अधिनियम के अंतर्गत केवल राज्य सरकारें ही प्रदूषकों के उत्सर्जन के मानक निर्धारित कर सकती हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"EP अधिनियम की धारा 2(a) जल, वायु और भूमि तथा उनके मानवों, अन्य जीवों, पौधों, सूक्ष्मजीवों और संपत्ति से अंतर्संबंध को शामिल करती है; 1987 के वायु अधिनियम संशोधन ने शोर जोड़ा। धारा 3 के अंतर्गत मानक निर्धारण केंद्र सरकार के पास है।"},
  {"id":"env-ecology-780","question":"Consider the following statements: 1. The Water (Prevention and Control of Pollution) Act, 1974 was enacted by Parliament under Article 252, after the legislatures of several states passed resolutions. 2. The Air (Prevention and Control of Pollution) Act, 1981 was enacted under Article 253 to implement decisions of the Stockholm Conference. Which of the statements given above is/are correct?","options":["1 only","2 only","Neither 1 nor 2","Both 1 and 2"],"answer":3,"explanation":"Water is a state subject, so Parliament legislated under Article 252 on the request of state legislatures, and other states adopted the Act later. The Air Act, like the EP Act, rests on Article 253, which lets Parliament implement international agreements.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. जल (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1974 संसद द्वारा अनुच्छेद 252 के अंतर्गत, अनेक राज्यों की विधायिकाओं द्वारा प्रस्ताव पारित करने के बाद, अधिनियमित किया गया। 2. वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1981 स्टॉकहोम सम्मेलन के निर्णयों को लागू करने के लिए अनुच्छेद 253 के अंतर्गत अधिनियमित किया गया। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","न तो 1 और न ही 2","1 और 2 दोनों"],"explanationHi":"जल राज्य सूची का विषय है, इसलिए संसद ने राज्य विधायिकाओं के अनुरोध पर अनुच्छेद 252 के अंतर्गत कानून बनाया, और अन्य राज्यों ने अधिनियम को बाद में अपनाया। वायु अधिनियम, EP अधिनियम की तरह, अनुच्छेद 253 पर आधारित है, जो संसद को अंतर्राष्ट्रीय समझौते लागू करने देता है।"},
  {"id":"env-ecology-781","question":"Consider the following statements about the Water (Prevention and Control of Pollution) Cess Act, 1977: 1. It levied a cess on water consumed by specified industries and local authorities. 2. Its proceeds were meant to augment the resources of the pollution control boards. 3. It was repealed in 2017 when the Goods and Services Tax was introduced. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"The cess, with rebates for installing treatment plants, funded the central and state boards. It was among the levies subsumed with the introduction of GST and was repealed by the Taxation Laws (Amendment) Act, 2017.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जल (प्रदूषण निवारण और नियंत्रण) उपकर अधिनियम, 1977 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसने निर्दिष्ट उद्योगों और स्थानीय प्राधिकरणों द्वारा उपभोग किए गए जल पर उपकर लगाया। 2. इसकी आय प्रदूषण नियंत्रण बोर्डों के संसाधन बढ़ाने के लिए थी। 3. वस्तु एवं सेवा कर लागू होने पर इसे 2017 में निरस्त कर दिया गया। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"उपचार संयंत्र लगाने पर छूट वाले इस उपकर से केंद्रीय और राज्य बोर्डों को धन मिलता था। यह GST लागू होने पर समाहित किए गए करों में था और कराधान विधि (संशोधन) अधिनियम, 2017 द्वारा निरस्त कर दिया गया।"},
  {"id":"env-ecology-782","question":"Consider the following statements about the Wild Life (Protection) Amendment Act, 2022: 1. It reduced the number of schedules in the Act from six to four. 2. It removed the separate schedule listing vermin species. 3. It took away the power of the Central Government to declare any wild animal as vermin. Which of the statements given above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"After 2022 the schedules are: I and II for animals with different levels of protection, III for plants and IV for CITES-listed specimens; the vermin schedule went. But Section 62 still lets the Centre notify an animal as vermin for an area and period.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"वन्यजीव (संरक्षण) संशोधन अधिनियम, 2022 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसने अधिनियम में अनुसूचियों की संख्या छह से घटाकर चार कर दी। 2. इसने नाशीजीव (वर्मिन) प्रजातियों को सूचीबद्ध करने वाली अलग अनुसूची हटा दी। 3. इसने केंद्र सरकार से किसी भी वन्य जंतु को नाशीजीव घोषित करने की शक्ति छीन ली। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"2022 के बाद अनुसूचियाँ हैं: I और II भिन्न स्तरों की सुरक्षा वाले जंतुओं के लिए, III पौधों के लिए और IV CITES-सूचीबद्ध नमूनों के लिए; नाशीजीव अनुसूची हट गई। परंतु धारा 62 अब भी केंद्र को किसी क्षेत्र और अवधि के लिए किसी जंतु को नाशीजीव अधिसूचित करने देती है।"},
  {"id":"env-ecology-783","question":"Under the Forest (Conservation) Act, 1980, which of the following uses of forest land counts as a 'non-forest purpose', requiring prior approval of the Central Government?","options":["Laying fire lines to protect the forest from fires","Building check-posts and wireless stations for forest staff","Planting rubber, oil palm or tea on cleared forest land","Fencing a plantation of native trees inside the forest"],"answer":2,"explanation":"The Act's explanation expressly treats cultivation of tea, coffee, spices, rubber, palms, oil-bearing plants, horticultural crops and medicinal plants as non-forest purposes. Works for conservation and management of forests, such as fire lines, check-posts and fencing, are excluded.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"वन (संरक्षण) अधिनियम, 1980 के अंतर्गत वन भूमि का निम्नलिखित में से कौन-सा उपयोग 'गैर-वानिकी प्रयोजन' माना जाता है, जिसके लिए केंद्र सरकार की पूर्व अनुमति आवश्यक है?","optionsHi":["वन को आग से बचाने के लिए अग्नि रेखाएँ बनाना","वन कर्मचारियों के लिए जाँच चौकियाँ और बेतार स्टेशन बनाना","साफ़ की गई वन भूमि पर रबर, तेल ताड़ या चाय लगाना","वन के भीतर देशी वृक्षों के रोपण की बाड़ लगाना"],"explanationHi":"अधिनियम का स्पष्टीकरण चाय, कॉफ़ी, मसालों, रबर, ताड़, तेल-बीज वाले पौधों, बागवानी फसलों और औषधीय पौधों की खेती को स्पष्ट रूप से गैर-वानिकी प्रयोजन मानता है। वनों के संरक्षण और प्रबंधन के कार्य, जैसे अग्नि रेखाएँ, जाँच चौकियाँ और बाड़, इससे बाहर हैं।"},
  {"id":"env-ecology-784","question":"The 2023 amendment to the Forest (Conservation) Act, 1980 exempts from its approval requirement, among other things, forest land needed for strategic linear projects of national importance located within:","options":["100 km of India's international borders, the LoC or the Line of Actual Control","10 km on either side of any national highway or railway line through the forest","50 km of the coastline, for new ports, jetties and coastal security roads","25 km of the boundary of any protected area, for its patrolling roads"],"answer":0,"explanation":"The amendment exempts land within 100 km of the borders, LoC or LAC for strategic linear projects, and up to 10 hectares for security-related infrastructure, among other exemptions; critics argued these could fragment border forests in the north-east and Himalaya.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"वन (संरक्षण) अधिनियम, 1980 का 2023 का संशोधन अपनी अनुमति की आवश्यकता से अन्य बातों के साथ उस वन भूमि को छूट देता है जो राष्ट्रीय महत्त्व की रणनीतिक रैखिक परियोजनाओं के लिए आवश्यक हो और जो स्थित हो:","optionsHi":["भारत की अंतर्राष्ट्रीय सीमाओं, LoC या वास्तविक नियंत्रण रेखा से 100 km के भीतर","वन से गुज़रने वाले किसी भी राष्ट्रीय राजमार्ग या रेल लाइन के दोनों ओर 10 km के भीतर","नए बंदरगाहों, जेटियों और तटीय सुरक्षा सड़कों के लिए तटरेखा से 50 km के भीतर","किसी संरक्षित क्षेत्र की सीमा से 25 km के भीतर, उसकी गश्ती सड़कों के लिए"],"explanationHi":"संशोधन रणनीतिक रैखिक परियोजनाओं के लिए सीमाओं, LoC या LAC से 100 km के भीतर की भूमि को, और सुरक्षा-संबंधी अवसंरचना के लिए 10 हेक्टेयर तक, अन्य छूटों के साथ, मुक्त करता है; आलोचकों ने कहा कि इनसे पूर्वोत्तर और हिमालय के सीमावर्ती वन खंडित हो सकते हैं।"},
  {"id":"env-ecology-785","question":"When forest land is diverted for a project, compensatory afforestation is normally to be carried out on:","options":["An equal area of degraded forest land, anywhere in the country","Equal non-forest land, or twice the area of degraded forest land","Non-forest land five times the area diverted, within the same district","Any land at all, of an area decided freely by the user agency itself"],"answer":1,"explanation":"The rules require equivalent non-forest land, or double the area on degraded forest land where non-forest land is not available. The user agency also pays the net present value of the forest lost into the CAMPA fund.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जब किसी परियोजना के लिए वन भूमि का उपयोग बदला जाता है, तो प्रतिपूरक वनीकरण सामान्यतः कहाँ किया जाना होता है?","optionsHi":["देश में कहीं भी निम्नीकृत वन भूमि के समान क्षेत्र पर","समान गैर-वन भूमि पर, या निम्नीकृत वन भूमि के दोगुने क्षेत्र पर","उसी ज़िले के भीतर परिवर्तित क्षेत्र से पाँच गुना गैर-वन भूमि पर","किसी भी भूमि पर, ऐसे क्षेत्रफल के साथ जिसे उपयोगकर्ता एजेंसी स्वयं स्वतंत्र रूप से तय करे"],"explanationHi":"नियम समतुल्य गैर-वन भूमि, या जहाँ गैर-वन भूमि उपलब्ध न हो वहाँ निम्नीकृत वन भूमि पर दोगुना क्षेत्र अपेक्षित करते हैं। उपयोगकर्ता एजेंसी खोए वन का शुद्ध वर्तमान मूल्य भी CAMPA कोष में देती है।"},
  {"id":"env-ecology-786","question":"Under the Coastal Regulation Zone Notification, 2019, in densely populated rural coastal areas classified as CRZ-III A, the 'No Development Zone' extends from the high tide line up to:","options":["500 metres","200 metres","100 metres","50 metres"],"answer":3,"explanation":"The 2019 notification cut the NDZ to 50 m in CRZ-III A areas, those with a population density above 2,161 per sq km in the 2011 census. In less densely populated CRZ-III B areas the NDZ remains 200 m; 500 m is the outer limit of the CRZ on the sea front.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"तटीय विनियमन क्षेत्र अधिसूचना, 2019 के अंतर्गत CRZ-III A के रूप में वर्गीकृत घनी आबादी वाले ग्रामीण तटीय क्षेत्रों में 'विकास रहित क्षेत्र' उच्च ज्वार रेखा से कितनी दूरी तक विस्तृत है?","optionsHi":["500 मीटर","200 मीटर","100 मीटर","50 मीटर"],"explanationHi":"2019 की अधिसूचना ने CRZ-III A क्षेत्रों में, जिनका 2011 की जनगणना में जनसंख्या घनत्व 2,161 प्रति वर्ग किमी से अधिक है, NDZ को घटाकर 50 m कर दिया। कम घनी आबादी वाले CRZ-III B क्षेत्रों में NDZ 200 m ही रहता है; 500 m समुद्र की ओर CRZ की बाह्य सीमा है।"},
  {"id":"env-ecology-787","question":"Under the Forest Rights Act, 2006, recognition of an individual's right to forest land under occupation for habitation or self-cultivation is subject to which of the following limits?","options":["Only land under actual occupation, and not more than 4 hectares","Any area the claimant names, subject only to approval by the Gram Sabha","Not more than 1 hectare, irrespective of the area actually occupied","Not more than 10 hectares, provided the land was cultivated after 2010"],"answer":0,"explanation":"Rights are limited to the area actually occupied, with a ceiling of 4 hectares, and the land must have been occupied before the cut-off date of 13 December 2005. The Gram Sabha starts the process, but committees at sub-division and district level decide.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"वन अधिकार अधिनियम, 2006 के अंतर्गत निवास या स्व-कृषि के लिए अधिभोग में रखी वन भूमि पर किसी व्यक्ति के अधिकार की मान्यता निम्नलिखित में से किस सीमा के अधीन है?","optionsHi":["केवल वास्तविक अधिभोग वाली भूमि, और 4 हेक्टेयर से अधिक नहीं","दावेदार द्वारा बताया गया कोई भी क्षेत्र, केवल ग्राम सभा की अनुमति के अधीन","1 हेक्टेयर से अधिक नहीं, वास्तविक अधिभोग वाले क्षेत्र की परवाह किए बिना","10 हेक्टेयर से अधिक नहीं, बशर्ते भूमि पर 2010 के बाद खेती की गई हो"],"explanationHi":"अधिकार वास्तव में अधिभोग वाले क्षेत्र तक, 4 हेक्टेयर की सीमा के साथ, सीमित हैं, और भूमि पर 13 दिसंबर 2005 की कट-ऑफ तिथि से पहले अधिभोग होना चाहिए। प्रक्रिया ग्राम सभा आरंभ करती है, पर निर्णय उप-खंड और ज़िला स्तर की समितियाँ करती हैं।"},
  {"id":"env-ecology-788","question":"The Panchayats (Extension to the Scheduled Areas) Act, 1996 (PESA) gives Gram Sabhas and panchayats in Scheduled Areas:","options":["Ownership of minor forest produce","Power to grant environmental clearance to mining projects","Power to notify national parks and sanctuaries","Ownership of all reserved forests in the area"],"answer":0,"explanation":"PESA vests ownership of minor forest produce in panchayats at the appropriate level and requires consultation with Gram Sabhas before land acquisition. Clearances and notification of protected areas remain with governments; reserved forests stay state property.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पंचायत (अनुसूचित क्षेत्रों पर विस्तार) अधिनियम, 1996 (PESA) अनुसूचित क्षेत्रों में ग्राम सभाओं और पंचायतों को क्या देता है?","optionsHi":["लघु वन उपज का स्वामित्व","खनन परियोजनाओं को पर्यावरणीय मंज़ूरी देने की शक्ति","राष्ट्रीय उद्यानों और अभयारण्यों को अधिसूचित करने की शक्ति","क्षेत्र के सभी आरक्षित वनों का स्वामित्व"],"explanationHi":"PESA लघु वन उपज का स्वामित्व उपयुक्त स्तर की पंचायतों में निहित करता है और भूमि अधिग्रहण से पहले ग्राम सभाओं से परामर्श आवश्यक करता है। मंज़ूरियाँ और संरक्षित क्षेत्रों की अधिसूचना सरकारों के पास रहती हैं; आरक्षित वन राज्य की संपत्ति रहते हैं।"},
  {"id":"env-ecology-789","question":"Arrange the following in chronological order: 1. Creation of the Department of Environment in the Government of India 2. Creation of the Ministry of Environment and Forests 3. Enactment of the Environment (Protection) Act 4. Setting up of the National Green Tribunal","options":["2-1-3-4","1-3-2-4","1-2-3-4","2-3-1-4"],"answer":2,"explanation":"The Department of Environment came in 1980, the Ministry of Environment and Forests in 1985, the EP Act in 1986 and the NGT in 2010. 'Climate Change' was added to the Ministry's name in 2014.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित को कालानुक्रमिक क्रम में व्यवस्थित कीजिए: 1. भारत सरकार में पर्यावरण विभाग की रचना 2. पर्यावरण और वन मंत्रालय की रचना 3. पर्यावरण (संरक्षण) अधिनियम का अधिनियमन 4. राष्ट्रीय हरित अधिकरण की स्थापना","optionsHi":["2-1-3-4","1-3-2-4","1-2-3-4","2-3-1-4"],"explanationHi":"पर्यावरण विभाग 1980 में आया, पर्यावरण और वन मंत्रालय 1985 में, EP अधिनियम 1986 में और NGT 2010 में। मंत्रालय के नाम में 2014 में 'जलवायु परिवर्तन' जोड़ा गया।"},
  {"id":"env-ecology-790","question":"Consider the following statements about the National Board for Wildlife: 1. It is a statutory body constituted under the Wild Life (Protection) Act, 1972. 2. It is chaired by the Prime Minister. 3. Its Standing Committee, which examines projects in and around protected areas, is chaired by the Union Minister for Environment. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Section 5A, added in 2002, creates the NBWL under the Prime Minister. In practice most project clearances in protected areas and eco-sensitive zones are given by its Standing Committee, headed by the Environment Minister as vice-chairperson.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"राष्ट्रीय वन्यजीव बोर्ड के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत गठित एक सांविधिक निकाय है। 2. इसके अध्यक्ष प्रधानमंत्री हैं। 3. संरक्षित क्षेत्रों के भीतर और आसपास की परियोजनाओं की जाँच करने वाली इसकी स्थायी समिति के अध्यक्ष केंद्रीय पर्यावरण मंत्री हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"2002 में जोड़ी गई धारा 5A प्रधानमंत्री के अधीन NBWL बनाती है। व्यवहार में संरक्षित क्षेत्रों और पारिस्थितिक संवेदनशील क्षेत्रों में अधिकांश परियोजना मंज़ूरियाँ उसकी स्थायी समिति देती है, जिसके उपाध्यक्ष के रूप में पर्यावरण मंत्री प्रमुख होते हैं।"},
  {"id":"env-ecology-791","question":"The Animal Welfare Board of India is a statutory advisory body established under:","options":["The Wild Life (Protection) Act, 1972","The Environment (Protection) Act, 1986","The Societies Registration Act, 1860","The Prevention of Cruelty to Animals Act, 1960"],"answer":3,"explanation":"AWBI was set up in 1962 under Section 4 of the PCA Act, 1960, and advises on animal welfare laws, a role prominent in matters such as jallikattu. The WPA deals with wild animals and their habitats.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भारतीय जीव-जंतु कल्याण बोर्ड किसके अंतर्गत स्थापित एक सांविधिक सलाहकार निकाय है?","optionsHi":["वन्यजीव (संरक्षण) अधिनियम, 1972","पर्यावरण (संरक्षण) अधिनियम, 1986","सोसायटी पंजीकरण अधिनियम, 1860","पशु क्रूरता निवारण अधिनियम, 1960"],"explanationHi":"AWBI की स्थापना 1962 में PCA अधिनियम, 1960 की धारा 4 के अंतर्गत हुई, और वह पशु कल्याण कानूनों पर सलाह देता है, जो जल्लीकट्टू जैसे मामलों में प्रमुख रहा है। WPA वन्य जंतुओं और उनके आवासों से संबंधित है।"},
  {"id":"env-ecology-792","question":"In 2010, the Government of India declared which animal as the 'National Heritage Animal'?","options":["Asian elephant","Bengal tiger","Ganges river dolphin","Great one-horned rhinoceros"],"answer":0,"explanation":"The elephant was declared National Heritage Animal in 2010 on the recommendation of an elephant task force. The tiger is the National Animal, and the Ganges river dolphin the National Aquatic Animal.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"2010 में भारत सरकार ने किस जंतु को 'राष्ट्रीय विरासत पशु' घोषित किया?","optionsHi":["एशियाई हाथी","बंगाल टाइगर","गंगा नदी डॉल्फ़िन","एक सींग वाला बड़ा गैंडा"],"explanationHi":"हाथी को 2010 में एक हाथी कार्य बल की सिफ़ारिश पर राष्ट्रीय विरासत पशु घोषित किया गया। बाघ राष्ट्रीय पशु है, और गंगा नदी डॉल्फ़िन राष्ट्रीय जलीय पशु।"},
  {"id":"env-ecology-793","question":"The 'polluter pays' principle was applied by the Supreme Court to make chemical units pay for remedying soil and groundwater contamination by sludge at Bichhri village, Rajasthan, in:","options":["M.C. Mehta v. Union of India (oleum gas leak case)","Vellore Citizens' Welfare Forum v. Union of India","Indian Council for Enviro-Legal Action v. Union of India","Rural Litigation and Entitlement Kendra v. State of U.P."],"answer":2,"explanation":"In Indian Council for Enviro-Legal Action (1996), units making H-acid were held absolutely liable to pay for remediation of Bichhri. Vellore Citizens' (1996) later declared polluter pays and precaution part of Indian law, and the oleum case set absolute liability.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"राजस्थान के बिछड़ी गाँव में अवपंक से मृदा और भूजल के संदूषण के उपचार के लिए रासायनिक इकाइयों से भुगतान कराने हेतु उच्चतम न्यायालय ने 'प्रदूषक भुगतान करे' सिद्धांत किस मामले में लागू किया?","optionsHi":["एम.सी. मेहता बनाम भारत संघ (ओलियम गैस रिसाव मामला)","वेल्लोर नागरिक कल्याण मंच बनाम भारत संघ","इंडियन काउंसिल फॉर एन्वायरो-लीगल एक्शन बनाम भारत संघ","रूरल लिटिगेशन एंड एंटाइटलमेंट केंद्र बनाम उत्तर प्रदेश राज्य"],"explanationHi":"इंडियन काउंसिल फॉर एन्वायरो-लीगल एक्शन (1996) में H-एसिड बनाने वाली इकाइयों को बिछड़ी के उपचार के लिए भुगतान हेतु पूर्णतः उत्तरदायी ठहराया गया। वेल्लोर नागरिक (1996) ने बाद में प्रदूषक भुगतान करे और पूर्व-सावधानी को भारतीय कानून का हिस्सा घोषित किया, और ओलियम मामले ने पूर्ण दायित्व स्थापित किया।"},
  {"id":"env-ecology-794","question":"The case of Rural Litigation and Entitlement Kendra v. State of Uttar Pradesh, decided in the mid-1980s, is known for the Supreme Court's order to:","options":["Shift tanneries away from the Ganga at Kanpur","Close limestone quarries in the Doon Valley","Convert Delhi's public transport fleet to compressed natural gas","Relocate industries away from the Taj Mahal"],"answer":1,"explanation":"Acting on a letter treated as a writ petition, the Court ordered the closure of most limestone quarries in the Dehradun valley, one of the earliest cases balancing development and ecology. The other orders came in M.C. Mehta's separate cases.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1980 के दशक के मध्य में तय हुआ रूरल लिटिगेशन एंड एंटाइटलमेंट केंद्र बनाम उत्तर प्रदेश राज्य मामला उच्चतम न्यायालय के किस आदेश के लिए जाना जाता है?","optionsHi":["कानपुर में चर्मशोधन कारखानों को गंगा से दूर ले जाना","दून घाटी की चूना पत्थर खदानों को बंद करना","दिल्ली के सार्वजनिक परिवहन बेड़े को संपीड़ित प्राकृतिक गैस पर परिवर्तित करना","उद्योगों को ताजमहल से दूर स्थानांतरित करना"],"explanationHi":"एक पत्र को रिट याचिका मानकर कार्रवाई करते हुए न्यायालय ने देहरादून घाटी की अधिकांश चूना पत्थर खदानों को बंद करने का आदेश दिया, जो विकास और पारिस्थितिकी में संतुलन बैठाने वाले सबसे प्रारंभिक मामलों में से एक था। अन्य आदेश एम.सी. मेहता के अलग मामलों में आए।"},
  {"id":"env-ecology-795","question":"In the Niyamgiri case (2013) concerning bauxite mining in Odisha, the Supreme Court directed that:","options":["Mining should go ahead, with compensation paid to affected tribal families","The Central Government alone should decide, as the hills were reserved forest","The National Green Tribunal should hear the matter afresh within six months","The local Gram Sabhas should decide whether their rights were affected"],"answer":3,"explanation":"Relying on the Forest Rights Act, the Court held that the Dongria Kondh Gram Sabhas must decide whether mining would affect their religious and cultural rights; all the Gram Sabhas consulted rejected the project.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ओडिशा में बॉक्साइट खनन से संबंधित नियमगिरि मामले (2013) में उच्चतम न्यायालय ने निर्देश दिया कि:","optionsHi":["खनन आगे बढ़ना चाहिए, प्रभावित आदिवासी परिवारों को मुआवज़ा दिया जाए","केवल केंद्र सरकार निर्णय करे, क्योंकि पहाड़ियाँ आरक्षित वन थीं","राष्ट्रीय हरित अधिकरण छह महीने के भीतर मामले की नए सिरे से सुनवाई करे","स्थानीय ग्राम सभाएँ तय करें कि उनके अधिकार प्रभावित हुए या नहीं"],"explanationHi":"वन अधिकार अधिनियम पर भरोसा करते हुए न्यायालय ने कहा कि डोंगरिया कोंध ग्राम सभाओं को तय करना चाहिए कि खनन उनके धार्मिक और सांस्कृतिक अधिकारों को प्रभावित करेगा या नहीं; परामर्श की गई सभी ग्राम सभाओं ने परियोजना को अस्वीकार कर दिया।"},
  {"id":"env-ecology-796","question":"The National Green Tribunal, set up in 2010, replaced which earlier body that heard appeals against environmental clearances?","options":["The National Environment Appellate Authority","The Central Empowered Committee","The Environment Pollution (Prevention and Control) Authority","The Central Pollution Control Board's appellate wing"],"answer":0,"explanation":"The NGT Act repealed the National Environment Appellate Authority Act, 1997. The Central Empowered Committee is a Supreme Court-appointed body on forest matters, and EPCA was a Delhi-NCR pollution authority later replaced by CAQM.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2010 में स्थापित राष्ट्रीय हरित अधिकरण ने किस पूर्ववर्ती निकाय का स्थान लिया जो पर्यावरणीय मंज़ूरियों के विरुद्ध अपीलें सुनता था?","optionsHi":["राष्ट्रीय पर्यावरण अपीलीय प्राधिकरण","केंद्रीय अधिकार प्राप्त समिति","पर्यावरण प्रदूषण (निवारण और नियंत्रण) प्राधिकरण","केंद्रीय प्रदूषण नियंत्रण बोर्ड की अपीलीय शाखा"],"explanationHi":"NGT अधिनियम ने राष्ट्रीय पर्यावरण अपीलीय प्राधिकरण अधिनियम, 1997 को निरस्त किया। केंद्रीय अधिकार प्राप्त समिति वन मामलों पर उच्चतम न्यायालय द्वारा नियुक्त निकाय है, और EPCA दिल्ली-NCR का प्रदूषण प्राधिकरण था जिसका स्थान बाद में CAQM ने लिया।"},
  {"id":"env-ecology-797","question":"The 'Ecomark' scheme, launched in India in 1991 to label environment-friendly consumer products, is administered by:","options":["The Central Pollution Control Board","The Bureau of Energy Efficiency","The Bureau of Indian Standards","The Indian Council of Agricultural Research"],"answer":2,"explanation":"Ecomark products must meet BIS quality standards plus environmental criteria; the label is an earthen pot. BEE runs the separate star-labelling programme for energy efficiency.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"पर्यावरण-अनुकूल उपभोक्ता उत्पादों पर लेबल लगाने के लिए 1991 में भारत में शुरू की गई 'इकोमार्क' योजना किसके द्वारा प्रशासित है?","optionsHi":["केंद्रीय प्रदूषण नियंत्रण बोर्ड","ऊर्जा दक्षता ब्यूरो","भारतीय मानक ब्यूरो","भारतीय कृषि अनुसंधान परिषद"],"explanationHi":"इकोमार्क उत्पादों को BIS गुणवत्ता मानकों के साथ पर्यावरणीय मानदंड पूरे करने होते हैं; लेबल मिट्टी का घड़ा है। BEE ऊर्जा दक्षता के लिए अलग स्टार-लेबलिंग कार्यक्रम चलाता है।"},
  {"id":"env-ecology-798","question":"'Urban forestry, protection of the environment and promotion of ecological aspects' is listed as a function of municipalities in the:","options":["Seventh Schedule","Eleventh Schedule","Tenth Schedule","Twelfth Schedule"],"answer":3,"explanation":"The Twelfth Schedule (Article 243W), added by the 74th Amendment, lists it for municipalities. The Eleventh Schedule for panchayats lists social forestry, farm forestry and minor forest produce instead.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"'नगरीय वानिकी, पर्यावरण का संरक्षण और पारिस्थितिक पहलुओं का संवर्धन' किसमें नगरपालिकाओं के एक कार्य के रूप में सूचीबद्ध है?","optionsHi":["सातवीं अनुसूची","ग्यारहवीं अनुसूची","दसवीं अनुसूची","बारहवीं अनुसूची"],"explanationHi":"बारहवीं अनुसूची (अनुच्छेद 243W), जो 74वें संशोधन द्वारा जोड़ी गई, इसे नगरपालिकाओं के लिए सूचीबद्ध करती है। पंचायतों के लिए ग्यारहवीं अनुसूची के बजाय सामाजिक वानिकी, कृषि वानिकी और लघु वन उपज सूचीबद्ध करती है।"},
  {"id":"env-ecology-799","question":"Where an eco-sensitive zone has not yet been notified around a national park or sanctuary, the Supreme Court and Central guidelines have applied a default buffer of:","options":["1 km from the boundary","5 km from the boundary","10 km from the boundary","25 km from the boundary"],"answer":2,"explanation":"Following a National Board for Wildlife decision of 2002 and the Goa Foundation case, a 10 km belt was treated as the ESZ until site-specific zones were notified under the EP Act. Notified zones can be narrower or wider depending on the site.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जहाँ किसी राष्ट्रीय उद्यान या अभयारण्य के आसपास पारिस्थितिक संवेदनशील क्षेत्र अभी तक अधिसूचित नहीं हुआ है, वहाँ उच्चतम न्यायालय और केंद्रीय दिशानिर्देशों ने कितना डिफ़ॉल्ट बफ़र लागू किया है?","optionsHi":["सीमा से 1 km","सीमा से 5 km","सीमा से 10 km","सीमा से 25 km"],"explanationHi":"2002 के राष्ट्रीय वन्यजीव बोर्ड के निर्णय और गोवा फ़ाउंडेशन मामले के बाद, EP अधिनियम के अंतर्गत स्थल-विशिष्ट क्षेत्र अधिसूचित होने तक 10 km की पट्टी को ESZ माना गया। अधिसूचित क्षेत्र स्थल के अनुसार संकरे या चौड़े हो सकते हैं।"},
  {"id":"env-ecology-800","question":"India's Ozone Depleting Substances (Regulation and Control) Rules, 2000, which give effect to the Montreal Protocol, were framed under:","options":["The Air (Prevention and Control of Pollution) Act, 1981","The Environment (Protection) Act, 1986","The Factories Act, 1948","The Insecticides Act, 1968"],"answer":1,"explanation":"Most environmental rules in India, including those on ODS, hazardous waste, plastic and e-waste, are framed under the umbrella EP Act, 1986. They regulate production, trade and use of CFCs, halons and HCFCs.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"मॉन्ट्रियल प्रोटोकॉल को प्रभावी बनाने वाले भारत के ओज़ोन क्षयकारी पदार्थ (विनियमन और नियंत्रण) नियम, 2000 किसके अंतर्गत बनाए गए?","optionsHi":["वायु (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1981","पर्यावरण (संरक्षण) अधिनियम, 1986","कारखाना अधिनियम, 1948","कीटनाशक अधिनियम, 1968"],"explanationHi":"भारत में अधिकांश पर्यावरणीय नियम, जिनमें ODS, खतरनाक अपशिष्ट, प्लास्टिक और ई-अपशिष्ट पर नियम शामिल हैं, छत्र EP अधिनियम, 1986 के अंतर्गत बनाए जाते हैं। वे CFC, हैलॉन और HCFC के उत्पादन, व्यापार और उपयोग को विनियमित करते हैं।"},
  {"id":"env-ecology-801","question":"Consider the following statements about conservation reserves and community reserves: 1. Both categories were added to the Wildlife (Protection) Act, 1972 by an amendment in 2002. 2. A community reserve may be declared on community or private land where the community or individual has volunteered to conserve wildlife. 3. A conservation reserve is declared on land owned by the State Government, especially land adjacent to national parks and sanctuaries or linking them. How many of the statements given above are correct?","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are correct. These categories, from the 2002 amendment, give communities and governments flexible ways to protect corridors and landscapes outside national parks and sanctuaries.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"संरक्षण रिज़र्व और सामुदायिक रिज़र्व के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. दोनों श्रेणियाँ 2002 के संशोधन द्वारा वन्यजीव (संरक्षण) अधिनियम, 1972 में जोड़ी गईं। 2. सामुदायिक रिज़र्व ऐसी सामुदायिक या निजी भूमि पर घोषित किया जा सकता है जहाँ समुदाय या व्यक्ति ने वन्यजीव संरक्षण के लिए स्वेच्छा से प्रस्ताव किया हो। 3. संरक्षण रिज़र्व राज्य सरकार के स्वामित्व वाली भूमि पर घोषित किया जाता है, विशेषकर राष्ट्रीय उद्यानों और अभयारण्यों से सटी या उन्हें जोड़ने वाली भूमि पर। उपर्युक्त कथनों में से कितने सही हैं?","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"तीनों सही हैं। 2002 के संशोधन से आई ये श्रेणियाँ समुदायों और सरकारों को राष्ट्रीय उद्यानों और अभयारण्यों के बाहर गलियारों और भूदृश्यों की रक्षा के लचीले तरीके देती हैं।"},
  {"id":"env-ecology-802","question":"India's first marine national park, declared in the early 1980s to protect coral reefs and mangroves off Jamnagar, is in the:","options":["Gulf of Mannar, Tamil Nadu","Wandoor area, South Andaman","Malvan coast, Maharashtra","Gulf of Kutch, Gujarat"],"answer":3,"explanation":"The Marine National Park in the Gulf of Kutch was the first. The Mahatma Gandhi Marine National Park at Wandoor came in 1983 and the Gulf of Mannar Marine National Park in 1986.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जामनगर के तट पर प्रवाल भित्तियों और मैंग्रोव की रक्षा के लिए 1980 के दशक के आरंभ में घोषित भारत का पहला समुद्री राष्ट्रीय उद्यान कहाँ है?","optionsHi":["मन्नार की खाड़ी, तमिलनाडु","वंडूर क्षेत्र, दक्षिण अंडमान","मालवण तट, महाराष्ट्र","कच्छ की खाड़ी, गुजरात"],"explanationHi":"कच्छ की खाड़ी का समुद्री राष्ट्रीय उद्यान पहला था। वंडूर का महात्मा गांधी समुद्री राष्ट्रीय उद्यान 1983 में और मन्नार की खाड़ी समुद्री राष्ट्रीय उद्यान 1986 में आया।"},
  {"id":"env-ecology-803","question":"The first marine biosphere reserve in South and South-East Asia, set up in 1989, is the:","options":["Great Nicobar Biosphere Reserve","Sundarbans Biosphere Reserve","Gulf of Mannar Biosphere Reserve","Agasthyamala Biosphere Reserve"],"answer":2,"explanation":"The Gulf of Mannar reserve, between India and Sri Lanka, protects coral islands, seagrass beds and the dugong. The Sundarbans reserve centres on mangroves rather than open sea.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"1989 में स्थापित, दक्षिण और दक्षिण-पूर्व एशिया का पहला समुद्री जैवमंडल आरक्षित क्षेत्र कौन-सा है?","optionsHi":["ग्रेट निकोबार जैवमंडल आरक्षित क्षेत्र","सुंदरबन जैवमंडल आरक्षित क्षेत्र","मन्नार की खाड़ी जैवमंडल आरक्षित क्षेत्र","अगस्त्यमलाई जैवमंडल आरक्षित क्षेत्र"],"explanationHi":"भारत और श्रीलंका के बीच मन्नार की खाड़ी का आरक्षित क्षेत्र प्रवाल द्वीपों, समुद्री घास की शय्याओं और डुगोंग की रक्षा करता है। सुंदरबन आरक्षित क्षेत्र खुले समुद्र के बजाय मैंग्रोव पर केंद्रित है।"},
  {"id":"env-ecology-804","question":"Which one of the following Indian biosphere reserves has been included in UNESCO's World Network of Biosphere Reserves?","options":["Manas","Panna","Kachchh","Cold Desert"],"answer":1,"explanation":"Panna was added to the world network in 2020, joining eleven other Indian reserves such as Nilgiri and Sundarbans. Manas, Kachchh and Cold Desert are national biosphere reserves not on the UNESCO list.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-सा भारतीय जैवमंडल आरक्षित क्षेत्र UNESCO के जैवमंडल आरक्षित क्षेत्रों के विश्व नेटवर्क में शामिल किया गया है?","optionsHi":["मानस","पन्ना","कच्छ","शीत मरुस्थल"],"explanationHi":"पन्ना को 2020 में विश्व नेटवर्क में जोड़ा गया, जो नीलगिरि और सुंदरबन जैसे ग्यारह अन्य भारतीय आरक्षित क्षेत्रों में शामिल हुआ। मानस, कच्छ और शीत मरुस्थल राष्ट्रीय जैवमंडल आरक्षित क्षेत्र हैं जो UNESCO सूची में नहीं हैं।"},
  {"id":"env-ecology-805","question":"The largest biosphere reserve in India by area is:","options":["Great Nicobar","Gulf of Mannar","Nilgiri","Kachchh"],"answer":3,"explanation":"The Kachchh Biosphere Reserve, covering much of the Great Rann, exceeds 12,000 km². Nilgiri was the first, not the largest.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"क्षेत्रफल की दृष्टि से भारत का सबसे बड़ा जैवमंडल आरक्षित क्षेत्र है:","optionsHi":["ग्रेट निकोबार","मन्नार की खाड़ी","नीलगिरि","कच्छ"],"explanationHi":"कच्छ जैवमंडल आरक्षित क्षेत्र, जो ग्रेट रण के बड़े भाग को शामिल करता है, 12,000 km² से अधिक है। नीलगिरि पहला था, सबसे बड़ा नहीं।"},
  {"id":"env-ecology-806","question":"Consider the following statements about tiger reserves under the Wildlife (Protection) Act, 1972: 1. A tiger reserve consists of a core or critical tiger habitat and a buffer or peripheral area. 2. The buffer area is meant to promote coexistence between wildlife and human activity, with due recognition of local livelihood rights. 3. A State Government can alter the boundaries of a tiger reserve on its own, without any recommendation from the National Tiger Conservation Authority. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Boundaries of a tiger reserve can be altered only in the public interest, on the NTCA's recommendation and with the approval of the National Board for Wildlife, so statement 3 is wrong.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"वन्यजीव (संरक्षण) अधिनियम, 1972 के अंतर्गत बाघ अभयारण्यों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. बाघ अभयारण्य में एक क्रोड या क्रांतिक बाघ आवास और एक बफ़र या परिधीय क्षेत्र होता है। 2. बफ़र क्षेत्र का उद्देश्य स्थानीय आजीविका अधिकारों की उचित मान्यता के साथ वन्यजीव और मानवीय गतिविधि के बीच सह-अस्तित्व को बढ़ावा देना है। 3. राज्य सरकार राष्ट्रीय बाघ संरक्षण प्राधिकरण की किसी सिफ़ारिश के बिना स्वयं बाघ अभयारण्य की सीमाएँ बदल सकती है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"बाघ अभयारण्य की सीमाएँ केवल लोकहित में, NTCA की सिफ़ारिश पर और राष्ट्रीय वन्यजीव बोर्ड की अनुमति से बदली जा सकती हैं, इसलिए कथन 3 गलत है।"},
  {"id":"env-ecology-807","question":"Consider the following statements: 1. Elephant reserves are a legal category of protected area defined in the Wildlife (Protection) Act, 1972. 2. Elephant reserves often include national parks and sanctuaries along with reserved forests and other land. Which of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"Elephant reserves are administrative units under Project Elephant, notified by states, not a statutory protected-area category. They span existing protected areas and other forests used by elephants.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. हाथी अभयारण्य वन्यजीव (संरक्षण) अधिनियम, 1972 में परिभाषित संरक्षित क्षेत्र की एक विधिक श्रेणी हैं। 2. हाथी अभयारण्यों में प्रायः आरक्षित वनों और अन्य भूमि के साथ राष्ट्रीय उद्यान और अभयारण्य भी शामिल होते हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"हाथी अभयारण्य प्रोजेक्ट एलीफ़ेंट के अंतर्गत राज्यों द्वारा अधिसूचित प्रशासनिक इकाइयाँ हैं, सांविधिक संरक्षित क्षेत्र श्रेणी नहीं। वे मौजूदा संरक्षित क्षेत्रों और हाथियों द्वारा प्रयुक्त अन्य वनों में फैले होते हैं।"},
  {"id":"env-ecology-808","question":"The largest surviving population of the Nilgiri tahr is protected in:","options":["Eravikulam National Park, Kerala","Bandipur National Park, Karnataka","Mukurthi National Park, Tamil Nadu","Silent Valley National Park, Kerala"],"answer":0,"explanation":"Eravikulam, on the high grassland plateau near Munnar, holds the largest tahr population. Mukurthi also protects tahr but in smaller numbers; Bandipur lies in lower dry forests.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"नीलगिरि तहर की सबसे बड़ी जीवित समष्टि किस में संरक्षित है?","optionsHi":["इरविकुलम राष्ट्रीय उद्यान, केरल","बांदीपुर राष्ट्रीय उद्यान, कर्नाटक","मुकुर्ती राष्ट्रीय उद्यान, तमिलनाडु","साइलेंट वैली राष्ट्रीय उद्यान, केरल"],"explanationHi":"मुन्नार के निकट उच्च घास के पठार पर स्थित इरविकुलम में तहर की सबसे बड़ी समष्टि है। मुकुर्ती भी तहर की रक्षा करता है पर कम संख्या में; बांदीपुर निचले शुष्क वनों में है।"},
  {"id":"env-ecology-809","question":"Hemis National Park, India's largest national park, is best known for protecting the:","options":["Hangul","Red panda","Snow leopard","Asiatic black bear"],"answer":2,"explanation":"Hemis in Ladakh is famous for its snow leopard population, along with bharal and Tibetan wolves. The hangul lives in Dachigam in Kashmir and the red panda in the eastern Himalaya.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत का सबसे बड़ा राष्ट्रीय उद्यान, हेमिस राष्ट्रीय उद्यान, किसकी रक्षा के लिए सबसे अधिक जाना जाता है?","optionsHi":["हंगुल","रेड पांडा","हिम तेंदुआ","एशियाई काला भालू"],"explanationHi":"लद्दाख का हेमिस अपनी हिम तेंदुआ समष्टि के लिए प्रसिद्ध है, साथ में भरल और तिब्बती भेड़िये भी। हंगुल कश्मीर के दाचीगाम में रहता है और रेड पांडा पूर्वी हिमालय में।"},
  {"id":"env-ecology-810","question":"Which national park in India is noted as a home to all four large cats of the region: tiger, common leopard, clouded leopard and snow leopard?","options":["Manas","Kaziranga","Namdapha","Dibru-Saikhowa"],"answer":2,"explanation":"Namdapha in Arunachal Pradesh spans altitudes from low tropical forest to high snow-clad peaks, so all four cats occur within it.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत का कौन-सा राष्ट्रीय उद्यान क्षेत्र की सभी चार बड़ी बिल्लियों का घर होने के लिए प्रसिद्ध है: बाघ, सामान्य तेंदुआ, क्लाउडेड तेंदुआ और हिम तेंदुआ?","optionsHi":["मानस","काज़ीरंगा","नामदफा","डिब्रू-साइखोवा"],"explanationHi":"अरुणाचल प्रदेश का नामदफा निम्न उष्णकटिबंधीय वन से लेकर ऊँची हिमाच्छादित चोटियों तक की ऊँचाइयों में फैला है, इसलिए चारों बिल्लियाँ उसमें पाई जाती हैं।"},
  {"id":"env-ecology-811","question":"The Hornbill Nest Adoption Programme, in which members of the Nyishi community are paid to protect nesting trees, is associated with:","options":["Pakke Tiger Reserve, Arunachal Pradesh","Dampa Tiger Reserve, Mizoram","Nagarhole National Park, Karnataka","Namdapha Tiger Reserve, Arunachal Pradesh"],"answer":0,"explanation":"Former Nyishi hunters now monitor and guard hornbill nests in and around Pakke; the scheme is a well-known model of community-based conservation. Namdapha, also in Arunachal, has hornbills but not this programme.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"धनेश घोंसला गोद लेने का कार्यक्रम, जिसमें न्यिशी समुदाय के सदस्यों को घोंसले वाले वृक्षों की रक्षा के लिए भुगतान किया जाता है, किससे जुड़ा है?","optionsHi":["पक्के बाघ अभयारण्य, अरुणाचल प्रदेश","दम्पा बाघ अभयारण्य, मिज़ोरम","नागरहोल राष्ट्रीय उद्यान, कर्नाटक","नामदफा बाघ अभयारण्य, अरुणाचल प्रदेश"],"explanationHi":"पूर्व न्यिशी शिकारी अब पक्के के भीतर और आसपास धनेश के घोंसलों की निगरानी और रखवाली करते हैं; यह योजना समुदाय-आधारित संरक्षण का प्रसिद्ध मॉडल है। नामदफा, जो अरुणाचल में ही है, में धनेश हैं पर यह कार्यक्रम नहीं।"},
  {"id":"env-ecology-812","question":"Because of its grasslands, wetlands and dense population of one-horned rhinoceros, which protected area on the north bank of the Brahmaputra is often called a 'mini Kaziranga'?","options":["Dibru-Saikhowa National Park","Rajiv Gandhi Orang National Park","Nameri National Park","Pobitora Wildlife Sanctuary"],"answer":1,"explanation":"Orang has a landscape and fauna much like Kaziranga's on a smaller scale. Pobitora, with the highest rhino density, lies south of the Brahmaputra.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अपने घास के मैदानों, आर्द्रभूमियों और एक सींग वाले गैंडों की घनी आबादी के कारण ब्रह्मपुत्र के उत्तरी तट का कौन-सा संरक्षित क्षेत्र प्रायः 'मिनी काज़ीरंगा' कहलाता है?","optionsHi":["डिब्रू-साइखोवा राष्ट्रीय उद्यान","राजीव गांधी ओरंग राष्ट्रीय उद्यान","नामेरी राष्ट्रीय उद्यान","पोबितोरा वन्यजीव अभयारण्य"],"explanationHi":"ओरंग का भूदृश्य और जीव-जंतु काज़ीरंगा जैसे ही हैं, पर छोटे पैमाने पर। सर्वाधिक गैंडा घनत्व वाला पोबितोरा ब्रह्मपुत्र के दक्षिण में है।"},
  {"id":"env-ecology-813","question":"A national park lying largely within the limits of a metropolitan city, known for its leopards and the ancient Kanheri caves, is:","options":["Guindy National Park","Bannerghatta National Park","Sanjay Gandhi National Park","Van Vihar National Park"],"answer":2,"explanation":"Sanjay Gandhi National Park at Borivali, Mumbai, holds a resident leopard population and the Buddhist Kanheri caves. Guindy in Chennai is far smaller and has no caves.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"एक राष्ट्रीय उद्यान जो मुख्यतः एक महानगर की सीमाओं के भीतर स्थित है, जो अपने तेंदुओं और प्राचीन कान्हेरी गुफाओं के लिए जाना जाता है, है:","optionsHi":["गिंडी राष्ट्रीय उद्यान","बन्नेरघट्टा राष्ट्रीय उद्यान","संजय गांधी राष्ट्रीय उद्यान","वन विहार राष्ट्रीय उद्यान"],"explanationHi":"मुंबई के बोरीवली में संजय गांधी राष्ट्रीय उद्यान में निवासी तेंदुआ समष्टि और बौद्ध कान्हेरी गुफाएँ हैं। चेन्नई का गिंडी कहीं छोटा है और उसमें गुफाएँ नहीं हैं।"},
  {"id":"env-ecology-814","question":"Which of the following protected areas form part of the Nilgiri Biosphere Reserve? 1. Mudumalai 2. Silent Valley 3. Bandipur 4. Periyar. Select the correct answer:","options":["1 and 3 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Mudumalai, Bandipur, Nagarhole, Wayanad, Mukurthi and Silent Valley lie in the Nilgiri Biosphere Reserve. Periyar is much further south, in the Cardamom Hills.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से कौन-से संरक्षित क्षेत्र नीलगिरि जैवमंडल आरक्षित क्षेत्र का भाग हैं? 1. मुदुमलई 2. साइलेंट वैली 3. बांदीपुर 4. पेरियार। सही उत्तर चुनिए:","optionsHi":["केवल 1 और 3","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"मुदुमलई, बांदीपुर, नागरहोल, वायनाड, मुकुर्ती और साइलेंट वैली नीलगिरि जैवमंडल आरक्षित क्षेत्र में स्थित हैं। पेरियार कहीं और दक्षिण में, इलायची की पहाड़ियों में है।"},
  {"id":"env-ecology-815","question":"The Harike wetland, a Ramsar site that hosts large numbers of wintering waterbirds, was formed by a barrage at the confluence of the:","options":["Ravi and Beas in Punjab","Sutlej and Ghaggar in Haryana","Yamuna and Hindon in Uttar Pradesh","Beas and Sutlej in Punjab"],"answer":3,"explanation":"The Harike headworks stand just below the meeting point of the Beas and Sutlej; the resulting reservoir is one of north India's largest wetlands.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हरिके आर्द्रभूमि, जो एक रामसर स्थल है और शीतकाल में बड़ी संख्या में जलपक्षियों की मेज़बानी करती है, किनके संगम पर बने बैराज से बनी थी?","optionsHi":["पंजाब में रावी और ब्यास","हरियाणा में सतलुज और घग्गर","उत्तर प्रदेश में यमुना और हिंडन","पंजाब में ब्यास और सतलुज"],"explanationHi":"हरिके हेडवर्क्स ब्यास और सतलुज के मिलन बिंदु के ठीक नीचे है; इससे बना जलाशय उत्तर भारत की सबसे बड़ी आर्द्रभूमियों में से एक है।"},
  {"id":"env-ecology-816","question":"Nalabana Bird Sanctuary, an island that is submerged during the monsoon and hosts huge numbers of wintering birds, lies within:","options":["Kolleru Lake","Pulicat Lake","Chilika Lake","Loktak Lake"],"answer":2,"explanation":"Nalabana lies in the middle of Chilika lagoon in Odisha. Kolleru (Andhra Pradesh), Pulicat (on the Andhra–Tamil Nadu border) and Loktak (Manipur) are other important wetlands.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"नलबन पक्षी अभयारण्य, एक द्वीप जो मानसून में जलमग्न हो जाता है और शीतकाल में बड़ी संख्या में पक्षियों की मेज़बानी करता है, किसके भीतर स्थित है?","optionsHi":["कोल्लेरु झील","पुलिकट झील","चिल्का झील","लोकटक झील"],"explanationHi":"नलबन ओडिशा की चिल्का लैगून के मध्य में है। कोल्लेरु (आंध्र प्रदेश), पुलिकट (आंध्र–तमिलनाडु सीमा पर) और लोकटक (मणिपुर) अन्य महत्त्वपूर्ण आर्द्रभूमियाँ हैं।"},
  {"id":"env-ecology-817","question":"Point Calimere (Kodiakkarai) Wildlife Sanctuary, a Ramsar site known for flamingos and blackbuck on a coastal plain, is in:","options":["Gujarat","Odisha","Andhra Pradesh","Tamil Nadu"],"answer":3,"explanation":"Point Calimere lies on the Coromandel coast in Nagapattinam district of Tamil Nadu, combining tropical dry evergreen forest, mudflats and salt swamps.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पॉइंट कैलिमियर (कोडियाक्कराई) वन्यजीव अभयारण्य, एक रामसर स्थल जो तटीय मैदान पर राजहंस (फ्लेमिंगो) और काले हिरण के लिए जाना जाता है, कहाँ है?","optionsHi":["गुजरात","ओडिशा","आंध्र प्रदेश","तमिलनाडु"],"explanationHi":"पॉइंट कैलिमियर तमिलनाडु के नागपट्टिनम ज़िले में कोरोमंडल तट पर स्थित है, जिसमें उष्णकटिबंधीय शुष्क सदाबहार वन, कीचड़ के मैदान और लवणीय दलदल मिलते हैं।"},
  {"id":"env-ecology-818","question":"Ranganathittu Bird Sanctuary, a group of islets that hosts colonies of nesting waterbirds, lies on the:","options":["Kaveri river in Karnataka","Godavari river in Andhra Pradesh","Krishna river in Telangana","Mahanadi river in Odisha"],"answer":0,"explanation":"Ranganathittu is on the Kaveri near Srirangapatna, Mysuru district. Its islets host painted storks, open-billed storks, spoonbills and mugger crocodiles.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"रंगनाथिट्टू पक्षी अभयारण्य, जो टापुओं का समूह है और घोंसले बनाने वाले जलपक्षियों की बस्तियों की मेज़बानी करता है, किस पर स्थित है?","optionsHi":["कर्नाटक में कावेरी नदी","आंध्र प्रदेश में गोदावरी नदी","तेलंगाना में कृष्णा नदी","ओडिशा में महानदी"],"explanationHi":"रंगनाथिट्टू मैसूरु ज़िले के श्रीरंगपट्टनम के निकट कावेरी पर है। उसके टापुओं पर पेंटेड स्टॉर्क, ओपन-बिल्ड स्टॉर्क, स्पूनबिल और मगर मगरमच्छ रहते हैं।"},
  {"id":"env-ecology-819","question":"In 1984, greater one-horned rhinoceroses were reintroduced from Assam and Nepal into which protected area, part of their former range?","options":["Corbett National Park","Valmiki Tiger Reserve","Dudhwa National Park","Jaldapara National Park"],"answer":2,"explanation":"Dudhwa in the Terai of Uttar Pradesh received rhinos in 1984, re-establishing the species where it had been extinct. Jaldapara has a surviving natural rhino population.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1984 में असम और नेपाल से एक सींग वाले बड़े गैंडों को, जो उनके पूर्व परास का हिस्सा था, किस संरक्षित क्षेत्र में पुनः लाया गया?","optionsHi":["कॉर्बेट राष्ट्रीय उद्यान","वाल्मीकि बाघ अभयारण्य","दुधवा राष्ट्रीय उद्यान","जलदापाड़ा राष्ट्रीय उद्यान"],"explanationHi":"उत्तर प्रदेश के तराई में दुधवा को 1984 में गैंडे मिले, जिससे वहाँ प्रजाति पुनः स्थापित हुई जहाँ वह विलुप्त हो चुकी थी। जलदापाड़ा में प्राकृतिक रूप से जीवित गैंडा समष्टि है।"},
  {"id":"env-ecology-820","question":"Match the tiger reserve with its state. A. Satpura  B. Melghat  C. Buxa  D. Kawal; 1. West Bengal  2. Telangana  3. Madhya Pradesh  4. Maharashtra","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Satpura is in Madhya Pradesh, Melghat in Maharashtra's Amravati district, Buxa in north Bengal and Kawal in Telangana.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"बाघ अभयारण्य का उसके राज्य से मिलान कीजिए। A. सतपुड़ा B. मेलघाट C. बक्सा D. कवाल; 1. पश्चिम बंगाल 2. तेलंगाना 3. मध्य प्रदेश 4. महाराष्ट्र","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"सतपुड़ा मध्य प्रदेश में है, मेलघाट महाराष्ट्र के अमरावती ज़िले में, बक्सा उत्तर बंगाल में और कवाल तेलंगाना में।"},
  {"id":"env-ecology-821","question":"Guindy National Park, one of the few national parks located inside a city, is in:","options":["Chennai","Bengaluru","Hyderabad","Kolkata"],"answer":0,"explanation":"Guindy, in Chennai, protects tropical dry evergreen scrub and a population of blackbuck and spotted deer. Bengaluru's Bannerghatta lies on the city's outskirts.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"गिंडी राष्ट्रीय उद्यान, जो किसी शहर के भीतर स्थित गिने-चुने राष्ट्रीय उद्यानों में से एक है, कहाँ है?","optionsHi":["चेन्नई","बेंगलुरु","हैदराबाद","कोलकाता"],"explanationHi":"चेन्नई का गिंडी उष्णकटिबंधीय शुष्क सदाबहार झाड़ी और काले हिरण तथा चित्तीदार हिरण की समष्टि की रक्षा करता है। बेंगलुरु का बन्नेरघट्टा शहर के बाहरी भाग में है।"},
  {"id":"env-ecology-822","question":"Sathyamangalam Tiger Reserve in Tamil Nadu is ecologically important mainly because it:","options":["Forms a link between the Western Ghats and the Eastern Ghats","Holds the only population of tigers living in mangroves in south India","Protects the largest surviving shola grassland of the Nilgiris","Is the southernmost point of the range of the Asiatic lion"],"answer":0,"explanation":"Sathyamangalam lies where the two ranges meet and connects the Nilgiri landscape with the Eastern Ghats, making it a key corridor for tigers and elephants.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"तमिलनाडु का सत्यमंगलम बाघ अभयारण्य पारिस्थितिक दृष्टि से मुख्यतः इसलिए महत्त्वपूर्ण है क्योंकि वह:","optionsHi":["पश्चिमी घाट और पूर्वी घाट के बीच कड़ी बनाता है","दक्षिण भारत में मैंग्रोव में रहने वाले बाघों की एकमात्र समष्टि रखता है","नीलगिरि के सबसे बड़े शेष शोला घास के मैदान की रक्षा करता है","एशियाई शेर के परास का सबसे दक्षिणी बिंदु है"],"explanationHi":"सत्यमंगलम वहाँ स्थित है जहाँ दोनों पर्वत श्रेणियाँ मिलती हैं और नीलगिरि भूदृश्य को पूर्वी घाट से जोड़ता है, जिससे वह बाघों और हाथियों के लिए प्रमुख गलियारा है।"},
  {"id":"env-ecology-823","question":"Coringa Wildlife Sanctuary, an important mangrove area in India, lies in the delta of the:","options":["Brahmani–Baitarani in Odisha","Godavari in Andhra Pradesh","Kaveri in Tamil Nadu","Krishna in Andhra Pradesh"],"answer":1,"explanation":"Coringa protects the mangroves of the Godavari delta near Kakinada; the Krishna delta's mangroves form the separate Krishna Wildlife Sanctuary, and Bhitarkanika covers the Brahmani–Baitarani delta of Odisha.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"कोरिंगा वन्यजीव अभयारण्य, भारत का एक महत्त्वपूर्ण मैंग्रोव क्षेत्र, किसके डेल्टा में स्थित है?","optionsHi":["ओडिशा में ब्राह्मणी–बैतरणी","आंध्र प्रदेश में गोदावरी","तमिलनाडु में कावेरी","आंध्र प्रदेश में कृष्णा"],"explanationHi":"कोरिंगा काकीनाडा के निकट गोदावरी डेल्टा के मैंग्रोव की रक्षा करता है; कृष्णा डेल्टा के मैंग्रोव अलग कृष्णा वन्यजीव अभयारण्य बनाते हैं, और भितरकनिका ओडिशा के ब्राह्मणी–बैतरणी डेल्टा को शामिल करता है।"},
  {"id":"env-ecology-824","question":"Campbell Bay National Park and Galathea National Park form core areas of which biosphere reserve?","options":["Great Nicobar","Gulf of Mannar","Sundarbans","Andaman Islands"],"answer":0,"explanation":"Both national parks lie on Great Nicobar island, the southernmost part of India, and form the core of the Great Nicobar Biosphere Reserve, which falls in the Sundaland hotspot.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कैंपबेल बे राष्ट्रीय उद्यान और गैलाथिया राष्ट्रीय उद्यान किस जैवमंडल आरक्षित क्षेत्र के क्रोड क्षेत्र हैं?","optionsHi":["ग्रेट निकोबार","मन्नार की खाड़ी","सुंदरबन","अंडमान द्वीप"],"explanationHi":"दोनों राष्ट्रीय उद्यान भारत के सबसे दक्षिणी भाग, ग्रेट निकोबार द्वीप पर हैं और ग्रेट निकोबार जैवमंडल आरक्षित क्षेत्र का क्रोड बनाते हैं, जो सुंडालैंड हॉटस्पॉट में आता है।"},
  {"id":"env-ecology-825","question":"The golden langur, brought to scientific attention by the naturalist E. P. Gee, has a small natural range in western Assam and Bhutan that is bounded mainly by:","options":["The Teesta, the Mahananda and the Ganga","The Subansiri, the Kameng and the Lohit","The Barak, the Surma and the Kopili","The Sankosh, the Manas and the Brahmaputra"],"answer":3,"explanation":"The langur lives between the Sankosh river in the west, the Manas in the east and the Brahmaputra in the south, with the Bhutan hills to the north; rivers act as barriers that it does not cross.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"प्रकृतिवादी ई. पी. गी द्वारा वैज्ञानिक ध्यान में लाए गए सुनहरे लंगूर का पश्चिमी असम और भूटान में छोटा प्राकृतिक वितरण क्षेत्र मुख्यतः किन नदियों से घिरा है?","optionsHi":["तीस्ता, महानंदा और गंगा","सुबनसिरी, कामेंग और लोहित","बराक, सुरमा और कोपिली","संकोश, मानस और ब्रह्मपुत्र"],"explanationHi":"लंगूर पश्चिम में संकोश नदी, पूर्व में मानस और दक्षिण में ब्रह्मपुत्र के बीच रहता है, जिसके उत्तर में भूटान की पहाड़ियाँ हैं; नदियाँ अवरोध का काम करती हैं जिन्हें वह पार नहीं करता।"},
  {"id":"env-ecology-826","question":"The wild water buffalo, whose few surviving central Indian herds live in Indravati and Udanti-Sitanadi, is the state animal of:","options":["Odisha","Madhya Pradesh","Chhattisgarh","Jharkhand"],"answer":2,"explanation":"Chhattisgarh adopted the wild buffalo as its state animal. Apart from these small central Indian herds, the main wild populations are in Assam, notably Kaziranga and Manas.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जंगली जल भैंसा, जिसके मध्य भारत के कुछ बचे झुंड इंद्रावती और उदंती-सीतानदी में रहते हैं, किस राज्य का राजकीय पशु है?","optionsHi":["ओडिशा","मध्य प्रदेश","छत्तीसगढ़","झारखंड"],"explanationHi":"छत्तीसगढ़ ने जंगली भैंसे को अपना राजकीय पशु बनाया। मध्य भारत के इन छोटे झुंडों के अलावा मुख्य वन्य समष्टियाँ असम में हैं, विशेषकर काज़ीरंगा और मानस में।"},
  {"id":"env-ecology-827","question":"The largest antelope found in Asia is the:","options":["Blackbuck","Chinkara","Four-horned antelope","Nilgai"],"answer":3,"explanation":"The nilgai or blue bull is Asia's largest antelope; its sacred status in many areas lets it thrive near farms, where it is often a crop pest.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"एशिया में पाया जाने वाला सबसे बड़ा मृग (एंटीलोप) है:","optionsHi":["काला हिरण","चिंकारा","चौसिंगा","नीलगाय"],"explanationHi":"नीलगाय एशिया का सबसे बड़ा मृग है; अनेक क्षेत्रों में उसकी पवित्र स्थिति उसे खेतों के निकट फलने-फूलने देती है, जहाँ वह प्रायः फसल का नाशीजीव होती है।"},
  {"id":"env-ecology-828","question":"The chousingha, found in dry deciduous forests of India and Nepal, is unique among the world's wild bovids because:","options":["Females have larger horns than males","It sheds its horns every year like a deer","Males carry two pairs of horns","It has no horns in either sex"],"answer":2,"explanation":"The chousingha, or four-horned antelope, is the only wild bovid in which males bear two pairs of horns, a short front pair and a longer rear pair. Bovid horns, unlike deer antlers, are not shed.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत और नेपाल के शुष्क पर्णपाती वनों में पाया जाने वाला चौसिंगा विश्व के जंगली बोविडों में इसलिए अनूठा है क्योंकि:","optionsHi":["मादाओं के सींग नरों से बड़े होते हैं","वह हिरण की तरह हर वर्ष अपने सींग गिराता है","नरों के दो जोड़ी सींग होते हैं","दोनों लिंगों में उसके सींग नहीं होते"],"explanationHi":"चौसिंगा, यानी चार-सींग वाला मृग, एकमात्र जंगली बोविड है जिसके नरों में दो जोड़ी सींग होते हैं, एक छोटी अगली जोड़ी और एक लंबी पिछली जोड़ी। हिरण के शृंगों के विपरीत बोविड के सींग गिरते नहीं।"},
  {"id":"env-ecology-829","question":"Consider the following statements about the Himalayan musk deer: 1. Males grow branched antlers that are shed every year. 2. Males have long, tusk-like upper canine teeth. 3. It is poached for a gland whose secretion is used in perfumes and traditional medicines. Which of the statements given above is/are correct?","options":["2 and 3 only","1 and 3 only","3 only","1, 2 and 3"],"answer":0,"explanation":"Musk deer have no antlers at all; males instead carry long upper canines. The musk pod of males is the reason for heavy poaching.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"हिमालयी कस्तूरी मृग के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. नरों में शाखित शृंग उगते हैं जो हर वर्ष गिर जाते हैं। 2. नरों के लंबे, दाँत-सदृश ऊपरी रदनक दाँत होते हैं। 3. उसका शिकार एक ग्रंथि के लिए किया जाता है जिसका स्राव इत्र और पारंपरिक औषधियों में प्रयुक्त होता है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 2 और 3","केवल 1 और 3","केवल 3","1, 2 और 3"],"explanationHi":"कस्तूरी मृग के शृंग बिल्कुल नहीं होते; इसके बजाय नरों में लंबे ऊपरी रदनक होते हैं। नरों की कस्तूरी थैली ही भारी अवैध शिकार का कारण है।"},
  {"id":"env-ecology-830","question":"The mithun, regarded as a domesticated form of the gaur and central to the culture of many hill communities, is the state animal of:","options":["Arunachal Pradesh and Nagaland","Arunachal Pradesh and Mizoram","Nagaland and Manipur","Meghalaya and Arunachal Pradesh"],"answer":0,"explanation":"The mithun is the state animal of both Arunachal Pradesh and Nagaland, where it is a symbol of wealth and is used in ceremonies. Mizoram's state animal is the serow, Manipur's the sangai and Meghalaya's the clouded leopard.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मिथुन, जिसे गौर का पालतू रूप माना जाता है और जो अनेक पहाड़ी समुदायों की संस्कृति का केंद्र है, किन राज्यों का राजकीय पशु है?","optionsHi":["अरुणाचल प्रदेश और नागालैंड","अरुणाचल प्रदेश और मिज़ोरम","नागालैंड और मणिपुर","मेघालय और अरुणाचल प्रदेश"],"explanationHi":"मिथुन अरुणाचल प्रदेश और नागालैंड दोनों का राजकीय पशु है, जहाँ वह धन का प्रतीक है और समारोहों में प्रयुक्त होता है। मिज़ोरम का राजकीय पशु सीरो, मणिपुर का संगाई और मेघालय का क्लाउडेड तेंदुआ है।"},
  {"id":"env-ecology-831","question":"The clouded leopard, an arboreal cat with the longest canines relative to body size of any living cat, is the state animal of:","options":["Sikkim","Meghalaya","Mizoram","Arunachal Pradesh"],"answer":1,"explanation":"Meghalaya chose the clouded leopard, which lives in its forests. Sikkim's state animal is the red panda, and Arunachal's the mithun.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"क्लाउडेड तेंदुआ, एक वृक्षवासी बिल्ली जिसके रदनक दाँत शरीर के आकार की तुलना में किसी भी जीवित बिल्ली से सबसे लंबे हैं, किस राज्य का राजकीय पशु है?","optionsHi":["सिक्किम","मेघालय","मिज़ोरम","अरुणाचल प्रदेश"],"explanationHi":"मेघालय ने क्लाउडेड तेंदुए को चुना, जो उसके वनों में रहता है। सिक्किम का राजकीय पशु रेड पांडा है, और अरुणाचल का मिथुन।"},
  {"id":"env-ecology-832","question":"The Indian giant squirrel (Malabar giant squirrel), known locally as 'shekru' and protected in Bhimashankar Wildlife Sanctuary, is the state animal of:","options":["Kerala","Karnataka","Goa","Maharashtra"],"answer":3,"explanation":"Maharashtra adopted the shekru as its state animal; Bhimashankar was created largely to protect it. It is an important seed predator and disperser in the canopy.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारतीय विशाल गिलहरी (मालाबार विशाल गिलहरी), जो स्थानीय रूप से 'शेकरू' कहलाती है और भीमाशंकर वन्यजीव अभयारण्य में संरक्षित है, किस राज्य का राजकीय पशु है?","optionsHi":["केरल","कर्नाटक","गोवा","महाराष्ट्र"],"explanationHi":"महाराष्ट्र ने शेकरू को अपना राजकीय पशु बनाया; भीमाशंकर मुख्यतः उसी की रक्षा के लिए बना। वह वितान में बीजों का महत्त्वपूर्ण भक्षक और प्रकीर्णक है।"},
  {"id":"env-ecology-833","question":"The only species of marten endemic to southern India, found in the evergreen forests of the Western Ghats, is the:","options":["Yellow-throated marten","Beech marten","Nilgiri marten","Pine marten"],"answer":2,"explanation":"The Nilgiri marten is a Western Ghats endemic. The yellow-throated marten, its closest relative, lives in the Himalaya and north-east, far to the north.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"दक्षिण भारत की एकमात्र स्थानिक मार्टन प्रजाति, जो पश्चिमी घाट के सदाबहार वनों में पाई जाती है, है:","optionsHi":["पीले गले वाली मार्टन","बीच मार्टन","नीलगिरि मार्टन","पाइन मार्टन"],"explanationHi":"नीलगिरि मार्टन पश्चिमी घाट की स्थानिक प्रजाति है। उसकी निकटतम संबंधी पीले गले वाली मार्टन हिमालय और पूर्वोत्तर में, बहुत उत्तर में रहती है।"},
  {"id":"env-ecology-834","question":"An Endangered pack-hunting canid of Indian forests, known for its whistling calls and for cooperatively hunting prey as large as sambar, is the:","options":["Indian wolf","Golden jackal","Dhole","Indian fox"],"answer":2,"explanation":"The dhole or Asiatic wild dog hunts in packs and communicates with whistles. The Indian wolf lives mainly in open grasslands and scrub, and the golden jackal is a smaller, more solitary opportunist.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भारतीय वनों का एक संकटग्रस्त झुंड में शिकार करने वाला कैनिड, जो अपनी सीटी जैसी पुकारों और सांभर जितने बड़े शिकार का सहयोग से शिकार करने के लिए जाना जाता है, है:","optionsHi":["भारतीय भेड़िया","सुनहरा सियार","ढोल (जंगली कुत्ता)","भारतीय लोमड़ी"],"explanationHi":"ढोल या एशियाई जंगली कुत्ता झुंड में शिकार करता है और सीटियों से संवाद करता है। भारतीय भेड़िया मुख्यतः खुले घास के मैदानों और झाड़ियों में रहता है, और सुनहरा सियार छोटा, अधिक एकाकी अवसरवादी है।"},
  {"id":"env-ecology-835","question":"The sloth bear can suck termites out of their mounds with great force. An anatomical feature that helps it do this is:","options":["A long, sticky tongue like that of an anteater","Very large, flat molars for grinding","Loss of the inner pair of upper incisors","Webbed claws for digging"],"answer":2,"explanation":"The gap left by the missing upper incisors, together with mobile lips and closable nostrils, lets the bear blow away dust and suck up termites like a vacuum.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भालू (स्लॉथ बियर) दीमकों को उनकी बाँबियों से बड़े बल से चूस सकता है। इसमें उसकी सहायता करने वाली एक शारीरिक विशेषता है:","optionsHi":["चींटीखोर जैसी लंबी, चिपचिपी जीभ","पीसने के लिए बहुत बड़ी, चपटी दाढ़ें","ऊपरी भीतरी कृंतक दाँतों की जोड़ी का न होना","खोदने के लिए जालयुक्त नाखून"],"explanationHi":"ऊपरी कृंतकों के न होने से बना अंतराल, गतिशील होंठों और बंद हो सकने वाले नथुनों के साथ, भालू को धूल उड़ाने और वैक्यूम की तरह दीमक चूसने देता है।"},
  {"id":"env-ecology-836","question":"India's only population of the Indus river dolphin survives in the:","options":["Beas river in Punjab","Chenab river in Jammu","Sutlej river in Himachal Pradesh","Ghaggar river in Haryana"],"answer":0,"explanation":"A small population lives in the Beas between Talwara and Harike. Most Indus dolphins live in Pakistan; the Ganges dolphin is a separate species found in the Ganga–Brahmaputra system.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत में सिंधु नदी डॉल्फ़िन की एकमात्र समष्टि कहाँ जीवित है?","optionsHi":["पंजाब की ब्यास नदी में","जम्मू की चिनाब नदी में","हिमाचल प्रदेश की सतलुज नदी में","हरियाणा की घग्गर नदी में"],"explanationHi":"एक छोटी समष्टि तलवाड़ा और हरिके के बीच ब्यास में रहती है। अधिकांश सिंधु डॉल्फ़िन पाकिस्तान में रहती हैं; गंगा डॉल्फ़िन गंगा–ब्रह्मपुत्र तंत्र में पाई जाने वाली अलग प्रजाति है।"},
  {"id":"env-ecology-837","question":"The slender loris, a small nocturnal primate with large eyes, is found naturally in:","options":["The Himalayan foothills of Uttarakhand","The hill forests of north-east India","The Andaman and Nicobar Islands","Southern India and Sri Lanka"],"answer":3,"explanation":"The slender loris lives in the forests of peninsular India and Sri Lanka. North-east India has a different species, the Bengal slow loris.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पतला लोरिस, बड़ी आँखों वाला एक छोटा निशाचर नर-वानर (प्राइमेट), स्वाभाविक रूप से कहाँ पाया जाता है?","optionsHi":["उत्तराखंड की हिमालयी तलहटी में","पूर्वोत्तर भारत के पहाड़ी वनों में","अंडमान और निकोबार द्वीप समूह में","दक्षिण भारत और श्रीलंका में"],"explanationHi":"पतला लोरिस प्रायद्वीपीय भारत और श्रीलंका के वनों में रहता है। पूर्वोत्तर भारत में एक अलग प्रजाति, बंगाल स्लो लोरिस, पाई जाती है।"},
  {"id":"env-ecology-838","question":"The hispid hare, an Endangered mammal that shares its habitat with the pygmy hog, depends on:","options":["Alpine meadows above the treeline in the western Himalaya","Tall, wet grasslands of the Terai and Duars","Sand dunes of the Thar desert in western Rajasthan","Mangrove forests of the Sundarbans delta"],"answer":1,"explanation":"Both animals live in tall grasslands at the foot of the Himalaya, notably in Manas, and suffer when these grasslands are burnt, cleared or converted to farms.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"हिस्पिड खरगोश, एक संकटग्रस्त स्तनधारी जो पिग्मी हॉग के साथ अपना आवास साझा करता है, किस पर निर्भर है?","optionsHi":["पश्चिमी हिमालय में वृक्ष-रेखा से ऊपर के अल्पाइन चारागाह","तराई और दुआर के ऊँचे, आर्द्र घास के मैदान","पश्चिमी राजस्थान के थार मरुस्थल के रेत के टीले","सुंदरबन डेल्टा के मैंग्रोव वन"],"explanationHi":"दोनों जंतु हिमालय की तलहटी के ऊँचे घास के मैदानों में रहते हैं, विशेषकर मानस में, और जब इन घास के मैदानों को जलाया, साफ़ किया या खेतों में बदला जाता है तब उन्हें हानि होती है।"},
  {"id":"env-ecology-839","question":"The pygmy hog-sucking louse is listed as Critically Endangered, though it has never been directly hunted or traded. The reason is that:","options":["It is killed by the same pesticides used on tea plantations in Assam","Its larvae can develop only in clear, fast-flowing mountain streams","It lives only on the pygmy hog, so it shares that host's fate","It is exported in large numbers for laboratory research"],"answer":2,"explanation":"A host-specific parasite cannot outlive its host, so the louse is threatened with co-extinction. Conservation of the pygmy hog is therefore conservation of its parasite too.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"पिग्मी हॉग-चूषक जूँ घोर संकटग्रस्त सूचीबद्ध है, यद्यपि उसका कभी प्रत्यक्ष शिकार या व्यापार नहीं हुआ। इसका कारण यह है कि:","optionsHi":["वह असम के चाय बागानों में प्रयुक्त उन्हीं कीटनाशकों से मारी जाती है","उसके लार्वा केवल स्वच्छ, तेज़ बहने वाली पहाड़ी धाराओं में ही विकसित हो सकते हैं","वह केवल पिग्मी हॉग पर रहती है, इसलिए उस पोषी के भाग्य में साझेदार है","प्रयोगशाला अनुसंधान के लिए उसका बड़ी संख्या में निर्यात किया जाता है"],"explanationHi":"पोषी-विशिष्ट परजीवी अपने पोषी से अधिक जीवित नहीं रह सकता, इसलिए जूँ पर सह-विलुप्ति का संकट है। अतः पिग्मी हॉग का संरक्षण उसके परजीवी का भी संरक्षण है।"},
  {"id":"env-ecology-840","question":"Shahtoosh shawls, whose trade is banned in India, are woven from the fine underfur of the:","options":["Changthangi (pashmina) goat","Himalayan ibex","Kashmir stag (hangul)","Tibetan antelope (chiru)"],"answer":3,"explanation":"Shahtoosh comes from the chiru, which must be killed for its wool; in India it occurs in the Changthang of Ladakh. Pashmina, by contrast, is combed from domestic Changthangi goats.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"शहतूश शॉल, जिनका व्यापार भारत में प्रतिबंधित है, किसके महीन अंतःरोम से बुने जाते हैं?","optionsHi":["चांगथांगी (पश्मीना) बकरी","हिमालयी आइबेक्स","कश्मीर हिरण (हंगुल)","तिब्बती मृग (चिरु)"],"explanationHi":"शहतूश चिरु से आता है, जिसे ऊन के लिए मारना पड़ता है; भारत में वह लद्दाख के चांगथांग में पाया जाता है। इसके विपरीत, पश्मीना पालतू चांगथांगी बकरियों से कंघी करके निकाला जाता है।"},
  {"id":"env-ecology-841","question":"The markhor, a wild goat with spectacular corkscrew horns, is found in India only in:","options":["The Pir Panjal range of Kashmir","The Changthang plateau of Ladakh","The Kumaon Himalaya of Uttarakhand","The Kinnaur district of Himachal Pradesh"],"answer":0,"explanation":"In India the markhor survives in a small area of the Pir Panjal range around Kazinag and Hirpora; it is more widespread in Pakistan, where it is the national animal.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मारखोर, शानदार पेचदार सींगों वाली जंगली बकरी, भारत में केवल कहाँ पाई जाती है?","optionsHi":["कश्मीर की पीर पंजाल श्रेणी में","लद्दाख के चांगथांग पठार में","उत्तराखंड के कुमाऊँ हिमालय में","हिमाचल प्रदेश के किन्नौर ज़िले में"],"explanationHi":"भारत में मारखोर काज़ीनाग और हिरपोरा के आसपास पीर पंजाल श्रेणी के छोटे क्षेत्र में जीवित है; पाकिस्तान में वह अधिक व्यापक है, जहाँ वह राष्ट्रीय पशु है।"},
  {"id":"env-ecology-842","question":"The bharal, the main prey of the snow leopard in much of the Himalaya, is popularly known as the:","options":["Blue sheep","Barking deer","Mountain goat","Red goral"],"answer":0,"explanation":"Bharal (Pseudois nayaur) are called blue sheep for their slate-grey coat, though in many features they are intermediate between sheep and goats.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भरल, जो हिमालय के बड़े भाग में हिम तेंदुए का मुख्य शिकार है, लोकप्रिय रूप से किस नाम से जाना जाता है?","optionsHi":["नीली भेड़","भौंकने वाला हिरण","पहाड़ी बकरी","लाल घोरल"],"explanationHi":"भरल (सूडोइस नयौर) को उसके स्लेटी-धूसर रोम के कारण नीली भेड़ कहा जाता है, यद्यपि अनेक लक्षणों में वह भेड़ और बकरी के बीच की है।"},
  {"id":"env-ecology-843","question":"The gaur, often wrongly called the 'Indian bison', is noteworthy as:","options":["The ancestor of all humped zebu cattle of India","The largest living species of wild cattle","A native of Africa introduced into India","The only wild ox found in the Thar desert"],"answer":1,"explanation":"The gaur is the largest wild bovine in the world. Zebu cattle descend from the aurochs, not the gaur, though the mithun is considered a domesticated gaur.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"गौर, जिसे प्रायः गलती से 'भारतीय बाइसन' कहा जाता है, किस कारण उल्लेखनीय है?","optionsHi":["भारत के सभी कूबड़ वाले ज़ेबू पशुओं का पूर्वज","जीवित जंगली गोवंश की सबसे बड़ी प्रजाति","अफ़्रीका का मूल निवासी जिसे भारत में लाया गया","थार मरुस्थल में पाया जाने वाला एकमात्र जंगली बैल"],"explanationHi":"गौर विश्व का सबसे बड़ा जंगली गोवंशीय जंतु है। ज़ेबू पशु ऑरॉक्स के वंशज हैं, गौर के नहीं, यद्यपि मिथुन को पालतू गौर माना जाता है।"},
  {"id":"env-ecology-844","question":"In Asian elephants, an adult male that has no tusks is commonly called a:","options":["Musth bull","Tusker","Gunda","Makhna"],"answer":3,"explanation":"Tuskless males are called makhnas; female Asian elephants normally lack tusks or have only small 'tushes'. Musth is a periodic hormonal state of bulls, with or without tusks.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"एशियाई हाथियों में बिना दाँतों (दंतहीन) वयस्क नर को सामान्यतः क्या कहा जाता है?","optionsHi":["मस्त (मस्थ) बैल","टस्कर","गुंडा","मखना"],"explanationHi":"दंतहीन नरों को मखना कहा जाता है; मादा एशियाई हाथियों के सामान्यतः दाँत नहीं होते या केवल छोटे 'टुश' होते हैं। मस्त (मस्थ) बैलों की समय-समय की हार्मोनी अवस्था है, चाहे दाँत हों या न हों।"},
  {"id":"env-ecology-845","question":"A shaggy, black, tree-dwelling mammal of north-east India with a prehensile tail, sometimes called the 'bearcat' and said to smell like buttered popcorn, is the:","options":["Binturong","Red panda","Slow loris","Hoolock gibbon"],"answer":0,"explanation":"The binturong is a large civet, related neither to bears nor to cats, and one of the few Old World mammals with a prehensile tail. Its musky scent contains the same compound as popcorn.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"पूर्वोत्तर भारत का एक झबरा, काला, वृक्षवासी स्तनधारी जिसकी पूँछ पकड़ने वाली होती है, जिसे कभी-कभी 'बियरकैट' कहा जाता है और जिसकी गंध मक्खन लगे पॉपकॉर्न जैसी बताई जाती है, है:","optionsHi":["बिंटुरोंग","रेड पांडा","स्लो लोरिस","हूलॉक गिब्बन"],"explanationHi":"बिंटुरोंग एक बड़ा सिवेट है, जो न भालुओं से संबंधित है न बिल्लियों से, और पुरानी दुनिया के उन थोड़े स्तनधारियों में है जिनकी पूँछ पकड़ने वाली होती है। उसकी कस्तूरी-गंध में वही यौगिक होता है जो पॉपकॉर्न में।"},
  {"id":"env-ecology-846","question":"The red panda, a bamboo-eating mammal of the eastern Himalaya, is the state animal of:","options":["Arunachal Pradesh","Sikkim","Meghalaya","Nagaland"],"answer":1,"explanation":"Sikkim adopted the red panda as its state animal. It is Endangered, threatened by loss of temperate forest with a bamboo understorey.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"रेड पांडा, पूर्वी हिमालय का बाँस खाने वाला स्तनधारी, किस राज्य का राजकीय पशु है?","optionsHi":["अरुणाचल प्रदेश","सिक्किम","मेघालय","नागालैंड"],"explanationHi":"सिक्किम ने रेड पांडा को अपना राजकीय पशु बनाया। वह संकटग्रस्त है, और बाँस के अधोवन वाले शीतोष्ण वन की हानि से संकट में है।"},
  {"id":"env-ecology-847","question":"The blackbuck is the state animal of which group of states?","options":["Rajasthan, Gujarat and Madhya Pradesh","Haryana, Punjab and Andhra Pradesh","Uttar Pradesh, Bihar and Odisha","Karnataka, Tamil Nadu and Kerala"],"answer":1,"explanation":"Punjab, Haryana and Andhra Pradesh all chose the blackbuck. Rajasthan's state animals are the chinkara and the camel, and Gujarat's is the Asiatic lion.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"काला हिरण राज्यों के किस समूह का राजकीय पशु है?","optionsHi":["राजस्थान, गुजरात और मध्य प्रदेश","हरियाणा, पंजाब और आंध्र प्रदेश","उत्तर प्रदेश, बिहार और ओडिशा","कर्नाटक, तमिलनाडु और केरल"],"explanationHi":"पंजाब, हरियाणा और आंध्र प्रदेश तीनों ने काले हिरण को चुना। राजस्थान के राजकीय पशु चिंकारा और ऊँट हैं, और गुजरात का एशियाई शेर।"},
  {"id":"env-ecology-848","question":"The Indian chevrotain or 'mouse deer', the smallest hoofed mammal of Indian forests, is not a true deer because it:","options":["Is actually a rodent that only resembles a small deer","Is from a primitive separate family and lacks antlers","Feeds mainly on insects and small vertebrates","Is a marsupial that carries its young in a pouch"],"answer":1,"explanation":"Chevrotains form the family Tragulidae, an ancient lineage of ruminants. They have no antlers, and males have small tusk-like canines.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारतीय चेवरोटेन या 'चूहा हिरण', भारतीय वनों का सबसे छोटा खुर वाला स्तनधारी, सच्चा हिरण नहीं है क्योंकि वह:","optionsHi":["वास्तव में कृंतक है जो केवल छोटे हिरण जैसा दिखता है","एक आदिम अलग कुल का है और उसमें शृंग नहीं होते","मुख्यतः कीटों और छोटे कशेरुकियों को खाता है","शिशुधानी है जो अपने बच्चों को थैली में रखता है"],"explanationHi":"चेवरोटेन ट्रेगुलिडी कुल बनाते हैं, जो जुगाली करने वालों की प्राचीन वंश-परंपरा है। उनके शृंग नहीं होते, और नरों में छोटे दाँत-सदृश रदनक होते हैं।"},
  {"id":"env-ecology-849","question":"Pollination of flowers by bats, as in the baobab and several night-blooming trees, is known as:","options":["Ornithophily","Entomophily","Chiropterophily","Anemophily"],"answer":2,"explanation":"Chiropterophily is bat pollination; such flowers are large, pale, strong-smelling and open at night. Ornithophily is pollination by birds and anemophily by wind.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"चमगादड़ों द्वारा फूलों का परागण, जैसा बाओबाब और कई रात में खिलने वाले वृक्षों में होता है, क्या कहलाता है?","optionsHi":["पक्षी परागण (ऑर्निथोफिली)","कीट परागण (एंटोमोफिली)","चमगादड़ परागण (कीरोप्टेरोफिली)","वायु परागण (एनीमोफिली)"],"explanationHi":"कीरोप्टेरोफिली चमगादड़ परागण है; ऐसे फूल बड़े, पीले-से, तेज़ गंध वाले होते हैं और रात में खुलते हैं। ऑर्निथोफिली पक्षियों द्वारा और एनीमोफिली वायु द्वारा परागण है।"},
  {"id":"env-ecology-850","question":"Strategic Environmental Assessment (SEA) differs from project-level Environmental Impact Assessment (EIA) mainly in that SEA:","options":["Is carried out only after a project has been built, to audit its actual impacts","Is applied to policies, plans and programmes, before projects are chosen","Covers only social and economic impacts, leaving ecological ones to the EIA","Is a voluntary exercise done by companies for investors, not by governments"],"answer":1,"explanation":"SEA brings environmental concerns into decisions at the level of a sector plan or regional programme, such as a river-basin hydropower plan, where cumulative impacts and alternatives can still be weighed. EIA looks at one project at a time.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सामरिक पर्यावरणीय आकलन (SEA) परियोजना-स्तर के पर्यावरणीय प्रभाव आकलन (EIA) से मुख्यतः इस बात में भिन्न है कि SEA:","optionsHi":["परियोजना के बन जाने के बाद ही, उसके वास्तविक प्रभावों की लेखा-परीक्षा के लिए किया जाता है","नीतियों, योजनाओं और कार्यक्रमों पर, परियोजनाओं के चुने जाने से पहले, लागू किया जाता है","केवल सामाजिक और आर्थिक प्रभावों को शामिल करता है, पारिस्थितिक प्रभावों को EIA पर छोड़ते हुए","निवेशकों के लिए कंपनियों द्वारा किया गया स्वैच्छिक अभ्यास है, सरकारों द्वारा नहीं"],"explanationHi":"SEA पर्यावरणीय चिंताओं को क्षेत्रीय योजना या कार्यक्रम स्तर के निर्णयों में लाता है, जैसे नदी-बेसिन जल-विद्युत योजना, जहाँ संचयी प्रभावों और विकल्पों को अब भी तौला जा सकता है। EIA एक समय में एक परियोजना को देखता है।"},
  {"id":"env-ecology-851","question":"Under the EIA Notification, 2006, the public hearing for a project requiring public consultation is conducted by:","options":["The Expert Appraisal Committee of the Union Ministry of Environment","The project proponent, through a consultant accredited by the Ministry","The State Pollution Control Board or UT Pollution Control Committee","The Gram Sabha of the village in which the project is to be located"],"answer":2,"explanation":"The SPCB or UTPCC organises the hearing, chaired by the District Magistrate or an officer not below Additional District Magistrate, and forwards the proceedings to the regulatory authority. The EAC appraises the project afterwards.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"EIA अधिसूचना, 2006 के अंतर्गत, जन परामर्श की आवश्यकता वाली परियोजना की जन सुनवाई कौन आयोजित करता है?","optionsHi":["केंद्रीय पर्यावरण मंत्रालय की विशेषज्ञ मूल्यांकन समिति","परियोजना प्रस्तावक, मंत्रालय द्वारा मान्यता प्राप्त परामर्शदाता के माध्यम से","राज्य प्रदूषण नियंत्रण बोर्ड या संघ राज्य क्षेत्र प्रदूषण नियंत्रण समिति","उस गाँव की ग्राम सभा जहाँ परियोजना स्थित होनी है"],"explanationHi":"SPCB या UTPCC सुनवाई आयोजित करता है, जिसकी अध्यक्षता ज़िला मजिस्ट्रेट या अतिरिक्त ज़िला मजिस्ट्रेट से अन्यून अधिकारी करता है, और कार्यवाही नियामक प्राधिकरण को भेजता है। EAC परियोजना का मूल्यांकन बाद में करती है।"},
  {"id":"env-ecology-852","question":"Under India's Coastal Regulation Zone notifications, the zone classified as CRZ-IV covers:","options":["Ecologically sensitive areas such as mangroves, coral reefs and turtle nesting beaches","Developed urban areas that are already substantially built up up to the shoreline","Rural and relatively undisturbed coastal land, including fishing villages","The water area from the low tide line up to 12 nautical miles, and tidal water bodies"],"answer":3,"explanation":"CRZ-I is ecologically sensitive areas, CRZ-II developed urban areas and CRZ-III relatively undisturbed rural areas. CRZ-IV regulates activities in the sea up to the territorial limit of 12 nautical miles and in tidal creeks, rivers and backwaters.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत की तटीय विनियमन क्षेत्र अधिसूचनाओं के अंतर्गत CRZ-IV के रूप में वर्गीकृत क्षेत्र में क्या आता है?","optionsHi":["मैंग्रोव, प्रवाल भित्तियों और कछुओं के घोंसले वाले तटों जैसे पारिस्थितिक संवेदनशील क्षेत्र","विकसित नगरीय क्षेत्र जो तटरेखा तक पहले से काफ़ी हद तक निर्मित हैं","ग्रामीण और अपेक्षाकृत अक्षुण्ण तटीय भूमि, जिनमें मछुआरा गाँव शामिल हैं","निम्न ज्वार रेखा से 12 समुद्री मील तक का जल क्षेत्र, और ज्वारीय जल निकाय"],"explanationHi":"CRZ-I पारिस्थितिक संवेदनशील क्षेत्र हैं, CRZ-II विकसित नगरीय क्षेत्र और CRZ-III अपेक्षाकृत अक्षुण्ण ग्रामीण क्षेत्र। CRZ-IV समुद्र में 12 समुद्री मील की प्रादेशिक सीमा तक और ज्वारीय खाड़ियों, नदियों और अप्रवाही जल (बैकवाटर) में गतिविधियों का नियमन करता है।"},
  {"id":"env-ecology-853","question":"Consider the following statements about the National Clean Air Programme (NCAP): 1. It was launched in 2019. 2. Its targets for reducing particulate matter concentrations were set against 2017 as the base year. 3. It is a statutory programme under the Air Act, so its city targets are legally binding. Which of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"NCAP, launched by the Environment Ministry in January 2019 for non-attainment cities, set an initial target of a 20–30 per cent cut in PM concentrations by 2024 from 2017 levels. It is a national programme without statutory backing, a point often criticised.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"राष्ट्रीय स्वच्छ वायु कार्यक्रम (NCAP) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसे 2019 में शुरू किया गया। 2. कणिकीय पदार्थ सांद्रता घटाने के इसके लक्ष्य 2017 को आधार वर्ष मानकर निर्धारित किए गए। 3. यह वायु अधिनियम के अंतर्गत एक सांविधिक कार्यक्रम है, इसलिए इसके शहर-स्तरीय लक्ष्य विधिक रूप से बाध्यकारी हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"जनवरी 2019 में पर्यावरण मंत्रालय द्वारा गैर-प्राप्ति शहरों के लिए शुरू किए गए NCAP ने 2017 के स्तरों से 2024 तक PM सांद्रता में 20–30 प्रतिशत कटौती का प्रारंभिक लक्ष्य रखा। यह सांविधिक आधार रहित राष्ट्रीय कार्यक्रम है, जिसकी प्रायः आलोचना होती है।"},
  {"id":"env-ecology-854","question":"The Central Ground Water Authority, which regulates groundwater extraction by industries and infrastructure projects, was constituted under:","options":["The Water (Prevention and Control of Pollution) Act, 1974","The River Boards Act, 1956","The Environment (Protection) Act, 1986","The Inter-State River Water Disputes Act, 1956"],"answer":2,"explanation":"CGWA was set up in 1997 under Section 3(3) of the EP Act on the directions of the Supreme Court, which allows the Centre to constitute authorities. India has no single central law on groundwater, so the EP Act was used.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"उद्योगों और अवसंरचना परियोजनाओं द्वारा भूजल निष्कर्षण का नियमन करने वाला केंद्रीय भूजल प्राधिकरण किसके अंतर्गत गठित हुआ?","optionsHi":["जल (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1974","नदी बोर्ड अधिनियम, 1956","पर्यावरण (संरक्षण) अधिनियम, 1986","अंतर-राज्यीय नदी जल विवाद अधिनियम, 1956"],"explanationHi":"CGWA की स्थापना 1997 में उच्चतम न्यायालय के निर्देशों पर EP अधिनियम की धारा 3(3) के अंतर्गत हुई, जो केंद्र को प्राधिकरण गठित करने देती है। भारत में भूजल पर कोई एकल केंद्रीय कानून नहीं है, इसलिए EP अधिनियम का उपयोग किया गया।"},
  {"id":"env-ecology-855","question":"In 2013, in Centre for Environmental Law, WWF-India v. Union of India, the Supreme Court directed that:","options":["Cheetahs from Africa be introduced into Kuno National Park within a year","Some Asiatic lions be moved from Gir to Kuno to form a second population","All tigers living outside reserves be shifted into the core areas of reserves","Gir National Park be declared a tiger reserve under the Wild Life Act, 1972"],"answer":1,"explanation":"The Court held that the lion, confined to one region of Gujarat, needed a second home to guard against epidemics or disasters, and ordered translocation to Kuno in Madhya Pradesh. In the same judgment it rejected the then cheetah plan; cheetahs were brought to Kuno only in 2022.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2013 में सेंटर फॉर एन्वायरनमेंटल लॉ, WWF-इंडिया बनाम भारत संघ मामले में उच्चतम न्यायालय ने निर्देश दिया कि:","optionsHi":["अफ़्रीका से चीते एक वर्ष के भीतर कूनो राष्ट्रीय उद्यान में लाए जाएँ","कुछ एशियाई शेर गिर से कूनो ले जाए जाएँ ताकि दूसरी समष्टि बने","अभयारण्यों के बाहर रहने वाले सभी बाघ अभयारण्यों के क्रोड क्षेत्रों में ले जाए जाएँ","गिर राष्ट्रीय उद्यान को वन्यजीव अधिनियम, 1972 के अंतर्गत बाघ अभयारण्य घोषित किया जाए"],"explanationHi":"न्यायालय ने कहा कि गुजरात के एक क्षेत्र तक सीमित शेर को महामारियों या आपदाओं से बचाव के लिए दूसरे घर की आवश्यकता है, और मध्य प्रदेश के कूनो में स्थानांतरण का आदेश दिया। उसी निर्णय में उसने तत्कालीन चीता योजना को अस्वीकार किया; चीते कूनो में केवल 2022 में लाए गए।"},
  {"id":"env-ecology-856","question":"Under the Montreal Protocol, developing countries that qualify under 'Article 5' are:","options":["Given extra time to phase out and access to the Multilateral Fund","Exempted permanently from phasing out CFCs, halons and other controlled substances","Required to phase out ozone-depleting substances before the developed countries do","Barred from producing any ozone-depleting substance, even for essential uses"],"answer":0,"explanation":"Article 5 parties, developing countries with low per capita consumption, got roughly a ten-year delay in compliance and financial and technical help, an early application of common but differentiated responsibilities. India is an Article 5 party.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"मॉन्ट्रियल प्रोटोकॉल के अंतर्गत, 'अनुच्छेद 5' के पात्र विकासशील देश:","optionsHi":["चरणबद्ध समाप्ति के लिए अतिरिक्त समय और बहुपक्षीय कोष तक पहुँच पाते हैं","CFC, हैलॉन और अन्य नियंत्रित पदार्थों को चरणबद्ध समाप्त करने से स्थायी रूप से मुक्त हैं","ओज़ोन-क्षयकारी पदार्थों को विकसित देशों से पहले चरणबद्ध समाप्त करने के लिए बाध्य हैं","आवश्यक उपयोगों के लिए भी किसी ओज़ोन-क्षयकारी पदार्थ का उत्पादन करने से वर्जित हैं"],"explanationHi":"अनुच्छेद 5 के पक्षों, कम प्रति व्यक्ति खपत वाले विकासशील देशों, को अनुपालन में लगभग दस वर्ष का विलंब तथा वित्तीय और तकनीकी सहायता मिली, जो साझा परंतु विभेदित उत्तरदायित्वों का प्रारंभिक अनुप्रयोग था। भारत अनुच्छेद 5 का पक्षकार है।"},
  {"id":"env-ecology-857","question":"The Montreal Protocol is often praised for its flexibility because 'adjustments' to the phase-out schedules of substances already controlled:","options":["Must be ratified by every party before they apply to anyone","Apply only to developed countries, never to developing ones","Can be made by a single party for its own territory","Become binding on all parties without separate ratification"],"answer":3,"explanation":"Under Article 2(9), the parties can tighten phase-out schedules by adjustment, binding on all of them, whereas adding new substances (as with HFCs at Kigali) needs an amendment that each party ratifies. This let the phase-out be accelerated quickly as the science advanced.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"मॉन्ट्रियल प्रोटोकॉल की प्रायः उसके लचीलेपन के लिए प्रशंसा की जाती है क्योंकि पहले से नियंत्रित पदार्थों की चरणबद्ध समाप्ति अनुसूचियों में 'समायोजन':","optionsHi":["किसी के लिए भी लागू होने से पहले प्रत्येक पक्ष द्वारा अभिपुष्ट किए जाने चाहिए","केवल विकसित देशों पर लागू होते हैं, विकासशील देशों पर कभी नहीं","एक पक्ष द्वारा अपने ही क्षेत्र के लिए किए जा सकते हैं","अलग अभिपुष्टि के बिना सभी पक्षों पर बाध्यकारी हो जाते हैं"],"explanationHi":"अनुच्छेद 2(9) के अंतर्गत पक्ष समायोजन द्वारा चरणबद्ध समाप्ति अनुसूचियों को कड़ा कर सकते हैं, जो सभी पर बाध्यकारी होता है, जबकि नए पदार्थ जोड़ने (जैसे किगाली में HFC) के लिए संशोधन चाहिए जिसकी प्रत्येक पक्ष अभिपुष्टि करे। इससे विज्ञान के आगे बढ़ने पर चरणबद्ध समाप्ति को शीघ्र तेज़ किया जा सका।"},
  {"id":"env-ecology-858","question":"The first Conference of the Parties (COP-1) to the UNFCCC, held in 1995, is known for the 'Berlin Mandate'. It took place at:","options":["Geneva","Kyoto","Berlin","Rio de Janeiro"],"answer":2,"explanation":"COP-1 in Berlin agreed that the commitments of developed countries were inadequate and launched talks that led to the Kyoto Protocol at COP-3 in 1997. Rio de Janeiro hosted the 1992 Earth Summit, not a COP.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1995 में आयोजित UNFCCC के पक्षकारों का पहला सम्मेलन (COP-1) 'बर्लिन अधिदेश' के लिए जाना जाता है। यह कहाँ हुआ?","optionsHi":["जिनेवा","क्योटो","बर्लिन","रियो डी जेनेरो"],"explanationHi":"बर्लिन में COP-1 ने सहमति दी कि विकसित देशों की प्रतिबद्धताएँ अपर्याप्त हैं और ऐसी वार्ताएँ शुरू कीं जिनसे 1997 में COP-3 में क्योटो प्रोटोकॉल बना। रियो डी जेनेरो ने 1992 के पृथ्वी शिखर सम्मेलन की मेज़बानी की, किसी COP की नहीं।"},
  {"id":"env-ecology-859","question":"The Green Climate Fund, now headquartered at Songdo in South Korea, was established by a decision of the UNFCCC at:","options":["COP-16 at Cancún in 2010","COP-15 at Copenhagen in 2009","COP-21 at Paris in 2015","COP-13 at Bali in 2007"],"answer":0,"explanation":"The Copenhagen Accord proposed a fund, but the GCF was formally set up by the Cancún Agreements (COP-16). It later became an operating entity of the financial mechanism for the Paris Agreement as well.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हरित जलवायु कोष, जिसका मुख्यालय अब दक्षिण कोरिया के सोंगदो में है, UNFCCC के किस सम्मेलन (COP) के निर्णय द्वारा स्थापित हुआ?","optionsHi":["कैनकुन में COP-16, 2010 में","कोपेनहेगन में COP-15, 2009 में","पेरिस में COP-21, 2015 में","बाली में COP-13, 2007 में"],"explanationHi":"कोपेनहेगन समझौते ने एक कोष प्रस्तावित किया, परंतु GCF औपचारिक रूप से कैनकुन समझौतों (COP-16) द्वारा स्थापित हुआ। बाद में वह पेरिस समझौते के वित्तीय तंत्र की संचालन इकाई भी बन गया।"},
  {"id":"env-ecology-860","question":"The 'Durban Platform for Enhanced Action', agreed at COP-17 in 2011, is important because it:","options":["Set up the Clean Development Mechanism under the Kyoto Protocol for the first time","Launched talks on a new agreement for all parties, to be adopted by 2015","Created the Intergovernmental Panel on Climate Change under WMO and UNEP","Adopted the Kyoto Protocol's first commitment period, running from 2008 to 2012"],"answer":1,"explanation":"Durban started negotiations for an agreement covering developed and developing countries alike, which produced the Paris Agreement in 2015. The CDM was created by Kyoto itself (1997) and the IPCC dates from 1988.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2011 में COP-17 में सहमत 'संवर्धित कार्रवाई के लिए डरबन मंच' महत्त्वपूर्ण इसलिए है क्योंकि उसने:","optionsHi":["पहली बार क्योटो प्रोटोकॉल के अंतर्गत स्वच्छ विकास तंत्र स्थापित किया","सभी पक्षों के लिए नए समझौते की वार्ताएँ शुरू कीं, जिसे 2015 तक अपनाया जाना था","WMO और UNEP के अंतर्गत जलवायु परिवर्तन पर अंतर-सरकारी पैनल की रचना की","क्योटो प्रोटोकॉल की पहली प्रतिबद्धता अवधि अपनाई, जो 2008 से 2012 तक चली"],"explanationHi":"डरबन ने विकसित और विकासशील दोनों प्रकार के देशों को शामिल करने वाले समझौते की वार्ता शुरू की, जिससे 2015 में पेरिस समझौता बना। CDM की रचना क्योटो (1997) ने ही की थी और IPCC 1988 का है।"},
  {"id":"env-ecology-861","question":"The 'Paris Rulebook', which set out detailed rules for implementing most of the Paris Agreement, was largely adopted at:","options":["COP-22 at Marrakech in 2016","COP-23 at Bonn in 2017","COP-25 at Madrid in 2019","COP-24 at Katowice in 2018"],"answer":3,"explanation":"COP-24 in Katowice, Poland, agreed most of the rules, including those for transparency and NDCs. The rules on carbon markets under Article 6 were left unresolved until COP-26 at Glasgow in 2021.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'पेरिस नियम पुस्तिका', जिसने पेरिस समझौते के अधिकांश कार्यान्वयन के लिए विस्तृत नियम निर्धारित किए, मुख्यतः कहाँ अपनाई गई?","optionsHi":["मराकेश में COP-22, 2016 में","बॉन में COP-23, 2017 में","मैड्रिड में COP-25, 2019 में","काटोवित्से में COP-24, 2018 में"],"explanationHi":"पोलैंड के काटोवित्से में COP-24 ने पारदर्शिता और NDC सहित अधिकांश नियमों पर सहमति दी। अनुच्छेद 6 के अंतर्गत कार्बन बाज़ारों के नियम 2021 में ग्लासगो के COP-26 तक अनसुलझे रहे।"},
  {"id":"env-ecology-862","question":"Under the Paris Agreement, the 'Enhanced Transparency Framework' (Article 13) requires parties to:","options":["Have their NDC targets approved by the UNFCCC secretariat before submission","Pay a penalty into the Green Climate Fund if they miss their NDC targets","Report regularly on emissions and progress, with technical expert review","Allow independent inspectors to measure emissions directly at their factories"],"answer":2,"explanation":"The ETF obliges all parties, with flexibility for developing countries that need it, to submit biennial transparency reports that undergo expert review and a facilitative multilateral consideration. The agreement has no penalties and targets are nationally determined.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"पेरिस समझौते के अंतर्गत 'संवर्धित पारदर्शिता ढाँचा' (अनुच्छेद 13) पक्षों से क्या अपेक्षा करता है?","optionsHi":["प्रस्तुत करने से पहले अपने NDC लक्ष्यों को UNFCCC सचिवालय से स्वीकृत करवाना","अपने NDC लक्ष्य चूकने पर हरित जलवायु कोष में जुर्माना भरना","उत्सर्जन और प्रगति की नियमित रिपोर्ट देना, तकनीकी विशेषज्ञ समीक्षा के साथ","स्वतंत्र निरीक्षकों को अपने कारखानों में सीधे उत्सर्जन मापने देना"],"explanationHi":"ETF सभी पक्षों को, आवश्यकता वाले विकासशील देशों के लिए लचीलेपन के साथ, द्विवार्षिक पारदर्शिता रिपोर्ट प्रस्तुत करने के लिए बाध्य करता है, जिनकी विशेषज्ञ समीक्षा और सुगम बहुपक्षीय विचार होता है। समझौते में कोई दंड नहीं है और लक्ष्य राष्ट्रीय स्तर पर निर्धारित होते हैं।"},
  {"id":"env-ecology-863","question":"India hosted COP-8 of the UNFCCC in 2002, which adopted a declaration stressing that climate action must fit with sustainable development and poverty eradication. It was held at:","options":["New Delhi","Mumbai","Hyderabad","Goa"],"answer":0,"explanation":"COP-8 in New Delhi adopted the Delhi Ministerial Declaration on Climate Change and Sustainable Development, reflecting developing countries' emphasis on adaptation and development needs.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत ने 2002 में UNFCCC के COP-8 की मेज़बानी की, जिसने यह घोषणा अपनाई कि जलवायु कार्रवाई को सतत विकास और गरीबी उन्मूलन के साथ तालमेल बिठाना चाहिए। यह कहाँ आयोजित हुआ?","optionsHi":["नई दिल्ली","मुंबई","हैदराबाद","गोवा"],"explanationHi":"नई दिल्ली में COP-8 ने जलवायु परिवर्तन और सतत विकास पर दिल्ली मंत्रिस्तरीय घोषणा अपनाई, जो अनुकूलन और विकास की आवश्यकताओं पर विकासशील देशों के बल को दर्शाती है।"},
  {"id":"env-ecology-864","question":"Which one of the following was NOT an outcome of the UN Conference on Environment and Development (Earth Summit) held at Rio de Janeiro in 1992?","options":["The Rio Declaration on Environment and Development","Agenda 21","The Forest Principles","The Kyoto Protocol"],"answer":3,"explanation":"Rio produced the Rio Declaration, Agenda 21 and the non-binding Forest Principles, and opened the UNFCCC and CBD for signature. The Kyoto Protocol was adopted five years later at COP-3 in Japan.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"1992 में रियो डी जेनेरो में आयोजित पर्यावरण और विकास पर संयुक्त राष्ट्र सम्मेलन (पृथ्वी शिखर सम्मेलन) का निम्नलिखित में से कौन-सा परिणाम नहीं था?","optionsHi":["पर्यावरण और विकास पर रियो घोषणा","एजेंडा 21","वन सिद्धांत","क्योटो प्रोटोकॉल"],"explanationHi":"रियो ने रियो घोषणा, एजेंडा 21 और गैर-बाध्यकारी वन सिद्धांत दिए, और UNFCCC तथा CBD को हस्ताक्षर के लिए खोला। क्योटो प्रोटोकॉल पाँच वर्ष बाद जापान में COP-3 में अपनाया गया।"},
  {"id":"env-ecology-865","question":"A species can be placed in a CITES Appendix by a single party acting on its own, without a vote of the Conference of the Parties. That Appendix is:","options":["Appendix I","Appendix III","Appendix II","None, since every listing needs a two-thirds vote"],"answer":1,"explanation":"Appendix III lists species protected in at least one country that asks others for help in controlling trade; the party can add them unilaterally. Changes to Appendices I and II need a two-thirds majority at a CoP.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"किसी प्रजाति को CITES के परिशिष्ट में पक्षकारों के सम्मेलन के मत के बिना, अकेला एक पक्ष अपने स्तर पर रख सकता है। वह परिशिष्ट है:","optionsHi":["परिशिष्ट I","परिशिष्ट III","परिशिष्ट II","कोई नहीं, क्योंकि प्रत्येक सूचीकरण के लिए दो-तिहाई मत चाहिए"],"explanationHi":"परिशिष्ट III में वे प्रजातियाँ सूचीबद्ध हैं जो कम से कम एक ऐसे देश में संरक्षित हैं जो व्यापार नियंत्रित करने में दूसरों की सहायता माँगता है; पक्ष उन्हें एकतरफ़ा जोड़ सकता है। परिशिष्ट I और II में परिवर्तन के लिए CoP में दो-तिहाई बहुमत चाहिए।"},
  {"id":"env-ecology-866","question":"The Global Tiger Forum, the only intergovernmental body set up solely to conserve tigers, has its secretariat at:","options":["New Delhi","Kathmandu","Bangkok","Dhaka"],"answer":0,"explanation":"The GTF was formed in the 1990s with its secretariat in New Delhi; it works with tiger range countries, for example on the St Petersburg goal of doubling wild tigers.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"वैश्विक बाघ मंच, जो केवल बाघों के संरक्षण के लिए स्थापित एकमात्र अंतर-सरकारी निकाय है, का सचिवालय कहाँ है?","optionsHi":["नई दिल्ली","काठमांडू","बैंकॉक","ढाका"],"explanationHi":"GTF का गठन 1990 के दशक में हुआ और उसका सचिवालय नई दिल्ली में है; वह बाघ परास वाले देशों के साथ कार्य करता है, उदाहरण के लिए सेंट पीटर्सबर्ग लक्ष्य पर, जो वन्य बाघों को दोगुना करने का है।"},
  {"id":"env-ecology-867","question":"The Basel Convention (1989) was negotiated largely in response to:","options":["The Bhopal gas leak of 1984 and the thousands of resulting deaths in India","The discovery of the Antarctic ozone hole by British scientists in the mid-1980s","Cases of rich countries' hazardous waste being dumped in Africa","The Chernobyl nuclear disaster of 1986 and the spread of radioactive fallout"],"answer":2,"explanation":"Episodes such as the 1988 dumping of toxic waste at Koko in Nigeria exposed a trade in which rich countries shipped wastes to poorer ones, leading to the convention on transboundary movement of hazardous wastes.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"बेसल अभिसमय (1989) पर मुख्यतः किसकी प्रतिक्रिया में वार्ता हुई?","optionsHi":["1984 की भोपाल गैस त्रासदी और भारत में उससे हुई हज़ारों मौतें","1980 के दशक के मध्य में ब्रिटिश वैज्ञानिकों द्वारा अंटार्कटिक ओज़ोन छिद्र की खोज","अमीर देशों के खतरनाक अपशिष्ट को अफ़्रीका में डंप किए जाने के मामले","1986 की चेर्नोबिल परमाणु आपदा और रेडियोधर्मी विकिरण पतन का फैलाव"],"explanationHi":"नाइजीरिया के कोको में 1988 में विषैले अपशिष्ट के डंपिंग जैसी घटनाओं ने उस व्यापार को उजागर किया जिसमें अमीर देश अपशिष्ट गरीब देशों को भेजते थे, जिससे खतरनाक अपशिष्टों के सीमापारीय संचलन पर अभिसमय बना।"},
  {"id":"env-ecology-868","question":"On joining the Ramsar Convention, a country is required to:","options":["Ban all fishing and farming activity in every wetland within its territory","Pay a fixed annual fee per hectare of its wetlands to the Ramsar secretariat","Hand over the management of its listed wetlands to an international body","Designate at least one suitable wetland for the Ramsar List"],"answer":3,"explanation":"Article 2 requires each party to designate at least one site; parties also commit to the 'wise use' of all their wetlands and to international cooperation. Wise use permits sustainable human use such as fishing.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"रामसर अभिसमय में शामिल होने पर किसी देश से क्या अपेक्षित है?","optionsHi":["अपने क्षेत्र की प्रत्येक आर्द्रभूमि में सभी मछली पकड़ने और कृषि गतिविधियों पर प्रतिबंध लगाना","अपनी आर्द्रभूमियों के प्रति हेक्टेयर के हिसाब से रामसर सचिवालय को निश्चित वार्षिक शुल्क देना","अपनी सूचीबद्ध आर्द्रभूमियों का प्रबंधन किसी अंतर्राष्ट्रीय निकाय को सौंपना","रामसर सूची के लिए कम से कम एक उपयुक्त आर्द्रभूमि नामित करना"],"explanationHi":"अनुच्छेद 2 प्रत्येक पक्ष से कम से कम एक स्थल नामित करने की अपेक्षा करता है; पक्ष अपनी सभी आर्द्रभूमियों के 'विवेकपूर्ण उपयोग' और अंतर्राष्ट्रीय सहयोग के लिए भी प्रतिबद्ध होते हैं। विवेकपूर्ण उपयोग मछली पकड़ने जैसे सतत मानवीय उपयोग की अनुमति देता है।"},
  {"id":"env-ecology-869","question":"The World Day to Combat Desertification and Drought, linked to the UNCCD, is observed every year on:","options":["5 June","17 June","22 April","16 September"],"answer":1,"explanation":"17 June marks the adoption of the UNCCD text in 1994. 5 June is World Environment Day, 22 April Earth Day and 16 September the International Day for the Preservation of the Ozone Layer.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"UNCCD से जुड़ा विश्व मरुस्थलीकरण और सूखा रोकथाम दिवस प्रतिवर्ष कब मनाया जाता है?","optionsHi":["5 जून","17 जून","22 अप्रैल","16 सितंबर"],"explanationHi":"17 जून 1994 में UNCCD के पाठ को अपनाए जाने का दिन है। 5 जून विश्व पर्यावरण दिवस है, 22 अप्रैल पृथ्वी दिवस और 16 सितंबर ओज़ोन परत संरक्षण का अंतर्राष्ट्रीय दिवस।"},
  {"id":"env-ecology-870","question":"Match the IPCC Working Group with its area. A. Working Group I  B. Working Group II  C. Working Group III; 1. Mitigation of climate change  2. Impacts, adaptation and vulnerability  3. The physical science basis","options":["A-1, B-2, C-3","A-2, B-3, C-1","A-3, B-2, C-1","A-3, B-1, C-2"],"answer":2,"explanation":"Working Group I covers the physical science of climate change, Working Group II impacts, adaptation and vulnerability, and Working Group III mitigation; a separate task force handles national greenhouse gas inventories.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"IPCC कार्य समूह का उसके क्षेत्र से मिलान कीजिए। A. कार्य समूह I B. कार्य समूह II C. कार्य समूह III; 1. जलवायु परिवर्तन का शमन 2. प्रभाव, अनुकूलन और संवेदनशीलता 3. भौतिक विज्ञान आधार","optionsHi":["A-1, B-2, C-3","A-2, B-3, C-1","A-3, B-2, C-1","A-3, B-1, C-2"],"explanationHi":"कार्य समूह I जलवायु परिवर्तन का भौतिक विज्ञान, कार्य समूह II प्रभाव, अनुकूलन और संवेदनशीलता, और कार्य समूह III शमन को शामिल करता है; एक अलग कार्य बल राष्ट्रीय हरितगृह गैस सूचियों को संभालता है।"},
  {"id":"env-ecology-871","question":"The UN-REDD Programme, launched in 2008 to help developing countries prepare for REDD+, is a collaboration of:","options":["FAO, UNDP and UNEP","The World Bank, IMF and WTO","UNESCO, IUCN and WWF","WMO, UNEP and the IPCC"],"answer":0,"explanation":"UN-REDD brings together the Food and Agriculture Organization, UNDP and UNEP. The World Bank runs a separate Forest Carbon Partnership Facility, and WMO with UNEP set up the IPCC.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"UN-REDD कार्यक्रम, जो 2008 में विकासशील देशों को REDD+ के लिए तैयार करने में सहायता हेतु शुरू हुआ, किसका सहयोग है?","optionsHi":["FAO, UNDP और UNEP","विश्व बैंक, IMF और WTO","UNESCO, IUCN और WWF","WMO, UNEP और IPCC"],"explanationHi":"UN-REDD खाद्य और कृषि संगठन, UNDP और UNEP को एक साथ लाता है। विश्व बैंक अलग वन कार्बन साझेदारी सुविधा चलाता है, और WMO ने UNEP के साथ IPCC की स्थापना की।"},
  {"id":"env-ecology-872","question":"The International Day for the Preservation of the Ozone Layer is observed on 16 September because that date marks:","options":["The discovery of the Antarctic ozone hole in 1985","The adoption of the Vienna Convention in 1985","The entry into force of the Kigali Amendment in 2019","The signing of the Montreal Protocol in 1987"],"answer":3,"explanation":"The Montreal Protocol was signed on 16 September 1987. The Vienna Convention was adopted in March 1985, and the ozone hole was reported by British Antarctic Survey scientists in 1985.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"ओज़ोन परत संरक्षण का अंतर्राष्ट्रीय दिवस 16 सितंबर को इसलिए मनाया जाता है क्योंकि वह तिथि चिह्नित करती है:","optionsHi":["1985 में अंटार्कटिक ओज़ोन छिद्र की खोज","1985 में वियना अभिसमय को अपनाया जाना","2019 में किगाली संशोधन का लागू होना","1987 में मॉन्ट्रियल प्रोटोकॉल पर हस्ताक्षर"],"explanationHi":"मॉन्ट्रियल प्रोटोकॉल पर 16 सितंबर 1987 को हस्ताक्षर हुए। वियना अभिसमय मार्च 1985 में अपनाया गया था, और ओज़ोन छिद्र की रिपोर्ट 1985 में ब्रिटिश अंटार्कटिक सर्वेक्षण के वैज्ञानिकों ने दी।"},
  {"id":"env-ecology-873","question":"Which statement about the UN Environment Assembly (UNEA) is correct?","options":["It is the governing body of the UNFCCC and meets during each COP","It was created after Rio+20 and has universal membership of UN states","It is a tribunal that settles disputes between countries over shared rivers","It is made up of 58 member countries elected by the UN General Assembly"],"answer":1,"explanation":"UNEA replaced UNEP's 58-member Governing Council in 2012–13 and is open to all UN member states, making it the world's highest decision-making body on the environment. It meets at Nairobi; its 2022 session launched the plastics treaty talks.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"संयुक्त राष्ट्र पर्यावरण सभा (UNEA) के बारे में कौन-सा कथन सही है?","optionsHi":["यह UNFCCC का शासी निकाय है और प्रत्येक COP के दौरान बैठता है","यह रियो+20 के बाद बनी और संयुक्त राष्ट्र के राज्यों की सार्वभौमिक सदस्यता वाली है","यह एक अधिकरण है जो साझा नदियों पर देशों के बीच विवाद सुलझाता है","यह संयुक्त राष्ट्र महासभा द्वारा निर्वाचित 58 सदस्य देशों से बनी है"],"explanationHi":"UNEA ने 2012–13 में UNEP की 58-सदस्यीय शासी परिषद का स्थान लिया और सभी संयुक्त राष्ट्र सदस्य देशों के लिए खुली है, जिससे वह पर्यावरण पर विश्व का सर्वोच्च निर्णय-निर्माण निकाय है। यह नैरोबी में बैठती है; उसके 2022 के सत्र ने प्लास्टिक संधि वार्ता शुरू की।"},
  {"id":"env-ecology-874","question":"The India Cooling Action Plan, released in 2019, is notable because it:","options":["Bans the sale of all air conditioners that use any fluorinated refrigerant gas","Applies only to cold storage for farm produce and not to homes or offices","Sets a 20-year plan to cut cooling and refrigerant demand across sectors","Requires every new commercial building to install centralised air-conditioning"],"answer":2,"explanation":"India was among the first countries to prepare such a plan; it looks ahead to 2037–38 to reduce cooling demand, refrigerant demand and cooling energy use, supporting the HFC phase-down under the Kigali Amendment and thermal comfort for all.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2019 में जारी भारत शीतलन कार्य योजना इसलिए उल्लेखनीय है क्योंकि वह:","optionsHi":["किसी भी फ्लोरीनयुक्त प्रशीतक गैस का उपयोग करने वाले सभी एयर कंडीशनरों की बिक्री पर प्रतिबंध लगाती है","केवल कृषि उपज के शीत भंडारण पर लागू होती है, घरों या कार्यालयों पर नहीं","क्षेत्रों में शीतलन और प्रशीतक माँग घटाने की 20 वर्ष की योजना निर्धारित करती है","प्रत्येक नई वाणिज्यिक इमारत में केंद्रीकृत वातानुकूलन लगाना अनिवार्य करती है"],"explanationHi":"भारत ऐसी योजना तैयार करने वाले पहले देशों में था; यह 2037–38 तक देखती है ताकि शीतलन माँग, प्रशीतक माँग और शीतलन ऊर्जा उपयोग घटे, जो किगाली संशोधन के अंतर्गत HFC में कमी और सभी के लिए तापीय आराम का समर्थन करती है।"},
  {"id":"env-ecology-875","question":"Jerdon's courser, a nocturnal bird thought to be extinct until it was rediscovered in 1986, is known only from the scrub jungle of:","options":["The Desert National Park near Jaisalmer in Rajasthan","The Banni grasslands of the Kutch region in Gujarat","Sri Lankamalleswara Wildlife Sanctuary in Andhra Pradesh","The Great Indian Bustard Sanctuary near Solapur, Maharashtra"],"answer":2,"explanation":"After decades without records, Jerdon's courser was found again near Lankamalla in Andhra Pradesh's Kadapa district, its only known stronghold.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जर्डन का कोर्सर, एक निशाचर पक्षी जिसे 1986 में पुनः खोजे जाने तक विलुप्त माना जाता था, केवल कहाँ के झाड़ीदार जंगल से ज्ञात है?","optionsHi":["राजस्थान में जैसलमेर के निकट मरुस्थल राष्ट्रीय उद्यान","गुजरात के कच्छ क्षेत्र के बन्नी घास के मैदान","आंध्र प्रदेश में श्री लंकामल्लेश्वर वन्यजीव अभयारण्य","महाराष्ट्र में सोलापुर के निकट ग्रेट इंडियन बस्टर्ड अभयारण्य"],"explanationHi":"दशकों तक कोई अभिलेख न मिलने के बाद जर्डन का कोर्सर आंध्र प्रदेश के कडप्पा ज़िले में लंकामल्ला के निकट फिर मिला, जो उसका एकमात्र ज्ञात गढ़ है।"},
  {"id":"env-ecology-876","question":"The forest owlet, rediscovered in 1997 after more than a century without any confirmed record, lives in:","options":["The dry deciduous forests of central and western India","The evergreen rainforests of the Andaman and Nicobar Islands","The oak forests of the western Himalaya","The mangroves of the Sundarbans"],"answer":0,"explanation":"Rediscovered in Maharashtra, the forest owlet survives in teak-dominated dry deciduous forests such as Melghat and Toranmal. Many old 'specimens' had been fraudulent, which delayed the search.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"वन उल्लू, जो एक सदी से अधिक किसी पुष्ट अभिलेख के बिना रहने के बाद 1997 में पुनः खोजा गया, कहाँ रहता है?","optionsHi":["मध्य और पश्चिमी भारत के शुष्क पर्णपाती वन","अंडमान और निकोबार द्वीप समूह के सदाबहार वर्षावन","पश्चिमी हिमालय के ओक वन","सुंदरबन के मैंग्रोव"],"explanationHi":"महाराष्ट्र में पुनः खोजा गया वन उल्लू मेलघाट और तोरणमाल जैसे सागौन-प्रधान शुष्क पर्णपाती वनों में जीवित है। अनेक पुराने 'नमूने' जाली निकले थे, जिससे खोज में विलंब हुआ।"},
  {"id":"env-ecology-877","question":"The sarus crane, the state bird of Uttar Pradesh, is notable as:","options":["The only crane that migrates to India from Siberia","The tallest flying bird in the world","India's largest bird of prey","A bird that breeds only in the high Himalaya"],"answer":1,"explanation":"Standing up to about 1.8 m, the resident sarus is the world's tallest flying bird and nests in wetlands and paddy fields of the Gangetic plain.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"सारस क्रेन, उत्तर प्रदेश का राजकीय पक्षी, किस रूप में उल्लेखनीय है?","optionsHi":["साइबेरिया से भारत आने वाला एकमात्र क्रेन","विश्व का सबसे ऊँचा उड़ने वाला पक्षी","भारत का सबसे बड़ा शिकारी पक्षी","ऐसा पक्षी जो केवल ऊँचे हिमालय में प्रजनन करता है"],"explanationHi":"लगभग 1.8 m तक ऊँचा, निवासी सारस विश्व का सबसे ऊँचा उड़ने वाला पक्षी है और गंगा के मैदान की आर्द्रभूमियों और धान के खेतों में घोंसला बनाता है।"},
  {"id":"env-ecology-878","question":"In India, the black-necked crane breeds in summer in the high-altitude wetlands of Ladakh and spends the winter mainly in:","options":["The salt flats of the Little Rann of Kutch in Gujarat","The Keoladeo National Park wetlands at Bharatpur","The brackish lagoon of Chilika Lake in coastal Odisha","The Sangti and Zemithang valleys of Arunachal Pradesh"],"answer":3,"explanation":"Black-necked cranes winter in valleys of western Arunachal Pradesh and in Bhutan, after breeding on the Tibetan plateau and in Ladakh's Changthang.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत में काली गर्दन वाला क्रेन गर्मियों में लद्दाख की उच्च-ऊँचाई वाली आर्द्रभूमियों में प्रजनन करता है और शीतकाल मुख्यतः कहाँ बिताता है?","optionsHi":["गुजरात में कच्छ के छोटे रण के लवणीय समतल","भरतपुर में केओलादेव राष्ट्रीय उद्यान की आर्द्रभूमियाँ","तटीय ओडिशा में चिल्का झील की खारी लैगून","अरुणाचल प्रदेश की सांगती और ज़ेमिथांग घाटियाँ"],"explanationHi":"काली गर्दन वाले क्रेन तिब्बती पठार और लद्दाख के चांगथांग में प्रजनन के बाद पश्चिमी अरुणाचल प्रदेश की घाटियों और भूटान में शीतकाल बिताते हैं।"},
  {"id":"env-ecology-879","question":"The western population of the Siberian crane, which used to spend the winter in Keoladeo National Park, has not been seen there since about:","options":["1972","1985","2002","2015"],"answer":2,"explanation":"The last Siberian cranes were recorded at Bharatpur around the winter of 2001–02; hunting along the long migratory route through Afghanistan and Pakistan is blamed for the population's collapse.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"साइबेरियाई क्रेन की पश्चिमी समष्टि, जो केओलादेव राष्ट्रीय उद्यान में शीतकाल बिताती थी, वहाँ लगभग किस वर्ष से नहीं देखी गई है?","optionsHi":["1972","1985","2002","2015"],"explanationHi":"अंतिम साइबेरियाई क्रेन भरतपुर में लगभग 2001–02 की सर्दियों में दर्ज किए गए; अफ़गानिस्तान और पाकिस्तान से होकर लंबे प्रवास मार्ग पर शिकार को समष्टि के ढहने के लिए उत्तरदायी माना जाता है।"},
  {"id":"env-ecology-880","question":"The white-bellied heron, one of the world's rarest herons and Critically Endangered, is found in India mainly along rivers in:","options":["Namdapha in Arunachal Pradesh","The Western Ghats of Kerala","The Chambal ravines of Madhya Pradesh","The Gulf of Kutch in Gujarat"],"answer":0,"explanation":"The heron survives in tiny numbers along undisturbed rivers of Namdapha and adjacent areas, in Bhutan and in Myanmar; dams and disturbance threaten its habitat.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सफ़ेद पेट वाला बगुला, विश्व के सबसे दुर्लभ बगुलों में से एक और घोर संकटग्रस्त, भारत में मुख्यतः किन स्थानों की नदियों के किनारे पाया जाता है?","optionsHi":["अरुणाचल प्रदेश में नामदफा","केरल का पश्चिमी घाट","मध्य प्रदेश के चंबल के बीहड़","गुजरात में कच्छ की खाड़ी"],"explanationHi":"बगुला नामदफा और आसपास के क्षेत्रों, भूटान और म्यांमार की अबाधित नदियों के किनारे बहुत कम संख्या में जीवित है; बाँध और विक्षोभ उसके आवास के लिए खतरा हैं।"},
  {"id":"env-ecology-881","question":"The great hornbill is the state bird of:","options":["Kerala and Arunachal Pradesh","Karnataka and Assam","Tamil Nadu and Arunachal Pradesh","Goa and Nagaland"],"answer":0,"explanation":"Both Kerala and Arunachal Pradesh chose the great hornbill. Its wide distribution across the Western Ghats and north-east mirrors the shared Indo-Malayan character of these forests.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"बड़ा धनेश (ग्रेट हॉर्नबिल) किन राज्यों का राजकीय पक्षी है?","optionsHi":["केरल और अरुणाचल प्रदेश","कर्नाटक और असम","तमिलनाडु और अरुणाचल प्रदेश","गोवा और नागालैंड"],"explanationHi":"केरल और अरुणाचल प्रदेश दोनों ने बड़े धनेश को चुना। पश्चिमी घाट और पूर्वोत्तर में उसका व्यापक वितरण इन वनों के साझा इंडो-मलायी चरित्र को दर्शाता है।"},
  {"id":"env-ecology-882","question":"The Himalayan monal, a brilliantly iridescent pheasant, is the state bird of:","options":["Himachal Pradesh","Sikkim","Uttarakhand","Jammu and Kashmir"],"answer":2,"explanation":"The Himalayan monal is Uttarakhand's state bird (and Nepal's national bird). Himachal Pradesh's state bird is the western tragopan.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"हिमालयी मोनाल, एक चमकीला इंद्रधनुषी तीतर (फ़ीज़ेंट), किस राज्य का राजकीय पक्षी है?","optionsHi":["हिमाचल प्रदेश","सिक्किम","उत्तराखंड","जम्मू और कश्मीर"],"explanationHi":"हिमालयी मोनाल उत्तराखंड का राजकीय पक्षी है (और नेपाल का राष्ट्रीय पक्षी)। हिमाचल प्रदेश का राजकीय पक्षी पश्चिमी ट्रैगोपैन है।"},
  {"id":"env-ecology-883","question":"Mrs Hume's pheasant, a bar-tailed pheasant of the north-eastern hills, is the state bird of:","options":["Assam and Tripura","Arunachal Pradesh and Sikkim","Meghalaya and Nagaland","Mizoram and Manipur"],"answer":3,"explanation":"Mizoram and Manipur both chose Mrs Hume's pheasant, named after the wife of the ornithologist A. O. Hume.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"श्रीमती ह्यूम का फ़ीज़ेंट, उत्तर-पूर्वी पहाड़ियों का धारीदार पूँछ वाला तीतर, किन राज्यों का राजकीय पक्षी है?","optionsHi":["असम और त्रिपुरा","अरुणाचल प्रदेश और सिक्किम","मेघालय और नागालैंड","मिज़ोरम और मणिपुर"],"explanationHi":"मिज़ोरम और मणिपुर दोनों ने श्रीमती ह्यूम के फ़ीज़ेंट को चुना, जिसका नाम पक्षी-विज्ञानी ए. ओ. ह्यूम की पत्नी के नाम पर रखा गया।"},
  {"id":"env-ecology-884","question":"The Indian skimmer, which nests on river sandbars such as those of the Chambal, is unusual among birds because:","options":["It dives from great heights to catch fish underwater","Its lower mandible is longer than the upper one","It feeds only at night on insects attracted to water","It carries water to its chicks in its breast feathers"],"answer":1,"explanation":"The skimmer flies low with its long lower mandible slicing the surface and snaps shut on fish it touches. Sand mining and disturbance of sandbars threaten its nesting.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारतीय स्किमर, जो चंबल जैसी नदियों की रेतीली पट्टियों पर घोंसला बनाता है, पक्षियों में असामान्य इसलिए है क्योंकि:","optionsHi":["वह बड़ी ऊँचाइयों से गोता लगाकर पानी के नीचे मछली पकड़ता है","उसकी निचली चंचु ऊपरी चंचु से लंबी होती है","वह केवल रात में जल की ओर आकर्षित कीटों को खाता है","वह अपने चूजों के लिए अपने वक्ष के पंखों में पानी ले जाता है"],"explanationHi":"स्किमर नीचे उड़ता है, उसकी लंबी निचली चंचु सतह को चीरती है और छूई गई मछली पर झट से बंद हो जाती है। रेत खनन और रेतीली पट्टियों में विक्षोभ उसके घोंसला बनाने के लिए खतरा हैं।"},
  {"id":"env-ecology-885","question":"'Flamingo City', one of the largest breeding colonies of flamingos in Asia, is located in the:","options":["Great Rann of Kachchh, Gujarat","Nal Sarovar Bird Sanctuary, Gujarat","Point Calimere, Tamil Nadu","Chilika Lake, Odisha"],"answer":0,"explanation":"Flamingos nest on mudflats of the Great Rann when monsoon rains flood it. Sambhar and Chilika host many wintering flamingos, but the breeding colonies are in the Rann.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'फ्लेमिंगो सिटी', जो एशिया में राजहंसों (फ्लेमिंगो) की सबसे बड़ी प्रजनन बस्तियों में से एक है, कहाँ स्थित है?","optionsHi":["गुजरात में कच्छ का बड़ा रण","गुजरात में नल सरोवर पक्षी अभयारण्य","तमिलनाडु में पॉइंट कैलिमियर","ओडिशा में चिल्का झील"],"explanationHi":"राजहंस बड़े रण के कीचड़ के मैदानों पर तब घोंसला बनाते हैं जब मानसूनी वर्षा से वह जलमग्न हो जाता है। सांभर और चिल्का में अनेक शीतकालीन राजहंस आते हैं, परंतु प्रजनन बस्तियाँ रण में हैं।"},
  {"id":"env-ecology-886","question":"The bar-headed goose is famous for migrating between Central Asia and India by flying over the Himalaya at great heights. Which of the following helps it do this?","options":["It flies only by gliding on rising warm air currents","It stops to breathe at oxygen-rich glacial lakes","It flies only at night, when the air contains more oxygen","Its haemoglobin binds oxygen very readily at low pressure"],"answer":3,"explanation":"A high-affinity haemoglobin, large lungs and dense muscle capillaries let it fly where oxygen is scarce. The proportion of oxygen in air does not change by night; it is total pressure that falls with altitude.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पट्टीदार सिर वाली हंस मध्य एशिया और भारत के बीच हिमालय के ऊपर बड़ी ऊँचाइयों पर उड़कर प्रवास के लिए प्रसिद्ध है। इसमें निम्नलिखित में से क्या उसकी सहायता करता है?","optionsHi":["वह केवल ऊपर उठती गर्म वायु धाराओं पर तैरकर उड़ता है","वह साँस लेने के लिए ऑक्सीजन-समृद्ध हिमनदी झीलों पर रुकता है","वह केवल रात में उड़ता है, जब वायु में अधिक ऑक्सीजन होती है","उसका हीमोग्लोबिन कम दाब पर ऑक्सीजन को बहुत आसानी से बाँध लेता है"],"explanationHi":"उच्च-आसक्ति वाला हीमोग्लोबिन, बड़े फेफड़े और घनी पेशी केशिकाएँ उसे वहाँ उड़ने देते हैं जहाँ ऑक्सीजन दुर्लभ है। वायु में ऑक्सीजन का अनुपात रात में नहीं बदलता; ऊँचाई के साथ कुल दाब घटता है।"},
  {"id":"env-ecology-887","question":"Which of the following pairs of Indian birds are both listed by the IUCN as 'Critically Endangered (Possibly Extinct)'?","options":["Great Indian bustard and Bengal florican","Pink-headed duck and Himalayan quail","Siberian crane and white-bellied heron","Sarus crane and Indian skimmer"],"answer":1,"explanation":"Neither the pink-headed duck nor the Himalayan quail has been reliably recorded for many decades. The bustard, florican, Siberian crane and heron are Critically Endangered but known to survive.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारतीय पक्षियों के निम्नलिखित जोड़ों में से कौन-से दोनों IUCN द्वारा 'घोर संकटग्रस्त (संभवतः विलुप्त)' सूचीबद्ध हैं?","optionsHi":["ग्रेट इंडियन बस्टर्ड और बंगाल फ्लोरिकन","गुलाबी सिर वाली बत्तख और हिमालयी बटेर","साइबेरियाई क्रेन और सफ़ेद पेट वाला बगुला","सारस क्रेन और भारतीय स्किमर"],"explanationHi":"न तो गुलाबी सिर वाली बत्तख और न ही हिमालयी बटेर कई दशकों से विश्वसनीय रूप से दर्ज हुई है। बस्टर्ड, फ्लोरिकन, साइबेरियाई क्रेन और बगुला घोर संकटग्रस्त हैं परंतु जीवित ज्ञात हैं।"},
  {"id":"env-ecology-888","question":"The edible-nest swiftlet of the Andaman and Nicobar Islands is threatened by the harvesting of its nests, which are made almost entirely of:","options":["Mud mixed with chopped seaweed fibres","Woven grass and feathers","Twigs bound with spider silk","Hardened strands of its own saliva"],"answer":3,"explanation":"Swiftlets build cup-shaped nests from saliva in dark caves, and these are prized for bird's-nest soup. Over-harvesting before the chicks fledge caused steep declines.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अंडमान और निकोबार द्वीप समूह की खाद्य-घोंसले वाली अबाबील (स्विफ्टलेट) अपने घोंसलों की कटाई से संकट में है, जो लगभग पूरी तरह किससे बने होते हैं?","optionsHi":["कटे समुद्री शैवाल के रेशों में मिली मिट्टी","बुनी हुई घास और पंख","मकड़ी के रेशम से बँधी टहनियाँ","उसकी अपनी लार के कठोर हुए तंतु"],"explanationHi":"अबाबीलें अँधेरी गुफाओं में लार से कटोरीनुमा घोंसले बनाती हैं, जिनकी पक्षी-घोंसला सूप के लिए माँग रहती है। चूजों के उड़ने से पहले अत्यधिक कटाई से भारी गिरावट आई।"},
  {"id":"env-ecology-889","question":"The lesser florican, a small bustard of western and central Indian grasslands, is best known for:","options":["Nesting in tree holes in dry deciduous forests of central India","Spending the winter only on high meadows of the western Himalaya","Males leaping repeatedly into the air in display during the monsoon","Feeding in large mixed flocks on coastal mudflats of the east coast"],"answer":2,"explanation":"Breeding males make dramatic vertical leaps above the tall monsoon grass to attract females; loss of these seasonal grasslands has made it one of India's most threatened birds.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"छोटा फ्लोरिकन (लेसर फ्लोरिकन), पश्चिमी और मध्य भारतीय घास के मैदानों का छोटा बस्टर्ड, किसके लिए सर्वाधिक जाना जाता है?","optionsHi":["मध्य भारत के शुष्क पर्णपाती वनों में वृक्ष-कोटरों में घोंसला बनाना","शीतकाल केवल पश्चिमी हिमालय के ऊँचे चारागाहों में बिताना","मानसून में प्रदर्शन के लिए नरों का बार-बार हवा में उछलना","पूर्वी तट के तटीय कीचड़ के मैदानों पर बड़े मिश्रित झुंडों में चरना"],"explanationHi":"प्रजनन करने वाले नर मादाओं को आकर्षित करने के लिए ऊँची मानसूनी घास के ऊपर नाटकीय ऊर्ध्वाधर छलाँग लगाते हैं; इन मौसमी घास के मैदानों की हानि ने उसे भारत के सबसे संकटग्रस्त पक्षियों में से एक बना दिया है।"},
  {"id":"env-ecology-890","question":"Consider the following statements about the king cobra: 1. It feeds mainly on other snakes. 2. The female builds a nest of leaf litter and guards her eggs. 3. It is the longest venomous snake in the world. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Its scientific name Ophiophagus means 'snake-eater'; it is the only snake known to build a nest, and it can exceed five metres, the longest of all venomous snakes.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"किंग कोबरा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वह मुख्यतः अन्य साँपों को खाता है। 2. मादा पत्तियों के अवकर्कट का घोंसला बनाती है और अपने अंडों की रखवाली करती है। 3. वह विश्व का सबसे लंबा विषैला साँप है। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"उसका वैज्ञानिक नाम ओफ़ियोफ़ैगस का अर्थ 'साँप-भक्षी' है; वह घोंसला बनाने वाला एकमात्र ज्ञात साँप है, और वह पाँच मीटर से अधिक लंबा हो सकता है, जो सभी विषैले साँपों में सबसे लंबा है।"},
  {"id":"env-ecology-891","question":"The broad-snouted freshwater crocodile found in rivers, lakes and reservoirs across most of India is the:","options":["Gharial","Saltwater crocodile","Mugger","Caiman"],"answer":2,"explanation":"The mugger or marsh crocodile is widespread in fresh water. The gharial has a thin snout and lives in a few rivers, the saltwater crocodile is restricted to coastal mangroves, and caimans are American.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भारत के अधिकांश भाग की नदियों, झीलों और जलाशयों में पाया जाने वाला चौड़ी थूथन वाला मीठे जल का मगरमच्छ कौन-सा है?","optionsHi":["घड़ियाल","खारे जल का मगरमच्छ","मगर","केमन"],"explanationHi":"मगर या दलदली मगरमच्छ मीठे जल में व्यापक है। घड़ियाल की पतली थूथन होती है और वह कुछ नदियों में रहता है, खारे जल का मगरमच्छ तटीय मैंग्रोव तक सीमित है, और केमन अमेरिकी हैं।"},
  {"id":"env-ecology-892","question":"The northern river terrapin (Batagur baska), a Critically Endangered turtle, survives in India mainly in:","options":["The Sundarbans","The Chambal river","The backwaters of Kerala","The Gulf of Kutch"],"answer":0,"explanation":"This large estuarine turtle lives in the tidal creeks of the Sundarbans, where a captive breeding programme supports it. The Chambal holds other species such as the red-crowned roofed turtle.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"उत्तरी नदी टेरापिन (बटागुर बास्का), एक घोर संकटग्रस्त कछुआ, भारत में मुख्यतः कहाँ जीवित है?","optionsHi":["सुंदरबन में","चंबल नदी में","केरल के अप्रवाही जल (बैकवाटर) में","कच्छ की खाड़ी में"],"explanationHi":"यह बड़ा ज्वारनदमुखीय कछुआ सुंदरबन की ज्वारीय खाड़ियों में रहता है, जहाँ बंदी प्रजनन कार्यक्रम उसका समर्थन करता है। चंबल में लाल मुकुट वाला छत्र कछुआ जैसी अन्य प्रजातियाँ हैं।"},
  {"id":"env-ecology-893","question":"In 2019, the Conference of the Parties to CITES moved which Indian reptile, heavily smuggled for the pet trade, to Appendix I?","options":["Indian rock python","Bengal monitor lizard","Indian flapshell turtle","Indian star tortoise"],"answer":3,"explanation":"At CoP-18 the star tortoise was uplisted to Appendix I on India's proposal, banning commercial international trade. Its attractive shell pattern drives illegal collection.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2019 में CITES के पक्षकारों के सम्मेलन ने किस भारतीय सरीसृप को, जिसकी पालतू व्यापार के लिए भारी तस्करी होती है, परिशिष्ट I में रखा?","optionsHi":["भारतीय चट्टानी अजगर","बंगाल मॉनिटर छिपकली","भारतीय फ़्लैपशेल कछुआ","भारतीय तारा कछुआ"],"explanationHi":"CoP-18 में भारत के प्रस्ताव पर तारा कछुए को परिशिष्ट I में उन्नत किया गया, जिससे वाणिज्यिक अंतर्राष्ट्रीय व्यापार प्रतिबंधित हो गया। उसके आकर्षक कवच का प्रतिरूप अवैध संग्रहण को बढ़ाता है।"},
  {"id":"env-ecology-894","question":"The golden mahseer (Tor putitora), a large game fish sometimes called the 'tiger of the water', lives mainly in:","options":["Brackish lagoons and backwaters of the east coast","Coral reefs of Lakshadweep","Fast-flowing rivers of the Himalayan region","Saline lakes of Rajasthan"],"answer":2,"explanation":"The golden mahseer inhabits clear, fast Himalayan and sub-Himalayan rivers and migrates upstream to breed, so dams that block its movement are a major threat.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"गोल्डन महसीर (टोर पुटिटोरा), एक बड़ी शिकार-योग्य मछली जिसे कभी-कभी 'जल का बाघ' कहा जाता है, मुख्यतः कहाँ रहती है?","optionsHi":["पूर्वी तट की खारी लैगूनों और अप्रवाही जल में","लक्षद्वीप की प्रवाल भित्तियों में","हिमालयी क्षेत्र की तेज़ बहने वाली नदियों में","राजस्थान की लवणीय झीलों में"],"explanationHi":"गोल्डन महसीर स्वच्छ, तेज़ हिमालयी और उप-हिमालयी नदियों में रहती है और प्रजनन के लिए धारा के विपरीत जाती है, इसलिए उसके आवागमन को रोकने वाले बाँध एक बड़ा खतरा हैं।"},
  {"id":"env-ecology-895","question":"The humpback mahseer, a giant fish endemic to the Kaveri basin and now Critically Endangered, has declined partly because of:","options":["Competition from the introduced blue-finned mahseer","Overfishing of its eggs for the international caviar trade","Warming of the sea where it spawns","Pollution from oil drilling in the river delta"],"answer":0,"explanation":"Stocking of the non-native blue-finned mahseer for angling, along with dams and sand mining, pushed the humpback mahseer close to extinction.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कूबड़ वाली महसीर (हंपबैक महसीर), कावेरी बेसिन की स्थानिक विशाल मछली जो अब घोर संकटग्रस्त है, आंशिक रूप से किस कारण घटी है?","optionsHi":["लाई गई नीले पंख वाली महसीर से प्रतिस्पर्धा","अंतर्राष्ट्रीय कैवियार व्यापार के लिए उसके अंडों की अत्यधिक मछली पकड़ाई","समुद्र का गर्म होना जहाँ वह अंडे देती है","नदी डेल्टा में तेल खुदाई से प्रदूषण"],"explanationHi":"शिकार (एंगलिंग) के लिए गैर-देशी नीले पंख वाली महसीर के संग्रहण, बाँधों और रेत खनन के साथ, ने कूबड़ वाली महसीर को विलुप्ति के निकट धकेल दिया।"},
  {"id":"env-ecology-896","question":"The hilsa swims from the Bay of Bengal up rivers such as the Hooghly and Padma to spawn in fresh water. Such a fish is described as:","options":["Catadromous","Potamodromous","Oceanodromous","Anadromous"],"answer":3,"explanation":"Anadromous fish live in the sea and breed in rivers; catadromous fish, such as freshwater eels, do the opposite. Barrages such as Farakka have reduced the hilsa's upstream run.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हिल्सा बंगाल की खाड़ी से हुगली और पद्मा जैसी नदियों में मीठे जल में अंडे देने के लिए ऊपर की ओर तैरती है। ऐसी मछली को कहा जाता है:","optionsHi":["सागरगामी प्रजननी (कैटाड्रोमस)","नदीय प्रवासी (पोटामोड्रोमस)","महासागरीय प्रवासी (ओशनोड्रोमस)","नदीगामी प्रजननी (एनाड्रोमस)"],"explanationHi":"एनाड्रोमस मछलियाँ समुद्र में रहती हैं और नदियों में प्रजनन करती हैं; कैटाड्रोमस मछलियाँ, जैसे मीठे जल की ईल, इसका उलटा करती हैं। फरक्का जैसे बैराजों ने हिल्सा के ऊपरी प्रवाह की ओर आगमन को घटा दिया है।"},
  {"id":"env-ecology-897","question":"The Malabar gliding frog of the Western Ghats can glide from tree to tree because:","options":["It inflates air sacs on both sides of its body like a balloon","It has broad, fully webbed feet that act like parachutes","Its skin folds stretch between its fore and hind limbs","It leaps using its strong tail as a spring"],"answer":1,"explanation":"Large webbing between its long toes lets it descend at a controlled angle. Frogs have no tail as adults, and skin folds between the limbs are the gliding method of flying squirrels.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पश्चिमी घाट का मालाबार ग्लाइडिंग (तैरता) मेंढक एक वृक्ष से दूसरे वृक्ष तक इसलिए तैर सकता है क्योंकि:","optionsHi":["वह अपने शरीर के दोनों ओर की वायु थैलियों को गुब्बारे की तरह फुला लेता है","उसके चौड़े, पूर्णतः जालयुक्त पैर पैराशूट की तरह काम करते हैं","उसकी त्वचा की तहें उसके अगले और पिछले अंगों के बीच तन जाती हैं","वह अपनी मज़बूत पूँछ को कमानी की तरह उपयोग करके छलाँग लगाता है"],"explanationHi":"उसकी लंबी उँगलियों के बीच बड़ा जाल उसे नियंत्रित कोण पर उतरने देता है। वयस्क मेंढकों की पूँछ नहीं होती, और अंगों के बीच त्वचा की तहें उड़ने वाली गिलहरियों की तैरने की विधि है।"},
  {"id":"env-ecology-898","question":"In 2001, the whale shark became the first fish species to be placed in Schedule I of the Wildlife (Protection) Act. Which of the following statements about it is correct?","options":["It is a mammal that must surface to breathe air like a whale","It is the largest living fish and feeds mainly on plankton","It is a fierce predator of dolphins and seals","It lives only in fresh water near river mouths"],"answer":1,"explanation":"Despite its name, the whale shark is a fish, the world's largest, and a gentle filter-feeder. A community campaign in Gujarat turned fishermen from hunting it to rescuing it from nets.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"2001 में व्हेल शार्क वन्यजीव (संरक्षण) अधिनियम की अनुसूची I में रखी जाने वाली पहली मछली प्रजाति बनी। उसके बारे में निम्नलिखित में से कौन-सा कथन सही है?","optionsHi":["वह स्तनधारी है जिसे व्हेल की तरह हवा में साँस लेने के लिए सतह पर आना पड़ता है","वह सबसे बड़ी जीवित मछली है और मुख्यतः प्लवक खाती है","वह डॉल्फ़िनों और सीलों की उग्र परभक्षी है","वह केवल नदी मुहानों के निकट मीठे जल में रहती है"],"explanationHi":"नाम के बावजूद व्हेल शार्क एक मछली है, विश्व की सबसे बड़ी, और सौम्य निस्यंदक-भक्षी। गुजरात में सामुदायिक अभियान ने मछुआरों को उसके शिकार से हटाकर उसे जालों से बचाने की ओर मोड़ा।"},
  {"id":"env-ecology-899","question":"The Ganges shark (Glyphis gangeticus), listed as Critically Endangered, is unusual because it:","options":["Lives only in the deep sea far beyond the continental shelf","Is a river shark of the Hooghly and other tidal rivers","Is found only in cold, high-altitude lakes of the Himalaya","Feeds by filtering plankton like the whale shark"],"answer":1,"explanation":"It is one of the few sharks adapted to rivers and estuaries, recorded mainly from the Hooghly–Ganga system; it is often confused with the bull shark.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"गंगा शार्क (ग्लाइफ़िस गैंजेटिकस), जो घोर संकटग्रस्त सूचीबद्ध है, असामान्य इसलिए है क्योंकि वह:","optionsHi":["केवल महाद्वीपीय मग्न तट से बहुत दूर गहरे समुद्र में रहती है","हुगली और अन्य ज्वारीय नदियों की नदी शार्क है","केवल हिमालय की ठंडी, उच्च-ऊँचाई वाली झीलों में पाई जाती है","व्हेल शार्क की तरह प्लवक को छानकर भोजन करती है"],"explanationHi":"यह उन थोड़ी शार्कों में है जो नदियों और ज्वारनदमुखों के अनुकूल हैं, मुख्यतः हुगली–गंगा तंत्र से दर्ज; इसे प्रायः बुल शार्क समझ लिया जाता है।"},
  {"id":"env-ecology-900","question":"Caecilians, several species of which are found in the Western Ghats and north-east India, are best described as:","options":["Legless lizards related to snakes","Larval stages of salamanders","Limbless, mostly burrowing amphibians","Primitive earthworms that have developed a backbone"],"answer":2,"explanation":"Caecilians are amphibians that have lost their limbs and live mostly in moist soil; they look like large earthworms or snakes but have a skull and backbone and breathe partly through their skin.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सीसिलियन, जिनकी कई प्रजातियाँ पश्चिमी घाट और पूर्वोत्तर भारत में पाई जाती हैं, का सबसे उपयुक्त वर्णन है:","optionsHi":["साँपों से संबंधित पादरहित छिपकलियाँ","सैलामैंडरों की डिंभक अवस्थाएँ","पादरहित, अधिकांशतः बिल बनाने वाले उभयचर","आदिम केंचुए जिनमें रीढ़ विकसित हो गई है"],"explanationHi":"सीसिलियन उभयचर हैं जिन्होंने अपने अंग खो दिए हैं और अधिकांशतः नम मृदा में रहते हैं; वे बड़े केंचुओं या साँपों जैसे दिखते हैं, पर उनकी खोपड़ी और रीढ़ होती है और वे आंशिक रूप से त्वचा से साँस लेते हैं।"},
  {"id":"env-ecology-901","question":"Solar photovoltaic panels in Rajasthan often produce less power at noon in May than on a clear, cooler day in February with similar sunlight. The main reason is that:","options":["Silicon cells stop absorbing visible light once they become warm","Summer sunlight contains less ultraviolet light, which PV cells mainly use","The conversion efficiency of PV cells falls as their temperature rises","The inverters switch off automatically whenever the air is above 40 °C"],"answer":2,"explanation":"Higher cell temperature lowers the voltage of a silicon cell, cutting output by roughly 0.4–0.5 per cent per °C above 25 °C. Dust also matters, but the temperature effect explains the summer drop under similar irradiance.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"राजस्थान में सौर प्रकाश-वोल्टीय पैनल मई की दोपहर में प्रायः फरवरी के समान धूप वाले साफ़, ठंडे दिन की तुलना में कम बिजली बनाते हैं। इसका मुख्य कारण है:","optionsHi":["गर्म हो जाने पर सिलिकॉन सेल दृश्य प्रकाश को अवशोषित करना बंद कर देते हैं","गर्मियों के सूर्य प्रकाश में पराबैंगनी प्रकाश कम होता है, जिसका PV सेल मुख्यतः उपयोग करते हैं","तापमान बढ़ने के साथ PV सेलों की रूपांतरण दक्षता घट जाती है","वायु का तापमान 40 °C से ऊपर होने पर इन्वर्टर अपने आप बंद हो जाते हैं"],"explanationHi":"उच्च सेल तापमान सिलिकॉन सेल का वोल्टता घटाता है, जिससे 25 °C से ऊपर प्रति °C लगभग 0.4–0.5 प्रतिशत उत्पादन घटता है। धूल भी मायने रखती है, पर समान विकिरण पर गर्मियों की गिरावट को तापमान का प्रभाव समझाता है।"},
  {"id":"env-ecology-902","question":"'Bifacial' solar modules, increasingly used in Indian solar parks, can give higher output than ordinary modules because they:","options":["Also capture light reflected from the ground onto their rear side","Track the Sun automatically from east to west through the day","Use two layers of silicon, so they convert infrared light as well","Store part of the electricity in a battery built into the panel"],"answer":0,"explanation":"Bifacial panels have a transparent back, so light reflected by bright ground (sand, white gravel) adds to generation, with gains depending on ground albedo and mounting height. Tracking and storage are separate technologies.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारतीय सौर पार्कों में बढ़ते उपयोग वाले 'द्विमुखी' (बाइफेशियल) सौर मॉड्यूल साधारण मॉड्यूलों से अधिक उत्पादन दे सकते हैं क्योंकि वे:","optionsHi":["भूमि से परावर्तित प्रकाश को भी अपनी पिछली सतह पर ग्रहण करते हैं","दिन भर सूर्य को पूर्व से पश्चिम तक स्वतः अनुसरण करते हैं","सिलिकॉन की दो परतों का उपयोग करते हैं, इसलिए अवरक्त प्रकाश को भी रूपांतरित करते हैं","बिजली का कुछ भाग पैनल में बनी बैटरी में संचित करते हैं"],"explanationHi":"द्विमुखी पैनलों की पीठ पारदर्शी होती है, इसलिए चमकीली भूमि (रेत, सफ़ेद बजरी) से परावर्तित प्रकाश उत्पादन में जुड़ता है, जिसका लाभ भूमि के एल्बिडो और स्थापना ऊँचाई पर निर्भर करता है। अनुसरण और भंडारण अलग प्रौद्योगिकियाँ हैं।"},
  {"id":"env-ecology-903","question":"If the wind speed at a turbine site rises from 5 m/s to 10 m/s, the power available in the wind increases by a factor of about:","options":["2","4","6","8"],"answer":3,"explanation":"Power in the wind is proportional to the cube of wind speed (P = ½ρAv³), so doubling speed gives 2³ = 8 times the power. This is why small differences in average wind speed matter greatly in choosing sites.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"यदि किसी टर्बाइन स्थल पर पवन की चाल 5 m/s से बढ़कर 10 m/s हो जाए, तो पवन में उपलब्ध शक्ति लगभग कितने गुना बढ़ जाती है?","optionsHi":["2","4","6","8"],"explanationHi":"पवन की शक्ति पवन चाल के घन के समानुपाती है (P = ½ρAv³), इसलिए चाल दोगुनी करने पर 2³ = 8 गुना शक्ति मिलती है। इसीलिए स्थल चुनने में औसत पवन चाल के छोटे अंतर बहुत मायने रखते हैं।"},
  {"id":"env-ecology-904","question":"According to Betz's law, the maximum fraction of the kinetic energy in the wind that any turbine can capture is about:","options":["100 per cent, if the blades are perfectly designed","59 per cent","33 per cent","90 per cent, minus friction losses"],"answer":1,"explanation":"A turbine cannot stop the air completely, or no more air would flow through it; the theoretical limit is 16/27, about 59.3 per cent. Real turbines reach roughly 40–50 per cent.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"बेट्ज़ के नियम के अनुसार, पवन में गतिज ऊर्जा का वह अधिकतम अंश जिसे कोई भी टर्बाइन ग्रहण कर सकता है, लगभग है:","optionsHi":["100 प्रतिशत, यदि पंखुड़ियाँ पूर्णतः डिज़ाइन की गई हों","59 प्रतिशत","33 प्रतिशत","90 प्रतिशत, घर्षण हानियाँ घटाकर"],"explanationHi":"टर्बाइन हवा को पूरी तरह नहीं रोक सकता, वरना उससे और हवा बहेगी ही नहीं; सैद्धांतिक सीमा 16/27, यानी लगभग 59.3 प्रतिशत है। वास्तविक टर्बाइन लगभग 40–50 प्रतिशत तक पहुँचते हैं।"},
  {"id":"env-ecology-905","question":"The main advantage of offshore wind farms over onshore ones is that at sea:","options":["Winds are generally stronger and steadier, so turbines yield more","Turbines need no foundations at all, so they cost far less to build","Salty sea air cools the generators, so they never need any maintenance","There is no need for any transmission lines to bring the power to land"],"answer":0,"explanation":"The smooth sea surface causes less friction, so winds are faster and less turbulent, raising the capacity factor. Offshore projects cost more because of foundations, undersea cables and corrosion.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"स्थलीय पवन फार्मों की तुलना में अपतटीय पवन फार्मों का मुख्य लाभ यह है कि समुद्र में:","optionsHi":["पवनें सामान्यतः अधिक प्रबल और स्थिर होती हैं, इसलिए टर्बाइन अधिक उत्पादन देते हैं","टर्बाइनों को नींव की बिल्कुल आवश्यकता नहीं होती, इसलिए निर्माण लागत बहुत कम होती है","खारी समुद्री हवा जनरेटरों को ठंडा रखती है, इसलिए उन्हें कभी रखरखाव की आवश्यकता नहीं होती","बिजली को तट तक लाने के लिए किसी पारेषण लाइन की आवश्यकता नहीं होती"],"explanationHi":"समतल समुद्री सतह कम घर्षण उत्पन्न करती है, इसलिए पवनें तेज़ और कम विक्षुब्ध होती हैं, जिससे क्षमता उपयोग गुणक बढ़ता है। अपतटीय परियोजनाओं की लागत नींव, समुद्र के नीचे केबल और संक्षारण के कारण अधिक होती है।"},
  {"id":"env-ecology-906","question":"In India, hydropower projects classified as 'small hydro' under the Ministry of New and Renewable Energy are those with a capacity of up to:","options":["5 MW","10 MW","25 MW","100 MW"],"answer":2,"explanation":"Plants up to 25 MW are classed as small hydro and handled by MNRE. Large hydro was declared a renewable source in 2019 but remains under the Ministry of Power.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत में नवीन और नवीकरणीय ऊर्जा मंत्रालय के अंतर्गत 'लघु जल-विद्युत' के रूप में वर्गीकृत जल-विद्युत परियोजनाएँ वे हैं जिनकी क्षमता कितनी तक हो?","optionsHi":["5 MW","10 MW","25 MW","100 MW"],"explanationHi":"25 MW तक के संयंत्र लघु जल-विद्युत के रूप में वर्गीकृत हैं और MNRE द्वारा संभाले जाते हैं। बड़ी जल-विद्युत को 2019 में नवीकरणीय स्रोत घोषित किया गया, पर वह विद्युत मंत्रालय के अंतर्गत ही रहती है।"},
  {"id":"env-ecology-907","question":"A pumped storage hydropower plant helps a grid with a large share of solar and wind power mainly because it:","options":["Generates more electricity over each day than it consumes in pumping","Produces power with no reservoir at all, using only the river's flow","Burns biomass in its turbines whenever reservoir water levels are low","Pumps water uphill with surplus power and releases it at peak demand"],"answer":3,"explanation":"Pumped storage is a large battery: it consumes more energy than it returns (losses of about 20–30 per cent), but shifts energy from hours of surplus, such as sunny afternoons, to evening peaks.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"सौर और पवन ऊर्जा के बड़े हिस्से वाले ग्रिड में पंप्ड भंडारण जल-विद्युत संयंत्र मुख्यतः इसलिए सहायक होता है क्योंकि वह:","optionsHi":["प्रत्येक दिन पंपन में खपत से अधिक बिजली उत्पन्न करता है","बिना किसी जलाशय के, केवल नदी के प्रवाह से बिजली उत्पन्न करता है","जलाशय का जल स्तर कम होने पर अपने टर्बाइनों में जैव-ईंधन जलाता है","अधिशेष बिजली से जल को ऊपर की ओर पंप करता है और अधिकतम माँग पर उसे छोड़ता है"],"explanationHi":"पंप्ड भंडारण एक बड़ी बैटरी है: यह लौटाने से अधिक ऊर्जा की खपत करता है (लगभग 20–30 प्रतिशत हानियाँ), पर ऊर्जा को अधिशेष के घंटों, जैसे धूप वाली दोपहर, से शाम की अधिकतम माँग में स्थानांतरित करता है।"},
  {"id":"env-ecology-908","question":"Which of the following regions of India are considered to have the highest potential for tidal energy?","options":["The Konkan coast and the Gulf of Mannar in Tamil Nadu","The Gulfs of Khambhat and Kutch, and the Sundarbans","The Malabar coast and the Lakshadweep islands","The coasts of Andhra Pradesh and Odisha"],"answer":1,"explanation":"Tidal power needs a large tidal range; the funnel-shaped Gulf of Khambhat has a range of up to about 11 m, the Gulf of Kutch about 8 m, and the Sundarbans delta is also suitable. The west-coast and Gulf of Mannar ranges are small.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत के निम्नलिखित में से किन क्षेत्रों में ज्वारीय ऊर्जा की सर्वाधिक संभावना मानी जाती है?","optionsHi":["कोंकण तट और तमिलनाडु में मन्नार की खाड़ी","खंभात और कच्छ की खाड़ियाँ, और सुंदरबन","मालाबार तट और लक्षद्वीप द्वीप","आंध्र प्रदेश और ओडिशा के तट"],"explanationHi":"ज्वारीय शक्ति के लिए बड़ा ज्वारीय परास चाहिए; कीप के आकार की खंभात की खाड़ी का परास लगभग 11 m तक, कच्छ की खाड़ी का लगभग 8 m है, और सुंदरबन डेल्टा भी उपयुक्त है। पश्चिमी तट और मन्नार की खाड़ी के परास छोटे हैं।"},
  {"id":"env-ecology-909","question":"Biodiesel made from the seeds of Jatropha curcas is produced mainly by:","options":["Transesterification of the oil with methanol, giving glycerol as a by-product","Fermenting the seed cake with yeast to produce ethanol and carbon dioxide","Gasifying the dried seeds at high temperature to give hydrogen and carbon monoxide","Distilling the crushed seeds directly to separate diesel-like hydrocarbons"],"answer":0,"explanation":"The vegetable oil reacts with an alcohol (usually methanol) and a catalyst to form fatty acid methyl esters (biodiesel) and glycerol. Jatropha was favoured because its oil is non-edible and the plant grows on poor land.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जेट्रोफा करकस के बीजों से बनने वाला बायोडीज़ल मुख्यतः किसके द्वारा बनाया जाता है?","optionsHi":["तेल का मेथनॉल के साथ ट्रांसएस्टरीकरण, जिसमें ग्लिसरॉल उप-उत्पाद के रूप में मिलता है","बीज खली का यीस्ट से किण्वन करके एथेनॉल और कार्बन डाइऑक्साइड बनाना","सूखे बीजों का उच्च तापमान पर गैसीकरण करके हाइड्रोजन और कार्बन मोनोऑक्साइड बनाना","कुचले बीजों का सीधे आसवन करके डीज़ल-सदृश हाइड्रोकार्बन अलग करना"],"explanationHi":"वनस्पति तेल एक अल्कोहल (प्रायः मेथनॉल) और उत्प्रेरक से अभिक्रिया करके वसा अम्ल मेथिल एस्टर (बायोडीज़ल) और ग्लिसरॉल बनाता है। जेट्रोफा इसलिए पसंद किया गया क्योंकि उसका तेल अखाद्य है और पौधा निम्न भूमि पर उगता है।"},
  {"id":"env-ecology-910","question":"India's three-stage nuclear power programme is designed ultimately to make use of the country's large reserves of:","options":["Uranium, through light water reactors in all three stages","Plutonium, mined from deposits in Jharkhand","Thorium, found in the monazite sands of the coast","Deuterium, extracted from seawater for fusion"],"answer":2,"explanation":"Stage one uses natural uranium in pressurised heavy water reactors, stage two uses plutonium in fast breeder reactors that also breed uranium-233 from thorium, and stage three runs on thorium–U-233. India has modest uranium but large thorium reserves.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत का त्रि-चरणीय परमाणु ऊर्जा कार्यक्रम अंततः देश के किन बड़े भंडारों का उपयोग करने के लिए बनाया गया है?","optionsHi":["यूरेनियम, तीनों चरणों में हल्के जल रिएक्टरों के माध्यम से","प्लूटोनियम, जो झारखंड के निक्षेपों से खोदा जाता है","थोरियम, जो तट की मोनाज़ाइट रेत में पाया जाता है","ड्यूटेरियम, जो संलयन के लिए समुद्री जल से निकाला जाता है"],"explanationHi":"पहला चरण दाबित भारी जल रिएक्टरों में प्राकृतिक यूरेनियम का उपयोग करता है, दूसरा चरण फास्ट ब्रीडर रिएक्टरों में प्लूटोनियम का उपयोग करता है जो थोरियम से यूरेनियम-233 भी बनाते हैं, और तीसरा चरण थोरियम–U-233 पर चलता है। भारत में यूरेनियम सीमित पर थोरियम के बड़े भंडार हैं।"},
  {"id":"env-ecology-911","question":"A 100 MW solar plant operates at an annual capacity utilisation factor of 20 per cent. About how much electricity does it generate in a year?","options":["876 GWh","175 GWh","438 GWh","17.5 GWh"],"answer":1,"explanation":"Energy = 100 MW × 8,760 hours × 0.20 = 175,200 MWh, about 175 GWh. 876 GWh would need the plant to run at full output all year, which is why rated capacity overstates solar output compared with coal plants.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"100 MW का एक सौर संयंत्र 20 प्रतिशत के वार्षिक क्षमता उपयोग गुणक पर संचालित होता है। वह एक वर्ष में लगभग कितनी बिजली उत्पन्न करता है?","optionsHi":["876 GWh","175 GWh","438 GWh","17.5 GWh"],"explanationHi":"ऊर्जा = 100 MW × 8,760 घंटे × 0.20 = 175,200 MWh, यानी लगभग 175 GWh। 876 GWh के लिए संयंत्र को पूरे वर्ष पूर्ण उत्पादन पर चलना पड़ता, इसीलिए रेटेड क्षमता कोयला संयंत्रों की तुलना में सौर उत्पादन को अधिक दर्शाती है।"},
  {"id":"env-ecology-912","question":"The 'duck curve', discussed in power systems with much solar generation, describes:","options":["The steady fall in the price of solar panels over the past two decades","The sharp drop in solar output during the monsoon months every year","The rise in deaths of water birds near solar parks built on wetlands","Net demand dipping at midday and then ramping up steeply at sunset"],"answer":3,"explanation":"When demand minus solar output is plotted over a day, the midday trough and steep evening rise as the sun sets look like a duck's outline. It creates a need for flexible plants, storage and demand shifting.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"बहुत अधिक सौर उत्पादन वाली विद्युत प्रणालियों में चर्चित 'डक कर्व' (बत्तख वक्र) किसका वर्णन करता है?","optionsHi":["पिछले दो दशकों में सौर पैनलों की कीमत में लगातार गिरावट","हर वर्ष मानसून के महीनों में सौर उत्पादन में तीव्र गिरावट","आर्द्रभूमियों पर बने सौर पार्कों के निकट जलपक्षियों की मौतों में वृद्धि","दोपहर में शुद्ध माँग का घटना और फिर सूर्यास्त पर तेज़ी से बढ़ना"],"explanationHi":"जब किसी दिन में माँग घटा सौर उत्पादन आलेखित किया जाता है, तो दोपहर की गर्त और सूर्यास्त पर शाम की तीव्र वृद्धि बत्तख की रूपरेखा जैसी दिखती है। इससे लचीले संयंत्रों, भंडारण और माँग-स्थानांतरण की आवश्यकता पैदा होती है।"},
  {"id":"env-ecology-913","question":"The National Green Hydrogen Mission, approved by India in January 2023, aims at a green hydrogen production capacity by 2030 of at least:","options":["5 million tonnes per year","50 million tonnes per year","0.5 million tonnes per year","500 million tonnes per year"],"answer":0,"explanation":"The mission targets about 5 MMT a year by 2030, with associated renewable capacity of about 125 GW, to cut fossil-fuel imports and decarbonise refineries, fertilisers and steel.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जनवरी 2023 में भारत द्वारा स्वीकृत राष्ट्रीय हरित हाइड्रोजन मिशन का लक्ष्य 2030 तक कम से कम कितनी हरित हाइड्रोजन उत्पादन क्षमता का है?","optionsHi":["5 मिलियन टन प्रति वर्ष","50 मिलियन टन प्रति वर्ष","0.5 मिलियन टन प्रति वर्ष","500 मिलियन टन प्रति वर्ष"],"explanationHi":"मिशन का लक्ष्य 2030 तक लगभग 5 MMT प्रति वर्ष है, जिसके साथ लगभग 125 GW की संबद्ध नवीकरणीय क्षमता है, ताकि जीवाश्म ईंधन आयात घटे और रिफ़ाइनरियों, उर्वरकों तथा इस्पात का कार्बन-मुक्तिकरण हो।"},
  {"id":"env-ecology-914","question":"The PM-KUSUM scheme, launched in 2019, mainly aims to:","options":["Provide free electric two-wheelers to rural women entrepreneurs","Fund wind turbines on the coast of Gujarat and Tamil Nadu","Promote solar pumps and solar power plants for farmers","Replace diesel generators in telecom towers with fuel cells"],"answer":2,"explanation":"KUSUM supports standalone solar pumps, solarisation of grid-connected pumps and small solar plants on farmers' land, reducing diesel use and giving farmers an income from selling surplus power.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"2019 में शुरू की गई PM-कुसुम योजना का मुख्य उद्देश्य है:","optionsHi":["ग्रामीण महिला उद्यमियों को निःशुल्क इलेक्ट्रिक दोपहिया वाहन देना","गुजरात और तमिलनाडु के तट पर पवन टर्बाइनों को वित्त पोषित करना","किसानों के लिए सौर पंप और सौर विद्युत संयंत्रों को बढ़ावा देना","दूरसंचार टावरों में डीज़ल जनरेटरों को ईंधन सेलों से बदलना"],"explanationHi":"कुसुम स्वतंत्र सौर पंपों, ग्रिड-संयोजित पंपों के सौरीकरण और किसानों की भूमि पर छोटे सौर संयंत्रों का समर्थन करता है, जिससे डीज़ल का उपयोग घटता है और किसानों को अधिशेष बिजली बेचकर आय मिलती है।"},
  {"id":"env-ecology-915","question":"Bhadla Solar Park, one of the largest solar parks in the world, is located in:","options":["Kutch district, Gujarat","Jodhpur district, Rajasthan","Anantapur district, Andhra Pradesh","Tumakuru district, Karnataka"],"answer":1,"explanation":"Bhadla in Jodhpur district has high irradiance and cheap desert land. Pavagada in Tumakuru and the Kurnool and Anantapur parks are other large Indian solar parks, which makes this a common trap.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भडला सौर पार्क, विश्व के सबसे बड़े सौर पार्कों में से एक, कहाँ स्थित है?","optionsHi":["कच्छ ज़िला, गुजरात","जोधपुर ज़िला, राजस्थान","अनंतपुर ज़िला, आंध्र प्रदेश","तुमकुरु ज़िला, कर्नाटक"],"explanationHi":"जोधपुर ज़िले के भडला में उच्च विकिरण और सस्ती मरुस्थलीय भूमि है। तुमकुरु में पावागड़ा और कुरनूल तथा अनंतपुर के पार्क अन्य बड़े भारतीय सौर पार्क हैं, जिससे यह एक आम भ्रम है।"},
  {"id":"env-ecology-916","question":"A 'Renewable Purchase Obligation' (RPO) in India requires:","options":["Renewable energy developers to buy back their own power whenever grid demand falls","Households above a set income to buy a minimum number of solar appliances every year","Coal power plants to sell a fixed share of their output to renewable energy firms","Discoms and some large consumers to buy a minimum share of renewable power"],"answer":3,"explanation":"RPOs are set under the Electricity Act for obligated entities such as discoms, open-access consumers and captive users; they can meet them by buying renewable power or Renewable Energy Certificates.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत में 'नवीकरणीय क्रय दायित्व' (RPO) किससे अपेक्षा करता है?","optionsHi":["नवीकरणीय ऊर्जा डेवलपरों से, ग्रिड माँग घटने पर अपनी ही बिजली वापस खरीदना","एक निर्धारित आय से ऊपर के परिवारों से, प्रत्येक वर्ष न्यूनतम संख्या में सौर उपकरण खरीदना","कोयला विद्युत संयंत्रों से, अपने उत्पादन का निश्चित हिस्सा नवीकरणीय ऊर्जा कंपनियों को बेचना","डिस्कॉम और कुछ बड़े उपभोक्ताओं से, नवीकरणीय बिजली का न्यूनतम हिस्सा खरीदना"],"explanationHi":"RPO विद्युत अधिनियम के अंतर्गत डिस्कॉम, खुली पहुँच वाले उपभोक्ताओं और कैप्टिव उपयोगकर्ताओं जैसी बाध्य इकाइयों के लिए निर्धारित होते हैं; वे इन्हें नवीकरणीय बिजली या नवीकरणीय ऊर्जा प्रमाणपत्र खरीदकर पूरा कर सकते हैं।"},
  {"id":"env-ecology-917","question":"Under 'net metering' for a house with rooftop solar panels:","options":["The household is billed only for the difference between power drawn and fed in","The household must consume all of its own solar power and cannot export any of it","The household is paid for all of its solar generation at a fixed rate, separately","The household's meter is removed, and it pays a flat monthly fee for all power used"],"answer":0,"explanation":"A bidirectional meter records imports and exports, so surplus daytime solar offsets night-time consumption. In gross metering, by contrast, all generation is sold to the grid at a fixed tariff.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"रूफटॉप सौर पैनल वाले घर के लिए 'नेट मीटरिंग' के अंतर्गत:","optionsHi":["परिवार से केवल ली गई और ग्रिड में दी गई बिजली के अंतर का बिल लिया जाता है","परिवार को अपनी सारी सौर बिजली स्वयं उपभोग करनी होती है और वह उसमें से कुछ भी निर्यात नहीं कर सकता","परिवार को उसके सारे सौर उत्पादन का निश्चित दर पर अलग से भुगतान किया जाता है","परिवार का मीटर हटा दिया जाता है, और वह उपयोग की सारी बिजली के लिए निश्चित मासिक शुल्क देता है"],"explanationHi":"द्विदिशीय मीटर आयात और निर्यात दर्ज करता है, इसलिए दिन की अधिशेष सौर बिजली रात की खपत की भरपाई करती है। इसके विपरीत, सकल मीटरिंग में सारा उत्पादन निश्चित टैरिफ़ पर ग्रिड को बेचा जाता है।"},
  {"id":"env-ecology-918","question":"Garrett Hardin's 1968 essay 'The Tragedy of the Commons' argued that:","options":["Common lands are always better managed by local communities than private lands are","Industrial pollution in the world is caused mainly by poverty in developing countries","People acting in self-interest can overuse and ruin a shared, open-access resource","Population growth in any country will stop by itself once that country becomes rich"],"answer":2,"explanation":"Hardin's example was herders each adding cattle to a shared pasture until it is ruined. Elinor Ostrom later showed that communities often manage commons well through local rules, an important rejoinder.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"गैरेट हार्डिन के 1968 के निबंध 'द ट्रैजेडी ऑफ़ द कॉमन्स' का तर्क था कि:","optionsHi":["साझा भूमियाँ निजी भूमियों की तुलना में सदैव स्थानीय समुदायों द्वारा बेहतर प्रबंधित होती हैं","विश्व में औद्योगिक प्रदूषण मुख्यतः विकासशील देशों की निर्धनता से होता है","स्वार्थ में कार्य करने वाले लोग किसी साझा, खुली पहुँच वाले संसाधन का अतिउपयोग कर उसे नष्ट कर सकते हैं","किसी भी देश में जनसंख्या वृद्धि देश के धनी हो जाने पर अपने आप रुक जाएगी"],"explanationHi":"हार्डिन का उदाहरण पशुपालकों का था जो साझा चरागाह में तब तक अपने पशु बढ़ाते जाते हैं जब तक वह नष्ट न हो जाए। एलिनॉर ऑस्ट्रॉम ने बाद में दिखाया कि समुदाय प्रायः स्थानीय नियमों से साझा संसाधनों का अच्छा प्रबंधन करते हैं, जो एक महत्त्वपूर्ण उत्तर है।"},
  {"id":"env-ecology-919","question":"'The Limits to Growth' (1972), which modelled the consequences of exponential growth in population and resource use, was commissioned by:","options":["The World Bank","The Club of Rome","The UN Environment Programme","The Brundtland Commission"],"answer":1,"explanation":"A team at MIT led by Donella and Dennis Meadows produced the report for the Club of Rome, warning of overshoot and collapse within a century without change. The Brundtland Commission's 'Our Common Future' came in 1987.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'द लिमिट्स टू ग्रोथ' (1972), जिसने जनसंख्या और संसाधन उपयोग में चरघातांकी वृद्धि के परिणामों का मॉडल बनाया, किसके द्वारा प्रायोजित थी?","optionsHi":["विश्व बैंक","क्लब ऑफ़ रोम","संयुक्त राष्ट्र पर्यावरण कार्यक्रम","ब्रंटलैंड आयोग"],"explanationHi":"डोनेला और डेनिस मीडोज़ के नेतृत्व में MIT की एक टीम ने क्लब ऑफ़ रोम के लिए रिपोर्ट तैयार की, जिसमें परिवर्तन के बिना एक सदी के भीतर अतिक्रमण और पतन की चेतावनी थी। ब्रंटलैंड आयोग की 'हमारा साझा भविष्य' 1987 में आई।"},
  {"id":"env-ecology-920","question":"The 'doughnut' model of economics, proposed by Kate Raworth, describes a safe and just space for humanity that lies between:","options":["A minimum annual growth rate and a maximum inflation rate set for every economy","The remaining carbon budget for 1.5 °C and the larger one for 2 °C of warming","The average incomes of the poorest tenth and the richest tenth of humanity","A social foundation of needs and an ecological ceiling of planetary limits"],"answer":3,"explanation":"The inner ring represents shortfalls in essentials such as food, water and health; the outer ring represents overshoot of planetary boundaries such as climate change and biodiversity loss.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"केट रैवर्थ द्वारा प्रस्तावित अर्थशास्त्र का 'डोनट' मॉडल मानवता के लिए सुरक्षित और न्यायसंगत स्थान का वर्णन करता है जो किनके बीच है?","optionsHi":["प्रत्येक अर्थव्यवस्था के लिए निर्धारित न्यूनतम वार्षिक वृद्धि दर और अधिकतम मुद्रास्फीति दर","1.5 °C के लिए शेष कार्बन बजट और 2 °C तापन के लिए बड़ा बजट","मानवता के सबसे निर्धन दसवें हिस्से और सबसे धनी दसवें हिस्से की औसत आय","आवश्यकताओं की सामाजिक नींव और ग्रहीय सीमाओं की पारिस्थितिक छत"],"explanationHi":"भीतरी वलय भोजन, जल और स्वास्थ्य जैसी अनिवार्यताओं की कमी को दर्शाता है; बाहरी वलय जलवायु परिवर्तन और जैव विविधता हानि जैसी ग्रहीय सीमाओं के अतिक्रमण को दर्शाता है।"},
  {"id":"env-ecology-921","question":"A country's GDP grows by 6 per cent a year while its total carbon emissions fall by 1 per cent a year. This is an example of:","options":["Absolute decoupling of emissions from economic growth","Relative decoupling of emissions from economic growth","The rebound effect of improved energy efficiency","Carbon leakage to the country from its trading partners"],"answer":0,"explanation":"Absolute decoupling means emissions fall while output grows. If emissions rose but more slowly than GDP, it would be relative decoupling, meaning only the emissions intensity of the economy is falling.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"किसी देश का GDP प्रति वर्ष 6 प्रतिशत बढ़ता है जबकि उसका कुल कार्बन उत्सर्जन प्रति वर्ष 1 प्रतिशत घटता है। यह किसका उदाहरण है?","optionsHi":["आर्थिक वृद्धि से उत्सर्जन का निरपेक्ष वियोजन","आर्थिक वृद्धि से उत्सर्जन का सापेक्ष वियोजन","ऊर्जा दक्षता सुधार का प्रत्यावर्तन प्रभाव","व्यापारिक साझेदारों से उस देश में कार्बन रिसाव"],"explanationHi":"निरपेक्ष वियोजन का अर्थ है उत्पादन बढ़ने के साथ उत्सर्जन घटना। यदि उत्सर्जन बढ़ता पर GDP से धीमी गति से, तो यह सापेक्ष वियोजन होता, यानी केवल अर्थव्यवस्था की उत्सर्जन तीव्रता घट रही है।"},
  {"id":"env-ecology-922","question":"W. S. Jevons observed in 1865 that more efficient steam engines led to greater, not lower, total coal use in Britain. This 'Jevons paradox' is an extreme case of:","options":["Carbon leakage","The precautionary principle","The rebound effect","Diminishing marginal utility"],"answer":2,"explanation":"Efficiency lowers the effective cost of an energy service, so people use more of it; when the extra use outweighs the savings, total consumption rises. Policies on efficiency therefore often pair it with pricing or caps.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"डब्ल्यू. एस. जेवन्स ने 1865 में देखा कि अधिक दक्ष भाप इंजनों से ब्रिटेन में कोयले का कुल उपयोग घटने के बजाय बढ़ा। यह 'जेवन्स विरोधाभास' किसका चरम मामला है?","optionsHi":["कार्बन रिसाव","पूर्व-सावधानी सिद्धांत","प्रत्यावर्तन प्रभाव","ह्रासमान सीमांत उपयोगिता"],"explanationHi":"दक्षता ऊर्जा सेवा की प्रभावी लागत घटाती है, इसलिए लोग उसका अधिक उपयोग करते हैं; जब अतिरिक्त उपयोग बचत से अधिक हो जाता है, तो कुल खपत बढ़ती है। इसलिए दक्षता संबंधी नीतियाँ प्रायः उसे मूल्य निर्धारण या सीमाओं के साथ जोड़ती हैं।"},
  {"id":"env-ecology-923","question":"In the 'I = P × A × T' identity proposed by Ehrlich and Holdren, environmental impact is expressed as the product of:","options":["Investment, Pollution and Taxation","Population, Affluence and Technology","Industry, Agriculture and Transport","Income, Area and Time"],"answer":1,"explanation":"Impact depends on the number of people, consumption per person and the impact per unit of consumption set by technology. It shows that cleaner technology can offset growth in population and affluence only if it improves faster than they grow.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"एर्लिक और होल्ड्रेन द्वारा प्रस्तावित 'I = P × A × T' सूत्र में पर्यावरणीय प्रभाव को किनके गुणनफल के रूप में व्यक्त किया जाता है?","optionsHi":["निवेश, प्रदूषण और कराधान","जनसंख्या, समृद्धि और प्रौद्योगिकी","उद्योग, कृषि और परिवहन","आय, क्षेत्र और समय"],"explanationHi":"प्रभाव लोगों की संख्या, प्रति व्यक्ति उपभोग और प्रौद्योगिकी द्वारा निर्धारित उपभोग की प्रति इकाई के प्रभाव पर निर्भर करता है। यह दर्शाता है कि स्वच्छ प्रौद्योगिकी जनसंख्या और समृद्धि की वृद्धि को तभी संतुलित कर सकती है जब वह उनसे तेज़ी से सुधरे।"},
  {"id":"env-ecology-924","question":"A 'run-of-the-river' hydroelectric project differs from a conventional storage project mainly in that it:","options":["Burns biomass to pump river water up to a turbine on a hill","Can generate power only during the dry season, when flows are steady","Requires a reservoir large enough to store a full year's river flow","Uses the river's natural flow with little or no storage reservoir"],"answer":3,"explanation":"Run-of-river schemes divert flow through turbines with at most a small pondage, so they submerge less land but their output follows seasonal river flow, peaking in the monsoon and snow-melt months.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'रन-ऑफ़-द-रिवर' जल-विद्युत परियोजना पारंपरिक भंडारण परियोजना से मुख्यतः इस बात में भिन्न है कि वह:","optionsHi":["पहाड़ी पर स्थित टर्बाइन तक नदी जल को पंप करने के लिए जैव-ईंधन जलाती है","केवल शुष्क ऋतु में बिजली बना सकती है, जब प्रवाह स्थिर होता है","पूरे वर्ष के नदी प्रवाह को भंडारित करने जितना बड़ा जलाशय माँगती है","नदी के प्राकृतिक प्रवाह का उपयोग करती है, जिसमें भंडारण जलाशय कम या बिल्कुल नहीं होता"],"explanationHi":"रन-ऑफ़-रिवर योजनाएँ अधिक से अधिक छोटे पोंडेज के साथ प्रवाह को टर्बाइनों से मोड़ती हैं, इसलिए वे कम भूमि डुबोती हैं, पर उनका उत्पादन नदी के मौसमी प्रवाह का अनुसरण करता है, जो मानसून और हिम-पिघलन के महीनों में चरम पर होता है।"},
  {"id":"env-ecology-925","question":"Muppandal, one of the largest onshore wind power clusters in India, is located in:","options":["Jaisalmer district, Rajasthan","Anantapur district, Andhra Pradesh","Kanyakumari district, Tamil Nadu","Satara district, Maharashtra"],"answer":2,"explanation":"Muppandal lies near the Aralvaimozhi gap in the Western Ghats, which funnels strong monsoon winds. Jaisalmer, Anantapur and Satara also host large wind farms, which is why this is a common trap.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मुप्पंडल, भारत के सबसे बड़े स्थलीय पवन ऊर्जा समूहों में से एक, कहाँ स्थित है?","optionsHi":["जैसलमेर ज़िला, राजस्थान","अनंतपुर ज़िला, आंध्र प्रदेश","कन्याकुमारी ज़िला, तमिलनाडु","सतारा ज़िला, महाराष्ट्र"],"explanationHi":"मुप्पंडल पश्चिमी घाट के अरलवाइमोझी दर्रे के निकट है, जो प्रबल मानसूनी पवनों को केंद्रित करता है। जैसलमेर, अनंतपुर और सतारा में भी बड़े पवन फार्म हैं, इसीलिए यह एक आम भ्रम है।"},
  {"id":"env-ecology-926","question":"Young sandalwood (Santalum album) plants grow poorly in plantations unless other plants are grown alongside them. The reason is that sandalwood:","options":["Needs shade from taller trees throughout its life","Is a root hemiparasite that draws water and nutrients from host plants","Depends on nitrogen-fixing neighbours because it cannot absorb nitrate","Requires insect pollinators that nest only in neighbouring shrubs"],"answer":1,"explanation":"Sandalwood photosynthesises but attaches to roots of neighbouring plants through haustoria to obtain water and minerals, so suitable hosts are planted with it.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"चंदन (सैंटलम एल्बम) के छोटे पौधे वृक्षारोपणों में तब तक खराब बढ़ते हैं जब तक उनके साथ अन्य पौधे न उगाए जाएँ। इसका कारण यह है कि चंदन:","optionsHi":["को अपने पूरे जीवन में ऊँचे वृक्षों की छाया चाहिए","एक मूल अर्ध-परजीवी है जो पोषी पौधों से जल और पोषक तत्व लेता है","नाइट्रोजन-स्थिरीकारी पड़ोसियों पर निर्भर है क्योंकि वह नाइट्रेट अवशोषित नहीं कर सकता","को ऐसे कीट परागणकर्ता चाहिए जो केवल पास की झाड़ियों में घोंसला बनाते हैं"],"explanationHi":"चंदन प्रकाश संश्लेषण करता है, पर जल और खनिज पाने के लिए चूषकांगों के द्वारा पड़ोसी पौधों की जड़ों से जुड़ जाता है, इसलिए उसके साथ उपयुक्त पोषी पौधे लगाए जाते हैं।"},
  {"id":"env-ecology-927","question":"Red sanders (Pterocarpus santalinus), whose heartwood is heavily smuggled abroad, grows naturally only in:","options":["The Seshachalam hills and nearby ranges of Andhra Pradesh","The Nilgiri and Anamalai hills of the southern Western Ghats","The Aravalli ranges of Rajasthan and Haryana","The Chota Nagpur plateau of Jharkhand and northern Odisha"],"answer":0,"explanation":"Red sanders is endemic to a small belt of the southern Eastern Ghats in Andhra Pradesh; its narrow range makes illegal felling especially damaging.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"रक्त चंदन (टेरोकार्पस सैंटलिनस), जिसकी अंतःकाष्ठ की भारी तस्करी होती है, स्वाभाविक रूप से केवल कहाँ उगता है?","optionsHi":["आंध्र प्रदेश की शेषाचलम पहाड़ियों और निकट की श्रेणियों में","दक्षिणी पश्चिमी घाट की नीलगिरि और अन्नामलाई पहाड़ियों में","राजस्थान और हरियाणा की अरावली श्रेणियों में","झारखंड और उत्तरी ओडिशा के छोटा नागपुर पठार में"],"explanationHi":"रक्त चंदन आंध्र प्रदेश में दक्षिणी पूर्वी घाट की छोटी पट्टी का स्थानिक है; उसका संकीर्ण परास अवैध कटाई को विशेष रूप से हानिकारक बनाता है।"},
  {"id":"env-ecology-928","question":"The Himalayan yew has been heavily stripped of its bark and leaves in many areas because it is a source of:","options":["Quinine, used to treat malaria","Reserpine, used for lowering high blood pressure","Paclitaxel (taxol), used in cancer treatment","Artemisinin, used against malaria parasites"],"answer":2,"explanation":"Taxol, an anticancer drug, was first isolated from yews; demand for Himalayan yew bark led to severe over-harvesting. Reserpine comes from Rauwolfia and quinine from Cinchona.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हिमालयी यू (थ्यू) के बहुत से क्षेत्रों में छाल और पत्तियों को भारी मात्रा में उतारा गया है क्योंकि वह किसका स्रोत है?","optionsHi":["क्विनीन, जो मलेरिया के उपचार में प्रयुक्त है","रेसरपीन, जो उच्च रक्तचाप घटाने में प्रयुक्त है","पैक्लिटैक्सेल (टैक्सॉल), जो कैंसर उपचार में प्रयुक्त है","आर्टीमिसिनिन, जो मलेरिया परजीवियों के विरुद्ध प्रयुक्त है"],"explanationHi":"टैक्सॉल, एक कैंसर-रोधी औषधि, पहली बार यू वृक्षों से पृथक की गई थी; हिमालयी यू की छाल की माँग से गंभीर अतिदोहन हुआ। रेसरपीन राउवोल्फिया से और क्विनीन सिंकोना से आती है।"},
  {"id":"env-ecology-929","question":"The Brahma kamal (Saussurea obvallata), a flower of high Himalayan meadows used in religious offerings, is the state flower of:","options":["Himachal Pradesh","Sikkim","Arunachal Pradesh","Uttarakhand"],"answer":3,"explanation":"Uttarakhand chose the Brahma kamal; it blooms in alpine areas such as the Valley of Flowers and is threatened by excessive picking by pilgrims.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ब्रह्म कमल (सॉसुरिया ऑब्वैलाटा), ऊँचे हिमालयी चारागाहों का फूल जो धार्मिक चढ़ावे में प्रयुक्त होता है, किस राज्य का राजकीय पुष्प है?","optionsHi":["हिमाचल प्रदेश","सिक्किम","अरुणाचल प्रदेश","उत्तराखंड"],"explanationHi":"उत्तराखंड ने ब्रह्म कमल को चुना; यह फूलों की घाटी जैसे अल्पाइन क्षेत्रों में खिलता है और तीर्थयात्रियों द्वारा अत्यधिक तोड़े जाने से संकट में है।"},
  {"id":"env-ecology-930","question":"Rohida (Tecomella undulata), sometimes called 'Marwar teak' for its fine timber, is the state flower of:","options":["Gujarat","Haryana","Madhya Pradesh","Rajasthan"],"answer":3,"explanation":"Rohida is a tree of the Thar that helps stabilise sand dunes and bears showy orange-yellow flowers; Rajasthan adopted it as its state flower.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"रोहिड़ा (टेकोमेला अंडुलाटा), जिसे अपनी उत्तम लकड़ी के लिए कभी-कभी 'मारवाड़ का सागौन' कहा जाता है, किस राज्य का राजकीय पुष्प है?","optionsHi":["गुजरात","हरियाणा","मध्य प्रदेश","राजस्थान"],"explanationHi":"रोहिड़ा थार का वृक्ष है जो रेत के टीलों को स्थिर करने में सहायक है और आकर्षक नारंगी-पीले फूल देता है; राजस्थान ने इसे अपना राजकीय पुष्प बनाया।"},
  {"id":"env-ecology-931","question":"The hollong (Dipterocarpus macrocarpus), a tall tree of the wet evergreen forests of the north-east, is the state tree of:","options":["Meghalaya","Arunachal Pradesh","Assam","Nagaland"],"answer":2,"explanation":"Assam's state tree is the hollong, which gives its name to the Hollongapar Gibbon Sanctuary near Jorhat. Dipterocarps dominate many tropical rainforests of Asia.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"होलोंग (डिप्टेरोकार्पस मैक्रोकार्पस), पूर्वोत्तर के आर्द्र सदाबहार वनों का एक ऊँचा वृक्ष, किस राज्य का राजकीय वृक्ष है?","optionsHi":["मेघालय","अरुणाचल प्रदेश","असम","नागालैंड"],"explanationHi":"असम का राजकीय वृक्ष होलोंग है, जिसके नाम पर जोरहाट के निकट होलोंगापार गिब्बन अभयारण्य का नाम पड़ा। डिप्टेरोकार्प एशिया के अनेक उष्णकटिबंधीय वर्षावनों में प्रभावी हैं।"},
  {"id":"env-ecology-932","question":"The mahua tree (Madhuca longifolia) is important in the economy of many tribal communities of central India mainly because:","options":["Its flowers are eaten and distilled into liquor, and its seeds yield oil","Its leaves are rolled into bidis and sold as a nationalised minor forest produce","Its bark yields tannin that is used for curing leather in rural tanneries","Its milky latex is tapped and sold as natural rubber to factories"],"answer":0,"explanation":"Mahua flowers are collected for food and liquor and the seeds for edible oil. Bidi wrappers come from tendu (kendu) leaves, a different tree.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"महुआ वृक्ष (मधुका लोंगिफोलिया) मध्य भारत के अनेक आदिवासी समुदायों की अर्थव्यवस्था में मुख्यतः किस कारण महत्त्वपूर्ण है?","optionsHi":["उसके फूल खाए जाते हैं और शराब के लिए आसवित किए जाते हैं, तथा बीजों से तेल मिलता है","उसकी पत्तियाँ बीड़ियों में लपेटी और राष्ट्रीयकृत लघु वन उपज के रूप में बेची जाती हैं","उसकी छाल से टैनिन मिलता है जो ग्रामीण चर्मशोधनालयों में चमड़ा कमाने में प्रयुक्त होता है","उसका दूधिया लेटेक्स निकाला और कारखानों को प्राकृतिक रबर के रूप में बेचा जाता है"],"explanationHi":"महुआ के फूल भोजन और शराब के लिए तथा बीज खाद्य तेल के लिए एकत्र किए जाते हैं। बीड़ी के आवरण तेंदू (केंदू) की पत्तियों से आते हैं, जो अलग वृक्ष है।"},
  {"id":"env-ecology-933","question":"Leaves of which tree are collected on a large scale in central and eastern India for rolling bidis and are traded as a nationalised minor forest produce in several states?","options":["Sal","Palash","Mahua","Tendu"],"answer":3,"explanation":"Tendu or kendu leaf collection is a major seasonal income for forest dwellers; states such as Odisha and Madhya Pradesh control its trade. Sal leaves are used to make plates.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"मध्य और पूर्वी भारत में किस वृक्ष की पत्तियाँ बीड़ी लपेटने के लिए बड़े पैमाने पर एकत्र की जाती हैं और कई राज्यों में राष्ट्रीयकृत लघु वन उपज के रूप में व्यापारित होती हैं?","optionsHi":["साल","पलाश","महुआ","तेंदू"],"explanationHi":"तेंदू या केंदू पत्ता संग्रहण वनवासियों के लिए प्रमुख मौसमी आय है; ओडिशा और मध्य प्रदेश जैसे राज्य उसके व्यापार को नियंत्रित करते हैं। साल की पत्तियों से पत्तल बनाई जाती हैं।"},
  {"id":"env-ecology-934","question":"In Mizoram, the 'mautam' event that occurs about every 48–50 years is feared because:","options":["Monsoon floods sweep away the terraced hill fields in the same season","A bamboo flowers en masse and rats feeding on its seed destroy crops","Locust swarms arriving from the west devastate crops across the hills","Cyclones from the Bay of Bengal flatten the bamboo forests and villages"],"answer":1,"explanation":"Melocanna baccifera flowers gregariously and dies; rats feasting on its abundant seed multiply explosively and then devour crops, as in the famine of 1959.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"मिज़ोरम में लगभग हर 48–50 वर्ष में होने वाली 'माउतम' घटना से भय क्यों रहता है?","optionsHi":["मानसूनी बाढ़ उसी ऋतु में सीढ़ीदार पहाड़ी खेतों को बहा ले जाती है","बाँस बड़े पैमाने पर फूलता है और उसके बीज खाने वाले चूहे फसलें नष्ट कर देते हैं","पश्चिम से आए टिड्डी दल पूरी पहाड़ियों में फसलें तबाह कर देते हैं","बंगाल की खाड़ी के चक्रवात बाँस के वनों और गाँवों को ध्वस्त कर देते हैं"],"explanationHi":"मेलोकैना बैसीफेरा सामूहिक रूप से फूलता है और मर जाता है; उसके प्रचुर बीजों की दावत उड़ाने वाले चूहे विस्फोटक रूप से बढ़ते हैं और फिर फसलें खा जाते हैं, जैसा 1959 के अकाल में हुआ।"},
  {"id":"env-ecology-935","question":"The famous living root bridges of Meghalaya are made by Khasi and Jaintia villagers by training the aerial roots of:","options":["The banyan, Ficus benghalensis","The peepal, Ficus religiosa","The rubber fig, Ficus elastica","The cluster fig, Ficus racemosa"],"answer":2,"explanation":"Roots of the Indian rubber fig are guided across streams until they grow and fuse into strong bridges, some of which last for centuries.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मेघालय के प्रसिद्ध जीवित जड़ पुल खासी और जयंतिया ग्रामीणों द्वारा किसकी हवाई जड़ों को प्रशिक्षित करके बनाए जाते हैं?","optionsHi":["बरगद, फ़ाइकस बेंघालेंसिस","पीपल, फ़ाइकस रिलीजियोसा","रबर अंजीर, फ़ाइकस इलास्टिका","गूलर, फ़ाइकस रेसमोसा"],"explanationHi":"भारतीय रबर अंजीर की जड़ों को धाराओं के आर-पार तब तक निर्देशित किया जाता है जब तक वे उगकर जुड़ न जाएँ और मज़बूत पुल न बन जाएँ, जिनमें से कुछ सदियों तक टिकते हैं।"},
  {"id":"env-ecology-936","question":"Sapria himalayana, a rare flowering plant of north-east India such as Namdapha, is a close relative of Rafflesia. Which feature does it share with Rafflesia?","options":["It is a root parasite with no leaves, stem or chlorophyll","It is an epiphytic orchid that grows on tree trunks","It is an insectivorous plant with large pitcher-shaped leaves","It is a tree fern that grows above the treeline"],"answer":0,"explanation":"Like Rafflesia, Sapria lives entirely inside the roots of host vines and shows itself only as a large, foul-smelling flower that attracts carrion flies.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"सैप्रिया हिमालयाना, नामदफा जैसे पूर्वोत्तर भारत का दुर्लभ पुष्पीय पौधा, रैफ़्लेशिया का निकट संबंधी है। वह रैफ़्लेशिया के साथ कौन-सी विशेषता साझा करता है?","optionsHi":["यह पत्तियों, तने या क्लोरोफ़िल से रहित मूल परजीवी है","यह वृक्ष-तनों पर उगने वाला अधिपादपी ऑर्किड है","यह बड़े घटपर्णी पत्तों वाला कीटभक्षी पौधा है","यह वृक्ष-रेखा से ऊपर उगने वाला वृक्ष-फर्न है"],"explanationHi":"रैफ़्लेशिया की तरह सैप्रिया पूरी तरह पोषी बेलों की जड़ों के भीतर रहता है और केवल एक बड़े, दुर्गंधयुक्त फूल के रूप में प्रकट होता है जो मांस-मक्खियों को आकर्षित करता है।"},
  {"id":"env-ecology-937","question":"Guggul (Commiphora wightii), a shrub of the arid zones of Rajasthan and Gujarat, has become threatened mainly because of:","options":["Felling for its valuable timber used in carved furniture","Grazing of its leaves by camels and goats","Destructive tapping of its stems for medicinal gum resin","Clearing of the coastal mangroves where it grows"],"answer":2,"explanation":"Guggul gum resin is prized in Ayurveda, and crude, excessive tapping kills the plants; it grows in dry, rocky areas, not mangroves.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"गुग्गुल (कमिफ़ोरा विटी), राजस्थान और गुजरात के शुष्क क्षेत्रों की झाड़ी, मुख्यतः किस कारण संकटग्रस्त हो गई है?","optionsHi":["नक्काशीदार फ़र्नीचर में प्रयुक्त उसकी मूल्यवान लकड़ी के लिए कटाई","ऊँटों और बकरियों द्वारा उसकी पत्तियों की चराई","औषधीय गोंद-राल के लिए उसके तनों का विनाशकारी दोहन","तटीय मैंग्रोव की सफ़ाई, जहाँ वह उगती है"],"explanationHi":"गुग्गुल का गोंद-राल आयुर्वेद में बहुमूल्य है, और अपरिष्कृत, अत्यधिक दोहन पौधों को मार देता है; वह शुष्क, चट्टानी क्षेत्रों में उगती है, मैंग्रोव में नहीं।"},
  {"id":"env-ecology-938","question":"Kuth (Saussurea costus), a Himalayan medicinal herb whose roots were exported in large quantities, is notable for being:","options":["Declared India's national medicinal plant by the AYUSH ministry","The original natural source of the anti-malarial drug quinine","A plant that flowers only once in twelve years","Listed in CITES Appendix I, which bans its commercial trade"],"answer":3,"explanation":"Over-collection for its aromatic roots led to kuth's listing in CITES Appendix I. Quinine comes from Cinchona, and twelve-yearly flowering is a feature of neelakurinji.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कुठ (सॉसुरिया कॉस्टस), एक हिमालयी औषधीय जड़ी-बूटी जिसकी जड़ों का बड़ी मात्रा में निर्यात होता था, किस रूप में उल्लेखनीय है?","optionsHi":["AYUSH मंत्रालय द्वारा भारत का राष्ट्रीय औषधीय पौधा घोषित","मलेरिया-रोधी औषधि क्विनीन का मूल प्राकृतिक स्रोत","ऐसा पौधा जो बारह वर्ष में केवल एक बार फूलता है","CITES परिशिष्ट I में सूचीबद्ध, जो उसके वाणिज्यिक व्यापार पर प्रतिबंध लगाता है"],"explanationHi":"उसकी सुगंधित जड़ों के अत्यधिक संग्रहण के कारण कुठ CITES परिशिष्ट I में सूचीबद्ध हुआ। क्विनीन सिंकोना से आती है, और बारह-वर्षीय पुष्पन नीलकुरिंजी की विशेषता है।"},
  {"id":"env-ecology-939","question":"Yarsagumba (keeda jadi), collected in large quantities from the high meadows of Uttarakhand and Nepal, is:","options":["A fungus growing out of the bodies of infected caterpillars","The dried underground root of a rare high-altitude orchid","A slow-growing lichen found on rocks just above the snowline","The aromatic resin collected from an alpine juniper shrub"],"answer":0,"explanation":"Ophiocordyceps sinensis infects ghost-moth larvae underground and sends up a fruiting body; its high price has led to over-harvesting and conflicts over collection.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"यारसागुम्बा (कीड़ा जड़ी), जो उत्तराखंड और नेपाल के ऊँचे चारागाहों से बड़ी मात्रा में एकत्र की जाती है, है:","optionsHi":["संक्रमित इल्लियों के शरीर से उगने वाला कवक","किसी दुर्लभ उच्च-ऊँचाई ऑर्किड की सूखी भूमिगत जड़","हिमरेखा के ठीक ऊपर चट्टानों पर पाया जाने वाला धीमी वृद्धि वाला लाइकेन","किसी अल्पाइन जूनिपर झाड़ी से एकत्र सुगंधित राल"],"explanationHi":"ओफ़ियोकॉर्डिसेप्स साइनेंसिस भूमिगत घोस्ट-मॉथ के लार्वा को संक्रमित करता है और फलनकाय ऊपर भेजता है; उसकी ऊँची कीमत ने अतिदोहन और संग्रहण पर संघर्षों को जन्म दिया है।"},
  {"id":"env-ecology-940","question":"All species of lady's slipper orchids (Paphiopedilum), several of which occur in north-east India, are listed in which appendix of CITES?","options":["Appendix III","Appendix II","Appendix I","They are not listed in CITES"],"answer":2,"explanation":"Because collectors prize them, all Paphiopedilum species are in Appendix I. Most other orchids are in Appendix II, which permits regulated trade.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"लेडीज़ स्लिपर ऑर्किड (पैफ़ियोपेडिलम) की सभी प्रजातियाँ, जिनमें से कई पूर्वोत्तर भारत में पाई जाती हैं, CITES के किस परिशिष्ट में सूचीबद्ध हैं?","optionsHi":["परिशिष्ट III","परिशिष्ट II","परिशिष्ट I","वे CITES में सूचीबद्ध नहीं हैं"],"explanationHi":"संग्राहकों द्वारा बहुमूल्य माने जाने के कारण सभी पैफ़ियोपेडिलम प्रजातियाँ परिशिष्ट I में हैं। अधिकांश अन्य ऑर्किड परिशिष्ट II में हैं, जो विनियमित व्यापार की अनुमति देता है।"},
  {"id":"env-ecology-941","question":"In their classic 1968 classification of the forest types of India, Champion and Seth grouped the forests into five major groups. How many type groups did they recognise at the next level?","options":["Ten","Sixteen","Twenty-five","Two hundred"],"answer":1,"explanation":"Champion and Seth recognised 5 major groups, divided into 16 type groups (such as tropical wet evergreen and alpine scrub), which are further split into about 200 forest types.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1968 के अपने क्लासिक भारतीय वन-प्रकार वर्गीकरण में चैम्पियन और सेठ ने वनों को पाँच प्रमुख समूहों में बाँटा। अगले स्तर पर उन्होंने कितने प्रकार समूह माने?","optionsHi":["दस","सोलह","पच्चीस","दो सौ"],"explanationHi":"चैम्पियन और सेठ ने 5 प्रमुख समूह माने, जो 16 प्रकार समूहों (जैसे उष्णकटिबंधीय आर्द्र सदाबहार और अल्पाइन झाड़ी) में बँटे हैं, जो आगे लगभग 200 वन प्रकारों में विभाजित हैं।"},
  {"id":"env-ecology-942","question":"According to the forest type mapping based on Champion and Seth's classification, which forest type group covers the largest area in India?","options":["Tropical wet evergreen forests","Tropical moist deciduous forests","Montane wet temperate forests","Tropical dry deciduous forests"],"answer":3,"explanation":"Tropical dry deciduous forests, typical of areas with about 70–100 cm of rain, cover the largest share of India's forest area, followed by tropical moist deciduous forests.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"चैम्पियन और सेठ के वर्गीकरण पर आधारित वन प्रकार मानचित्रण के अनुसार, कौन-सा वन प्रकार समूह भारत में सबसे बड़े क्षेत्र को घेरता है?","optionsHi":["उष्णकटिबंधीय आर्द्र सदाबहार वन","उष्णकटिबंधीय आर्द्र पर्णपाती वन","पर्वतीय आर्द्र शीतोष्ण वन","उष्णकटिबंधीय शुष्क पर्णपाती वन"],"explanationHi":"उष्णकटिबंधीय शुष्क पर्णपाती वन, जो लगभग 70–100 cm वर्षा वाले क्षेत्रों की विशेषता हैं, भारत के वन क्षेत्र का सबसे बड़ा हिस्सा घेरते हैं, उसके बाद उष्णकटिबंधीय आर्द्र पर्णपाती वन आते हैं।"},
  {"id":"env-ecology-943","question":"The Sundarbans are popularly said to take their name from the sundari tree, which is a:","options":["Mangrove tree of the genus Heritiera","Stemless mangrove palm of the genus Nypa","Seagrass of the genus Halophila","Strangler fig of the genus Ficus"],"answer":0,"explanation":"Sundari (Heritiera fomes) is a characteristic mangrove of the less saline parts of the Sundarbans and is threatened by rising salinity as fresh water from upstream declines.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"सुंदरबन के बारे में लोकप्रिय रूप से कहा जाता है कि उसका नाम सुंदरी वृक्ष पर पड़ा, जो है:","optionsHi":["हेरिटिएरा वंश का मैंग्रोव वृक्ष","निपा वंश का तनारहित मैंग्रोव ताड़","हैलोफ़िला वंश की समुद्री घास","फ़ाइकस वंश का गला घोंटने वाला अंजीर"],"explanationHi":"सुंदरी (हेरिटिएरा फ़ोमेस) सुंदरबन के कम लवणीय भागों का विशिष्ट मैंग्रोव है और ऊपरी प्रवाह से मीठे जल के घटने पर बढ़ती लवणता से संकट में है।"},
  {"id":"env-ecology-944","question":"Consider the following statements about tropical wet evergreen forests in India: 1. They occur where annual rainfall exceeds about 200 cm. 2. All the trees shed their leaves together in the dry season. 3. Mahogany, ebony and rosewood are among the typical trees. Which of the statements given above is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"These forests, found in the Western Ghats, the north-east and the Andamans, have no common leaf-fall season and so stay green all year; statement 2 describes deciduous forests.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत के उष्णकटिबंधीय आर्द्र सदाबहार वनों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वे वहाँ मिलते हैं जहाँ वार्षिक वर्षा लगभग 200 cm से अधिक होती है। 2. शुष्क ऋतु में सभी वृक्ष एक साथ अपनी पत्तियाँ गिरा देते हैं। 3. महोगनी, आबनूस और शीशम विशिष्ट वृक्षों में से हैं। उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"पश्चिमी घाट, पूर्वोत्तर और अंडमान में पाए जाने वाले इन वनों में पत्ती गिरने की कोई साझा ऋतु नहीं होती, इसलिए वे साल भर हरे रहते हैं; कथन 2 पर्णपाती वनों का वर्णन करता है।"},
  {"id":"env-ecology-945","question":"The Himalayan birch (Betula utilis), whose papery bark was used for writing manuscripts ('bhojpatra'), typically grows:","options":["In the lowland sal forests of the Terai","On sand dunes of the Thar desert","Near the treeline in the high Himalaya","In the mangrove swamps of the delta coast"],"answer":2,"explanation":"Birch forms forests at the upper treeline, often with rhododendron and juniper, just below the alpine meadows; these treeline forests are sensitive indicators of climate change.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"हिमालयी भोजपत्र (बेटुला यूटिलिस), जिसकी कागज़ जैसी छाल का पांडुलिपियाँ लिखने में उपयोग होता था ('भोजपत्र'), सामान्यतः कहाँ उगता है?","optionsHi":["तराई के निचले साल वनों में","थार मरुस्थल के रेत के टीलों पर","ऊँचे हिमालय में वृक्ष-रेखा के निकट","डेल्टा तट के मैंग्रोव दलदलों में"],"explanationHi":"भोजपत्र ऊपरी वृक्ष-रेखा पर, प्रायः रोडोडेंड्रॉन और जूनिपर के साथ, अल्पाइन चारागाहों के ठीक नीचे वन बनाता है; ये वृक्ष-रेखा वन जलवायु परिवर्तन के संवेदनशील सूचक हैं।"},
  {"id":"env-ecology-946","question":"Neem-based biopesticides act against many insect pests mainly through azadirachtin, which:","options":["Kills insects instantly on contact like an organochlorine","Repels insects and disrupts their feeding and moulting","Fixes nitrogen in the soil for the crop","Makes the plant poisonous to people who eat it"],"answer":1,"explanation":"Azadirachtin is an antifeedant and insect growth regulator; it acts slowly and selectively, so it fits integrated pest management better than broad-spectrum poisons.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"नीम-आधारित जैव कीटनाशक अनेक कीट नाशीजीवों पर मुख्यतः एज़ाडिरैक्टिन के माध्यम से कार्य करते हैं, जो:","optionsHi":["ऑर्गेनोक्लोरीन की तरह संपर्क में आते ही कीटों को तुरंत मार देता है","कीटों को दूर भगाता है और उनके भोजन तथा निर्मोचन को बाधित करता है","फसल के लिए मृदा में नाइट्रोजन स्थिर करता है","पौधे को उसे खाने वाले मनुष्यों के लिए विषैला बना देता है"],"explanationHi":"एज़ाडिरैक्टिन भोजन-रोधी और कीट वृद्धि नियामक है; यह धीमे और चयनात्मक रूप से कार्य करता है, इसलिए यह व्यापक-परास विषों की तुलना में एकीकृत नाशीजीव प्रबंधन में बेहतर बैठता है।"},
  {"id":"env-ecology-947","question":"Mikania micrantha, which smothers plantations and forest edges in Kerala and north-east India, is a:","options":["Native shade tree planted in tea gardens of Assam and Kerala","Fast-growing invasive climber nicknamed 'mile-a-minute'","Parasitic fungus that kills bamboo clumps","Floating aquatic plant that blocks backwaters"],"answer":1,"explanation":"Mikania, a South American vine, grows extremely fast and covers other vegetation, cutting off its light. The floating weed of backwaters is water hyacinth.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मिकेनिया माइक्रैंथा, जो केरल और पूर्वोत्तर भारत में बागानों और वन किनारों को ढक लेती है, है:","optionsHi":["असम और केरल के चाय बागानों में लगाया गया देशी छायादार वृक्ष","तेज़ी से बढ़ने वाली आक्रामक आरोही, जिसे 'माइल-अ-मिनट' उपनाम दिया गया है","परजीवी कवक जो बाँस के झुरमुटों को मार देता है","तैरता जलीय पौधा जो अप्रवाही जल को अवरुद्ध कर देता है"],"explanationHi":"मिकेनिया, दक्षिण अमेरिका की बेल, अत्यंत तेज़ी से बढ़ती है और अन्य वनस्पति को ढककर उसका प्रकाश रोक देती है। अप्रवाही जल का तैरता खरपतवार जलकुंभी है।"},
  {"id":"env-ecology-948","question":"The red seaweed Kappaphycus alvarezii has caused concern in the Gulf of Mannar because it:","options":["Releases toxins that cause red tides along the Tamil Nadu coast","Grazes on living coral polyps at night and bleaches the reefs","Was farmed there and escaped onto reefs, smothering the corals","Is a native weed that blocks the seagrass feeding beds of dugongs"],"answer":2,"explanation":"Kappaphycus was brought in for commercial carrageenan farming and escaped onto reefs near Kurusadai island, where it overgrows and kills corals.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"लाल समुद्री शैवाल कैप्पाफ़ाइकस एल्वारेज़ी मन्नार की खाड़ी में चिंता का कारण बना है क्योंकि वह:","optionsHi":["ऐसे विष छोड़ता है जो तमिलनाडु तट पर लाल ज्वार उत्पन्न करते हैं","रात में जीवित प्रवाल पॉलिपों को चरता है और भित्तियों का विरंजन करता है","वहाँ उगाया गया था और भित्तियों पर फैल गया, जिससे प्रवाल दब गए","एक देशी खरपतवार है जो डुगोंगों की समुद्री घास चरागाहों को अवरुद्ध करता है"],"explanationHi":"कैप्पाफ़ाइकस को वाणिज्यिक कैराजीनन खेती के लिए लाया गया था और वह कुरुसदई द्वीप के निकट भित्तियों पर फैल गया, जहाँ वह प्रवालों को ढककर मार देता है।"},
  {"id":"env-ecology-949","question":"Utricularia (bladderwort), found in wetlands and paddy fields across India, obtains extra nitrogen by:","options":["Trapping tiny aquatic animals in small bladders that suck them in","Catching insects on sticky glandular hairs on its leaves","Housing nitrogen-fixing cyanobacteria in its leaf cavities","Closing hinged leaf traps when sensitive trigger hairs are touched"],"answer":0,"explanation":"Bladderwort's bladders create a vacuum and snap open to suck in prey such as water fleas. Sticky hairs are the method of sundews (Drosera); hinged traps belong to the Venus flytrap.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"यूट्रिकुलेरिया (ब्लैडरवॉर्ट), जो भारत भर की आर्द्रभूमियों और धान के खेतों में पाया जाता है, अतिरिक्त नाइट्रोजन कैसे प्राप्त करता है?","optionsHi":["सूक्ष्म जलीय जंतुओं को छोटी थैलियों में फँसाकर जो उन्हें अंदर खींच लेती हैं","अपनी पत्तियों पर चिपचिपे ग्रंथिल रोमों से कीटों को पकड़कर","अपनी पत्ती गुहिकाओं में नाइट्रोजन-स्थिरीकारी सायनोबैक्टीरिया रखकर","संवेदी ट्रिगर रोमों के छूने पर कब्ज़ेदार पत्ती जाल बंद करके"],"explanationHi":"ब्लैडरवॉर्ट की थैलियाँ निर्वात बनाती हैं और झट से खुलकर जल पिस्सू जैसे शिकार को खींच लेती हैं। चिपचिपे रोम सनड्यू (ड्रोसेरा) की विधि हैं; कब्ज़ेदार जाल वीनस फ्लाइट्रैप के होते हैं।"},
  {"id":"env-ecology-950","question":"The noble dendrobium (Dendrobium nobile), an epiphytic orchid, is the state flower of:","options":["Meghalaya","Assam","Mizoram","Sikkim"],"answer":3,"explanation":"Sikkim, rich in orchids, chose the noble dendrobium as its state flower. Epiphytic orchids use trees only for support and absorb moisture through spongy aerial roots.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"नोबल डेंड्रोबियम (डेंड्रोबियम नोबाइल), एक अधिपादपी ऑर्किड, किस राज्य का राजकीय पुष्प है?","optionsHi":["मेघालय","असम","मिज़ोरम","सिक्किम"],"explanationHi":"ऑर्किडों से समृद्ध सिक्किम ने नोबल डेंड्रोबियम को अपना राजकीय पुष्प चुना। अधिपादपी ऑर्किड वृक्षों का उपयोग केवल सहारे के लिए करते हैं और स्पंजी हवाई जड़ों से नमी अवशोषित करते हैं।"},
  {"id":"env-ecology-951","question":"Assertion (A): Hydrofluorocarbons (HFCs), which replaced CFCs in refrigerators, do not damage the ozone layer. Reason (R): HFC molecules contain no chlorine or bromine. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Ozone destruction by CFCs and halons comes from the chlorine and bromine they release; HFCs contain only hydrogen, fluorine and carbon, so their ODP is zero. Their high GWP is why the Kigali Amendment now phases them down.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): हाइड्रोफ्लोरोकार्बन (HFC), जिन्होंने रेफ्रिजरेटरों में CFC का स्थान लिया, ओज़ोन परत को हानि नहीं पहुँचाते। कारण (R): HFC अणुओं में क्लोरीन या ब्रोमीन नहीं होती। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"CFC और हैलॉन द्वारा ओज़ोन विनाश उनसे मुक्त होने वाली क्लोरीन और ब्रोमीन से होता है; HFC में केवल हाइड्रोजन, फ्लोरीन और कार्बन होते हैं, इसलिए उनकी ODP शून्य है। उनकी उच्च GWP के कारण ही किगाली संशोधन अब उनमें कमी करता है।"},
  {"id":"env-ecology-952","question":"Assertion (A): Sharply cutting sulphur dioxide emissions from power plants can temporarily speed up global warming. Reason (R): Sulphur dioxide is a powerful greenhouse gas that traps outgoing infrared radiation. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"SO2 forms sulphate aerosols that reflect sunlight and brighten clouds, masking part of greenhouse warming; removing them unmasks it. SO2 is not a significant greenhouse gas, so R is false.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): विद्युत संयंत्रों से सल्फर डाइऑक्साइड उत्सर्जन में भारी कटौती वैश्विक तापन को अस्थायी रूप से तेज़ कर सकती है। कारण (R): सल्फर डाइऑक्साइड एक शक्तिशाली हरितगृह गैस है जो बहिर्गामी अवरक्त विकिरण को फँसाती है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"SO2 सल्फेट एरोसॉल बनाती है जो सूर्य प्रकाश परावर्तित करते हैं और बादलों को चमकीला बनाते हैं, जिससे हरितगृह तापन का कुछ भाग ढका रहता है; उन्हें हटाने से वह उजागर हो जाता है। SO2 कोई उल्लेखनीय हरितगृह गैस नहीं है, इसलिए R असत्य है।"},
  {"id":"env-ecology-953","question":"Assertion (A): Fish kills in lakes with dense algal blooms often happen in the early hours of the morning. Reason (R): At night, photosynthesis stops while respiration by algae, bacteria and fish continues to consume dissolved oxygen. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Dissolved oxygen in a eutrophic lake swings daily: it is supersaturated in the afternoon and falls to its lowest just before dawn, after a night of respiration without photosynthesis. That is when fish suffocate.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): घने शैवाल प्रस्फुटन वाली झीलों में मछलियों की मृत्यु प्रायः सुबह के तड़के होती है। कारण (R): रात में प्रकाश संश्लेषण रुक जाता है जबकि शैवालों, जीवाणुओं और मछलियों का श्वसन घुलित ऑक्सीजन की खपत करता रहता है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सुपोषित झील में घुलित ऑक्सीजन प्रतिदिन झूलती है: दोपहर में वह अतिसंतृप्त होती है और भोर से ठीक पहले, प्रकाश संश्लेषण के बिना श्वसन की रात के बाद, न्यूनतम पर पहुँच जाती है। तभी मछलियाँ दम घुटने से मरती हैं।"},
  {"id":"env-ecology-954","question":"Assertion (A): A wind turbine emits no carbon dioxide while it is generating electricity. Reason (R): Wind turbines are built without using any steel, cement or other energy-intensive materials. Choose the correct option.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Operation involves no combustion, but towers use steel and foundations use concrete, so turbines have life-cycle emissions from manufacture and construction, though these are far lower per unit of electricity than for coal.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"अभिकथन (A): पवन टर्बाइन बिजली उत्पन्न करते समय कार्बन डाइऑक्साइड उत्सर्जित नहीं करता। कारण (R): पवन टर्बाइन बिना किसी स्टील, सीमेंट या अन्य ऊर्जा-गहन सामग्री के बनाए जाते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"संचालन में कोई दहन नहीं होता, परंतु मीनारों में स्टील और नींवों में कंक्रीट लगता है, इसलिए टर्बाइनों के निर्माण और संरचना से जीवन-चक्र उत्सर्जन होते हैं, यद्यपि प्रति इकाई बिजली ये कोयले की तुलना में बहुत कम हैं।"},
  {"id":"env-ecology-955","question":"The Jharia coalfield, known for underground coal-seam fires that have burned for about a century and for land subsidence, is in:","options":["Chhattisgarh","Jharkhand","Odisha","West Bengal"],"answer":1,"explanation":"Jharia, in Dhanbad district of Jharkhand, holds India's main coking coal reserves; its mine fires release smoke, CO2 and toxic gases and have forced the relocation of many residents. Raniganj in West Bengal is the nearby, separate coalfield.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"झरिया कोयला क्षेत्र, जो लगभग एक सदी से जल रही भूमिगत कोयला-परत आग और भूमि धँसाव के लिए जाना जाता है, कहाँ है?","optionsHi":["छत्तीसगढ़","झारखंड","ओडिशा","पश्चिम बंगाल"],"explanationHi":"झारखंड के धनबाद ज़िले में झरिया भारत के मुख्य कोकिंग कोयला भंडारों का स्थान है; उसकी खदान की आग धुआँ, CO2 और विषैली गैसें छोड़ती है और उसने अनेक निवासियों को स्थानांतरित होने को विवश किया है। पश्चिम बंगाल का रानीगंज निकट का अलग कोयला क्षेत्र है।"},
  {"id":"env-ecology-956","question":"Chemical dispersants are sometimes sprayed on an oil slick at sea. Which of the following best describes what they do?","options":["They dissolve the oil completely into harmless carbon dioxide and water within hours","They make the oil sink to the sea floor, where it stays buried permanently","They set the oil alight so that it burns off the surface of the sea quickly","They break the slick into tiny droplets that mix into the water and degrade faster"],"answer":3,"explanation":"Dispersants reduce surface tension so oil disperses into the water column, protecting coasts and seabirds and speeding biodegradation; the trade-off is greater exposure of fish and plankton below the surface. Burning in situ is a separate method.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"समुद्र में तेल की परत पर कभी-कभी रासायनिक परिक्षेपक छिड़के जाते हैं। निम्नलिखित में से कौन-सा सबसे अच्छी तरह बताता है कि वे क्या करते हैं?","optionsHi":["वे तेल को कुछ घंटों में पूरी तरह घोलकर हानिरहित कार्बन डाइऑक्साइड और जल में बदल देते हैं","वे तेल को समुद्र तल में डुबो देते हैं, जहाँ वह स्थायी रूप से दबा रहता है","वे तेल में आग लगा देते हैं ताकि वह समुद्र की सतह से शीघ्र जल जाए","वे परत को सूक्ष्म बूँदों में तोड़ देते हैं जो जल में मिल जाती हैं और तेज़ी से विघटित होती हैं"],"explanationHi":"परिक्षेपक पृष्ठ तनाव घटाते हैं ताकि तेल जल स्तंभ में बिखर जाए, जिससे तट और समुद्री पक्षी बचते हैं और जैव-निम्नीकरण तेज़ होता है; इसका समझौता सतह के नीचे मछलियों और प्लवक का अधिक संपर्क है। यथास्थान जलाना अलग विधि है।"},
  {"id":"env-ecology-957","question":"Conservationists ask coastal towns near turtle nesting beaches to switch off or shield bright lights during the hatching season. The reason is that:","options":["Bright light warms the nest sand, so that all of the hatchlings turn out to be males","Hatchlings head for the brightest horizon, so artificial light draws them inland","Artificial light attracts crabs and stray dogs, which then dig up the turtle nests","Strong light stops the eggs from hatching until the night of the next new moon"],"answer":1,"explanation":"Hatchlings emerge at night and head for the brighter seaward horizon; street and building lights draw them inland, where they die of exhaustion or predation. Sand temperature, not light, determines sex, and warmer sand produces more females.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"संरक्षणवादी कछुओं के घोंसले वाले तटों के निकट के तटीय नगरों से अंडे सेने के मौसम में तेज़ रोशनी बंद करने या ढकने को कहते हैं। इसका कारण यह है कि:","optionsHi":["तेज़ रोशनी घोंसले की रेत को गर्म करती है, जिससे सभी बच्चे नर निकलते हैं","बच्चे सबसे चमकीले क्षितिज की ओर जाते हैं, इसलिए कृत्रिम रोशनी उन्हें भीतर की ओर खींच लेती है","कृत्रिम रोशनी केकड़ों और आवारा कुत्तों को आकर्षित करती है, जो फिर कछुओं के घोंसले खोद डालते हैं","तेज़ रोशनी अंडों को अगली अमावस्या की रात तक सेने से रोक देती है"],"explanationHi":"बच्चे रात में निकलते हैं और समुद्र की ओर के चमकीले क्षितिज की ओर जाते हैं; सड़कों और इमारतों की रोशनी उन्हें भीतर खींच लेती है, जहाँ वे थकावट या परभक्षण से मर जाते हैं। लिंग रेत का तापमान निर्धारित करता है, रोशनी नहीं, और गर्म रेत अधिक मादाएँ उत्पन्न करती है।"},
  {"id":"env-ecology-958","question":"In cloud seeding operations to induce rain, the substance most commonly dispersed into suitable clouds is:","options":["Calcium carbonate","Sulphur dioxide","Ammonium nitrate","Silver iodide"],"answer":3,"explanation":"Silver iodide has a crystal structure similar to ice and acts as an ice nucleus in cold clouds; salts such as sodium chloride are used for warm clouds, and dry ice is also used. Seeding works only if suitable moist clouds are already present.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"वर्षा कराने के लिए मेघ बीजन अभियानों में उपयुक्त बादलों में सबसे सामान्यतः छोड़ा जाने वाला पदार्थ है:","optionsHi":["कैल्शियम कार्बोनेट","सल्फर डाइऑक्साइड","अमोनियम नाइट्रेट","सिल्वर आयोडाइड"],"explanationHi":"सिल्वर आयोडाइड की क्रिस्टल संरचना बर्फ़ के समान होती है और ठंडे बादलों में हिम केंद्रक का कार्य करती है; गर्म बादलों के लिए सोडियम क्लोराइड जैसे लवण प्रयुक्त होते हैं, और शुष्क बर्फ़ (ड्राई आइस) का भी उपयोग होता है। बीजन तभी कारगर होता है जब उपयुक्त नम बादल पहले से मौजूद हों।"},
  {"id":"env-ecology-959","question":"In large river deltas such as the Sundarbans, the rise in sea level relative to the land is often faster than the global average rise. A major reason is:","options":["Land sinking as sediments compact and dams starve the delta of silt","Deltas lie closer to the poles, where the melting of ice raises the sea fastest","Mangrove roots absorb seawater and so lift the level of the surrounding sea","Tidal ranges in deltas are nil, so the whole global rise is concentrated there"],"answer":0,"explanation":"Relative sea-level rise combines global ocean rise with local land movement. Deltas sink as sediments compact and as dams and embankments starve them of new silt; groundwater extraction can add to subsidence.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सुंदरबन जैसे बड़े नदी डेल्टाओं में स्थल की तुलना में समुद्र तल की वृद्धि प्रायः वैश्विक औसत वृद्धि से तेज़ होती है। इसका एक प्रमुख कारण है:","optionsHi":["तलछट के संघनन से भूमि का धँसना और बाँधों द्वारा डेल्टा को गाद से वंचित करना","डेल्टा ध्रुवों के निकट स्थित हैं, जहाँ बर्फ़ पिघलने से समुद्र सबसे तेज़ी से बढ़ता है","मैंग्रोव की जड़ें समुद्री जल अवशोषित करती हैं और इसलिए आसपास के समुद्र का स्तर ऊपर उठाती हैं","डेल्टाओं में ज्वारीय परास शून्य होता है, इसलिए पूरी वैश्विक वृद्धि वहीं केंद्रित हो जाती है"],"explanationHi":"सापेक्ष समुद्र-तल वृद्धि वैश्विक महासागर वृद्धि और स्थानीय भूमि गति को मिलाती है। तलछट के संघनन और बाँधों तथा तटबंधों द्वारा नई गाद से वंचित होने के कारण डेल्टा धँसते हैं; भूजल निष्कर्षण धँसाव को और बढ़ा सकता है।"},
  {"id":"env-ecology-960","question":"LOHAFEX, an Indo-German experiment carried out in the Southern Ocean in 2009, tested the idea of:","options":["Pumping liquefied CO2 into deep-sea sediments below the ocean floor","Measuring how krill populations respond to warming ocean water","Fertilising the ocean with iron to boost plankton that absorb CO2","Spraying fine seawater into clouds so that they reflect more sunlight"],"answer":2,"explanation":"In iron-limited waters, adding iron sulphate triggers plankton blooms. LOHAFEX found that much of the fixed carbon was eaten by zooplankton and recycled near the surface rather than sinking, casting doubt on iron fertilisation as a carbon sink.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"2009 में दक्षिणी महासागर में किया गया भारत-जर्मन प्रयोग LOHAFEX किस विचार का परीक्षण कर रहा था?","optionsHi":["द्रवीकृत CO2 को महासागर तल के नीचे गहरे समुद्र के अवसादों में पंप करना","यह मापना कि क्रिल समष्टियाँ गर्म होते महासागरीय जल पर कैसी प्रतिक्रिया करती हैं","महासागर को आयरन से निषेचित करके CO2 अवशोषित करने वाले प्लवक को बढ़ाना","समुद्री जल की महीन फुहार बादलों में छिड़कना ताकि वे अधिक सूर्य प्रकाश परावर्तित करें"],"explanationHi":"आयरन-सीमित जल में आयरन सल्फेट मिलाने से प्लवक प्रस्फुटन होता है। LOHAFEX ने पाया कि स्थिर किए गए कार्बन का बड़ा भाग प्राणिप्लवक द्वारा खा लिया गया और डूबने के बजाय सतह के निकट पुनःचक्रित हुआ, जिससे कार्बन अवशोषक के रूप में आयरन निषेचन पर संदेह उत्पन्न हुआ।"},
  {"id":"env-ecology-961","question":"According to the IPCC's Special Report on Global Warming of 1.5 °C (2018), pathways that limit warming to 1.5 °C with no or limited overshoot require global net CO2 emissions to reach zero around:","options":["2030","2050","2070","2100"],"answer":1,"explanation":"Such pathways cut net CO2 emissions by about 45 per cent from 2010 levels by 2030 and reach net zero around 2050; for likely below 2 °C, net zero comes around 2070. This report drove the many 'net zero by 2050' pledges.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"IPCC की 1.5 °C के वैश्विक तापन पर विशेष रिपोर्ट (2018) के अनुसार, तापन को 1.5 °C तक सीमित रखने वाले पथों, जिनमें अतिक्रमण नहीं या सीमित हो, के लिए वैश्विक शुद्ध CO2 उत्सर्जन को लगभग कब तक शून्य पर पहुँचना होगा?","optionsHi":["2030","2050","2070","2100"],"explanationHi":"ऐसे पथ 2030 तक 2010 के स्तरों से शुद्ध CO2 उत्सर्जन को लगभग 45 प्रतिशत घटाते हैं और लगभग 2050 तक शुद्ध-शून्य पर पहुँचते हैं; 2 °C से नीचे रहने की संभावना के लिए शुद्ध-शून्य लगभग 2070 में आता है। इस रिपोर्ट ने अनेक '2050 तक शुद्ध-शून्य' प्रतिज्ञाओं को प्रेरित किया।"},
  {"id":"env-ecology-962","question":"Which one of the following statements about India's greenhouse gas emissions is correct?","options":["India's per capita emissions are higher than those of the European Union","India's emissions are mostly from agriculture rather than from energy","India accepted absolute emission caps under the Kyoto Protocol","India's per capita emissions are well below the world average"],"answer":3,"explanation":"Although India is a large emitter in total, its per capita CO2 emissions are under half the world average, a central point in its argument for equity and CBDR. Energy, not agriculture, is the largest source, and India had no Kyoto caps.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भारत के हरितगृह गैस उत्सर्जन के बारे में निम्नलिखित में से कौन-सा कथन सही है?","optionsHi":["भारत का प्रति व्यक्ति उत्सर्जन यूरोपीय संघ से अधिक है","भारत का उत्सर्जन ऊर्जा के बजाय मुख्यतः कृषि से है","भारत ने क्योटो प्रोटोकॉल के अंतर्गत निरपेक्ष उत्सर्जन सीमाएँ स्वीकार कीं","भारत का प्रति व्यक्ति उत्सर्जन विश्व औसत से काफ़ी कम है"],"explanationHi":"यद्यपि भारत कुल मिलाकर बड़ा उत्सर्जक है, उसका प्रति व्यक्ति CO2 उत्सर्जन विश्व औसत के आधे से कम है, जो समता और CBDR के उसके तर्क का केंद्रीय बिंदु है। सबसे बड़ा स्रोत ऊर्जा है, कृषि नहीं, और भारत की क्योटो में कोई सीमाएँ नहीं थीं।"},
  {"id":"env-ecology-963","question":"HFC-23, a greenhouse gas with a global warming potential of over 10,000, became controversial under the Clean Development Mechanism because it is:","options":["An unwanted by-product of manufacturing the refrigerant HCFC-22","Released naturally in large amounts by termites and tropical wetlands","Emitted mainly when tropical forests are burnt to clear land for farms","A by-product of producing green hydrogen through water electrolysis"],"answer":0,"explanation":"Plants making HCFC-22 earned huge numbers of CDM credits by destroying HFC-23, creating incentives to produce more HCFC-22. The Kigali Amendment now requires parties to destroy HFC-23 by-product emissions as far as practicable.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"HFC-23, जिसकी वैश्विक तापन क्षमता 10,000 से अधिक है, स्वच्छ विकास तंत्र के अंतर्गत विवादास्पद बन गई क्योंकि वह है:","optionsHi":["प्रशीतक HCFC-22 के निर्माण का अवांछित उप-उत्पाद","दीमकों और उष्णकटिबंधीय आर्द्रभूमियों से स्वाभाविक रूप से बड़ी मात्रा में निकलने वाली","उष्णकटिबंधीय वनों को खेती के लिए साफ़ करने हेतु जलाए जाने पर मुख्यतः उत्सर्जित","जल के विद्युत अपघटन से हरित हाइड्रोजन बनाने का उप-उत्पाद"],"explanationHi":"HCFC-22 बनाने वाले संयंत्रों ने HFC-23 नष्ट करके बहुत बड़ी संख्या में CDM क्रेडिट कमाए, जिससे अधिक HCFC-22 बनाने का प्रोत्साहन पैदा हुआ। किगाली संशोधन अब पक्षों से जहाँ तक व्यावहारिक हो HFC-23 उप-उत्पाद उत्सर्जन को नष्ट करने की अपेक्षा करता है।"},
  {"id":"env-ecology-964","question":"The Love Canal disaster in the United States, where homes and a school were built over buried chemical waste, led directly to the US law popularly known as:","options":["The Clean Air Act","The Endangered Species Act","The Superfund law (CERCLA)","The Oil Pollution Act"],"answer":2,"explanation":"Leaking chemicals at Love Canal near Niagara Falls caused an emergency evacuation in 1978, and Congress passed the Comprehensive Environmental Response, Compensation, and Liability Act in 1980 to clean up hazardous waste sites and make polluters pay.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"संयुक्त राज्य अमेरिका की लव कैनाल आपदा, जहाँ दबे रासायनिक अपशिष्ट के ऊपर घर और एक स्कूल बनाए गए थे, सीधे किस अमेरिकी कानून की ओर ले गई, जो लोकप्रिय रूप से जाना जाता है:","optionsHi":["क्लीन एयर एक्ट","एंडेंजर्ड स्पीशीज़ एक्ट","सुपरफंड कानून (CERCLA)","ऑयल पॉल्यूशन एक्ट"],"explanationHi":"नियाग्रा फॉल्स के निकट लव कैनाल में रिसते रसायनों के कारण 1978 में आपातकालीन निकासी हुई, और कांग्रेस ने 1980 में खतरनाक अपशिष्ट स्थलों की सफ़ाई और प्रदूषकों से भुगतान कराने के लिए व्यापक पर्यावरणीय प्रतिक्रिया, मुआवज़ा और दायित्व अधिनियम पारित किया।"},
  {"id":"env-ecology-965","question":"The 1976 industrial accident at Seveso in Italy, which led to European laws on the control of major-accident hazards, released large amounts of:","options":["Methyl isocyanate","Dioxin (TCDD)","Radioactive caesium","Liquid ammonia"],"answer":1,"explanation":"A reactor at Seveso released a cloud containing TCDD, the most toxic dioxin, contaminating a large area and causing chloracne. The EU's Seveso Directives on industrial accident prevention followed. Methyl isocyanate was the Bhopal gas.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"इटली के सेवेसो में 1976 की औद्योगिक दुर्घटना, जिसके कारण बड़े दुर्घटना खतरों के नियंत्रण पर यूरोपीय कानून बने, ने बड़ी मात्रा में क्या छोड़ा?","optionsHi":["मेथिल आइसोसायनेट","डाइऑक्सिन (TCDD)","रेडियोधर्मी सीज़ियम","द्रव अमोनिया"],"explanationHi":"सेवेसो के एक रिएक्टर ने TCDD, सबसे विषैली डाइऑक्सिन, वाले बादल को छोड़ा, जिससे बड़ा क्षेत्र संदूषित हुआ और क्लोरएक्ने हुआ। इसके बाद औद्योगिक दुर्घटना रोकथाम पर EU के सेवेसो निर्देश आए। मेथिल आइसोसायनेट भोपाल की गैस थी।"},
  {"id":"env-ecology-966","question":"The Exxon Valdez disaster of 1989, which led to the US Oil Pollution Act of 1990, occurred in:","options":["The Gulf of Mexico off Louisiana","The North Sea off Scotland","The Persian Gulf","Prince William Sound, Alaska"],"answer":3,"explanation":"The tanker ran aground in Prince William Sound, spilling crude oil that killed huge numbers of seabirds and sea otters. The Deepwater Horizon blowout of 2010 was in the Gulf of Mexico, and Gulf War spills in 1991 were in the Persian Gulf.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1989 की एक्सॉन वाल्डेज़ आपदा, जिसके कारण 1990 का अमेरिकी तेल प्रदूषण अधिनियम बना, कहाँ हुई?","optionsHi":["लुइज़ियाना के तट से दूर मेक्सिको की खाड़ी में","स्कॉटलैंड के तट से दूर उत्तरी सागर में","फ़ारस की खाड़ी में","प्रिंस विलियम साउंड, अलास्का में"],"explanationHi":"टैंकर प्रिंस विलियम साउंड में फँस गया और कच्चा तेल फैल गया, जिसने बहुत बड़ी संख्या में समुद्री पक्षियों और समुद्री ऊदबिलावों को मार डाला। 2010 का डीपवाटर होराइज़न विस्फोट मेक्सिको की खाड़ी में था, और 1991 के खाड़ी युद्ध के रिसाव फ़ारस की खाड़ी में।"},
  {"id":"env-ecology-967","question":"The Great Smog of London in December 1952, which caused thousands of deaths, was mainly due to:","options":["Smoke and SO2 from coal burning, trapped under an inversion","Ozone and nitrogen oxides from car exhausts in strong summer sunshine","Dust storms carrying fine sand all the way from the Sahara Desert","Radioactive fallout drifting in from British nuclear weapon tests"],"answer":0,"explanation":"Cold, still weather and an inversion trapped soot and SO2 from household coal fires and power stations for days; the episode prompted the UK Clean Air Act of 1956. Photochemical smog of the Los Angeles type is the summer, traffic-related kind.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"दिसंबर 1952 का लंदन का महान धुंध (ग्रेट स्मॉग), जिसमें हज़ारों मौतें हुईं, मुख्यतः किस कारण से था?","optionsHi":["कोयला जलाने से धुआँ और SO2, जो व्युत्क्रमण के नीचे फँस गए","तेज़ गर्मियों की धूप में कारों के निकास से ओज़ोन और नाइट्रोजन ऑक्साइड","सहारा मरुस्थल से दूर तक महीन रेत लाने वाले धूल भरे तूफ़ान","ब्रिटिश परमाणु हथियार परीक्षणों से बहकर आया रेडियोधर्मी विकिरण पतन"],"explanationHi":"ठंडे, शांत मौसम और व्युत्क्रमण ने घरेलू कोयला चूल्हों और विद्युत केंद्रों से निकली कालिख और SO2 को दिनों तक फँसाए रखा; इस घटना ने 1956 के यूके क्लीन एयर एक्ट को प्रेरित किया। लॉस एंजिल्स प्रकार का प्रकाश-रासायनिक धुआँ गर्मियों वाला, यातायात-संबंधी प्रकार है।"},
  {"id":"env-ecology-968","question":"The gas leak at the LG Polymers plant in Visakhapatnam in May 2020 involved vapour of:","options":["Methyl isocyanate","Chlorine","Styrene","Hydrogen sulphide"],"answer":2,"explanation":"Styrene monomer stored in a tank heated up and polymerised, releasing vapour that killed several people and affected thousands. The NGT held the company liable and directed it to deposit an interim amount towards damages.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"मई 2020 में विशाखापत्तनम के LG पॉलिमर्स संयंत्र में गैस रिसाव किसके वाष्प का था?","optionsHi":["मेथिल आइसोसायनेट","क्लोरीन","स्टाइरीन","हाइड्रोजन सल्फाइड"],"explanationHi":"टंकी में रखा स्टाइरीन मोनोमर गर्म होकर बहुलकित हो गया, जिससे निकले वाष्प ने कई लोगों की जान ली और हज़ारों को प्रभावित किया। NGT ने कंपनी को उत्तरदायी ठहराया और उसे क्षतिपूर्ति के लिए अंतरिम राशि जमा करने का निर्देश दिया।"},
  {"id":"env-ecology-969","question":"The Sukinda valley in Odisha, often listed among the most polluted places in India, is affected mainly by:","options":["Arsenic leached from deep aquifers into tube wells","Fluoride released by phosphate fertiliser factories","Mercury from chlor-alkali plants upstream","Hexavalent chromium from open-cast chromite mining"],"answer":3,"explanation":"Sukinda holds most of India's chromite reserves; overburden and mine water carry Cr(VI) into the Brahmani river and groundwater. Arsenic contamination is typical of the Ganga–Brahmaputra plains.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ओडिशा की सुकिंडा घाटी, जिसे प्रायः भारत के सबसे प्रदूषित स्थानों में गिना जाता है, मुख्यतः किससे प्रभावित है?","optionsHi":["गहरे जलभृतों से नलकूपों में निक्षालित आर्सेनिक","फॉस्फेट उर्वरक कारखानों से निकला फ्लोराइड","ऊपरी प्रवाह के क्लोर-क्षार संयंत्रों से पारा","खुली खदान से क्रोमाइट खनन से निकला षट्संयोजी क्रोमियम"],"explanationHi":"सुकिंडा में भारत के अधिकांश क्रोमाइट भंडार हैं; अधिभार और खदान का जल Cr(VI) को ब्राह्मणी नदी और भूजल में पहुँचा देता है। आर्सेनिक संदूषण गंगा–ब्रह्मपुत्र के मैदानों की विशेषता है।"},
  {"id":"env-ecology-970","question":"The Comprehensive Environmental Pollution Index (CEPI), used to identify critically polluted industrial clusters such as Vapi and Ankleshwar, was developed by:","options":["The Bureau of Indian Standards","The Central Pollution Control Board","The National Green Tribunal","The Union Ministry of Environment and Forests"],"answer":1,"explanation":"CPCB developed CEPI around 2009 with IIT Delhi, scoring clusters on air, water and land pollution and health effects; the Environment Ministry then used the scores to impose a moratorium on new units in clusters scoring 70 or more.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"व्यापक पर्यावरणीय प्रदूषण सूचकांक (CEPI), जो वापी और अंकलेश्वर जैसे गंभीर रूप से प्रदूषित औद्योगिक समूहों की पहचान के लिए प्रयुक्त होता है, किसके द्वारा विकसित किया गया?","optionsHi":["भारतीय मानक ब्यूरो","केंद्रीय प्रदूषण नियंत्रण बोर्ड","राष्ट्रीय हरित अधिकरण","केंद्रीय पर्यावरण और वन मंत्रालय"],"explanationHi":"CPCB ने लगभग 2009 में IIT दिल्ली के साथ CEPI विकसित किया, जो समूहों को वायु, जल और भूमि प्रदूषण तथा स्वास्थ्य प्रभावों पर अंक देता है; फिर पर्यावरण मंत्रालय ने इन अंकों का उपयोग 70 या उससे अधिक अंक पाने वाले समूहों में नई इकाइयों पर रोक लगाने के लिए किया।"},
  {"id":"env-ecology-971","question":"Under the Bhopal Gas Leak Disaster (Processing of Claims) Act, 1985:","options":["Each victim had to sue Union Carbide separately in courts in the United States","All claims were to be decided by a special bench of the National Green Tribunal","The Centre got the exclusive right to represent victims and press claims","The State of Madhya Pradesh became liable to pay all of the compensation itself"],"answer":2,"explanation":"Acting as parens patriae, the Union Government took over the claims, and in 1989 settled with Union Carbide for 470 million US dollars, a settlement widely criticised as inadequate. The NGT did not exist until 2010.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भोपाल गैस रिसाव आपदा (दावों का प्रसंस्करण) अधिनियम, 1985 के अंतर्गत:","optionsHi":["प्रत्येक पीड़ित को यूनियन कार्बाइड पर अमेरिका की अदालतों में अलग से मुकदमा करना था","सभी दावों का निर्णय राष्ट्रीय हरित अधिकरण की विशेष पीठ को करना था","केंद्र को पीड़ितों का प्रतिनिधित्व करने और दावे आगे बढ़ाने का अनन्य अधिकार मिला","मध्य प्रदेश राज्य सारा मुआवज़ा स्वयं चुकाने के लिए उत्तरदायी बन गया"],"explanationHi":"राज्य के संरक्षक (पेरेन्स पैट्रिए) के रूप में कार्य करते हुए केंद्र सरकार ने दावे अपने हाथ में लिए, और 1989 में यूनियन कार्बाइड से 470 मिलियन अमेरिकी डॉलर में समझौता किया, जिसकी व्यापक रूप से अपर्याप्त कहकर आलोचना हुई। NGT 2010 तक अस्तित्व में नहीं था।"},
  {"id":"env-ecology-972","question":"The rapid depletion of groundwater in north-west India, including Punjab, Haryana and Rajasthan, was confirmed from space by the GRACE satellites. They detected it by measuring:","options":["Changes in the colour of crops as seen in infrared satellite images","Tiny changes in Earth's gravity from the loss of water mass","The temperature of the soil surface measured from orbit every day","The depth of water in wells measured by radar beams from space"],"answer":1,"explanation":"GRACE's twin satellites tracked tiny changes in the distance between them caused by variations in gravity; loss of water stored underground over years showed up as a falling mass, attributed mainly to pumping for irrigation.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"पंजाब, हरियाणा और राजस्थान सहित उत्तर-पश्चिम भारत में भूजल के तेज़ ह्रास की पुष्टि अंतरिक्ष से GRACE उपग्रहों ने की। उन्होंने इसका पता किसे मापकर लगाया?","optionsHi":["अवरक्त उपग्रह चित्रों में दिखने वाले फसलों के रंग में परिवर्तन","जल द्रव्यमान की हानि से पृथ्वी के गुरुत्व में सूक्ष्म परिवर्तन","कक्षा से प्रतिदिन मापा गया मृदा सतह का तापमान","अंतरिक्ष से रडार किरणों द्वारा मापी गई कुओं में जल की गहराई"],"explanationHi":"GRACE के जुड़वाँ उपग्रहों ने गुरुत्व में भिन्नताओं से उनके बीच की दूरी में सूक्ष्म परिवर्तनों को ट्रैक किया; वर्षों में भूमिगत संचित जल की हानि घटते द्रव्यमान के रूप में दिखी, जिसका श्रेय मुख्यतः सिंचाई के लिए पंपन को दिया गया।"},
  {"id":"env-ecology-973","question":"'Oilzapper', used in India to clean up oily sludge and oil-contaminated soil, is:","options":["A chemical dispersant sprayed from aircraft over oil slicks at sea","An incinerator that burns oily sludge at a very high temperature","A floating boom that collects oil from the surface of harbours","A consortium of oil-degrading bacteria developed by TERI"],"answer":3,"explanation":"Oilzapper is a bioremediation product, a mix of bacteria that break down hydrocarbons, developed by The Energy and Resources Institute with the oil industry. It has been used at refineries and oil spill sites.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'ऑइलज़ैपर', जिसका भारत में तैलीय अवपंक और तेल-संदूषित मृदा की सफ़ाई के लिए उपयोग होता है, है:","optionsHi":["रासायनिक परिक्षेपक जो समुद्र में तेल की परतों पर विमान से छिड़का जाता है","भस्मक जो तैलीय अवपंक को बहुत उच्च तापमान पर जलाता है","तैरती बूम जो बंदरगाहों की सतह से तेल एकत्र करती है","तेल-निम्नीकारक जीवाणुओं का समूह जिसे TERI ने विकसित किया"],"explanationHi":"ऑइलज़ैपर एक जैव-उपचार उत्पाद है, हाइड्रोकार्बनों को तोड़ने वाले जीवाणुओं का मिश्रण, जिसे द एनर्जी एंड रिसोर्सेज़ इंस्टीट्यूट ने तेल उद्योग के साथ विकसित किया। इसका उपयोग रिफ़ाइनरियों और तेल रिसाव स्थलों पर हुआ है।"},
  {"id":"env-ecology-974","question":"The 'green muffler' approach to controlling noise pollution involves:","options":["Planting rows of dense trees and shrubs along roads and noise sources","Fitting all city buses and auto-rickshaws with quieter electric engines","Covering factory roofs and walls with grass mats to absorb vibration","Banning the use of horns on roads marked with green signboards"],"answer":0,"explanation":"Belts of dense vegetation, often four to six rows deep, absorb and scatter sound and screen residential areas from traffic noise, while also trapping dust. Horn bans and silence zones are separate measures.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"ध्वनि प्रदूषण नियंत्रित करने के 'ग्रीन मफ़लर' उपाय में क्या शामिल है?","optionsHi":["सड़कों और शोर स्रोतों के साथ घने वृक्षों और झाड़ियों की पंक्तियाँ लगाना","शहर की सभी बसों और ऑटो-रिक्शाओं में शांत इलेक्ट्रिक इंजन लगाना","कंपन सोखने के लिए कारखानों की छतों और दीवारों को घास की चटाइयों से ढकना","हरे साइनबोर्ड वाली सड़कों पर हॉर्न के उपयोग पर प्रतिबंध लगाना"],"explanationHi":"घनी वनस्पति की पट्टियाँ, प्रायः चार से छह पंक्तियाँ गहरी, ध्वनि को सोखती और बिखेरती हैं और आवासीय क्षेत्रों को यातायात शोर से बचाती हैं, साथ ही धूल को भी रोकती हैं। हॉर्न प्रतिबंध और शांत क्षेत्र अलग उपाय हैं।"},
  {"id":"env-ecology-975","question":"'Cool roofs', promoted in several Indian heat action plans, keep buildings cooler mainly because they:","options":["Contain refrigerant pipes that pump heat out of the building","Have a high albedo, reflecting much of the incoming sunlight","Are made of thick concrete that stores the heat for winter","Absorb sunlight and convert it into electricity for fans"],"answer":1,"explanation":"White or reflective coatings reflect sunlight and emit heat well, lowering roof temperatures and indoor heat in homes without air-conditioning; on a city scale they also reduce the urban heat island. Solar panels are a different technology.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"'शीतल छतें' (कूल रूफ), जिन्हें अनेक भारतीय ऊष्मा कार्य योजनाओं में बढ़ावा दिया जाता है, इमारतों को मुख्यतः इसलिए ठंडा रखती हैं क्योंकि वे:","optionsHi":["इनमें प्रशीतक पाइप होते हैं जो इमारत से ऊष्मा बाहर पंप करते हैं","उच्च एल्बिडो वाली होती हैं, आने वाले सूर्य प्रकाश का बड़ा भाग परावर्तित करती हैं","मोटे कंक्रीट से बनी होती हैं जो सर्दियों के लिए ऊष्मा संचित करता है","सूर्य प्रकाश अवशोषित करके पंखों के लिए बिजली में बदलती हैं"],"explanationHi":"सफ़ेद या परावर्तक लेप सूर्य प्रकाश परावर्तित करते हैं और ऊष्मा अच्छी तरह उत्सर्जित करते हैं, जिससे बिना वातानुकूलन वाले घरों में छत का तापमान और भीतर की गर्मी घटती है; शहर के स्तर पर वे नगरीय ऊष्मा द्वीप भी घटाती हैं। सौर पैनल अलग प्रौद्योगिकी हैं।"},
  {"id":"env-ecology-976","question":"The National Plan for Conservation of Aquatic Ecosystems (NPCA), a centrally sponsored scheme, was formed by merging:","options":["The National Lake Conservation Plan and National Wetlands Conservation Programme","The National River Conservation Plan and the Namami Gange programme for the Ganga","Project Tiger and Project Elephant, along with the scheme for other wild species","The National Afforestation Programme and the National Mission for a Green India"],"answer":0,"explanation":"NPCA combined the lake and wetland programmes so that lakes and wetlands are managed under one integrated scheme. River pollution abatement remains under the National River Conservation Plan and the Ganga programme.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जलीय पारिस्थितिकी तंत्रों के संरक्षण की राष्ट्रीय योजना (NPCA), जो केंद्र प्रायोजित योजना है, किनके विलय से बनी?","optionsHi":["राष्ट्रीय झील संरक्षण योजना और राष्ट्रीय आर्द्रभूमि संरक्षण कार्यक्रम","राष्ट्रीय नदी संरक्षण योजना और गंगा के लिए नमामि गंगे कार्यक्रम","प्रोजेक्ट टाइगर और प्रोजेक्ट एलीफ़ेंट, अन्य वन्य प्रजातियों की योजना के साथ","राष्ट्रीय वनीकरण कार्यक्रम और हरित भारत के लिए राष्ट्रीय मिशन"],"explanationHi":"NPCA ने झील और आर्द्रभूमि कार्यक्रमों को मिलाया ताकि झीलों और आर्द्रभूमियों का प्रबंधन एक एकीकृत योजना के अंतर्गत हो। नदी प्रदूषण निवारण राष्ट्रीय नदी संरक्षण योजना और गंगा कार्यक्रम के अंतर्गत ही रहता है।"},
  {"id":"env-ecology-977","question":"'Amrit Dharohar', announced in the Union Budget 2023–24, is a scheme for:","options":["Restoring stepwells, tanks and other traditional water bodies in historic towns","Promoting wise use of Ramsar sites, their biodiversity and eco-tourism","Digitising the records of India's protected monuments and sacred groves","Reviving indigenous seed varieties through village community seed banks"],"answer":1,"explanation":"Amrit Dharohar aims to encourage wise use of Ramsar sites, enhancing their biodiversity, carbon stock and eco-tourism, and income for local communities. Coastal mangroves were addressed by the separate MISHTI scheme announced in the same budget.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"केंद्रीय बजट 2023–24 में घोषित 'अमृत धरोहर' किसके लिए योजना है?","optionsHi":["ऐतिहासिक नगरों में बावड़ियों, तालाबों और अन्य पारंपरिक जल निकायों की बहाली","रामसर स्थलों, उनकी जैव विविधता और पारिस्थितिक-पर्यटन के विवेकपूर्ण उपयोग को बढ़ावा देना","भारत के संरक्षित स्मारकों और पवित्र उपवनों के अभिलेखों का डिजिटलीकरण","ग्राम सामुदायिक बीज बैंकों के माध्यम से देशी बीज किस्मों का पुनरुद्धार"],"explanationHi":"अमृत धरोहर का उद्देश्य रामसर स्थलों के विवेकपूर्ण उपयोग को प्रोत्साहित करना, उनकी जैव विविधता, कार्बन भंडार और पारिस्थितिक-पर्यटन तथा स्थानीय समुदायों की आय बढ़ाना है। तटीय मैंग्रोव को उसी बजट में घोषित अलग MISHTI योजना ने संबोधित किया।"},
  {"id":"env-ecology-978","question":"MISHTI, announced by the Government of India in 2023, is an initiative for:","options":["Promoting millet cultivation in drought-prone rainfed districts","Cleaning up plastic waste from beaches, estuaries and harbours","Planting mangroves along the coastline and on salt-pan lands","Installing solar-powered desalination plants on small islands"],"answer":2,"explanation":"The Mangrove Initiative for Shoreline Habitats and Tangible Incomes plans mangrove plantation along the coast and on salt pans through convergence of MGNREGS, CAMPA funds and other sources, for coastal protection and livelihoods.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2023 में भारत सरकार द्वारा घोषित MISHTI किस पहल के लिए है?","optionsHi":["सूखा-प्रवण वर्षा-आधारित ज़िलों में मोटे अनाज की खेती को बढ़ावा देना","समुद्र तटों, ज्वारनदमुखों और बंदरगाहों से प्लास्टिक अपशिष्ट की सफ़ाई","तटरेखा के साथ और लवण-क्यारी भूमि पर मैंग्रोव लगाना","छोटे द्वीपों पर सौर-चालित विलवणीकरण संयंत्र लगाना"],"explanationHi":"तटवर्ती आवासों और ठोस आय के लिए मैंग्रोव पहल MGNREGS, CAMPA निधि और अन्य स्रोतों के अभिसरण से तट के साथ और लवण क्यारियों पर मैंग्रोव रोपण की योजना बनाती है, तटीय संरक्षण और आजीविका के लिए।"},
  {"id":"env-ecology-979","question":"The Nagar Van Yojana, launched on World Environment Day 2020, aims to:","options":["Relocate villages from the core areas of national parks","Pay forest-dwelling communities for not cutting trees","Convert degraded forests into commercial plantations","Develop urban forests in cities and towns"],"answer":3,"explanation":"The scheme supports creating 'Nagar Vans' (city forests) on forest or other land in urban areas, with local bodies, schools and citizens, to improve urban greenery and biodiversity and reduce pollution and heat.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"2020 के विश्व पर्यावरण दिवस पर शुरू की गई नगर वन योजना का उद्देश्य है:","optionsHi":["राष्ट्रीय उद्यानों के क्रोड क्षेत्रों से गाँवों को स्थानांतरित करना","वनवासी समुदायों को वृक्ष न काटने के लिए भुगतान करना","निम्नीकृत वनों को वाणिज्यिक वृक्षारोपणों में बदलना","शहरों और कस्बों में नगरीय वन विकसित करना"],"explanationHi":"योजना स्थानीय निकायों, स्कूलों और नागरिकों के साथ, नगरीय क्षेत्रों में वन या अन्य भूमि पर 'नगर वन' (शहरी वन) बनाने का समर्थन करती है, ताकि नगरीय हरियाली और जैव विविधता सुधरे तथा प्रदूषण और गर्मी घटे।"},
  {"id":"env-ecology-980","question":"PARIVESH, launched by the Union Environment Ministry in 2018, is:","options":["A satellite-based system that monitors and reports forest fires in real time","An annual index ranking all the states on the quality of their environment","A national register of every wetland in India larger than one hectare","A single-window online system for green clearances of all kinds"],"answer":3,"explanation":"PARIVESH lets project proponents apply for and track all central green clearances online, with documents and decisions placed in the public domain. Forest fire alerts come from the Forest Survey of India.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2018 में केंद्रीय पर्यावरण मंत्रालय द्वारा शुरू किया गया परिवेश (PARIVESH) क्या है?","optionsHi":["उपग्रह-आधारित प्रणाली जो वन अग्नियों की वास्तविक समय निगरानी और रिपोर्ट करती है","वार्षिक सूचकांक जो सभी राज्यों को उनके पर्यावरण की गुणवत्ता पर क्रमबद्ध करता है","भारत की एक हेक्टेयर से बड़ी प्रत्येक आर्द्रभूमि का राष्ट्रीय रजिस्टर","सभी प्रकार की हरित मंज़ूरियों के लिए एकल-खिड़की ऑनलाइन प्रणाली"],"explanationHi":"परिवेश परियोजना प्रस्तावकों को सभी केंद्रीय हरित मंज़ूरियों के लिए ऑनलाइन आवेदन और उन्हें ट्रैक करने देता है, जिसमें दस्तावेज़ और निर्णय सार्वजनिक रूप से उपलब्ध रहते हैं। वन अग्नि अलर्ट भारतीय वन सर्वेक्षण से आते हैं।"},
  {"id":"env-ecology-981","question":"Under the CPCB's categorisation of industries (2016) by pollution index into Red, Orange, Green and White, units in the 'White' category:","options":["Are practically non-polluting and do not need consent to establish or operate","Are the most polluting and may not be set up near protected areas","Must install continuous online emission monitoring with real-time reporting","Are allowed only inside notified industrial estates with common effluent plants"],"answer":0,"explanation":"White-category units, with a pollution index up to 20, need only intimate the board, not obtain consent. Red-category units, the most polluting, are generally not permitted in ecologically fragile and protected areas.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"CPCB द्वारा उद्योगों के प्रदूषण सूचकांक के आधार पर लाल, नारंगी, हरा और श्वेत में वर्गीकरण (2016) के अंतर्गत 'श्वेत' श्रेणी की इकाइयाँ:","optionsHi":["व्यावहारिक रूप से प्रदूषण-रहित हैं और उन्हें स्थापित या संचालित करने के लिए सहमति की आवश्यकता नहीं","सर्वाधिक प्रदूषणकारी हैं और संरक्षित क्षेत्रों के निकट स्थापित नहीं की जा सकतीं","वास्तविक समय रिपोर्टिंग के साथ सतत ऑनलाइन उत्सर्जन निगरानी लगानी होगी","केवल सामूहिक बहिःस्राव संयंत्रों वाली अधिसूचित औद्योगिक संपदाओं के भीतर ही अनुमत हैं"],"explanationHi":"श्वेत श्रेणी की इकाइयों को, जिनका प्रदूषण सूचकांक 20 तक है, केवल बोर्ड को सूचित करना होता है, सहमति नहीं लेनी होती। लाल श्रेणी की इकाइयाँ, सर्वाधिक प्रदूषणकारी, पारिस्थितिक रूप से नाज़ुक और संरक्षित क्षेत्रों में सामान्यतः अनुमत नहीं होतीं।"},
  {"id":"env-ecology-982","question":"Under the Water Act, 1974 and the Air Act, 1981, a new industrial unit must obtain 'Consent to Establish' and later 'Consent to Operate' from:","options":["The State Pollution Control Board","The Union Ministry of Environment","The National Green Tribunal","The District Collector of the area"],"answer":0,"explanation":"Consents are granted, with conditions, by the SPCB (or Pollution Control Committee in a UT). These are separate from environmental clearance under the EIA Notification, which large projects need from the Centre or SEIAA.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"जल अधिनियम, 1974 और वायु अधिनियम, 1981 के अंतर्गत नई औद्योगिक इकाई को 'स्थापना की सहमति' और बाद में 'संचालन की सहमति' किससे प्राप्त करनी होती है?","optionsHi":["राज्य प्रदूषण नियंत्रण बोर्ड","केंद्रीय पर्यावरण मंत्रालय","राष्ट्रीय हरित अधिकरण","क्षेत्र का ज़िला कलेक्टर"],"explanationHi":"सहमतियाँ शर्तों के साथ SPCB (या संघ राज्य क्षेत्र में प्रदूषण नियंत्रण समिति) द्वारा दी जाती हैं। ये EIA अधिसूचना के अंतर्गत पर्यावरणीय मंज़ूरी से अलग हैं, जो बड़ी परियोजनाओं को केंद्र या SEIAA से चाहिए।"},
  {"id":"env-ecology-983","question":"The Adaptation Fund, set up under the Kyoto Protocol to finance adaptation in developing countries, was distinctive because it was financed mainly by:","options":["A levy on international air tickets, paid by passengers at the time of booking","A 2 per cent share of the credits issued under the Clean Development Mechanism","Compulsory contributions fixed in proportion to each Annex I country's emissions","Concessional loans from the World Bank and the IMF to the developing countries"],"answer":1,"explanation":"The 'share of proceeds' from CERs was an innovative, automatic source of funding beyond voluntary donations; it also supports direct access by national implementing entities, such as NABARD in India.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"क्योटो प्रोटोकॉल के अंतर्गत विकासशील देशों में अनुकूलन के वित्त पोषण के लिए स्थापित अनुकूलन कोष इसलिए विशिष्ट था क्योंकि उसका वित्त पोषण मुख्यतः किससे होता था?","optionsHi":["अंतर्राष्ट्रीय हवाई टिकटों पर शुल्क, जिसे यात्री बुकिंग के समय देते हैं","स्वच्छ विकास तंत्र के अंतर्गत जारी क्रेडिटों का 2 प्रतिशत हिस्सा","प्रत्येक अनुलग्नक I देश के उत्सर्जन के अनुपात में निर्धारित अनिवार्य योगदान","विश्व बैंक और IMF से विकासशील देशों को रियायती ऋण"],"explanationHi":"CER से 'आय का हिस्सा' स्वैच्छिक दान से परे धन का एक नवीन, स्वचालित स्रोत था; यह भारत में नाबार्ड जैसी राष्ट्रीय क्रियान्वयन इकाइयों द्वारा प्रत्यक्ष पहुँच का भी समर्थन करता है।"},
  {"id":"env-ecology-984","question":"The 'Santiago Network', established under the UNFCCC, is meant to:","options":["Trade carbon credits among Latin American countries under Article 6","Monitor deforestation across the Amazon basin using satellite data","Coordinate the phase-out of coal from South American power grids","Link vulnerable countries with technical help on loss and damage"],"answer":3,"explanation":"The network was set up at COP-25 in 2019, chaired by Chile though held in Madrid, as part of the Warsaw International Mechanism to connect vulnerable countries with technical expertise on loss and damage.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"UNFCCC के अंतर्गत स्थापित 'सैंटियागो नेटवर्क' का उद्देश्य है:","optionsHi":["अनुच्छेद 6 के अंतर्गत लैटिन अमेरिकी देशों के बीच कार्बन क्रेडिट का व्यापार करना","उपग्रह आँकड़ों से अमेज़न बेसिन में वनोन्मूलन की निगरानी करना","दक्षिण अमेरिकी विद्युत ग्रिडों से कोयले की चरणबद्ध समाप्ति का समन्वय करना","असुरक्षित देशों को हानि और क्षति पर तकनीकी सहायता से जोड़ना"],"explanationHi":"यह नेटवर्क 2019 में COP-25 में स्थापित हुआ, जिसकी अध्यक्षता चिली ने की यद्यपि वह मैड्रिड में हुआ, वारसॉ अंतर्राष्ट्रीय तंत्र के भाग के रूप में, असुरक्षित देशों को हानि और क्षति पर तकनीकी विशेषज्ञता से जोड़ने के लिए।"},
  {"id":"env-ecology-985","question":"The SDG India Index, which ranks states and union territories on their progress towards the Sustainable Development Goals, is prepared by:","options":["The Ministry of Environment, Forest and Climate Change","The Reserve Bank of India","NITI Aayog","The Comptroller and Auditor General"],"answer":2,"explanation":"NITI Aayog, which coordinates SDG implementation in India, has published the index since 2018 in partnership with the UN in India and the statistics ministry.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"SDG इंडिया इंडेक्स, जो राज्यों और संघ राज्य क्षेत्रों को सतत विकास लक्ष्यों की दिशा में उनकी प्रगति पर क्रमबद्ध करता है, किसके द्वारा तैयार किया जाता है?","optionsHi":["पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय","भारतीय रिज़र्व बैंक","नीति आयोग","भारत के नियंत्रक एवं महालेखा परीक्षक"],"explanationHi":"भारत में SDG कार्यान्वयन का समन्वय करने वाले नीति आयोग ने भारत में संयुक्त राष्ट्र और सांख्यिकी मंत्रालय की साझेदारी में 2018 से यह सूचकांक प्रकाशित किया है।"},
  {"id":"env-ecology-986","question":"The Energy Conservation Building Code (ECBC), first launched in 2007, is administered by:","options":["The Bureau of Energy Efficiency","The Bureau of Indian Standards","The Central Public Works Department","The Ministry of New and Renewable Energy"],"answer":0,"explanation":"BEE, set up under the Energy Conservation Act, 2001, framed the ECBC to set minimum energy performance standards for new commercial buildings; states notify it to make it mandatory.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2007 में पहली बार शुरू की गई ऊर्जा संरक्षण भवन संहिता (ECBC) का प्रशासन किसके द्वारा किया जाता है?","optionsHi":["ऊर्जा दक्षता ब्यूरो","भारतीय मानक ब्यूरो","केंद्रीय लोक निर्माण विभाग","नवीन और नवीकरणीय ऊर्जा मंत्रालय"],"explanationHi":"ऊर्जा संरक्षण अधिनियम, 2001 के अंतर्गत स्थापित BEE ने नई वाणिज्यिक इमारतों के लिए न्यूनतम ऊर्जा निष्पादन मानक निर्धारित करने हेतु ECBC बनाई; राज्य उसे अनिवार्य बनाने के लिए अधिसूचित करते हैं।"},
  {"id":"env-ecology-987","question":"The FAME scheme, launched in India in 2015, is aimed at:","options":["Mapping India's forest areas and their carbon stock through satellite imagery","Funding afforestation and soil restoration on old mined-out lands","Reforming fertiliser subsidies so that small farmers use less urea","Faster adoption and manufacturing of electric and hybrid vehicles"],"answer":3,"explanation":"FAME (Faster Adoption and Manufacturing of Hybrid and Electric Vehicles) gave demand incentives and supported charging infrastructure under the National Electric Mobility Mission Plan, to cut oil imports and vehicle pollution.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2015 में भारत में शुरू की गई FAME योजना का उद्देश्य है:","optionsHi":["उपग्रह चित्रों से भारत के वन क्षेत्रों और उनके कार्बन भंडार का मानचित्रण","पुरानी खनन-समाप्त भूमियों पर वनीकरण और मृदा बहाली को वित्त पोषित करना","उर्वरक रियायतों में सुधार ताकि छोटे किसान कम यूरिया उपयोग करें","इलेक्ट्रिक और हाइब्रिड वाहनों को तेज़ी से अपनाना और बनाना"],"explanationHi":"FAME (हाइब्रिड और इलेक्ट्रिक वाहनों का तेज़ अंगीकरण और विनिर्माण) ने राष्ट्रीय इलेक्ट्रिक गतिशीलता मिशन योजना के अंतर्गत माँग प्रोत्साहन दिए और चार्जिंग अवसंरचना का समर्थन किया, ताकि तेल आयात और वाहन प्रदूषण घटे।"},
  {"id":"env-ecology-988","question":"In 2023, the Geological Survey of India reported inferred resources of lithium, important for batteries in electric vehicles and grid storage, in:","options":["Mandya district, Karnataka","Reasi district, Jammu and Kashmir","Singhbhum district, Jharkhand","Sonbhadra district, Uttar Pradesh"],"answer":1,"explanation":"GSI reported about 5.9 million tonnes of inferred lithium resources in Reasi in February 2023. A small lithium find had earlier been reported at Mandya, and Sonbhadra made news for gold, which makes both common traps.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2023 में भारतीय भूवैज्ञानिक सर्वेक्षण ने लिथियम, जो इलेक्ट्रिक वाहनों और ग्रिड भंडारण की बैटरियों के लिए महत्त्वपूर्ण है, के अनुमानित संसाधनों की सूचना कहाँ दी?","optionsHi":["मांड्या ज़िला, कर्नाटक","रियासी ज़िला, जम्मू और कश्मीर","सिंहभूम ज़िला, झारखंड","सोनभद्र ज़िला, उत्तर प्रदेश"],"explanationHi":"GSI ने फरवरी 2023 में रियासी में लगभग 5.9 मिलियन टन अनुमानित लिथियम संसाधनों की सूचना दी। मांड्या में पहले एक छोटी लिथियम खोज की सूचना आई थी, और सोनभद्र सोने के लिए चर्चा में आया, जिससे दोनों आम भ्रम हैं।"},
  {"id":"env-ecology-989","question":"Consider the following statements about the Construction and Demolition Waste Management Rules, 2016: 1. They were framed under the Environment (Protection) Act, 1986. 2. Waste generators are responsible for collecting and segregating their construction and demolition waste. 3. They apply only to the eight largest metropolitan cities. Which of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"These were India's first separate rules for C&D waste; they place duties on generators and local bodies, and encourage use of recycled C&D products in construction. They apply across the country, not only to metros.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निर्माण और ध्वंस अपशिष्ट प्रबंधन नियम, 2016 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इन्हें पर्यावरण (संरक्षण) अधिनियम, 1986 के अंतर्गत बनाया गया था। 2. अपशिष्ट उत्पादक अपने निर्माण और ध्वंस अपशिष्ट के संग्रहण और पृथक्करण के लिए उत्तरदायी हैं। 3. ये केवल आठ सबसे बड़े महानगरों पर लागू होते हैं। उपर्युक्त कथनों में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"ये C&D अपशिष्ट के लिए भारत के पहले अलग नियम थे; ये उत्पादकों और स्थानीय निकायों पर दायित्व डालते हैं, और निर्माण में पुनःचक्रित C&D उत्पादों के उपयोग को प्रोत्साहित करते हैं। ये पूरे देश में लागू हैं, केवल महानगरों में नहीं।"},
  {"id":"env-ecology-990","question":"The Battery Waste Management Rules, 2022 differ from the earlier Batteries (Management and Handling) Rules, 2001 mainly in that the 2022 rules:","options":["Apply only to the lead-acid batteries used in cars, trucks and inverters","Ban the sale of all lithium-ion batteries in India from a notified date","Allow used batteries to be disposed of in municipal sanitary landfills","Cover all battery types, including EV batteries, under EPR"],"answer":3,"explanation":"The 2001 rules dealt essentially with lead-acid batteries. The 2022 rules cover portable, automotive, industrial and EV batteries, set EPR collection and recycling targets and require minimum recycled content in new batteries.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"बैटरी अपशिष्ट प्रबंधन नियम, 2022 पूर्व के बैटरी (प्रबंधन और हैंडलिंग) नियम, 2001 से मुख्यतः इस बात में भिन्न हैं कि 2022 के नियम:","optionsHi":["केवल कारों, ट्रकों और इन्वर्टरों में प्रयुक्त लेड-एसिड बैटरियों पर लागू होते हैं","एक अधिसूचित तिथि से भारत में सभी लिथियम-आयन बैटरियों की बिक्री पर प्रतिबंध लगाते हैं","प्रयुक्त बैटरियों को नगरपालिका स्वच्छता भूभरावों में निपटाने की अनुमति देते हैं","EV बैटरियों सहित सभी प्रकार की बैटरियों को EPR के अंतर्गत शामिल करते हैं"],"explanationHi":"2001 के नियम मूलतः लेड-एसिड बैटरियों से निपटते थे। 2022 के नियम पोर्टेबल, ऑटोमोटिव, औद्योगिक और EV बैटरियों को शामिल करते हैं, EPR संग्रहण और पुनःचक्रण लक्ष्य निर्धारित करते हैं और नई बैटरियों में न्यूनतम पुनःचक्रित सामग्री अपेक्षित करते हैं।"},
  {"id":"env-ecology-991","question":"SAFAR, a system that provides location-specific air quality forecasts for several Indian cities, was developed by:","options":["The Indian Institute of Tropical Meteorology, Pune","The Central Pollution Control Board, Delhi","The Indian Space Research Organisation, Bengaluru","The National Environmental Engineering Research Institute, Nagpur"],"answer":0,"explanation":"SAFAR (System of Air Quality and Weather Forecasting and Research) was developed by IITM Pune under the Ministry of Earth Sciences; it was first deployed during the 2010 Commonwealth Games in Delhi.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"SAFAR, जो कई भारतीय शहरों के लिए स्थान-विशिष्ट वायु गुणवत्ता पूर्वानुमान देने वाली प्रणाली है, किसके द्वारा विकसित की गई?","optionsHi":["भारतीय उष्णदेशीय मौसम विज्ञान संस्थान, पुणे","केंद्रीय प्रदूषण नियंत्रण बोर्ड, दिल्ली","भारतीय अंतरिक्ष अनुसंधान संगठन, बेंगलुरु","राष्ट्रीय पर्यावरण अभियांत्रिकी अनुसंधान संस्थान, नागपुर"],"explanationHi":"SAFAR (वायु गुणवत्ता और मौसम पूर्वानुमान एवं अनुसंधान प्रणाली) पृथ्वी विज्ञान मंत्रालय के अंतर्गत IITM पुणे ने विकसित की; इसे पहली बार 2010 के दिल्ली राष्ट्रमंडल खेलों के दौरान तैनात किया गया।"},
  {"id":"env-ecology-992","question":"HCFC-141b, an ozone-depleting chemical widely used as a blowing agent for making polyurethane foam, was completely phased out in India by:","options":["1 January 2010","1 January 2015","1 January 2030","1 January 2020"],"answer":3,"explanation":"India phased out HCFC-141b from 1 January 2020 under its HCFC Phase-out Management Plan, converting foam manufacturers to alternatives with zero ODP and low GWP. CFCs had been phased out in 2010.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"HCFC-141b, एक ओज़ोन-क्षयकारी रसायन जो पॉलीयूरेथेन फ़ोम बनाने में फूँकने वाले एजेंट के रूप में व्यापक रूप से प्रयुक्त था, भारत में किस तिथि तक पूरी तरह चरणबद्ध रूप से समाप्त किया गया?","optionsHi":["1 जनवरी 2010","1 जनवरी 2015","1 जनवरी 2030","1 जनवरी 2020"],"explanationHi":"भारत ने अपनी HCFC चरणबद्ध समाप्ति प्रबंधन योजना के अंतर्गत HCFC-141b को 1 जनवरी 2020 से चरणबद्ध रूप से समाप्त किया, और फ़ोम निर्माताओं को शून्य ODP और निम्न GWP वाले विकल्पों में परिवर्तित किया। CFC 2010 में चरणबद्ध रूप से समाप्त हुए थे।"},
  {"id":"env-ecology-993","question":"The Biological Diversity (Amendment) Act, 2023 changed the 2002 Act by, among other things:","options":["Exempting registered AYUSH practitioners from giving prior intimation for access to bioresources","Abolishing the National Biodiversity Authority and transferring all its functions to the Ministry","Requiring foreign companies to obtain separate approval from each Gram Sabha whose land they use","Bringing the 2002 Act under the authority of the Chief Wildlife Wardens appointed under the WPA"],"answer":0,"explanation":"The amendment eased compliance for codified traditional knowledge and AYUSH practitioners, decriminalised offences into monetary penalties and promoted cultivation of medicinal plants. The NBA continues to exist.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जैविक विविधता (संशोधन) अधिनियम, 2023 ने 2002 के अधिनियम को अन्य बातों के साथ किस प्रकार बदला?","optionsHi":["पंजीकृत आयुष चिकित्सकों को जैव संसाधनों तक पहुँच के लिए पूर्व सूचना देने से छूट दे दी","राष्ट्रीय जैव विविधता प्राधिकरण को समाप्त कर उसके सभी कार्य मंत्रालय को सौंप दिए","विदेशी कंपनियों से प्रत्येक उस ग्राम सभा की अलग अनुमति माँगना जिसकी भूमि वे उपयोग करती हैं","2002 के अधिनियम को WPA के अंतर्गत नियुक्त मुख्य वन्यजीव वार्डनों के अधिकार में ला दिया"],"explanationHi":"संशोधन ने संहिताबद्ध पारंपरिक ज्ञान और आयुष चिकित्सकों के लिए अनुपालन आसान किया, अपराधों को आर्थिक दंड में बदल दिया और औषधीय पौधों की खेती को बढ़ावा दिया। NBA बना हुआ है।"},
  {"id":"env-ecology-994","question":"The Environment Relief Fund, used to pay immediate relief to victims of accidents involving hazardous substances, was set up under:","options":["The Environment (Protection) Act, 1986, through its Section 3","The Public Liability Insurance Act, 1991, as amended in 1992","The National Green Tribunal Act, 2010, under its Section 24","The Disaster Management Act, 2005, as a part of the NDRF"],"answer":1,"explanation":"Owners handling hazardous substances must take insurance and also contribute to the Environment Relief Fund, so that victims get relief on a no-fault basis without proving negligence.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"खतरनाक पदार्थों से जुड़ी दुर्घटनाओं के पीड़ितों को तत्काल राहत देने के लिए प्रयुक्त पर्यावरण राहत कोष किसके अंतर्गत स्थापित हुआ?","optionsHi":["पर्यावरण (संरक्षण) अधिनियम, 1986, उसकी धारा 3 के माध्यम से","लोक दायित्व बीमा अधिनियम, 1991, जैसा 1992 में संशोधित","राष्ट्रीय हरित अधिकरण अधिनियम, 2010, उसकी धारा 24 के अंतर्गत","आपदा प्रबंधन अधिनियम, 2005, NDRF के भाग के रूप में"],"explanationHi":"खतरनाक पदार्थों को संभालने वाले स्वामियों को बीमा लेना होता है और पर्यावरण राहत कोष में भी योगदान देना होता है, ताकि पीड़ितों को लापरवाही सिद्ध किए बिना, बिना-दोष आधार पर राहत मिले।"},
  {"id":"env-ecology-995","question":"Match the study with its subject. A. Stern Review (2006)  B. Dasgupta Review (2021)  C. TEEB initiative (from 2007); 1. The economics of biodiversity, for the UK Treasury  2. The economics of climate change  3. Making visible the economic value of ecosystems and biodiversity, hosted by UNEP","options":["A-1, B-2, C-3","A-2, B-3, C-1","A-2, B-1, C-3","A-3, B-1, C-2"],"answer":2,"explanation":"Nicholas Stern's review argued that early climate action costs far less than inaction; Partha Dasgupta's review treated nature as an asset; TEEB, led by Pavan Sukhdev, grew out of a G8+5 initiative at Potsdam.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अध्ययन का उसके विषय से मिलान कीजिए। A. स्टर्न समीक्षा (2006) B. दासगुप्ता समीक्षा (2021) C. TEEB पहल (2007 से); 1. जैव विविधता का अर्थशास्त्र, यूके ट्रेज़री के लिए 2. जलवायु परिवर्तन का अर्थशास्त्र 3. पारिस्थितिकी तंत्रों और जैव विविधता के आर्थिक मूल्य को दृश्य बनाना, UNEP द्वारा आयोजित","optionsHi":["A-1, B-2, C-3","A-2, B-3, C-1","A-2, B-1, C-3","A-3, B-1, C-2"],"explanationHi":"निकोलस स्टर्न की समीक्षा ने तर्क दिया कि जलवायु पर शीघ्र कार्रवाई की लागत निष्क्रियता से कहीं कम है; पार्थ दासगुप्ता की समीक्षा ने प्रकृति को एक संपत्ति माना; पवन सुखदेव के नेतृत्व वाला TEEB पॉट्सडैम में G8+5 पहल से उभरा।"},
  {"id":"env-ecology-996","question":"Which of the following is the best example of 'payment for ecosystem services'?","options":["A government fines a factory heavily for discharging effluent into a river","A city water utility pays upstream farmers to keep its catchment forested","A tourist pays an entry fee at a national park that funds its staff salaries","A farmer buys organic manure instead of urea for use on his own fields"],"answer":1,"explanation":"PES rewards land managers for maintaining services, here clean and steady water supply, that benefit others downstream. A fine is a penalty under polluter pays, and an entry fee is simply a user charge.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित में से 'पारिस्थितिकी तंत्र सेवाओं के लिए भुगतान' का सबसे अच्छा उदाहरण कौन-सा है?","optionsHi":["सरकार नदी में बहिःस्राव छोड़ने पर किसी कारखाने पर भारी जुर्माना लगाती है","शहर की जल उपयोगिता अपने जलग्रहण क्षेत्र को वनाच्छादित रखने के लिए ऊपरी प्रवाह के किसानों को भुगतान करती है","पर्यटक राष्ट्रीय उद्यान में प्रवेश शुल्क देता है जिससे उसके कर्मचारियों के वेतन चलते हैं","किसान अपने खेतों में उपयोग के लिए यूरिया के बजाय जैविक खाद खरीदता है"],"explanationHi":"PES भूमि प्रबंधकों को उन सेवाओं को बनाए रखने के लिए पुरस्कृत करता है, यहाँ स्वच्छ और स्थिर जल आपूर्ति, जिनसे दूसरों को लाभ होता है। जुर्माना प्रदूषक भुगतान करे के अंतर्गत दंड है, और प्रवेश शुल्क केवल उपयोगकर्ता शुल्क।"},
  {"id":"env-ecology-997","question":"Common Effluent Treatment Plants (CETPs) are set up in Indian industrial clusters mainly because:","options":["Large industries are prohibited by law from treating their own effluent on site","They allow treated water to be sold back to member industries at a large profit","Rivers next to industrial estates need extra water released in the dry season","Small units cannot afford their own treatment plants, so they share one"],"answer":3,"explanation":"CETPs pool effluent from many small units, making treatment affordable and easier to monitor; member units usually pre-treat their wastewater first. Poorly run CETPs remain a problem in clusters such as Vapi and Ankleshwar.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"भारतीय औद्योगिक समूहों में सामूहिक बहिःस्राव उपचार संयंत्र (CETP) मुख्यतः इसलिए स्थापित किए जाते हैं क्योंकि:","optionsHi":["कानून द्वारा बड़े उद्योगों को अपने बहिःस्राव का उपचार स्थल पर करने से प्रतिबंधित किया गया है","वे उपचारित जल को सदस्य उद्योगों को भारी लाभ पर वापस बेचने देते हैं","औद्योगिक संपदाओं के निकट की नदियों को शुष्क ऋतु में अतिरिक्त जल छोड़ने की आवश्यकता होती है","छोटी इकाइयाँ अपने उपचार संयंत्र का खर्च नहीं उठा सकतीं, इसलिए एक साझा करती हैं"],"explanationHi":"CETP कई छोटी इकाइयों का बहिःस्राव एकत्र करते हैं, जिससे उपचार सस्ता और निगरानी आसान होती है; सदस्य इकाइयाँ प्रायः पहले अपने अपशिष्ट जल का पूर्व-उपचार करती हैं। वापी और अंकलेश्वर जैसे समूहों में खराब चलाए जा रहे CETP एक समस्या बने हुए हैं।"},
  {"id":"env-ecology-998","question":"The SATAT initiative, launched in India in 2018, promotes:","options":["Solar-powered trains on suburban railway routes in large cities","Sale of electric three-wheelers through post offices in villages","Compressed biogas plants that turn biomass into transport fuel","Ethanol made from sugarcane juice for blending with petrol"],"answer":2,"explanation":"Sustainable Alternative Towards Affordable Transportation invites entrepreneurs to set up compressed biogas (CBG) plants, with oil marketing companies buying the gas, helping reduce stubble burning and gas imports.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2018 में भारत में शुरू की गई SATAT पहल किसे बढ़ावा देती है?","optionsHi":["बड़े शहरों के उपनगरीय रेल मार्गों पर सौर-चालित रेलगाड़ियाँ","गाँवों में डाकघरों के माध्यम से इलेक्ट्रिक तिपहिया वाहनों की बिक्री","संपीड़ित बायोगैस संयंत्र जो जैव-पदार्थ को परिवहन ईंधन में बदलते हैं","पेट्रोल में मिश्रण के लिए गन्ने के रस से बना एथेनॉल"],"explanationHi":"सस्ते परिवहन की ओर सतत विकल्प (SATAT) उद्यमियों को संपीड़ित बायोगैस (CBG) संयंत्र लगाने के लिए आमंत्रित करता है, जिसकी गैस तेल विपणन कंपनियाँ खरीदती हैं, जिससे पराली जलाने और गैस आयात घटाने में सहायता मिलती है।"},
  {"id":"env-ecology-999","question":"Under the Green Highways (Plantation, Transplantation, Beautification and Maintenance) Policy, 2015, funds for planting along national highways come mainly from:","options":["Penalties collected from vehicles that violate emission norms on highways","Earmarking about 1 per cent of the civil works cost of highway projects","A special cess levied on diesel sold at fuel stations along the highways","Voluntary donations collected from road users at the toll plazas"],"answer":1,"explanation":"The policy sets aside about 1 per cent of the total project cost of highway construction for plantation and maintenance, involving local communities, NGOs and the private sector.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"हरित राजमार्ग (वृक्षारोपण, प्रत्यारोपण, सौंदर्यीकरण और रखरखाव) नीति, 2015 के अंतर्गत राष्ट्रीय राजमार्गों के किनारे रोपण के लिए धन मुख्यतः कहाँ से आता है?","optionsHi":["राजमार्गों पर उत्सर्जन मानदंडों का उल्लंघन करने वाले वाहनों से वसूले गए दंड","राजमार्ग परियोजनाओं की सिविल कार्य लागत का लगभग 1 प्रतिशत अलग रखना","राजमार्गों के किनारे ईंधन स्टेशनों पर बिकने वाले डीज़ल पर लगाया गया विशेष उपकर","टोल प्लाज़ा पर सड़क उपयोगकर्ताओं से एकत्र स्वैच्छिक दान"],"explanationHi":"नीति राजमार्ग निर्माण की कुल परियोजना लागत का लगभग 1 प्रतिशत रोपण और रखरखाव के लिए अलग रखती है, जिसमें स्थानीय समुदायों, गैर-सरकारी संगठनों और निजी क्षेत्र को शामिल किया जाता है।"},
  {"id":"env-ecology-1000","question":"While the cold North Atlantic absorbs CO2 from the air, the equatorial Pacific is a net source of CO2 to the atmosphere. The main reason is that in the equatorial Pacific:","options":["Intense phytoplankton photosynthesis in warm water gives off CO2 as a by-product","Frequent tropical cyclones churn up sediments that are rich in organic carbon","Upwelled carbon-rich deep water warms at the surface and releases CO2","Volcanoes on the sea floor emit large amounts of CO2 directly into the water"],"answer":2,"explanation":"Deep water carries carbon accumulated from sinking organic matter; when it upwells and warms, CO2 becomes less soluble and outgasses. In the North Atlantic, cold surface water takes up CO2 and sinks, the solubility pump in reverse.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"जहाँ ठंडा उत्तरी अटलांटिक वायु से CO2 अवशोषित करता है, वहीं भूमध्यरेखीय प्रशांत वायुमंडल को CO2 का शुद्ध स्रोत है। इसका मुख्य कारण यह है कि भूमध्यरेखीय प्रशांत में:","optionsHi":["गर्म जल में तीव्र फाइटोप्लैंकटन प्रकाश संश्लेषण उप-उत्पाद के रूप में CO2 छोड़ता है","बार-बार आने वाले उष्णकटिबंधीय चक्रवात कार्बनिक कार्बन से समृद्ध अवसादों को उछाल देते हैं","ऊपर आया कार्बन-समृद्ध गहरा जल सतह पर गर्म होकर CO2 मुक्त करता है","समुद्र तल के ज्वालामुखी बड़ी मात्रा में CO2 सीधे जल में उत्सर्जित करते हैं"],"explanationHi":"गहरा जल डूबते कार्बनिक पदार्थ से संचित कार्बन लिए होता है; जब वह ऊपर आता है और गर्म होता है तो CO2 कम विलेय हो जाती है और बाहर निकल जाती है। उत्तरी अटलांटिक में ठंडा सतही जल CO2 सोखकर डूब जाता है, यानी विलेयता पंप का उलटा।"},
];

export default questions;
